#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structure to represent an LTE PHY RX Frame
struct LTE_PHY_RX_FRAME {
    struct PHY_HEADER header; // PHY frame header
    float signal_strength; // Signal strength of the frame
    size_t num_symbols; // Number of symbols in the frame
    struct LTE_PHY_RX_SYMBOL* symbols; // Array of symbols in the frame
};

// Structure to represent an LTE PHY RX Symbol
struct LTE_PHY_RX_SYMBOL {
    uint8_t symbol_index; // Index of the symbol within the frame
    int16_t symbol_value; // Value of the symbol (in QAM format)
};

// Function to allocate memory for a new LTE PHY RX Frame
struct LTE_PHY_RX_FRAME* allocate_new_frame(void) {
    struct LTE_PHY_RX_FRAME* frame = (struct LTE_PHY_RX_FRAME*)malloc(sizeof(struct LTE_PHY_RX_FRAME));
    if (!frame) {
        return NULL;
    }
    frame->header = (struct PHY_HEADER){0}; // Initialize the header to zeroes
    frame->signal_strength = 0.0f; // Initialize signal strength to zero
    frame->num_symbols = 0; // Initialize number of symbols to zero
    frame->symbols = NULL; // Initialize symbol array to null
    return frame;
}

// Function to free memory for a LTE PHY RX Frame
void free_frame(struct LTE_PHY_RX_FRAME* frame) {
    if (!frame) {
        return;
    }
    // Free the symbol array, if it exists
    if (frame->symbols) {
        free(frame->symbols);
    }
    // Free the frame structure itself
    free(frame);
}

// Function to allocate memory for a new LTE PHY RX Symbol
struct LTE_PHY_RX_SYMBOL* allocate_new_symbol(void) {
    struct LTE_PHY_RX_SYMBOL* symbol = (struct LTE_PHY_RX_SYMBOL*)malloc(sizeof(struct LTE_PHY_RX_SYMBOL));
    if (!symbol) {
        return NULL;
    }
    symbol->symbol_index = 0; // Initialize symbol index to zero
    symbol->symbol_value = 0; // Initialize symbol value to zero
    return symbol;
}

// Function to free memory for a LTE PHY RX Symbol
void free_symbol(struct LTE_PHY_RX_SYMBOL* symbol) {
    if (!symbol) {
        return;
    }
    // Free the symbol structure itself
    free(symbol);
}

// Function to add a new symbol to an existing frame
int add_symbol_to_frame(struct LTE_PHY_RX_FRAME* frame, struct LTE_PHY_RX_SYMBOL* symbol) {
    if (!frame || !symbol) {
        return -1; // Error: invalid arguments
    }
    // Allocate memory for the new symbol array, if it doesn't already exist
    if (!frame->symbols) {
        frame->symbols = (struct LTE_PHY_RX_SYMBOL**)malloc(sizeof(struct LTE_PHY_RX_SYMBOL*) * (frame->num_symbols + 1));
        if (!frame->symbols) {
            return -2; // Error: unable to allocate memory for symbol array
        }
    }
    // Copy the new symbol into the frame's symbol array
    memcpy(&(frame->symbols[frame->num_symbols]), symbol, sizeof(struct LTE_PHY_RX_SYMBOL));
    // Increment the number of symbols in the frame
    frame->num_symbols++;
    return 0; // Success: symbol added to frame
}

// Function to remove a symbol from an existing frame
int remove_symbol_from_frame(struct LTE_PHY_RX_FRAME* frame, struct LTE_PHY_RX_SYMBOL* symbol) {
    if (!frame || !symbol) {
        return -1; // Error: invalid arguments
    }
    // Find the index of the symbol in the frame's symbol array
    size_t symbol_index = 0;
    for (size_t i = 0; i < frame->num_symbols; i++) {
        if (frame->symbols[i] == symbol) {
            symbol_index = i;
            break;
        }
    }
    // Error: symbol not found in frame
    if (symbol_index == 0) {
        return -2;
    }
    // Remove the symbol from the frame's symbol array
    for (size_t i = symbol_index; i < frame->num_symbols - 1; i++) {
        memcpy(&(frame->symbols[i]), &(frame->symbols[i + 1]), sizeof(struct LTE_PHY_RX_SYMBOL));
    }
    // Decrement the number of symbols in the frame
    frame->num_symbols--;
    return 0; // Success: symbol removed from frame
}

// Function to allocate memory for a new dynamic array of LTE PHY RX Frames
struct LTE_PHY_RX_FRAME** allocate_frame_array(size_t num_frames) {
    struct LTE_PHY_RX_FRAME*** frame_array = (struct LTE_PHY_RX_FRAME***)malloc(sizeof(struct LTE_PHY_RX_FRAME**) * num_frames);
    if (!frame_array) {
        return NULL;
    }
    for (size_t i = 0; i < num_frames; i++) {
        frame_array[i] = allocate_new_frame();
        if (!frame_array[i]) {
            // Error: unable to allocate memory for frame
            return NULL;
        }
    }
    return frame_array;
}

// Function to free memory for a dynamic array of LTE PHY RX Frames
void free_frame_array(struct LTE_PHY_RX_FRAME** frame_array, size_t num_frames) {
    if (!frame_array) {
        return; // Error: invalid arguments
    }
    for (size_t i = 0; i < num_frames; i++) {
        free_symbol(frame_array[i]);
    }
    free(frame_array);
}

// Example usage of the functions above:
int main() {
    // Allocate memory for a dynamic array of LTE PHY RX Frames
    struct LTE_PHY_RX_FRAME** frame_array = allocate_frame_array(10);
    if (!frame_array) {
        return 1; // Error: unable to allocate memory for frame array
    }

    // Add symbols to the frames in the dynamic array
    struct LTE_PHY_RX_SYMBOL* symbol = allocate_new_symbol();
    symbol->symbol_index = 0;
    symbol->symbol_value = 1234;
    for (size_t i = 0; i < 5; i++) {
        add_symbol_to_frame(frame_array[i], symbol);
    }

    // Remove symbols from the frames in the dynamic array
    remove_symbol_from_frame(frame_array[3], symbol);

    // Free memory for the dynamic array of LTE PHY RX Frames
    free_frame_array(frame_array, 10);

    return 0; // Success: frame array freed successfully
}
```

This code defines a set of functions for allocating and freeing memory for a dynamic array of LTE PHY RX Frames. The functions `allocate_frame_array` and `free_frame_array` are used to allocate and free memory for the entire dynamic array, while the functions `add_symbol_to_frame` and `remove_symbol_from_frame` are used to add and remove symbols from individual frames in the array.

The example usage of these functions is shown in the main function. First, a dynamic array of 10 LTE PHY RX Frames is allocated using the `allocate_frame_array` function. Then, a new symbol is created and added to five of the frames in the array using the `add_symbol_to_frame` function. Finally, the main function frees the memory for the entire dynamic array using the `free_frame_array` function.

Note that the example usage assumes that the `struct LTE_PHY_RX_FRAME` and `struct LTE_PHY_RX_SYMBOL` definitions are available in the program."]

