#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include <assert.h>
#include <stdint.h>
#include <time.h>

// Define the data structures for the arrays and hash table
struct offset_array {
    long *data;
    size_t count;
};

struct key_array {
    int *data;
    size_t count;
};

struct record {
    int value;
    long offset;
};

struct hash_table {
    struct record **data;
    size_t count;
    size_t capacity;
};

// Define the custom hash function for the hash table
size_t hash(int key) {
    // A simple and fast hash function is used here, but it's important to use a good hash function that minimizes collisions
    return key % 100;
}

// Allocate memory for all arrays and the hash table
struct offset_array *allocate_offset_array(size_t count) {
    struct offset_array *arr = malloc(sizeof(struct offset_array));
    if (!arr) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    arr->data = calloc(count, sizeof(long));
    if (!arr->data) {
        printf("Memory allocation failed\n");
        free(arr);
        return NULL;
    }

    arr->count = count;
    return arr;
}

struct key_array *allocate_key_array(size_t count) {
    struct key_array *arr = malloc(sizeof(struct key_array));
    if (!arr) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    arr->data = calloc(count, sizeof(int));
    if (!arr->data) {
        printf("Memory allocation failed\n");
        free(arr);
        return NULL;
    }

    arr->count = count;
    return arr;
}

struct record *allocate_record(size_t count) {
    struct record *rec = malloc(sizeof(struct record));
    if (!rec) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    rec->value = calloc(count, sizeof(int));
    if (!rec->value) {
        printf("Memory allocation failed\n");
        free(rec);
        return NULL;
    }

    rec->offset = calloc(count, sizeof(long));
    if (!rec->offset) {
        printf("Memory allocation failed\n");
        free(rec->value);
        free(rec);
        return NULL;
    }

    rec->count = count;
    return rec;
}

struct hash_table *allocate_hash_table(size_t capacity) {
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    if (!ht) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    ht->data = calloc(capacity, sizeof(struct record));
    if (!ht->data) {
        printf("Memory allocation failed\n");
        free(ht);
        return NULL;
    }

    ht->count = 0;
    ht->capacity = capacity;
    return ht;
}

// Initialize the arrays and hash table with random data within given ranges
void initialize_arrays(struct offset_array *offset_arr, struct key_array *key_arr, struct record *rec, int min_key, int max_key, long min_offset, long max_offset) {
    assert(offset_arr != NULL);
    assert(key_arr != NULL);
    assert(rec != NULL);

    size_t i;
    for (i = 0; i < offset_arr->count; ++i) {
        offset_arr->data[i] = min_offset + (rand() % (max_offset - min_offset));
    }

    for (i = 0; i < key_arr->count; ++i) {
        key_arr->data[i] = min_key + (rand() % (max_key - min_key));
    }

    for (i = 0; i < rec->count; ++i) {
        rec->value[i] = rand();
        rec->offset[i] = offset_arr->data[i];
    }
}

// Populate the hash table with records
void populate_hash_table(struct hash_table *ht, struct record *rec) {
    assert(ht != NULL);
    assert(rec != NULL);

    size_t i;
    for (i = 0; i < rec->count; ++i) {
        int key = rec->value[i];
        long offset = rec->offset[i];
        struct record *record = ht->data + hash(key);
        if (record->key != 0) { // Check for collision and handle it properly
            size_t index;
            for (index = 0; index < ht->count && record->key != key; ++index) {
                record = ht->data + (hash(key) + index);
            }
            if (record->key == key) { // Collision detected, update the offset value
                record->offset = offset;
            } else { // No collision, insert a new record
                ++ht->count;
                ht->data[hash(key)] = (struct record) { .value = key, .offset = offset };
            }
        } else { // No collision, insert a new record
            ++ht->count;
            ht->data[hash(key)] = (struct record) { .value = key, .offset = offset };
        }
    }
}

// Dynamic resizing of the hash table to accommodate varying loads
void resize_hash_table(struct hash_table *ht, size_t capacity) {
    assert(ht != NULL);
    assert(capacity > 0);

    struct hash_table *new_ht = allocate_hash_table(capacity);
    if (!new_ht) {
        printf("Memory allocation failed\n");
        return;
    }

    size_t i;
    for (i = 0; i < ht->count; ++i) {
        struct record *record = ht->data + i;
        int key = record->value;
        long offset = record->offset;
        size_t index = hash(key);
        while (new_ht->data[index].key != 0) { // Handle collisions properly
            ++index;
            if (index == capacity) { // Resize again if the new table is still full
                resize_hash_table(new_ht, capacity * 2);
                index = hash(key);
            }
        }
        new_ht->data[index] = (struct record) { .value = key, .offset = offset };
    }
    ht->count = 0;
}

int main() {
    // Test the dynamic resizing of the hash table
    struct hash_table *ht = allocate_hash_table(16);
    if (!ht) {
        printf("Memory allocation failed\n");
        return 1;
    }

    int min_key = 0;
    int max_key = 256;
    long min_offset = 0;
    long max_offset = 256 * 256;

    struct offset_array *offset_arr = allocate_offset_array(10);
    if (!offset_arr) {
        printf("Memory allocation failed\n");
        return 1;
    }

    struct key_array *key_arr = allocate_key_array(10);
    if (!key_arr) {
        printf("Memory allocation failed\n");
        return 1;
    }

    struct record *rec = allocate_record(10);
    if (!rec) {
        printf("Memory allocation failed\n");
        return 1;
    }

    initialize_arrays(offset_arr, key_arr, rec, min_key, max_key, min_offset, max_offset);
    populate_hash_table(ht, rec);

    // Check if the hash table is full
    size_t i;
    for (i = 0; i < ht->capacity && ht->data[i].key != 0; ++i) {}
    if (i == ht->capacity) { // Hash table is full, resize it
        resize_hash_table(ht, 2 * ht->capacity);
    }

    return 0;
}']

