#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <map>
#include <vector>
#include <algorithm>
#include <chrono>

using namespace std;

// Define a struct to store the command line arguments
struct Arguments {
    string input_file;
    string output_file;
    bool help = false;
    bool version = false;
    bool count = false;
    bool summary = false;
    bool ignore_case = false;
};

// Define a struct to store the word frequency data
struct WordFrequency {
    string word;
    int frequency;
};

int main(int argc, char *argv[]) {
    // Parse the command line arguments and check for errors
    Arguments args = parse_arguments(argc, argv);
    if (args.error) {
        return 1;
    }

    // Open the input file
    ifstream infile;
    if (!args.input_file.empty()) {
        infile.open(args.input_file);
        if (!infile.is_open()) {
            cerr << "Error: unable to open input file: " << args.input_file << endl;
            return 1;
        }
    } else {
        // Read from stdin if no input file is specified
        infile = cin;
    }

    // Create a vector to store the words in the input file
    vector<string> words;

    // Read the input file and store the words in the vector
    string line;
    while (getline(infile, line)) {
        istringstream iss(line);
        string word;
        while (iss >> word) {
            if (!args.ignore_case) {
                // Store the word as it is
                words.push_back(word);
            } else {
                // Convert to lowercase and store
                transform(word.begin(), word.end(), word.begin(), ::tolower);
                words.push_back(word);
            }
        }
    }

    // Calculate the total number of words in the input file
    int num_words = words.size();

    // Create a map to store the frequency of each word
    map<string, int> word_freq;
    for (auto &word : words) {
        if (word_freq.find(word) == word_freq.end()) {
            word_freq[word] = 1;
        } else {
            word_freq[word] += 1;
        }
    }

    // Calculate the frequency of each unique word in the input file
    vector<WordFrequency> word_frequencies;
    for (auto &entry : word_freq) {
        WordFrequency freq = { entry.first, entry.second };
        word_frequencies.push_back(freq);
    }

    // Sort the frequency vector in descending order based on the frequency of each word
    sort(word_frequencies.begin(), word_frequencies.end(),
            [](const WordFrequency &a, const WordFrequency &b) {
        return a.frequency > b.frequency;
    });

    // Print the total number of words in the input file
    if (args.count) {
        cout << num_words << endl;
    }

    // Print the summary of word frequencies
    if (args.summary) {
        for (auto &entry : word_frequencies) {
            cout << entry.word << ": " << entry.frequency << endl;
        }
    }

    // Write the output to a file if specified
    if (!args.output_file.empty()) {
        ofstream outfile(args.output_file);
        if (outfile.is_open()) {
            for (auto &entry : word_frequencies) {
                outfile << entry.word << ": " << entry.frequency << endl;
            }
        } else {
            cerr << "Error: unable to open output file: " << args.output_file << endl;
        }
    }

    // Close the input file
    infile.close();

    return 0;
}

// Parse the command line arguments and check for errors
Arguments parse_arguments(int argc, char *argv[]) {
    Arguments args;
    int opt;
    while ((opt = getopt(argc, argv, "hi:o:vc:s")) != -1) {
        switch (opt) {
            case 'h':
                args.help = true;
                break;
            case 'i':
                args.input_file = optarg;
                break;
            case 'o':
                args.output_file = optarg;
                break;
            case 'v':
                args.version = true;
                break;
            case 'c':
                args.count = true;
                break;
            case 's':
                args.summary = true;
                break;
            default:
                args.error = true;
                break;
        }
    }
    return args;
}

// Print the usage message for the program
void print_usage(const string &program_name) {
    cout << "Usage: " << program_name << " [OPTIONS]" << endl;
    cout << "Options:" << endl;
    cout << "-h, --help\t\tPrint this help message and exit." << endl;
    cout << "-i, --input FILE\tInput file (defaults to standard input)." << endl;
    cout << "-o, --output FILE\tOutput file (defaults to standard output)." << endl;
    cout << "-v, --version\t\tPrint the version number." << endl;
    cout << "-c, --count\t\tPrint the total number of words in the input file." << endl;
    cout << "-s, --summary\t\tPrint a summary of the content distribution (word frequency)." << endl;
    cout << "-i, --ignore-case\tIgnore case when processing words for summaries." << endl;
}

// Print the version number for the program
void print_version() {
    cout << "Word Frequency Program Version 1.0" << endl;
}']

