#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <float.h>
#include <assert.h>
#include <errno.h>
#include <math.h>

void parseTransformationRules(const char* rules, int** ruleMatrix, int* numRules) {
    // Parse the transformation rules from the given string and store them in a matrix.
    *numRules = strlen(rules);
    *ruleMatrix = (int*)malloc(*numRules * sizeof(int));
    for (int i = 0; i < *numRules; ++i) {
        (*ruleMatrix)[i] = rules[i] - '0';
    }
}

void processData(const char* inputFile, const char* outputFile, int** ruleMatrix, int numRules, float threshold) {
    // Process the data from the input file and write it to the output file after applying the transformation rules.
    FILE *input = fopen(inputFile, "rb");
    if (input == NULL) {
        perror("Error opening input file");
        exit(EXIT_FAILURE);
    }
    FILE *output = fopen(outputFile, "wb");
    if (output == NULL) {
        perror("Error opening output file");
        exit(EXIT_FAILURE);
    }
    // Read the data from the input file and parse it.
    float* data = (float*)malloc(sizeof(float));
    size_t numDataPoints = 0;
    while (fread(&data[numDataPoints], sizeof(float), 1, input) == 1) {
        ++numDataPoints;
    }
    // Apply the transformation rules to the data.
    for (int i = 0; i < numDataPoints; ++i) {
        for (int j = 0; j < numRules; ++j) {
            if (ruleMatrix[j][0] == 1) { // If the rule is of the form "x -> y"
                data[i] += ruleMatrix[j][1]; // Add the constant value to x
            } else if (ruleMatrix[j][0] == 2) { // If the rule is of the form "x + k -> y + l"
                data[i] = data[i] + ruleMatrix[j][3] * ruleMatrix[j][1]; // Add the product of the constant and x to y
            } else if (ruleMatrix[j][0] == 3) { // If the rule is of the form "x - k -> y - l"
                data[i] = data[i] - ruleMatrix[j][3] * ruleMatrix[j][1]; // Subtract the product of the constant and x from y
            } else if (ruleMatrix[j][0] == 4) { // If the rule is of the form "x / k -> y / l"
                data[i] = data[i] / ruleMatrix[j][3]; // Divide x by the constant and store the result in y
            } else if (ruleMatrix[j][0] == 5) { // If the rule is of the form "x * k -> y * l"
                data[i] = data[i] * ruleMatrix[j][3]; // Multiply x by the constant and store the result in y
            } else if (ruleMatrix[j][0] == 6) { // If the rule is of the form "x % k -> y % l"
                data[i] = fmod(data[i], ruleMatrix[j][3]); // Calculate the modulus of x and store the result in y
            } else if (ruleMatrix[j][0] == 7) { // If the rule is of the form "x ^ k -> y ^ l"
                data[i] = pow(data[i], ruleMatrix[j][3]); // Raise x to the power of the constant and store the result in y
            } else if (ruleMatrix[j][0] == 8) { // If the rule is of the form "x <= k -> y <= l"
                data[i] = fmin(data[i], ruleMatrix[j][3]); // Take the minimum of x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 9) { // If the rule is of the form "x >= k -> y >= l"
                data[i] = fmax(data[i], ruleMatrix[j][3]); // Take the maximum of x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 10) { // If the rule is of the form "x < k -> y < l"
                data[i] = fmin(data[i], ruleMatrix[j][3]); // Take the minimum of x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 11) { // If the rule is of the form "x > k -> y > l"
                data[i] = fmax(data[i], ruleMatrix[j][3]); // Take the maximum of x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 12) { // If the rule is of the form "x != k -> y != l"
                data[i] = fabs(data[i] - ruleMatrix[j][3]); // Calculate the absolute difference between x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 13) { // If the rule is of the form "x == k -> y == l"
                data[i] = fabs(data[i] - ruleMatrix[j][3]); // Calculate the absolute difference between x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 14) { // If the rule is of the form "x && k -> y && l"
                data[i] = fmin(data[i], ruleMatrix[j][3]); // Take the minimum of x and the constant and store the result in y
            } else if (ruleMatrix[j][0] == 15) { // If the rule is of the form "x || k -> y || l"
                data[i] = fmax(data[i], ruleMatrix[j][3]); // Take the maximum of x and the constant and store the result in y
            }
        }
    }
    // Filter out any data entries that do not meet or exceed the specified threshold.
    size_t numOutputPoints = 0;
    for (int i = 0; i < numDataPoints; ++i) {
        if (data[i] >= threshold) {
            ++numOutputPoints;
        }
    }
    // Write the processed data to the output file.
    float* outputData = (float*)malloc(sizeof(float) * numOutputPoints);
    for (int i = 0, j = 0; i < numDataPoints; ++i) {
        if (data[i] >= threshold) {
            outputData[j++] = data[i];
        }
    }
    fwrite(outputData, sizeof(float), numOutputPoints, stdout);
}
