int largest_integer(FILE *input) {
    int max = -1; // Initialize with the smallest possible value
    char* buffer = NULL;
    size_t bufsize = 0;
    ssize_t bytes_read = 0;

    while ((bytes_read = getline(&buffer, &bufsize, input)) != -1) {
        // Ignore non-integer inputs and handle empty lines
        if (bytes_read > 0 && buffer[bytes_read-1] == '\n') {
            int num = atoi(buffer);
            if (num > max) {
                max = num;
            }
        }
    }

    free(buffer);
    return max;
}
