// Implementation of the logging function
void log(int verbosity, const char* format, ...) {
    // Check if the message is within the configured verbosity threshold
    if (verbosity <= LOG_VERBOSITY_DEBUG) {
        return;
    }

    // Create a new log message
    log_message_t* msg = malloc(sizeof(log_message_t));
    msg->verbosity = verbosity;

    // Format the log message using snprintf
    va_list args;
    va_start(args, format);
    vsnprintf(msg->message, LOG_MESSAGE_BUFFER_SIZE, format, args);
    va_end(args);

    // Add the log message to the buffer
