// CSP Framework

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <openssl/aes.h>
#include <openssl/rsa.h>
#include <openssl/ecdsa.h>
#include <openssl/obj_mac.h>
#include <openssl/evp.h>
#include <openssl/err.h>

#define CRYPTO_LOG_PATH "/var/log/crypto.log"
#define MAX_MEMORY 1024*1024*1024 // 1GB
#define DEFAULT_ALGORITHMS "aes-128 aes-192 aes-256 rsa-2048 rsa-4096 ecdsa-p256 ecdsa-p384"
#define DEFAULT_THRESHOLDS "aes=50,rsa=75,ecdsa=100"
#define DEFAULT_PRIORITIES "aes=high rsa=medium ecdsa=low"

// CSP Context Structure
typedef struct csp_context {
    char *algorithms; // list of supported algorithms
    char *thresholds; // threshold values for algorithm performance and resource usage
    char *priorities; // priority values for algorithm selection
    size_t memory_limit; // maximum amount of memory to use for cryptographic operations
} csp_context_t;

// CSP Functions
csp_context_t *csp_init(const char *algorithms, const char *thresholds, const char *priorities);
int csp_destroy(csp_context_t *ctx);
int csp_generate_key(csp_context_t *ctx, EVP_PKEY **pkey, const int key_size);
int csp_import_key(csp_context_t *ctx, EVP_PKEY **pkey, const unsigned char *data, size_t data_len);
int csp_export_key(csp_context_t *ctx, EVP_PKEY *pkey, unsigned char **data, size_t *data_len);
int csp_encrypt(csp_context_t *ctx, const unsigned char *plaintext, const unsigned char *key, const unsigned char *iv, unsigned char **ciphertext, size_t *ciphertext_len);
int csp_decrypt(csp_context_t *ctx, const unsigned char *ciphertext, const unsigned char *key, const unsigned char *iv, unsigned char **plaintext, size_t *plaintext_len);
int csp_sign(csp_context_t *ctx, EVP_PKEY *pkey, const unsigned char *data, size_t data_len, unsigned char **signature, size_t *signature_len);
int csp_verify(csp_context_t *ctx, EVP_PKEY *pkey, const unsigned char *data, size_t data_len, const unsigned char *signature, size_t signature_len);

// Internal Functions
int csp_check_algorithm(csp_context_t *ctx, const char *alg);
int csp_check_key(csp_context_t *ctx, EVP_PKEY *pkey);
int csp_get_algorithm_index(csp_context_t *ctx, const char *alg);
EVP_PKEY *csp_load_key(const unsigned char *data, size_t data_len);
void csp_unload_key(EVP_PKEY *pkey);
int csp_generate_random(unsigned char *buf, size_t len);
int csp_memory_usage(size_t *used, size_t *total);
void csp_print_error(const char *file, const int line, const char *func, const char *msg);

// Error Handling
#define CSP_ERROR -1
#define CSP_SUCCESS 0
#define CSP_UNKNOWN_ALGORITHM_ERROR 1
#define CSP_INVALID_KEY_ERROR 2
#define CSP_MEMORY_LIMIT_EXCEEDED_ERROR 3
#define CSP_RESOURCE_CONSTRAINT_ERROR 4
#define CSP_UNKNOWN_ERROR 5

int csp_handle_error(const char *file, const int line, const char *func, const int errnum);

// Internal Variables
static csp_context_t *ctx = NULL;
static EVP_PKEY **key_map = NULL;
static unsigned char *key_memory = NULL;
static size_t key_memory_used = 0;
static int num_keys = 0;
static double algorithm_thresholds[6] = {0};
static double algorithm_priorities[3] = {0};
static pthread_mutex_t csp_lock = PTHREAD_MUTEX_INITIALIZER;

// CSP Context Initialization and Destruction
csp_context_t *csp_init(const char *algorithms, const char *thresholds, const char *priorities) {
    if (!algorithms || !thresholds || !priorities) {
        return NULL;
    }
    csp_context_t *ctx = (csp_context_t *) malloc(sizeof(csp_context_t));
    memset(ctx, 0, sizeof(csp_context_t));

    ctx->algorithms = strdup(algorithms);
    ctx->thresholds = strdup(thresholds);
    ctx->priorities = strdup(priorities);
    ctx->memory_limit = MAX_MEMORY;

    // Parse thresholds and priorities
    int i, j;
    char *str1, *str2;
    for (i = 0; i < 6 && algorithm_thresholds[i] == 0; i++) {
        str1 = strtok(ctx->thresholds, ",");
        if (!str1) break;
        strcpy(algorithm_thresholds[i], str1);
    }
    for (j = 0; j < 3 && algorithm_priorities[j] == 0; j++) {
        str2 = strtok(ctx->priorities, ",");
        if (!str2) break;
        strcpy(algorithm_priorities[j], str2);
    }

    return ctx;
}

int csp_destroy(csp_context_t *ctx) {
    if (ctx->algorithms) free(ctx->algorithms);
    if (ctx->thresholds) free(ctx->thresholds);
    if (ctx->priorities) free(ctx->priorities);

    int i;
    for (i = 0; i < num_keys; i++) {
        csp_unload_key(key_map[i]);
    }
    free(key_memory);

    return CSP_SUCCESS;
}

// Key Management
int csp_check_algorithm(csp_context_t *ctx, const char *alg) {
    if (strlen(alg) == 0 || strcmp(alg, "RSA") && strcmp(alg, "DSA") && strcmp(alg, "ECDSA")) {
        return CSP_UNKNOWN_ALGORITHM_ERROR;
    }
    if (strncmp(ctx->algorithms, alg, strlen(alg)) != 0) {
        return CSP_UNKNOWN_ALGORITHM_ERROR;
    }
    return CSP_SUCCESS;
}

int csp_check_key(csp_context_t *ctx, EVP_PKEY *pkey) {
    if (pkey == NULL) {
        return CSP_INVALID_KEY_ERROR;
    }
    return CSP_SUCCESS;
}

int csp_get_algorithm_index(csp_context_t *ctx, const char *alg) {
    int i;
    for (i = 0; i < 6 && strcmp(algorithm_thresholds[i], alg); i++) { }
    if (i == 6) return CSP_UNKNOWN_ALGORITHM_ERROR;
    return i;
}

EVP_PKEY *csp_load_key(const unsigned char *data, size_t data_len) {
    int alg = strncmp(data, "RSA", 3);
    if (alg == 0) {
        EVP_PKEY *pkey;
        pkey = EVP_parse_public_key(data, data_len);
        return pkey;
    } else if (alg == -1) {
        // DSA or ECDSA
        int type = strncmp(data, "DSA", 3);
        if (type == 0) {
            EVP_PKEY *pkey;
            pkey = EVP_parse_public_key(data, data_len);
            return pkey;
        } else if (type == -1) {
            // DSA or ECDSA
            int type = strncmp(data, "ECDSA", 6);
            if (type == 0) {
                EVP_PKEY *pkey;
                pkey = EVP_parse_public_key(data, data_len);
                return pkey;
            } else if (type == -1) {
                // DSA or ECDSA
                return NULL;
            }
        }
    }
}

void csp_unload_key(EVP_PKEY *pkey) {
    EVP_PKEY_free(pkey);
}

// Random Number Generation
int csp_generate_random(unsigned char *buf, size_t len) {
    if (!RAND_bytes(buf, len)) {
        return CSP_RESOURCE_CONSTRAINT_ERROR;
    }
    return CSP_SUCCESS;
}

// Memory Usage
int csp_memory_usage(size_t *used, size_t *total) {
    if (used != NULL && total != NULL) {
        *used = key_memory_used;
        *total = MAX_MEMORY;
    }
    return CSP_SUCCESS;
}

// Printing Errors
void csp_print_error(const char *file, const int line, const char *func, const char *msg) {
    printf("Error: %s:%d [%s] (%s)\n", file, line, func, msg);
}

int csp_handle_error(const char *file, const int line, const char *func, const int errnum) {
    switch (errnum) {
        case CSP_ERROR:
            csp_print_error(file, line, func, "Generic error");
            break;
        case CSP_UNKNOWN_ALGORITHM_ERROR:
            csp_print_error(file, line, func, "Unknown algorithm error");
            break;
        case CSP_INVALID_KEY_ERROR:
            csp_print_error(file, line, func, "Invalid key error");
            break;
        case CSP_RESOURCE_CONSTRAINT_ERROR:
            csp_print_error(file, line, func, "Resource constraint error");
            break;
        default:
            csp_print_error(file, line, func, "Unknown error");
            break;
    }
}
```

### Exercise 3 - Implementing the `CSP` module

#### Problem Statement

In this exercise, you will implement a Cryptographic Service Provider (CSP) module that provides a set of cryptographic functions. The module should support different types of encryption algorithms and provide a way to generate keys. You will also implement a function to sign data using the RSA algorithm.

The CSP module is a key part of the `DDoS` project, as it allows the network to communicate with other nodes securely.

#### Instructions

1. Implement the `CSP` module in the file `csp.js`. The module should export an object with the following functions:
	* `generateKey(algorithm, keySize)` - Generates a new public/private key pair using the specified algorithm and size of the key. The function should return the generated key as an object with two properties: `public` and `private`, which contain the public and private keys, respectively.
	* `encrypt(data, publicKey)` - Encrypts the given data using the specified public key. The function should return the encrypted data as a buffer.
	* `decrypt(data, privateKey)` - Decrypts the given data using the specified private key. The function should return the decrypted data as a buffer.
	* `sign(data, privateKey)` - Signs the given data using the specified private key and RSA algorithm. The function should return the signature as a buffer.
2. Write unit tests for each of the functions in the `CSP` module. The unit tests should test all possible scenarios, including invalid input data, invalid key sizes, etc.
3. Run the unit tests and make sure they pass successfully.
4. In the file `network.js`, replace the `getPublicKey` function with a call to the new `CSP` module's `generateKey` function to generate a new public/private key pair for each node in the network. This will allow the network to communicate securely using the RSA algorithm.
5. Run the simulation and observe the secure communication between nodes using the RSA algorithm.
6. Submit your solution (`csp.js`) and make sure it works correctly.']

