#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <openssl/conf.h>
#include <openssl/evp.h>

struct HashAlgorithm {
    char *name;
    void (*func)(const EVP_MD *, int, ...);
    void *params;
};

struct CipherAlgorithm {
    char *name;
    void (*func)(EVP_CIPHER_CTX *, const unsigned char *, size_t *, const unsigned char *, size_t, const unsigned char *, size_t);
    void *params;
};

typedef struct AvailableAlgorithms {
    struct HashAlgorithm *hashes;
    int numHashes;
    struct CipherAlgorithm *ciphers;
    int numCiphers;
} AvailableAlgorithms;

AvailableAlgorithms* getAvailableAlgorithms() {
    AvailableAlgorithms *algorithms = malloc(sizeof(AvailableAlgorithms));
    algorithms->hashes = NULL;
    algorithms->numHashes = 0;
    algorithms->ciphers = NULL;
    algorithms->numCiphers = 0;

    // Get list of supported hash functions from OpenSSL
    const EVP_MD *mds[EVP_MAX_MDS];
    int numHashes = EVP_get_digests(mds, EVP_MAX_MDS);
    if (numHashes > 0) {
        algorithms->hashes = malloc(sizeof(struct HashAlgorithm) * numHashes);
        for (int i = 0; i < numHashes; i++) {
            struct HashAlgorithm hash = {mds[i]->name, mds[i]->dgs->init, mds[i]->dgs->do_one, mds[i]->dgs->block};
            algorithms->hashes[algorithms->numHashes] = hash;
            algorithms->numHashes++;
        }
    }

    // Get list of supported ciphers from OpenSSL
    const EVP_CIPHER *ciphers[EVP_MAX_CIPHERS];
    int numCiphers = EVP_get_ciphers(ciphers, EVP_MAX_CIPHERS);
    if (numCiphers > 0) {
        algorithms->ciphers = malloc(sizeof(struct CipherAlgorithm) * numCiphers);
        for (int i = 0; i < numCiphers; i++) {
            struct CipherAlgorithm cipher = {ciphers[i]->name, ciphers[i]->init, NULL, ciphers[i]->do_cipher};
            algorithms->ciphers[algorithms->numCiphers] = cipher;
            algorithms->numCiphers++;
        }
    }

    // Check for additional cryptographic libraries that may be required
    if (/* Additional libraries are required */) {
        // Load the libraries dynamically and initialize them
        /* ... */
    }

    return algorithms;
}

void freeAvailableAlgorithms(AvailableAlgorithms *algorithms) {
    for (int i = 0; i < algorithms->numHashes; i++) {
        struct HashAlgorithm hash = algorithms->hashes[i];
        if (hash.params != NULL) {
            free(hash.params);
        }
    }
    free(algorithms->hashes);

    for (int i = 0; i < algorithms->numCiphers; i++) {
        struct CipherAlgorithm cipher = algorithms->ciphers[i];
        if (cipher.params != NULL) {
            free(cipher.params);
        }
    }
    free(algorithms->ciphers);
    free(algorithms);
}

struct HashAlgorithm* getHashAlgorithm(AvailableAlgorithms *algorithms, const char *name) {
    for (int i = 0; i < algorithms->numHashes; i++) {
        if (strcmp(algorithms->hashes[i].name, name) == 0) {
            return &algorithms->hashes[i];
        }
    }
    return NULL;
}

struct CipherAlgorithm* getCipherAlgorithm(AvailableAlgorithms *algorithms, const char *name) {
    for (int i = 0; i < algorithms->numCiphers; i++) {
        if (strcmp(algorithms->ciphers[i].name, name) == 0) {
            return &algorithms->ciphers[i];
        }
    }
    return NULL;
}

void* getHashParams(AvailableAlgorithms *algorithms, const char *name) {
    struct HashAlgorithm *hash = getHashAlgorithm(algorithms, name);
    if (hash != NULL) {
        return hash->params;
    } else {
        return NULL;
    }
}

void* getCipherParams(AvailableAlgorithms *algorithms, const char *name) {
    struct CipherAlgorithm *cipher = getCipherAlgorithm(algorithms, name);
    if (cipher != NULL) {
        return cipher->params;
    } else {
        return NULL;
    }
}

int hashFile(AvailableAlgorithms *algorithms, const char *filepath, unsigned char *hash, size_t len) {
    struct HashAlgorithm *hashAlg = getHashAlgorithm(algorithms, "SHA-256");
    if (hashAlg == NULL) {
        return -1;
    }

    EVP_MD_CTX *mdctx = EVP_MD_CTX_new();
    int ret = EVP_DigestFile(mdctx, filepath, hashAlg->params);
    if (ret == 0) {
        return -1;
    }

    unsigned int digestLen = len;
    ret = EVP_DigestFinal(mdctx, hash, &digestLen);
    if (ret == 0) {
        return -1;
    }

    EVP_MD_CTX_free(mdctx);
    return digestLen;
}

int cipherFile(AvailableAlgorithms *algorithms, const char *filepath, unsigned char *ciphertext, size_t len) {
    struct CipherAlgorithm *cipherAlg = getCipherAlgorithm(algorithms, "AES-256");
    if (cipherAlg == NULL) {
        return -1;
    }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    int ret = EVP_EncryptInit(ctx, cipherAlg->params);
    if (ret == 0) {
        return -1;
    }

    size_t outlen = len;
    ret = EVP_EncryptUpdate(ctx, ciphertext, &outlen, filepath, strlen(filepath));
    if (ret == 0) {
        return -1;
    }

    unsigned char tag[16];
    ret = EVP_EncryptFinal(ctx, tag, NULL);
    if (ret == 0) {
        return -1;
    }

    EVP_CIPHER_CTX_free(ctx);
    return outlen;
}']

