                    Player player = new Player(conn);
                    players.Add(player);
                    numPlayersInMatch++;

                    // Send match information to player
                    if (currentMatch != null)
                    {
                        currentMatch.SendPlayerInfo(player, false);
                    }
                }

                // Handle match start and end
                if (matchStarted && numPlayersInMatch == 0)
                {
                    EndCurrentMatch();
                }
                else if (!matchStarted && numPlayersInMatch >= minPlayersPerMatch)
                {
                    StartNewMatch();
                }

                // Update server capacity based on real-time load metrics
                if (dynamicAdjustmentEnabled)
                {
                    int availableResources = GetAvailableResources();
                    if (availableResources < 100)
                    {
                        AdjustServerCapacity(availableResources);
                    }
                }

                // Handle network disruptions and failover to secondary server
                if (!server.IsListening && numPlayersInMatch > 0)
                {
                    Console.WriteLine("Network disruption detected, starting secondary server...");
                    SecondaryServer.Start();
                }
            }
        }

        // Start a new match
        void StartNewMatch()
        {
            currentMatch = new Match(players);
            numPlayersInMatch = 0;
            matchStarted = true;
            Console.WriteLine("New match started");
        }

        // End the current match and clean up
        void EndCurrentMatch()
        {
            foreach (Player player in players)
            {
                player.Disconnect();
            }
            currentMatch = null;
            numPlayersInMatch = 0;
            matchStarted = false;
            Console.WriteLine("Match ended");
        }

        // Get available resources based on CPU, memory, and network throughput
        int GetAvailableResources()
        {
            return (int)(CPUUsage * MemoryConsumption * NetworkThroughput);
        }

        // Adjust server capacity based on real-time load metrics
        void AdjustServerCapacity(int availableResources)
        {
            if (availableResources < 100)
            {
                Console.WriteLine("Adjusting server capacity...");
                CPUUsage = Math.Min(1, CPUUsage * 2);
                MemoryConsumption = Math.Min(1, MemoryConsumption * 2);
                NetworkThroughput = Math.Min(1, NetworkThroughput * 2);
            }
            else if (availableResources > 100)
            {
                Console.WriteLine("Adjusting server capacity...");
                CPUUsage = Math.Max(0.5, CPUUsage / 2);
                MemoryConsumption = Math.Max(0.5, MemoryConsumption / 2);
                NetworkThroughput = Math.Max(0.5, NetworkThroughput / 2);
            }
        }
    }

    // Class for storing player information
    class Player
    {
        public ServerConnection Connection { get; set; }
        public bool IsInMatch { get; set; }

        public Player(ServerConnection connection)
        {
            Connection = connection;
        }

        // Send match information to player
        public void SendPlayerInfo(Player player, bool isNewPlayer)
        {
            if (isNewPlayer)
            {
                Console.WriteLine($"{player.Connection.RemoteEndPoint} connected");
            }
            else
            {
                Console.WriteLine($"{player.Connection.RemoteEndPoint} disconnected");
            }
        }
    }

    // Class for storing match information
    class Match
    {
        public List<Player> Players { get; set; }
        public int CurrentRound { get; set; }

        public Match(List<Player> players)
        {
            Players = players;
            CurrentRound = 0;
        }

        // Send match information to all players
        public void SendMatchInfo()
        {
            foreach (Player player in Players)
            {
                Console.WriteLine($"{player.Connection.RemoteEndPoint} joined match");
            }
        }
    }

    // Class for handling server connections
    class ServerConnection
    {
        public IPEndPoint RemoteEndPoint { get; set; }
        public NetworkStream NetworkStream { get; set; }
        public StreamReader Reader { get; set; }
        public StreamWriter Writer { get; set; }

        public ServerConnection(IPEndPoint remoteEndPoint, NetworkStream networkStream)
        {
            RemoteEndPoint = remoteEndPoint;
            NetworkStream = networkStream;
            Reader = new StreamReader(networkStream);
            Writer = new StreamWriter(networkStream);
        }

        // Accept incoming connection and handle authentication
        public void Accept()
        {
            Console.WriteLine($"{RemoteEndPoint} connected");
            string username = Reader.ReadLine();
            string password = Reader.ReadLine();
            if (username == "admin" && password == "password")
            {
                Writer.Write("Authentication successful\n");
            }
            else
            {
                Writer.Write("Authentication failed\n");
            }
        }

        // Send data to the remote end point
        public void Send(string data)
        {
            Writer.WriteLine(data);
        }

        // Disconnect from the remote end point
        public void Disconnect()
        {
            Console.WriteLine($"{RemoteEndPoint} disconnected");
            NetworkStream.Close();
        }
    }

    // Class for handling secondary server connections
    class SecondaryServerConnection
    {
        public IPEndPoint RemoteEndPoint { get; set; }
        public NetworkStream NetworkStream { get; set; }
        public StreamReader Reader { get; set; }
        public StreamWriter Writer { get; set; }

        public SecondaryServerConnection(IPEndPoint remoteEndPoint, NetworkStream networkStream)
        {
            RemoteEndPoint = remoteEndPoint;
            NetworkStream = networkStream;
            Reader = new StreamReader(networkStream);
            Writer = new StreamWriter(networkStream);
        }

        // Accept incoming connection and handle authentication
        public void Accept()
        {
            Console.WriteLine($"{RemoteEndPoint} connected");
            string username = Reader.ReadLine();
            string password = Reader.ReadLine();
            if (username == "admin" && password == "password")
            {
                Writer.Write("Authentication successful\n");
            }
            else
            {
                Writer.Write("Authentication failed\n");
            }
        }

        // Send data to the remote end point
