package com.example.backgroundservices;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class BackgroundServiceManager {
    private static final Map<String, Service> services = new HashMap<>();
    private static final List<String> activeServices = new ArrayList<>();

    public static void addService(String name, int startDelay, int stopDelay, int maxRestarts) {
        if (services.containsKey(name)) {
            throw new IllegalArgumentException("A service with the same name already exists.");
        }

        Service service = new Service(name, startDelay, stopDelay, maxRestarts);
        services.put(name, service);
    }

    public static void removeService(String name) {
        if (!services.containsKey(name)) {
            throw new IllegalArgumentException("The specified service does not exist.");
        }

        activeServices.remove(name);
        services.remove(name);
    }

    public static void startService(String name) {
        if (!services.containsKey(name)) {
            throw new IllegalArgumentException("The specified service does not exist.");
        }

        Service service = services.get(name);
        int attempts = 0;

        while (attempts < service.maxRestarts) {
            try {
                Thread.sleep(service.startDelay);
                service.start();
                activeServices.add(name);
                break;
            } catch (InterruptedException e) {
                attempts++;
            }
        }
    }

    public static void stopService(String name) {
        if (!activeServices.contains(name)) {
            throw new IllegalArgumentException("The specified service is not active.");
        }

        Service service = services.get(name);
        int attempts = 0;

        while (attempts < service.maxRestarts) {
            try {
                Thread.sleep(service.stopDelay);
                service.stop();
                activeServices.remove(name);
                break;
            } catch (InterruptedException e) {
                attempts++;
            }
        }
    }

    public static boolean isServiceActive(String name) {
        return activeServices.contains(name);
    }

    public static void logMetrics() {
        // TODO: Implement metrics logging here.
    }

    private static class Service {
        private String name;
        private int startDelay;
        private int stopDelay;
        private int maxRestarts;

        public Service(String name, int startDelay, int stopDelay, int maxRestarts) {
            this.name = name;
            this.startDelay = startDelay;
            this.stopDelay = stopDelay;
            this.maxRestarts = maxRestarts;
        }

        public void start() {
            // TODO: Implement service start logic here.
        }

        public void stop() {
            // TODO: Implement service stop logic here.
        }
    }
}
