use std::time;
use std::process::Command;
use std::process::Output;

fn build() -> i32 {
    // Measure the time taken for the build using the `std::time` module
    let start = time::Instant::now();
    let output: Output = Command::new("build_driver")
        .arg("--flag")
        .arg("value")
        .output()
        .expect("failed to execute command");
    let elapsed = start.elapsed().as_secs();

    // Record the resident set size of the process before and after the build
    let initial_rss = get_resident_set_size(Command::new("build_driver")).unwrap();
    let final_rss = get_resident_set_size(Command::new("build_driver").arg("--flag").arg("value")).unwrap();

    // Catch any errors during the build with the `build_driver::catch_with_exit_code` function
    if output.status.success() {
        println!("Build successful!");
        return 0;
    } else {
        let error = EarlyError::new(output.status, elapsed, initial_rss, final_rss);
        println!("Build failed: {}", error);
        return 1;
    }
}

fn get_resident_set_size(cmd: &mut Command) -> Result<u64, std::io::Error> {
    let mut handle = cmd.spawn()?;
    let status = handle.wait()?;
    if !status.success() {
        return Err(std::io::Error::new(
            std::io::ErrorKind::Other,
            "failed to get resident set size",
        ));
    }
    Ok(handle.try_wait()?.map(|p| p.memory().unwrap()).ok_or_else(|| {
        std::io::Error::new(std::io::ErrorKind::Other, "process exited without memory info")
    })?)
}

