<?php
function updateClinicStatus($clinicId, $newStatus, $lastModifiedIP, $lastModifiedDate, $errorMessageFormat, ...$args) {
    // 1. Validate inputs
    if (!is_numeric($clinicId)) {
        return "Error: Invalid clinic ID.";
    }
    if (!is_string($newStatus) || !in_array($newStatus, ['active', 'inactive'])) {
        return "Error: Invalid new status.";
    }
    if (!is_string($lastModifiedIP)) {
        return "Error: Invalid last modified IP address.";
    }
    if (!is_string($lastModifiedDate) || !strtotime($lastModifiedDate)) {
        return "Error: Invalid last modified date.";
    }

    // 2. Establish secure database connection using PDO
    $pdo = new PDO("mysql:host=localhost;dbname=mydatabase", "username", "password");
    $pdo->setAttribute(PDO::ATTR_ERRMODE, PDO::ERRMODE_EXCEPTION);

    // 3. Prepare and execute SQL statement to update clinic status
    $stmt = $pdo->prepare("UPDATE clinics SET status=:newStatus, lastModifiedIP=:lastModifiedIP, lastModifiedDate=:lastModifiedDate WHERE id=:clinicId");
    $stmt->bindParam(":newStatus", $newStatus);
    $stmt->bindParam(":lastModifiedIP", $lastModifiedIP);
    $stmt->bindParam(":lastModifiedDate", $lastModifiedDate);
    $stmt->bindParam(":clinicId", $clinicId);

    // 4. Handle potential latency issues and ensure operation completes within specified time limit
    $startTime = microtime(true);
    while (microtime(true) - $startTime < 10) { // Retry mechanism with exponential backoff
        try {
            $stmt->execute();
            return "Success: Clinic status updated successfully.";
        } catch (PDOException $e) {
            if ($e->getCode() === '23000') { // Duplicate entry
                continue;
            } else {
                break;
            }
        }
    }

    // 5. Log detailed error messages to application log using snprintf and va_start/va_end
    $errorMessage = sprintf($errorMessageFormat, ...$args);
    file_put_contents('/path/to/application/log', $errorMessage . PHP_EOL, FILE_APPEND);

    // 6. Handle concurrent updates from multiple instances by implementing a distributed lock or another mechanism
    $lock = fopen("/tmp/clinic-$clinicId.lock", "w");
    fwrite($lock, $pid = getmypid());
    if (flock($lock, LOCK_EX | LOCK_NB)) {
        // Acquired lock; execute update
        $stmt->execute();
        flock($lock, LOCK_UN);
    } else {
        // Failed to acquire lock; release and try again
        fclose($lock);
        usleep(10000); // 10 milliseconds
        goto updateClinicStatus;
    }

    return "Error: Clinic status update failed.";
}
?>
