int updateUserPassword(const char* hostname, const char* userId, const char* newPassword) {
    // Perform DNS resolution for the provided hostname to verify its legitimacy
    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;
    struct addrinfo* result;
    if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        syslog(LOG_ERR, "Failed to resolve hostname: %s", hostname);
        return -1;
    }

    // Establish a connection to the external service API
    int sock = socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0) {
        syslog(LOG_ERR, "Failed to create socket");
        return -1;
    }
    struct addrinfo* res;
    for (res = result; res != NULL; res = res->ai_next) {
        if (connect(sock, res->ai_addr, res->ai_addrlen) == 0) {
            break;
        }
    }
    freeaddrinfo(result);
    if (res == NULL) {
        syslog(LOG_ERR, "Failed to connect to service API");
        return -1;
    }

    // Send a request to the external service API to validate the new password
    char* request = "UPDATE USER PASSWORD\n";
    if (send(sock, request, strlen(request), 0) < 0) {
        syslog(LOG_ERR, "Failed to send request");
        close(sock);
        return -1;
    }
    char response[128];
    memset(response, '\0', sizeof(response));
    if (recv(sock, response, sizeof(response), 0) < 0) {
        syslog(LOG_ERR, "Failed to receive response");
        close(sock);
        return -1;
    }

    // Parse the response from the external service API and handle any errors
    char* token = strtok(response, "\n");
    if (token == NULL) {
        syslog(LOG_ERR, "Failed to parse response");
        close(sock);
        return -1;
    }
    int statusCode = atoi(token);
    if (statusCode != 200) {
        syslog(LOG_ERR, "Invalid password strength or compliance with organizational policies");
        close(sock);
        return -1;
    }

    // Close the socket and log activity
    close(sock);
    syslog(LOG_INFO, "User password updated successfully");
    return 0;
}
