// Octree Initialization Function

#include <iostream>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <string>
#include <memory>
#include <algorithm>

using namespace std;

class Octree {
public:
    // Constructor
    Octree(int feature_size, int num_leaf_nodes, int data_capacity) :
        feature_size_(feature_size),
        num_leaf_nodes_(num_leaf_nodes),
        data_capacity_(data_capacity),
        max_level_(ceil(log2(num_leaf_nodes))),
        leaf_level_(max_level_ - 1),
        data_pointers_(vector<shared_ptr<int>>(data_capacity, nullptr)),
        tree_pointers_(vector<shared_ptr<OctreeNode>>(pow(2, max_level_), nullptr)) { }

    // Member Functions
    void initialize();
    void insert(const vector<float>& data);
    void remove(const vector<float>& data);
    bool contains(const vector<float>& data) const;
    void print() const;

private:
    // Octree Node Structure
    struct OctreeNode {
        int level_;
        shared_ptr<int> data_pointer_;
        shared_ptr<OctreeNode> child1_, child2_;
    };

    // Member Variables
    const int feature_size_;
    const int num_leaf_nodes_;
    const int data_capacity_;
    const int max_level_;
    const int leaf_level_;
    vector<shared_ptr<int>> data_pointers_;
    vector<shared_ptr<OctreeNode>> tree_pointers_;
};

void Octree::initialize() {
    // Initialize data pointers and tree nodes
    for (int i = 0; i < data_capacity_; ++i) {
        data_pointers_[i] = make_shared<int>(-1);
    }
    for (int i = 0; i < pow(2, max_level_); ++i) {
        tree_pointers_[i] = make_shared<OctreeNode>();
    }
}

void Octree::insert(const vector<float>& data) {
    // Find the appropriate node and insert data pointer
    shared_ptr<OctreeNode> current = tree_pointers_[0];
    for (int i = 0; i < max_level_; ++i) {
        if (current->data_pointer_ == nullptr) {
            // Insert data at this level
            current->data_pointer_ = data_pointers_[current->data_pointer_.use_count()];
            *(current->data_pointer_) = i;
            return;
        } else if (current->child1_ == nullptr) {
            // Create children and insert data at next level
            current->child1_ = make_shared<OctreeNode>();
            current->child2_ = make_shared<OctreeNode>();
            *(current->data_pointer_) = i;
            return;
        } else {
            // Recursively descend tree
            if (data[i] == 0) {
                current = current->child1_;
            } else {
                current = current->child2_;
            }
        }
    }
}

void Octree::remove(const vector<float>& data) {
    // Find the appropriate node and remove data pointer
    shared_ptr<OctreeNode> current = tree_pointers_[0];
    for (int i = 0; i < max_level_; ++i) {
        if (current->data_pointer_ == nullptr) {
            return;
        } else if (current->child1_ == nullptr) {
            // Remove data at this level
            *(current->data_pointer_) = -1;
            current->data_pointer_ = nullptr;
            return;
        } else {
            // Recursively descend tree
            if (data[i] == 0) {
                current = current->child1_;
            } else {
                current = current->child2_;
            }
        }
    }
}

bool Octree::contains(const vector<float>& data) const {
    // Find the appropriate node and check if data is present
    shared_ptr<OctreeNode> current = tree_pointers_[0];
    for (int i = 0; i < max_level_; ++i) {
        if (current->data_pointer_ == nullptr) {
            return false;
        } else if (current->child1_ == nullptr) {
            // Check data at this level
            int index = *(current->data_pointer_);
            if (index != -1 && data[i] == 0) {
                return true;
            }
            return false;
        } else {
            // Recursively descend tree
            if (data[i] == 0) {
                current = current->child1_;
            } else {
                current = current->child2_;
            }
        }
    }
}

void Octree::print() const {
    // Print the octree structure
    for (int i = 0; i < pow(2, max_level_); ++i) {
        if (tree_pointers_[i] != nullptr) {
            cout << "Level " << tree_pointers_[i]->level_ << ": ";
            print_node(tree_pointers_[i]);
        }
    }
}

void Octree::print_node(const shared_ptr<OctreeNode>& node) const {
    // Print the children of a node and its data pointer
    if (node->child1_ != nullptr) {
        print_node(node->child1_);
    }
    if (node->child2_ != nullptr) {
        print_node(node->child2_);
    }
    cout << node->data_pointer_ << " ";
}
```
This code defines a class `Octree` that implements an octree data structure for a specific spatial indexing application. The constructor takes in three parameters: `feature_size`, which is the size of each feature vector, `num_leaf_nodes`, which is the number of leaf nodes in the tree, and `data_capacity`, which is the total capacity of the tree.

The class has several member functions:
* `initialize`: This function initializes the data pointers and tree nodes.
* `insert`: This function inserts a new feature vector into the octree.
* `remove`: This function removes an existing feature vector from the octree.
* `contains`: This function checks if an existing feature vector is present in the octree.
* `print`: This function prints the structure of the octree.

The `OctreeNode` struct defines a node in the octree, which has three pointers: `child1`, `child2`, and `data_pointer`. The `data_pointer` points to an index in the data array that stores the feature vector at this level of the tree. The `child1` and `child2` pointers point to the next levels in the tree.

The code also defines a few utility functions: `print_node`, which prints the children of a node and its data pointer, and `pow`, which calculates the power of an integer.

This implementation uses lazy allocation, meaning that nodes are only created when necessary. This reduces the memory usage of the tree while maintaining efficient insertion and removal operations. The use of smart pointers also helps to manage memory safely and efficiently.

Please note that this is a highly simplified version of the octree data structure and it does not include all the features of a full-fledged implementation, such as balancing the tree, handling collisions, etc.']

