#include <vector>
#include <map>
#include <queue>
#include <iostream>

using namespace std;

bool scheduleTasks(const vector<TaskConfig>& taskConfigs) {
    // Create a priority queue of tasks based on their priorities
    // and a map to keep track of the dependencies between tasks
    priority_queue<Task, vector<Task>, greater<Task>> taskQueue;
    map<int, set<int>> dependencyMap;

    for (const auto& taskConfig : taskConfigs) {
        Task task(taskConfig.id, taskConfig.scheduledTime, taskConfig.duration);
        // Add the task to the priority queue based on its priority
        taskQueue.push(task);
        // Update the dependency map with the dependencies of the task
        for (const auto& dependency : taskConfig.dependencies) {
            dependencyMap[dependency.first].insert(dependency.second);
        }
    }

    while (!taskQueue.empty()) {
        Task currentTask = taskQueue.top();
        // If the current task has not started yet, start it and remove it from the queue
        if (currentTask.startTime == -1) {
            currentTask.startTime = 0;
            taskQueue.pop();
        }

        for (const auto& dependency : dependencyMap[currentTask.id]) {
            // If a dependency of the current task has not finished yet, skip it
            if (!taskQueue.empty() && taskQueue.top().id == dependency) {
                break;
            }
        }
        // If all dependencies have been met, start the next task
        if (dependencyMap[currentTask.id].size() == 0) {
            Task nextTask = taskQueue.top();
            // Update the start time of the next task based on its priority and previous execution times
            nextTask.startTime = currentTask.startTime + nextTask.priority;
            taskQueue.pop();
        } else {
            break;
        }
    }

    // Check for conflicts with existing tasks
    for (const auto& taskConfig : taskConfigs) {
        Task task(taskConfig.id, 0, taskConfig.duration);
        bool conflict = false;
        for (int i = 0; i < taskQueue.size(); ++i) {
            // If the new task conflicts with an existing task, set conflict to true and break
            if (task.startTime + task.duration > taskQueue[i].startTime &&
                task.startTime < taskQueue[i].startTime + taskQueue[i].duration) {
                conflict = true;
                break;
            }
        }
        // If there is a conflict, log an error message and return false
        if (conflict) {
            cerr << "Conflict found for task " << taskConfig.id << " at time " << taskConfig.scheduledTime << endl;
            return false;
        }
    }

    // If no conflicts were found, log the completion of each task and return true
    while (!taskQueue.empty()) {
        Task completedTask = taskQueue.top();
        cout << "Task " << completedTask.id << " completed at time " << completedTask.startTime << endl;
        taskQueue.pop();
    }

    return true;
}

struct Task {
    int id;
    int startTime;
    int duration;
    int priority;

    Task(int id, int startTime, int duration) : id(id), startTime(startTime), duration(duration), priority(0) {}
};

struct TaskConfig {
    int id;
    int scheduledTime;
    int duration;
    vector<pair<int, int>> dependencies;
    int priority;

    TaskConfig(int id, int scheduledTime, int duration, vector<pair<int, int>> dependencies, int priority) :
        id(id), scheduledTime(scheduledTime), duration(duration), dependencies(dependencies), priority(priority) {}
};

int main() {
    // Test case 1: Schedule multiple tasks with dependencies and priorities
    vector<TaskConfig> taskConfigs = {
        TaskConfig(1, 0, 5, {{2, 3}}, 3),
        TaskConfig(2, 3, 4, {}, 2),
        TaskConfig(3, 7, 6, {}, 1)
    };

    bool scheduled = scheduleTasks(taskConfigs);
    if (scheduled) {
        cout << "Scheduling successful!" << endl;
    } else {
        cout << "Scheduling failed!" << endl;
    }

    // Test case 2: Schedule multiple tasks with conflicts and priorities
    vector<TaskConfig> taskConfigs2 = {
        TaskConfig(1, 0, 5, {{2, 3}}, 3),
        TaskConfig(2, 3, 4, {}, 2),
        TaskConfig(3, 7, 6, {}, 1)
    };

    scheduled = scheduleTasks(taskConfigs2);
    if (scheduled) {
        cout << "Scheduling successful!" << endl;
    } else {
        cout << "Scheduling failed!" << endl;
    }

    return 0;
}']

