// Define a function to verify the existence and integrity of a default theme directory
int verifyDefaultThemeDirectory() {
    // Open the default theme directory for reading
    DIR* dir = opendir(DEFAULT_THEME_DIRECTORY);
    if (dir == NULL) {
        printf("Error: failed to open default theme directory\n");
        return -1;
    }

    // Iterate over the files in the directory and verify their existence and integrity
    struct dirent* entry = readdir(dir);
    while (entry != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        char path[PATH_MAX];
        snprintf(path, PATH_MAX, "%s/%s", DEFAULT_THEME_DIRECTORY, entry->d_name);
        if (verifyFileIntegrity(path)) {
            printf("Error: failed to verify file integrity for %s\n", path);
            return -1;
        }
    }

    // Close the directory and return success
    closedir(dir);
    return 0;
}

