        public static async Task<bool> Launch(string directoryPath, string siteName)
        {
            // Validate inputs
            if (!Directory.Exists(directoryPath))
            {
                LogWarning($"Invalid directory path: {directoryPath}");
                return null;
            }

            var webConfigFile = Path.Combine(directoryPath, "web.config");
