            var directoryInfo = new DirectoryInfo(directoryPath);
            if (!directoryInfo.Exists || !directoryInfo.IsAccessible())
            {
                LogError($"Invalid or inaccessible directory: {directoryPath}");
                return false;
            }

            var dependencies = GetDependencies();
            foreach (var dependency in dependencies)
            {
                if (!dependency.IsInstalled || !dependency.IsUpToDate)
                {
                    LogInfo($"Updating dependency: {dependency.Name}");
                    try
                    {
                        await dependency.Update();
                    }
                    catch (Exception e)
                    {
                        LogError($"Failed to update dependency: {e.Message}");
                        return false;
                    }
                }
            }

            // Implement retry mechanism for launching website
            var attempt = 0;
            while (attempt < MAX_ATTEMPTS)
            {
