using System;
using System.Text;
using System.Security.Cryptography;
using System.Collections.Generic;

public static class OAuth2TokenProcessor {
  private const string BEARER_TOKEN_TYPE = "Bearer";
  private const int MINIMUM_EXPIRES_IN = 1;

  public static TokenProcessingResult Process(string accessTokenResponse, string key, string iv) {
    var tokenJson = JObject.Parse(accessTokenResponse);
    var tokenType = (string)tokenJson["token_type"];
    if (tokenType != BEARER_TOKEN_TYPE) {
      LogWarning("Invalid token type: " + tokenType);
      return TokenProcessingResult.Error;
    }

    var expiresIn = (int)tokenJson["expires_in"];
    if (expiresIn <= 0) {
      LogWarning("Invalid expiration time: " + expiresIn);
      return TokenProcessingResult.Error;
    }

    var refreshToken = tokenJson["refresh_token"] as string;
    if (!string.IsNullOrEmpty(refreshToken)) {
      // handle refresh token
    }

    var messageBase64 = (string)tokenJson["message"];
    if (string.IsNullOrEmpty(messageBase64)) {
      LogWarning("Missing message in token response");
      return TokenProcessingResult.Error;
    }

    try {
      // decrypt message using Triple DES encryption with key and iv
      var messageBytes = Convert.FromBase64String(messageBase64);
      var decryptedMessage = DecryptTripleDES(messageBytes, key, iv);

      // cache decrypted message for future use
      var cachedDecryptedMessage = CachedDecryptedMessages[accessTokenResponse];
      if (cachedDecryptedMessage == null) {
        cachedDecryptedMessage = new Dictionary<string, string>();
        CachedDecryptedMessages[accessTokenResponse] = cachedDecryptedMessage;
      }

      cachedDecryptedMessage[messageBase64] = decryptedMessage;

      return TokenProcessingResult.Success(decryptedMessage);
    } catch (Exception e) {
      LogError("Failed to decrypt message: " + e.Message);
      return TokenProcessingResult.Error;
    }
  }

  private static string DecryptTripleDES(byte[] cipherText, string key, string iv) {
    using (var tripleDes = new TripleDESCryptoServiceProvider()) {
      var decryptedBytes = tripleDes.CreateDecryptor(key, iv).TransformFinalBlock(cipherText, 0, cipherText.Length);
      return Encoding.UTF8.GetString(decryptedBytes);
    }
  }

  private static readonly Dictionary<string, Dictionary<string, string>> CachedDecryptedMessages = new Dictionary<string, Dictionary<string, string>>();
}
