    public static class HashHelper
    {
        private const int BUFFER_SIZE = 1024 * 1024; // 1MB buffer size

        public static string ComputeHash(string filePath)
        {
            if (filePath == null || !File.Exists(filePath))
                throw new ArgumentException("Invalid file path provided", nameof(filePath));

            using var stream = File.OpenRead(filePath);
            using var md5 = MD5.Create();
            using var writer = new StreamWriter(new MemoryStream());
            byte[] buffer = new byte[BUFFER_SIZE];

            while (true)
            {
                int readBytes = stream.Read(buffer, 0, BUFFER_SIZE);
                if (readBytes == 0) break;

                md5.TransformBlock(buffer, 0, readBytes, null, 0);
            }

            md5.TransformFinalBlock(Array.Empty<byte>(), 0, 0);

            byte[] hash = md5.Hash;
            return BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }
    }
}
