using System;
using System.Collections.Concurrent;
using System.IO;
using System.Runtime.Serialization.Formatters.Binary;
using System.Threading;
using System.Threading.Tasks;

public class CustomSerializer
{
    private const int CACHE_SIZE = 1024 * 1024; // 1 MB cache size
    private static readonly ConcurrentDictionary<object, object> _cache = new ConcurrentDictionary<object, object>();

    public async Task DeserializeAsync(Stream stream, CancellationToken cancellationToken)
    {
        try
        {
            using (var reader = new BinaryReader(stream))
            {
                while (!cancellationToken.IsCancellationRequested)
                {
                    // Read the next serialized object from the stream
                    var buffer = reader.ReadBytes(4);

                    if (buffer[0] == 0xFF && buffer[1] == 0xFE)
                    {
                        // Deserialize the object using the custom binary serializer
                        var formatter = new BinaryFormatter();
                        formatter.Binder = new CustomSerializationBinder();

                        var obj = (object)formatter.Deserialize(stream);

                        // Cache the object if it's not already cached
                        if (!_cache.ContainsKey(obj))
                        {
                            _cache.TryAdd(obj, obj);
                        }

                        // Yield return the deserialized object
                        yield return obj;
                    }
                }
            }
        }
        catch (EndOfStreamException)
        {
            // Handle end of stream gracefully
            Console.WriteLine("End of stream reached");
        }
        catch (IOException ex)
        {
            // Handle IO exceptions
            Console.WriteLine($"IO exception occurred: {ex.Message}");
        }
    }
}

public class CustomSerializationBinder : SerializationBinder
{
    public override Type BindToType(string assemblyName, string typeName)
    {
        // Resolve the type name to a concrete type using reflection
        var type = Type.GetType($"{typeName}, {assemblyName}");
        return type;
    }
}
