package distributedgraphdb;

import java.util.*;
import java.util.concurrent.locks.*;
import org.apache.commons.lang3.tuple.Pair;

public class DistributedGraphDatabase {
    private final Map<String, Vertex> vertices = new HashMap<>();
    private final Map<Pair<String, String>, Edge> edges = new HashMap<>();
    private final ReentrantReadWriteLock lock = new ReentrantReadWriteLock();

    public void addVertices(int numVertices) {
        if (numVertices <= 0) {
            throw new IllegalArgumentException("Number of vertices must be positive");
        }

        // Acquire write lock to modify vertex map
        lock.writeLock().lock();

        try {
            for (int i = 0; i < numVertices; i++) {
                String id = UUID.randomUUID().toString();
                vertices.put(id, new Vertex(id));
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void addEdges(int numEdges) {
        if (numEdges <= 0) {
            throw new IllegalArgumentException("Number of edges must be positive");
        }

        // Acquire write lock to modify edge map
        lock.writeLock().lock();

        try {
            for (int i = 0; i < numEdges; i++) {
                String sourceId = UUID.randomUUID().toString();
                String targetId = UUID.randomUUID().toString();
                edges.put(Pair.of(sourceId, targetId), new Edge(sourceId, targetId));
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public void setProperty(String vertexId, String propertyKey, Object propertyValue) {
        // Acquire read lock to access vertex map
        lock.readLock().lock();

        try {
            Vertex vertex = vertices.get(vertexId);
            if (vertex == null) {
                throw new IllegalArgumentException("Vertex does not exist");
            }

            // Acquire write lock to modify vertex properties
            lock.writeLock().lock();

            try {
                vertex.properties.put(propertyKey, propertyValue);
            } finally {
                lock.writeLock().unlock();
            }
        } finally {
            lock.readLock().unlock();
        }
    }

