use std::fs;
use std::env;
use log::{info};

fn create_directory(path: &str) -> Result<bool, String> {
    // Environment variable management
    let env_var = match env::var("DIRECTORY") {
        Ok(val) => val,
        Err(_) => "".to_string(),
    };

    if !env_var.is_empty() && path != &env_var {
        return Err("Environment variable already set to a different directory.".to_string());
    }

    // Concurrency management
    let mutex = Mutex::new(());
    let guard = mutex.lock().unwrap();

    // Error handling
    if !path.contains('/') || path.starts_with('/') {
        return Err("Invalid directory path.".to_string());
    }

    match fs::create_dir_all(path) {
        Ok(_) => (),
        Err(e) => {
            if let Some(error) = e.raw_os_error() {
                return Err("Failed to create directory: ".to_string() + &format!("{}", error));
            } else {
                return Err("Failed to create directory.".to_string());
            }
        }
    };

    // Set environment variable
    env::set_var("DIRECTORY", path);

    info!("Directory created: {}", path);

    Ok(true)
}
