    class ConfigurationServiceClient
    {
        private readonly HttpClient _httpClient = new HttpClient();
        private readonly string _serviceEndpointUrl;

        public ConfigurationServiceClient(string serviceEndpointUrl)
        {
            _serviceEndpointUrl = serviceEndpointUrl;
        }

        public async Task<Configuration> GetLatestConfigurationAsync()
        {
            try
            {
                var response = await _httpClient.GetAsync(_serviceEndpointUrl);
                if (response.IsSuccessStatusCode)
                {
                    var jsonString = await response.Content.ReadAsStringAsync();
                    return JsonConvert.DeserializeObject<Configuration>(jsonString);
                }
            }
            catch (Exception e)
            {
                Console.WriteLine($"Error retrieving configuration: {e}");
            }
            return null;
        }
