using System;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;

namespace DataProcessor
{
    public class RandomValueGenerator
    {
        private readonly Random _random = new Random();
        private double _minInclusive, _maxExclusive;

        public RandomValueGenerator(double minInclusive, double maxExclusive)
        {
            _minInclusive = minInclusive;
            _maxExclusive = maxExclusive;
        }

        public void ResetRange(double minInclusive, double maxExclusive)
        {
            _minInclusive = minInclusive;
            _maxExclusive = maxExclusive;
        }

        public double GenerateRandomFloat()
        {
            return _random.NextDouble(_minInclusive, _maxExclusive);
        }

        public int GenerateRandomInteger()
        {
            return _random.Next((int)_minInclusive, (int)_maxExclusive);
        }

        public override string ToString()
        {
            return $"Range: [{_minInclusive}, {_maxExclusive})";
        }
    }

    public class DisjointPairsAnalyzer
    {
        private readonly RandomValueGenerator _random = new RandomValueGenerator(0, 1);
        private readonly UnionFind _unionFind;

        public DisjointPairsAnalyzer()
        {
            _unionFind = new UnionFind();
        }

        public int GetDisjointPairCount(int[] array)
        {
            var unionFind = _unionFind.Clone();
            for (var i = 0; i < array.Length - 1; i++)
            {
                var j = i + 1;
                if (array[i] == array[j]) continue; // Skip duplicates
                unionFind.Union(array[i], array[j]);
            }
            return unionFind.GetCount();
        }

        public int GetDisjointPairCount(IEnumerable<int> enumerable)
        {
            var unionFind = _unionFind.Clone();
            foreach (var item in enumerable)
            {
                if (!unionFind.Contains(item)) continue; // Skip duplicates
                unionFind.Union(item, _random.GenerateRandomInteger());
            }
            return unionFind.GetCount();
        }

        public override string ToString()
        {
            return $"Total processing time: {_unionFind.ProcessingTime}";
        }
    }

    public class UnionFind
    {
        private readonly Dictionary<int, HashSet<int>> _dict = new Dictionary<int, HashSet<int>>();
        private long _count;
        private Stopwatch _stopwatch;

        public void Union(int x, int y)
        {
            var xSet = GetOrCreateSet(x);
            var ySet = GetOrCreateSet(y);
            if (xSet == ySet) return; // Already unioned
            foreach (var item in xSet) _dict[item].UnionWith(ySet);
            _count--;
        }

        public void UnionAll(IEnumerable<int> enumerable)
        {
            var set = new HashSet<int>(enumerable);
            foreach (var item in set) GetOrCreateSet(item);
            _count = set.Count;
        }

        public int GetCount()
        {
            return (int)_count;
        }

        public bool Contains(int x)
        {
            return _dict.ContainsKey(x);
        }

        public HashSet<int> GetOrCreateSet(int x)
        {
            if (_dict.TryGetValue(x, out var set)) return set;
            set = new HashSet<int>();
            _dict[x] = set;
            return set;
        }

        public void Reset()
        {
            _count = 0;
            _stopwatch.Restart();
        }

        public long GetProcessingTime()
        {
            return _stopwatch.ElapsedMilliseconds;
        }

        public override string ToString()
        {
            return $"Total processing time: {GetProcessingTime()}";
        }
    }
}
