            // handle errors and race conditions in data retrieval
            printf("Error encountered while executing command: %s\n", strerror(error));
            break;
        }
    }

    // return result of operation
    if (num_populated == num_entries && num_executed == num_entries) {
        ret = 1;
    } else {
        ret = 0;
