#define MIN_VALUE INT_MIN
#define MAX_VALUE INT_MAX

// Struct to store the integer and its index in the array
struct Integer {
    int value;
    size_t index;
};

// Function to validate an integer and add it to the array if valid
void addInteger(int *array, size_t *size, size_t capacity, struct Integer *integer) {
    // Check if the integer is within the specified range
    if (integer->value < MIN_VALUE || integer->value > MAX_VALUE) {
        return;
    }

    // Add the integer to the array if it's not full
    if (*size < capacity) {
        array[*size] = integer->value;
        integer->index = *size++;
    } else {
        printf("Maximum number of integers reached. Ignoring %d\n", integer->value);
    }
}

// Function to find and print the largest integer in the array
void printLargestInteger(int *array, size_t size) {
    // Find the largest integer in the array
    int max = INT_MIN;
    for (size_t i = 0; i < size; ++i) {
        if (array[i] > max) {
            max = array[i];
        }
    }

    // Print the largest integer and its index in the array
    printf("Largest integer: %d (index %zu)\n", max, sizeof(struct Integer) * i);
}

// Main function to read integers from standard input and process them
int main() {
    int *array = malloc(sizeof(int) * MAX_INTEGERS);
    size_t size = 0;
    struct Integer integer;

    // Read the integers from standard input and validate them
    while (scanf("%d", &integer.value) == 1) {
        addInteger(array, &size, MAX_INTEGERS, &integer);
    }

    // Print the largest integer in the array
    printLargestInteger(array, size);

    // Clean up memory
    free(array);

    return 0;
}
