        uint32_t rand_ue_id = (uint32_t)rand();

        // Initialize the NAS PDU with a valid message and checksum
        (*messages)[i].nas.header.message_type = NFAPI_NAS_MESSAGE;
        (*messages)[i].nas.header.message_length = sizeof(NFAPI_NAS_PDU);
        (*messages)[i].nas.payload[0] = rand_ue_id & 0xFF;
        (*messages)[i].nas.payload[1] = (rand_ue_id >> 8) & 0xFF;
        (*messages)[i].nas.payload[2] = (rand_ue_id >> 16) & 0xFF;
        (*messages)[i].nas.payload[3] = (rand_ue_id >> 24) & 0xFF;
        (*messages)[i].nas.payload[4] = i % 256;
        (*messages)[i].nas.payload[5] = (i >> 8) % 256;
        (*messages)[i].nas.payload[6] = (i >> 16) % 256;
        (*messages)[i].nas.payload[7] = (i >> 24) % 256;
        (*messages)[i].nas.payload_length = sizeof(NFAPI_NAS_PDU);
        (*messages)[i].nas.checksum = calculate_integrity_algorithm((*messages)[i].nas.payload, sizeof(NFAPI_NAS_PDU));
    }
}

void find_largest_integer(int num_integers, int* input_data, int* largest_integer) {
    // Find the largest integer in the array using a helper function
    *largest_integer = max_integer(input_data, num_integers);
}
