import os
import json
import requests

# Define environment variables for each environment
dev_env = {
    "database": {"host": "localhost", "port": 5432},
    "api_endpoints": ["http://localhost:8000"],
    "caching_strategy": "none",
    "logging_level": "info"
}
test_env = {
    "database": {"host": "localhost", "port": 5432},
    "api_endpoints": ["http://localhost:8000"],
    "caching_strategy": "memory",
    "logging_level": "debug"
}
prod_env = {
    "database": {"host": "db.example.com", "port": 5432},
    "api_endpoints": ["https://api.example.com"],
    "caching_strategy": "redis",
    "logging_level": "info"
}

# Define dependencies between server components
dependencies = {
    "database": ["api_endpoints"],
    "api_endpoints": ["caching_strategy"],
    "caching_strategy": ["logging_level"]
}

# Define the configuration for each environment
configs = {
    "dev": dev_env,
    "test": test_env,
    "prod": prod_env
}

def generate_configuration(environment):
    # Validate the environment variable is a valid key in the configs dictionary
    if environment not in configs:
        raise ValueError("Invalid environment")

    # Create an empty configuration object
    config = {}

    # Iterate over the dependencies and populate the configuration
    for component, deps in dependencies.items():
        for dep in deps:
            if dep not in configs[environment]:
                raise ValueError("Dependency missing")

        config[component] = configs[environment][component]

    # Validate the configuration is valid
    validate_configuration(config)

    # Write the configuration to disk
    with open(f"{environment}.json", "w") as f:
        json.dump(config, f, indent=4)

    print(f"Configuration for {environment} has been generated.")

def validate_configuration(config):
    # Check if the database connection is valid
    try:
        conn = requests.get("http://{}:{}/".format(config["database"]["host"], config["database"]["port"]))
        if conn.status_code != 200:
            raise ValueError("Invalid database connection")
    except Exception as e:
        raise ValueError("Invalid database connection") from e

    # Check if the API endpoints are valid
    for endpoint in config["api_endpoints"]:
        try:
            conn = requests.get(endpoint)
            if conn.status_code != 200:
                raise ValueError("Invalid API endpoint")
        except Exception as e:
            raise ValueError("Invalid API endpoint") from e

    # Check if the caching strategy is valid
    if config["caching_strategy"] not in ["none", "memory", "redis"]:
        raise ValueError("Invalid caching strategy")

    # Check if the logging level is valid
    if config["logging_level"] not in ["debug", "info", "warning", "error"]:
        raise ValueError("Invalid logging level")

# Handle potential network issues when querying external services for configuration details
try:
    generate_configuration(os.environ.get("ENVIRONMENT"))
except requests.exceptions.ConnectionError as e:
    print("Network error occurred while generating configuration.")
    raise ValueError("Invalid environment") from e

# Handle potential runtime errors
try:
    generate_configuration("invalid")
except ValueError as e:
    print(e)
