struct dns_result *dns_resolve(char *hostname) {
    // Check if the hostname is valid and has not been queried before
    if (is_valid_hostname(hostname)) {
        // Check if there are any concurrent queries, and if so, wait for them to complete
        while (num_concurrent_queries >= MAX_CONCURRENT_QUERIES) {
            usleep(DNS_QUERY_INTERVAL);
        }

        // Increment the number of concurrent queries
        num_concurrent_queries++;

        // Create a new DNS query and add it to the list of queries
        struct dns_query *dns_query = malloc(sizeof(struct dns_query));
        dns_query->hostname = hostname;
        dns_query->timeout = 10; // set default timeout to 10 seconds
        dns_queries[num_concurrent_queries - 1] = dns_query;

        // Perform DNS resolution using the standard library functions
        struct addrinfo hints, *res;
        memset(&hints, 0, sizeof(hints));
        hints.ai_family = AF_UNSPEC;
        hints.ai_socktype = SOCK_STREAM;
        if (getaddrinfo(hostname, NULL, &hints, &res) != 0) {
            fprintf(stderr, "DNS resolution failed for %s\n", hostname);
            return NULL;
        }

        // Create a new DNS result and store the IP address in it
        struct dns_result *dns_result = malloc(sizeof(struct dns_result));
        dns_result->addr = res->ai_addr;
        dns_result->len = res->ai_addrlen;

        // Decrement the number of concurrent queries and remove the DNS query from the list
        num_concurrent_queries--;
        free(dns_queries[num_concurrent_queries]);

        return dns_result;
    } else {
        fprintf(stderr, "Invalid hostname: %s\n", hostname);
        return NULL;
    }
}

