}

// Function to implement a mechanism to limit the number of concurrent DNS queries to prevent resource exhaustion
void limit_concurrent_queries() {
    // Check if there are any concurrent queries and if so, wait for them to complete
    while (num_concurrent_queries >= THRESHOLD_PER_SEC) {
        usleep(DNS_QUERY_INTERVAL);
