// Load the cipher settings from a configuration file
int loadCipherSettings(char *filename) {
    int ret = 0;

    // Open the configuration file and read its contents
    FILE *file = fopen(filename, "r");
    if (file == NULL) {
        perror("fopen");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), file)) {
        // Ignore empty lines and comments
        if (line[0] == '\n' || line[0] == '#') continue;

        // Split the line into its components
        char *token = strtok(line, " ");
        int keySize = atoi(token);
        token = strtok(NULL, " ");
        int blockSize = atoi(token);
        token = strtok(NULL, " ");
        char *iv = (char *)malloc(sizeof(char) * 16);
        memcpy(iv, token, sizeof(char) * 16);

        // Add the new cipher suite to the list of supported suites
        struct CipherSuiteData *suite = malloc(sizeof(struct CipherSuiteData));
        suite->type = (enum CipherSuite)keySize;
        suite->config.mode = blockSize;
        suite->config.keySize = keySize;
        suite->config.blockSize = blockSize;
        suite->config.iv = iv;

        // Add the new cipher suite to the list of supported suites
        if (cipherSuiteList == NULL) {
            cipherSuiteList = malloc(sizeof(struct CipherSuiteData));
            cipherSuiteList[0] = *suite;
        } else {
            struct CipherSuiteData **tmp = realloc(cipherSuiteList, sizeof(struct CipherSuiteData) * (numCipherSuites + 1));
            if (tmp == NULL) {
                perror("realloc");
                free(suite);
                return -1;
            }
            cipherSuiteList = tmp;
            cipherSuiteList[numCipherSuites] = *suite;
        }
        numCipherSuites++;
    }

    // Close the configuration file
    fclose(file);

    return ret;
}

// Dynamically select and initialize the appropriate cipher suite based on the loaded configuration
int initCipherSuite(struct CipherSuiteData *suite) {
    int ret = 0;

    // Check if the selected cipher suite is supported by the module
    if (suite->type >= AES_128_CBC && suite->type <= CAST5_CBC) {
        cipherSuite = suite;
        return ret;
    }

    // Use NULL cipher suite if no suitable configuration is found
    cipherSuite = &nullCipherSuite;
    return -1;
}

// Encrypt or decrypt the given data using the selected cipher suite
int encryptDecrypt(char *data, int mode) {
    int ret = 0;

    // Check if the selected cipher suite is valid
    if (cipherSuite == NULL || cipherSuite->type == NULL_CIPHER) return -1;

    // Create an OpenSSL EVP context for encryption or decryption
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (ctx == NULL) {
        perror("EVP_CIPHER_CTX_new");
        return -1;
    }

    // Initialize the encryption or decryption operation based on the selected cipher suite
    if (mode == ENCRYPTION) {
