    }

    // Set the key and initialization vector for the encryption or decryption operation
    unsigned char *key = (unsigned char *)malloc(sizeof(char) * 32);
    memcpy(key, cipherSuite->config.iv, sizeof(char) * 16);
    EVP_CIPHER_CTX_set_key_length(ctx, cipherSuite->config.keySize / 8);
    EVP_CipherInit(ctx, NULL, key, NULL, sizeof(char) * 16);

