    char *dataPtr = data;
    int len = strlen(data);
    while (len > 0) {
        unsigned char *outBuf = (unsigned char *)malloc(sizeof(char) * blockSize);
        EVP_EncryptUpdate(ctx, outBuf, &blockSize, (const unsigned char *)dataPtr, len);
        dataPtr += blockSize;
        len -= blockSize;
    }

    // Check if the encryption or decryption operation was successful
    if (!EVP_EncryptFinal(ctx, NULL, 0)) {
        perror("EVP_EncryptFinal");
        ret = -1;
    }

    // Clean up memory and return the encrypted/decrypted data
    free(key);
    EVP_CIPHER_CTX_free(ctx);
    return ret;
}

