typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Global variables
static NFAPI_CRC_INDICATION_PDU_T* crcIndicationList = NULL;
static size_t numElements = 0;
static pthread_mutex_t listMutex;

void initCrcIndicationList() {
    // Initialize the mutex for thread-safe access to the list
    pthread_mutex_init(&listMutex, NULL);
}

void destroyCrcIndicationList() {
    // Free the memory allocated for the list
    free(crcIndicationList);
}

bool addCrcIndicationPduToList(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Acquire the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    bool success = true;
    // Check if the RNTI is already in the list
    for (size_t i = 0; i < numElements; i++) {
        if (crcIndicationList[i].RNTI == pdu->RNTI) {
            success = false;
            break;
        }
    }

    if (success) {
        // Reallocate the memory for the list to make room for the new PDU
        crcIndicationList = realloc(crcIndicationList, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (numElements + 1));
        if (!crcIndicationList) {
            success = false;
            printf("Error: Unable to allocate memory for CRC indication list\n");
        } else {
            // Add the new PDU to the list
            crcIndicationList[numElements++] = *pdu;
        }
    }

    // Release the mutex
    pthread_mutex_unlock(&listMutex);

    return success;
}

void removeCrcIndicationPduFromList(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Acquire the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Find the index of the PDU in the list
    size_t index = 0;
    for (size_t i = 0; i < numElements; i++) {
        if (crcIndicationList[i].RNTI == pdu->RNTI) {
            index = i;
            break;
        }
    }

    // Remove the PDU from the list and update the number of elements
    if (index < numElements) {
        memmove(&crcIndicationList[index], &crcIndicationList[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (numElements - index));
        numElements--;
    }

    // Release the mutex
    pthread_mutex_unlock(&listMutex);
}

void clearCrcIndicationList() {
    // Acquire the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    // Release all memory allocated for the list
    free(crcIndicationList);
    crcIndicationList = NULL;
    numElements = 0;

    // Release the mutex
    pthread_mutex_unlock(&listMutex);
}

void printCrcIndicationList() {
    // Acquire the mutex to ensure thread-safe access to the list
    pthread_mutex_lock(&listMutex);

    printf("CRC Indication List (%lu elements):\n", numElements);
    for (size_t i = 0; i < numElements; i++) {
        printf("- RX_UE_INFORMATION_TAG: %u\n", crcIndicationList[i].RX_UE_INFORMATION_TAG);
        printf("- RNTI: %u\n", crcIndicationList[i].RNTI);
        printf("- CRCFLAG: %u\n", crcIndicationList[i].CRCFLAG);
    }

    // Release the mutex
    pthread_mutex_unlock(&listMutex);
}
