// C header file
#ifndef LIST_HASH_TABLE_H
#define LIST_HASH_TABLE_H

#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>

// Custom hash function for Item structure
uint64_t item_hash(Item* item) {
    uint64_t hash = 0;
    // Use a combination of identifier and timestamp as the hash key
    hash += item->id * 1234567891234567;
    hash += item->timestamp * 9876543219876543;
    return hash;
}

// Item structure definition
typedef struct {
    uint64_t id;
    uint64_t timestamp;
    double value;
} Item;

// List and hash table data structures
typedef struct {
    Item* items; // Array of items
    size_t capacity; // Current capacity of the list
    size_t count; // Number of items in the list
} List;

typedef struct {
    List* lists; // Array of lists
    size_t num_lists; // Number of lists
    size_t hash_size; // Size of the hash table
    Item** hash_table; // Hash table for efficient lookups
} HashTable;

// Function to create a new list and initialize it with capacity 1024.
List* new_list() {
    List* list = (List*)malloc(sizeof(List));
    if (!list) {
        perror("Failed to allocate memory for list");
        return NULL;
    }
    list->items = (Item*)malloc(1024 * sizeof(Item));
    if (!list->items) {
        perror("Failed to allocate memory for list items");
        free(list);
        return NULL;
    }
    list->capacity = 1024;
    list->count = 0;
    return list;
}

// Function to create a new hash table and initialize it with size 1024.
HashTable* new_hash_table() {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HashTable));
    if (!hash_table) {
        perror("Failed to allocate memory for hash table");
        return NULL;
    }
    hash_table->lists = (List*)malloc(1024 * sizeof(List));
    if (!hash_table->lists) {
        perror("Failed to allocate memory for lists in hash table");
        free(hash_table);
        return NULL;
    }
    hash_table->num_lists = 1024;
    hash_table->hash_size = 1024 * sizeof(Item**);
    hash_table->hash_table = (Item**)malloc(hash_table->hash_size);
    if (!hash_table->hash_table) {
        perror("Failed to allocate memory for hash table");
        free(hash_table->lists);
        free(hash_table);
        return NULL;
    }
    // Initialize hash table
    for (int i = 0; i < hash_table->num_lists; i++) {
        hash_table->hash_table[i] = NULL;
    }
    return hash_table;
}

// Function to add an item to the list and hash table.
bool add_item(Item* item, HashTable* hash_table) {
    // Check if the list is full
    if (hash_table->lists[0].count == hash_table->lists[0].capacity) {
        // Double the capacity of the list and resize the hash table accordingly
        for (int i = 0; i < hash_table->num_lists; i++) {
            hash_table->lists[i].capacity *= 2;
            hash_table->hash_table = (Item**)realloc(hash_table->hash_table, hash_table->hash_size);
            if (!hash_table->hash_table) {
                perror("Failed to resize hash table");
                return false;
            }
        }
    }
    // Add the item to the list and hash table
    List* list = &(hash_table->lists[0]);
    Item** hash_slot = &(hash_table->hash_table[item_hash(item)]);
    if (*hash_slot == NULL) {
        // Create a new slot in the hash table if none exists for this item
        *hash_slot = (Item*)malloc(sizeof(Item));
        if (!*hash_slot) {
            perror("Failed to allocate memory for hash slot");
            return false;
        }
    } else {
        // Check if the list already contains an item with this identifier
        Item* existing = *hash_slot;
        while (existing->next != NULL) {
            if (existing->id == item->id) {
                // Remove the duplicate item from the list and hash table
                existing->prev->next = existing->next;
                existing->next->prev = existing->prev;
                *hash_slot = existing->next;
                free(existing);
                break;
            }
            existing = existing->next;
        }
    }
    // Add the item to the list and hash table
    Item* new_item = (Item*)malloc(sizeof(Item));
    if (!new_item) {
        perror("Failed to allocate memory for new item");
        return false;
    }
    memcpy(new_item, item, sizeof(Item));
    new_item->next = NULL;
    new_item->prev = list->tail;
    if (list->head == NULL) {
        // Add the first item to the list
        list->head = new_item;
        list->tail = new_item;
    } else {
        // Add the item to the end of the list
        list->tail->next = new_item;
        list->tail = new_item;
    }
    *hash_slot = new_item;
    hash_table->lists[0].count++;
    return true;
}

// Function to remove an item from the list and hash table.
bool remove_item(Item* item, HashTable* hash_table) {
    // Check if the item is in the hash table
    Item** hash_slot = &(hash_table->hash_table[item_hash(item)]);
    if (*hash_slot == NULL) {
        return false;
    }
    List* list = &(hash_table->lists[0]);
    // Check if the item is in the list
    Item* existing = *hash_slot;
    while (existing != NULL && existing->id != item->id) {
        existing = existing->next;
    }
    if (existing == NULL) {
        return false;
    }
    // Remove the item from the list and hash table
    if (existing->prev != NULL) {
        existing->prev->next = existing->next;
    } else {
        list->head = existing->next;
    }
    if (existing->next != NULL) {
        existing->next->prev = existing->prev;
    } else {
        list->tail = existing->prev;
    }
    free(existing);
    *hash_slot = NULL;
    hash_table->lists[0].count--;
    return true;
}

// Function to find an item in the list and hash table.
bool find_item(Item* item, HashTable* hash_table) {
    // Check if the item is in the hash table
    Item** hash_slot = &(hash_table->hash_table[item_hash(item)]);
    if (*hash_slot == NULL) {
        return false;
    }
    List* list = &(hash_table->lists[0]);
    // Check if the item is in the list
    Item* existing = *hash_slot;
    while (existing != NULL && existing->id != item->id) {
        existing = existing->next;
    }
    return existing != NULL;
}

// Function to print an item from the list.
void print_item(Item* item, HashTable* hash_table) {
    // Check if the item is in the hash table
    Item** hash_slot = &(hash_table->hash_table[item_hash(item)]);
    if (*hash_slot == NULL) {
        printf("Item not found\n");
        return;
    }
    List* list = &(hash_table->lists[0]);
    // Check if the item is in the list
    Item* existing = *hash_slot;
    while (existing != NULL && existing->id != item->id) {
        existing = existing->next;
    }
    if (existing == NULL) {
        printf("Item not found\n");
        return;
    }
    // Print the item
    printf("Name: %s\n", existing->name);
    printf("Age: %d\n", existing->age);
}

int main() {
    HashTable* hash_table = new_hash_table();
    if (!hash_table) {
        perror("Failed to create hash table");
        return 1;
    }
    Item item1 = {"Alice", 25};
    Item item2 = {"Bob", 30};
    Item item3 = {"Charlie", 40};
    // Add the items to the list and hash table
    add_item(&item1, hash_table);
    add_item(&item2, hash_table);
    add_item(&item3, hash_table);
    // Remove an item from the list and hash table
    remove_item(&item2, hash_table);
    // Find an item in the list and hash table
    find_item(&item1, hash_table);
    find_item(&item2, hash_table);
    find_item(&item3, hash_table);
    // Print the items from the list
    print_item(&item1, hash_table);
    print_item(&item2, hash_table);
    print_item(&item3, hash_table);
    return 0;
}']

