#include <stdlib.h>
#include <time.h>

struct record {
    int key;
};

struct graph {
    struct record** vertices;
    int num_vertices;
    int* edges;
    int num_edges;
};

struct graph* init_graph(int num_vertices, int num_edges) {
    struct graph* graph = malloc(sizeof(struct graph));
    if (!graph) return NULL;

    graph->vertices = malloc(num_vertices * sizeof(struct record*));
    if (!graph->vertices) {
        free(graph);
        return NULL;
    }

    graph->edges = malloc(num_edges * sizeof(int));
    if (!graph->edges) {
        free(graph->vertices);
        free(graph);
        return NULL;
    }

    for (int i = 0; i < num_vertices; i++) {
        graph->vertices[i] = malloc(sizeof(struct record));
        if (!graph->vertices[i]) {
            for (int j = 0; j < i; j++) {
                free(graph->vertices[j]);
            }
            free(graph->edges);
            free(graph->vertices);
            free(graph);
            return NULL;
        }
    }

    for (int i = 0; i < num_edges; i++) {
        graph->edges[i] = -1;
    }

    graph->num_vertices = num_vertices;
    graph->num_edges = num_edges;

    return graph;
}

void add_vertex(struct graph* graph, int key) {
    if (graph->num_vertices >= graph->num_edges) {
        // resize the array of edges to accommodate new vertex
        graph->edges = realloc(graph->edges, graph->num_vertices * 2);
        if (!graph->edges) return;
    }

    struct record* vertex = malloc(sizeof(struct record));
    if (!vertex) {
        free(vertex);
        return;
    }

    vertex->key = key;

    graph->vertices[graph->num_vertices] = vertex;
    graph->num_vertices++;
}

void add_edge(struct graph* graph, int from, int to) {
    if (from >= graph->num_vertices || to >= graph->num_vertices) return;

    graph->edges[from] = to;
}

void set_vertex_properties(struct graph* graph, int vertex_index, const char** property_names, const char** property_values) {
    if (graph->num_vertices <= vertex_index || !property_names || !property_values) return;

    struct record* vertex = graph->vertices[vertex_index];

    for (int i = 0; i < graph->num_edges && property_names[i] != NULL && property_values[i] != NULL; i++) {
        const char* name = property_names[i];
        const char* value = property_values[i];

        if (strcmp(name, "name") == 0) {
            vertex->key = atoi(value);
        } else {
            // ignore unrecognized properties
        }
    }
}

void load_graph_properties(struct graph* graph, const char* filepath) {
    FILE* fp = fopen(filepath, "r");
    if (!fp) return;

    while (fscanf(fp, "%d %d", &from, &to) != EOF) {
        add_edge(graph, from, to);
    }

    fclose(fp);
}
```']

