    // Allocate memory from the custom pool
    struct memory_pool* pool = malloc(total_size);
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for pool\n");
        exit(1);
    }

    // Initialize the first free block in the pool
    pool->next = (void*)((char*)pool + sizeof(struct memory_pool));
    pool->size = total_size - sizeof(struct memory_pool);

    // Create and initialize each data structure
    for (int i = 0; i < num_elements; ++i) {
