// Custom Item structure for the list
typedef struct {
  uint32_t id;
  uint64_t timestamp;
  float value;
} Item;

// Rolling hash algorithm for efficient lookups and collision resolution
uint32_t get_hash(const char* key, size_t len) {
  // Implement a simple rolling hash function
  // that takes the last 4 characters of the ID as the hash value
  uint32_t hash = 0;
  for (int i = len - 1; i >= len - 4; i--) {
    hash = (hash << 8) | key[i];
  }
  return hash % 1000;
}

// LRU mechanism with fine-grained locking for thread safety
#define MAX_SIZE 10000 // maximum size of the list
Item* items[MAX_SIZE];
int lru_index = -1; // least recently used index
pthread_mutex_t mutex;

// Memory pool allocator for efficient memory management
void* mempool = NULL;
size_t mempool_size = 0;

// Function to manage the list of items
void manage_items(Item** items, size_t count) {
  // Implement LRU eviction with a rolling hash table
  // that minimizes collisions under various workload patterns
  uint32_t hashes[count];
  for (int i = 0; i < count; i++) {
    Item* item = items[i];
    hashes[i] = get_hash(item->id, strlen(item->id));
  }

  // Sort the hash values in ascending order
  qsort(hashes, count, sizeof(uint32_t), compare_ints);

  // Evict LRU items until size limit is reached
  for (int i = 0; i < count && lru_index < MAX_SIZE - 1; i++) {
    uint32_t hash = hashes[i];
    Item* item = get_item(hash);
    if (item) {
      // Remove the item from the list and deallocate its memory
      remove_item(item);
      lru_index--;
    } else {
      // If the hash is not found, it means that the item has already been evicted
      // In this case, we can skip this iteration and move on to the next one
      continue;
    }
  }

  // Add the new items to the list and allocate their memory if necessary
  for (int i = 0; i < count; i++) {
    Item* item = items[i];
    uint32_t hash = hashes[i];
    add_item(item, hash);
  }
}

// Add an item to the list and allocate its memory if necessary
void add_item(Item* item, uint32_t hash) {
  // Allocate memory for the item if it does not exist
  Item* new_item = get_item(hash);
  if (!new_item) {
    pthread_mutex_lock(&mutex);
    int index = lru_index + 1;
    if (index < MAX_SIZE) {
      // Allocate memory for the item using the memory pool allocator
      size_t mem_size = sizeof(Item);
      void* new_mem = mempool + mempool_size;
      if (new_mem) {
        new_item = new_mem;
        mempool_size += mem_size;
      } else {
        // If the memory pool is full, allocate a new block of memory for the item
        new_item = malloc(sizeof(Item));
      }
    }
    pthread_mutex_unlock(&mutex);
  }

  // Add the item to the list and update its position in the LRU index
  if (new_item) {
    items[index] = new_item;
    lru_index++;
  }
}

// Remove an item from the list and deallocate its memory
void remove_item(Item* item) {
  // Find the index of the item in the list
  int index = get_item_index(item);
  if (index != -1) {
    pthread_mutex_lock(&mutex);
    items[index] = NULL;
    lru_index--;
    pthread_mutex_unlock(&mutex);
    // Deallocate the item's memory if necessary
    if (item != new_mem) {
      free(item);
    } else {
      mempool_size -= sizeof(Item);
    }
  }
}

// Get an item from the list by its hash value
Item* get_item(uint32_t hash) {
  // Iterate over the list and check for a matching hash value
  for (int i = 0; i < MAX_SIZE; i++) {
    Item* item = items[i];
    if (item && item->hash == hash) {
      return item;
    }
  }
  return NULL;
}

// Get the index of an item in the list by its pointer
int get_item_index(Item* item) {
  // Iterate over the list and check for a matching pointer
  for (int i = 0; i < MAX_SIZE; i++) {
    Item* curr_item = items[i];
    if (curr_item == item) {
      return i;
    }
  }
  return -1;
}

// Comparison function for sorting hash values in ascending order
int compare_ints(const void* a, const void* b) {
  uint32_t hash_a = *(uint32_t*)a;
  uint32_t hash_b = *(uint32_t*)b;
  return hash_a - hash_b;
}
```

This code implements a simple cache that stores `Item` objects in a list. The cache has a fixed size and uses the LRU (Least Recently Used) algorithm to determine which items to evict when the cache is full. The cache also supports adding, removing, and retrieving items from the list.

