    for (i = 0; i < num_items; ++i) {
        collection[i].name = strndup(input, i + 1);
        if (collection[i].name == NULL) {
            // Handle memory allocation failure
            return NULL;
        }
    }

    // Initialize each item's integer value to a random number within a specified range
    srand(time(NULL));
    for (i = 0; i < num_items; ++i) {
        collection[i].value = rand() % 10 + 1;
    }

    // Return the initialized collection
    return collection;
}

// Define a function to resize the collection if necessary
void resize_collection(Item** collection, int* num_items) {
    // Check if the current allocation is sufficient
    if (*num_items < *collection->length) {
        // Allocate more memory for the collection
        Item* new_collection = realloc(*collection, 2 * *num_items * sizeof(Item));
        if (new_collection == NULL) {
            // Handle memory allocation failure
            return;
        }

        // Update the pointer to the collection and the number of items
        *collection = new_collection;
        *num_items *= 2;
    }
}

// Define a function to add an item to the collection
void add_item(Item** collection, int* num_items, const char* name, int value) {
    // Check if the current allocation is sufficient
    if (*num_items >= *collection->length) {
        resize_collection(collection, num_items);
    }

    // Add the item to the collection
    Item new_item = {name, value};
    (*collection)[*num_items] = new_item;
    ++(*num_items);
}

// Define a function to remove an item from the collection
void remove_item(Item** collection, int* num_items, const char* name) {
    // Find the index of the item to be removed
    int i = 0;
    while (i < *num_items && strcmp((*collection)[i].name, name) != 0) {
        ++i;
    }

    // Check if the item was found
    if (i == *num_items) {
        return;
    }

    // Remove the item from the collection
    for (int j = i; j < *num_items - 1; ++j) {
        (*collection)[j] = (*collection)[j + 1];
    }

    // Decrement the number of items and reallocate memory if necessary
    --(*num_items);
    resize_collection(collection, num_items);
}
