    pdu->CRC_INDICATION_REL8_TAG = read_uint8_t(binary_data, &offset);
    pdu->CRCFLAG = read_uint8_t(binary_data, &offset);

    // Return the deserialized structure
    return pdu;
}

// Function to serialize an NFAPI_CRC_INDICATION_PDU_T structure into a binary data stream
char *serialize_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    // Check if the input PDU is NULL
    if (pdu == NULL) {
        return NULL;
    }

    // Create a new binary data stream to hold the serialized data
    char *data = (char *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (data == NULL) {
        // Handle memory allocation failure
        printf("Error: Failed to allocate memory for the CRC indication PDU\n");
        return NULL;
    }

    // Serialize the input PDU into the new binary data stream
    uint32_t offset = 0;
    write_uint16_be(pdu->RX_UE_INFORMATION_TAG, data, &offset);
    write_uint16_be(pdu->RNTI, data, &offset);
    write_uint8_t(pdu->CRC_INDICATION_REL8_TAG, data, &offset);
    write_uint8_t(pdu->CRCFLAG, data, &offset);

    // Return the serialized binary data stream
    return data;
}

// Function to clear the CRC indication list and reset all allocated structures to a default state
void clear_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T **list) {
    // Check if the list is NULL or has no elements
    if (*list == NULL || (*list)->count == 0) {
        return;
    }

    // Free all allocated structures within the list
    for (uint16_t i = 0; i < (*list)->count; i++) {
        free((*list)[i]);
    }

    // Reset the count of the list to 0
    (*list)->count = 0;
}

