import requests
from typing import Dict, List
from itertools import chain

class APICaller:
    def __init__(self, api_url: str):
        self.api_url = api_url

    def call(self, params: Dict[str, any] = None) -> requests.Response:
        response = requests.get(self.api_url, params=params)
        if not response.ok:
            raise Exception("Failed to fetch data from API")
        return response

    def call_with_retry(self, params: Dict[str, any] = None, retries: int = 3) -> requests.Response:
        for i in range(retries):
            try:
                response = self.call(params)
                return response
            except Exception as e:
                print(f"Failed to fetch data from API: {e}")
                continue
        raise Exception("Max retries exceeded")

    def get_data(self, params: Dict[str, any] = None) -> List[Dict[str, any]]:
        response = self.call_with_retry(params)
        data = response.json()
        return data["data"]

class ConfigurationUpdater:
    def __init__(self, config_path: str):
        self.config_path = config_path

    def update_config(self, params: Dict[str, any]) -> None:
        with open(self.config_path) as f:
            config = json.load(f)

        for key, value in params.items():
            if key not in config:
                raise Exception(f"Invalid placeholder name: {key}")

            try:
                config[key] = value
            except ValueError as e:
                print(f"Invalid data type for {key}: {e}")

        with open(self.config_path, "w") as f:
            json.dump(config, f)

    def load_config(self) -> Dict[str, any]:
        with open(self.config_path) as f:
            config = json.load(f)
        return config

class APIManager:
    def __init__(self, api_urls: List[str], params: Dict[str, any]):
        self.api_urls = api_urls
        self.params = params

    def fetch_data(self) -> Dict[str, any]:
        data = {}
        for url in self.api_urls:
            api_caller = APICaller(url)
            try:
                response = api_caller.call_with_retry()
                data[url] = response.json()["data"]
            except Exception as e:
                print(f"Failed to fetch data from {url}: {e}")
        return data

class ConfigurationBuilder:
    def __init__(self, api_urls: List[str], params: Dict[str, any]):
        self.api_urls = api_urls
        self.params = params

    def build(self) -> Dict[str, any]:
        config = {}
        for url in self.api_urls:
            api_caller = APICaller(url)
            try:
                response = api_caller.call_with_retry()
                data = response.json()["data"]
            except Exception as e:
                print(f"Failed to fetch data from {url}: {e}")
            else:
                config[url] = data
        return config

def update_config(params: Dict[str, any], config_path: str) -> None:
    updater = ConfigurationUpdater(config_path)
    updater.update_config(params)

def load_config(config_path: str) -> Dict[str, any]:
    loader = ConfigurationLoader(config_path)
    return loader.load_config()

if __name__ == "__main__":
    api_urls = ["https://api1.com", "https://api2.com"]
    params = {
        "placeholder1": "value1",
        "placeholder2": "value2"
    }

    # Fetch data from APIs and update configuration file
    manager = APIManager(api_urls, params)
    config = manager.fetch_data()
    updater = ConfigurationUpdater("config.json")
    updater.update_config(config)

    # Load updated configuration
    config = load_config("config.json")
