// Constants
#define MAX_FRAMES 1024 // Maximum number of frames to store in the array
#define UPDATE_INTERVAL 5 // Interval between updates (in seconds)

// Structures
typedef struct {
    LTE_PHY_RX_HEADER header;
    float signal_strength;
    int num_symbols;
    LTE_PHY_RX_SYMBOL symbols[];
} LTE_PHY_RX_FRAME;

// Global variables
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER; // Lock for synchronizing access to the array
LTE_PHY_RX_FRAME frames[MAX_FRAMES]; // Array of frames
int num_frames = 0; // Number of valid frames in the array
time_t last_update = time(NULL); // Timestamp of the last update
float avg_signal_strength = 0.0f; // Average signal strength over the last UPDATE_INTERVAL seconds

// Function to initialize and manage the dynamic array of LTE_PHY_RX_FRAME structures
void init_frames() {
    for (int i = 0; i < MAX_FRAMES; i++) {
        frames[i].header.valid = false; // Mark all frames as invalid
    }
}

// Function to add a new frame to the dynamic array
void add_frame(LTE_PHY_RX_HEADER header, float signal_strength) {
    pthread_mutex_lock(&lock);
    int index = num_frames % MAX_FRAMES; // Index of the next available slot in the array
    frames[index].header = header; // Store the new frame header
    frames[index].signal_strength = signal_strength; // Store the new signal strength
    frames[index].num_symbols = 0; // Initialize the number of symbols to zero
    num_frames++; // Increment the number of valid frames
    pthread_mutex_unlock(&lock);
}

// Function to update the signal strength indicator based on recent symbol data
void update_signal_strength() {
    time_t current = time(NULL);
    if (current - last_update >= UPDATE_INTERVAL) { // If the update interval has elapsed
        avg_signal_strength = 0.0f; // Reset the average signal strength
        for (int i = 0; i < num_frames; i++) { // Iterate over all valid frames
            if (frames[i].header.valid) { // If the frame is valid
                avg_signal_strength += frames[i].signal_strength; // Add the signal strength to the average
            }
        }
        avg_signal_strength /= num_frames; // Calculate the average signal strength
        last_update = current; // Update the timestamp of the last update
    }
}

// Function to retrieve frames based on certain criteria such as signal strength or time of reception
void get_frames(float signal_threshold, time_t start_time, time_t end_time) {
    pthread_mutex_lock(&lock); // Lock the access to the array
    int num_valid_frames = 0; // Initialize the number of valid frames to zero
    for (int i = 0; i < num_frames; i++) { // Iterate over all frames
        if (frames[i].header.valid) { // If the frame is valid
            float signal_strength = frames[i].signal_strength; // Get the current signal strength
            time_t timestamp = frames[i].header.timestamp; // Get the timestamp of the current frame
            if (signal_threshold > 0) { // If a signal threshold is specified
                if (signal_strength >= signal_threshold) { // Check if the signal strength meets the threshold
                    num_valid_frames++; // Increment the number of valid frames
                }
            } else { // No signal threshold is specified
                num_valid_frames++; // Increment the number of valid frames
            }
            if (start_time <= timestamp && timestamp <= end_time) { // Check if the frame falls within the time range
                num_valid_frames++; // Increment the number of valid frames
            }
        }
    }
    pthread_mutex_unlock(&lock); // Unlock the access to the array
}

// Function to handle errors and exceptions
void error_handler(char *message) {
    printf("Error: %s\n", message);
    exit(EXIT_FAILURE);
}

// Main function
int main() {
    init_frames(); // Initialize the dynamic array of frames
    while (1) { // Infinite loop
        LTE_PHY_RX_HEADER header; // Header of the received frame
        float signal_strength; // Signal strength of the received frame
        if (receive_frame(&header, &signal_strength)) { // Receive a new frame
            add_frame(header, signal_strength); // Add the new frame to the array
            update_signal_strength(); // Update the signal strength indicator based on recent symbol data
        } else {
            error_handler("Failed to receive frame"); // Handle errors and exceptions
        }
    }
}
