import java.security.MessageDigest;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;
import java.util.logging.Logger;

public class StringHasher {
    private static final Logger LOGGER = Logger.getLogger(StringHasher.class.getName());

    // maximum number of concurrent threads to handle input strings
    private static final int MAX_THREADS = 15;

    // frequency at which inactive data structures are cleared (in milliseconds)
    private static final long MEMORY_CLEARING_FREQUENCY = 30000L;

    // maximum number of inputs to process per second
    private static final int MAX_INPUTS_PER_SECOND = 500;

    public List<String> hashStrings(List<String> inputStrings) {
        if (inputStrings.isEmpty()) {
            return new ArrayList<>();
        }

        ExecutorService executorService = Executors.newFixedThreadPool(MAX_THREADS);
        List<FutureTask<MessageDigest>> tasks = new ArrayList<>();

        try {
            for (String inputString : inputStrings) {
                // create a task for each input string and add it to the list of tasks
                FutureTask<MessageDigest> task = new FutureTask<>(new HashStringCallable(inputString));
                tasks.add(task);

                executorService.submit(task);
            }

            // execute all tasks in parallel and wait for them to complete
            List<MessageDigest> hashes = new ArrayList<>();
            for (FutureTask<MessageDigest> task : tasks) {
                try {
                    MessageDigest digest = task.get();
                    hashes.add(digest);
                } catch (InterruptedException | ExecutionException e) {
                    LOGGER.log(Level.SEVERE, "Error occurred while processing input string", e);
                }
            }

            executorService.shutdown();
            try {
                if (!executorService.awaitTermination(MEMORY_CLEARING_FREQUENCY, TimeUnit.MILLISECONDS)) {
                    LOGGER.log(Level.WARNING, "Executor service did not terminate within the specified time");
                }
            } catch (InterruptedException e) {
                LOGGER.log(Level.SEVERE, "Interrupted while waiting for executor service to terminate", e);
            }

            return hashes;
        } finally {
            // clear inactive data structures to free up memory
            tasks.removeIf(task -> task.isDone() && !task.isCancelled());
            executorService.shutdownNow();
        }
    }

    private static class HashStringCallable implements Callable<MessageDigest> {
        private final String inputString;

        public HashStringCallable(String inputString) {
            this.inputString = inputString;
        }

        @Override
        public MessageDigest call() {
            try {
                // hash the input string using SHA-256 algorithm
                byte[] hashedBytes = MessageDigest.getInstance("SHA-256").digest(inputString.getBytes());

                // return the hash value as a hexadecimal String
                return new MessageDigest(hashedBytes);
            } catch (NoSuchAlgorithmException e) {
                LOGGER.log(Level.SEVERE, "Error occurred while hashing input string", e);
            }
            return null;
        }
    }
}
