// Struct to store a PDU session
typedef struct {
    uint32_t pdu_session_id; // Unique ID for each PDU session
    char suci[16]; // SUCI (Session-based User Control Information)
    uint8_t seid; // Session Endpoint Identifier
    bool session_state; // Current state of the session (true = active, false = inactive)
} MAC_PDU_T;

// List to store all PDU sessions
MAC_PDU_T *pdu_sessions = NULL;

// Mutex to protect concurrent access to the list
pthread_mutex_t pdu_session_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new PDU session to the list
void add_pdu_session(uint32_t pdu_session_id, char *suci, uint8_t seid) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Check if there is space for a new entry in the list
    if (pdu_sessions == NULL || pdu_sessions->size >= 50000) {
        // If there is no space, reallocate the memory for the list
        MAC_PDU_T **new_pdu_sessions = realloc(pdu_sessions, (pdu_sessions->size + 1) * sizeof(MAC_PDU_T));
        if (new_pdu_sessions == NULL) {
            // If the reallocation failed, unlock the mutex and return
            pthread_mutex_unlock(&pdu_session_lock);
            return;
        } else {
            pdu_sessions = new_pdu_sessions;
        }
    }

    // Create a new entry in the list and fill it with the provided values
    MAC_PDU_T *new_entry = &(pdu_sessions[pdu_sessions->size]);
    new_entry->pdu_session_id = pdu_session_id;
    strcpy(new_entry->suci, suci);
    new_entry->seid = seid;
    new_entry->session_state = true;

    // Increment the size of the list and unlock the mutex
    pdu_sessions->size++;
    pthread_mutex_unlock(&pdu_session_lock);
}

// Function to remove a PDU session from the list
void remove_pdu_session(uint32_t pdu_session_id) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Find the entry with the matching PDU session ID and delete it
    MAC_PDU_T *target_entry = NULL;
    for (int i = 0; i < pdu_sessions->size; i++) {
        if (pdu_sessions[i].pdu_session_id == pdu_session_id) {
            target_entry = &(pdu_sessions[i]);
            break;
        }
    }
    if (target_entry != NULL) {
        // If the entry was found, delete it and update the size of the list
        for (int i = target_entry - pdu_sessions; i < pdu_sessions->size - 1; i++) {
            pdu_sessions[i] = pdu_sessions[i + 1];
        }
        pdu_sessions->size--;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_session_lock);
}

// Function to validate the uniqueness of a PDU session ID within the list
bool is_unique_pdu_session_id(uint32_t pdu_session_id) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Iterate through the list and check for duplicates
    bool is_unique = true;
    for (int i = 0; i < pdu_sessions->size; i++) {
        if (pdu_sessions[i].pdu_session_id == pdu_session_id) {
            is_unique = false;
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_session_lock);
    return is_unique;
}

// Function to update the state of a PDU session within the list
void update_pdu_session_state(uint32_t pdu_session_id, bool new_state) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Find the entry with the matching PDU session ID and update its state
    MAC_PDU_T *target_entry = NULL;
    for (int i = 0; i < pdu_sessions->size; i++) {
        if (pdu_sessions[i].pdu_session_id == pdu_session_id) {
            target_entry = &(pdu_sessions[i]);
            break;
        }
    }
    if (target_entry != NULL) {
        target_entry->session_state = new_state;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_session_lock);
}

// Function to print all PDU sessions within the list
void print_all_pdu_sessions() {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Print each entry in the list
    for (int i = 0; i < pdu_sessions->size; i++) {
        printf("%d %s %c\n", pdu_sessions[i].pdu_session_id, pdu_sessions[i].suci, pdu_sessions[i].session_state ? 'A' : 'D');
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_session_lock);
}

// Function to print a specific PDU session within the list
void print_specific_pdu_session(uint32_t pdu_session_id) {
    // Lock the mutex before accessing the list
    pthread_mutex_lock(&pdu_session_lock);

    // Find the entry with the matching PDU session ID and print it
    MAC_PDU_T *target_entry = NULL;
    for (int i = 0; i < pdu_sessions->size; i++) {
        if (pdu_sessions[i].pdu_session_id == pdu_session_id) {
            target_entry = &(pdu_sessions[i]);
            break;
        }
    }
    if (target_entry != NULL) {
        printf("%d %s %c\n", target_entry->pdu_session_id, target_entry->suci, target_entry->session_state ? 'A' : 'D');
    } else {
        printf("PDU session not found\n");
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pdu_session_lock);
}
