void generate_crc_indication(NFAPI_CRC_INDICATION_PDU_T* crc_indication, int num_elements) {
    // Initialize the CRC flag to a random value
    for (int i = 0; i < num_elements; i++) {
        crc_indication[i].crcflag = rand() % 256;
    }

