    if (num_elements > 0) {
        NFAPI_CRC_INDICATION_PDU_T* temp = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
        memset(temp, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);

