        for (int i = 0; i < num_elements; i++) {
            if (!rntis[temp[i].rnti]) {
                rntis[temp[i].rnti] = temp[i].rnti;
            } else {
                printf("Duplicate RNTI detected: %d\n", temp[i].rnti);
            }
        }

        // Free the memory allocated for the temporary array
        free(temp);
    }
}

void* populate_crc_indication_thread(void* args) {
    int thread_id = (int)args;
    int num_elements = 10000;

    // Allocate memory dynamically based on the number of elements being processed
    NFAPI_CRC_INDICATION_PDU_T* crc_indication = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);
    memset(crc_indication, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_elements);

    // Populate the CRC indication PDUs with random values for the RX UE information and CRC indication tags
    generate_crc_indication(crc_indication, num_elements);

    // Check for duplicate RNTIs and log issues
    for (int i = 0; i < num_elements; i++) {
        if (!rntis[crc_indication[i].rnti]) {
            rntis[crc_indication[i].rnti] = crc_indication[i].rnti;
        } else {
            printf("Duplicate RNTI detected: %d\n", crc_indication[i].rnti);
        }
    }

    // Free the memory allocated for the temporary array
    free(crc_indication);

    return NULL;
}

int main() {
    int num_threads = 4;
    pthread_t threads[num_threads];

    // Initialize the RNTIs array to zero
    uint16_t rntis[10000] = {0};

    for (int i = 0; i < num_threads; i++) {
        pthread_create(&threads[i], NULL, populate_crc_indication_thread, (void*)i);
    }

    // Wait for all threads to finish
    for (int i = 0; i < num_threads; i++) {
        pthread_join(threads[i], NULL);
    }

    return 0;
}
