#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>
#include <stdbool.h>
#include <assert.h>

typedef struct LTE_PHY_RX_FRAME {
    LTE_PHY_RX_HEADER header;
    int signal_strength;
    size_t num_symbols;
    LTE_PHY_RX_SYMBOL *symbols;
} LTE_PHY_RX_FRAME;

typedef struct LTE_PHY_RX_HEADER {
    int modulation_type;
    int phase_rotation;
    float noise_variance_estimate;
} LTE_PHY_RX_HEADER;

typedef struct LTE_PHY_RX_SYMBOL {
    int modulation_type;
    int phase_rotation;
    float noise_variance_estimate;
} LTE_PHY_RX_SYMBOL;

// Thread-safe functions for managing the dynamic array of frames
pthread_mutex_t frame_lock = PTHREAD_MUTEX_INITIALIZER;
LTE_PHY_RX_FRAME *frames = NULL;
size_t num_frames = 0;

// Thread-safe functions for managing the dynamic array of symbols within frames
pthread_mutex_t symbol_lock = PTHREAD_MUTEX_INITIALIZER;
LTE_PHY_RX_SYMBOL *symbols = NULL;
size_t num_symbols = 0;

// Function for initializing the dynamic array of frames
void init_frames(size_t max_num_frames) {
    pthread_mutex_lock(&frame_lock);
    if (frames != NULL) {
        free(frames);
    }
    frames = calloc(max_num_frames, sizeof(LTE_PHY_RX_FRAME));
    num_frames = max_num_frames;
    pthread_mutex_unlock(&frame_lock);
}

// Function for managing the dynamic array of frames
void manage_frames(size_t frame_idx, bool add_frame) {
    if (add_frame) {
        // Add a new frame to the array
        pthread_mutex_lock(&frame_lock);
        if (num_frames > 0) {
            frames[frame_idx] = calloc(1, sizeof(LTE_PHY_RX_FRAME));
            num_frames--;
        } else {
            // Reached maximum number of frames, ignore new frame
            pthread_mutex_unlock(&frame_lock);
            return;
        }
        pthread_mutex_unlock(&frame_lock);
    } else {
        // Remove an existing frame from the array
        pthread_mutex_lock(&frame_lock);
        if (num_frames < max_num_frames) {
            free(frames[frame_idx]);
            frames[frame_idx] = NULL;
            num_frames++;
        } else {
            // Reached minimum number of frames, ignore deleted frame
            pthread_mutex_unlock(&frame_lock);
            return;
        }
        pthread_mutex_unlock(&frame_lock);
    }
}

// Function for initializing a new symbol within a frame
void init_symbol(size_t frame_idx, size_t symb_idx) {
    if (frame_idx < num_frames && symb_idx < frames[frame_idx].num_symbols) {
        pthread_mutex_lock(&symbol_lock);
        if (symbols != NULL) {
            free(symbols);
        }
        symbols = calloc(max_num_symbols, sizeof(LTE_PHY_RX_SYMBOL));
        num_symbols = max_num_symbols;
        pthread_mutex_unlock(&symbol_lock);
    }
}

// Function for managing the dynamic array of symbols within a frame
void manage_symbol(size_t frame_idx, size_t symb_idx, bool add_symbol) {
    if (frame_idx < num_frames && symb_idx < frames[frame_idx].num_symbols) {
        pthread_mutex_lock(&symbol_lock);
        if (add_symbol) {
            // Add a new symbol to the array
            if (num_symbols > 0) {
                symbols[symb_idx] = calloc(1, sizeof(LTE_PHY_RX_SYMBOL));
                num_symbols--;
            } else {
                // Reached maximum number of symbols, ignore new symbol
                pthread_mutex_unlock(&symbol_lock);
                return;
            }
        } else {
            // Remove an existing symbol from the array
            if (num_symbols < max_num_symbols) {
                free(symbols[symb_idx]);
                symbols[symb_idx] = NULL;
                num_symbols++;
            } else {
                // Reached minimum number of symbols, ignore deleted symbol
                pthread_mutex_unlock(&symbol_lock);
                return;
            }
        }
        pthread_mutex_unlock(&symbol_lock);
    }
}

// Function for serializing the entire array structure to a binary file
void serialize(FILE *out) {
    pthread_mutex_lock(&frame_lock);
    fwrite(&num_frames, sizeof(size_t), 1, out);
    for (size_t i = 0; i < num_frames; i++) {
        LTE_PHY_FRAME *frame = &frames[i];
        fwrite(&frame->num_symbols, sizeof(size_t), 1, out);
        for (size_t j = 0; j < frame->num_symbols; j++) {
            LTE_PHY_SYMBOL *symbol = &symbols[j];
            fwrite(&symbol->mcs, sizeof(uint8_t), 1, out);
        }
    }
    pthread_mutex_unlock(&frame_lock);
}

// Function for deserializing the entire array structure from a binary file
void deserialize(FILE *in) {
    pthread_mutex_lock(&frame_lock);
    fread(&num_frames, sizeof(size_t), 1, in);
    if (num_frames > max_num_frames) {
        // Too many frames, ignore
        num_frames = max_num_frames;
    }
    for (size_t i = 0; i < num_frames; i++) {
        LTE_PHY_FRAME *frame = &frames[i];
        fread(&frame->num_symbols, sizeof(size_t), 1, in);
        if (frame->num_symbols > max_num_symbols) {
            // Too many symbols for this frame, ignore
            frame->num_symbols = max_num_symbols;
        }
        for (size_t j = 0; j < frame->num_symbols; j++) {
            LTE_PHY_SYMBOL *symbol = &symbols[j];
            fread(&symbol->mcs, sizeof(uint8_t), 1, in);
        }
    }
    pthread_mutex_unlock(&frame_lock);
}
