#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <math.h>

// Structure to represent an UE context
typedef struct {
  char imsi[15];
  int rnti;
  int pdu_session_id;
} UEContext;

// Function to populate the UE context array with random data
void populateUEContextArray(UEContext **context, int size) {
  // Initialize an array of UE contexts with the given size
  *context = (UEContext *)malloc(size * sizeof(UEContext));
  if (*context == NULL) {
    printf("Memory allocation failed\n");
    return;
  }

  // Populate the UE contexts with random data
  for (int i = 0; i < size; i++) {
    sprintf((*context)[i].imsi, "%d", rand() % 10000000);
    (*context)[i].rnti = rand() % 10000;
    (*context)[i].pdu_session_id = rand() % 10000;
  }
}

// Function to load initial context data from a CSV file
void loadInitialContextData(char *filename, UEContext **context) {
  // Open the CSV file for reading
  FILE *fp = fopen(filename, "r");
  if (fp == NULL) {
    printf("Error opening CSV file: %s\n", filename);
    return;
  }

  // Read the header line of the CSV file
  char header[1024];
  if (fgets(header, sizeof(header), fp) == NULL) {
    printf("Error reading header from CSV file: %s\n", filename);
    fclose(fp);
    return;
  }

  // Get the number of columns in the CSV file
  int num_cols = strlen(header) - 1;

  // Allocate memory for the UE context array
  *context = (UEContext *)malloc((num_cols-2) * sizeof(UEContext));
  if (*context == NULL) {
    printf("Memory allocation failed\n");
    fclose(fp);
    return;
  }

  // Read the rows of the CSV file and populate the UE context array
  while (fgets(header, sizeof(header), fp) != NULL) {
    char *token = strtok(header, ",");
    int i = 0;
    while (token != NULL && i < num_cols-2) {
      (*context)[i].imsi[i] = token;
      token = strtok(NULL, ",");
      i++;
    }
  }
}
```
