int allocate_array(size_t N) {
  // Allocate memory for an array of NFAPI_L1_FFT_OUTPUT_T structures
  NFAPI_L1_FFT_OUTPUT_T* array = (NFAPI_L1_FFT_OUTPUT_T*)malloc(N * sizeof(NFAPI_L1_FFT_OUTPUT_T));
  if (array == NULL) {
    printf("Error: Failed to allocate memory for array of size %zu\n", N);
    return -1;
  }

  // Initialize the structures with default values
  for (size_t i = 0; i < N; ++i) {
    array[i].FFT_SIZE = 256;
    array[i].CENTER_FREQUENCY = 100e3;
    array[i].TX_POWER_LEVEL = 10;
  }

  // Validate the values and populate the structures accordingly
  for (size_t i = 0; i < N; ++i) {
    if (array[i].CENTER_FREQUENCY <= 1e3 || array[i].CENTER_FREQUENCY >= 2e9) {
      printf("Error: Center frequency value out of range [1e3, 2e9]: %f\n", array[i].CENTER_FREQUENCY);
      return -2;
    }
    if (array[i].TX_POWER_LEVEL < 0 || array[i].TX_POWER_LEVEL > 15) {
      printf("Error: TX power level value out of range [0, 15]: %d\n", array[i].TX_POWER_LEVEL);
      return -3;
    }
    // Logarithmic interpolation of TX power level across different frequency bands
    array[i].TX_POWER_LEVEL = log(array[i].CENTER_FREQUENCY) * 10 + array[i].TX_POWER_LEVEL;
  }

  // Handle memory allocation failures gracefully
  if (N > 0 && array == NULL) {
    printf("Error: Failed to allocate memory for array of size %zu\n", N);
    return -1;
  }

  // Return the allocated memory
  return array;
}
