            networkAdapter_ = std::make_unique<HttpNetworkAdapter>();
            if (!networkAdapter_->connect()) {
                return false;
            }
            return true;
        } catch (std::exception& e) {
            std::cout << "Error starting service: " << e.what() << std::endl;
            return false;
        }
    }

    void stop() {
        if (networkAdapter_) {
            networkAdapter_->disconnect();
        }
    }

