            if (!response) {
                return false;
            }
            // Process response here.
            return true;
        } catch (std::exception& e) {
            std::cout << "Error processing request: " << e.what() << std::endl;
            networkAdapter_->handleFailure(request);
            return false;
        }
    }

private:
