    pthread_mutex_unlock(&crcMutex);
}

// Define the function to adjust the list based on current network load
void adjustCrcIndications() {
    // Lock the mutex for thread synchronization
    pthread_mutex_lock(&crcMutex);
    // Check if the network load is high
    if (networkLoad > 80) {
        // If it is, reduce the list size by half
        int newSize = crcIndications.length / 2;
        for (int i = 0; i < newSize; i++) {
