        int newSize = crcIndications.length * 2;
        for (int i = 0; i < newSize; i++) {
            if (crcIndications[i] == NULL) {
                // Allocate a new structure and store it in the list
                crcIndications[i] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));
