    pthread_mutex_unlock(&crcMutex);
}

// Define the function to read CRC indications from a file and store them in a list
void readCrcIndicationsFromFile() {
    // Lock the mutex for thread synchronization
    pthread_mutex_lock(&crcMutex);
    // Iterate over the list of CRC indication PDUs and read each structure from a file
    for (int i = 0; i < 50000; i++) {
