    pthread_mutex_unlock(&crcMutex);
}

// Define the function to handle CRC indications and store them in a list
void handleCrcIndications(NFAPI_CRC_INDICATION_PDU *crc) {
    // Lock the mutex for thread synchronization
    pthread_mutex_lock(&crcMutex);
    // Manage the dynamic list of CRC indication PDUs and validate the uniqueness of RNTIs within it
