    ue_instance_t *ue_instances; // Array of UE instances
    pthread_mutex_t lock; // Mutex for protecting the UE instance list
} netif_module_t;

// Initialize and configure a network interface module
netif_module_t *init_netif_module(int num_ues) {
    netif_module_t *module = malloc(sizeof(netif_module_t));
    if (!module) {
        perror("Failed to allocate memory for network interface module");
        return NULL;
    }

    // Initialize the mutex for protecting the UE instance list
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    if (pthread_mutex_init(&module->lock, &attr) != 0) {
        perror("Failed to initialize mutex for network interface module");
        return NULL;
    }

    // Allocate memory for the UE instance list
    module->ue_instances = malloc(sizeof(ue_instance_t) * num_ues);
    if (!module->ue_instances) {
        perror("Failed to allocate memory for UE instances");
        return NULL;
    }

    // Initialize the UE instance list
    int i;
    for (i = 0; i < num_ues; i++) {
        module->ue_instances[i].rnti[0] = '\0';
        module->ue_instances[i].pdu_type = 0;
        module->ue_instances[i].pdu_buffer = NULL;
        module->ue_instances[i].pdu_size = 0;
    }

    // Set the number of UE instances
    module->num_ues = num_ues;

    return module;
}

// Add a new UE instance to the network interface module
int add_ue_instance(netif_module_t *module, char *rnti, int pdu_type) {
    if (!module || !rnti) {
        fprintf(stderr, "Invalid arguments for add_ue_instance()\n");
        return -1;
    }

    // Acquire the lock for protecting the UE instance list
    pthread_mutex_lock(&module->lock);

    // Check if the maximum number of UEs has been reached
    if (module->num_ues == module->ue_instances.size) {
        fprintf(stderr, "Maximum number of UE instances has been reached\n");
        pthread_mutex_unlock(&module->lock);
        return -1;
    }

    // Find an empty slot in the UE instance list
    int i = 0;
    while (i < module->num_ues && strlen(module->ue_instances[i].rnti) != 0) {
        i++;
    }

    // Add a new UE instance to the list
    if (strlen(rnti) > sizeof(module->ue_instances[i].rnti)) {
        fprintf(stderr, "RNTI is too long\n");
        pthread_mutex_unlock(&module->lock);
        return -1;
    }
    strcpy(module->ue_instances[i].rnti, rnti);
    module->ue_instances[i].pdu_type = pdu_type;

    // Release the lock for protecting the UE instance list
    pthread_mutex_unlock(&module->lock);

    return i;
}

// Remove an existing UE instance from the network interface module
int remove_ue_instance(netif_module_t *module, int index) {
    if (!module || index < 0 || index >= module->num_ues) {
        fprintf(stderr, "Invalid arguments for remove_ue_instance()\n");
        return -1;
    }

    // Acquire the lock for protecting the UE instance list
    pthread_mutex_lock(&module->lock);

    // Remove the UE instance from the list
    if (strlen(module->ue_instances[index].rnti) != 0) {
        module->ue_instances[index].rnti[0] = '\0';
        module->ue_instances[index].pdu_type = 0;
        module->ue_instances[index].pdu_buffer = NULL;
        module->ue_instances[index].pdu_size = 0;
    } else {
        fprintf(stderr, "UE instance at index %d is not found\n", index);
    }

    // Release the lock for protecting the UE instance list
    pthread_mutex_unlock(&module->lock);

    return 0;
}

// Handle a received PDU message from an UE instance
int handle_pdu(netif_module_t *module, int index, void *data, size_t data_size) {
    if (!module || index < 0 || index >= module->num_ues || !data) {
        fprintf(stderr, "Invalid arguments for handle_pdu()\n");
        return -1;
    }

    // Acquire the lock for protecting the UE instance list
    pthread_mutex_lock(&module->lock);

    // Check if the UE instance exists and has enough memory to store the PDU message
    if (strlen(module->ue_instances[index].rnti) == 0 || module->ue_instances[index].pdu_size < data_size) {
        fprintf(stderr, "UE instance at index %d does not exist or has insufficient memory\n", index);
        pthread_mutex_unlock(&module->lock);
        return -1;
    }

    // Copy the PDU message to the UE instance buffer
    memcpy(module->ue_instances[index].pdu_buffer, data, data_size);
    module->ue_instances[index].pdu_size = data_size;

    // Release the lock for protecting the UE instance list
    pthread_mutex_unlock(&module->lock);

    return 0;
}
```

