void populate_hash_table(int size, int *keys, long *offsets, hash_table_t *ht) {
    assert(size > 0 && keys != NULL && offsets != NULL);
    // Initialize the hash table with the specified number of buckets
    init_hash_table(size, ht);
    // Iterate over the input data and insert each key-value pair into the hash table
    for (int i = 0; i < size; i++) {
        int key = keys[i];
        long offset = offsets[i];
        // Calculate the hash value for the current key
        int hash_val = key % ht->size;
        // If there is already a bucket with this hash value, use linear probing to find an empty slot
        while (ht->buckets[hash_val] != NULL && ht->buckets[hash_val]->key == key) {
            hash_val = (hash_val + 1) % ht->size;
