// Function for resizing the hash table to accommodate more keys
void resize_hash_table(hash_table_t *ht) {
    assert(ht != NULL);
    int old_size = ht->size;
    ht->size *= 2; // Double the size of the table
    // Allocate new buckets for the resized hash table and copy over existing entries
    ht->buckets = (hash_entry_t**)realloc(ht->buckets, sizeof(hash_entry_t*) * ht->size);
