void initTasks(Task **tasks, int num_tasks) {
    // Allocate memory for the tasks collection
    *tasks = (Task *)malloc(num_tasks * sizeof(Task));
    if (*tasks == NULL) {
        printf("Error: Failed to allocate memory for task collection");
        exit(1);
    }

    // Initialize each task's description and priority level randomly
