            exit(1);
        }
        snprintf((*tasks)[i].description, 32, "Task %d", i + 1);
        (*tasks)[i].priority = rand() % 10 + 1; // Randomly assign priority level between 1 and 10
    }

    // Set start and end timestamps for each task
    struct timespec current_ts;
    clock_gettime(CLOCK_MONOTONIC, &current_ts);
    for (int i = 0; i < num_tasks; i++) {
        (*tasks)[i].start_ts = current_ts;
        (*tasks)[i].end_ts = current_ts;
    }
}

// Define function to insert a new task into the tasks collection
void insertTask(Task **tasks, int num_tasks, Task *new_task) {
    // Resize tasks collection if necessary
    if (num_tasks == 0 || (*tasks)[num_tasks - 1].priority >= new_task->priority) {
        // Allocate more memory for the tasks collection
        int new_size = num_tasks + 1;
        Task *new_tasks = realloc(*tasks, new_size * sizeof(Task));
        if (new_tasks == NULL) {
            printf("Error: Failed to resize task collection");
            exit(1);
        }
        *tasks = new_tasks;
    }

    // Insert new task into the tasks collection
    for (int i = num_tasks - 1; i >= 0; i--) {
        if ((*tasks)[i].priority > new_task->priority) {
            (*tasks)[i + 1] = (*tasks)[i];
        } else {
            break;
        }
    }
    (*tasks)[i + 1] = *new_task;

    // Update number of tasks in the collection
    num_tasks++;
}

// Define function to delete a task from the tasks collection
void deleteTask(Task **tasks, int *num_tasks, Task *to_delete) {
    // Find index of task to delete
    int i;
    for (i = 0; i < *num_tasks; i++) {
        if ((*tasks)[i].priority == to_delete->priority) {
            break;
        }
    }

    // Update number of tasks in the collection
    (*num_tasks)--;

    // Shift tasks down one position to fill gap
    for (int j = i; j < *num_tasks; j++) {
        (*tasks)[j] = (*tasks)[j + 1];
    }
}

// Define function to periodically log the state of the task collection to a file
