    // If the key is already in the data structure, update the value of the existing record
    update_record(ds, key, record);
  } else {
    // If the key is not in the data structure, add a new record
    int index = ds->num_keys++;
    ds->offsets[index] = ds->size;
    ds->keys[index] = key;
    ds->records[index] = record;
    ds->size += sizeof(struct record);
  }
}

// Define a function to find the index of a key in the data structure
