// Add a new item to the list, updating an existing item if necessary
void add_item(const char* name, int id, double value) {
    bool found = false;

    // Check if an item with the same ID already exists
    for (size_t i = 0; i < num_items; i++) {
        if (items[i].id == id) {
            items[i] = (Item){ name, id, value };
            found = true;
            break;
        }
    }

    // If not found, add a new item to the end of the list
    if (!found) {
        items = realloc(items, (num_items + 1) * sizeof(Item));
        items[num_items] = (Item){ name, id, value };
        num_items++;
    }
}

// Update an existing item by ID
void update_item(int id, const char* name, double value) {
    // Check if an item with the specified ID exists
    for (size_t i = 0; i < num_items; i++) {
        if (items[i].id == id) {
            items[i] = (Item){ name, id, value };
            return;
        }
    }
}

// Remove an item from the list by ID
void remove_item(int id) {
    // Find the index of the item to be removed
    for (size_t i = 0; i < num_items; i++) {
        if (items[i].id == id) {
            items[i] = items[--num_items]; // Shift the item to the end
            return;
        }
    }
}

// Retrieve an item from the list by ID
Item* get_item(int id) {
    for (size_t i = 0; i < num_items; i++) {
        if (items[i].id == id) {
            return &items[i];
        }
    }
    return NULL;
}

// List all items in sorted order by ID
