    // Check if the encryption context is valid
    if (ctx == NULL || ctx->ctx == NULL) {
        printf("Invalid encryption context\n");
        return -1;
    }

    // Decrypt the given data using the specified encryption parameters
    EVP_DecryptUpdate(ctx->ctx, data, len);

    // Return the decrypted data
