// Function to clean up the encryption context object
int encrypt_cleanup(struct EncryptionContext *ctx) {
    // Check if the encryption context is valid
    if (ctx == NULL || ctx->ctx == NULL) {
        printf("Invalid encryption context\n");
        return -1;
    }

    // Clean up the OpenSSL cipher context object
    EVP_CIPHER_CTX_cleanup(ctx->ctx);

    // Free the encryption context object
    free(ctx);

    // Return success
    return 0;
}
