#define MAX_UE 10000
#define MAX_PDU 50

// Structure to store UE information
typedef struct {
    int rnti; // RNTI (Radio Network Temporary Identifier) for each UE
    char* pdu_types[MAX_PDU]; // Array of supported PDU types for each UE
} ue_info_t;

// Structure to store network interface information
typedef struct {
    int sockfd; // Socket file descriptor
    bool is_active; // Flag to indicate whether the interface is active or not
} net_iface_t;

// Global variables
ue_info_t* ue_info_arr = (ue_info_t*) malloc(MAX_UE * sizeof(ue_info_t));
net_iface_t* net_ifaces[MAX_UE]; // Array of network interfaces
int num_ues = 0; // Number of UEs currently active

// Function to initialize and configure a network interface module
void init_net_iface(int sockfd) {
    net_iface_t* iface = (net_iface_t*) malloc(sizeof(net_iface_t));
    iface->sockfd = sockfd;
    iface->is_active = true;
    net_ifaces[num_ues++] = iface;
}

// Function to handle a new UE connection request
void handle_new_ue(int sockfd) {
    // Allocate memory for the new UE
    ue_info_t* new_ue = (ue_info_t*) malloc(sizeof(ue_info_t));
    new_ue->rnti = num_ues; // Assign a unique RNTI for the new UE
    char* pdu_types[MAX_PDU]; // Initialize the array of supported PDU types for the new UE
    for (int i = 0; i < MAX_PDU; i++) {
        pdu_types[i] = malloc(sizeof(char)); // Allocate memory for each type
    }
    new_ue->pdu_types = pdu_types;
    ue_info_arr[num_ues++] = new_ue;
}

// Function to handle a UE disconnection request
void handle_disconnect_ue(int sockfd) {
    // Find the corresponding UE and free its memory
    for (int i = 0; i < num_ues; i++) {
        if (net_ifaces[i]->sockfd == sockfd) {
            free(ue_info_arr[i]);
            net_ifaces[i]->is_active = false;
            break;
        }
    }
}

// Function to handle a PDU message from an UE
void handle_pdu(int sockfd, char* pdu) {
    // Find the corresponding UE and update its PDU type array
    for (int i = 0; i < num_ues; i++) {
        if (net_ifaces[i]->sockfd == sockfd) {
            ue_info_arr[i]->pdu_types[pdu->type] = pdu;
            break;
        }
    }
}

// Function to manage UE connections and handle PDU messages
void* manage_ue(void* arg) {
    int sockfd = (int) arg;
    while (true) {
        // Receive a message from the socket
        char* pdu = recv(sockfd, NULL, 0, MSG_WAITALL);
        if (!pdu) {
            break;
        }
        handle_pdu(sockfd, pdu);
    }
    return NULL;
}

// Function to manage network interfaces and UE connections
void* manage_interfaces() {
    while (true) {
        // Receive a message from the socket
        char* msg = recv(net_ifaces[0]->sockfd, NULL, 0, MSG_WAITALL);
        if (!msg) {
            break;
        }
        int sockfd = atoi(msg);
        handle_new_ue(sockfd);
    }
    return NULL;
}

// Main function to initialize and configure the network interface module
int main() {
    // Initialize the network interfaces
    for (int i = 0; i < MAX_UE; i++) {
        init_net_iface(i);
    }
    // Start a thread to manage UE connections and handle PDU messages
    pthread_create(&ue_manage_thread, NULL, manage_ue, (void*) net_ifaces[0]->sockfd);
    // Start another thread to manage network interfaces and UE connections
    pthread_create(&interface_manage_thread, NULL, manage_interfaces, NULL);
    return 0;
}
