```c++
#include <iostream>
#include <vector>
#include <mutex>
#include <condition_variable>
#include <atomic>
#include <chrono>
#include <memory>
#include <thread>
#include <functional>

// Custom mission structure for managing missions
struct Mission {
  float timestamp; // Timestamp of the mission
  enum Strategy strategy; // Type of strategy to use for the mission
  double priority; // Priority value for the mission
};

// Custom memory pool for allocating and deallocating mission structures
class MemoryPool {
 public:
  MemoryPool() {}
  ~MemoryPool() {}

  // Allocate a new mission structure
  Mission* allocateMission() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (freeList_.empty()) {
      return new Mission;
    } else {
      auto it = freeList_.back();
      freeList_.pop_back();
      return it;
    }
  }

  // Deallocate a mission structure
  void deallocateMission(Mission* mission) {
    std::lock_guard<std::mutex> lock(mutex_);
    freeList_.push_back(mission);
  }

 private:
  std::vector<Mission*> freeList_; // List of available mission structures
  std::mutex mutex_; // Mutex for protecting the memory pool
};

// Custom least recently used (LRU) eviction policy for managing active missions
class LRUEvictionPolicy {
 public:
  LRUEvictionPolicy() {}
  ~LRUEvictionPolicy() {}

  // Add a new mission to the active set
  void addMission(Mission* mission) {
    std::lock_guard<std::mutex> lock(mutex_);
    activeSet_.insert(mission);
  }

  // Remove an inactive mission from the active set
  void removeInactiveMission(Mission* mission) {
    std::lock_guard<std::mutex> lock(mutex_);
    activeSet_.erase(mission);
  }

  // Evict the least recently used (LRU) mission from the active set
  Mission* evictLRU() {
    std::lock_guard<std::mutex> lock(mutex_);
    if (!activeSet_.empty()) {
      auto it = activeSet_.begin();
      Mission* oldestMission = *it;
      activeSet_.erase(it);
      return oldestMission;
    } else {
      return nullptr;
    }
  }

 private:
  std::unordered_set<Mission*> activeSet_; // Set of active missions
  std::mutex mutex_; // Mutex for protecting the active set
};

// Custom strategy selection and logging system
class StrategySelectionSystem {
 public:
  StrategySelectionSystem() {}
  ~StrategySelectionSystem() {}

  // Select and log a strategy for a mission
  void selectAndLogStrategy(Mission* mission) {
    std::lock_guard<std::mutex> lock(mutex_);
    validatePriorityValue(mission->priority);
    // Check if the memory pool is full and evict an LRU mission if necessary
    if (memoryPool_.freeList().empty()) {
      auto oldestMission = lruEvictionPolicy_.evictLRU();
      if (oldestMission != nullptr) {
        memoryPool_.deallocateMission(oldestMission);
      }
    }
    // Allocate a new mission structure from the memory pool
    Mission* newMission = memoryPool_.allocateMission();
    *newMission = *mission;
    activeSet_.insert(newMission);
  }

  // Validate the priority value for a mission
  void validatePriorityValue(double priority) {
    if (priority < MIN_PRIORITY || priority > MAX_PRIORITY) {
      throw std::invalid_argument("Invalid priority value");
    }
  }

 private:
  static constexpr double MIN_PRIORITY = 0.0; // Minimum allowed priority value
  static constexpr double MAX_PRIORITY = 1.0; // Maximum allowed priority value

  MemoryPool memoryPool_; // Memory pool for managing mission structures
  LRUEvictionPolicy lruEvictionPolicy_; // LRU eviction policy for managing active missions
  std::unordered_set<Mission*> activeSet_; // Set of active missions
  std::mutex mutex_; // Mutex for protecting the strategy selection and logging system
};

int main() {
  StrategySelectionSystem system;
