    for (int i = 0; i < num_frames; i++) {
        if (rx_frames[i].signal_strength >= min_signal_strength && rx_frames[i].signal_strength <= max_signal_strength) {
            retrieved_frames[num_retrieved_frames++] = &rx_frames[i];
        }
