    // Iterate over the dynamic array of frames and calculate the average signal strength
    float avg_signal_strength = 0;
    for (int i = 0; i < num_frames; i++) {
        avg_signal_strength += rx_frames[i].signal_strength;
    }
    avg_signal_strength /= num_frames;

    // Update the signal strength indicator with the average value
    signal_strength = avg_signal_strength;
}

