// Define the record structure to hold offset, key, and random value
typedef struct {
  long offset;
  int key;
  int random_val;
} Record;

// Define the dynamic list to store records
typedef struct {
  Record *records;
  size_t num_records;
  size_t max_num_records;
} DynamicList;

// Function to initialize and manage a dynamic list of records
void init_list(DynamicList *list, size_t max_num_records) {
  list->records = (Record *)malloc(max_num_records * sizeof(Record));
  list->num_records = 0;
  list->max_num_records = max_num_records;
}

// Function to add a record to the list
void add_record(DynamicList *list, long offset, int key) {
  // Check if the list is full
  if (list->num_records == list->max_num_records) {
    // Evict an entry from the LRU cache
    Record *evicted = list->records[0];
    for (size_t i = 1; i < list->max_num_records; i++) {
      if (list->records[i]->offset < evicted->offset) {
        evicted = list->records[i];
      }
    }
    // Remove the evicted entry from the list
    memmove(evicted, &list->records[0], sizeof(Record));
  } else {
    // Add a new record to the end of the list
    Record *new_record = &list->records[list->num_records];
    new_record->offset = offset;
    new_record->key = key;
    new_record->random_val = rand() % 100 + 1;
    list->num_records++;
  }
}

// Function to get a record from the list by key
Record *get_record(DynamicList *list, int key) {
  for (size_t i = 0; i < list->max_num_records; i++) {
    if (list->records[i].key == key) {
      return &list->records[i];
    }
  }
  return NULL;
}

// Function to update a record in the list
void update_record(DynamicList *list, long offset, int key, int random_val) {
  Record *record = get_record(list, key);
  if (record != NULL) {
    record->offset = offset;
    record->random_val = random_val;
  }
}

// Function to delete a record from the list
void delete_record(DynamicList *list, int key) {
  Record *record = get_record(list, key);
  if (record != NULL) {
    // Remove the record from the list
    memmove(record, &list->records[0], sizeof(Record));
    list->num_records--;
  }
}
```
