```c
#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>

// Item structure to store name, ID, and value
typedef struct {
    char name[256];
    int id;
    double value;
} item_t;

// Collection of items
typedef struct {
    item_t* items;
    size_t capacity;
    size_t count;
} item_collection_t;

/* Adds a new item to the collection.
 * Return true if successful, false otherwise. */
bool add_item(item_collection_t* collection, const char* name, int id, double value) {
    // Check if there is enough space in the collection
    if (collection->count == collection->capacity) {
        return false;
    }

    // Create a new item structure and initialize it with the given values
    item_t* new_item = malloc(sizeof(item_t));
    strcpy(new_item->name, name);
    new_item->id = id;
    new_item->value = value;

    // Add the new item to the collection
    collection->items[collection->count++] = new_item;

    return true;
}

/* Updates an existing item in the collection by ID.
 * Return true if successful, false otherwise. */
bool update_item(item_collection_t* collection, int id, const char* name, double value) {
    // Find the item with the given ID and update its values
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i]->id == id) {
            strcpy(collection->items[i]->name, name);
            collection->items[i]->value = value;
            return true;
        }
    }

    // Return false if the item was not found
    return false;
}

/* Removes an existing item from the collection by ID.
 * Return true if successful, false otherwise. */
bool remove_item(item_collection_t* collection, int id) {
    // Find the index of the item with the given ID and remove it from the collection
    for (size_t i = 0; i < collection->count; ++i) {
        if (collection->items[i]->id == id) {
            free(collection->items[i]);
            memmove(&collection->items[i], &collection->items[i + 1], sizeof(item_t*) * (collection->count - i - 1));
            collection->count--;
            return true;
        }
    }

    // Return false if the item was not found
    return false;
}

/* Prints all items in the collection. */
void print_items(item_collection_t* collection) {
    for (size_t i = 0; i < collection->count; ++i) {
        printf("%d: %s, %.2f\n", collection->items[i]->id, collection->items[i]->name, collection->items[i]->value);
    }
}

int main() {
    // Create a new collection with an initial capacity of 10 items
    item_collection_t* collection = malloc(sizeof(item_collection_t));
    collection->capacity = 10;
    collection->count = 0;
    collection->items = malloc(sizeof(item_t*) * collection->capacity);

    // Add a few items to the collection
    add_item(collection, "Apple", 1, 5.99);
    add_item(collection, "Orange", 2, 4.99);
    add_item(collection, "Banana", 3, 1.99);

    // Update an existing item by ID
    update_item(collection, 1, "Grapefruit", 6.99);

    // Remove an item from the collection by ID
    remove_item(collection, 2);

    // Print all items in the collection
    print_items(collection);

    free(collection->items);
    free(collection);

    return 0;
}
```
