#define MAX_MEMORY 1024 * 1024 * 10 // 10MB
#define BLOCK_SIZE 1024 * 8 // 8KB

typedef struct {
    double amount;
    char currency[3];
    long timestamp;
} transaction;

struct memory_pool {
    size_t block_count;
    size_t block_size;
    void* blocks;
};

void init_memory_pool(struct memory_pool* pool, size_t block_count, size_t block_size) {
    pool->block_count = block_count;
    pool->block_size = block_size;
    pool->blocks = malloc(block_count * block_size);
}

void destroy_memory_pool(struct memory_pool* pool) {
    free(pool->blocks);
}

void* allocate_block(struct memory_pool* pool, size_t size) {
    if (size > pool->block_size) {
        return NULL;
    }

    void* block = pool->blocks;
    pool->blocks += size;
    pool->block_count--;

    return block;
}

void deallocate_block(struct memory_pool* pool, void* block) {
    if (block < pool->blocks || block > pool->blocks + pool->block_count * pool->block_size) {
        // invalid block
        return;
    }

    size_t index = (block - pool->blocks) / pool->block_size;
    memset(block, 0, pool->block_size);
    pool->blocks += pool->block_size;
    pool->block_count++;
}

struct data_structure {
    struct memory_pool* pool;
    size_t block_count;
    size_t transaction_count;
    size_t capacity;
};

void init_data_structure(struct data_structure* ds, size_t capacity) {
    ds->capacity = capacity;
    ds->transaction_count = 0;

    struct memory_pool* pool = malloc(sizeof(*pool));
    init_memory_pool(pool, capacity * BLOCK_SIZE / sizeof(transaction), BLOCK_SIZE);
    ds->pool = pool;
}

void destroy_data_structure(struct data_structure* ds) {
    destroy_memory_pool(ds->pool);
    free(ds->pool);
}

int add_transaction(struct data_structure* ds, transaction t) {
    if (ds->transaction_count >= ds->capacity) {
        return -1;
    }

    size_t index = ds->transaction_count++;
    void* block = allocate_block(ds->pool, sizeof(transaction));
    if (!block) {
        return -1;
    }

    transaction* tp = (transaction*)block;
    tp->amount = t.amount;
    strcpy(tp->currency, t.currency);
    tp->timestamp = t.timestamp;

    return 0;
}

int update_transaction(struct data_structure* ds, size_t index, transaction t) {
    if (index >= ds->transaction_count || ds->pool->blocks[index * sizeof(transaction)] == NULL) {
        // invalid index or block is not allocated
        return -1;
    }

    void* block = &ds->pool->blocks[index * sizeof(transaction)];
    transaction* tp = (transaction*)block;
    tp->amount = t.amount;
    strcpy(tp->currency, t.currency);
    tp->timestamp = t.timestamp;

    return 0;
}

int delete_transaction(struct data_structure* ds, size_t index) {
    if (index >= ds->transaction_count || ds->pool->blocks[index * sizeof(transaction)] == NULL) {
        // invalid index or block is not allocated
        return -1;
    }

    void* block = &ds->pool->blocks[index * sizeof(transaction)];
    deallocate_block(ds->pool, block);

    return 0;
}

int get_transaction(struct data_structure* ds, size_t index, transaction* t) {
    if (index >= ds->transaction_count || ds->pool->blocks[index * sizeof(transaction)] == NULL) {
        // invalid index or block is not allocated
        return -1;
    }

    void* block = &ds->pool->blocks[index * sizeof(transaction)];
    transaction* tp = (transaction*)block;
    memcpy(t, tp, sizeof(*t));

    return 0;
}

