function manageUserAccount($request) {
    // Input validation
    if (!isset($request['name']) || !preg_match('/^[a-zA-Z ]+$/', $request['name'])) {
        return jsonResponse(['error' => 'Name is required and must be a valid string']);
    }
    if (!isset($request['email']) || !filter_var($request['email'], FILTER_VALIDATE_EMAIL)) {
        return jsonResponse(['error' => 'Email is required and must be a valid email address']);
    }
    if (!isset($request['password']) || strlen($request['password']) < 8) {
        return jsonResponse(['error' => 'Password is required and must be at least 8 characters long']);
    }
    if (isset($request['sub_action'])) {
        // Handle updates or deletions based on sub_action
        if ($request['sub_action'] === 'update') {
            $user = getUserById($request['id']);
            if (!$user) {
                return jsonResponse(['error' => 'User not found']);
            }
            // Update user data
            $user->name = $request['name'];
            $user->email = $request['email'];
            $user->password = password_hash($request['password'], PASSWORD_DEFAULT);
            saveUserData($user);
            return jsonResponse(['message' => 'Success']);
        } else if ($request['sub_action'] === 'delete') {
            // Delete user data
            $user = getUserById($request['id']);
            if (!$user) {
                return jsonResponse(['error' => 'User not found']);
            }
            deleteUserData($user);
            return jsonResponse(['message' => 'Success']);
        }
    } else {
        // Handle creation of new user
        $user = new User();
        $user->name = $request['name'];
        $user->email = $request['email'];
        $user->password = password_hash($request['password'], PASSWORD_DEFAULT);
