    PHY_RX_SUBFRAME_INFO subframe_info;
} LTE_PHY_RX_PROC_T;

LTE_PHY_RX_PROC_T* create_rx_proc(size_t num_symbols) {
    // Allocate memory for the array of structures
    LTE_PHY_RX_PROC_T *rx_procs = (LTE_PHY_RX_PROC_T*) malloc(num_symbols * sizeof(LTE_PHY_RX_PROC_T));

