        rx_procs[i].symbol_info.rx_antenna = get_default_rx_antenna();
        rx_procs[i].subframe_info.tx_mode = get_default_tx_mode();
    }

    // Log the creation of each structure, including timestamps and detailed information about the reception parameters
    log_message("Created rx_proc array with %d elements", LOG_SEVERITY_INFO, num_symbols);

    return rx_procs;
}

void free_rx_proc(LTE_PHY_RX_PROC_T* rx_procs) {
    // Free the memory allocated for the array of structures
    free(rx_procs);
}
