using System.Net;
using System.Text.Json;

public static class HttpHandler {
    private static readonly DatabaseService _databaseService = new DatabaseService();
    private static readonly LoggingService _loggingService = new LoggingService();

    public static async Task<HttpResponseMessage> HandlePostRequest(int pageSectionId, int elementId, string htmlContent) {
        if (string.IsNullOrEmpty(htmlContent)) {
            return new HttpResponseMessage(HttpStatusCode.BadRequest);
        }

        // Validate input data before proceeding
        if (!_databaseService.ValidateInputData(pageSectionId, elementId)) {
            _loggingService.LogError("Invalid input data for page section ID and element ID");
            return new HttpResponseMessage(HttpStatusCode.BadRequest);
        }

        // Update HTML content using service class
        try {
            await _databaseService.UpdateHtmlContent(pageSectionId, elementId, htmlContent);
        } catch (Exception e) {
            _loggingService.LogError("Failed to update HTML content", e);
            return new HttpResponseMessage(HttpStatusCode.InternalServerError);
        }

        // Verify integrity of HTML structure
        try {
            await _databaseService.VerifyHtmlStructure();
        } catch (Exception e) {
            _loggingService.LogError("Failed to verify HTML structure", e);
            return new HttpResponseMessage(HttpStatusCode.InternalServerError);
        }

        // Return response indicating whether page should be refreshed
        if (_databaseService.ShouldRefreshPage()) {
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("true") };
        } else {
            return new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("false") };
        }
    }
}
