#define MAX_PERMISSIONS 256

// Structure to represent an entity in the system
struct Entity {
    char *name;
    int group_id;
    int permission_level;
};

// Linked list data structure to store users
struct UserList {
    struct Entity *head;
    struct Entity *tail;
    int size;
};

// Linked list data structure to store groups
struct GroupList {
    struct Entity *head;
    struct Entity *tail;
    int size;
};

// Linked list data structure to store permissions
struct PermissionList {
    struct Entity *head;
    struct Entity *tail;
    int size;
};

// Hash table data structure to map users to their respective groups
struct UserGroupMap {
    struct Entity **table;
    int capacity;
    int size;
};

// Custom hash function for the user group map
int user_group_hash(const char *username) {
    // Use a simple hash function based on the ASCII values of the characters in the username
    int hash = 0;
    for (int i = 0; i < strlen(username); ++i) {
        hash += username[i];
    }
    return hash % USER_GROUP_MAP_CAPACITY;
}

// Function to allocate memory dynamically for all linked lists and the hash table, ensuring no memory leaks and adhering to the existing memory management conventions of the system.
void *allocate(size_t size) {
    void *ptr = malloc(size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Function to initialize the linked lists and hash table to store a specified number of entities, considering the expected growth rate and memory constraints of the system.
void init(struct UserList *users, struct GroupList *groups, struct PermissionList *permissions, struct UserGroupMap *user_group_map) {
    // Allocate memory for all linked lists and hash table
    users->head = (struct Entity *)allocate(sizeof(struct Entity) * MAX_USERS);
    users->tail = users->head;
    groups->head = (struct Entity *)allocate(sizeof(struct Entity) * MAX_GROUPS);
    groups->tail = groups->head;
    permissions->head = (struct Entity *)allocate(sizeof(struct Entity) * MAX_PERMISSIONS);
    permissions->tail = permissions->head;
    user_group_map->table = (struct Entity **)allocate(sizeof(struct Entity *) * USER_GROUP_MAP_CAPACITY);
    memset(user_group_map->table, -1, sizeof(struct Entity *) * USER_GROUP_MAP_CAPACITY);

    // Initialize the linked lists and hash table with an empty state
    users->size = 0;
    groups->size = 0;
    permissions->size = 0;
    user_group_map->capacity = USER_GROUP_MAP_CAPACITY;
    user_group_map->size = 0;
}

// Function to populate the linked lists and hash table with data read from a file, where each line represents an entity in a structured format (e.g., "username:group_id:permission_level"). Implement error handling for parsing errors and ensure data consistency across the system.
void populate(struct UserList *users, struct GroupList *groups, struct PermissionList *permissions, struct UserGroupMap *user_group_map, FILE *file) {
    // Read lines from the file
    char line[1024];
    while (fgets(line, sizeof(line), file) != NULL) {
        // Parse each line into an entity structure
        struct Entity *entity = (struct Entity *)allocate(sizeof(struct Entity));
        char *username = strtok(line, ":");
        char *group_id = strtok(NULL, ":");
        char *permission_level = strtok(NULL, "\n");
        entity->name = username;
        entity->group_id = atoi(group_id);
        entity->permission_level = atoi(permission_level);

        // Add the entity to the linked lists and hash table accordingly
        add_entity(users, groups, permissions, user_group_map, entity);
    }
}

// Function to add an entity to the linked lists and hash table.
void add_entity(struct UserList *users, struct GroupList *groups, struct PermissionList *permissions, struct UserGroupMap *user_group_map, struct Entity *entity) {
    // Add the entity to the corresponding linked list
    if (strcmp(entity->name, "user") == 0) {
        add_user(users, entity);
    } else if (strcmp(entity->name, "group") == 0) {
        add_group(groups, entity);
    } else if (strcmp(entity->name, "permission") == 0) {
        add_permission(permissions, entity);
    }

    // Add the entity to the hash table for efficient lookups
    user_group_map->table[user_group_hash(entity->name)] = entity;
}

// Function to add a user to the linked list and hash table.
void add_user(struct UserList *users, struct Entity *entity) {
    // Add the entity to the head of the linked list
    users->tail->next = entity;
    users->tail = entity;

    // Increment the size of the linked list and hash table accordingly
    ++users->size;
}

// Function to add a group to the linked list and hash table.
void add_group(struct GroupList *groups, struct Entity *entity) {
    // Add the entity to the head of the linked list
    groups->tail->next = entity;
    groups->tail = entity;

    // Increment the size of the linked list and hash table accordingly
    ++groups->size;
}

// Function to add a permission to the linked list and hash table.
void add_permission(struct PermissionList *permissions, struct Entity *entity) {
