    for (uint16_t i = 0; i < num_elements; i++) {
        crc_indication_pdu_list[i].RX_UE_INFORMATION_TAG = 0x01;
    }

    // Set the CRC_INDICATION_REL8_TAG for each PDU to a pseudo-random value
    srand(seed);
    for (uint16_t i = 0; i < num_elements; i++) {
