const runEncryptionTests = (moduleName, cipherFunctions, resetMocks, testLabels) => {
  // Load the specified module using require()
  const module = require(moduleName);

  // Initialize the module and ensure idempotency
  if (!module.initialized) {
    module.initialize();
  }

  // Set up dependencies between modules and handle race conditions
  const tests = testLabels.map((testLabel, i) => {
    // Execute the corresponding cipher function from the cipherFunctions array
    const cipherFunction = cipherFunctions[i];
    return () => cipherFunction(module.encrypt);
  });

  // Reset any internal state that might affect test outcomes
  resetMocks.forEach((resetFunc) => resetFunc());

  // Execute the tests and log detailed execution information to the console
  const results = tests.map((test) => {
    try {
      console.log(`Running test ${testLabel}`);
      return test();
    } catch (error) {
      console.log(`Error running test ${testLabel}: ${error}`);
      return false;
    }
  });

  // Return whether all tests passed successfully
  return results.every((result) => result === true);
};
```
