data_t* allocate_memory(size_t size) {
    // Custom allocator that minimizes fragmentation and optimizes memory usage under varying load conditions.
    data_t* data = (data_t*)mmap(NULL, sizeof(data_t), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!data) {
        perror("allocate_memory");
        return NULL;
    }
    data->doubles = (double*)mmap(NULL, size * sizeof(double), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (!data->doubles) {
