// Function to load configuration from JSON file
void load_configuration(const char* filename, Config* config) {
    // Open JSON file and read contents into buffer
    FILE* fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error opening configuration file.\n");
        return;
    }
    fseek(fp, 0L, SEEK_END);
    long bufsize = ftell(fp);
    fseek(fp, 0L, SEEK_SET);
    char* buffer = (char*)malloc(bufsize + 1);
    if (!buffer) {
        printf("Error allocating memory for configuration file.\n");
        return;
    }
    size_t read = fread(buffer, bufsize, 1, fp);
    if (read < bufsize) {
        printf("Error reading configuration file.\n");
        return;
    }
    buffer[bufsize] = '\0';

    // Parse JSON contents into config structure
    cJSON* root = cJSON_Parse(buffer);
    if (!root) {
        printf("Invalid configuration format.\n");
        free(buffer);
        return;
    }
    config->tileSize = cJSON_GetObjectItemCaseSensitive(root, "tileSize")->valueint;
    config->width = cJSON_GetObjectItemCaseSensitive(root, "width")->valueint;
    config->height = cJSON_GetObjectItemCaseSensitive(root, "height")->valueint;
    config->cameraSpeed = cJSON_GetObjectItemCaseSensitive(root, "cameraSpeed")->valuedouble;
    config->validRangeMin = cJSON_GetObjectItemCaseSensitive(root, "validRangeMin")->valueint;
    config->validRangeMax = cJSON_GetObjectItemCaseSensitive(root, "validRangeMax")->valueint;

    // Close JSON file and free buffer
    fclose(fp);
    free(buffer);
}

