        printf("Error allocating memory for offset array.\n");
        return;
    }

    // Initialize offset array with random values within valid range
    srand(time(NULL));
    for (int i = 0; i < config->tileSize; i++) {
        (*offsets)[i] = rand() % (config->validRangeMax - config->validRangeMin + 1) + config->validRangeMin;
    }

    // Allocate memory for key array based on predefined pattern or input source
    *keys = (int*)malloc(config->width * config->height * sizeof(int));
    if (!(*keys)) {
        printf("Error allocating memory for key array.\n");
        return;
    }

    // Initialize key array with predefined pattern or input source
    // ...
}

// Function to allocate and initialize memory for an array of records with a single int field
