NFAPI_CRC_INDICATION_PDU_T* allocate_crc_indication_array(uint16_t n) {
  // Check if the given number of elements exceeds the maximum allowed size
  if (n > 65535) {
    printf("Error: Too many elements in CRC indication array\n");
    return NULL;
  }

  // Allocate memory for the array
  NFAPI_CRC_INDICATION_PDU_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
  if (array == NULL) {
    printf("Error: Failed to allocate memory for CRC indication array\n");
    return NULL;
  }

  // Populate the array with unique RNTIs and CRCFLAG values
  for (uint16_t i = 0; i < n; i++) {
    uint16_t RX_UE_INFORMATION_TAG = i + 1;
    uint16_t RNTI = rand() % 0xFFFF;
    while (RNTI == 0 || is_duplicate(RNTI, array, i)) {
      RNTI = rand() % 0xFFFF;
    }
    uint8_t CRCFLAG = rand() % 2;
    array[i].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    array[i].RNTI = RNTI;
    array[i].CRCFLAG = CRCFLAG;
  }

  return array;
}

bool is_duplicate(uint16_t RNTI, NFAPI_CRC_INDICATION_PDU_T* array, uint16_t index) {
  for (uint16_t i = 0; i < index; i++) {
    if (array[i].RNTI == RNTI) {
      return true;
    }
  }
  return false;
}

void deallocate_crc_indication_array(NFAPI_CRC_INDICATION_PDU_T* array) {
  free(array);
}
