#define MAX_STRUCTS 10000
#define RX_UE_INFORMATION_TAG 0x01
#define RNTI 0xFFFF
#define CRC_INDICATION_REL8_TAG 0x02

typedef struct {
    unsigned short rx_ue_information_tag;
    unsigned int rnti;
    unsigned char crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t allocation_mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_structs = 0;
static int max_structs = MAX_STRUCTS;
static unsigned short *cached_rnti = NULL;

void* allocate_nfapi_crc_indication_pdu(int n) {
    if (n <= 0 || n > max_structs) {
        return NULL;
    }

    pthread_mutex_lock(&allocation_mutex);

    NFAPI_CRC_INDICATION_PDU_T* structs = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
    if (structs == NULL) {
        pthread_mutex_unlock(&allocation_mutex);
        return NULL;
    }

    num_structs += n;

    for (int i = 0; i < n; i++) {
        structs[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        structs[i].rnti = rand() % RNTI;
        structs[i].crc_indication_rel8_tag = CRC_INDICATION_REL8_TAG;
    }

    pthread_mutex_unlock(&allocation_mutex);

    return structs;
}

void free_nfapi_crc_indication_pdu(void* ptr) {
    if (ptr == NULL) {
        return;
    }

    pthread_mutex_lock(&allocation_mutex);

    int n = num_structs - 1;
    NFAPI_CRC_INDICATION_PDU_T* structs = ptr;
    for (int i = 0; i < n; i++) {
        if (structs[i].rnti == cached_rnti) {
            free(cached_rnti);
            cached_rnti = NULL;
            break;
        }
    }

    num_structs -= n;

    pthread_mutex_unlock(&allocation_mutex);

    free(ptr);
}
```
