#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

#define MAX_CRC_INDICATIONS 100000
#define CLEANUP_THRESHOLD 50000

typedef struct {
    RX_UE_INFORMATION_TAG *rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG *crc_indication_rel8;
    void *payload_data;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage a dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *crc_indications = NULL;
size_t crc_indication_count = 0;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Background worker thread for cleaning up old or unused structures
void *cleanup_worker(void *arg) {
    while (1) {
        pthread_mutex_lock(&mutex);
        if (crc_indication_count < CLEANUP_THRESHOLD) {
            // If the list is not large enough, wait for more elements to be added
            pthread_cond_wait(&cond, &mutex);
            continue;
        }

        // Find the oldest structure in the list
        size_t oldest = 0;
        time_t current_time = time(NULL);
        for (size_t i = 1; i < crc_indication_count; i++) {
            if (current_time - crc_indications[i].rx_ue_information->timestamp >
                current_time - crc_indications[oldest].rx_ue_information->timestamp) {
                oldest = i;
            }
        }

        // Reallocate the list to remove the oldest structure
        NFAPI_CRC_INDICATION_PDU_T *new_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - 1));
        if (!new_list) {
            // If memory allocation fails, attempt to reallocate with a smaller size
            new_list = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - 1));
            if (!new_list) {
                // If the allocation still fails, log an error and continue
                perror("Failed to allocate memory for CRC indications");
                pthread_mutex_unlock(&mutex);
                continue;
            }
        }
        memcpy(new_list, crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - 1));
        free(crc_indications);
        crc_indications = new_list;
        crc_indication_count--;

        pthread_mutex_unlock(&mutex);
    }
}

void add_crc_indication(RX_UE_INFORMATION_TAG *rx_ue_information, RNTI rnti, CRC_INDICATION_REL8_TAG *crc_indication_rel8, void *payload_data) {
    pthread_mutex_lock(&mutex);
    if (crc_indication_count == MAX_CRC_INDICATIONS) {
        // If the list is full, attempt to reallocate with a larger size
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_CRC_INDICATIONS + 1));
        if (!new_list) {
            // If the allocation fails, log an error and do not add the new structure
            perror("Failed to allocate memory for CRC indications");
            pthread_mutex_unlock(&mutex);
            return;
        }
        crc_indications = new_list;
    }

    // Add the new structure to the list
    crc_indications[crc_indication_count].rx_ue_information = rx_ue_information;
    crc_indications[crc_indication_count].rnti = rnti;
    crc_indications[crc_indication_count].crc_indication_rel8 = crc_indication_rel8;
    crc_indications[crc_indication_count].payload_data = payload_data;
    crc_indication_count++;

    // Signal the cleanup worker thread to clean up old structures
    pthread_cond_signal(&cond);
    pthread_mutex_unlock(&mutex);
}

void remove_crc_indications(size_t count) {
    pthread_mutex_lock(&mutex);
    if (count > crc_indication_count) {
        // If the count is larger than the number of structures in the list, clear all structures
        free(crc_indications);
        crc_indications = NULL;
        crc_indication_count = 0;
    } else {
        NFAPI_CRC_INDICATION_PDU_T *new_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - count));
        if (!new_list) {
            // If memory allocation fails, attempt to reallocate with a smaller size
            new_list = realloc(crc_indications, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - count));
            if (!new_list) {
                // If the allocation fails, log an error and do not remove any structures
                perror("Failed to allocate memory for CRC indications");
                pthread_mutex_unlock(&mutex);
                return;
            }
        }
        memcpy(new_list, crc_indications + count, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (crc_indication_count - count));
        free(crc_indications);
        crc_indications = new_list;
        crc_indication_count -= count;
    }
    pthread_mutex_unlock(&mutex);
}

void clear_crc_indications() {
    pthread_mutex_lock(&mutex);
    free(crc_indications);
    crc_indications = NULL;
    crc_indication_count = 0;
    pthread_mutex_unlock(&mutex);
}
