#define HASH_TABLE_SIZE 1024 // must be a power of 2
#define MAX_EMAIL_LENGTH 256
#define MAX_ID_LENGTH 32
#define MAX_PASSWORD_LENGTH 64
#define MAX_SUB_ACTION_LENGTH 32
#define MIN_RETRY_INTERVAL 1 // in seconds
#define MAX_RETRY_ATTEMPTS 5
