struct user {
    char id[MAX_ID_LENGTH];
    char name[MAX_NAME_LENGTH];
    char email[MAX_EMAIL_LENGTH];
    char password[MAX_PASSWORD_LENGTH];
    int sub_action;
};

struct hash_table {
    struct user* users;
    int size;
};

struct distributed_lock {
    pthread_mutex_t mutex;
    semaphore_t semaphore;
};

struct cache {
    struct user** entries;
    int size;
    int capacity;
};

// custom hash function for user IDs
unsigned long long get_hash(const char* id) {
    unsigned long long h = 0;
    for (int i = 0; id[i]; ++i) {
        h += id[i] * (i + 1);
    }
    return h % HASH_TABLE_SIZE;
}

// create a new hash table with the specified size
struct hash_table* hash_table_create(int size) {
    struct hash_table* ht = malloc(sizeof(struct hash_table));
    if (!ht) {
        return NULL;
    }
    ht->users = malloc(size * sizeof(struct user*));
    if (!ht->users) {
        free(ht);
        return NULL;
    }
    for (int i = 0; i < size; ++i) {
        ht->users[i] = NULL;
    }
    ht->size = size;
    return ht;
}

// destroy the hash table and free its memory
void hash_table_destroy(struct hash_table* ht) {
    for (int i = 0; i < ht->size; ++i) {
        if (ht->users[i]) {
            free(ht->users[i]);
        }
    }
    free(ht->users);
    free(ht);
}

// add a new user to the hash table or update an existing one
void hash_table_add(struct hash_table* ht, struct user* u) {
    int index = get_hash(u->id);
    if (ht->users[index]) {
        // update existing user
        ht->users[index]->name = u->name;
        ht->users[index]->email = u->email;
        ht->users[index]->password = u->password;
        ht->users[index]->sub_action = u->sub_action;
    } else {
        // add new user
        int i;
        for (i = 0; i < ht->size; ++i) {
            if (!ht->users[i]) {
                break;
            }
        }
        if (i == ht->size) {
            // hash table is full, need to resize it
            struct hash_table* new_ht = hash_table_create(ht->size * 2);
            if (!new_ht) {
                return;
            }
            for (int j = 0; j < ht->size; ++j) {
                if (ht->users[j]) {
                    new_ht->users[j] = malloc(sizeof(struct user));
                    memcpy(new_ht->users[j], ht->users[j], sizeof(struct user));
                }
            }
            hash_table_destroy(ht);
            ht = new_ht;
        }
        ht->users[i] = malloc(sizeof(struct user));
        if (!ht->users[i]) {
            return;
        }
        memcpy(ht->users[i], u, sizeof(struct user));
    }
}

// delete a user from the hash table
void hash_table_delete(struct hash_table* ht, const char* id) {
    int index = get_hash(id);
    if (ht->users[index]) {
        free(ht->users[index]);
        ht->users[index] = NULL;
    }
}

// check if a user ID exists in the hash table
int hash_table_exists(struct hash_table* ht, const char* id) {
    int index = get_hash(id);
    return ht->users[index];
}

// get a user from the hash table by ID
struct user* hash_table_get(struct hash_table* ht, const char* id) {
    int index = get_hash(id);
    if (ht->users[index]) {
        return ht->users[index];
    } else {
        return NULL;
    }
}

// create a new distributed lock object
struct distributed_lock* distributed_lock_create() {
    struct distributed_lock* dl = malloc(sizeof(struct distributed_lock));
    if (!dl) {
        return NULL;
    }
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_setpshared(&attr, PTHREAD_PROCESS_SHARED);
    pthread_mutex_init(&dl->mutex, &attr);
    semaphore_create(&dl->semaphore, 1);
    return dl;
}

// destroy the distributed lock object and free its memory
void distributed_lock_destroy(struct distributed_lock* dl) {
    pthread_mutex_destroy(&dl->mutex);
    semaphore_destroy(&dl->semaphore);
    free(dl);
}

// acquire the distributed lock
int distributed_lock_acquire(struct distributed_lock* dl) {
    return pthread_mutex_lock(&dl->mutex);
}

// release the distributed lock
void distributed_lock_release(struct distributed_lock* dl) {
    pthread_mutex_unlock(&dl->mutex);
}

// wait on the distributed lock with a timeout
int distributed_lock_wait(struct distributed_lock* dl, int ms) {
    return semaphore_wait(&dl->semaphore, ms);
}

// signal that we have acquired the distributed lock
void distributed_lock_signal(struct distributed_lock* dl) {
    semaphore_signal(&dl->semaphore);
}

// check if we have acquired the distributed lock
int distributed_lock_held(struct distributed_lock* dl) {
    return pthread_mutex_owned(&dl->mutex);
}

// create a new cache object with the specified size and hash function
struct cache* cache_create(size_t size, int (*hash)(void*)) {
    struct cache* c = malloc(sizeof(struct cache));
    if (!c) {
        return NULL;
    }
    c->size = size;
    c->capacity = 0;
    c->hash = hash;
    c->buckets = calloc(size, sizeof(struct bucket*));
    if (!c->buckets) {
        free(c);
        return NULL;
    }
    return c;
}

// destroy the cache object and free its memory
void cache_destroy(struct cache* c) {
    for (int i = 0; i < c->capacity; ++i) {
        if (c->buckets[i]) {
            cache_remove(c, c->buckets[i]->key);
        }
    }
    free(c->buckets);
    free(c);
}

// insert a new key-value pair into the cache
int cache_insert(struct cache* c, void* key, void* value) {
    if (cache_contains(c, key)) {
        return 0;
    }
    struct bucket* b = malloc(sizeof(struct bucket));
    if (!b) {
        return -1;
    }
    b->key = key;
    b->value = value;
    c->buckets[c->capacity++] = b;
    if (c->capacity == c->size) {
        // cache is full, need to evict an item
        struct bucket* eb = NULL;
        int min_hash = INT_MAX;
        for (int i = 0; i < c->size; ++i) {
            if (!c->buckets[i]) {
                continue;
            }
            int hash = c->hash(c->buckets[i]->key);
            if (hash < min_hash) {
                eb = c->buckets[i];
                min_hash = hash;
            }
        }
        free(eb);
    }
}

// remove a key-value pair from the cache
int cache_remove(struct cache* c, void* key) {
    for (int i = 0; i < c->capacity; ++i) {
        if (!c->buckets[i]) {
            continue;
        }
        if (c->hash(c->buckets[i]->key) == key) {
            free(c->buckets[i]);
            c->buckets[i] = NULL;
            return 0;
        }
    }
}

// check if a key-value pair exists in the cache
int cache_contains(struct cache* c, void* key) {
    for (int i = 0; i < c->capacity; ++i) {
        if (!c->buckets[i]) {
            continue;
        }
        if (c->hash(c->buckets[i]->key) == key) {
            return 1;
        }
    }
}

// get the value associated with a key in the cache
void* cache_get(struct cache* c, void* key) {
    for (int i = 0; i < c->capacity; ++i) {
        if (!c->buckets[i]) {
            continue;
        }
        if (c->hash(c->buckets[i]->key) == key) {
            return c->buckets[i]->value;
        }
    }
}

// cache statistics
struct cache_stats* cache_get_stats(struct cache* c) {
    struct cache_stats* stats = malloc(sizeof(struct cache_stats));
    if (!stats) {
        return NULL;
    }
    int hits = 0, misses = 0;
    for (int i = 0; i < c->capacity; ++i) {
        if (!c->buckets[i]) {
            continue;
        }
        if (c->hash(c->buckets[i]->key) == key) {
            hits++;
        } else {
            misses++;
        }
    }
    stats->hits = hits;
    stats->misses = misses;
}
