// Define the record structure
typedef struct record {
    int value;
    long* offset;
} Record;

// Define the dynamic array of records
struct record_array {
    // Pointer to the first element in the array
    Record* data;
    // Number of elements in the array
    size_t num_elements;
    // Size of each element in bytes
    size_t element_size;
};

// Define the file for logging memory usage and record statistics
static FILE* log_file = NULL;

// Function to initialize the dynamic array of records
void init_record_array(struct record_array* arr, size_t initial_size) {
    // Allocate memory for the array and set its pointer
    arr->data = (Record*)malloc(initial_size * sizeof(Record));
    if (!arr->data) {
        printf("Error: Could not allocate memory for record array.\n");
        exit(1);
    }
    // Set the number of elements to the initial size and the element size to the size of a single Record struct
    arr->num_elements = initial_size;
    arr->element_size = sizeof(Record);
}

// Function to add a new record to the dynamic array
void add_record(struct record_array* arr, int value, long offset) {
    // Check if the array needs to be resized
    if (arr->num_elements == arr->element_size / sizeof(Record)) {
        // Double the size of the array and reallocate memory for it
        arr->data = (Record*)realloc(arr->data, 2 * arr->element_size);
        if (!arr->data) {
            printf("Error: Could not resize record array.\n");
            exit(1);
        }
        // Update the number of elements and the element size
        arr->num_elements *= 2;
        arr->element_size = 2 * arr->element_size;
    }
    // Create a new record with the given value and offset and append it to the array
    Record* rec = (Record*)malloc(sizeof(Record));
    if (!rec) {
        printf("Error: Could not allocate memory for new record.\n");
        exit(1);
    }
    rec->value = value;
    rec->offset = offset;
    arr->data[arr->num_elements++] = *rec;
}

// Function to remove a record from the dynamic array by its index
void remove_record(struct record_array* arr, int index) {
    // Check if the index is valid
    if (index < 0 || index >= arr->num_elements) {
        printf("Error: Invalid record index.\n");
        exit(1);
    }
    // Shift all records after the specified index to the left by one position
    for (int i = index + 1; i < arr->num_elements; i++) {
        arr->data[i - 1] = arr->data[i];
    }
    // Decrease the number of elements in the array
    arr->num_elements--;
}

// Function to update a record by its index with a new value and offset
void update_record(struct record_array* arr, int index, int value, long offset) {
    // Check if the index is valid
    if (index < 0 || index >= arr->num_elements) {
        printf("Error: Invalid record index.\n");
        exit(1);
    }
    // Update the record with the new value and offset
    Record* rec = &arr->data[index];
    rec->value = value;
    rec->offset = offset;
}

// Function to print all records in the dynamic array
void print_records(struct record_array* arr) {
    // Loop through each record and print its value and offset
    for (int i = 0; i < arr->num_elements; i++) {
        Record* rec = &arr->data[i];
        printf("Record %d: Value = %d, Offset = %ld\n", i, rec->value, *rec->offset);
    }
}

// Function to clean up memory and close the log file
void deinit_record_array(struct record_array* arr) {
    // Free all dynamically allocated memory for the array
    free(arr->data);
    // Close the log file if it was open
    if (log_file) {
        fclose(log_file);
    }
}
```
This code implements a dynamic array of `record` structures, where each record contains an integer value and a pointer to a dynamically allocated long offset value. The array is initialized with an initial size, and the function to add a new record doubles the size of the array when it needs to be resized. The function to remove a record by its index shifts all records after the specified index to the left by one position and decreases the number of elements in the array. The function to update a record by its index updates the value and offset of the specified record with the new values. The function to print all records in the dynamic array loops through each record and prints its value and offset. Finally, the function to clean up memory and close the log file frees all dynamically allocated memory for the array and closes the log file if it was open.

