unsigned int myHashFunction(int id) {
    unsigned int hash = 0;
    for (int i = 0; i < sizeof(id); i++) {
        hash += ((unsigned char*)&id)[i] * (i + 1);
    }
    return hash % MEMORY_POOL_SIZE;
}

// Initialize the list and hash table with a specified number of items
