// Custom allocator for dynamic memory management in multi-threaded environment
void* custom_alloc(size_t size) {
    void *ptr = NULL;
    if (size > 0) {
        ptr = malloc(size);
        if (ptr == NULL) {
            printf("Failed to allocate %lu bytes\n", size);
            exit(1);
        }
    }
    return ptr;
}

// Custom deallocator for freeing memory allocated by custom_alloc()
void custom_dealloc(void* ptr) {
    if (ptr != NULL) {
        free(ptr);
    }
}

// Hash function for hashing keys to offsets in the hash table
unsigned long hash_function(int key) {
    return abs(key) % HASH_TABLE_SIZE;
}

// Data structure for storing offset and record values
typedef struct record {
    long offset;
    int value;
} record_t;

// Global variables for managing hash table and arrays
const size_t INITIAL_RECORD_COUNT = 100000; // initial number of records to allocate
const size_t GROWTH_FACTOR = 2; // factor by which to grow the record count when needed
const int MAX_KEY = 1000000000; // maximum key value for hashing
const unsigned long HASH_TABLE_SIZE = 10000000; // size of hash table in slots
record_t* records; // array of record structures
int* keys; // array of integer keys
long* offsets; // array of offset values
unsigned long* hash_table; // hash table mapping keys to offsets

// Function for initializing arrays and hashtable
void init(size_t record_count) {
    records = (record_t*)custom_alloc(sizeof(record_t) * record_count);
    keys = (int*)custom_alloc(sizeof(int) * record_count);
    offsets = (long*)custom_alloc(sizeof(long) * record_count);
    hash_table = (unsigned long*)custom_alloc(sizeof(unsigned long) * HASH_TABLE_SIZE);
    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        hash_table[i] = -1;
    }
}

// Function for populating arrays and hashtable with random data
void populate(size_t record_count) {
    for (size_t i = 0; i < record_count; i++) {
        int key = rand() % MAX_KEY; // generate integer key between 0 and MAX_KEY
        long offset = rand() % 100000000; // generate long offset value between 0 and 10^8
        record_t* rec = &records[i];
        rec->offset = offset;
        rec->value = key;
        keys[i] = key;
        offsets[i] = offset;
        hash_table[hash_function(key)] = i;
    }
}

// Function for adding a new record to the arrays and hashtable
void add_record(int key, long offset) {
    size_t index = hash_table[hash_function(key)];
    while (index != -1 && keys[index] != key) {
        index = hash_table[HASH_TABLE_SIZE + index];
    }
    if (index == -1) { // key not found in hashtable, add new record
        size_t i = hash_table[hash_function(key)];
        while (i != -1 && hash_table[i] != -1) {
            i = HASH_TABLE_SIZE + i;
        }
        if (i == -1) { // no available slots in hashtable, grow array
            size_t new_record_count = record_count * GROWTH_FACTOR;
            void* new_records = custom_alloc(sizeof(record_t) * new_record_count);
            void* new_keys = custom_alloc(sizeof(int) * new_record_count);
            void* new_offsets = custom_alloc(sizeof(long) * new_record_count);
            memcpy(new_records, records, sizeof(record_t) * record_count);
            memcpy(new_keys, keys, sizeof(int) * record_count);
            memcpy(new_offsets, offsets, sizeof(long) * record_count);
            custom_dealloc(records);
            records = (record_t*)new_records;
            custom_dealloc(keys);
            keys = (int*)new_keys;
            custom_dealloc(offsets);
            offsets = (long*)new_offsets;
            for (size_t i = record_count; i < new_record_count; i++) {
                hash_table[hash_function(i)] = -1;
            }
        } else { // found available slot in hashtable, add new record
            index = i;
            keys[index] = key;
            offsets[index] = offset;
            records[index].offset = offset;
            records[index].value = key;
            hash_table[hash_function(key)] = index;
        }
    } else { // key found in hashtable, update record
        offsets[index] = offset;
        records[index].offset = offset;
    }
}

// Function for querying a record from the arrays and hashtable
record_t* get_record(int key) {
    size_t index = hash_table[hash_function(key)];
    while (index != -1 && keys[index] != key) {
        index = hash_table[HASH_TABLE_SIZE + index];
    }
    if (index == -1) { // key not found in hashtable, return NULL
        return NULL;
    } else { // key found in hashtable, return record
        return &records[index];
    }
}

// Function for deleting a record from the arrays and hashtable
void delete_record(int key) {
    size_t index = hash_table[hash_function(key)];
    while (index != -1 && keys[index] != key) {
        index = hash_table[HASH_TABLE_SIZE + index];
    }
    if (index == -1) { // key not found in hashtable, return NULL
        return;
    } else { // key found in hashtable, delete record
        keys[index] = -1;
        offsets[index] = -1;
        records[index].offset = -1;
        records[index].value = -1;
        hash_table[hash_function(key)] = -1;
    }
}

// Main function for testing the add, get, and delete functions
int main() {
    init(10); // initialize arrays and hashtable with 10 records
    populate(10); // populate arrays and hashtable with random data
    add_record(5, 123456789); // add new record with key=5 and offset=123456789
    record_t* rec = get_record(5); // query record with key=5 from hashtable
    if (rec != NULL) {
        printf("Record found: %d, %ld\n", rec->value, rec->offset);
    } else {
        printf("Record not found\n");
    }
    delete_record(3); // delete record with key=3 from hashtable
    rec = get_record(3); // query record with key=3 from hashtable
    if (rec != NULL) {
        printf("Record found: %d, %ld\n", rec->value, rec->offset);
    } else {
        printf("Record not found\n");
    }
    return 0;
}
```
