  int num_packets; // Number of packets in the array
  pthread_mutex_t lock; // Mutex for synchronizing access to the hash table
} hash_table_t;

// Define a thread-safe function to add a new packet to the hash table
void add_packet(hash_table_t *ht, packet_t *pkt) {
  pthread_mutex_lock(&ht->lock); // Acquire the lock for the hash table

  // Check if the hash table is full and need to resize
  if (ht->num_packets >= 100) {
    printf("Resizing hash table...\n");
    ht = resize_hash_table(ht); // Resize the hash table and return a new one
  }

  // Add the packet to the end of the hash table
  ht->packets[ht->num_packets++] = pkt;

  pthread_mutex_unlock(&ht->lock); // Release the lock for the hash table
}

// Define a thread-safe function to update a packet in the hash table
void update_packet(hash_table_t *ht, uint32_t seq_num, packet_t *pkt) {
  pthread_mutex_lock(&ht->lock); // Acquire the lock for the hash table

  // Find the index of the packet in the hash table
  int i = find_packet(ht, seq_num);

  if (i >= 0) {
    // Update the payload and size fields of the packet
    ht->packets[i]->payload = pkt->payload;
    ht->packets[i]->size = pkt->size;

    printf("Packet %u updated\n", seq_num);
  } else {
    printf("Packet %u not found in the hash table\n", seq_num);
  }

  pthread_mutex_unlock(&ht->lock); // Release the lock for the hash table
}

// Define a thread-safe function to retrieve a packet from the hash table
void *get_packet(hash_table_t *ht, uint32_t seq_num) {
  pthread_mutex_lock(&ht->lock); // Acquire the lock for the hash table

  // Find the index of the packet in the hash table
  int i = find_packet(ht, seq_num);

  if (i >= 0) {
    // Return a pointer to the packet
    return ht->packets[i];
  } else {
    printf("Packet %u not found in the hash table\n", seq_num);
    return NULL;
  }

  pthread_mutex_unlock(&ht->lock); // Release the lock for the hash table
}

// Define a function to resize the hash table when it's full
hash_table_t *resize_hash_table(hash_table_t *ht) {
  int new_size = ht->num_packets * 2; // Double the size of the hash table

  // Allocate memory for the new hash table
  hash_table_t *new_ht = malloc(sizeof(hash_table_t));
  if (new_ht == NULL) {
    printf("Failed to allocate memory for the new hash table\n");
    return ht; // Return the old hash table on failure
  }

  // Initialize the mutex and lock for the new hash table
  pthread_mutex_init(&new_ht->lock, NULL);

  // Copy the contents of the old hash table to the new one
  memcpy(new_ht->packets, ht->packets, sizeof(packet_t *) * ht->num_packets);

  // Return the new hash table
  return new_ht;
}

// Define a function to find a packet in the hash table by sequence number
int find_packet(hash_table_t *ht, uint32_t seq_num) {
  for (int i = 0; i < ht->num_packets; i++) {
    if (ht->packets[i]->seq_num == seq_num) {
      return i; // Return the index of the packet
    }
  }

  return -1; // Return -1 if the packet is not found
}
