// Function to dynamically manage a list of NFAPI_CRC_INDICATION_PDU_T structures
void dynamic_list(int n) {
    // Initialize the linked list
    LIST *list = (LIST *)malloc(sizeof(LIST));
    list->head = NULL;
    list->tail = NULL;

    // Iterate through each structure in the list
    for (int i = 0; i < n; i++) {
