        if (list->head == NULL) {
            list->head = structure;
            list->tail = structure;
        } else {
            // Add the structure to the tail of the list
            list->tail->next = structure;
            list->tail = structure;
        }

        // Check if the current RNTI value is the same as the previous one, and skip adding it to the list if so
        if (i > 0 && list->head->RNTI == structure->RNTI) {
            continue;
