    // Print the contents of the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        printf("RX_UE_INFORMATION_TAG: %d\n", current->RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", current->RNTI);
        printf("CRCFLAG: %d\n", current->CRCFLAG);
        current = current->next;
