    // Initialize the configuration
    configuration.rx_ue_information_tag_start = 0x0100;
    configuration.rx_ue_information_tag_end = 0x7fff;
    configuration.enable_crc_indication = true;
}

/**
 * Allocate a new memory block from the memory pool.
 */
void* allocate(size_t size) {
    // Check if there is enough space in the pool to allocate the requested size
    if (memory_pool.num_allocated - memory_pool.num_used >= size / sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        void* new_block = malloc(size);
        return new_block;
    } else {
        // Reallocate the pool if it is full
        memory_pool.num_allocated += 10000;
        memory_pool.max_size += sizeof(NFAPI_CRC_INDICATION_PDU_T) * 10000;
        memory_pool.memory = realloc(memory_pool.memory, memory_pool.max_size);
    }
}

/**
 * Free a memory block from the memory pool.
 */
void free(void* block) {
    // Check if the block is in the pool and free it if so
    size_t index = (block - (void*)memory_pool.memory) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    if (index < memory_pool.num_allocated && memory_pool.memory[index] != NULL) {
        memory_pool.memory[index] = NULL;
        memory_pool.num_used--;
        free(block);
    } else {
        // Otherwise, do nothing and log a warning
        fprintf(stderr, "Warning: trying to free a non-existent block\n");
    }
}

/**
 * Reallocate the memory pool if necessary.
 */
void reallocate() {
    size_t new_size = memory_pool.num_allocated + 10000;
    void* new_memory = realloc(memory_pool.memory, new_size);
    if (new_memory != NULL) {
        memory_pool.memory = new_memory;
        memory_pool.max_size = new_size;
    } else {
        fprintf(stderr, "Error: failed to reallocate the memory pool\n");
    }
}

/**
 * Serialize a list of NFAPI_CRC_INDICATION_PDU_T structures into a binary format.
 */
void serialize(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
    // Check if the list is empty
    if (count == 0) return;

    // Initialize the serialization buffer
    uint8_t buffer[sizeof(NFAPI_CRC_INDICATION_PDU_T) * count];
    size_t offset = 0;

    // Serialize each structure in the list
    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];

        // Write the RX UE information tag to the buffer
        offset += write_uint16(buffer, offset, pdu->rx_ue_information_tag);

        // Write the data field to the buffer
        memcpy(buffer + offset, pdu->data, sizeof(pdu->data));
        offset += sizeof(pdu->data);
    }

    // Write the serialized buffer to a file or other output stream
    fwrite(buffer, 1, offset, stdout);
}

/**
 * Deserialize a list of NFAPI_CRC_INDICATION_PDU_T structures from a binary format.
 */
NFAPI_CRC_INDICATION_PDU_T* deserialize(size_t count) {
    // Check if the list is empty
    if (count == 0) return NULL;

    // Initialize the deserialization buffer
    uint8_t buffer[sizeof(NFAPI_CRC_INDICATION_PDU_T) * count];
    size_t offset = 0;

    // Deserialize each structure in the list
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];

        // Read the RX UE information tag from the buffer
        offset += read_uint16(buffer, offset, &pdu->rx_ue_information_tag);

        // Read the data field from the buffer
        memcpy(pdu->data, buffer + offset, sizeof(pdu->data));
        offset += sizeof(pdu->data);
    }

    return list;
}

/**
 * Write an unsigned 16-bit integer to a buffer.
 */
size_t write_uint16(void* buffer, size_t offset, uint16_t value) {
    ((uint8_t*)buffer)[offset + 0] = (value >> 8) & 0xff;
    ((uint8_t*)buffer)[offset + 1] = value & 0xff;
    return offset + sizeof(uint16_t);
}

/**
 * Read an unsigned 16-bit integer from a buffer.
 */
size_t read_uint16(void* buffer, size_t offset, uint16_t* value) {
    *value = ((uint8_t*)buffer)[offset + 0] << 8;
    *value |= ((uint8_t*)buffer)[offset + 1];
    return offset + sizeof(uint16_t);
}

/**
 * Check if a memory block is in the pool.
 */
bool in_pool(void* block) {
    size_t index = (block - (void*)memory_pool.memory) / sizeof(NFAPI_CRC_INDICATION_PDU_T);
    return index < memory_pool.num_allocated && memory_pool.memory[index] != NULL;
}

/**
 * Check if a RX UE information tag is in the allowed range.
 */
bool is_valid_tag(uint16_t tag) {
    return tag >= configuration.rx_ue_information_tag_start && tag <= configuration.rx_ue_information_tag_end;
}

/**
 * Check if a CRC information message is valid.
 */
bool is_valid_message(NFAPI_CRC_INDICATION_PDU_T* message) {
    return message->length > 0 && message->length <= sizeof(message->data);
}

/**
 * Parse a CRC information message and log any errors.
 */
void parse_message(NFAPI_CRC_INDICATION_PDU_T* message) {
    // Check if the message is valid
    if (!is_valid_message(message)) {
        fprintf(stderr, "Warning: invalid CRC information message\n");
        return;
    }

    // Check if the RX UE information tag is in the allowed range
    if (!is_valid_tag(message->rx_ue_information_tag)) {
        fprintf(stderr, "Warning: invalid RX UE information tag\n");
        return;
    }

    // Log the message as a warning if it is not valid
    fprintf(stderr, "Warning: %s\n", message->data);
}

/**
 * Main function.
 */
int main(int argc, char* argv[]) {
    // Initialize the memory pool and configuration
    initialize();

    // Serialize a list of NFAPI_CRC_INDICATION_PDU_T structures into a binary format
    serialize(list, count);

    // Deserialize a list of NFAPI_CRC_INDICATION_PDU_T structures from a binary format
    deserialize(count);

    // Clean up the memory pool and configuration
    cleanup();

    return 0;
}
