void dynamicMemoryManagement(long *offsetArray, int *keyArray, Record **recordArray) {
    // Memory allocation limits
    const int MEMORY_LIMIT = 1000000; // 1MB
    const int RECORDS_LIMIT = 10000000; // 10 million records

    // Initialize arrays and record structures
    offsetArray = (long *)malloc(sizeof(long) * RECORDS_LIMIT);
    keyArray = (int *)malloc(sizeof(int) * RECORDS_LIMIT);
    recordArray = (Record **)malloc(sizeof(Record *) * RECORDS_LIMIT);

    // Seed random number generator for value generation
    srand(time(NULL));

    // Loop through records and allocate memory for each one
    for (int i = 0; i < RECORDS_LIMIT; i++) {
        // Generate a unique key for the record
        do {
            int tempKey = rand() % 10000000; // Randomly generated key between 0 and 10 million
            bool duplicateFound = false;

            // Check if the key is already present in the key array
            for (int j = 0; j < i; j++) {
                if (tempKey == keyArray[j]) {
                    duplicateFound = true;
                    break;
                }
            }

            // If a duplicate was found, generate a new key and try again
            if (duplicateFound) continue;

            keyArray[i] = tempKey;
        } while (true);

        // Allocate memory for the record structure
        recordArray[i] = (Record *)malloc(sizeof(Record));
        recordArray[i]->key = keyArray[i];
        recordArray[i]->value = rand() % 10000000; // Randomly generated value between 0 and 10 million
    }

    // Periodically perform garbage collection to minimize memory usage over time
    for (int i = 0; i < RECORDS_LIMIT; i++) {
        if (recordArray[i]->value == 0) {
            free(recordArray[i]);
            recordArray[i] = NULL;
        }
    }

    // Deallocate memory when the function exits
    for (int i = 0; i < RECORDS_LIMIT; i++) {
        if (recordArray[i]) free(recordArray[i]);
    }
    free(offsetArray);
    free(keyArray);
    free(recordArray);
}
