// LTE_PHY_RX_FRAME structure definition
struct LTE_PHY_RX_FRAME {
    struct LTE_PHY_RX_SYMBOL* symbols;
    int num_symbols;
    float signal_strength;
};

// LTE_PHY_RX_SYMBOL structure definition
struct LTE_PHY_RX_SYMBOL {
    int modulation_type;
    float phase_rotation;
    float noise_variance;
};

// Dynamic array of LTE_PHY_RX_FRAME structures
static struct LTE_PHY_RX_FRAME* frames = NULL;

// Number of frames in the dynamic array
static int num_frames = 0;

// Mutex for protecting the access to the dynamic array
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and manage a dynamic array of LTE_PHY_RX_FRAME structures
void init_frames(int num_frames) {
    // Allocate memory for the dynamic array of frames
    this->frames = (struct LTE_PHY_RX_FRAME*)malloc(num_frames * sizeof(struct LTE_PHY_RX_FRAME));

    // Initialize each frame with a list of symbols and a valid header
    for (int i = 0; i < num_frames; i++) {
        this->frames[i].symbols = (struct LTE_PHY_RX_SYMBOL*)malloc(sizeof(struct LTE_PHY_RX_SYMBOL) * num_symbols);
        this->frames[i].num_symbols = num_symbols;
    }
}

// Function to add a new frame to the dynamic array
void add_frame(struct LTE_PHY_RX_FRAME* frame) {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Check if there is enough memory for a new frame
    if (num_frames >= this->frames.size()) {
        // Increase the size of the dynamic array by 50% to accommodate new frames
        int old_size = this->frames.size();
        this->frames.resize(old_size + old_size / 2);
    }

    // Copy the frame data into the next available slot in the dynamic array
    memcpy(&this->frames[num_frames], frame, sizeof(struct LTE_PHY_RX_FRAME));

    // Increment the number of frames
    num_frames++;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to get a frame from the dynamic array by index
struct LTE_PHY_RX_FRAME* get_frame(int index) {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < 0 || index >= num_frames) {
        return NULL;
    }

    // Return a pointer to the frame at the specified index in the dynamic array
    struct LTE_PHY_RX_FRAME* frame = &this->frames[index];

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);

    return frame;
}

// Function to get the number of frames in the dynamic array
int num_frames() {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Return the number of frames in the dynamic array
    int count = this->num_frames;

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);

    return count;
}

// Function to serialize a frame to a binary file
void serialize_frame(struct LTE_PHY_RX_FRAME* frame, FILE* fp) {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Write the size of the frame to the file
    int size = sizeof(struct LTE_PHY_RX_FRAME) + (sizeof(struct LTE_PHY_RX_SYMBOL) * frame->num_symbols);
    fwrite(&size, sizeof(int), 1, fp);

    // Write the data of the frame to the file
    fwrite(frame, size, 1, fp);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}

// Function to deserialize a frame from a binary file
struct LTE_PHY_RX_FRAME* deserialize_frame(FILE* fp) {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Read the size of the frame from the file
    int size;
    fread(&size, sizeof(int), 1, fp);

    // Allocate memory for the frame
    struct LTE_PHY_RX_FRAME* frame = (struct LTE_PHY_RX_FRAME*)malloc(size);

    // Read the data of the frame from the file
    fread(frame, size, 1, fp);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);

    return frame;
}

// Function to free memory used by a frame
void free_frame(struct LTE_PHY_RX_FRAME* frame) {
    // Lock the mutex to prevent concurrent access to the dynamic array
    pthread_mutex_lock(&mutex);

    // Free the memory used by the symbols in the frame
    for (int i = 0; i < frame->num_symbols; i++) {
        free(frame->symbols[i]);
    }

    // Free the memory used by the frame
    free(frame);

    // Unlock the mutex and return
    pthread_mutex_unlock(&mutex);
}']

