// Custom hash function for identifiers
unsigned long custom_hash(const void* key) {
    unsigned long hash = 5381;
    const char* str = (const char*)key;
    int c;
    while ((c = *str++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash;
}

// Item structure for storing data
typedef struct {
    char* id;
    long timestamp;
    int value;
} Item;

// Record structure for storing items in the list
typedef struct {
    Item item;
    bool used;
} Record;

// List structure for managing the items
typedef struct {
    Record* records;
    long count;
    pthread_mutex_t mutex;
} List;

// Initialize a new list with a given capacity
List* init_list(long capacity) {
    List* list = (List*)malloc(sizeof(List));
    if (!list) return NULL;

    list->records = (Record*)malloc(capacity * sizeof(Record));
    if (!list->records) {
        free(list);
        return NULL;
    }

    memset(list->records, 0, capacity * sizeof(Record));
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

// Add a new item to the list
bool add_item(List* list, const char* id, long timestamp, int value) {
    // Check if the item already exists in the list
    for (long i = 0; i < list->count; i++) {
        if (!strcmp(list->records[i].item.id, id)) return false;
    }

    // Get a new record and populate it with data
    Record* record = &list->records[list->count];
    record->used = true;
    record->item.id = (char*)malloc(strlen(id) + 1);
    strcpy(record->item.id, id);
    record->item.timestamp = timestamp;
    record->item.value = value;

    // Add the item to the hash table and increase the count
    pthread_mutex_lock(&list->mutex);
    list->records[custom_hash(id) & (list->count - 1)].used = true;
    list->count++;
    pthread_mutex_unlock(&list->mutex);

    return true;
}

// Get an item from the list by its id
Item* get_item(List* list, const char* id) {
    for (long i = 0; i < list->count; i++) {
        if (!strcmp(list->records[i].item.id, id)) return &list->records[i].item;
    }
    return NULL;
}

// Remove an item from the list by its id
void remove_item(List* list, const char* id) {
    for (long i = 0; i < list->count; i++) {
        if (!strcmp(list->records[i].item.id, id)) {
            // Mark the record as unused and decrease the count
            pthread_mutex_lock(&list->mutex);
            list->records[i].used = false;
            list->count--;
            pthread_mutex_unlock(&list->mutex);

            // Free the memory used by the id and value strings
            free(list->records[i].item.id);
            return;
        }
    }
}

// Check if an item exists in the list by its id
bool contains_item(List* list, const char* id) {
    for (long i = 0; i < list->count; i++) {
        if (!strcmp(list->records[i].item.id, id)) return true;
    }
    return false;
}

// Clear the list and release all memory
void clear_list(List* list) {
    for (long i = 0; i < list->count; i++) {
        // Free the memory used by the id and value strings
        free(list->records[i].item.id);
    }
    pthread_mutex_destroy(&list->mutex);
    free(list->records);
    free(list);
}
