// Define a struct to store a record
struct record {
    int value;
    long offset;
};

// Define a struct to store the hash table and its metadata
struct hash_table {
    // Array of records
    struct record **records;

    // Array of offsets for fast lookup
    long *offsets;

    // Hash function for mapping keys to offsets
    uint32_t (*hash_func)(uint32_t);

    // Size of the hash table in terms of number of records
    size_t capacity;

    // Number of elements in the hash table
    size_t count;

    // Lock to protect concurrent access
    pthread_mutex_t lock;
};

// Define a struct to store the hash table and its metadata
struct hash_table *create_hash_table(size_t capacity, uint32_t (*hash_func)(uint32_t)) {
    // Allocate memory for the hash table and its metadata
    struct hash_table *ht = malloc(sizeof(struct hash_table));
    ht->records = malloc(capacity * sizeof(struct record*));
    ht->offsets = malloc(capacity * sizeof(long));
    ht->hash_func = hash_func;
    ht->capacity = capacity;
    ht->count = 0;
    pthread_mutex_init(&ht->lock, NULL);

    // Initialize the arrays to store records and offsets
    for (size_t i = 0; i < capacity; i++) {
        ht->records[i] = NULL;
        ht->offsets[i] = -1;
    }

    return ht;
}

// Define a function to insert a record into the hash table
int insert_record(struct hash_table *ht, int key, long offset) {
    // Check if the hash table is full
    if (ht->count >= ht->capacity) {
        return -1;
    }

    // Generate a random value for the record
    struct record r = {rand() % 100, offset};

    // Compute the index where the record should be stored
    size_t idx = ht->hash_func(key) % ht->capacity;

    // While the slot is occupied and there are no collisions, try to find a new index
    while (ht->records[idx] != NULL && ht->offsets[idx] == key) {
        idx = (idx + 1) % ht->capacity;
    }

    // If the slot is occupied and there are collisions, resize the hash table
    if (ht->records[idx] != NULL) {
        resize_hash_table(ht);
        idx = ht->hash_func(key) % ht->capacity;
    }

    // Insert the record into the hash table
    ht->records[idx] = &r;
    ht->offsets[idx] = key;

    return 0;
}

// Define a function to delete a record from the hash table
int delete_record(struct hash_table *ht, int key) {
    // Compute the index of the record to be deleted
    size_t idx = ht->hash_func(key) % ht->capacity;

    // While the slot is occupied and there are no collisions, try to find the correct record
    while (ht->records[idx] != NULL && ht->offsets[idx] != key) {
        idx = (idx + 1) % ht->capacity;
    }

    // If the slot is occupied and there are no collisions, delete the record
    if (ht->records[idx] != NULL && ht->offsets[idx] == key) {
        ht->records[idx] = NULL;
        ht->offsets[idx] = -1;
        return 0;
    } else {
        return -1;
    }
}

// Define a function to lookup a record in the hash table
int lookup_record(struct hash_table *ht, int key, struct record **r) {
    // Compute the index of the record to be looked up
    size_t idx = ht->hash_func(key) % ht->capacity;

    // While the slot is occupied and there are no collisions, try to find the correct record
    while (ht->records[idx] != NULL && ht->offsets[idx] != key) {
        idx = (idx + 1) % ht->capacity;
    }

    // If the slot is occupied and there are no collisions, return the record
    if (ht->records[idx] != NULL && ht->offsets[idx] == key) {
        *r = ht->records[idx];
        return 0;
    } else {
        return -1;
    }
}

// Define a function to resize the hash table when it's full
void resize_hash_table(struct hash_table *ht) {
    // Double the size of the hash table
    ht->capacity *= 2;

    // Reallocate memory for the hash table and its metadata
    struct record **new_records = realloc(ht->records, ht->capacity * sizeof(struct record*));
    long *new_offsets = realloc(ht->offsets, ht->capacity * sizeof(long));

    // Initialize the new arrays to store records and offsets
    for (size_t i = 0; i < ht->capacity; i++) {
        new_records[i] = NULL;
        new_offsets[i] = -1;
    }

    // Copy the records and offsets from the old hash table to the new one
    for (size_t i = 0; i < ht->capacity / 2; i++) {
        if (ht->records[i] != NULL) {
            struct record *r = ht->records[i];
            size_t idx = ht->hash_func(r->key) % ht->capacity;
            while (new_records[idx] != NULL && new_offsets[idx] == r->key) {
                idx = (idx + 1) % ht->capacity;
            }
            new_records[idx] = r;
            new_offsets[idx] = r->key;
        }
    }

    // Free the memory of the old hash table and replace it with the new one
    free(ht->records);
    free(ht->offsets);
    ht->records = new_records;
    ht->offsets = new_offsets;
}

// Define a function to print the contents of the hash table
void print_hash_table(struct hash_table *ht) {
    // Print the records and offsets in the hash table
    for (size_t i = 0; i < ht->capacity; i++) {
        if (ht->records[i] != NULL && ht->offsets[i] != -1) {
            printf("Record: %d, Offset: %ld\n", ht->records[i]->key, ht->offsets[i]);
        }
    }
}
