### Solution 2 (Simple Hash Table Implementation Using Arrays)

The hash table in this solution is implemented using arrays. An array of size `MAX_RECORDS` is used to store the records, and an array of size `MAX_RECORDS` is used to store the offsets. The records are stored in the array at indices determined by a hash function, and the offsets are stored in the corresponding index in the offset array. When the hash table becomes full, the array is doubled in size and the records and offsets are rehashed into the new array.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the constants for the maximum number of records and the hash table size
#define MAX_RECORDS 1000
#define HASH_SIZE 32768

// Define a structure to store the records
struct record {
    int key;
    long offset;
};

// Define a function to compute the hash value of a given key
int hash(int key) {
    return key % HASH_SIZE;
}

// Define a function to insert a record into the hash table
void insert(struct record *r, struct record **ht, int *capacity) {
    // Compute the index where the record should be stored
    int idx = hash(r->key);

    // While the slot is occupied and there are no collisions, try to find a new index
    while (ht[idx] != NULL && ht[idx]->key == r->key) {
        idx = (idx + 1) % (*capacity);
    }

    // If the slot is occupied and there are collisions, resize the hash table
    if (ht[idx] != NULL) {
        *capacity *= 2;
        struct record **new_ht = realloc(ht, (*capacity) * sizeof(struct record*));
        int new_size = *capacity / 2;
        for (int i = 0; i < new_size; i++) {
            if (ht[i] != NULL) {
                struct record *new_r = malloc(sizeof(struct record));
                new_r->key = ht[i]->key;
                new_r->offset = ht[i]->offset;
                new_ht[i] = new_r;
            } else {
                new_ht[i] = NULL;
            }
        }
        free(ht);
        ht = new_ht;
    }

    // Store the record in the hash table at the computed index
    ht[idx] = r;
}

// Define a function to search for a record in the hash table
struct record *search(int key, struct record **ht) {
    // Compute the index where the record should be stored
    int idx = hash(key);

    // If the slot is occupied and the key matches, return the record
    if (ht[idx] != NULL && ht[idx]->key == key) {
        return ht[idx];
    }

    // If the slot is occupied but the key does not match, try to find it in the next index
    while (ht[idx] != NULL && ht[idx]->key != key) {
        idx = (idx + 1) % HASH_SIZE;
    }

    // If the slot is still occupied but the key does not match, return NULL
    if (ht[idx] == NULL || ht[idx]->key != key) {
        return NULL;
    } else {
        return ht[idx];
    }
}

int main() {
    // Create an array to store the hash table
    struct record **ht = malloc(HASH_SIZE * sizeof(struct record*));

    // Initialize the hash table with NULL values
    for (int i = 0; i < HASH_SIZE; i++) {
        ht[i] = NULL;
    }

    // Insert some records into the hash table
    struct record *r1 = malloc(sizeof(struct record));
    r1->key = 23;
    r1->offset = 3000;
    insert(r1, ht, &HASH_SIZE);

    struct record *r2 = malloc(sizeof(struct record));
    r2->key = 45;
    r2->offset = 5000;
    insert(r2, ht, &HASH_SIZE);

    // Search for some records in the hash table
    struct record *result1 = search(23, ht);
    printf("Search result: %d\n", result1->offset);

    struct record *result2 = search(45, ht);
    printf("Search result: %ld\n", result2->offset);

    // Print the contents of the hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        if (ht[i] != NULL) {
            struct record *r = ht[i];
            printf("Record: %d, Offset: %ld\n", r->key, r->offset);
        }
    }

    return 0;
}
```

### Solution 3 (Advanced Hash Table Implementation Using Linked Lists)

The hash table in this solution is implemented using linked lists. Each slot in the hash table contains a pointer to a linked list of records with the same key. The insertion and search operations are performed by iterating through the linked lists in the hash table. When the hash table becomes full, the linked lists are rehashed into a new hash table with twice the size.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the constants for the maximum number of records and the hash table size
#define MAX_RECORDS 1000
#define HASH_SIZE 32768

// Define a structure to store the records
struct record {
    int key;
    long offset;
};

// Define a function to compute the hash value of a given key
int hash(int key) {
    return key % HASH_SIZE;
}

// Define a function to insert a record into the hash table
void insert(struct record *r, struct record **ht, int *capacity) {
    // Compute the index where the record should be stored
    int idx = hash(r->key);

    // If the slot is occupied and there are collisions, append the record to the linked list at the corresponding index
    if (ht[idx] != NULL && ht[idx]->key == r->key) {
        struct record *current = ht[idx];
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = malloc(sizeof(struct record));
        current->next->key = r->key;
        current->next->offset = r->offset;
    } else {
        // Store the record in the hash table at the computed index
        struct record *new_record = malloc(sizeof(struct record));
        new_record->key = r->key;
        new_record->offset = r->offset;
        new_record->next = NULL;
        ht[idx] = new_record;
    }
}

// Define a function to search for a record in the hash table
struct record *search(int key, struct record **ht) {
    // Compute the index where the record should be stored
    int idx = hash(key);

    // If the slot is occupied and the key matches, return the record
    if (ht[idx] != NULL && ht[idx]->key == key) {
        return ht[idx];
    }

    // If the slot is occupied but the key does not match, iterate through the linked list at the corresponding index until a matching record is found or the end of the list is reached
    struct record *current = ht[idx];
    while (current != NULL) {
        if (current->key == key) {
            return current;
        }
        current = current->next;
    }

    // If the slot is still occupied but the key does not match, or the end of the list has been reached without finding a matching record, return NULL
    return NULL;
}

int main() {
    // Create an array to store the hash table
    struct record **ht = malloc(HASH_SIZE * sizeof(struct record*));

    // Initialize the hash table with NULL values
    for (int i = 0; i < HASH_SIZE; i++) {
        ht[i] = NULL;
    }

    // Insert some records into the hash table
    struct record *r1 = malloc(sizeof(struct record));
    r1->key = 23;
    r1->offset = 3000;
    insert(r1, ht, &HASH_SIZE);

    struct record *r2 = malloc(sizeof(struct record));
    r2->key = 45;
    r2->offset = 5000;
    insert(r2, ht, &HASH_SIZE);

    // Search for some records in the hash table
    struct record *result1 = search(23, ht);
    printf("Search result: %d\n", result1->offset);

    struct record *result2 = search(45, ht);
    printf("Search result: %ld\n", result2->offset);

    // Print the contents of the hash table
    for (int i = 0; i < HASH_SIZE; i++) {
        if (ht[i] != NULL) {
            struct record *current = ht[i];
            printf("Record: %d, Offset: %ld\n", current->key, current->offset);
            while (current->next != NULL) {
                current = current->next;
                printf("Record: %d, Offset: %ld\n", current->key, current->offset);
            }
        }
    }

    return 0;
}
