struct node_cache {
    int size;
    struct node** nodes;
};

// Initialize the cache with a fixed size
void init_node_cache(struct node_cache* cache, int size) {
    cache->size = size;
    cache->nodes = malloc(sizeof(struct node*) * size);
}

// Add a new node to the cache
void add_node_to_cache(struct node_cache* cache, struct node* node) {
    int index = 0;
    while (index < cache->size && cache->nodes[index] != NULL) {
        if (strcmp(cache->nodes[index]->string, node->string) == 0) {
            // Node already exists in the cache, update its value and status
            cache->nodes[index]->value = node->value;
            cache->nodes[index]->status = node->status;
            return;
        }
        index++;
    }
    if (index == cache->size) {
        // Cache is full, remove the least recently used node
        free(cache->nodes[0]);
        memmove(cache->nodes, cache->nodes + 1, sizeof(struct node*) * (cache->size - 1));
        index = 0;
    }
    // Add the new node to the end of the cache
    cache->nodes[index] = malloc(sizeof(struct node));
    memcpy(cache->nodes[index], node, sizeof(struct node));
}

// Free all allocated memory for the cache
void free_node_cache(struct node_cache* cache) {
    int i;
    for (i = 0; i < cache->size && cache->nodes[i] != NULL; i++) {
        free(cache->nodes[i]);
    }
    free(cache->nodes);
