// Define a dynamic memory allocator for managing memory allocation and deallocation
struct MemoryAllocator {
  size_t allocated_memory; // total amount of memory allocated so far
  size_t max_memory; // maximum amount of memory that can be allocated
};

// Function to initialize the hash table with a specified capacity
void init_product_category_hash_table(ProductCategoryHashTable* table, int capacity) {
  assert(capacity > 0);
  table->size = 0;
  table->capacity = capacity;
  table->keys = (int*)malloc(sizeof(int) * capacity);
  table->values = (int*)malloc(sizeof(int) * capacity);
}

// Function to allocate memory dynamically for the data structures
void* malloc_memory(size_t size, MemoryAllocator* allocator) {
  assert(allocator != NULL);
  void* ptr = malloc(size);
  if (ptr == NULL) {
    // Handle memory allocation failure
    return NULL;
  }
  allocator->allocated_memory += size;
  if (allocator->allocated_memory > allocator->max_memory) {
    // Handle exceeding the maximum amount of memory that can be allocated
    free(ptr);
    return NULL;
  }
  return ptr;
}

// Function to deallocate memory dynamically for the data structures
void free_memory(void* ptr, MemoryAllocator* allocator) {
  assert(allocator != NULL);
  if (ptr == NULL) {
    // Handle invalid pointer argument
    return;
  }
  size_t size = malloc_usable_size(ptr);
  free(ptr);
  allocator->allocated_memory -= size;
}

// Function to initialize the data structures with a specified number of entities
void init_data_structures(int num_products, int num_categories, int num_reviews) {
  // Initialize product and category arrays
  struct Product* products = (struct Product*)malloc_memory(sizeof(struct Product) * num_products, NULL);
  if (products == NULL) {
    // Handle memory allocation failure
    return;
  }
  struct Category* categories = (struct Category*)malloc_memory(sizeof(struct Category) * num_categories, NULL);
  if (categories == NULL) {
    // Handle memory allocation failure
    free_memory(products, NULL);
    return;
  }

  // Initialize review array
  struct Review* reviews = (struct Review*)malloc_memory(sizeof(struct Review) * num_reviews, NULL);
  if (reviews == NULL) {
    // Handle memory allocation failure
    free_memory(products, NULL);
    free_memory(categories, NULL);
    return;
  }

  // Initialize hash table for mapping products to their respective categories
  ProductCategoryHashTable* product_category_hash_table = (ProductCategoryHashTable*)malloc_memory(sizeof(ProductCategoryHashTable), NULL);
  if (product_category_hash_table == NULL) {
    // Handle memory allocation failure
    free_memory(products, NULL);
    free_memory(categories, NULL);
    free_memory(reviews, NULL);
    return;
  }
  init_product_category_hash_table(product_category_hash_table, num_products);
}

// Function to populate the data structures with data read from an external database service
void populate_data_structures(int num_products, int num_categories, int num_reviews) {
  // Read data from database service
  char** product_names = (char**)malloc_memory(sizeof(char*) * num_products, NULL);
  if (product_names == NULL) {
    // Handle memory allocation failure
    return;
  }
  int* category_ids = (int*)malloc_memory(sizeof(int) * num_categories, NULL);
  if (category_ids == NULL) {
    // Handle memory allocation failure
    free_memory(product_names, NULL);
    return;
  }
  float* review_scores = (float*)malloc_memory(sizeof(float) * num_reviews, NULL);
  if (review_scores == NULL) {
    // Handle memory allocation failure
    free_memory(product_names, NULL);
    free_memory(category_ids, NULL);
    return;
  }
  char*** review_comments = (char***)malloc_memory(sizeof(char**) * num_reviews, NULL);
  if (review_comments == NULL) {
    // Handle memory allocation failure
    free_memory(product_names, NULL);
    free_memory(category_ids, NULL);
    free_memory(review_scores, NULL);
    return;
  }
  for (int i = 0; i < num_reviews; ++i) {
    review_comments[i] = (char**)malloc_memory(sizeof(char*) * 10, NULL); // arbitrary limit on number of comments per review
    if (review_comments[i] == NULL) {
      // Handle memory allocation failure
      free_memory(product_names, NULL);
      free_memory(category_ids, NULL);
      free_memory(review_scores, NULL);
      for (int j = 0; j < i; ++j) {
        free_memory(review_comments[i], NULL);
      }
      return;
    }
  }

  // Populate product and category arrays
  int num_products_read = 0;
  for (int i = 0; i < num_reviews; ++i) {
    if (strlen(product_names[i]) > 0) {
      struct Product* product = products + num_products_read;
      product->name = product_names[i];
      category_ids[num_categories_read] = review_scores[i];
      for (int j = 0; j < 10; ++j) { // arbitrary limit on number of comments per review
        if (strlen(review_comments[i][j]) > 0) {
          struct Review* review = reviews + num_reviews_read;
          review->comment = review_comments[i][j];
        }
      }
      num_products_read++;
    }
  }

  // Populate hash table for mapping products to their respective categories
  for (int i = 0; i < num_products_read; ++i) {
    struct Product* product = products + i;
    int category_id = category_ids[i];
    if (category_id > 0 && category_id <= num_categories) {
      struct Category* category = categories + category_id - 1; // zero-indexed array of categories
      product->category = category;
    } else {
      product->category = NULL;
    }
  }
}

// Function to retrieve the category for a given product
struct Category* get_product_category(struct Product* product) {
  return product->category;
}

int main() {
  // Initialize data structures with a specified number of entities
  init_data_structures(10, 5, 20);

  // Populate the data structures with data read from an external database service
  populate_data_structures(10, 5, 20);

  // Retrieve the category for a given product
  struct Product* product = products + 3;
  struct Category* category = get_product_category(product);
  if (category != NULL) {
    printf("Product %d belongs to category %s\n", product->id, category->name);
  } else {
    printf("Product %d does not belong to any category\n", product->id);
  }

  return 0;
}
