// Struct to represent a list item
struct Item {
  char* id;
  time_t timestamp;
  int value;
};

// Map to store items with unique identifiers
static void* items = NULL;
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to insert an item into the list
void insertItem(char* id, time_t timestamp, int value) {
  // Lock mutex before modifying shared data
  pthread_mutex_lock(&mutex);

  struct Item* newItem = (struct Item*)malloc(sizeof(struct Item));
  newItem->id = id;
  newItem->timestamp = timestamp;
  newItem->value = value;

  // Hash the ID and insert item into map
  unsigned long hash = customHash(id);
  struct Item** bucket = (struct Item**)items + hash % TABLE_SIZE;
  *bucket = newItem;

  // Unlock mutex after modifying shared data
  pthread_mutex_unlock(&mutex);
}

// Function to delete an item from the list
void deleteItem(char* id) {
  // Lock mutex before modifying shared data
  pthread_mutex_lock(&mutex);

  unsigned long hash = customHash(id);
  struct Item** bucket = (struct Item**)items + hash % TABLE_SIZE;

  // Find and delete item with matching ID
  while (*bucket != NULL && strcmp((*bucket)->id, id) != 0) {
    bucket = &(*bucket)->next;
  }
  if (*bucket != NULL) {
    struct Item* temp = *bucket;
    *bucket = temp->next;
    free(temp);
  }

  // Unlock mutex after modifying shared data
  pthread_mutex_unlock(&mutex);
}

// Function to lookup an item in the list
