  struct Item* result = NULL;

  // Lock mutex before reading shared data
  pthread_mutex_lock(&mutex);

  unsigned long hash = customHash(id);
  struct Item** bucket = (struct Item**)items + hash % TABLE_SIZE;

  // Find item with matching ID and return it
  while (*bucket != NULL && strcmp((*bucket)->id, id) != 0) {
    bucket = &(*bucket)->next;
  }
  if (*bucket != NULL) {
    result = *bucket;
  }

  // Unlock mutex after reading shared data
  pthread_mutex_unlock(&mutex);

  return result;
}

// Function to manage a pool of worker threads for parallel processing
void* workerThread(void* args) {
  struct WorkerArgs* workerArgs = (struct WorkerArgs*)args;

  while (1) {
    // Lock mutex before reading shared data
    pthread_mutex_lock(&mutex);

    // Check if there are any items to process
    if (workerArgs->queueSize > 0) {
      struct Item* item = workerArgs->queue[--workerArgs->queueSize];

      // Process item and update cache
      processItem(item);
      addToCache(item);

      // Unlock mutex after modifying shared data
      pthread_mutex_unlock(&mutex);
    } else {
      // No more items to process, exit thread
      break;
    }
  }

  return NULL;
}

