// Define a structure to hold the UE context information
typedef struct {
    int ue_id;
    MeasurementReport *reports;
    time_t last_update;
} UEContext;

// Define a dynamic array to store the UE contexts
struct UEDynamicArray {
    int size;
    int capacity;
    UEContext *data;
};

// Function to add a new measurement report for a given UE ID
void add_measurement_report(int ue_id, MeasurementReport *report) {
    // Find the UE context corresponding to the given UE ID
    int index = find_ue_index(ue_id);
    if (index == -1) {
        // If there is no UE context for the given UE ID, create a new one
        UEContext *new_ue = malloc(sizeof(UEContext));
        new_ue->ue_id = ue_id;
        new_ue->reports = NULL;
        new_ue->last_update = 0;
        // Add the new UE context to the dynamic array
        struct UEDynamicArray *array = get_uedynamic_array();
        if (array->size == array->capacity) {
            // If the dynamic array is full, double its capacity
            int new_capacity = array->capacity * 2;
            UEContext *new_data = malloc(sizeof(UEContext) * new_capacity);
            memcpy(new_data, array->data, sizeof(UEContext) * array->size);
            free(array->data);
            array->data = new_data;
            array->capacity = new_capacity;
        }
        array->data[array->size++] = *new_ue;
    }
    // Add the new measurement report to the list of reports for the UE context
    UEContext *ue = &array->data[index];
    ReportListNode *node = malloc(sizeof(ReportListNode));
    node->report = report;
    node->next = ue->reports;
    ue->reports = node;
}

// Function to retrieve the latest measurement report for a given UE ID
MeasurementReport *get_latest_measurement_report(int ue_id) {
    // Find the UE context corresponding to the given UE ID
    int index = find_ue_index(ue_id);
    if (index == -1) {
        return NULL;
    }
    // Return the latest measurement report from the list of reports for the UE context
    UEContext *ue = &array->data[index];
    ReportListNode *node = ue->reports;
    while (node != NULL && node->next != NULL) {
        node = node->next;
    }
    if (node == NULL) {
        return NULL;
    }
    return node->report;
}

// Function to retrieve the number of UE contexts in the dynamic array
int get_num_ue_contexts() {
    struct UEDynamicArray *array = get_uedynamic_array();
    return array->size;
}

// Helper function to find the index of a UE context corresponding to a given UE ID
int find_ue_index(int ue_id) {
    struct UEDynamicArray *array = get_uedynamic_array();
    for (int i = 0; i < array->size; ++i) {
        if (array->data[i].ue_id == ue_id) {
            return i;
        }
    }
    return -1;
}

// Helper function to retrieve the dynamic array of UE contexts
struct UEDynamicArray *get_uedynamic_array() {
    static struct UEDynamicArray array = {0, 4, malloc(sizeof(UEContext) * 4)};
    return &array;
}
