#define MAX_DIRECTORY_PATH_LENGTH 256

// Define the logging levels to use for feedback
#define LOG_LEVEL_DEBUG 1
#define LOG_LEVEL_INFO 2
#define LOG_LEVEL_WARNING 3
#define LOG_LEVEL_ERROR 4

// Define the environment variable used to store the directory path
#define DIRECTORY_PATH_ENV_VAR "LTE_UE_CONTEXT_DIRECTORY"

static char *init_directory(const char *directory) {
    // Validate the directory name against system-specific naming conventions
    if (!is_valid_directory_name(directory)) {
        syslog(LOG_LEVEL_ERROR, "Invalid directory name: %s", directory);
        return NULL;
    }

    // Parse the XML configuration file to retrieve the desired directory path
    char *xml_path = getenv("CONFIG_FILE");
    if (xml_path == NULL) {
        syslog(LOG_LEVEL_ERROR, "Failed to retrieve XML configuration file path");
        return NULL;
    }

    // Load the XML configuration file into memory
    FILE *file = fopen(xml_path, "r");
    if (file == NULL) {
        syslog(LOG_LEVEL_ERROR, "Failed to open XML configuration file: %s", xml_path);
        return NULL;
    }

    // Read the desired directory path from the XML file
    char *directory_path = NULL;
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        if (strncmp(buffer, "<Directory", 9) == 0 && strchr(buffer, '>') != NULL) {
            directory_path = strtok(buffer, ">");
            break;
        }
    }

    // Close the XML file and return the directory path
    fclose(file);
    return directory_path;
}

static void create_directory(const char *directory) {
    // Create the directory with appropriate permissions
    if (mkdir(directory, 0755)) {
        syslog(LOG_LEVEL_ERROR, "Failed to create directory: %s", directory);
    } else {
        syslog(LOG_LEVEL_INFO, "Created directory: %s", directory);
    }
}

static void update_environment_variable(const char *directory) {
    // Update the environment variable with the absolute path of the directory
    if (setenv(DIRECTORY_PATH_ENV_VAR, directory, 1)) {
        syslog(LOG_LEVEL_ERROR, "Failed to update %s environment variable", DIRECTORY_PATH_ENV_VAR);
    } else {
        syslog(LOG_LEVEL_INFO, "Updated %s environment variable with: %s", DIRECTORY_PATH_ENV_VAR, directory);
    }
}

char *InitializeDataDirectory(void) {
    // Initialize the logging system
    openlog("LTE UE Context Directory Initializer", LOG_CONS | LOG_PID, LOG_USER);

    // Retrieve the desired directory path from the XML configuration file
    char *directory = init_directory();
    if (directory == NULL) {
        syslog(LOG_LEVEL_ERROR, "Failed to retrieve desired directory path");
        return NULL;
    }

    // Validate the directory name against system-specific naming conventions
    if (!is_valid_directory_name(directory)) {
        syslog(LOG_LEVEL_ERROR, "Invalid directory name: %s", directory);
        return NULL;
    }

    // Create the directory if it does not exist
    struct stat st = {0};
    if (stat(directory, &st) == -1) {
        create_directory(directory);
    }

    // Update the environment variable with the absolute path of the directory
    update_environment_variable(directory);

    // Release the logging system resources
    closelog();

    return directory;
}
