// Define a struct to represent a list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
} NFAPI_CRC_INDICATION_LIST;

// Define a function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_LIST *allocate_crc_indication_list(size_t n) {
    // Validate the input against the predefined minimum and maximum range
    if (n < MINIMUM_RANGE || n > MAXIMUM_RANGE) {
        fprintf(stderr, "Error: invalid input value for N\n");
        return NULL;
    }

    // Dynamically allocate memory for the list of structures
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    if (!list) {
        fprintf(stderr, "Error: failed to allocate memory for CRC indication list\n");
        return NULL;
    }

    // Initialize the capacity of the list to match the input value
    list->capacity = n;

    // Dynamically allocate memory for each structure in the list
    NFAPI_CRC_INDICATION_PDU_T *data = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        fprintf(stderr, "Error: failed to allocate memory for CRC indication data\n");
        free(list);
        return NULL;
    }

    // Set the pointer to the list of structures in the list
    list->data = data;

    // Initialize each structure in the list with a valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
    for (size_t i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list->data[i];
        pdu->rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        pdu->rx_ue_information.rnti = i + 1;
        pdu->crc_indication_rel8.tag = CRC_INDICATION_REL8_TAG;
        pdu->crc_indication_rel8.crc_flag = rand() % 2; // Randomly set the CRCFLAG according to a specific probability distribution
    }

    return list;
}

// Define a function to deallocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
void free_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list) {
    if (list == NULL) return;
    free(list->data);
    free(list);
}
