#include <iostream>
#include <string>
#include <vector>
#include <unordered_map>
#include <mutex>

// Struct to represent a single LTE UE Context
struct UEContext {
    std::string ue_id;
    std::vector<std::pair<int, MeasurementReport>> measurement_reports;
    time_t last_update;
};

// Container for all LTE UE Contexts in the system
class UEContextManager {
private:
    // Map from UE ID to UEContext object
    std::unordered_map<std::string, UEContext> ue_contexts_;

    // Mutex to protect concurrent access to the container
    std::mutex mutex_;

public:
    // Add a new measurement report for a given UE ID
    void addMeasurementReport(const std::string& ue_id, const MeasurementReport& report) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = ue_contexts_.find(ue_id);
        if (it != ue_contexts_.end()) {
            it->second.measurement_reports.push_back(report);
        } else {
            UEContext context;
            context.ue_id = ue_id;
            context.measurement_reports.push_back(report);
            ue_contexts_.insert({ue_id, context});
        }
    }

    // Retrieve the most recent measurement report for a given UE ID
    MeasurementReport getMeasurementReport(const std::string& ue_id) {
        std::lock_guard<std::mutex> lock(mutex_);
        auto it = ue_contexts_.find(ue_id);
        if (it != ue_contexts_.end()) {
            return it->second.measurement_reports.back();
        } else {
            throw std::runtime_error("UE Context not found");
        }
    }
};
```
This implementation uses an `unordered_map` to store the LTE UE Contexts in a thread-safe manner, with each context identified by its unique UE ID. The `addMeasurementReport` function adds a new measurement report for a given UE ID, while the `getMeasurementReport` function retrieves the most recent measurement report for that same UE ID.

The `UEContextManager` class provides a convenient interface for adding and retrieving measurement reports, while ensuring that concurrent access to the container is properly synchronized using a `std::mutex`.

