// Define a structure for the record data
typedef struct {
    int value;
} Record;

// Define a doubly linked list node
struct Node {
    Record* record;
    struct Node* next;
    struct Node* prev;
};

// Define a doubly linked list
struct LinkedList {
    struct Node* head;
    struct Node* tail;
};

// Initialize the collection with a specified number of records
void init_collection(int num_records) {
    // Allocate memory for the collection
    struct LinkedList* collection = malloc(sizeof(struct LinkedList));
    if (!collection) {
        printf("Failed to allocate memory for the collection\n");
        return;
    }

    // Initialize the head and tail pointers of the list
    collection->head = NULL;
    collection->tail = NULL;

    // Allocate memory for each record
    Record* record = malloc(sizeof(Record));
    if (!record) {
        printf("Failed to allocate memory for the record\n");
        return;
    }

    // Set the value of the record to a random integer within a given range
    int lower_bound = 100;
    int upper_bound = 200;
    srand(time(NULL));
    record->value = rand() % (upper_bound - lower_bound + 1) + lower_bound;

    // Create a new node for the record
    struct Node* node = malloc(sizeof(struct Node));
    if (!node) {
        printf("Failed to allocate memory for the node\n");
        return;
    }

    // Set the node's data field to the record
    node->record = record;

    // Add the node to the head of the list
    collection->head = node;
    collection->tail = node;
}

// Insert a new record into the collection
void insert_record(int value) {
    // Allocate memory for the new record
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) {
        printf("Failed to allocate memory for the new record\n");
        return;
    }

    // Set the value of the new record to the given value
    new_record->value = value;

    // Create a new node for the new record
    struct Node* new_node = malloc(sizeof(struct Node));
    if (!new_node) {
        printf("Failed to allocate memory for the new node\n");
        return;
    }

    // Set the new node's data field to the new record
    new_node->record = new_record;

    // Add the new node to the tail of the list
    struct LinkedList* collection = get_collection();
    if (!collection) {
        printf("Failed to retrieve the collection\n");
        return;
    }
    new_node->prev = collection->tail;
    new_node->next = NULL;
    collection->tail->next = new_node;
    collection->tail = new_node;
}

// Delete a record from the collection
void delete_record(int value) {
    // Get the head node of the list
    struct LinkedList* collection = get_collection();
    if (!collection) {
        printf("Failed to retrieve the collection\n");
        return;
    }
    struct Node* current_node = collection->head;

    // Find the node containing the given value
    while (current_node && current_node->record->value != value) {
        current_node = current_node->next;
    }

    // If the node is found, remove it from the list
    if (current_node) {
        struct Node* previous_node = current_node->prev;
        struct Node* next_node = current_node->next;
        if (previous_node) {
            previous_node->next = next_node;
        } else {
            collection->head = next_node;
        }
        if (next_node) {
            next_node->prev = previous_node;
        } else {
            collection->tail = previous_node;
        }
    }
}

// Get the head node of the list
struct LinkedList* get_collection() {
    // Allocate memory for the collection
    struct LinkedList* collection = malloc(sizeof(struct LinkedList));
    if (!collection) {
        printf("Failed to allocate memory for the collection\n");
        return NULL;
    }

    // Initialize the head and tail pointers of the list
    collection->head = NULL;
    collection->tail = NULL;

    // Return the collection
    return collection;
}
