// Define the structure for a WiFi RX packet header
struct WIFI_RX_PACKET {
  // Header fields
  int channel;
  int rssi;
  unsigned long timestamp;

  // Symbol list
  struct WIFI_RX_SYMBOL *symbols;
};

// Define the structure for a WiFi RX symbol
struct WIFI_RX_SYMBOL {
  // Symbol fields
  int frequency_offset;
  int signal_to_noise_ratio;
  unsigned long timestamp;
};

// Function to initialize and manage the dynamic array of WIFI_RX_PACKET structures
void init_wifi_rx_packet_array(struct WIFI_RX_PACKET **array, int size) {
  // Allocate memory for the array
  *array = malloc(sizeof(**array) * size);

  // Initialize each element of the array with a WIFI_RX_PACKET structure
  for (int i = 0; i < size; i++) {
    (*array)[i].symbols = NULL;
  }
}

// Function to free the memory allocated by init_wifi_rx_packet_array()
void free_wifi_rx_packet_array(struct WIFI_RX_PACKET **array) {
  // Free each element of the array
  for (int i = 0; i < (*array)->size; i++) {
    free((*array)[i].symbols);
  }

  // Free the memory allocated for the array itself
  free(*array);
}

// Function to add a new WiFi RX packet to the array
void add_wifi_rx_packet(struct WIFI_RX_PACKET **array, int size) {
  // Check if the array needs to be resized
  if (size == (*array)->size) {
    // Reallocate memory for the array with a new size that is twice the current size
    struct WIFI_RX_PACKET *new_array = realloc(*array, sizeof(**array) * size * 2);
    if (new_array == NULL) {
      // If reallocation fails, print an error message and exit
      printf("Error: Failed to allocate memory for the array\n");
      return;
    } else {
      // Update the pointer to point to the new array
      *array = new_array;
      (*array)->size *= 2;
    }
  }

  // Add a new WiFi RX packet to the end of the array
  (*array)[size].channel = 0;
  (*array)[size].rssi = 0;
  (*array)[size].timestamp = 0;
  (*array)[size].symbols = NULL;
}

// Function to remove a WiFi RX packet from the array
void remove_wifi_rx_packet(struct WIFI_RX_PACKET **array, int size) {
  // If there are no packets in the array, return
  if (size == 0) {
    return;
  }

  // Remove the last packet from the array
  free((*array)[size - 1].symbols);
  (*array)[size - 1] = NULL;

  // Reallocate memory for the array with a new size that is one less than the current size
  struct WIFI_RX_PACKET *new_array = realloc(*array, sizeof(**array) * (size - 1));
  if (new_array == NULL) {
    // If reallocation fails, print an error message and exit
    printf("Error: Failed to allocate memory for the array\n");
    return;
  } else {
    // Update the pointer to point to the new array
    *array = new_array;
    (*array)->size--;
  }
}

// Function to update a WiFi RX packet in the array
void update_wifi_rx_packet(struct WIFI_RX_PACKET **array, int size) {
  // Check if the array needs to be resized
  if (size == (*array)->size) {
    // Reallocate memory for the array with a new size that is twice the current size
    struct WIFI_RX_PACKET *new_array = realloc(*array, sizeof(**array) * size * 2);
    if (new_array == NULL) {
      // If reallocation fails, print an error message and exit
      printf("Error: Failed to allocate memory for the array\n");
      return;
    } else {
      // Update the pointer to point to the new array
      *array = new_array;
      (*array)->size *= 2;
    }
  }

  // Update the specified WiFi RX packet in the array
  (*array)[size].channel = 0;
  (*array)[size].rssi = 0;
  (*array)[size].timestamp = 0;
  (*array)[size].symbols = NULL;
}
```
