// Initialize and populate an array of TrafficFlow structures
void init_traffic_flows(struct TrafficFlow flows[], int num_flows) {
    // Initialize the flow IDs to a unique value
    for (int i = 0; i < num_flows; i++) {
        flows[i].FlowID = i + 1;
