        char *source_ip = flows[i].SourceIP;
        char *destination_ip = flows[i].DestinationIP;

        if (!inet_pton(AF_INET, source_ip, &flows[i].SourceIP) || !inet_pton(AF_INET, destination_ip, &flows[i].DestinationIP)) {
            printf("Error: Invalid IP address %s or %s\n", source_ip, destination_ip);
            return;
        }
    }

    // Persist the populated array to disk in a format that can be easily read by another application
    FILE *fp = fopen("traffic_flows.json", "w");
    if (fp == NULL) {
        printf("Error: Unable to open traffic_flows.json for writing\n");
        return;
    }

    // Serialize the flows array as JSON and write it to disk
    char *json = serialize_traffic_flows(flows, num_flows);
    fwrite(json, strlen(json), 1, fp);
    free(json);

    // Close the file stream
    fclose(fp);
}

// Serialize an array of TrafficFlow structures as JSON
char *serialize_traffic_flows(struct TrafficFlow flows[], int num_flows) {
    // Allocate memory for the serialized data
    char *json = malloc(1024);
    if (json == NULL) {
        printf("Error: Unable to allocate memory for JSON data\n");
        return NULL;
    }

    // Initialize a JSON object and array
    json_object *root = json_object_new_object();
    json_object *flows_array = json_object_new_array();

    // Serialize each flow as an object in the array
    for (int i = 0; i < num_flows; i++) {
        struct TrafficFlow *flow = &flows[i];
        json_object *flow_obj = json_object_new_object();
        json_object_object_add(flow_obj, "FlowID", json_object_new_int(flow->FlowID));
        json_object_object_add(flow_obj, "SourceIP", json_object_new_string(flow->SourceIP));
        json_object_object_add(flow_obj, "DestinationIP", json_object_new_string(flow->DestinationIP));
        json_object_object_add(flow_obj, "PacketCount", json_object_new_int(flow->PacketCount));
        json_object_array_add(flows_array, flow_obj);
    }

    // Add the array to the root object and serialize it as a JSON string
    json_object_object_add(root, "Flows", flows_array);
    char *json_str = json_object_to_json_string(root);

    // Clean up memory
    json_object_put(root);
    free(json);

    return json_str;
}

// Dynamic scaling mechanism to adjust the number of flows processed
void adjust_flows(struct TrafficFlow flows[], int num_flows, int new_num_flows) {
    if (new_num_flows < 0 || new_num_flows > 10000) {
        printf("Error: Invalid number of flows\n");
        return;
    }

    // Resize the array to match the new number of flows
    struct TrafficFlow *new_flows = realloc(flows, sizeof(struct TrafficFlow) * new_num_flows);
    if (new_flows == NULL) {
        printf("Error: Unable to resize flows array\n");
        return;
    }

    // Initialize the new flows with unique IDs and empty IP addresses
    for (int i = num_flows; i < new_num_flows; i++) {
        new_flows[i].FlowID = i + 1;
        memset(new_flows[i].SourceIP, 0, sizeof(new_flows[i].SourceIP));
        memset(new_flows[i].DestinationIP, 0, sizeof(new_flows[i].DestinationIP));
    }

    // Update the number of flows and persist the new array to disk
    num_flows = new_num_flows;
    FILE *fp = fopen("traffic_flows.json", "w");
    if (fp == NULL) {
        printf("Error: Unable to open traffic_flows.json for writing\n");
        return;
    }
    char *json = serialize_traffic_flows(new_flows, num_flows);
    fwrite(json, strlen(json), 1, fp);
    free(json);
    fclose(fp);
}
```
