// Define the function for initializing and managing the dynamic array of LTE PHY frames
void init_lte_phy_rx_frame_array(struct LTE_PHY_RX_FRAME_ARRAY* array) {
    // Allocate memory for the dynamic array of LTE PHY frames
    array->frames = (LTE_PHY_RX_FRAME**)malloc(sizeof(LTE_PHY_RX_FRAME*) * 10);
    if (!array->frames) {
        printf("Error: unable to allocate memory for the dynamic array of LTE PHY frames\n");
        return;
    }

    // Initialize the size and capacity of the dynamic array
    array->size = 0;
    array->capacity = 10;

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array_lock);

    // Unlock the mutex when the function returns
    __cleanup {
        pthread_mutex_unlock(&array_lock);
    }
}

// Define the function for adding a new LTE PHY frame to the dynamic array
void add_lte_phy_rx_frame(struct LTE_PHY_RX_FRAME_ARRAY* array, LTE_PHY_RX_FRAME* frame) {
    // Check if there is enough capacity in the dynamic array to store the new frame
    if (array->size >= array->capacity) {
        printf("Error: unable to add a new LTE PHY frame to the dynamic array, no more space available\n");
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array_lock);

    // Copy the new frame into the dynamic array
    array->frames[array->size] = (LTE_PHY_RX_FRAME*)malloc(sizeof(LTE_PHY_RX_FRAME));
    if (!array->frames[array->size]) {
        printf("Error: unable to allocate memory for the new LTE PHY frame\n");
        return;
    }
    memcpy(array->frames[array->size], frame, sizeof(LTE_PHY_RX_FRAME));

    // Increment the size of the dynamic array
    array->size++;

    // Unlock the mutex when the function returns
    __cleanup {
        pthread_mutex_unlock(&array_lock);
    }
}

// Define the function for removing an LTE PHY frame from the dynamic array
void remove_lte_phy_rx_frame(struct LTE_PHY_RX_FRAME_ARRAY* array, int index) {
    // Check if the specified index is within the bounds of the dynamic array
    if (index < 0 || index >= array->size) {
        printf("Error: unable to remove an LTE PHY frame from the dynamic array, invalid index\n");
        return;
    }

    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&array_lock);

    // Free the memory allocated for the specified frame
    free(array->frames[index]);
    array->frames[index] = NULL;

    // Decrement the size of the dynamic array
    array->size--;

    // Shift all frames after the removed one to fill the gap
    for (int i = index; i < array->size; i++) {
        memcpy(&array->frames[i], &array->frames[i + 1], sizeof(LTE_PHY_RX_FRAME));
    }

    // Unlock the mutex when the function returns
    __cleanup {
        pthread_mutex_unlock(&array_lock);
    }
}
