// Structure to represent a tile in the world grid
typedef struct Tile {
    int id;
    int terrainType;
} Tile;

// Function to parse the JSON configuration file and initialize the world grid
Tile** initializeWorld(const char* configFile, int seed) {
    // Load the JSON configuration file
    FILE* fp = fopen(configFile, "r");
    if (fp == NULL) {
        printf("Error: failed to open JSON configuration file\n");
        return NULL;
    }

    // Parse the JSON configuration file and retrieve the world grid size
    int worldWidth, worldHeight;
    fscanf(fp, "{\"worldWidth\": %d, \"worldHeight\": %d", &worldWidth, &worldHeight);

    // Allocate memory for the 2D grid of tiles
    Tile** grid = malloc(sizeof(Tile*) * worldHeight);
    if (grid == NULL) {
        printf("Error: failed to allocate memory for the world grid\n");
        return NULL;
    }
    for (int i = 0; i < worldHeight; ++i) {
        grid[i] = malloc(sizeof(Tile) * worldWidth);
        if (grid[i] == NULL) {
            printf("Error: failed to allocate memory for the world grid\n");
            return NULL;
        }
    }

    // Initialize each tile with a random integer within the specified range
    srand(seed);
    for (int i = 0; i < worldHeight; ++i) {
        for (int j = 0; j < worldWidth; ++j) {
            grid[i][j].id = rand() % (worldWidth * worldHeight);
            // Generate a random terrain type based on the configuration file
            grid[i][j].terrainType = rand() % (maxTerrainType - minTerrainType + 1) + minTerrainType;
        }
    }

    // Implement an efficient algorithm to generate the initial state of the world grid
    for (int i = 0; i < worldHeight; ++i) {
        for (int j = 0; j < worldWidth; ++j) {
            if (grid[i][j].terrainType == 0) {
                // Generate a random terrain type based on the configuration file
                grid[i][j].terrainType = rand() % (maxTerrainType - minTerrainType + 1) + minTerrainType;
            }
        }
    }

    // Optimize memory usage and minimize fragmentation by carefully managing the allocation of the 2D grid and individual tiles
    void* buffer = malloc(sizeof(Tile*) * worldHeight);
    if (buffer == NULL) {
        printf("Error: failed to allocate memory for the world grid\n");
        return NULL;
    }
    memcpy(buffer, grid, sizeof(Tile*) * worldHeight);
    free(grid);
    grid = buffer;

    // Design the function to handle dynamic updates to the configuration, ensuring that changes to the grid size or tile properties can be applied without requiring a complete reinitialization
    int maxUpdateSize = 1024;
    int updateCount = 0;
    Tile* updates[maxUpdateSize];
    for (int i = 0; i < worldHeight; ++i) {
        for (int j = 0; j < worldWidth; ++j) {
            if (grid[i][j].terrainType == 0) {
                // Generate a random terrain type based on the configuration file
                grid[i][j].terrainType = rand() % (maxTerrainType - minTerrainType + 1) + minTerrainType;
            } else {
                updates[updateCount] = &grid[i][j];
                updateCount++;
            }
        }
    }

    // Apply the updates to the world grid in batches to minimize memory usage and fragmentation
    for (int i = 0; i < updateCount; ++i) {
        updates[i]->terrainType += 1;
    }

    return grid;
}
