```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <sys/time.h>

// Define structures for log entries and network flow records
struct LogEntry {
    time_t timestamp;
    int log_level;
    char message[1024]; // variable-length message field
};

struct NetworkFlowRecord {
    int flow_id;
    char source_ip[INET_ADDRSTRLEN];
    char destination_ip[INET_ADDRSTRLEN];
    unsigned long packet_count;
    unsigned long byte_count;
};

// Define a function to initialize the network monitoring system
int init_network_monitoring(int M) {
    // Check if M is positive and non-zero
    if (M <= 0) {
        return -1;
    }

    // Allocate memory for an array of LogEntry structures
    struct LogEntry* log_entries = malloc(sizeof(struct LogEntry) * M);
    if (!log_entries) {
        perror("malloc");
        return -1;
    }

    // Initialize each log entry with a timestamp and a default log level
    for (int i = 0; i < M; i++) {
        struct LogEntry* entry = &log_entries[i];
        entry->timestamp = time(NULL);
        entry->log_level = 1; // default log level is informational
        strcpy(entry->message, "");
    }

    // Allocate memory for an array of NetworkFlowRecord structures
    struct NetworkFlowRecord* flow_records = malloc(sizeof(struct NetworkFlowRecord) * M);
    if (!flow_records) {
        perror("malloc");
        free(log_entries);
        return -1;
    }

    // Initialize each network flow record with a unique flow ID, source IP, and destination IP
    for (int i = 0; i < M; i++) {
        struct NetworkFlowRecord* record = &flow_records[i];
        record->flow_id = i + 1; // start at 1 to avoid confusion with the index
        record->source_ip = "127.0.0.1"; // default source IP is localhost
        record->destination_ip = "127.0.0.1"; // default destination IP is localhost
        record->packet_count = 0;
