using namespace std;

// Constants
const int MAX_STRUCTS = 10000; // Maximum number of structures to allocate
const int BLOCK_SIZE = 4096; // Size of memory blocks for reuse
const int CRCFLAG_VAL = 3; // Default value for CRCFLAG
const int HASH_ITERATIONS = 1 << 20; // Number of iterations for hashing
const int LOGGING_INTERVAL = 10000; // Interval between logging operations (ms)

// Data structures
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    uint8_t CRCFLAG;
};

class DataProcessor {
private:
    vector<NFAPI_CRC_INDICATION_PDU_T> structures; // List of structures
    mutex mtx; // Mutex for thread safety
    condition_variable cv; // Condition variable for logging operations
    ofstream logfile; // Log file for tracking allocations and failures
    bool initialized = false; // Flag indicating whether the class is initialized
    unordered_set<uint32_t> uniqueRX_UE_INFORMATION_TAGS; // Set of unique RX_UE_INFORMATION_TAG values

public:
    DataProcessor() {}

    ~DataProcessor() {
        if (initialized) {
            clear();
        }
    }

    void initialize(string logfilePath) {
        // Open the log file for writing
        logfile.open(logfilePath, ofstream::binary);
        if (!logfile.is_open()) {
            cerr << "Error: Failed to open log file" << endl;
            return;
        }

        // Initialize data structures
        structures.reserve(MAX_STRUCTS);
        uniqueRX_UE_INFORMATION_TAGS.reserve(MAX_STRUCTS);

        initialized = true;
    }

    void clear() {
        // Clear the list of structures and reset the mutex and condition variable
        mtx.lock();
        structures.clear();
        uniqueRX_UE_INFORMATION_TAGS.clear();
        cv.notify_all();
        mtx.unlock();
    }

    void add(string inputString) {
        // Generate a random seed for the Mersenne Twister algorithm
        unsigned long seed = chrono::high_resolution_clock::now().time_since_epoch().count();

        // Compute the hash of the input string using the Mersenne Twister algorithm
        uint64_t hash = 0;
        for (int i = 0; i < HASH_ITERATIONS; ++i) {
            hash = hash * seed + 1;
            seed = hash * seed + 3;
        }

        // Create a new structure and populate it with the input string and the generated hash value
        NFAPI_CRC_INDICATION_PDU_T structure;
        structure.RX_UE_INFORMATION_TAG = (uint32_t)hash;
        structure.RNTI = 0;
        structure.CRCFLAG = CRCFLAG_VAL;

        // Add the new structure to the list of structures
        mtx.lock();
        if (structures.size() < MAX_STRUCTS) {
            uniqueRX_UE_INFORMATION_TAGS.insert(structure.RX_UE_INFORMATION_TAG);
            structures.push_back(structure);
            cv.notify_all();
        } else {
            cerr << "Error: Structure limit reached" << endl;
        }
        mtx.unlock();
    }

    void serialize() {
        // Serialize the list of structures into a binary format for storage and reuse
        ofstream outputFile("structures.bin", ofstream::binary);
        if (!outputFile.is_open()) {
            cerr << "Error: Failed to open output file" << endl;
            return;
        }

        // Write the size of the list and then each structure in the list
        mtx.lock();
        size_t numStructures = structures.size();
        outputFile.write((char*)&numStructures, sizeof(numStructures));
        for (auto it = structures.begin(); it != structures.end(); ++it) {
            outputFile.write((char*)&(*it), sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        mtx.unlock();
    }

    void deserialize() {
        // Deserialize the list of structures from a binary format stored in the file
        ifstream inputFile("structures.bin", ifstream::binary);
        if (!inputFile.is_open()) {
            cerr << "Error: Failed to open input file" << endl;
            return;
        }

        // Read the size of the list and then each structure in the list
        mtx.lock();
        size_t numStructures = 0;
        inputFile.read((char*)&numStructures, sizeof(numStructures));
        for (int i = 0; i < numStructures; ++i) {
            NFAPI_CRC_INDICATION_PDU_T structure;
            inputFile.read((char*)&structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            structures.push_back(structure);
        }
        mtx.unlock();
    }

    void reset() {
        // Reset all allocated structures to a default state and clear the list periodically
        if (structures.size() > 0) {
            for (auto it = structures.begin(); it != structures.end(); ++it) {
                *it = {};
            }
            structures.clear();
            uniqueRX_UE_INFORMATION_TAGS.clear();
        }
    }
};

int main() {
    // Initialize the DataProcessor class with a log file path
    string logfilePath("log.txt");
    DataProcessor dataProcessor;
    dataProcessor.initialize(logfilePath);

    // Add some input strings to the list of structures
    vector<string> inputStrings = {"hello", "world", "abc", "def"};
    for (auto it = inputStrings.begin(); it != inputStrings.end(); ++it) {
        dataProcessor.add(*it);
    }

    // Serialize the list of structures into a binary format for storage and reuse
    dataProcessor.serialize();

    // Reset all allocated structures to a default state and clear the list periodically
    dataProcessor.reset();
}
