// Define a structure to represent the metadata for a file
typedef struct {
    char *filename;
    int frequency[256];
} FileMetadata;

// Function to generate a new filename based on the contents of an existing filename
int generate_new_filename(const char *existing_filename, const char *extension) {
    // Check if the input filename is too long or contains invalid characters
    if (strlen(existing_filename) > PATH_MAX || strpbrk(existing_filename, "\\/:*?\"<>|")) {
        fprintf(stderr, "Invalid input filename: %s\n", existing_filename);
        return -1;
    }

    // Create a copy of the input filename for processing
    char *new_filename = strdup(existing_filename);

    // Remove any leading or trailing spaces from the new filename
    trim(new_filename);

    // Count the frequency of each character in the existing filename
    int i;
    for (i = 0; i < strlen(new_filename); i++) {
        new_filename[i] = tolower(new_filename[i]);
        if (!isalpha(new_filename[i]) && !isspace(new_filename[i])) {
            fprintf(stderr, "Invalid character in input filename: %s\n", existing_filename);
            return -1;
        }
    }

    // Initialize the metadata for the file
    FileMetadata *metadata = (FileMetadata *) malloc(sizeof(FileMetadata));
    if (!metadata) {
        fprintf(stderr, "Memory allocation failed: %s\n", strerror(errno));
        return -1;
    }
    metadata->filename = new_filename;

    // Generate the new filename based on the character frequency in the existing filename
    int sequence[256] = { 0 };
    for (i = 0; i < strlen(new_filename); i++) {
        sequence[new_filename[i]]++;
    }
    char *sequence_str = malloc(sizeof(char) * 10);
    sprintf(sequence_str, "%d", sequence['a']);
    new_filename = realloc(new_filename, strlen(new_filename) + strlen(sequence_str) + strlen(extension));
    strcat(new_filename, "_");
    strcat(new_filename, sequence_str);
    strcat(new_filename, extension);

    // Log any errors encountered during execution
    if (strlen(new_filename) > PATH_MAX || strpbrk(new_filename, "\\/:*?\"<>|")) {
        fprintf(stderr, "New filename exceeds maximum length: %s\n", new_filename);
        return -1;
    }

    // Return the new filename and metadata structure
    return 0;
}

// Function to trim leading or trailing spaces from a string
void trim(char *str) {
    char *end;
    while (isspace((unsigned char)*str)) str++;
    if (*str == 0) return; // all spaces?
    end = str + strlen(str) - 1;
    while (end > str && isspace((unsigned char)*end)) end--;
    *(end + 1) = 0;
}
