#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdio.h>

typedef struct KeyValue {
    char* key;
    int value;
} KeyValue;

typedef struct Dictionary {
    KeyValue** dict;
    int size;
    int capacity;
    pthread_mutex_t mutex;
} Dictionary;

Dictionary* create_dictionary(int capacity) {
    Dictionary* dict = malloc(sizeof(Dictionary));
    if (!dict) {
        printf("Error: Failed to allocate memory for dictionary\n");
        return NULL;
    }
    dict->size = 0;
    dict->capacity = capacity;
    dict->dict = calloc(capacity, sizeof(KeyValue*));
    if (!dict->dict) {
        printf("Error: Failed to allocate memory for dictionary entries\n");
        free(dict);
        return NULL;
    }
    pthread_mutex_init(&dict->mutex, NULL);
    return dict;
}

void destroy_dictionary(Dictionary* dict) {
    if (dict == NULL) {
        return;
    }
    free(dict->dict);
    dict->dict = NULL;
    pthread_mutex_destroy(&dict->mutex);
    free(dict);
}

int get_hash(const char* key, int capacity) {
    int hash = 0;
    for (int i = 0; i < strlen(key); ++i) {
        hash += key[i];
    }
    return hash % capacity;
}

void add_item(Dictionary* dict, const char* key, int value) {
    if (!dict || !key) {
        return;
    }
    pthread_mutex_lock(&dict->mutex);
    int hash = get_hash(key, dict->capacity);
    while (dict->dict[hash]) {
        hash = (hash + 1) % dict->capacity;
    }
    KeyValue* kv = malloc(sizeof(KeyValue));
    if (!kv) {
        printf("Error: Failed to allocate memory for key-value pair\n");
        pthread_mutex_unlock(&dict->mutex);
        return;
    }
    kv->key = strdup(key);
    kv->value = value;
    dict->dict[hash] = kv;
    dict->size++;
    pthread_mutex_unlock(&dict->mutex);
}

void remove_item(Dictionary* dict, const char* key) {
    if (!dict || !key) {
        return;
    }
    pthread_mutex_lock(&dict->mutex);
    int hash = get_hash(key, dict->capacity);
    while (dict->dict[hash]) {
        KeyValue* kv = dict->dict[hash];
        if (!strcmp(kv->key, key)) {
            free(kv->key);
            free(kv);
            dict->dict[hash] = NULL;
            break;
        }
        hash = (hash + 1) % dict->capacity;
    }
    dict->size--;
    pthread_mutex_unlock(&dict->mutex);
}

int get_value(Dictionary* dict, const char* key) {
    if (!dict || !key) {
        return -1;
    }
    int hash = get_hash(key, dict->capacity);
    while (dict->dict[hash]) {
        KeyValue* kv = dict->dict[hash];
        if (!strcmp(kv->key, key)) {
            return kv->value;
        }
        hash = (hash + 1) % dict->capacity;
    }
    return -1;
}
