};

// Function prototypes
void init_frame(struct LTE_PHY_RX_FRAME *frame);
void update_signal_strength(struct LTE_PHY_RX_FRAME *frame, int new_signal_strength);
void update_symbols(struct LTE_PHY_RX_FRAME *frame, size_t num_symbols);
void add_symbol(struct LTE_PHY_RX_FRAME *frame, struct LTE_PHY_RX_SYMBOL symbol);
void remove_symbol(struct LTE_PHY_RX_FRAME *frame, size_t index);
int get_signal_strength(struct LTE_PHY_RX_FRAME *frame);
size_t get_num_symbols(struct LTE_PHY_RX_FRAME *frame);
struct LTE_PHY_RX_SYMBOL* get_symbols(struct LTE_PHY_RX_FRAME *frame);
void destroy_frame(struct LTE_PHY_RX_FRAME *frame);

// Global variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static struct LTE_PHY_RX_FRAME *frames[MAX_NUM_FRAMES];
static size_t num_frames = 0;

// Function definitions
void init_frame(struct LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&mutex);
    if (num_frames >= MAX_NUM_FRAMES) {
        // Handle out-of-memory condition
        printf("Error: unable to initialize frame, no memory available\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frames[num_frames] = malloc(sizeof(struct LTE_PHY_RX_FRAME));
    if (frames[num_frames] == NULL) {
        // Handle out-of-memory condition
        printf("Error: unable to initialize frame, no memory available\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frame->symbols = malloc(sizeof(struct LTE_PHY_RX_SYMBOL) * INITIAL_NUM_SYMBOLS);
    if (frame->symbols == NULL) {
        // Handle out-of-memory condition
        printf("Error: unable to initialize frame, no memory available\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frame->num_symbols = 0;
    frame->signal_strength = -128; // Invalid value for signal strength
    frame->timestamp = -1; // Invalid value for timestamp
    num_frames++;
    pthread_mutex_unlock(&mutex);
}

void update_signal_strength(struct LTE_PHY_RX_FRAME *frame, int new_signal_strength) {
    pthread_mutex_lock(&mutex);
    if (new_signal_strength < -128 || new_signal_strength > 0) {
        // Handle invalid input parameter
        printf("Error: unable to update signal strength, invalid value provided\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frame->signal_strength = new_signal_strength;
    pthread_mutex_unlock(&mutex);
}

void update_symbols(struct LTE_PHY_RX_FRAME *frame, size_t num_symbols) {
    pthread_mutex_lock(&mutex);
    if (num_symbols > MAX_NUM_SYMBOLS) {
        // Handle invalid input parameter
        printf("Error: unable to update symbols, too many symbols provided\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frame->num_symbols = num_symbols;
    pthread_mutex_unlock(&mutex);
}

void add_symbol(struct LTE_PHY_RX_FRAME *frame, struct LTE_PHY_RX_SYMBOL symbol) {
    pthread_mutex_lock(&mutex);
    if (frame->num_symbols >= MAX_NUM_SYMBOLS) {
        // Handle out-of-memory condition
        printf("Error: unable to add symbol, no memory available\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    frame->symbols[frame->num_symbols] = symbol;
    frame->num_symbols++;
    pthread_mutex_unlock(&mutex);
}

void remove_symbol(struct LTE_PHY_RX_FRAME *frame, size_t index) {
    pthread_mutex_lock(&mutex);
    if (index >= frame->num_symbols || index < 0) {
        // Handle invalid input parameter
        printf("Error: unable to remove symbol, invalid index provided\n");
        pthread_mutex_unlock(&mutex);
        return;
    }
    for (size_t i = index; i < frame->num_symbols - 1; i++) {
        frame->symbols[i] = frame->symbols[i + 1];
    }
    frame->num_symbols--;
    pthread_mutex_unlock(&mutex);
}

void destroy_frame(struct LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&mutex);
    for (size_t i = 0; i < num_frames; i++) {
        if (frames[i] == frame) {
            free(frames[i]);
            frames[i] = NULL;
            break;
        }
    }
    num_frames--;
    pthread_mutex_unlock(&mutex);
}

int main() {
    struct LTE_PHY_RX_FRAME *frame;
    init_frame(frame);
    update_signal_strength(frame, -10);
    add_symbol(frame, (struct LTE_PHY_RX_SYMBOL){.timestamp = 10});
    remove_symbol(frame, 0);
    destroy_frame(frame);
    return 0;
}']

