struct record *find_record_by_id(char *id) {
    // Iterate over the records in the list
    struct record *current = list->head;
    while (current != NULL) {
        // Check if the current record has the given id
        if (strcmp(current->id, id) == 0) {
            // Return the found record
            return current;
        }

        // Move to the next record in the list
        current = current->next;
    }

    // If no record was found, return NULL
    return NULL;
}

// Function to update a record with new data
void update_record(struct record *record, void *data) {
    // Lock the record to avoid race conditions
    pthread_mutex_lock(&record->lock);

    // Update the record's data
    memcpy(record->data, data, record->length);

    // Unlock the record
    pthread_mutex_unlock(&record->lock);
}

// Function to delete a record from the list
void delete_record(struct record *record) {
    // Lock the list to avoid race conditions
    pthread_mutex_lock(&global_lock);

    // Find the previous record in the list with the same id as the given record
    struct record *previous = find_record_by_id(record->id);

    // Check if the previous record was found
    if (previous == NULL) {
        // Return an error response
        printf("Resource not found\n");
        pthread_mutex_unlock(&global_lock);
        return;
    }

    // Update the previous record's next pointer to point to the next record in the list
    previous->next = record->next;

    // Unlock the list
    pthread_mutex_unlock(&global_lock);
}
