// Define the task structure
typedef struct Task {
    char *description;
    int priority;
    struct timespec start_timestamp;
    struct timespec end_timestamp;
} Task;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint16_t RX_UE_INFORMATION_TAG;
    uint32_t RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the task collection structure
typedef struct TaskCollection {
    Task *tasks;
    size_t num_tasks;
    size_t max_num_tasks;
} TaskCollection;

// Initialize the task collection with a specified number of tasks
void initTaskCollection(TaskCollection *tc, size_t num_tasks) {
    tc->tasks = malloc(sizeof(Task) * num_tasks);
    if (!tc->tasks) {
        printf("Error: Failed to allocate memory for task collection\n");
        return;
    }
    tc->num_tasks = 0;
    tc->max_num_tasks = num_tasks;
}

// Add a new task to the collection and set its description, priority level, and timestamps
void addTask(TaskCollection *tc, char *description, int priority) {
    // Check if there is space for another task in the collection
    if (tc->num_tasks >= tc->max_num_tasks) {
        printf("Error: Task collection is full\n");
        return;
    }

    // Generate a random priority level within the specified range
    int min_priority = 0;
    int max_priority = 10;
    priority = (rand() % (max_priority - min_priority)) + min_priority;

    // Set the timestamps based on the elapsed time since the start of the program
    struct timespec start, end;
    clock_gettime(CLOCK_MONOTONIC, &start);
    sleep(1);
    clock_gettime(CLOCK_MONOTONIC, &end);
    tc->tasks[tc->num_tasks].start_timestamp = start;
    tc->tasks[tc->num_tasks].end_timestamp = end;

    // Set the task's description, priority level, and timestamps
    tc->tasks[tc->num_tasks].description = malloc(strlen(description) + 1);
    strcpy(tc->tasks[tc->num_tasks].description, description);
    tc->tasks[tc->num_tasks].priority = priority;
    tc->num_tasks++;
}

// Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures with randomly set RNTIs and CRCFLAG values
void createNFAPIList(TaskCollection *tc, size_t num_tasks) {
    NFAPI_CRC_INDICATION_PDU_T *nfa_list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_tasks);
    if (!nfa_list) {
        printf("Error: Failed to allocate memory for NFAPI list\n");
        return;
    }
    size_t i;
    for (i = 0; i < num_tasks; i++) {
        nfa_list[i].RX_UE_INFORMATION_TAG = rand();
        nfa_list[i].CRCFLAG = rand() % 256;
        // Generate a random RNTI value within the specified range
        int min_rnti = 0;
        int max_rnti = 1000000;
        nfa_list[i].RNTI = (rand() % (max_rnti - min_rnti)) + min_rnti;
    }
}

// Check if two NFAPI_CRC_INDICATION_PDU_T structures share the same RNTI value
int checkNFAPIRNTI(NFAPI_CRC_INDICATION_PDU_T *nfa1, NFAPI_CRC_INDICATION_PDU_T *nfa2) {
    if (nfa1->RNTI == nfa2->RNTI) {
        return 1;
    } else {
        return 0;
    }
}

// Assign a new RNTI value to a duplicate NFAPI_CRC_INDICATION_PDU_T structure
void assignNewRNTI(NFAPI_CRC_INDICATION_PDU_T *nfa) {
    // Generate a random RNTI value within the specified range
    int min_rnti = 0;
    int max_rnti = 1000000;
    nfa->RNTI = (rand() % (max_rnti - min_rnti)) + min_rnti;
}
