    } else {
        // Flush cache to disk if it is full
        flush_cache();

        // Add new transaction object to cache
        cache[cache_count++] = transaction;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&mutex);
}

void flush_cache() {
    // Write cache to disk
    FILE *file = fopen("cache.dat", "wb");
    if (file == NULL) ERR(errno, "failed to open file for writing");

    int size = cache_count * sizeof(*cache);
    if (fwrite(cache, 1, size, file) != size) {
        fclose(file);
        ERR(errno, "failed to write to file");
    }

    // Close the file
    if (fclose(file)) ERR(errno, "failed to close file");
}
