// C function for managing a dynamic array of NFAPI_CRC_INDICATION_PDU_T structures
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    char CRCFLAG[4];
};

struct DynamicArray {
    struct NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t size;
    size_t capacity;
};

void initDynamicArray(struct DynamicArray *array, size_t initialCapacity) {
    array->size = 0;
    array->capacity = initialCapacity;
    array->elements = (struct NFAPI_CRC_INDICATION_PDU_T *)malloc(initialCapacity * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
}

void addElementToDynamicArray(struct DynamicArray *array, struct NFAPI_CRC_INDICATION_PDU_T element) {
    if (array->size == array->capacity) {
        // Dynamically grow the capacity of the array by 50% when the number of elements exceeds the current capacity
        size_t newCapacity = array->capacity + (array->capacity >> 1);
        struct NFAPI_CRC_INDICATION_PDU_T *newElements = (struct NFAPI_CRC_INDICATION_PDU_T *)realloc(array->elements, newCapacity * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (!newElements) {
            // Handle memory allocation error
            return;
        }
        array->elements = newElements;
        array->capacity = newCapacity;
    }
    array->elements[array->size++] = element;
}

struct NFAPI_CRC_INDICATION_PDU_T removeElementFromDynamicArray(struct DynamicArray *array, size_t index) {
    if (index >= array->size) {
        // Handle invalid index error
        return NULL;
    }
    struct NFAPI_CRC_INDICATION_PDU_T element = array->elements[index];
    memmove(&(array->elements[index]), &(array->elements[index + 1]), (array->size - index - 1) * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    array->size--;
    return element;
}

void iterateOverDynamicArrayForward(struct DynamicArray *array, void (*callback)(struct NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = 0; i < array->size; i++) {
        callback(&(array->elements[i]));
    }
}

void iterateOverDynamicArrayBackward(struct DynamicArray *array, void (*callback)(struct NFAPI_CRC_INDICATION_PDU_T)) {
    for (size_t i = array->size; i > 0; i--) {
        callback(&(array->elements[i - 1]));
    }
}

void freeDynamicArray(struct DynamicArray *array) {
    free(array->elements);
}

