#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

typedef struct Record {
    int key;
    long offset;
    double value;
} Record;

typedef struct DataStructure {
    Record* records;
    size_t recordCount;
    size_t maxRecordCount;
} DataStructure;

DataStructure* initializeDataStructure(size_t maxRecordCount) {
    // Allocate memory for the data structure
    DataStructure* ds = (DataStructure*)malloc(sizeof(DataStructure));
    if (!ds) {
        return NULL;
    }

    // Initialize the data structure fields
    ds->records = (Record*)calloc(maxRecordCount, sizeof(Record));
    if (!ds->records) {
        free(ds);
        return NULL;
    }
    ds->recordCount = 0;
    ds->maxRecordCount = maxRecordCount;

    // Initialize the mutex for concurrent access
    pthread_mutex_init(&ds->mutex, NULL);

    return ds;
}

void addRecord(DataStructure* ds, int key, long offset, double value) {
    // Lock the mutex to ensure thread-safe access
    pthread_mutex_lock(&ds->mutex);

    // Check if the record exists already
    size_t i;
    for (i = 0; i < ds->recordCount; ++i) {
        if (ds->records[i].key == key) {
            break;
        }
    }

    // If the record doesn't exist, add it to the end of the array
    if (i == ds->recordCount) {
        if (ds->recordCount >= ds->maxRecordCount) {
            free(ds);
            pthread_mutex_unlock(&ds->mutex);
            return;
        }
        ds->records[ds->recordCount].key = key;
        ds->records[ds->recordCount].offset = offset;
        ds->records[ds->recordCount].value = value;
        ++ds->recordCount;
    } else {
        // If the record exists, update its values
        ds->records[i].offset = offset;
        ds->records[i].value = value;
    }

    pthread_mutex_unlock(&ds->mutex);
}

bool loadData(DataStructure* ds, const char* filePath) {
    // Open the input file
    FILE* inFile = fopen(filePath, "r");
    if (!inFile) {
        printf("Error opening file: %s\n", strerror(errno));
        return false;
    }

    // Read the records from the file
    Record record;
    while (fscanf(inFile, "%d,%ld,%lf", &record.key, &record.offset, &record.value) == 3) {
        addRecord(ds, record.key, record.offset, record.value);
    }

    // Close the input file
    fclose(inFile);

    return true;
}

bool loadDataFromMultipleSources(DataStructure* ds, const char** filePaths, int numFiles) {
    for (int i = 0; i < numFiles; ++i) {
        if (!loadData(ds, filePaths[i])) {
            return false;
        }
    }
    return true;
}

void freeDataStructure(DataStructure* ds) {
    // Free the memory allocated for the data structure
    pthread_mutex_destroy(&ds->mutex);
    free(ds->records);
    free(ds);
}
```
This code implements a function `initializeDataStructure` that initializes a dynamic data structure with records containing an integer key, a long offset, and a double value. It also includes functions for adding records to the structure, loading data from external sources, and freeing the memory allocated for the structure. The data structure is designed to be thread-safe, with a mutex used to ensure that concurrent access is handled correctly.

The function `addRecord` adds a new record to the data structure if it does not already exist, or updates an existing record's values if it does. It uses a lock to ensure thread-safe access.

