        // Resize the hash table with a factor of 2
        table->capacity *= 2;
        NFAPI_CRC_INDICATION_HASH_ENTRY_T* new_entries = malloc(table->capacity * sizeof(NFAPI_CRC_INDICATION_HASH_ENTRY_T));
        // Copy the old entries to the new table
        memcpy(new_entries, table->entries, table->size * sizeof(NFAPI_CRC_INDICATION_HASH_ENTRY_T));
        // Free the old entries
