        table->entries = new_entries;
    }
    // Calculate the hash value for the RNTI
    uint32_t hash_value = nfapi_crc_indication_hash(pdu.rnti);
    // Find an empty slot in the hash table
    while (table->entries[hash_value].rnti != 0) {
        hash_value++;
        if (hash_value == table->capacity) {
            hash_value = 0;
        }
    }
    // Store the item in the hash table
