        hash_value++;
        if (hash_value == table->capacity) {
            hash_value = 0;
        }
    }
    // Remove the item from the hash table
    table->entries[hash_value].rnti = 0;
    table->size--;
}

// Function to lookup an item in the hash table
NFAPI_CRC_INDICATION_PDU_T nfapi_crc_indication_lookup(NFAPI_CRC_INDICATION_HASH_TABLE_T* table, uint16_t rnti) {
    // Calculate the hash value for the RNTI
