    // Find the item in the hash table
    while (table->entries[hash_value].rnti != rnti) {
        hash_value++;
        if (hash_value == table->capacity) {
            hash_value = 0;
        }
    }
    // Return the item found in the hash table
    return table->entries[hash_value];
}

// Function to manage a pool of worker threads for parallel processing of operations
void nfapi_crc_indication_threadpool(NFAPI_CRC_INDICATION_HASH_TABLE_T* table) {
    // Initialize the thread pool with a fixed number of threads
