    int modulation_type;

    // Phase rotation
    int phase_rotation;

    // Noise variance estimate
    float noise_variance;
} LTE_PHY_RX_SYMBOL;

// Define dynamic array for managing RX frames
typedef struct {
    // Array of RX frames
    LTE_PHY_RX_FRAME *frames;

    // Size of the array
    size_t size;

    // Maximum number of elements in the array
    size_t capacity;
} LTE_PHY_RX_DYNAMIC_ARRAY;

// Define memory pool for managing RX frames and symbols
typedef struct {
    // Array of free memory blocks
    void **free_blocks;

    // Number of free memory blocks
    size_t num_free_blocks;

    // Size of each memory block
    size_t block_size;
} LTE_PHY_RX_MEMORY_POOL;

// Define function for initializing the dynamic array and memory pool
void init_rx_array(LTE_PHY_RX_DYNAMIC_ARRAY *array, size_t max_size) {
    // Initialize the dynamic array
    array->frames = (LTE_PHY_RX_FRAME *) malloc(max_size * sizeof(LTE_PHY_RX_FRAME));
    assert(array->frames != NULL);
    array->size = 0;
    array->capacity = max_size;

    // Initialize the memory pool
    LTE_PHY_RX_MEMORY_POOL *pool = (LTE_PHY_RX_MEMORY_POOL *) malloc(sizeof(LTE_PHY_RX_MEMORY_POOL));
    assert(pool != NULL);
    pool->free_blocks = (void **) malloc(max_size * sizeof(void *));
    assert(pool->free_blocks != NULL);
    pool->num_free_blocks = 0;
    pool->block_size = sizeof(LTE_PHY_RX_FRAME);

    // Set the memory pool for the dynamic array
    array->memory_pool = pool;
}

// Define function for adding a new RX frame to the dynamic array
void add_rx_frame(LTE_PHY_RX_DYNAMIC_ARRAY *array, LTE_PHY_RX_FRAME *frame) {
    // Check if there is enough space in the memory pool
    if (array->memory_pool->num_free_blocks == 0) {
        return;
    }

    // Allocate a new memory block from the pool
    void *new_block = malloc(array->memory_pool->block_size);
    assert(new_block != NULL);

    // Set the frame data in the new memory block
    LTE_PHY_RX_FRAME *new_frame = (LTE_PHY_RX_FRAME *) new_block;
    memcpy(new_frame, frame, array->memory_pool->block_size);

    // Add the new memory block to the free list
    array->memory_pool->free_blocks[array->memory_pool->num_free_blocks++] = new_block;

    // Increment the size of the dynamic array
    array->size++;
}

// Define function for removing a RX frame from the dynamic array
void remove_rx_frame(LTE_PHY_RX_DYNAMIC_ARRAY *array, size_t index) {
    // Check if the index is valid
    if (index >= array->size) {
        return;
    }

    // Get the memory block associated with the RX frame
    void *block = array->frames[index].memory_pool->free_blocks[array->memory_pool->num_free_blocks];

    // Decrement the number of free blocks in the memory pool
    array->memory_pool->num_free_blocks--;

    // Free the memory block
    free(block);

    // Move the last element to the index being removed
    memmove(&array->frames[index], &array->frames[index + 1], (array->size - index) * sizeof(LTE_PHY_RX_FRAME));

    // Decrement the size of the dynamic array
    array->size--;
}

// Define function for releasing resources associated with the dynamic array
void release_rx_array(LTE_PHY_RX_DYNAMIC_ARRAY *array) {
    // Free the memory pool
    free(array->memory_pool);

    // Free the dynamic array
    free(array->frames);
}

// Define function for handling RX frames in a circular buffer
void handle_rx_frames(LTE_PHY_RX_DYNAMIC_ARRAY *array, size_t num_frames) {
    // Handle the first frame differently
    add_rx_frame(array, array->frames[0]);

    // Handle the remaining frames
    for (size_t i = 1; i < num_frames; i++) {
        remove_rx_frame(array, i);
        add_rx_frame(array, array->frames[i]);
    }
}
