static void *mempool = NULL;

int initNetworkMonitoringSystem(size_t M) {
    if (M <= 0) {
        return -1; // Return error status for invalid size
    }

    // Allocate memory for the array of NetworkFlowRecords
    mempool = malloc(sizeof(LogEntry) * M);
    if (!mempool) {
        perror("malloc");
        return -1; // Return error status for allocation failure
    }

    // Initialize the NFAPI_CRC_INDICATION_PDU_T structures
