    for (i = 0; i < M; i++) {
        ((NFAPI_CRC_INDICATION_PDU_T *)mempool)[i].RX_UE_INFORMATION_TAG = rand();
        ((NFAPI_CRC_INDICATION_PDU_T *)mempool)[i].RNTI = rand();
        ((NFAPI_CRC_INDICATION_PDU_T *)mempool)[i].CRC_INDICATION_REL8_TAG = rand();
    }

    return 0; // Return success status
}

int deinitNetworkMonitoringSystem(void) {
    if (mempool) {
        free(mempool);
        mempool = NULL;
    }
    return 0; // Return success status
}

// Thread-safe function for adding a new LogEntry to the array
int addLogEntry(const char *message, int log_level) {
    pthread_mutex_lock(&mempool_lock);

    size_t M = (size_t)(mempool / sizeof(LogEntry));
    size_t i;
    for (i = 0; i < M; i++) {
        if (!((LogEntry *)mempool)[i].message) { // Check if entry is free
            ((LogEntry *)mempool)[i].timestamp = time(NULL);
            ((LogEntry *)mempool)[i].log_level = log_level;
            ((LogEntry *)mempool)[i].message = strdup(message);
            break;
        }
    }

    pthread_mutex_unlock(&mempool_lock);

    if (i == M) { // Return error status if no free entries found
        return -1;
    }

    return 0; // Return success status
}

// Thread-safe function for retrieving the next LogEntry from the array
int getNextLogEntry(const char **message, int *log_level) {
    pthread_mutex_lock(&mempool_lock);

    size_t M = (size_t)(mempool / sizeof(LogEntry));
    size_t i;
    for (i = 0; i < M; i++) {
        if (((LogEntry *)mempool)[i].message) { // Check if entry is used
            break;
        }
    }

    pthread_mutex_unlock(&mempool_lock);

    if (i == M) { // Return error status if no unused entries found
        return -1;
    }

    *message = ((LogEntry *)mempool)[i].message;
    *log_level = ((LogEntry *)mempool)[i].log_level;

    return 0; // Return success status
