#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

// Structure to represent a UE context record
typedef struct {
    char imsi[15];  // IMSI of the UE
    int rnti;       // RNTI of the UE
    int pdusessionid;  // PDU session ID of the UE
} ue_context_t;

// Linked list node to store UE context records
typedef struct {
    ue_context_t *ue_context;
    struct node *next;
} node_t;

// Array to store the UE context records
static ue_context_t *ue_contexts[10000];  // Maximum number of concurrent contexts supported is 10,000

// Mutex to protect the linked list and array data structures
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new UE context record
void add_ue_context(char *imsi, int rnti, int pdusessionid) {
    node_t *new_node = (node_t *)malloc(sizeof(node_t));
    if (!new_node) {
        fprintf(stderr, "Error: Failed to allocate memory for new UE context\n");
        return;
    }

    new_node->ue_context = (ue_context_t *)malloc(sizeof(ue_context_t));
    if (!new_node->ue_context) {
        fprintf(stderr, "Error: Failed to allocate memory for UE context\n");
        free(new_node);
        return;
    }

    strcpy(new_node->ue_context->imsi, imsi);
    new_node->ue_context->rnti = rnti;
    new_node->ue_context->pdusessionid = pdusessionid;

    pthread_mutex_lock(&mutex);
    ue_contexts[new_node->ue_context->pdusessionid] = new_node->ue_context;
    pthread_mutex_unlock(&mutex);
}

// Function to remove a UE context record by its PDU session ID
void remove_ue_context(int pdusessionid) {
    pthread_mutex_lock(&mutex);
    ue_context_t *ue_context = ue_contexts[pdusessionid];
    if (ue_context != NULL) {
        free(ue_context->imsi);
        free(ue_context);
        ue_contexts[pdusessionid] = NULL;
    }
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a UE context record by its IMSI
ue_context_t *get_ue_context(char *imsi) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < 10000; i++) {
        if (strcmp(imsi, ue_contexts[i]->imsi) == 0) {
            ue_context_t *ue_context = ue_contexts[i];
            pthread_mutex_unlock(&mutex);
            return ue_context;
        }
    }
    pthread_mutex_unlock(&mutex);
    return NULL;
}
```
