['```c
#include <stdbool.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Define the structure for a CRC indication PDU
typedef struct {
    uint32_t rx_ue_information_tag;
    uint32_t rnti;
    uint32_t crc_indication_rel8_tag;
    bool crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the pool of CRC indication PDUs
#define MAX_CRC_INDICATIONS 10000
static NFAPI_CRC_INDICATION_PDU_T crc_indications[MAX_CRC_INDICATIONS];

// Define the semaphore for protecting the pool of CRC indication PDUs
sem_t crc_indication_lock;

// Define the function to populate the pool of CRC indication PDUs
void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T *new_crc_indication) {
    // Acquire the lock on the pool of CRC indication PDUs
    sem_wait(&crc_indication_lock);

    // Check if there is space in the pool for a new CRC indication
    bool duplicate = false;
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        if (crc_indications[i].rnti == new_crc_indication->rnti) {
            duplicate = true;
            break;
        }
    }

    // If there is space, add the new CRC indication to the pool and release the lock
    if (!duplicate) {
        crc_indications[MAX_CRC_INDICATIONS].rx_ue_information_tag = new_crc_indication->rx_ue_information_tag;
        crc_indications[MAX_CRC_INDICATIONS].rnti = new_crc_indication->rnti;
        crc_indications[MAX_CRC_INDICATIONS].crc_indication_rel8_tag = new_crc_indication->crc_indication_rel8_tag;
        crc_indications[MAX_CRC_INDICATIONS].crcflag = new_crc_indication->crcflag;
        sem_post(&crc_indication_lock);
    } else {
        // If there is no space, release the lock and log a message indicating the duplication
        sem_post(&crc_indication_lock);
        printf("Duplicate RNTI detected. Skipping entry.\n");
    }
}

// Define the function to process CRC indications in a multi-threaded environment
void *process_crc_indications(void *arg) {
    // Acquire the lock on the pool of CRC indication PDUs
    sem_wait(&crc_indication_lock);

    // Check if there are any CRC indications in the pool to process
    bool more_to_process = false;
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        if (!crc_indications[i].rx_ue_information_tag) {
            more_to_process = true;
            break;
        }
    }

    // If there are CRC indications to process, proceed with processing them and releasing the lock
    if (more_to_process) {
        for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
            if (!crc_indications[i].rx_ue_information_tag) {
                break;
            }
            // Process the CRC indication here
            printf("Processing CRC indication with RNTI %d\n", crc_indications[i].rnti);
            // Clear the CRC indication from the pool once it has been processed
            memset(&crc_indications[i], 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        }
        sem_post(&crc_indication_lock);
    } else {
        // If there are no CRC indications to process, release the lock and wait for more CRC indications to arrive
        sem_post(&crc_indication_lock);
        printf("No CRC indications to process. Waiting for more.\n");
    }
}

int main() {
    // Initialize the pool of CRC indication PDUs and the semaphore for protecting the pool
    memset(crc_indications, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_CRC_INDICATIONS);
    sem_init(&crc_indication_lock, 1, 1);

    // Start a thread to process CRC indications in the background
    pthread_t process_thread;
    int rv = pthread_create(&process_thread, NULL, process_crc_indications, NULL);
    if (rv != 0) {
        printf("Error creating thread: %s\n", strerror(errno));
        return 1;
    }

    // Loop until the system is shut down or a timeout occurs
    while (true) {
        // Receive new CRC indications from the network
        NFAPI_CRC_INDICATION_PDU_T new_crc_indication = receive_crc_indication();

        // Populate the pool of CRC indication PDUs with the new CRC indication
        populate_crc_indications(&new_crc_indication);
    }
}
```
This code defines a structure for a CRC indication PDU, and a pool of such structures to manage up to 10,000 unique entries efficiently. The `populate_crc_indications` function checks if there is space in the pool for a new CRC indication, and adds it if there is. If the pool is full, the function skips the entry with a duplicate `RNTI` and logs an appropriate message.

The `process_crc_indications` function starts a thread that processes CRC indications in the background. The thread waits for new CRC indications to arrive in the pool, and processes them one by one until the system is shut down or a timeout occurs.

In the `main` function, we initialize the pool of CRC indication PDUs and the semaphore for protecting the pool. We then start a thread to process CRC indications in the background using the `pthread_create` function. The main loop receives new CRC indications from the network, populates the pool with them using the `populate_crc_indications` function, and continues until the system is shut down or a timeout occurs.']

