#include <string.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>

struct LTE_PHY_RX_FRAME {
    struct LTE_PHY_HEADER header;
    int signal_strength;
    size_t num_symbols;
    struct LTE_PHY_RX_SYMBOL *symbols;
};

struct LTE_PHY_RX_SYMBOL {
    enum ModulationType modulation;
    int phase_rotation;
    float noise_variance_estimate;
};

struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned short RX_UE_INFORMATION_TAG;
    unsigned long RNTI;
    enum CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
};

void init_rx_frame(struct LTE_PHY_RX_FRAME *frame) {
    frame->header.valid = 0;
    frame->signal_strength = -127;
    frame->num_symbols = 0;
    frame->symbols = NULL;
}

void free_rx_frame(struct LTE_PHY_RX_FRAME *frame) {
    if (frame->symbols != NULL) {
        for (size_t i = 0; i < frame->num_symbols; i++) {
            free(frame->symbols[i]);
        }
        free(frame->symbols);
    }
}

int read_binary_file(const char *path, void **data, size_t *size) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) {
        return -1;
    }

    struct stat sb;
    if (fstat(fd, &sb) != 0) {
        close(fd);
        return -2;
    }

    void *buffer = malloc(sb.st_size + 1);
    if (buffer == NULL) {
        close(fd);
        return -3;
    }

    ssize_t bytes_read = read(fd, buffer, sb.st_size);
    if (bytes_read < 0) {
        free(buffer);
        close(fd);
        return -4;
    } else if ((size_t)bytes_read != sb.st_size) {
        free(buffer);
        close(fd);
        return -5;
    }

    close(fd);

    *data = buffer;
    *size = sb.st_size;

    return 0;
}

int deserialize_rx_frame(struct LTE_PHY_RX_FRAME *frame, const void *data, size_t size) {
    if (frame == NULL || data == NULL || size <= 0) {
        return -1;
    }

    // Deserialize the frame header
    struct LTE_PHY_HEADER *header = (struct LTE_PHY_HEADER *)data;
    if (!header->valid) {
        return -2;
    }

    // Initialize the frame structure
    init_rx_frame(frame);

    // Deserialize the signal strength indicator
    int *signal_strength = (int *)(data + sizeof(*header));
    frame->signal_strength = *signal_strength;

    // Deserialize the number of symbols
    size_t *num_symbols = (size_t *)(data + sizeof(*header) + sizeof(*signal_strength));
    frame->num_symbols = *num_symbols;

    // Allocate memory for the symbol list
    struct LTE_PHY_RX_SYMBOL **symbols = malloc(frame->num_symbols * sizeof(struct LTE_PHY_RX_SYMBOL));
    if (symbols == NULL) {
        free_rx_frame(frame);
        return -3;
    }

    // Deserialize the symbol list
    for (size_t i = 0; i < frame->num_symbols; i++) {
        struct LTE_PHY_RX_SYMBOL *symbol = symbols[i];

        // Deserialize the modulation type
        enum ModulationType *modulation = (enum ModulationType *)(data + sizeof(*header) + sizeof(*signal_strength) + i * sizeof(struct LTE_PHY_RX_SYMBOL));
        symbol->modulation = *modulation;

        // Deserialize the phase rotation
        int *phase_rotation = (int *)(data + sizeof(*header) + sizeof(*signal_strength) + i * sizeof(struct LTE_PHY_RX_SYMBOL) + sizeof(*modulation));
        symbol->phase_rotation = *phase_rotation;

        // Deserialize the noise variance estimate
        float *noise_variance_estimate = (float *)(data + sizeof(*header) + sizeof(*signal_strength) + i * sizeof(struct LTE_PHY_RX_SYMBOL) + sizeof(*modulation) + sizeof(*phase_rotation));
        symbol->noise_variance_estimate = *noise_variance_estimate;
    }

    // Populate the NFAPI_CRC_INDICATION_PDU_T instances
    for (size_t i = 0; i < frame->num_symbols; i++) {
        struct LTE_PHY_RX_SYMBOL *symbol = symbols[i];
        struct NFAPI_CRC_INDICATION_PDU *pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU));
        if (pdu == NULL) {
            free_rx_frame(frame);
            return -3;
        }
        pdu->modulation = symbol->modulation;
        pdu->phase_rotation = symbol->phase_rotation;
        pdu->noise_variance_estimate = symbol->noise_variance_estimate;
    }

    // Free the deserialized data
    free(symbols);

    return 0;
}

int main() {
    const char *path = "test.bin";
    void *data = NULL;
    size_t size = 0;

    int ret = read_binary_file(path, &data, &size);
    if (ret != 0) {
        printf("Error reading binary file: %s\n", strerror(ret));
        return -1;
    }

