#include <fstream>
#include <iostream>
#include <vector>

using namespace std;

// Read a binary file into a buffer
int read_binary_file(const char *path, vector<char> &data) {
    ifstream in(path, ios::binary);
    if (!in) {
        return -1;
    }

    // Get the size of the file
    in.seekg(0, ios::end);
    int size = in.tellg();
    in.seekg(0, ios::beg);

    // Read the entire file into a buffer
    data.resize(size);
    in.read(&data[0], size);

    return 0;
}

// Deserialize an RX frame from a binary buffer
int deserialize_rx_frame(const vector<char> &data, struct LTE_PHY_RX_FRAME *frame) {
    if (data.empty() || frame == NULL) {
        return -1;
    }

    // Read the header of the RX frame
    struct LTE_PHY_RX_HEADER header = *((struct LTE_PHY_RX_HEADER *)&data[0]);
    int num_rx_symbols = header.num_rx_symbols;
    int num_rx_data = header.num_rx_data;

    // Read the RX symbols of the frame
    vector<struct LTE_PHY_RX_SYMBOL> rx_symbols(num_rx_symbols);
    for (int i = 0; i < num_rx_symbols; ++i) {
        struct LTE_PHY_RX_SYMBOL symbol = *((struct LTE_PHY_RX_SYMBOL *)&data[sizeof(header) + i*sizeof(struct LTE_PHY_RX_SYMBOL)]);
        rx_symbols[i] = symbol;
    }

    // Read the RX data of the frame
    vector<char> rx_data(num_rx_data);
    for (int i = 0; i < num_rx_data; ++i) {
        char data_byte = *((char *)&data[sizeof(header) + num_rx_symbols*sizeof(struct LTE_PHY_RX_SYMBOL) + i]);
        rx_data[i] = data_byte;
    }

    // Assign the deserialized RX frame to the output parameter
    frame->rx_header = header;
    frame->rx_symbols = rx_symbols;
    frame->rx_data = rx_data;

    return 0;
}
