#include <boost/asio.hpp>
#include <boost/json.hpp>
#include <iostream>
#include <string>
#include <thread>
#include <vector>

using namespace boost::asio;
using namespace boost::json;
using std::cout;
using std::endl;
using std::string;
using std::vector;

class HttpClient {
 public:
  HttpClient(const string& host, const unsigned short port) :
    host_(host), port_(port) {}

  void sendRequest(const string& request_type, const string& url,
                   const vector<string>& headers = {},
                   const string& body = "") {
    // Create a socket to the host and port.
    io_context context;
    tcp::socket socket(context);
    boost::system::error_code error;
    socket.connect(tcp::endpoint(boost::asio::ip::make_address(host_), port_),
                   error);
    if (error) {
      cout << "Error connecting to host: " << error.message() << endl;
      return;
    }

    // Send the request.
    boost::beast::http::request<boost::beast::http::string_body> request(request_type);
    request.set(boost::beast::http::field::host, host_);
    for (const auto& header : headers) {
      request.add_header(boost::beast::http::make_header_value_pair(header));
    }
    request.body() = body;
    request.prepare();
    boost::system::error_code send_error;
    size_t bytes_sent = socket.write_some(request.data(), send_error);
    if (send_error) {
      cout << "Error sending request: " << send_error.message() << endl;
      return;
    }

    // Read the response.
    boost::beast::http::response<boost::beast::http::string_body> response;
    boost::system::error_code read_error;
    size_t bytes_read = socket.read_some(response.data(), read_error);
    if (read_error) {
      cout << "Error reading response: " << read_error.message() << endl;
      return;
    }

    // Print the response.
    cout << "Response: " << response.body().c_str() << endl;
  }

 private:
  string host_;
  unsigned short port_;
};

int main() {
  // Create a HTTP client for making requests to the web service.
  HttpClient http_client("example.com", 80);

  // Send a GET request to the web service.
  vector<string> headers;
  headers.push_back("Accept: application/json");
  string body;
  http_client.sendRequest("GET", "/api/data", headers, body);

  // Send a POST request to the web service with a JSON body.
  headers.clear();
  headers.push_back("Content-Type: application/json");
  json data = {{"key1", "value1"}, {"key2", "value2"}};
  body = boost::json::serialize(data);
  http_client.sendRequest("POST", "/api/data", headers, body);

  return 0;
}
