            *head = new_node;
            *tail = new_node;
        } else {
            (*tail)->next = new_node;
            new_node->prev = *tail;
            *tail = new_node;
        }

        // Calculate the average transmission power level for all frames in the list
        float total_power = 0.0f;
        struct FrameMetadata* curr_node = *head;
        while (curr_node != NULL) {
            total_power += curr_node->transmission_power_level;
            curr_node = curr_node->next;
