// Structures to represent a node in the graph and its records
struct Node {
    int key;
    struct Record* head;
};

struct Record {
    float value;
    struct Node* next;
};

// Function to initialize the linked list of records for each node
void init_records(struct Node* nodes, size_t num_nodes, size_t record_limit) {
    // Allocate memory for the records and initialize their values
    size_t total_records = 0;
    struct Record* curr = NULL;
    for (size_t i = 0; i < num_nodes; i++) {
        nodes[i].head = malloc(sizeof(struct Record));
        nodes[i].head->value = 1.0f; // Initialize the value of the first record
        total_records++;

        // Add additional records to the linked list
        curr = nodes[i].head;
        while (total_records < record_limit) {
            struct Record* new_record = malloc(sizeof(struct Record));
            new_record->value = 1.0f / (float)(total_records + 1); // Initialize the value of the new record
            curr->next = new_record;
            curr = new_record;
            total_records++;
        }
    }

    // Ensure that the total number of records across all nodes does not exceed the limit
    assert(total_records <= record_limit);
}

int main() {
    // Define the number of nodes and the limit on the number of records per node
    size_t num_nodes = 10;
    size_t record_limit = 50;

    // Allocate memory for the nodes
    struct Node* nodes = malloc(sizeof(struct Node) * num_nodes);
    memset(nodes, 0, sizeof(struct Node) * num_nodes);

    // Initialize the linked list of records for each node
    init_records(nodes, num_nodes, record_limit);

    // Perform some operations on the graph
    // ...

    // Clean up memory
    for (size_t i = 0; i < num_nodes; i++) {
        struct Record* curr = nodes[i].head;
        while (curr != NULL) {
            free(curr);
            curr = curr->next;
        }
        free(nodes[i].head);
    }
    free(nodes);

    return 0;
}
