    int *keys;
    size_t capacity;
} Keys;

// Structure for holding record nodes
typedef struct {
    int value;
    struct RecordNode *next;
} RecordNode;

// Function to initialize and populate the offsets, keys, and records structures
void initAndPopulate(Offsets *offsets, Keys *keys, RecordNode **records, size_t recordCount) {
    // Initialize the offsets structure
    offsets->capacity = recordCount;
    offsets->offsets = malloc(sizeof(long) * recordCount);
    if (offsets->offsets == NULL) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        return;
    }

    // Initialize the keys structure
    keys->capacity = recordCount;
    keys->keys = malloc(sizeof(int) * recordCount);
    if (keys->keys == NULL) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(offsets->offsets);
        offsets->offsets = NULL;
        return;
    }

    // Initialize the records structure
    *records = malloc(sizeof(RecordNode) * recordCount);
    if (*records == NULL) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        free(offsets->offsets);
        offsets->offsets = NULL;
        free(keys->keys);
        keys->keys = NULL;
        return;
    }

    // Populate the records structure with int values within a specified range
    for (size_t i = 0; i < recordCount; i++) {
        (*records)[i].value = rand() % 100;
        if (i > 0) {
            (*records)[i - 1].next = &(*records)[i];
        }
    }

    // Update the offsets and keys structures
    for (size_t i = 0; i < recordCount; i++) {
        offsets->offsets[i] = (*records)[i].value;
        keys->keys[i] = (*records)[i].value % 10;
    }
}

// Function to clean up the allocated memory
void freeMemory(Offsets *offsets, Keys *keys, RecordNode **records) {
    // Free the offsets and keys structures
    if (offsets->offsets != NULL) {
        free(offsets->offsets);
        offsets->offsets = NULL;
    }
    if (keys->keys != NULL) {
        free(keys->keys);
        keys->keys = NULL;
    }

    // Free the records structure
    if (*records != NULL) {
        RecordNode *current = *records;
        while (current != NULL) {
            RecordNode *next = current->next;
            free(current);
            current = next;
        }
        *records = NULL;
    }
}
```
