struct NFAPI_CRC_INDICATION_PDU_T *populate_crc_indication_pdu(const char* filename, struct NFAPI_CRC_INDICATION_PDU_T **array) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        printf("Error: failed to open file %s\n", filename);
        return NULL;
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int count = 0, i = 0, j = 0;
    struct NFAPI_CRC_INDICATION_PDU_T *pdu = NULL;

    while (fscanf(fp, "%d", &count) == 1 && count > 0) {
        pthread_mutex_lock(&mutex);
        if (*array == NULL || i >= MAX_STRUCTS || j >= MAX_RNTI) {
            printf("Error: reached maximum number of structures or RNTIs\n");
            fclose(fp);
            return NULL;
        }
        pdu = &(*array)[i];
        if (fscanf(fp, "%d", &pdu->RX_UE_INFORMATION_TAG) == 1 && fscanf(fp, "%d", &pdu->CRC_INDICATION_REL8_TAG) == 1) {
            pdu->RNTI = j;
            i++;
        } else {
            printf("Error: failed to read RX_UE_INFORMATION_TAG or CRC_INDICATION_REL8_TAG\n");
        }
        pthread_mutex_unlock(&mutex);
    }

    fclose(fp);
    return *array;
}
