// Thread-safe linked list node structure to store the NFAPI_CRC_INDICATION_PDU_T structures
struct nfapi_crc_indication_node {
    struct nfapi_crc_indication_data data;
    struct nfapi_crc_indication_node *next;
};

// Global variable to store the head node of the linked list
struct nfapi_crc_indication_node *head = NULL;

// Global variable to store the mutex for synchronizing access to the linked list
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to dynamically build and manage the thread-safe linked list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_list(struct nfapi_crc_indication_data *data) {
    // Acquire the mutex to synchronize access to the linked list
    pthread_mutex_lock(&mutex);

    // Create a new node for the NFAPI_CRC_INDICATION_PDU_T structure and store it in the linked list
    struct nfapi_crc_indication_node *new_node = malloc(sizeof(struct nfapi_crc_indication_node));
    new_node->data = *data;
    new_node->next = head;
    head = new_node;

    // Release the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&mutex);
}

// Function to retrieve a NFAPI_CRC_INDICATION_PDU_T structure from the linked list with a specific RX_UE_INFORMATION_TAG and RNTI
struct nfapi_crc_indication_data *nfapi_crc_indication_get(uint16_t rx_ue_information_tag, uint16_t rnti) {
    // Acquire the mutex to synchronize access to the linked list
    pthread_mutex_lock(&mutex);

    // Iterate through the linked list until a matching RX_UE_INFORMATION_TAG and RNTI is found
    struct nfapi_crc_indication_node *current_node = head;
    while (current_node != NULL) {
        if (current_node->data.rx_ue_information_tag == rx_ue_information_tag && current_node->data.rnti == rnti) {
            // Release the mutex to allow other threads to access the linked list
            pthread_mutex_unlock(&mutex);

            return &(current_node->data);
        }

        current_node = current_node->next;
    }

    // Release the mutex to allow other threads to access the linked list
    pthread_mutex_unlock(&mutex);

    return NULL;
}
```
