// Header file for LTE_PHY_RX_FRAME array management
#include <stdlib.h> // For memory allocation
#include <pthread.h> // For synchronization
#include "logging.h" // For logging

typedef struct {
    int header;
    float signal_strength;
    LTE_PHY_RX_SYMBOL* symbols;
} LTE_PHY_RX_FRAME;

// Function to add a new frame to the array
void add_frame(LTE_PHY_RX_FRAME* frame) {
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    LTE_PHY_RX_FRAME* new_frame = (LTE_PHY_RX_FRAME*) malloc(sizeof(LTE_PHY_RX_FRAME));
    if (new_frame == NULL) { // Handle memory allocation failure
        log_error("Memory allocation failed");
        pthread_mutex_unlock(&frame_array_mutex);
        return;
    }
    *new_frame = *frame; // Copy frame data to new structure
    new_frame->symbols = (LTE_PHY_RX_SYMBOL*) malloc(sizeof(LTE_PHY_RX_SYMBOL) * frame->num_symbols);
    if (new_frame->symbols == NULL) { // Handle memory allocation failure
        log_error("Memory allocation failed");
        free(new_frame);
        pthread_mutex_unlock(&frame_array_mutex);
        return;
    }
    memcpy(new_frame->symbols, frame->symbols, sizeof(LTE_PHY_RX_SYMBOL) * frame->num_symbols);
    new_frame->next = NULL; // Set next pointer to null
    if (frame_array == NULL) { // If array is empty, set first element
        frame_array = new_frame;
    } else {
        frame_tail->next = new_frame; // Add new element to end of list
    }
    frame_tail = new_frame; // Update tail pointer
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
}

// Function to update a frame in the array
void update_frame(int index, LTE_PHY_RX_FRAME* frame) {
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    if (index >= 0 && index < num_frames) { // Check validity of index
        LTE_PHY_RX_FRAME* current_frame = frame_array;
        int i = 0;
        while (i < index && current_frame != NULL) { // Find frame at specified index
            current_frame = current_frame->next;
            i++;
        }
        if (current_frame == NULL) { // Handle invalid index
            log_error("Frame not found");
            pthread_mutex_unlock(&frame_array_mutex);
            return;
        }
        *current_frame = *frame; // Copy frame data to existing structure
        memcpy(current_frame->symbols, frame->symbols, sizeof(LTE_PHY_RX_SYMBOL) * current_frame->num_symbols);
    } else {
        log_error("Invalid index");
    }
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
}

// Function to retrieve a frame from the array
LTE_PHY_RX_FRAME* get_frame(int index) {
    LTE_PHY_RX_FRAME* result = NULL;
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    if (index >= 0 && index < num_frames) { // Check validity of index
        LTE_PHY_RX_FRAME* current_frame = frame_array;
        int i = 0;
        while (i < index && current_frame != NULL) { // Find frame at specified index
            current_frame = current_frame->next;
            i++;
        }
        if (current_frame == NULL) { // Handle invalid index
            log_error("Frame not found");
            pthread_mutex_unlock(&frame_array_mutex);
            return result;
        }
        result = current_frame; // Copy frame data to existing structure
    } else {
        log_error("Invalid index");
    }
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
    return result;
}

// Function to retrieve the number of frames in the array
int get_num_frames() {
    int result = 0;
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    result = num_frames;
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
    return result;
}

// Function to delete a frame from the array
void delete_frame(int index) {
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    if (index >= 0 && index < num_frames) { // Check validity of index
        LTE_PHY_RX_FRAME* current_frame = frame_array;
        int i = 0;
        while (i < index && current_frame != NULL) { // Find frame at specified index
            current_frame = current_frame->next;
            i++;
        }
        if (current_frame == NULL) { // Handle invalid index
            log_error("Frame not found");
            pthread_mutex_unlock(&frame_array_mutex);
            return;
        }
        LTE_PHY_RX_FRAME* previous_frame = current_frame->prev;
        if (previous_frame != NULL) { // If frame is not first in list, update previous frame's next pointer
            previous_frame->next = current_frame->next;
        } else { // If frame is first in list, update head pointer
            frame_array = current_frame->next;
        }
        free(current_frame); // Free frame memory
        num_frames--; // Decrement frame count
    } else {
        log_error("Invalid index");
    }
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
}

// Function to delete all frames from the array
void delete_all_frames() {
    pthread_mutex_lock(&frame_array_mutex); // Lock for thread-safe access
    while (num_frames > 0) {
        LTE_PHY_RX_FRAME* current_frame = frame_array;
        free(current_frame); // Free frame memory
        num_frames--; // Decrement frame count
    }
    pthread_mutex_unlock(&frame_array_mutex); // Unlock mutex
}

