#include <thread>

class Data {
public:
    int randomNum;
    char buffer[16]; // fixed-size string
    float* arr; // dynamically allocated array
};

// Memory pool for allocating memory
class MemoryPool {
public:
    MemoryPool(size_t size) : size_(size), freeList_(nullptr) {}

    void* allocate(size_t n) {
        if (n > size_) {
            return nullptr; // allocation failed
        }

        std::unique_lock<std::mutex> lock(mutex_);

        // find a suitable block in the free list
        void* p = nullptr;
        for (auto it = freeList_.begin(); it != freeList_.end(); ++it) {
            if (*it >= n) {
                p = *it;
                freeList_.erase(it);
                break;
            }
        }

        // allocate a new block from the system if necessary
        if (!p) {
            p = std::malloc(n);
        }

        return p;
    }

    void deallocate(void* p, size_t n) {
        if (n > size_) {
            return; // deallocation failed
        }

        std::unique_lock<std::mutex> lock(mutex_);
        freeList_.insert(p);
    }

private:
    const size_t size_;
    std::set<void*> freeList_;
    std::mutex mutex_;
};

// Custom allocator for managing memory pool
class Allocator {
public:
    Allocator(MemoryPool& pool) : pool_(pool) {}

    void* allocate(size_t n) {
        return pool_.allocate(n);
    }

    void deallocate(void* p, size_t n) {
        pool_.deallocate(p, n);
    }

private:
    MemoryPool& pool_;
};

// The function that manages memory allocation for the data structures
void handleCharacterActions(int numActions, int minKey, int maxKey, int bufferSize) {
    // create an allocator object to manage the memory pool
    Allocator alloc;

    // allocate memory for the arrays of offsets, keys, and Data structures
    auto offsetArray = (long*)alloc.allocate(numActions * sizeof(long));
    if (!offsetArray) {
        std::cerr << "Failed to allocate memory for offset array\n";
        return;
    }

    auto keyArray = (int*)alloc.allocate(numActions * sizeof(int));
    if (!keyArray) {
        std::cerr << "Failed to allocate memory for key array\n";
        alloc.deallocate(offsetArray, numActions * sizeof(long));
        return;
    }

    auto dataArray = (Data*)alloc.allocate(numActions * sizeof(Data));
    if (!dataArray) {
        std::cerr << "Failed to allocate memory for Data array\n";
        alloc.deallocate(offsetArray, numActions * sizeof(long));
        alloc.deallocate(keyArray, numActions * sizeof(int));
        return;
    }

    // generate random numbers for the offset and key arrays
    srand(time(nullptr));
    for (size_t i = 0; i < numActions; ++i) {
        offsetArray[i] = rand() % 1000;
        keyArray[i] = minKey + rand() % (maxKey - minKey);
    }

    // fill the buffer for each Data structure with a fixed-size string
    for (size_t i = 0; i < numActions; ++i) {
        std::string str("Hello, World!");
        std::memcpy(dataArray[i].buffer, str.c_str(), bufferSize);
    }

    // allocate memory for the float array in each Data structure
    size_t arrSize = 10; // predefined size
    for (size_t i = 0; i < numActions; ++i) {
        dataArray[i].arr = (float*)alloc.allocate(arrSize * sizeof(float));
        if (!dataArray[i].arr) {
            std::cerr << "Failed to allocate memory for float array\n";
            alloc.deallocate(offsetArray, numActions * sizeof(long));
            alloc.deallocate(keyArray, numActions * sizeof(int));
            alloc.deallocate(dataArray, numActions * sizeof(Data));
            return;
        }
    }

    // print the selected attack number to the console
    for (size_t i = 0; i < numActions; ++i) {
        std::cout << "Selected attack: " << keyArray[i] << "\n";
    }

    // deallocate memory for the arrays and Data structures
    alloc.deallocate(offsetArray, numActions * sizeof(long));
    alloc.deallocate(keyArray, numActions * sizeof(int));
    alloc.deallocate(dataArray, numActions * sizeof(Data));
}']

