typedef struct nfapi_crc_indication_list {
  size_t count; // Number of elements in the list
  size_t capacity; // Maximum number of elements that can be stored in the list
  pthread_mutex_t lock; // Mutex to ensure thread safety
  nfapi_crc_indication_pdu_t* data; // Pointer to an array of NFAPI_CRC_INDICATION_PDU_T structures
} nfapi_crc_indication_list_t;

// Function to create a new list of NFAPI_CRC_INDICATION_PDU_T structures
nfapi_crc_indication_list_t* nfapi_create_crc_indication_list(size_t capacity) {
  nfapi_crc_indication_list_t* list = (nfapi_crc_indication_list_t*)malloc(sizeof(nfapi_crc_indication_list_t));
  if (!list) {
    return NULL;
  }

  // Initialize the list with the specified capacity and a mutex for thread safety
  list->count = 0;
  list->capacity = capacity;
  pthread_mutex_init(&(list->lock), NULL);
  list->data = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t) * capacity);
  if (!list->data) {
    free(list);
    return NULL;
  }

  return list;
}

// Function to insert a new NFAPI_CRC_INDICATION_PDU_T structure into the list
bool nfapi_insert_crc_indication(nfapi_crc_indication_list_t* list, uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag) {
  if (!list || !list->data) {
    return false;
  }

  pthread_mutex_lock(&(list->lock));

  // Check if the list is full and needs to be resized
  if (list->count == list->capacity) {
    size_t new_capacity = list->capacity * 2;
    nfapi_crc_indication_pdu_t* new_data = (nfapi_crc_indication_pdu_t*)realloc(list->data, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
    if (!new_data) {
      pthread_mutex_unlock(&(list->lock));
      return false;
    }

    list->data = new_data;
    list->capacity = new_capacity;
  }

  // Insert the new element at the end of the list
  size_t index = list->count++;
  list->data[index].rx_ue_information_tag = rx_ue_information_tag;
  list->data[index].rnti = rnti;
  list->data[index].crc_indication_rel8_tag = crc_indication_rel8_tag;

  pthread_mutex_unlock(&(list->lock));

  return true;
}

// Function to remove a NFAPI_CRC_INDICATION_PDU_T structure from the list by its index
bool nfapi_remove_crc_indication(nfapi_crc_indication_list_t* list, size_t index) {
  if (!list || !list->data) {
    return false;
  }

  pthread_mutex_lock(&(list->lock));

  // Check if the specified index is valid
  if (index >= list->count) {
    pthread_mutex_unlock(&(list->lock));
    return false;
  }

  // Shift all elements after the specified index to fill the gap
  for (size_t i = index + 1; i < list->count; ++i) {
    list->data[i - 1] = list->data[i];
  }

  // Decrement the count and reallocate memory if necessary
  --list->count;
  if (list->capacity > 2 * list->count) {
    size_t new_capacity = list->count;
    nfapi_crc_indication_pdu_t* new_data = (nfapi_crc_indication_pdu_t*)realloc(list->data, sizeof(nfapi_crc_indication_pdu_t) * new_capacity);
    if (!new_data) {
      pthread_mutex_unlock(&(list->lock));
      return false;
    }

    list->data = new_data;
    list->capacity = new_capacity;
  }

  pthread_mutex_unlock(&(list->lock));

  return true;
}

