    return NULL;
  }

  pthread_mutex_lock(&(list->lock));

  // Check if the specified index is valid
  if (index >= list->count) {
    pthread_mutex_unlock(&(list->lock));
    return NULL;
  }

  nfapi_crc_indication_pdu_t* element = &(list->data[index]);

  pthread_mutex_unlock(&(list->lock));

  return element;
}

