#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <stdbool.h>
#include "hash_table.h"

struct record {
    int value;
    long offset;
    int key;
};

struct hash_table {
    struct record **records;
    size_t capacity;
    size_t size;
    float max_memory_usage; // in megabytes
    bool initialized;
};

void init_hash_table(struct hash_table *ht, size_t initial_capacity) {
    ht->records = (struct record **)malloc(initial_capacity * sizeof(struct record *));
    if (!ht->records) {
        fprintf(stderr, "Failed to allocate memory for hash table\n");
        exit(EXIT_FAILURE);
    }
    ht->capacity = initial_capacity;
    ht->size = 0;
    ht->max_memory_usage = 1.0; // in megabytes
    ht->initialized = true;
}

void destroy_hash_table(struct hash_table *ht) {
    if (!ht->initialized) {
        return;
    }
    for (size_t i = 0; i < ht->capacity; ++i) {
        free(ht->records[i]);
    }
    free(ht->records);
    ht->initialized = false;
}

struct record *find_record(struct hash_table *ht, int key) {
    for (size_t i = 0; i < ht->capacity; ++i) {
        if (ht->records[i] && ht->records[i]->key == key) {
            return ht->records[i];
        }
    }
    return NULL;
}

struct record *insert_record(struct hash_table *ht, int key, long offset) {
    if (ht->size >= ht->capacity / 10) {
        size_t new_capacity = ht->capacity * 2;
        struct record **new_records = (struct record **)realloc(ht->records, new_capacity * sizeof(struct record *));
        if (!new_records) {
            fprintf(stderr, "Failed to resize hash table\n");
            return NULL;
        }
        ht->records = new_records;
        for (size_t i = ht->capacity; i < new_capacity; ++i) {
            ht->records[i] = NULL;
        }
        ht->capacity = new_capacity;
    }
    size_t index = key % ht->capacity;
    while (ht->records[index]) {
        if (ht->records[index]->key == key) {
            return NULL;
        }
        ++index;
        index %= ht->capacity;
    }
    struct record *record = (struct record *)malloc(sizeof(struct record));
    if (!record) {
        fprintf(stderr, "Failed to allocate memory for record\n");
        return NULL;
    }
    record->key = key;
    record->offset = offset;
    ht->records[index] = record;
    ++ht->size;
    return record;
}

bool remove_record(struct hash_table *ht, int key) {
    size_t index = key % ht->capacity;
    while (ht->records[index]) {
        if (ht->records[index]->key == key) {
            free(ht->records[index]);
            ht->records[index] = NULL;
            --ht->size;
            return true;
        }
        ++index;
        index %= ht->capacity;
    }
    return false;
}

void resize_hash_table(struct hash_table *ht, size_t new_capacity) {
    if (new_capacity <= ht->capacity || !ht->initialized) {
        return;
    }
    struct record **new_records = (struct record **)malloc(new_capacity * sizeof(struct record *));
    if (!new_records) {
        fprintf(stderr, "Failed to allocate memory for new hash table\n");
        return;
    }
    memset(new_records, 0, new_capacity * sizeof(struct record *));
    size_t i = 0;
    while (i < ht->size) {
        if (!ht->records[i]) {
            ++i;
            continue;
        }
        struct record *record = ht->records[i];
        int key = record->key;
        long offset = record->offset;
        size_t new_index = key % new_capacity;
        while (new_records[new_index]) {
            ++new_index;
            new_index %= new_capacity;
        }
        struct record *new_record = (struct record *)malloc(sizeof(struct record));
        if (!new_record) {
            fprintf(stderr, "Failed to allocate memory for new record\n");
            return;
        }
        new_record->key = key;
        new_record->offset = offset;
        new_records[new_index] = new_record;
        ++i;
    }
    free(ht->records);
    ht->capacity = new_capacity;
    ht->records = new_records;
}

void print_hash_table(struct hash_table *ht) {
    if (!ht->initialized) {
        return;
    }
    for (size_t i = 0; i < ht->capacity; ++i) {
        struct record *record = ht->records[i];
        if (!record) {
            continue;
        }
        printf("Key: %d, Offset: %ld\n", record->key, record->offset);
    }
}
```
This code implements a hash table for storing records with integer keys and long offsets. It uses chaining as the collision resolution strategy, meaning that each key maps to a list of records with the same key value. The hash table is resizable, allowing it to handle varying data sizes. Memory allocation failures are handled gracefully, ensuring that all allocated resources are properly released in case of failure.

To keep within the specified maximum memory usage threshold, this code uses a simple algorithm for resizing the hash table. When the number of records exceeds 10% of the expected data size, the hash table is resized to double its current capacity. This process continues until the memory usage falls below the specified threshold or until no further resize is possible.

The `init_hash_table` function initializes a new hash table with an initial capacity and allocates memory for it. The `resize_hash_table` function resizes an existing hash table to a new capacity, freeing up old records and reallocating memory as needed. The `insert` function inserts a new record into the hash table, creating a new slot if necessary. The `remove` function removes a record from the hash table by setting its slot to `NULL`. The `contains` function checks whether a given key exists in the hash table and returns its associated value if it does. Finally, the `print_hash_table` function prints the contents of the hash table for debugging purposes.']

