int init_msg_array(LTE_PHY_RRC_INTERFACE_API_MSG_T **msg_array, size_t num_threads) {
    // Allocate memory for the message array
    *msg_array = (LTE_PHY_RRC_INTERFACE_API_MSG_T *)malloc(num_threads * sizeof(LTE_PHY_RRC_INTERFACE_API_MSG_T));
    if (*msg_array == NULL) {
        return -1;
    }

    // Initialize each entry in the message array as unused
    for (size_t i = 0; i < num_threads; i++) {
        (*msg_array)[i].in_use = false;
    }

    return 0;
}

// Define the function to enqueue a message in the message queue
int enqueue_message(LTE_PHY_RRC_INTERFACE_API_MSG_T **msg_array, size_t num_threads, LTE_PHY_RRC_INTERFACE_API_MSG_T *msg) {
    // Find the first unused entry in the message array
    for (size_t i = 0; i < num_threads; i++) {
        if (!(*msg_array)[i].in_use) {
            (*msg_array)[i].msg = *msg;
            (*msg_array)[i].in_use = true;
            return 0;
        }
    }

    // If no unused entry is found, allocate a new message array and enqueue the message there
    LTE_PHY_RRC_INTERFACE_API_MSG_T *new_msg_array = (LTE_PHY_RRC_INTERFACE_API_MSG_T *)malloc(num_threads * sizeof(LTE_PHY_RRC_INTERFACE_API_MSG_T));
    if (new_msg_array == NULL) {
        return -1;
    }

    // Copy the unused entries from the old message array to the new one
    size_t num_unused_entries = 0;
    for (size_t i = 0; i < num_threads; i++) {
        if (!(*msg_array)[i].in_use) {
            new_msg_array[num_unused_entries++] = (*msg_array)[i];
        }
    }

    // Enqueue the message in the new message array
    new_msg_array[num_unused_entries].msg = *msg;
    new_msg_array[num_unused_entries].in_use = true;

    // Free the old message array and set the new one as the current one
    free(*msg_array);
    *msg_array = new_msg_array;

    return 0;
}

// Define the function to dequeue a message from the message queue
int dequeue_message(LTE_PHY_RRC_INTERFACE_API_MSG_T **msg_array, size_t num_threads, LTE_PHY_RRC_INTERFACE_API_MSG_T *msg) {
    // Find the first used entry in the message array
    for (size_t i = 0; i < num_threads; i++) {
        if ((*msg_array)[i].in_use) {
            (*msg_array)[i].in_use = false;
            *msg = (*msg_array)[i].msg;
            return 0;
        }
    }

    // If no used entry is found, return an error
    return -1;
}

// Define the function to free the memory allocated for a message array
int free_msg_array(LTE_PHY_RRC_INTERFACE_API_MSG_T **msg_array) {
