// Define the product structure
struct product {
    char* name;
    double price;
    struct date release_date;
};

// Function to dynamically allocate memory for a collection of products
struct product* read_products(const char* filepath, const int start_year, const int end_year) {
    // Open the CSV file
    FILE* fp = fopen(filepath, "r");
    if (fp == NULL) {
        printf("Error opening file %s\n", filepath);
        return NULL;
    }

    // Read the header row
    char header[1024];
    fgets(header, 1024, fp);

    // Initialize the product array
    struct product* products = (struct product*)malloc(sizeof(struct product) * 1000000);
    if (products == NULL) {
        printf("Error allocating memory for products\n");
        return NULL;
    }

    // Iterate over the rows in the CSV file
    int i = 0;
    while (fgets(header, 1024, fp)) {
        char* tokens[3];
        int token_count = 0;
        for (int j = 0; j < strlen(header); j++) {
            if (header[j] == ',' || header[j] == '\n') {
                tokens[token_count++] = &header[j + 1];
                header[j] = '\0';
            }
        }

        // Check for empty lines or invalid data
        if (token_count < 3) {
            printf("Skipping row with insufficient data\n");
            continue;
        }

        // Parse the product name and price
        char* name = tokens[0];
        double price = atof(tokens[1]);

        // Parse the release date
        struct date release_date;
        int year = atoi(tokens[2]);
        if (year >= start_year && year <= end_year) {
            release_date.year = year;
            release_date.month = 1;
            release_date.day = 1;
        } else {
            printf("Skipping row with invalid date\n");
            continue;
        }

        // Add the product to the array
        products[i++] = (struct product){name, price, release_date};
    }

    // Close the file
    fclose(fp);

    // Calculate the average price of products released within the specified year range
    double total_price = 0;
    int count = 0;
    for (int j = 0; j < i; j++) {
        struct product* product = &products[j];
        if (product->release_date.year >= start_year && product->release_date.year <= end_year) {
            total_price += product->price;
            count++;
        }
    }
    double average_price = total_price / count;

    // Identify the most frequently occurring product name across all products
    int max_count = 0;
    char* most_frequent_name = NULL;
    for (int j = 0; j < i; j++) {
        struct product* product = &products[j];
        if (product->release_date.year >= start_year && product->release_date.year <= end_year) {
            int count = 1;
            for (int k = j + 1; k < i; k++) {
                struct product* other_product = &products[k];
                if (strcmp(product->name, other_product->name) == 0 &&
                        other_product->release_date.year >= start_year &&
                        other_product->release_date.year <= end_year) {
                    count++;
                }
            }
            if (count > max_count) {
                most_frequent_name = product->name;
                max_count = count;
            }
        }
    }

    // Return the average price and the most frequently occurring product name
    struct result {
        double average_price;
        char* most_frequent_name;
    };
    return (struct result){average_price, most_frequent_name};
}
