// Define a custom allocator for efficient memory management
struct IntArray {
    int *data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
};

void int_array_init(struct IntArray *arr) {
    arr->capacity = 1024; // initial capacity of the array
    arr->size = 0; // current size of the array
    arr->data = (int *)malloc(sizeof(int) * arr->capacity);
    pthread_mutex_init(&arr->lock, NULL);
}

void int_array_destroy(struct IntArray *arr) {
    free(arr->data);
    pthread_mutex_destroy(&arr->lock);
}

void int_array_resize(struct IntArray *arr, size_t new_capacity) {
    if (new_capacity <= arr->size) {
        return;
    }
    int *tmp = (int *)realloc(arr->data, sizeof(int) * new_capacity);
    assert(tmp != NULL);
    arr->data = tmp;
    arr->capacity = new_capacity;
}

void int_array_insert(struct IntArray *arr, int element) {
    pthread_mutex_lock(&arr->lock);
    if (arr->size == arr->capacity) {
        int_array_resize(arr, 2 * arr->capacity);
    }
    arr->data[arr->size] = element;
    arr->size++;
    pthread_mutex_unlock(&arr->lock);
}

int int_array_find_largest(struct IntArray *arr) {
    int largest = INT_MIN;
    for (size_t i = 0; i < arr->size; i++) {
        if (arr->data[i] > largest) {
            largest = arr->data[i];
        }
    }
    return largest;
}

int main() {
