    record->num_segments = num_segments;
    record->segments = calloc(num_segments, sizeof(struct audio_segment));
    if (!record->segments) {
        free(record);
        return NULL;
    }
    pthread_mutex_init(&record->lock, NULL);
    return record;
}

void audio_record_cleanup(struct audio_record *record) {
    if (record->segments) {
        for (size_t i = 0; i < record->num_segments; ++i) {
            struct audio_segment *segment = &record->segments[i];
            free(segment->sample_buffer);
            segment->sample_buffer = NULL;
        }
        free(record->segments);
        record->segments = NULL;
    }
    pthread_mutex_destroy(&record->lock);
    free(record);
}

void audio_record_lock(struct audio_record *record) {
    pthread_mutex_lock(&record->lock);
