}

// Define a function to initialize the arrays and hash table, taking into account the memory constraints of the target platform.
void init_arrays(array_struct* arr) {
    // Initialize the offset array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->offset[i] = rand() % (arr->capacity - i);
    }

    // Initialize the key array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->key[i] = rand() % arr->capacity + 1;
    }

    // Initialize the record structure array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->records[i] = (record*)malloc(sizeof(record));
        arr->records[i]->value = rand() % arr->capacity + 1;
    }

    // Initialize the metadata structure array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->metadata[i] = (metadata**)malloc(sizeof(metadata));
        arr->metadata[i]->last_accessed = time(NULL);
    }

    // Initialize the hash table with a default load factor and a custom hash function
    for (int i = 0; i < arr->size; i++) {
        arr->table[i] = (hash_node*)malloc(sizeof(hash_node));
        arr->table[i]->key = arr->key[i];
        arr->table[i]->offset = arr->offset[i];
        arr->table[i]->record = arr->records[i];
        arr->table[i]->metadata = arr->metadata[i];
    }
}

// Define a function to populate the arrays and hash table with randomly generated data within given ranges for keys, offsets, and record values, along with initial access statistics, while minimizing the impact on system performance during initialization.
void populate_arrays(array_struct* arr) {
    // Populate the offset array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->offset[i] = rand() % (arr->capacity - i);
    }

    // Populate the key array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->key[i] = rand() % arr->capacity + 1;
    }

    // Populate the record structure array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->records[i]->value = rand() % arr->capacity + 1;
    }

    // Initialize the metadata structure array with random values within the specified range
    for (int i = 0; i < arr->size; i++) {
        arr->metadata[i]->last_accessed = time(NULL);
    }
}

// Define a custom hash function to ensure efficient lookups and minimal collisions, while also providing a mechanism to update the hash table's load factor dynamically.
unsigned long hash_function(int key) {
    unsigned long hash = 0;
    for (int i = 0; i < sizeof(key); i++) {
        hash += (key & (1 << i)) << ((sizeof(hash) - 1) * i);
    }
    return hash % arr->size;
}

// Define a function to update the hash table's load factor dynamically.
void update_load_factor(array_struct* arr, int new_size) {
    // Update the capacity of the arrays and reinitialize them with the new size.
    arr->capacity = new_size;
    init_arrays(arr);
}

// Define a function to add an entry to the hash table.
void add_entry(int key, int offset, record* value) {
