    if (search_key(key)) {
        printf("Key already exists in the hash table.");
        return;
    }

    // Calculate the index of the new entry.
    int index = hash_function(key);

    // Add the new entry to the hash table.
    arr->table[index] = (hash_node*)malloc(sizeof(hash_node));
    arr->table[index]->key = key;
    arr->table[index]->offset = offset;
    arr->table[index]->record = value;
}

// Define a function to search for an entry in the hash table.
bool search_entry(int key) {
    // Calculate the index of the entry.
    int index = hash_function(key);

    // Search for the entry.
    while (arr->table[index] != NULL) {
        if (arr->table[index]->key == key) {
            return true;
        }
        index++;
    }
    return false;
}

// Define a function to delete an entry from the hash table.
void delete_entry(int key) {
    // Calculate the index of the entry.
    int index = hash_function(key);

    // Search for the entry.
    while (arr->table[index] != NULL) {
        if (arr->table[index]->key == key) {
            free(arr->table[index]);
            arr->table[index] = NULL;
            return;
        }
        index++;
    }
}

// Define a function to print the hash table.
void print_hash_table() {
    // Print the hash table.
    for (int i = 0; i < arr->size; i++) {
        printf("%d, %d, %d\n", arr->table[i]->key, arr->table[i]->offset, arr->table[i]->record->value);
    }
}
