// Function to dynamically allocate memory for an array of NetworkEventLogEntries
NetworkEventLogEntry* allocate_log_entries(int N) {
    // Check if the requested size is valid
    if (N <= 0) {
        fprintf(stderr, "Invalid log entry count: %d\n", N);
        return NULL;
    }

    // Allocate memory for the array of NetworkEventLogEntries
    NetworkEventLogEntry* log_entries = (NetworkEventLogEntry*)malloc(N * sizeof(NetworkEventLogEntry));
    if (!log_entries) {
        fprintf(stderr, "Failed to allocate memory for %d log entries\n", N);
        return NULL;
    }

    // Initialize each entry in the array with a timestamp and empty message
    for (int i = 0; i < N; ++i) {
        log_entries[i].timestamp = time(NULL);
        log_entries[i].message = calloc(1, MAX_LOG_MESSAGE_LENGTH + 1);
    }

    return log_entries;
}

// Function to append a new log entry to the array of NetworkEventLogEntries
void append_log_entry(NetworkEventLogEntry* log_entries, int N, int event_type, int log_level, char* message) {
    // Check if the log entry is valid
    if (!message || strlen(message) > MAX_LOG_MESSAGE_LENGTH) {
        fprintf(stderr, "Invalid log message: %s\n", message);
        return;
    }

    // Ensure that the log entries array has enough space for a new entry
    if (N == 0 || N == log_entries->size) {
        int new_size = N + LOG_ENTRY_INCREMENT;
        NetworkEventLogEntry* new_log_entries = realloc(log_entries, new_size * sizeof(NetworkEventLogEntry));
        if (!new_log_entries) {
            fprintf(stderr, "Failed to allocate memory for %d log entries\n", new_size);
            return;
        }
        log_entries = new_log_entries;
    }

    // Update the timestamp and message of the new entry
    NetworkEventLogEntry* new_entry = &log_entries[N];
    new_entry->timestamp = time(NULL);
    strncpy(new_entry->message, message, MAX_LOG_MESSAGE_LENGTH);
    new_entry->event_type = event_type;
    new_entry->log_level = log_level;

    // Increment the size of the log entries array
    ++log_entries->size;
}

