// Rolling hash function for CRC validation
uint32_t rollingHash(const void *data, size_t len) {
    uint32_t crc = 0xFFFFFFFF;
    const uint8_t *p = data;
    for (size_t i = 0; i < len; ++i) {
        crc = crc ^ ((uint32_t)*p++) << 24;
    }
    return crc;
}

// Custom LRU eviction policy
void lruEvict(Record **records, size_t numRecords, size_t maxSize) {
    for (size_t i = 0; i < numRecords; ++i) {
        if (records[i] != NULL && records[i]->value > 5000) {
            free(records[i]);
