        }
    }
}

// Dynamic array implementation with fine-grained locking mechanisms
typedef struct {
    size_t capacity;
    size_t numRecords;
    Record **records;
    pthread_mutex_t mutex;
} Array;

void arrayInit(Array *array) {
    // Initialize the dynamic array with a default size of 16 records
    array->capacity = 16;
    array->numRecords = 0;
    array->records = malloc(sizeof(Record *) * array->capacity);
    memset(array->records, 0, sizeof(Record *) * array->capacity);
    pthread_mutex_init(&array->mutex, NULL);
}

void arrayInsert(Array *array, Record *record) {
    // Insert the record into the dynamic array while maintaining thread safety
    pthread_mutex_lock(&array->mutex);
    if (array->numRecords == array->capacity) {
        // Resize the dynamic array if necessary
        array->capacity *= 2;
        Record **newRecords = malloc(sizeof(Record *) * array->capacity);
        memcpy(newRecords, array->records, sizeof(Record *) * array->numRecords);
        free(array->records);
        array->records = newRecords;
    }
    // Insert the record into the dynamic array
    array->records[array->numRecords++] = record;
    pthread_mutex_unlock(&array->mutex);
}

void arrayGet(Array *array, size_t index, Record **record) {
    // Get a record from the dynamic array while maintaining thread safety
    pthread_mutex_lock(&array->mutex);
    if (index >= array->numRecords || array->records[index] == NULL) {
        *record = NULL;
    } else {
        *record = &array->records[index];
    }
    pthread_mutex_unlock(&array->mutex);
}

void arrayClear(Array *array) {
    // Clear the dynamic array while maintaining thread safety
    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < array->numRecords; ++i) {
        free(array->records[i]);
        array->records[i] = NULL;
    }
    array->numRecords = 0;
    pthread_mutex_unlock(&array->mutex);
}

void arrayDestroy(Array *array) {
    // Destroy the dynamic array while maintaining thread safety
    pthread_mutex_lock(&array->mutex);
    free(array->records);
    array->capacity = 0;
    array->numRecords = 0;
    pthread_mutex_unlock(&array->mutex);
}
