// Initialize the list with a given capacity
void nfapi_crc_indication_init(NFAPI_CRC_INDICATION_LIST_T *list, size_t capacity) {
  list->count = 0;
  list->list = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

// Add a new CRC information structure to the list
void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T *list, uint16_t rx_ue_information_tag, uint32_t rnti, uint8_t crc_indication_rel8_tag) {
  NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
  pdu->rx_ue_information_tag = rx_ue_information_tag;
  pdu->rnti = rnti;
  pdu->crc_indication_rel8_tag = crc_indication_rel8_tag;
  list->list[list->count++] = pdu;
}

// Remove a CRC information structure from the list by its RNTI value
void nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_LIST_T *list, uint32_t rnti) {
  for (size_t i = 0; i < list->count; i++) {
    if (list->list[i]->rnti == rnti) {
      free(list->list[i]);
      memmove(&list->list[i], &list->list[i + 1], (list->count - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
