int read_and_initialize(const char* filepath, const char* format) {
    // Open the file for reading
    FILE *file = fopen(filepath, "r");
    if (file == NULL) {
        printf("Error opening file: %s\n", strerror(errno));
        return -1;
    }

    // Determine the number of elements in the file
    int num_elements = 0;
    while (!feof(file)) {
        char line[256];
        fgets(line, sizeof(line), file);
        if (strlen(line) > 0) {
            ++num_elements;
        }
    }

    // Allocate memory for the arrays
    double* doubles = (double*) malloc(sizeof(double) * num_elements);
    char* chars = (char*) malloc(sizeof(char) * num_elements);
    struct element* elements = (struct element*) malloc(sizeof(struct element) * num_elements);
    if (doubles == NULL || chars == NULL || elements == NULL) {
        printf("Error allocating memory for arrays: %s\n", strerror(errno));
        return -1;
    }

    // Initialize the arrays with values from the file
    rewind(file);
    int i = 0;
    while (!feof(file)) {
        char line[256];
        fgets(line, sizeof(line), file);
        if (strlen(line) > 0) {
            // Parse the line and fill in the arrays
            double dval = strtod(line, NULL);
            char cval = line[0];
            elements[i].fval = dval;
            elements[i].ival = i;
            elements[i].cval = cval;
            ++i;
        }
    }

    // Close the file and free memory
    fclose(file);
    free(doubles);
    free(chars);
    free(elements);

    return 0;
}

int main() {
    read_and_initialize("data.txt", "csv");
    return 0;
}

Custom allocator:

#include <stdlib.h>
#include <stdio.h>

void* allocate(size_t size) {
    // Use the standard library's malloc to allocate memory
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Error allocating memory: %s\n", strerror(errno));
        return NULL;
    }

    // Initialize the allocated memory with a custom pattern
    memset(ptr, 0xAB, size);
    return ptr;
}

void deallocate(void* ptr) {
    if (ptr == NULL) {
        return;
    }

    free(ptr);
}

Thread-safe memory pool:

#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

struct memory_pool {
    void* ptrs[1024];
    int num_ptrs;
    pthread_mutex_t mutex;
};

struct memory_pool* create_memory_pool() {
    struct memory_pool* pool = malloc(sizeof(struct memory_pool));
    if (pool == NULL) {
        printf("Error creating memory pool: %s\n", strerror(errno));
        return NULL;
    }

    pool->num_ptrs = 0;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void* allocate_from_pool(struct memory_pool* pool) {
    if (pool == NULL) {
        printf("Error: pool is null\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->mutex);
    if (pool->num_ptrs < 1024) {
        void* ptr = malloc(size);
        if (ptr == NULL) {
            printf("Error allocating memory from pool: %s\n", strerror(errno));
            return NULL;
        }

        // Initialize the allocated memory with a custom pattern
        memset(ptr, 0xAB, size);
        pool->ptrs[pool->num_ptrs++] = ptr;
    } else {
        printf("Error: pool is full\n");
    }

    pthread_mutex_unlock(&pool->mutex);
    return pool->ptrs[pool->num_ptrs - 1];
}

void deallocate_from_pool(struct memory_pool* pool, void* ptr) {
    if (pool == NULL || ptr == NULL) {
        printf("Error: pool or pointer is null\n");
        return;
    }

    pthread_mutex_lock(&pool->mutex);
    for (int i = 0; i < pool->num_ptrs; ++i) {
        if (ptr == pool->ptrs[i]) {
            free(ptr);
            pool->ptrs[i] = NULL;
            --pool->num_ptrs;
            break;
        }
    }

    pthread_mutex_unlock(&pool->mutex);
}

void destroy_memory_pool(struct memory_pool* pool) {
    if (pool == NULL) {
        printf("Error: pool is null\n");
        return;
    }

    for (int i = 0; i < pool->num_ptrs; ++i) {
        free(pool->ptrs[i]);
    }

    pthread_mutex_destroy(&pool->mutex);
    free(pool);
}']

