#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <math.h>
#include "LTE_PHY_RX_FRAME.h"
#include "LTE_PHY_RX_SYMBOL.h"

// Structure for storing a dynamic array of LTE PHY RX frames
typedef struct {
    int size; // Size of the array
    int capacity; // Capacity of the array
    LTE_PHY_RX_FRAME** frames; // Array of LTE PHY RX frames
} LTE_PHY_RX_FRAME_ARRAY;

// Structure for storing a dynamic array of LTE PHY RX symbols
typedef struct {
    int size; // Size of the array
    int capacity; // Capacity of the array
    LTE_PHY_RX_SYMBOL** symbols; // Array of LTE PHY RX symbols
} LTE_PHY_RX_SYMBOL_ARRAY;

// Structure for storing a single LTE PHY RX frame
typedef struct {
    LTE_PHY_RX_FRAME_ARRAY symbols; // Array of LTE PHY RX symbols
} LTE_PHY_RX_FRAME;

// Structure for storing a single LTE PHY RX symbol
typedef struct {
    int modulation; // Modulation type
    float phaseRotation; // Phase rotation
    float noiseVarianceEstimate; // Noise variance estimate
} LTE_PHY_RX_SYMBOL;

// Function for initializing a dynamic array of LTE PHY RX frames
LTE_PHY_RX_FRAME_ARRAY initLTE_PHY_RX_FRAME_ARRAY(int capacity) {
    LTE_PHY_RX_FRAME_ARRAY arr;
    arr.size = 0;
    arr.capacity = capacity;
    arr.frames = (LTE_PHY_RX_FRAME**)malloc(sizeof(LTE_PHY_RX_FRAME*) * capacity);
    for (int i = 0; i < capacity; i++) {
        arr.frames[i] = initLTE_PHY_RX_FRAME();
    }
    return arr;
}

// Function for initializing a single LTE PHY RX frame
LTE_PHY_RX_FRAME initLTE_PHY_RX_FRAME() {
    LTE_PHY_RX_FRAME frame;
    frame.symbols = initLTE_PHY_RX_SYMBOL_ARRAY(0);
    return frame;
}

// Function for initializing a dynamic array of LTE PHY RX symbols
LTE_PHY_RX_SYMBOL_ARRAY initLTE_PHY_RX_SYMBOL_ARRAY(int capacity) {
    LTE_PHY_RX_SYMBOL_ARRAY arr;
    arr.size = 0;
    arr.capacity = capacity;
    arr.symbols = (LTE_PHY_RX_SYMBOL**)malloc(sizeof(LTE_PHY_RX_SYMBOL*) * capacity);
    for (int i = 0; i < capacity; i++) {
        arr.symbols[i] = initLTE_PHY_RX_SYMBOL();
    }
    return arr;
}

// Function for initializing a single LTE PHY RX symbol
LTE_PHY_RX_SYMBOL initLTE_PHY_RX_SYMBOL() {
    LTE_PHY_RX_SYMBOL sym;
    sym.modulation = 0; // Set modulation type to 0 (unknown)
    sym.phaseRotation = 0; // Set phase rotation to 0 (no rotation)
    sym.noiseVarianceEstimate = 0; // Set noise variance estimate to 0 (no estimate)
    return sym;
}

// Function for adding a new LTE PHY RX frame to the array
void addLTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_ARRAY* arr, LTE_PHY_RX_FRAME frame) {
    if (arr->size >= arr->capacity) {
        // Array is full, increase capacity by 50%
        int newCapacity = arr->capacity * 1.5;
        arr->frames = realloc(arr->frames, sizeof(LTE_PHY_RX_FRAME*) * newCapacity);
        for (int i = arr->size; i < newCapacity; i++) {
            arr->frames[i] = initLTE_PHY_RX_FRAME();
        }
        arr->capacity = newCapacity;
    }
    arr->frames[arr->size++] = frame;
}

// Function for adding a new LTE PHY RX symbol to the array
void addLTE_PHY_RX_SYMBOL(LTE_PHY_RX_FRAME* frame, LTE_PHY_RX_SYMBOL sym) {
    if (frame->symbols.size >= frame->symbols.capacity) {
        // Array is full, increase capacity by 50%
        int newCapacity = frame->symbols.capacity * 1.5;
        frame->symbols.symbols = realloc(frame->symbols.symbols, sizeof(LTE_PHY_RX_SYMBOL*) * newCapacity);
        for (int i = frame->symbols.size; i < newCapacity; i++) {
            frame->symbols.symbols[i] = initLTE_PHY_RX_SYMBOL();
        }
        frame->symbols.capacity = newCapacity;
    }
    frame->symbols.symbols[frame->symbols.size++] = sym;
}

// Function for setting the modulation type of a LTE PHY RX symbol
void setLTE_PHY_RX_MODULATION(LTE_PHY_RX_SYMBOL* sym, int modulation) {
    if (modulation >= 0 && modulation <= 63) {
        sym->modulation = modulation;
    } else {
        printf("Invalid modulation type: %d\n", modulation);
    }
}

// Function for setting the phase rotation of a LTE PHY RX symbol
void setLTE_PHY_RX_PHASE_ROTATION(LTE_PHY_RX_SYMBOL* sym, float phaseRotation) {
    if (phaseRotation >= 0 && phaseRotation <= 360) {
        sym->phaseRotation = phaseRotation;
    } else {
        printf("Invalid phase rotation: %f\n", phaseRotation);
    }
}

// Function for setting the noise variance estimate of a LTE PHY RX symbol
void setLTE_PHY_RX_NOISE_VARIANCE(LTE_PHY_RX_SYMBOL* sym, float noiseVarianceEstimate) {
    if (noiseVarianceEstimate >= 0 && noiseVarianceEstimate <= 1) {
        sym->noiseVarianceEstimate = noiseVarianceEstimate;
    } else {
        printf("Invalid noise variance estimate: %f\n", noiseVarianceEstimate);
    }
}
