void init_structures(int N, int min_key, int max_key, int min_value, int max_value, long max_memory, int* num_offsets, int* num_keys, int* num_records, long* total_memory_used) {
    // Initialize the random number generator with the current time
    srand(time(NULL));

    // Calculate the maximum number of records and keys that can fit in the allowed memory
    int max_num_records = (max_memory / sizeof(int)) - 1;
    int max_num_keys = (max_num_records * sizeof(int)) / sizeof(long);

    // Allocate memory for the offset array and initialize it with sequential numbers starting from 0 up to N
    long* offsets = malloc(N * sizeof(long));
    if (!offsets) {
        printf("Error: failed to allocate memory for offset array\n");
        return;
    }
    for (int i = 0; i < N; ++i) {
        offsets[i] = i;
    }

    // Allocate memory for the key array and initialize it with random numbers within the specified range
    int* keys = malloc(max_num_keys * sizeof(int));
    if (!keys) {
        printf("Error: failed to allocate memory for key array\n");
        free(offsets);
        return;
    }
    for (int i = 0; i < max_num_keys; ++i) {
        keys[i] = rand() % (max_key - min_key + 1) + min_key;
    }

    // Allocate memory for the record array and initialize it with random values within the specified range
    int* records = malloc(max_num_records * sizeof(int));
    if (!records) {
        printf("Error: failed to allocate memory for record array\n");
        free(keys);
        free(offsets);
        return;
    }
    for (int i = 0; i < max_num_records; ++i) {
        records[i] = rand() % (max_value - min_value + 1) + min_value;
    }

    // Validate that all keys are unique before proceeding with the initialization of records
    int num_unique_keys = 0;
    for (int i = 0; i < max_num_keys; ++i) {
        bool is_duplicate = false;
        for (int j = 0; j < i; ++j) {
            if (keys[i] == keys[j]) {
                is_duplicate = true;
                break;
            }
        }
        if (!is_duplicate) {
            num_unique_keys++;
        } else {
            printf("Error: found duplicate key in generated key array\n");
            free(records);
            free(keys);
            free(offsets);
            return;
        }
    }

    // If there are any duplicates, free the allocated memory and return a null pointer
    if (num_unique_keys != max_num_keys) {
        printf("Error: found duplicate keys in generated key array\n");
        free(records);
        free(keys);
        free(offsets);
        return;
    }

    // Calculate the total memory used and assign it to the output parameter
    long total_memory = N * sizeof(long) + max_num_keys * sizeof(int) + max_num_records * sizeof(int);
    if (total_memory > max_memory) {
        printf("Error: allocated memory exceeds maximum allowed limit\n");
        free(records);
        free(keys);
        free(offsets);
        return;
    }
    *total_memory_used = total_memory;

    // Assign the output parameters and return a pointer to the allocated memory
    *num_offsets = N;
    *num_keys = max_num_keys;
    *num_records = max_num_records;
    return offsets;
}']

