// Define thread-safe data structures and functions for managing the dynamic array
typedef struct LTE_PHY_RX_FRAME_ARRAY {
    pthread_mutex_t mutex;
    uint16_t size;
    uint16_t capacity;
    LTE_PHY_RX_FRAME *frames;
} LTE_PHY_RX_FRAME_ARRAY;

void init_LTE_PHY_RX_FRAME_ARRAY(LTE_PHY_RX_FRAME_ARRAY *array) {
    array->size = 0;
    array->capacity = MAX_FRAME_SIZE;
    array->frames = malloc(sizeof(LTE_PHY_RX_FRAME) * MAX_FRAME_SIZE);
    pthread_mutex_init(&array->mutex, NULL);
}

void destroy_LTE_PHY_RX_FRAME_ARRAY(LTE_PHY_RX_FRAME_ARRAY *array) {
    pthread_mutex_destroy(&array->mutex);
    free(array->frames);
}

void resize_LTE_PHY_RX_FRAME_ARRAY(LTE_PHY_RX_FRAME_ARRAY *array, uint16_t new_size) {
    pthread_mutex_lock(&array->mutex);
    array->capacity = new_size;
    if (new_size > array->size) {
        LTE_PHY_RX_FRAME *temp = realloc(array->frames, sizeof(LTE_PHY_RX_FRAME) * new_size);
        if (!temp) {
            pthread_mutex_unlock(&array->mutex);
            return OUT_OF_MEMORY;
        }
        array->frames = temp;
    }
    pthread_mutex_unlock(&array->mutex);
}

void add_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_ARRAY *array, LTE_PHY_RX_FRAME frame) {
    pthread_mutex_lock(&array->mutex);
    if (array->size == array->capacity) {
        resize_LTE_PHY_RX_FRAME_ARRAY(array, 2 * array->capacity);
    }
    array->frames[array->size] = frame;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

