    pthread_mutex_lock(&array->mutex);
    stats->num_frames++;
    stats->num_symbols += frame.num_symbols;
    for (uint16_t i = 0; i < frame.num_symbols; i++) {
        LTE_PHY_RX_SYMBOL symbol = frame.symbols[i];
