Here is an example implementation of the C function that manages memory allocation and initialization for three arrays: one for 'long' offset values, one for 'int' keys, and one for 'record' structures containing an integer and an associated long offset. The function also maintains a mapping from keys to offsets using a hash table data structure for efficient lookups, ensuring no memory leaks.
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <errno.h>

// Define a record structure containing an integer and an associated long offset
typedef struct {
    int key;
    long offset;
} Record;

// Define a hash table data structure for storing the mapping from keys to offsets
typedef struct {
    int *keys; // array of integers
    long *offsets; // array of long values
    size_t capacity; // maximum number of elements in the hash table
    size_t count; // current number of elements in the hash table
} HashTable;

// Define a logging mechanism to track insertions, deletions, and successful lookups
typedef struct {
    int *insertedKeys; // array of keys that have been inserted
    long *insertedOffsets; // array of offsets that have been inserted
    size_t numInserted; // number of elements in the logging arrays
    int *deletedKeys; // array of keys that have been deleted
    long *deletedOffsets; // array of offsets that have been deleted
    size_t numDeleted; // number of elements in the logging arrays
} LoggingMechanism;

// Define a function to generate random integers within a given range
int generateRandomInteger(int min, int max) {
    return min + rand() % (max - min);
}

// Define a function to generate random long values within a given range
long generateRandomLong(long min, long max) {
    return min + rand() % (max - min);
}

// Define a custom hash function for the keys in the hash table
int hashFunction(int key) {
    // A simple hash function that maps each key to an index in the hash table
    return key % HASH_TABLE_SIZE;
}

// Define a function to initialize the arrays and hash table
void initArraysAndHashTable(int numRecords, size_t maxAllowedDepth, bool followSymbolicLinks) {
    // Allocate memory for the arrays and initialize them with random data within given ranges
    long *offsets = (long *) malloc(numRecords * sizeof(long));
    int *keys = (int *) malloc(numRecords * sizeof(int));
    Record *records = (Record *) malloc(numRecords * sizeof(Record));

    for (size_t i = 0; i < numRecords; i++) {
        records[i].key = generateRandomInteger(1, maxAllowedDepth);
        records[i].offset = generateRandomLong(1, maxAllowedDepth);
    }

    // Allocate memory for the hash table and initialize it with a capacity equal to the number of records
    HashTable *hashTable = (HashTable *) malloc(sizeof(HashTable));
    hashTable->keys = (int *) malloc(numRecords * sizeof(int));
    hashTable->offsets = (long *) malloc(numRecords * sizeof(long));
    hashTable->capacity = numRecords;
    hashTable->count = 0;

    // Initialize the logging mechanism to track insertions, deletions, and successful lookups
    LoggingMechanism *logging = (LoggingMechanism *) malloc(sizeof(LoggingMechanism));
    logging->insertedKeys = (int *) malloc(numRecords * sizeof(int));
    logging->insertedOffsets = (long *) malloc(numRecords * sizeof(long));
    logging->deletedKeys = (int *) malloc(numRecords * sizeof(int));
    logging->deletedOffsets = (long *) malloc(numRecords * sizeof(long));
    logging->numInserted = 0;
    logging->numDeleted = 0;

    // Initialize the hash table with the records and start tracking insertions, deletions, and successful lookups
    for (size_t i = 0; i < numRecords; i++) {
        int key = records[i].key;
        long offset = records[i].offset;
        int index = hashFunction(key);

        // Insert the record into the hash table
        hashTable->keys[index] = key;
        hashTable->offsets[index] = offset;
        hashTable->count++;

        // Log the insertion
        logging->insertedKeys[logging->numInserted] = key;
        logging->insertedOffsets[logging->numInserted] = offset;
        logging->numInserted++;
    }
}

// Define a function to clean up the arrays and hash table
void cleanupArraysAndHashTable() {
    // Free the memory allocated for the arrays and hash table
    free(offsets);
    free(keys);
    free(records);
    free(hashTable->keys);
    free(hashTable->offsets);
    free(hashTable);
}

// Define a function to perform insertions, deletions, and lookups in the hash table
int *performOperations(char *filePath, int maxAllowedDepth, bool followSymbolicLinks) {
    // Check if the file path is within the limits of directory traversal and symbolic links are not followed
    size_t depth = strlen(filePath);
    if (depth > maxAllowedDepth && !followSymbolicLinks) {
        return NULL;
    }

    // Check if there are any memory allocation failures
    errno = 0;
    int *result = malloc(HASH_TABLE_SIZE * sizeof(int));
    if (result == NULL) {
        printf("Memory allocation failure\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the arrays and hash table with random data within given ranges
    initArraysAndHashTable(HASH_TABLE_SIZE, maxAllowedDepth, followSymbolicLinks);

    // Perform insertions, deletions, and lookups in the hash table
    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        int key = generateRandomInteger(1, maxAllowedDepth);
        long offset = generateRandomLong(1, maxAllowedDepth);

        // Insert the record into the hash table
        if (hashTable->count < hashTable->capacity) {
            int index = hashFunction(key);
            hashTable->keys[index] = key;
            hashTable->offsets[index] = offset;
            hashTable->count++;
        } else {
            // If the hash table is full, delete a random record and insert the new record
            int indexToDelete = generateRandomInteger(0, HASH_TABLE_SIZE);
            free(hashTable->keys[indexToDelete]);
            free(hashTable->offsets[indexToDelete]);
            hashTable->count--;

            hashTable->keys[index] = key;
            hashTable->offsets[index] = offset;
            hashTable->count++;
        }
    }

    // Log the insertions, deletions, and successful lookups
    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable->keys[i] != NULL) {
            logging->insertedKeys[logging->numInserted] = hashTable->keys[i];
            logging->insertedOffsets[logging->numInserted] = hashTable->offsets[i];
            logging->numInserted++;
        } else {
            break;
        }
    }

    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable->keys[i] == NULL) {
            break;
        }

        int indexToDelete = generateRandomInteger(0, HASH_TABLE_SIZE);
        free(hashTable->keys[indexToDelete]);
        free(hashTable->offsets[indexToDelete]);
        hashTable->count--;
    }

    for (size_t i = 0; i < HASH_TABLE_SIZE; i++) {
        if (hashTable->keys[i] != NULL) {
            logging->deletedKeys[logging->numDeleted] = hashTable->keys[i];
            logging->deletedOffsets[logging->numDeleted] = hashTable->offsets[i];
            logging->numDeleted++;
        } else {
            break;
        }
    }

    // Clean up the arrays and hash table
    cleanupArraysAndHashTable();

    return result;
}

int main() {
    int maxAllowedDepth = 1024;
    bool followSymbolicLinks = false;

    // Perform insertions, deletions, and lookups in the hash table
    char *filePath = "/path/to/file";
    int *result = performOperations(filePath, maxAllowedDepth, followSymbolicLinks);

    return 0;
}
