// A function to remove outdated MAC PDUs for a given UE ID based on a timeout threshold
void cleanup_mac_pdus(uint32_t ue_id, uint64_t timeout) {
    // Check if the UE exists in the list
    bool found = false;
    SLIST_FOREACH(ue, &ue_list, entries) {
        if (ue->id == ue_id) {
            found = true;
            break;
        }
