    // If the UE does not exist, return without doing anything
    if (!found) {
        return;
    }

    // Get the current time in seconds since epoch
    uint64_t now = time(NULL);

    // Remove MAC PDUs that are older than the timeout threshold
    struct mac_pdu* pdu = NULL;
    SLIST_FOREACH_SAFE(pdu, &ue->pdu_list, entries) {
        if (now - pdu->timestamp > timeout) {
            SLIST_REMOVE(&ue->pdu_list, pdu, mac_pdu, entries);
            free(pdu);
        }
    }
}
