// Structure to represent TrafficFlowConfig
typedef struct {
    uint32_t flowID; // Unique identifier for the traffic flow
    uint8_t packetFilter[256]; // Packet filter rules for this flow
    uint32_t bandwidthPart; // Bandwidth partition for this flow
} TrafficFlowConfig;

// Structure to represent a dynamic array of TrafficFlowConfig structures
typedef struct {
    TrafficFlowConfig* configs; // Array of TrafficFlowConfig structures
    size_t numConfigs; // Number of configurations in the array
} TrafficFlowArray;

// Function to initialize and populate a dynamic array of TrafficFlowConfig structures
TrafficFlowArray initAndPopulateTrafficFlowArray(size_t maxNumConfigs) {
    TrafficFlowArray flowArray;
    flowArray.configs = (TrafficFlowConfig*)malloc(maxNumConfigs * sizeof(TrafficFlowConfig));
    flowArray.numConfigs = 0;
    return flowArray;
}

// Function to add a new TrafficFlowConfig structure to the dynamic array
void addNewTrafficFlowConfig(TrafficFlowArray* flowArray, uint32_t flowID, uint8_t packetFilter[256], uint32_t bandwidthPart) {
    // Check if the maximum number of configurations has been reached
    if (flowArray->numConfigs >= maxNumConfigs) {
        fprintf(stderr, "Maximum number of configurations reached\n");
        return;
    }

    // Add the new configuration to the array
    flowArray->configs[flowArray->numConfigs].flowID = flowID;
    memcpy(flowArray->configs[flowArray->numConfigs].packetFilter, packetFilter, 256);
    flowArray->configs[flowArray->numConfigs].bandwidthPart = bandwidthPart;
    flowArray->numConfigs++;
}

// Function to update a TrafficFlowConfig structure in the dynamic array
void updateTrafficFlowConfig(TrafficFlowArray* flowArray, uint32_t flowID, uint8_t packetFilter[256], uint32_t bandwidthPart) {
    // Find the configuration with the specified flow ID
    int configIndex = findTrafficFlowConfigIndex(flowArray, flowID);
    if (configIndex == -1) {
        fprintf(stderr, "Configuration not found\n");
        return;
    }

    // Update the packet filter and bandwidth partition for the configuration
    memcpy(flowArray->configs[configIndex].packetFilter, packetFilter, 256);
    flowArray->configs[configIndex].bandwidthPart = bandwidthPart;
}

// Function to find the index of a TrafficFlowConfig structure in the dynamic array
int findTrafficFlowConfigIndex(TrafficFlowArray* flowArray, uint32_t flowID) {
    for (int i = 0; i < flowArray->numConfigs; i++) {
        if (flowArray->configs[i].flowID == flowID) {
            return i;
        }
    }
    return -1;
}

// Function to check if two TrafficFlowConfig structures overlap in their bandwidth partitions
bool doTrafficFlowConfigsOverlap(TrafficFlowConfig* config1, TrafficFlowConfig* config2) {
    // Check if the bandwidth partitions of the two configurations overlap
    if (config1->bandwidthPart > config2->bandwidthPart &&
        config1->bandwidthPart < (config2->bandwidthPart + config2->bandwidthPart)) {
            return true;
        } else if (config2->bandwidthPart > config1->bandwidthPart &&
                   config2->bandwidthPart < (config1->bandwidthPart + config1->bandwidthPart)) {
                       return true;
                   }
    // If the bandwidth partitions do not overlap, check if the packet filters are consistent
    else if (memcmp(config1->packetFilter, config2->packetFilter, 256) == 0) {
        return false;
    } else {
        fprintf(stderr, "Inconsistent packet filter rules\n");
        return true;
    }
}
