#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <uuid/uuid.h>

struct Configuration {
    char* key;
    char* default_value;
    struct Configuration* nested_configurations;
};

void init_configuration(struct Configuration** configuration) {
    *configuration = malloc(sizeof(struct Configuration));

    // Generate a unique UUID for the key
    uuid_t uuid;
    uuid_generate(uuid);
    char* uuid_string = malloc(37); // 36 characters + null terminator
    uuid_unparse(uuid, uuid_string);

    (*configuration)->key = uuid_string;
    (*configuration)->default_value = "Not Set";
    (*configuration)->nested_configurations = NULL;
}

void set_configuration(struct Configuration** configuration, char* key, char* value) {
    if ((*configuration)->key == NULL || strcmp((*configuration)->key, key) != 0) {
        // Key not found or doesn't match the expected key. Create a new configuration.
        init_configuration(configuration);
    }

    (*configuration)->default_value = value;
}

void add_nested_configuration(struct Configuration** configuration, struct Configuration* nested) {
    if ((*configuration)->nested_configurations == NULL) {
        // Initialize the list of nested configurations.
        (*configuration)->nested_configurations = malloc(sizeof(struct Configuration*) * 1);
    } else {
        // Reallocate memory to accommodate a new nested configuration.
        (*configuration)->nested_configurations = realloc((*configuration)->nested_configurations, sizeof(struct Configuration*) * (1 + num_nested));
    }

    (*configuration)->nested_configurations[num_nested] = nested;
}

void retrieve_configuration(struct Configuration** configuration, char* key) {
    if ((*configuration)->key == NULL || strcmp((*configuration)->key, key) != 0) {
        // Key not found or doesn't match the expected key. Return "Not Set".
        return (*configuration)->default_value;
    } else {
        return (*configuration)->default_value;
    }
}

int main() {
    struct Configuration* configuration = NULL;
    init_configuration(&configuration);

    set_configuration(&configuration, "key1", "value1");
    add_nested_configuration(&configuration, create_configuration("nested_key1", "nested_value1"));
    set_configuration(&configuration, "key2", "value2");

    retrieve_configuration(&configuration, "key1"); // Returns "value1"
    retrieve_configuration(&configuration, "nested_key1"); // Returns "nested_value1"

    return 0;
}
```
