// NGAP_Message_T data structure for storing message metadata
typedef struct {
    uint64_t timestamp; // time at which the message was received
    uint8_t msg_type;   // type of message (e.g., NG_Setup, UE_Notification)
    uint16_t payload_len; // length of message payload
    uint8_t qos_class;  // optional QoS class identifier
} NGAP_Message_T;

// IP_EE_NG structure for storing Endpoint_ID and associated messages
typedef struct {
    char *endpoint_id; // unique identifier for the endpoint
    size_t msg_count;  // number of messages stored in the list
    NGAP_Message_T *msgs[]; // variable-length list of NGAP_Message_T entries
} IP_EE_NG;

// function for adding a new message to an IP_EE_NG structure
int add_msg(IP_EE_NG *ip_ee_ng, const char *endpoint_id, const uint8_t msg_type, const uint16_t payload_len, const uint8_t qos_class) {
    // check if the IP_EE_NG structure already exists for the endpoint
    bool exists = false;
    for (size_t i = 0; i < ip_ee_ng->msg_count; i++) {
        if (strcmp(ip_ee_ng->msgs[i].endpoint_id, endpoint_id) == 0) {
            exists = true;
            break;
        }
    }

    // create a new IP_EE_NG structure if it doesn't exist already
    if (!exists) {
        ip_ee_ng->msgs[ip_ee_ng->msg_count] = malloc(sizeof(NGAP_Message_T));
        memset(&ip_ee_ng->msgs[ip_ee_ng->msg_count], 0, sizeof(NGAP_Message_T));
        ip_ee_ng->endpoint_id = endpoint_id;
        ip_ee_ng->msg_count++;
    }

    // add the new message to the list of messages for the endpoint
    NGAP_Message_T *new_msg = &ip_ee_ng->msgs[ip_ee_ng->msg_count - 1];
    new_msg->timestamp = time(NULL);
    new_msg->msg_type = msg_type;
    new_msg->payload_len = payload_len;
    new_msg->qos_class = qos_class;

    return 0;
}

// function for updating a message in an IP_EE_NG structure
int update_msg(IP_EE_NG *ip_ee_ng, const char *endpoint_id, const uint8_t msg_type, const uint16_t payload_len, const uint8_t qos_class) {
    // find the message in the list of messages for the endpoint
    bool found = false;
    size_t i = 0;
    while (i < ip_ee_ng->msg_count && !found) {
        if (strcmp(ip_ee_ng->msgs[i].endpoint_id, endpoint_id) == 0) {
            found = true;
            break;
        }
        i++;
    }

    // update the message with the new metadata
    if (found) {
        NGAP_Message_T *updated_msg = &ip_ee_ng->msgs[i];
        updated_msg->timestamp = time(NULL);
        updated_msg->msg_type = msg_type;
        updated_msg->payload_len = payload_len;
        updated_msg->qos_class = qos_class;
    }

    return 0;
}

// function for retrieving a message from an IP_EE_NG structure
int get_msg(IP_EE_NG *ip_ee_ng, const char *endpoint_id, NGAP_Message_T **msg) {
    // find the message in the list of messages for the endpoint
    bool found = false;
    size_t i = 0;
    while (i < ip_ee_ng->msg_count && !found) {
        if (strcmp(ip_ee_ng->msgs[i].endpoint_id, endpoint_id) == 0) {
            found = true;
            break;
        }
        i++;
    }

    // retrieve the message from the list of messages for the endpoint
    if (found) {
        *msg = &ip_ee_ng->msgs[i];
    }

    return 0;
}

// function for cleaning up outdated messages in an IP_EE_NG structure
int cleanup(IP_EE_NG *ip_ee_ng, const uint64_t timeout) {
    // find the first message that has not been updated within the specified timeout
    size_t i = 0;
    while (i < ip_ee_ng->msg_count && ip_ee_ng->msgs[i].timestamp >= timeout) {
        i++;
    }

    // remove any messages that have not been updated within the specified timeout
    if (i > 0) {
        size_t removed_count = ip_ee_ng->msg_count - i;
        for (size_t j = i; j < ip_ee_ng->msg_count; j++) {
            free(ip_ee_ng->msgs[j].endpoint_id);
            free(ip_ee_ng->msgs[j]);
        }
        ip_ee_ng->msg_count -= removed_count;
    }

    return 0;
}

// function for managing an IP network traffic system
int manage_traffic(IP_EE_NG *ip_ee_ng, const char *endpoint_id, const uint8_t msg_type, const uint16_t payload_len, const uint8_t qos_class) {
    // add or update the message in the IP_EE_NG structure
    int ret = add_msg(ip_ee_ng, endpoint_id, msg_type, payload_len, qos_class);
    if (ret != 0) {
        return ret;
    }

    // clean up outdated messages in the IP_EE_NG structure
    cleanup(ip_ee_ng, time(NULL) - timeout);

    return 0;
}
```

This code defines a struct `IP_EE_NG` that represents an IP network traffic system. It has three functions: `add_msg`, `update_msg`, and `get_msg`, which add or update a message in the system, update a message in the system, and retrieve a message from the system, respectively. The `cleanup` function is used to clean up outdated messages in the system.

The `manage_traffic` function is the main function that manages the IP network traffic system. It takes five arguments: `ip_ee_ng`, which is an instance of the `IP_EE_NG` struct representing the IP network traffic system; `endpoint_id`, which is a string representing the endpoint ID for the message being added or updated; `msg_type`, which is a byte representing the type of message (e.g., 0 for a ping, 1 for a pong); `payload_len`, which is a short integer representing the length of the message payload; and `qos_class`, which is an integer representing the Quality of Service (QoS) class for the message.

This code uses a hash table to store the messages in the system, with the endpoint ID as the key and the struct `IP_EE_NG` as the value. The hash table is implemented using an array of linked lists, where each element in the array corresponds to a bucket in the hash table, and each linked list in the array represents a chain of collisions for that bucket.

The `add_msg` function adds a new message to the system by creating a new struct `IP_EE_NG` and adding it to the hash table using the endpoint ID as the key. If there is already an entry in the hash table for this endpoint, then the existing entry is updated with the new message information.

The `update_msg` function updates an existing message in the system by retrieving the message from the hash table using the endpoint ID as the key, and updating its metadata with the new message information. If there is no entry in the hash table for this endpoint, then the function returns an error code.

The `get_msg` function retrieves a message from the system by searching the hash table using the endpoint ID as the key. It returns the message if it is found, or it returns an error code if the message is not found.

