#include "nfapi_crc_indication_pdu.h"

struct nfapi_crc_indication_pdu_s {
  uint8_t rx_ue_information_tag;
  uint16_t rnti;
  uint8_t crc_indication_rel8_tag;
  bool crcflag;
};

struct nfapi_crc_indication_pdu_list {
  struct nfapi_crc_indication_pdu_s *entries[N];
  int num_entries;
};

void create_and_populate_nfapi_crc_indication_pdu_list(struct nfapi_crc_indication_pdu_list *list, int N) {
  list->num_entries = 0;
  for (int i = 0; i < N; i++) {
    struct nfapi_crc_indication_pdu_s *entry = malloc(sizeof(struct nfapi_crc_indication_pdu_s));
    if (!entry) {
      // handle memory allocation error
      continue;
    }
    entry->rx_ue_information_tag = rand() % 256;
    entry->rnti = rand() % 65536 + 1;
    entry->crc_indication_rel8_tag = rand() % 256;
    entry->crcflag = (rand() % 2) == 0;
    list->entries[list->num_entries++] = entry;
  }
}

int validate_rnti(uint16_t rnti, int valid_range_start, int valid_range_end) {
  return rnti >= valid_range_start && rnti <= valid_range_end;
}

void create_and_populate_nfapi_crc_indication_pdu_list_with_concurrency(struct nfapi_crc_indication_pdu_list *list, int N) {
  pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
  for (int i = 0; i < N; i++) {
    struct nfapi_crc_indication_pdu_s *entry = malloc(sizeof(struct nfapi_crc_indication_pdu_s));
    if (!entry) {
      // handle memory allocation error
      continue;
    }
    entry->rx_ue_information_tag = rand() % 256;
    int rnti = rand() % 65536 + 1;
    while (!validate_rnti(rnti, 0, 4096)) {
      rnti = rand() % 65536 + 1;
    }
    entry->rnti = rnti;
    entry->crc_indication_rel8_tag = rand() % 256;
    entry->crcflag = (rand() % 2) == 0;
    pthread_mutex_lock(&lock);
    list->entries[list->num_entries++] = entry;
    pthread_mutex_unlock(&lock);
  }
}

void destroy_nfapi_crc_indication_pdu_list(struct nfapi_crc_indication_pdu_list *list) {
  for (int i = 0; i < list->num_entries; i++) {
    free(list->entries[i]);
  }
}
```
