['#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <errno.h>
#include <assert.h>

#define CONFIG_INITIAL_SIZE 1024
#define CONFIG_MAX_SIZE 16384
#define CONFIG_GROWTH_FACTOR 2

typedef struct config_entry {
    void *key;
    void *value;
} config_entry_t;

typedef struct config_storage {
    size_t num_entries;
    size_t capacity;
    config_entry_t *entries;
} config_storage_t;

typedef enum config_status {
    CONFIG_SUCCESS,
    CONFIG_FAILURE,
    CONFIG_DUPLICATE_KEY,
    CONFIG_INVALID_PARAM,
    CONFIG_MEMORY_ALLOCATION_FAILED,
} config_status_t;

config_status_t config_init(config_storage_t *config) {
    // Allocate memory for the configuration storage.
    config->capacity = CONFIG_INITIAL_SIZE;
    config->num_entries = 0;
    config->entries = (config_entry_t *) malloc(sizeof(config_entry_t) * CONFIG_INITIAL_SIZE);
    if (config->entries == NULL) {
        return CONFIG_MEMORY_ALLOCATION_FAILED;
    }
    return CONFIG_SUCCESS;
}

void config_free(config_storage_t *config) {
    // Free memory for the configuration storage.
    free(config->entries);
    config->capacity = 0;
    config->num_entries = 0;
    config->entries = NULL;
}

config_status_t config_insert(config_storage_t *config, void *key, void *value) {
    // Check if the key already exists in the configuration.
    for (size_t i = 0; i < config->num_entries; ++i) {
        if (config->entries[i].key == key) {
            return CONFIG_DUPLICATE_KEY;
        }
    }

    // Check if the configuration needs to be resized.
    if (config->num_entries == config->capacity) {
        size_t new_size = config->capacity * CONFIG_GROWTH_FACTOR;
        if (new_size > CONFIG_MAX_SIZE) {
            return CONFIG_INVALID_PARAM;
        }
        config_entry_t *new_entries = (config_entry_t *) realloc(config->entries, sizeof(config_entry_t) * new_size);
        if (new_entries == NULL) {
            return CONFIG_MEMORY_ALLOCATION_FAILED;
        }
        config->capacity = new_size;
        config->entries = new_entries;
    }

    // Insert the key-value pair into the configuration.
    config->entries[config->num_entries].key = key;
    config->entries[config->num_entries].value = value;
    ++config->num_entries;

    return CONFIG_SUCCESS;
}

void *config_get(const config_storage_t *config, void *key) {
    // Search for the key in the configuration.
    for (size_t i = 0; i < config->num_entries; ++i) {
        if (config->entries[i].key == key) {
            return config->entries[i].value;
        }
    }
    return NULL;
}

void *config_remove(config_storage_t *config, void *key) {
    // Search for the key in the configuration.
    for (size_t i = 0; i < config->num_entries; ++i) {
        if (config->entries[i].key == key) {
            void *value = config->entries[i].value;
            --config->num_entries;
            memmove(&config->entries[i], &config->entries[i + 1], sizeof(config_entry_t) * (config->num_entries - i));
            return value;
        }
    }
    return NULL;
}

int config_size(const config_storage_t *config) {
    // Return the number of key-value pairs in the configuration.
    return config->num_entries;
}

void config_clear(config_storage_t *config) {
    // Clear all key-value pairs from the configuration.
    config->num_entries = 0;
}

int main() {
    // Test the configuration initialization and cleanup.
    config_storage_t config;
    config_init(&config);
    assert(config_size(&config) == 0);
    config_free(&config);

    // Test the configuration insertion and retrieval.
    config_status_t status = config_init(&config);
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value1");
    assert(status == CONFIG_SUCCESS);
    assert(strcmp((char *) config_get(&config, "key1"), "value1") == 0);
    status = config_insert(&config, "key2", "value2");
    assert(status == CONFIG_SUCCESS);
    assert(strcmp((char *) config_get(&config, "key2"), "value2") == 0);
    assert(config_size(&config) == 2);
    config_clear(&config);
    assert(config_size(&config) == 0);
    config_free(&config);

    // Test the configuration duplicate key handling.
    status = config_init(&config);
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value1");
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value2");
    assert(status == CONFIG_DUPLICATE_KEY);
    config_free(&config);

    // Test the configuration key removal.
    status = config_init(&config);
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value1");
    assert(status == CONFIG_SUCCESS);
    void *value = config_remove(&config, "key1");
    assert(strcmp((char *) value, "value1") == 0);
    assert(config_size(&config) == 0);
    config_free(&config);

    // Test the configuration key retrieval.
    status = config_init(&config);
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value1");
    assert(status == CONFIG_SUCCESS);
    value = config_get(&config, "key1");
    assert(strcmp((char *) value, "value1") == 0);
    assert(config_size(&config) == 1);
    config_free(&config);

    // Test the configuration size.
    status = config_init(&config);
    assert(status == CONFIG_SUCCESS);
    status = config_insert(&config, "key1", "value1");
    assert(status == CONFIG_SUCCESS);
    assert(config_size(&config) == 1);
    status = config_insert(&config, "key2", "value2");
    assert(status == CONFIG_SUCCESS);
    assert(config_size(&config) == 2);
    config_clear(&config);
    assert(config_size(&config) == 0);
    config_free(&config);

    return 0;
}']

