// Define synchronization mechanism using a mutex and condition variable
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Function to manage the dynamic, in-memory list of NFAPI_CRC_INDICATION_PDU_T structures
void nfapi_crc_indication_list_manage(NFAPI_CRC_INDICATION_LIST* list) {
    // Acquire mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Retention policy: clear entries older than the configured threshold
    struct timespec current_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    for (int i = 0; i < list->size; i++) {
        if (difftime(current_time.tv_sec, list->pdu[i].tag.timestamp) > RETENTION_THRESHOLD) {
            // Remove entry from the list
            free(list->pdu[i]);
            list->size--;
            i--;
        }
    }

    // Release mutex and notify waiting threads that the retention policy has been applied
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Function to add a new NFAPI_CRC_INDICATION_PDU_T structure to the list
void nfapi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU* pdu) {
