    pthread_mutex_lock(&mutex);

    // Check if the RNTI value is unique within the list
    int found = 0;
    for (int i = 0; i < list->size; i++) {
        if (list->pdu[i].rnti == pdu->rnti) {
            // Append a sequence number to the existing entry
            char new_rnti_str[16];
            sprintf(new_rnti_str, "%d", list->pdu[i].rnti);
            int new_rnti = atoi(new_rnti_str) + 1;
            pdu->rnti = new_rnti;
            found = 1;
            break;
        }
    }

    // If the RNTI value is not unique, add a new entry to the list
    if (!found) {
        list->pdu[list->size].tag.timestamp = current_time;
        list->pdu[list->size].rnti = pdu->rnti;
        list->pdu[list->size].crc_indication_rel8 = pdu->crc_indication_rel8;
        list->size++;
    }

    // Release mutex and notify waiting threads that a new entry has been added
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}

// Function to retrieve the latest NFAPI_CRC_INDICATION_PDU_T structure from the list
void nfapi_crc_indication_list_get(NFAPI_CRC_INDICATION_LIST* list, NFAPI_CRC_INDICATION_PDU* pdu) {
    // Acquire mutex to ensure thread safety
    pthread_mutex_lock(&mutex);

    // Check if the list is empty
    if (list->size == 0) {
        pthread_mutex_unlock(&mutex);
        return;
    }

    // Retrieve the latest entry from the list
    int index = list->size - 1;
    *pdu = list->pdu[index];

    // Release mutex and notify waiting threads that a new entry has been retrieved
    pthread_mutex_unlock(&mutex);
    pthread_cond_signal(&cond);
}
