    }
}

// Custom hash function to optimize performance and minimize collisions
unsigned long hash(int key) {
    // Use a simple polynomial hash function with x^3 + x^2 + 1
    unsigned long hash = (key * key * key) % ht->size;
    return hash;
}

// Custom copy constructor for the record structure
record* copy_record(record* r) {
    // Allocate memory for the new record and copy all members
    record* new_r = (record*)malloc(sizeof(record));
    if (!new_r) {
        printf("Error: unable to allocate memory for new record\n");
        exit(1);
    }

    new_r->key = r->key;
    new_r->offset = r->offset;

    return new_r;
}

// Insert a new record into the hash table
void insert(record* r) {
    // Acquire lock on the mutex to ensure thread-safe access
    pthread_mutex_lock(&ht->mutex);

    // Check if the key already exists in the hash table
    int index = hash(r->key);
    while (ht->records[index] != NULL && ht->records[index]->key == r->key) {
        index++;
        index %= ht->size;
    }

    // Insert the new record into the hash table at the first available index
    ht->records[index] = copy_record(r);

    // Release lock on the mutex
    pthread_mutex_unlock(&ht->mutex);
}

// Look up a key in the hash table and return its corresponding offset
long* lookup(int key) {
    // Acquire lock on the mutex to ensure thread-safe access
    pthread_mutex_lock(&ht->mutex);

    // Check if the key exists in the hash table
    int index = hash(key);
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index++;
        index %= ht->size;
    }

    // Return the offset if the key exists in the hash table, otherwise return NULL
    long* offset = NULL;
    if (ht->records[index] != NULL) {
        offset = ht->records[index]->offset;
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&ht->mutex);

    return offset;
}

// Delete a record from the hash table
void delete(int key) {
    // Acquire lock on the mutex to ensure thread-safe access
    pthread_mutex_lock(&ht->mutex);

    // Check if the key exists in the hash table
    int index = hash(key);
    while (ht->records[index] != NULL && ht->records[index]->key != key) {
        index++;
        index %= ht->size;
    }

    // Delete the record from the hash table if it exists
    if (ht->records[index] != NULL) {
        free(ht->records[index]);
        ht->records[index] = NULL;
    }

    // Release lock on the mutex
    pthread_mutex_unlock(&ht->mutex);
}

