        return -1;
    }

    // Lock the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&config_mutex);

    // Update the type of the configuration object
    config->type = type;

    // Unlock the mutex
    pthread_mutex_unlock(&config_mutex);

    return 0;
}

/**
 * Retrieve a network configuration object from the library by its unique ID.
 */
int get(char *id) {
    // Check if the configuration exists in the hash table
    config_hash_t *config = find_config(id);
    if (config == NULL) {
        fprintf(stderr, "Error: configuration with ID '%s' does not exist\n", id);
        return -1;
    }

    // Lock the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&config_mutex);

    // Retrieve the configuration object
    network_config_t *new_config = malloc(sizeof(network_config_t));
    if (!new_config) {
        fprintf(stderr, "Error: failed to allocate memory for new configuration\n");
        return -1;
    }

    // Initialize the configuration object
    strcpy(new_config->id, id);
    new_config->type = config->type;
    new_config->state = ACTIVATED;

    // Unlock the mutex
    pthread_mutex_unlock(&config_mutex);

    return new_config;
}

/**
 * Find a network configuration object in the hash table by its unique ID.
 */
config_hash_t *find_config(char *id) {
    // Check if the hash table exists
    if (!config_table) {
        fprintf(stderr, "Error: configuration table does not exist\n");
        return NULL;
    }

    // Lock the mutex for synchronizing access to the hash table
    pthread_mutex_lock(&config_mutex);

    // Find the corresponding configuration object in the hash table
    config_hash_t *config = (config_hash_t *)bsearch(id, config_table, sizeof(config_hash_t), compare_configs);

    // Unlock the mutex
    pthread_mutex_unlock(&config_mutex);

    return config;
}

/**
 * Compare two network configuration objects by their unique ID.
 */
int compare_configs(const void *a, const void *b) {
    // Get the IDs of the two configurations
    char *id1 = ((config_hash_t *)a)->id;
    char *id2 = ((config_hash_t *)b)->id;

    return strcmp(id1, id2);
}
