};

class NetworkConfigManager {
public:
    NetworkConfigManager() {}

    ~NetworkConfigManager() {}

    void add_config(int id, const string& bearer_name) {
        unique_lock<mutex> lock(_mtx);
        _configs.push_back({id, bearer_name});
    }

    bool update_config(int id, const string& bearer_name) {
        unique_lock<mutex> lock(_mtx);
        for (auto it = _configs.begin(); it != _configs.end(); ++it) {
            if (it->id == id) {
                it->bearer_name = bearer_name;
                return true;
            }
        }
        return false;
    }

    Config get_config(int id) {
        unique_lock<mutex> lock(_mtx);
        for (auto it = _configs.begin(); it != _configs.end(); ++it) {
            if (it->id == id) {
                return *it;
            }
        }
        throw "Config not found";
