    new_setting->port_number = port_number;
    new_setting->timeout_value = timeout_value;
    new_setting->auth_credentials = auth_credentials;

    // Add the new setting to the settings array
    settings[capacity - 1] = new_setting;
    capacity--;
}

// Define a function to remove a configuration setting by index
void remove_config_setting(struct config_settings** settings, size_t* capacity, size_t index) {
    // Check if the index is valid
    if (index >= *capacity) {
        printf("Invalid index. Cannot remove configuration setting.\n");
        return;
    }

    // Free the memory of the setting to be removed
    free(settings[index]->server_ip);
    settings[index]->server_ip = NULL;
    free(settings[index]->auth_credentials);
    settings[index]->auth_credentials = NULL;
    free(settings[index]);
    settings[index] = NULL;

    // Shift the remaining settings to fill the gap
    for (size_t i = index + 1; i < *capacity; i++) {
        settings[i - 1] = settings[i];
    }

    // Decrement the capacity
    (*capacity)--;
}

