    free(setting->server_ip);
    setting->server_ip = server_ip;
    setting->port_number = port_number;
    setting->timeout_value = timeout_value;
    free(setting->auth_credentials);
    setting->auth_credentials = auth_credentials;
}

// Define a function to handle configuration updates without requiring service restarts
void dynamic_update(struct config_settings** settings, size_t* capacity, char* server_ip, int port_number, int timeout_value, char* auth_credentials) {
    // Check if the new setting is already present in the settings array
    for (size_t i = 0; i < *capacity; i++) {
        struct config_settings* setting = settings[i];
        if (strcmp(setting->server_ip, server_ip) == 0 && setting->port_number == port_number && setting->timeout_value == timeout_value) {
            // Update the existing setting instead of adding a new one
            update_config_setting(settings, capacity, i, server_ip, port_number, timeout_value, auth_credentials);
            return;
        }
    }

    // Add the new setting to the settings array
    add_config_setting(settings, *capacity, server_ip, port_number, timeout_value, auth_credentials);
