#include <time.h>

// Define structure for task
typedef struct Task {
  char* name;
  int priority;
  time_t startTime;
} Task;

// Define array of tasks to store in list
Task* tasks = NULL;
int numTasks = 0;

// Function to add new task to list
void addTask(char* name, int priority) {
  // Allocate memory for new task structure
  Task* newTask = (Task*)malloc(sizeof(Task));
  if (!newTask) {
    printf("Error: Memory allocation failed\n");
    return;
  }

  // Initialize fields of new task structure
  newTask->name = strdup(name);
  newTask->priority = priority;
  newTask->startTime = time(NULL);

  // Add new task to list and increment counter
  tasks = realloc(tasks, (numTasks + 1) * sizeof(Task));
  if (!tasks) {
    printf("Error: Reallocation failed\n");
    free(newTask->name);
    free(newTask);
    return;
  }
  tasks[numTasks] = newTask;
  numTasks++;
}

// Function to remove task from list by name
void removeTask(char* name) {
  // Find index of task with matching name
  int i = 0;
  for (i = 0; i < numTasks; i++) {
    if (strcmp(tasks[i]->name, name) == 0) {
      break;
    }
  }

  // If found, remove task and adjust list
  if (i < numTasks) {
    free(tasks[i]->name);
    free(tasks[i]);
    memmove(&tasks[i], &tasks[i + 1], (numTasks - i - 1) * sizeof(Task));
    tasks = realloc(tasks, (numTasks - 1) * sizeof(Task));
    if (!tasks) {
      printf("Error: Reallocation failed\n");
      return;
    }
    numTasks--;
  } else {
    printf("Error: Task not found in list\n");
  }
}

// Function to update priority level of task by name
void updatePriority(char* name, int newPriority) {
  // Find index of task with matching name
  int i = 0;
  for (i = 0; i < numTasks; i++) {
    if (strcmp(tasks[i]->name, name) == 0) {
      break;
    }
  }

  // If found, update priority level and adjust list
  if (i < numTasks) {
    tasks[i]->priority = newPriority;
  } else {
    printf("Error: Task not found in list\n");
  }
}

// Function to sort task list by priority using a stable sorting algorithm
void sortTasks() {
  // Define comparison function for sorting tasks by priority
  int compare(const void* a, const void* b) {
    return ((Task*)a)->priority - ((Task*)b)->priority;
  }

  // Sort task list using stable sorting algorithm
  qsort(tasks, numTasks, sizeof(Task), compare);
}

// Function to serialize task list to disk for persistence
void serializeTasks() {
  // Open file for writing
  FILE* fp = fopen("task_list.txt", "w");
  if (!fp) {
    printf("Error: Failed to open file for writing\n");
    return;
  }

  // Write each task in list to file
  for (int i = 0; i < numTasks; i++) {
    fprintf(fp, "%s %d %ld\n", tasks[i]->name, tasks[i]->priority, tasks[i]->startTime);
  }

  // Close file and free memory
  fclose(fp);
}

// Function to deserialize task list from disk for persistence
void deserializeTasks() {
  // Open file for reading
  FILE* fp = fopen("task_list.txt", "r");
  if (!fp) {
    printf("Error: Failed to open file for reading\n");
    return;
  }

  // Read each line of file into task structure
  while (fscanf(fp, "%s %d %ld\n", tasks[numTasks]->name, &tasks[numTasks]->priority, &tasks[numTasks]->startTime) == 3) {
    numTasks++;
    tasks = realloc(tasks, numTasks * sizeof(Task));
    if (!tasks) {
      printf("Error: Reallocation failed\n");
      fclose(fp);
      return;
    }
  }

  // Close file and free memory
  fclose(fp);
}
