// Dynamic array of LTE_PHY_RX_FRAME structures
struct LTE_PHY_RX_FRAME {
    struct LTE_PHY_RX_SYMBOL *symbols; // Pointer to an array of symbols
    int num_symbols;                   // Number of symbols in the frame
    double signal_strength;            // Signal strength indicator
};

// LTE_PHY_RX_FRAME structure
struct LTE_PHY_RX_SYMBOL {
    char modulation;               // Modulation type
    int phase_rotation;            // Phase rotation
    double noise_variance;         // Noise variance estimate
};

// Dynamic array of LTE_PHY_RX_FRAME structures
struct LTE_PHY_RX_FRAME_ARRAY {
    struct LTE_PHY_RX_FRAME *frames; // Pointer to an array of frames
    int num_frames;                // Number of frames in the array
};

// Synchronization mechanism for concurrent access and modifications
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void init_dynamic_array(struct LTE_PHY_RX_FRAME_ARRAY *arr) {
    arr->frames = NULL;
    arr->num_frames = 0;
}

// Allocate memory for a new frame
struct LTE_PHY_RX_FRAME *alloc_frame() {
    struct LTE_PHY_RX_FRAME *frame = malloc(sizeof(struct LTE_PHY_RX_FRAME));
    if (frame == NULL) {
        return NULL;
    }
    frame->symbols = NULL;
    frame->num_symbols = 0;
    frame->signal_strength = 0.0;
    return frame;
}

// Allocate memory for a new symbol within a frame
struct LTE_PHY_RX_SYMBOL *alloc_symbol(struct LTE_PHY_RX_FRAME *frame) {
    struct LTE_PHY_RX_SYMBOL *symbol = malloc(sizeof(struct LTE_PHY_RX_SYMBOL));
    if (symbol == NULL) {
        return NULL;
    }
    symbol->modulation = 0;
    symbol->phase_rotation = 0;
    symbol->noise_variance = 0.0;
    frame->num_symbols++;
    return symbol;
}

// Deallocate memory for a frame and its symbols
void dealloc_frame(struct LTE_PHY_RX_FRAME *frame) {
    if (frame == NULL) {
        return;
    }
    struct LTE_PHY_RX_SYMBOL *symbol = frame->symbols;
    while (symbol != NULL) {
        struct LTE_PHY_RX_SYMBOL *next = symbol->next;
        free(symbol);
        symbol = next;
    }
    free(frame);
}

// Add a new frame to the dynamic array
int add_frame(struct LTE_PHY_RX_FRAME_ARRAY *arr, struct LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&lock);
    int ret = 0;
    if (arr->frames == NULL) {
        arr->frames = malloc(sizeof(struct LTE_PHY_RX_FRAME));
        if (arr->frames == NULL) {
            ret = -ENOMEM;
            goto unlock;
        }
    } else {
        struct LTE_PHY_RX_FRAME *tmp = realloc(arr->frames, (arr->num_frames + 1) * sizeof(struct LTE_PHY_RX_FRAME));
        if (tmp == NULL) {
            ret = -ENOMEM;
            goto unlock;
        }
    }
    arr->frames[arr->num_frames++] = frame;
unlock:
    pthread_mutex_unlock(&lock);
    return ret;
}

// Remove a frame from the dynamic array
int remove_frame(struct LTE_PHY_RX_FRAME_ARRAY *arr, struct LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&lock);
    int ret = 0;
    if (arr->frames == NULL || arr->num_frames == 0) {
        ret = -EINVAL;
        goto unlock;
    }
    struct LTE_PHY_RX_FRAME *tmp = arr->frames[arr->num_frames];
    for (int i = 0; i < arr->num_frames; i++) {
        if (tmp == frame) {
            arr->num_frames--;
            break;
        }
        tmp = tmp->next;
    }
unlock:
    pthread_mutex_unlock(&lock);
    return ret;
}

// Serialize the dynamic array to a binary file
int serialize(struct LTE_PHY_RX_FRAME_ARRAY *arr, FILE *fp) {
    if (fp == NULL) {
        return -EINVAL;
    }
    pthread_mutex_lock(&lock);
    int ret = 0;
    for (int i = 0; i < arr->num_frames; i++) {
        struct LTE_PHY_RX_FRAME *frame = arr->frames[i];
        if (fwrite(frame, sizeof(struct LTE_PHY_RX_FRAME), 1, fp) != 1) {
            ret = -ENOENT;
            goto unlock;
        }
    }
unlock:
    pthread_mutex_unlock(&lock);
    return ret;
}

// Deserialize the dynamic array from a binary file
int deserialize(struct LTE_PHY_RX_FRAME_ARRAY *arr, FILE *fp) {
    if (fp == NULL) {
        return -EINVAL;
    }
    pthread_mutex_lock(&lock);
    int ret = 0;
    while (!feof(fp)) {
        struct LTE_PHY_RX_FRAME *frame = alloc_frame();
        if (fread(frame, sizeof(struct LTE_PHY_RX_FRAME), 1, fp) != 1) {
            ret = -ENOENT;
            goto unlock;
        }
        add_frame(arr, frame);
    }
unlock:
    pthread_mutex_unlock(&lock);
    return ret;
}
```

