void addUserDataRecord(struct UserDataList* list, int user_id, char* session_info, unsigned long traffic_statistics) {
    // Check if the list is full
    if (list->size == 50000) {
        // If the list is full, prune inactive records based on a configurable time threshold
        pruneInactiveRecords(list);
    }

    // Allocate memory for the new record
