void pruneInactiveRecords(struct UserDataList* list) {
    // Iterate through the records and check if they are older than the configured time threshold
    for (int i = 0; i < list->size; ++i) {
        USER_DATA_RECORD* record = &list->records[i];
        if (record->last_accessed_time + getInactiveTimeThreshold() <= time(NULL)) {
            // If the record is inactive, remove it from the list
            memmove(&list->records[i], &list->records[i+1], sizeof(USER_DATA_RECORD) * (list->size - i));
            list->size--;
            i--;
        }
    }
}

