    unsigned int inactiveTimeThreshold = 30 * 24 * 60 * 60; // Default to 30 days
    char* inactiveTimeThresholdStr = getSetting("inactive_time_threshold");
    if (inactiveTimeThresholdStr) {
        inactiveTimeThreshold = atoi(inactiveTimeThresholdStr);
    }
    return inactiveTimeThreshold;
}

// Define a function to get a setting from the settings file
char* getSetting(const char* settingName) {
    // Read the value of the setting from the settings file
    char* settingValue = NULL;
    FILE* settingsFile = fopen("settings.txt", "r");
    if (settingsFile) {
        while (!feof(settingsFile)) {
            char buffer[1024];
            if (fgets(buffer, 1024, settingsFile)) {
                char* setting = strtok(buffer, ":");
                if (setting && !strcmp(settingName, setting)) {
                    // If the setting is found, return its value
                    char* value = strtok(NULL, "\n");
                    if (value) {
                        settingValue = strdup(value);
                    }
                }
            }
        }
        fclose(settingsFile);
    }
    return settingValue;
}

// Define a function to update the inactive time threshold in the settings file
void updateInactiveTimeThreshold(unsigned int newInactiveTimeThreshold) {
    // Write the new value of the inactive time threshold to the settings file
    char buffer[1024];
    FILE* settingsFile = fopen("settings.txt", "w");
    if (settingsFile) {
        fprintf(settingsFile, "inactive_time_threshold: %u\n", newInactiveTimeThreshold);
        fclose(settingsFile);
    }
}
