struct Transaction {
  long offset;
  int key;
  int value;
};

struct TransactionSet {
  struct Transaction* transactions;
  size_t capacity;
  size_t count;
  double maxWeightedSum;
  int maxWeightedSumTransactionId;
};

void initializeTransactionSet(struct TransactionSet* set) {
  set->transactions = NULL;
  set->capacity = 0;
  set->count = 0;
  set->maxWeightedSum = 0.0;
  set->maxWeightedSumTransactionId = -1;
}

void addTransaction(struct TransactionSet* set, struct Transaction transaction) {
  // Check if the set needs to be resized
  if (set->count >= set->capacity) {
    size_t newCapacity = set->capacity == 0 ? 16 : set->capacity * 2;
    struct Transaction* newTransactions = realloc(set->transactions, newCapacity * sizeof(struct Transaction));
    if (newTransactions == NULL) {
      // Handle out of memory error
      return;
    }
    set->transactions = newTransactions;
    set->capacity = newCapacity;
  }

  // Add the transaction to the set
  set->transactions[set->count] = transaction;
  set->count++;

  // Update the max weighted sum and corresponding transaction ID if necessary
  double weightedSum = transaction.value * (double)transaction.key;
  if (weightedSum > set->maxWeightedSum) {
    set->maxWeightedSum = weightedSum;
    set->maxWeightedSumTransactionId = transaction.id;
  }
}

void removeOldTransactions(struct TransactionSet* set, int threshold) {
  // Find the oldest transaction that is older than the threshold
  struct Transaction* oldTransaction = NULL;
  for (size_t i = 0; i < set->count; i++) {
    if (set->transactions[i].age >= threshold) {
      oldTransaction = &set->transactions[i];
      break;
    }
  }

  // Remove the oldest transaction from the set
  if (oldTransaction != NULL) {
    size_t indexToRemove = oldTransaction - set->transactions;
    for (size_t i = indexToRemove; i < set->count - 1; i++) {
      set->transactions[i] = set->transactions[i + 1];
    }
    set->count--;

    // Update the max weighted sum and corresponding transaction ID if necessary
    double weightedSum = oldTransaction->value * (double)oldTransaction->key;
    if (weightedSum == set->maxWeightedSum) {
      set->maxWeightedSum = 0.0;
      set->maxWeightedSumTransactionId = -1;
    } else if (weightedSum > set->maxWeightedSum) {
      set->maxWeightedSum -= weightedSum;
      set->maxWeightedSumTransactionId = oldTransaction->id;
    }
  }
}

void filterTransactions(struct TransactionSet* set, int threshold) {
  // Remove transactions that are older than the threshold
  removeOldTransactions(set, threshold);

