typedef struct interface {
    char ip[INET6_ADDRSTRLEN];
    char subnet[INET6_ADDRSTRLEN];
    char gateway[INET6_ADDRSTRLEN];
    int num_dns;
    char dns_servers[DNS_SERVERS_MAX][INET6_ADDRSTRLEN];
} interface_t;

typedef struct cache {
    interface_t interfaces[INITIAL_CACHE_SIZE];
    int size;
} cache_t;

cache_t *create_cache() {
    cache_t *cache = malloc(sizeof(cache_t));
    if (cache == NULL) {
        perror("Failed to allocate memory for cache");
        return NULL;
    }
    cache->size = 0;
    return cache;
}

void destroy_cache(cache_t *cache) {
    free(cache);
}

interface_t *find_interface(cache_t *cache, char *ip) {
    for (int i = 0; i < cache->size; ++i) {
        if (!strcmp(cache->interfaces[i].ip, ip)) {
            return &cache->interfaces[i];
        }
    }
    return NULL;
}

interface_t *add_interface(cache_t *cache, char *ip, char *subnet, char *gateway, int num_dns, char **dns_servers) {
    if (cache->size >= MAX_INTERFACES) {
        printf("Maximum number of interfaces reached\n");
        return NULL;
    }
    interface_t *interface = &cache->interfaces[cache->size];
    memset(interface, 0, sizeof(interface_t));
    strcpy(interface->ip, ip);
    strcpy(interface->subnet, subnet);
    strcpy(interface->gateway, gateway);
    interface->num_dns = num_dns;
    for (int i = 0; i < num_dns; ++i) {
        strcpy(interface->dns_servers[i], dns_servers[i]);
    }
    cache->size++;
    return interface;
}

void update_interface(cache_t *cache, char *ip, char *subnet, char *gateway, int num_dns, char **dns_servers) {
    interface_t *interface = find_interface(cache, ip);
    if (interface == NULL) {
        add_interface(cache, ip, subnet, gateway, num_dns, dns_servers);
    } else {
        strcpy(interface->subnet, subnet);
        strcpy(interface->gateway, gateway);
        interface->num_dns = num_dns;
        for (int i = 0; i < num_dns; ++i) {
            strcpy(interface->dns_servers[i], dns_servers[i]);
        }
    }
}

void free_interface(interface_t *interface) {
    free(interface);
}

int main() {
    cache_t *cache = create_cache();
    if (cache == NULL) {
        return 1;
    }

    char ip[] = "192.168.0.1";
    char subnet[] = "255.255.255.0";
    char gateway[] = "192.168.0.1";
    int num_dns = 2;
    char dns_servers[DNS_SERVERS_MAX][INET6_ADDRSTRLEN] = {"192.168.0.1", "192.168.0.2"};

    add_interface(cache, ip, subnet, gateway, num_dns, dns_servers);

    interface_t *interface = find_interface(cache, ip);
    if (interface != NULL) {
        printf("Interface found: %s\n", interface->ip);
        printf("Subnet: %s\n", interface->subnet);
        printf("Gateway: %s\n", interface->gateway);
        for (int i = 0; i < interface->num_dns; ++i) {
            printf("DNS server %d: %s\n", i + 1, interface->dns_servers[i]);
        }
    } else {
        printf("Interface not found\n");
    }

    update_interface(cache, ip, "255.255.0.0", "192.168.0.2", 3, dns_servers);

    interface = find_interface(cache, ip);
    if (interface != NULL) {
        printf("Updated interface: %s\n", interface->ip);
        printf("Subnet: %s\n", interface->subnet);
        printf("Gateway: %s\n", interface->gateway);
        for (int i = 0; i < interface->num_dns; ++i) {
            printf("DNS server %d: %s\n", i + 1, interface->dns_servers[i]);
        }
    } else {
        printf("Interface not found\n");
    }

    destroy_cache(cache);

    return 0;
}
