    collection->frames[collection->frame_count++] = frame;
}

void updateFrameInCollection(struct FrameCollection* collection, size_t index, struct LTE_PHY_RX_FRAME* frame) {
    // Check if the index is out of bounds
    if (index >= collection->frame_count) {
        return;
    }

    // Update the frame at the specified index in the array
    collection->frames[index] = frame;
}

void removeFrameFromCollection(struct FrameCollection* collection, size_t index) {
    // Check if the index is out of bounds
    if (index >= collection->frame_count) {
        return;
    }

    // Remove the frame at the specified index from the array
    for (size_t i = index; i < collection->frame_count - 1; i++) {
        collection->frames[i] = collection->frames[i + 1];
    }
    collection->frame_count--;
}

void initSymbolCollection(struct SymbolCollection* collection) {
    // Initialize the symbol count to 0 and allocate memory for the array of symbols
    collection->symbol_count = 0;
