// Define the structure for NFDataRecord
typedef struct {
  int32_t id;
  TaggedData data;
  DataChunk chunk;
} NFDataRecord;

// Define a list to store NFDataRecord structures
typedef struct {
  size_t capacity; // maximum number of elements in the list
  size_t size;    // current number of elements in the list
  NFDataRecord *data; // array of NFDataRecords
} NFDataList;

// Initialize a new empty list with a given capacity
void nfdata_list_init(NFDataList *list, size_t capacity) {
  list->capacity = capacity;
  list->size = 0;
  list->data = (NFDataRecord *)malloc(sizeof(NFDataRecord) * capacity);
}

// Add a new NFDataRecord to the list
void nfdata_list_add(NFDataList *list, NFDataRecord record) {
  if (list->size == list->capacity) {
    // resize the array if it's full
    list->data = (NFDataRecord *)realloc(list->data, sizeof(NFDataRecord) * 2 * capacity);
    list->capacity *= 2;
  }
  list->data[list->size++] = record;
}

// Update an existing NFDataRecord in the list based on its ID
bool nfdata_list_update(NFDataList *list, int32_t id, NFDataRecord new_record) {
  for (int i = 0; i < list->size; i++) {
    if (list->data[i].id == id) {
      // update the record in place
      memcpy(&list->data[i], &new_record, sizeof(NFDataRecord));
      return true;
    }
  }
  return false;
}

// Remove unused DataChunk entries from the list to optimize memory usage
void nfdata_list_compact(NFDataList *list) {
  for (int i = 0; i < list->size; i++) {
    if (!list->data[i].chunk.used) {
      // remove the unused DataChunk entry
      memmove(&list->data[i], &list->data[i + 1], sizeof(NFDataRecord) * (list->size - i));
      list->size--;
    }
  }
}
```
