// Define the function to dynamically adjust the size of the list based on system metrics
void adjust_list_size() {
    // Check the available memory and CPU load
    if (get_available_memory() < 100 || get_cpu_load() > 80) {
        // Decrease the size of the list by half
        CRC_INDICATION_LIST_T *list = &CRC_INDICATION_LIST;
        list->size /= 2;
    } else if (get_available_memory() > 500 && get_cpu_load() < 40) {
