        list->size *= 2;
    }
}

// Define the function to serialize the list into a binary format for persistence
void serialize_list(FILE *fp) {
    CRC_INDICATION_LIST_T *list = &CRC_INDICATION_LIST;
    for (size_t i = 0; i < list->size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = list->pdu[i];
        fwrite(&pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
    }
}

// Define the function to deserialize the binary data back into CRC indication PDUs
void deserialize_list(FILE *fp) {
    CRC_INDICATION_LIST_T *list = &CRC_INDICATION_LIST;
    while (!feof(fp)) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        fread(pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, fp);
        list->pdu = realloc(list->pdu, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(&list->pdu[list->size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->size++;
    }
}

// Define the function to handle variable throughput demands
void dynamic_resize(size_t num_elements) {
    CRC_INDICATION_LIST_T *list = &CRC_INDICATION_LIST;
    if (num_elements > list->size) {
        // Increase the size of the list by the difference between the new and old sizes
        list->size += num_elements - list->size;
    } else if (num_elements < list->size) {
        // Decrease the size of the list by half
        list->size /= 2;
