struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
};

typedef struct NFAPI_CRC_INDICATION_PDU_T NFAPI_CRC_INDICATION_PDU_T;

struct NFAPI_CRC_INDICATION_LIST {
    int size;
    NFAPI_CRC_INDICATION_PDU_T *data;
};

typedef struct NFAPI_CRC_INDICATION_LIST NFAPI_CRC_INDICATION_LIST;

// Atomic variables to maintain list and thread safety
std::atomic<int> next_index;
std::atomic<NFAPI_CRC_INDICATION_PDU_T *> current_list;

void manage_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, int rnti) {
    // Add new entry
    if (rnti != -1) {
        NFAPI_CRC_INDICATION_PDU_T *new_entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_entry->RX_UE_INFORMATION_TAG = 0;
        new_entry->RNTI = rnti;
        new_entry->CRC_INDICATION_REL8_TAG = 0;
        new_entry->CRCFLAG = false;
        list->data[list->size++] = *new_entry;
    }

    // Update existing entry based on RNTI
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            list->data[i].CRCFLAG = true;
            break;
        }
    }

    // Remove entry by RNTI
    for (int i = 0; i < list->size; ++i) {
        if (list->data[i].RNTI == rnti) {
            free(list->data + i);
            list->size--;
            break;
        }
    }
}

void *crc_indication_thread(void *args) {
    // Periodically update list from external data source
    while (true) {
        int rnti = get_rnti(); // Get RNTI from external data source
        manage_crc_indication_list(&current_list, rnti);
        sleep(10); // Sleep for 10 seconds before updating again
    }
}

int main() {
    pthread_t thread;
    NFAPI_CRC_INDICATION_LIST *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST));
    list->size = 0;
    list->data = NULL;

    // Create and start thread for updating list periodically
    pthread_create(&thread, NULL, crc_indication_thread, NULL);
    pthread_detach(thread);

    while (true) {
        int rnti = get_rnti(); // Get RNTI from external data source
        manage_crc_indication_list(&current_list, rnti);
    }
}
```
