// Function to dynamically allocate memory for an array of LTE_PHY_RX_PROC_T structures
void* alloc_rx_proc_array(size_t size) {
    void** arr = malloc(sizeof(void*) * size);
    if (!arr) {
        syslog(LOG_ERR, "Memory allocation failed for rx proc array");
        return NULL;
    }
    memset(arr, 0, sizeof(void*) * size);
    return arr;
