// Function to create a new device info structure and add it to the list of devices
int create_device_info(struct device_info** device) {
    struct device_info* new_dev = malloc(sizeof(struct device_info));
    if (!new_dev) {
        syslog(LOG_ERR, "Memory allocation failed for new device info");
        return -1;
    }
    memset(new_dev, 0, sizeof(struct device_info));
    *device = new_dev;
    return 0;
}

// Function to add a new device to the list of devices
int add_device(const char* ip_addr) {
    struct device_info* dev;
    if (create_device_info(&dev)) {
        syslog(LOG_ERR, "Failed to create device info");
        return -1;
    }
    strcpy(dev->ip_addr, ip_addr);
    num_devices++;
    // Add the new device to the end of the list of devices
    if (devices) {
        struct device_info* last = devices;
        while (last->next) {
            last = last->next;
        }
        last->next = dev;
    } else {
        devices = dev;
    }
    return 0;
}

// Function to update the configuration of a device in the list of devices
int update_device_config(const char* ip_addr, const struct network_config* config) {
    struct device_info* dev;
    if (find_device(&dev, ip_addr)) {
        syslog(LOG_ERR, "Device not found");
        return -1;
    }
    // Update the configuration of the device
    memcpy(&dev->config, config, sizeof(struct network_config));
    return 0;
}

// Function to find a device in the list of devices by its IP address
int find_device(struct device_info** dev, const char* ip_addr) {
    if (!devices) {
        *dev = NULL;
        return -1;
    }
    struct device_info* cur = devices;
    while (cur) {
        if (strcmp(cur->ip_addr, ip_addr) == 0) {
            *dev = cur;
            return 0;
        }
        cur = cur->next;
    }
    *dev = NULL;
    return -1;
}

// Function to free the memory allocated for a device info structure
void free_device_info(struct device_info* dev) {
    if (dev) {
        if (dev->config) {
            free(dev->config);
        }
        free(dev);
    }
}

// Function to free the memory allocated for the list of devices
void free_device_list() {
    struct device_info* cur = devices;
    while (cur) {
        struct device_info* next = cur->next;
        free_device_info(cur);
        cur = next;
    }
    devices = NULL;
}
