// Define the context pool structure
typedef struct mac_context_pool {
    MAC_CONTEXT* contexts;
    size_t num_contexts;
    pthread_mutex_t lock;
} MAC_CONTEXT_POOL;

// Function to initialize and populate a MAC context pool with a specified number of contexts, ensuring no two contexts share the same MAC ID
int init_mac_context_pool(MAC_CONTEXT_POOL* pool, size_t num_contexts) {
    // Allocate memory for the context pool and initialize the mutex lock
    pool->contexts = malloc(sizeof(MAC_CONTEXT) * num_contexts);
    if (pool->contexts == NULL) {
        return -1;
    }
    pool->num_contexts = num_contexts;
    pthread_mutex_init(&pool->lock, NULL);

    // Initialize each MAC context and assign a unique MAC ID
    for (size_t i = 0; i < num_contexts; i++) {
        pool->contexts[i].mac_id = i;
        pthread_mutex_init(&pool->contexts[i].lock, NULL);
    }

    return 0;
}

// Function to validate input data for each network device configuration and handle dynamic memory allocation efficiently under varying loads
int add_network_device_config(MAC_CONTEXT_POOL* pool, const NETWORK_DEVICE_CONFIG* config) {
    // Acquire the mutex lock to prevent concurrent access to the context pool
    pthread_mutex_lock(&pool->lock);

    // Check if there is space in the context pool for a new MAC context
    if (pool->num_contexts >= MAX_MAC_CONTEXTS) {
        return -1;
    }

    // Allocate memory for the new MAC context and initialize it
    MAC_CONTEXT* context = malloc(sizeof(MAC_CONTEXT));
    if (context == NULL) {
        pthread_mutex_unlock(&pool->lock);
        return -1;
    }
    memset(context, 0, sizeof(MAC_CONTEXT));

    // Validate the input data for each configuration and handle dynamic memory allocation efficiently under varying loads
    context->mac_id = pool->num_contexts++;
    pthread_mutex_init(&context->lock, NULL);
    if (config->device_type == DEVICE_TYPE_ETHERNET) {
        context->ip_address = malloc(sizeof(struct in_addr));
        if (context->ip_address == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->ip_address, 0, sizeof(struct in_addr));
        context->subnet_mask = malloc(sizeof(struct in_addr));
        if (context->subnet_mask == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->subnet_mask, 0, sizeof(struct in_addr));
        context->gateway = malloc(sizeof(struct in_addr));
        if (context->gateway == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->gateway, 0, sizeof(struct in_addr));
    } else {
        context->ip_address = malloc(sizeof(struct in6_addr));
        if (context->ip_address == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->ip_address, 0, sizeof(struct in6_addr));
        context->subnet_mask = malloc(sizeof(struct in6_addr));
        if (context->subnet_mask == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->subnet_mask, 0, sizeof(struct in6_addr));
        context->gateway = malloc(sizeof(struct in6_addr));
        if (context->gateway == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context->gateway, 0, sizeof(struct in6_addr));
    }

    // Add the new MAC context to the pool and release the mutex lock
    pool->contexts[context->mac_id] = *context;
    pthread_mutex_unlock(&pool->lock);

    return 0;
}

// Function to manage a dynamic pool of MAC context structures, each representing a network entity's state, while also handling a list of custom data structures for network device configurations. Each configuration includes details such as device type, IP address, subnet mask, gateway, and a list of port settings. The function should initialize and populate the pool with a specified number of contexts, ensuring no two contexts share the same MAC ID
int manage_mac_context_pool(MAC_CONTEXT_POOL* pool) {
    // Acquire the mutex lock to prevent concurrent access to the context pool
    pthread_mutex_lock(&pool->lock);

    // Check if there are any available MAC contexts in the pool
    for (size_t i = 0; i < pool->num_contexts; i++) {
        if (pool->contexts[i].used == false) {
            pool->contexts[i].used = true;
            pthread_mutex_unlock(&pool->lock);
            return &pool->contexts[i];
        }
    }

    // If there are no available MAC contexts, allocate a new one and add it to the pool
    if (pool->num_contexts < MAX_MAC_CONTEXTS) {
        MAC_CONTEXT* context = malloc(sizeof(MAC_CONTEXT));
        if (context == NULL) {
            pthread_mutex_unlock(&pool->lock);
            return -1;
        }
        memset(context, 0, sizeof(MAC_CONTEXT));
        context->mac_id = pool->num_contexts++;
        pthread_mutex_init(&context->lock, NULL);
        pool->contexts[context->mac_id] = *context;
        pthread_mutex_unlock(&pool->lock);
        return &pool->contexts[context->mac_id];
    }

    // If there are no available MAC contexts, return NULL to indicate that the pool is full
    pthread_mutex_unlock(&pool->lock);
    return NULL;
}

// Function to release a specific MAC context back into the pool for other threads to use
int release_mac_context(MAC_CONTEXT* context) {
    // Acquire the mutex lock to prevent concurrent access to the pool
    pthread_mutex_lock(&pool->lock);

    // Check if the specified MAC context is in the pool
    for (size_t i = 0; i < pool->num_contexts; i++) {
        if (&pool->contexts[i] == context) {
            pool->contexts[i].used = false;
            pthread_mutex_unlock(&pool->lock);
            return 0;
        }
    }

    // If the specified MAC context is not in the pool, return an error
    pthread_mutex_unlock(&pool->lock);
    return -1;
}']

