// Define the task structure
typedef struct {
    char *name;
    int priority;
    time_t start_time;
    time_t expiration_time;
} Task;

// Define the task list data structure
typedef struct {
    Task **tasks;
    size_t capacity;
    size_t count;
} TaskList;

// Function to create a new task list
TaskList* task_list_create() {
    // Allocate memory for the task list
    TaskList *task_list = (TaskList*)malloc(sizeof(TaskList));
    if (!task_list) {
        return NULL;
    }

    // Initialize the task list with an initial capacity of 16 tasks
    task_list->tasks = (Task**)malloc(sizeof(Task*) * 16);
    if (!task_list->tasks) {
        free(task_list);
        return NULL;
    }
    task_list->capacity = 16;
    task_list->count = 0;

    return task_list;
}

// Function to add a new task to the list
int task_list_add(TaskList *task_list, const char* name, int priority) {
    // Check if the task list is full
    if (task_list->count >= task_list->capacity) {
        return -1;
    }

    // Allocate memory for the new task
    Task *new_task = (Task*)malloc(sizeof(Task));
    if (!new_task) {
        return -2;
    }

    // Initialize the new task fields
    new_task->name = strdup(name);
    new_task->priority = priority;
    new_task->start_time = time(NULL);
    new_task->expiration_time = 0;

    // Add the new task to the list
    task_list->tasks[task_list->count] = new_task;
    task_list->count++;

    return 0;
}

// Function to update an existing task in the list
int task_list_update(TaskList *task_list, const char* name, int priority) {
    // Find the task with the given name
    for (size_t i = 0; i < task_list->count; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            task_list->tasks[i]->priority = priority;
            return 0;
        }
    }

    // Task not found
    return -1;
}

// Function to remove a task from the list based on its name
int task_list_remove(TaskList *task_list, const char* name) {
    // Find the task with the given name
    for (size_t i = 0; i < task_list->count; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            Task *task = task_list->tasks[i];
            task_list->tasks[i] = NULL;
            free(task);
            return 0;
        }
    }

    // Task not found
    return -1;
}

// Function to retrieve tasks by priority level
Task** task_list_retrieve(TaskList *task_list, int priority) {
    // Allocate memory for the retrieved tasks
    size_t count = 0;
    for (size_t i = 0; i < task_list->count; i++) {
        if (task_list->tasks[i]->priority == priority) {
            count++;
        }
    }

    Task **retrieved_tasks = (Task**)malloc(sizeof(Task*) * count);
    if (!retrieved_tasks) {
        return NULL;
    }

    // Copy the retrieved tasks to the array
    size_t j = 0;
    for (size_t i = 0; i < task_list->count; i++) {
        if (task_list->tasks[i]->priority == priority) {
            retrieved_tasks[j++] = task_list->tasks[i];
        }
    }

    return retrieved_tasks;
}

// Function to sort the tasks by priority level using a stable sorting algorithm
void task_list_sort(TaskList *task_list) {
    // Use a stable sorting algorithm, such as quicksort or mergesort
    qsort(task_list->tasks, task_list->count, sizeof(Task*), compare_tasks);
}

// Comparison function for sorting tasks by priority level
int compare_tasks(const void *a, const void *b) {
    Task **ta = (Task**)a;
    Task **tb = (Task**)b;
    return (*ta)->priority - (*tb)->priority;
}

// Function to notify when a task expires
void task_list_notify(TaskList *task_list, const char* name) {
    // Find the task with the given name
    for (size_t i = 0; i < task_list->count; i++) {
        if (strcmp(task_list->tasks[i]->name, name) == 0) {
            Task *task = task_list->tasks[i];
            task->expiration_time = time(NULL);
            return;
        }
    }
}

// Function to handle expired tasks and remove them from the list
void task_list_handle_expirations(TaskList *task_list) {
    // Iterate over the tasks in the list and check for expiration
    for (size_t i = 0; i < task_list->count; i++) {
        Task *task = task_list->tasks[i];
        if (task->expiration_time > 0 && task->expiration_time < time(NULL)) {
            // Notify the system of the expired task
            task_list->tasks[i] = NULL;
            free(task);
            i--;
        }
    }
}

// Function to handle REST API requests for tasks
int task_api_handler(TaskList *task_list, const char* method, const char* path) {
    // Check if the method is GET or POST
    if (strcmp(method, "GET") == 0 || strcmp(method, "POST") == 0) {
        // Parse the request path and query parameters
        char *path_parts[3];
        int num_parts = split_path(path, "/", path_parts);
        if (num_parts != 2) {
            return -1;
        }

        // Handle GET requests for all tasks
        if (strcmp(method, "GET") == 0) {
            // Retrieve all tasks from the list and serialize them as JSON
            Task **tasks = task_list_retrieve(task_list, -1);
            int num_tasks = 0;
            for (size_t i = 0; i < task_list->count; i++) {
                if (tasks[i] != NULL) {
                    num_tasks++;
                }
            }

            // Allocate memory for the serialized JSON data
            size_t json_size = sizeof(Task*) * num_tasks + 2048;
            char *json = malloc(json_size);
            if (json == NULL) {
                return -1;
            }

            // Serialize the tasks as JSON
            int pos = 0;
            pos += sprintf(json, "{\"tasks\":[");
            for (size_t i = 0; i < task_list->count; i++) {
                if (tasks[i] != NULL) {
                    pos += sprintf(json + pos, "%s", json_encode_task(tasks[i]));
                    if (i < num_tasks - 1) {
                        pos += sprintf(json + pos, ",");
                    }
                }
            }
            pos += sprintf(json + pos, "]}\n");

            // Send the JSON data to the client
            send(connection_fd, json, pos, 0);
            free(json);
        }

        // Handle POST requests for creating new tasks
        if (strcmp(method, "POST") == 0) {
            // Parse the request body and create a new task
            char *body = parse_request_body(connection_fd);
            Task *task = json_decode_task(body);
            free(body);
            if (task != NULL) {
                task->expiration_time = time(NULL) + 3600; // Set the expiration time to one hour from now
                task_list_add(task_list, task);
            }
        }
    } else {
        return -1;
    }

    return 0;
}

// Function to add a new task to the list
void task_list_add(TaskList *task_list, Task *task) {
    // Grow the array if necessary
    if (task_list->count >= task_list->capacity) {
        task_list->capacity *= 2;
        task_list->tasks = realloc(task_list->tasks, sizeof(Task*) * task_list->capacity);
    }

    // Add the new task to the list
    task_list->tasks[task_list->count++] = task;
}

// Function to handle expired tasks and remove them from the list
void task_list_handle_expirations(TaskList *task_list) {
    // Iterate over the tasks in the list and check for expiration
    for (size_t i = 0; i < task_list->count; i++) {
        Task *task = task_list->tasks[i];
        if (task->expiration_time > 0 && task->expiration_time < time(NULL)) {
            // Notify the system of the expired task
            task_list->tasks[i] = NULL;
            free(task);
            i--;
        }
    }
}
