// Define the function to update existing entries based on a provided RNTI
void updateExistingEntries(DynamicList *list, uint16_t RNTI) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i].RX_UE_INFORMATION_TAG == RNTI) {
            // Toggle the CRCFLAG between 0 and 1
            if (list->list[i].CRCFLAG == 0) {
                list->list[i].CRCFLAG = 1;
            } else {
                list->list[i].CRCFLAG = 0;
            }
        }
    }
}

// Define the function to remove entries by RNTI
void removeByRnti(DynamicList *list, uint16_t RNTI) {
    for (size_t i = 0; i < list->count; i++) {
        if (list->list[i].RX_UE_INFORMATION_TAG == RNTI) {
            memmove(&list->list[i], &list->list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list->count - i));
            list->count--;
        }
    }
}

// Define the function to toggle the CRCFLAG between 0 and 1 periodically
void toggleCRCFlag(DynamicList *list, size_t interval) {
    for (size_t i = 0; i < list->count; i++) {
        if (i % interval == 0 && list->list[i].CRCFLAG == 1) {
            list->list[i].CRCFLAG = 0;
        } else if (i % interval == 0 && list->list[i].CRCFLAG == 0) {
            list->list[i].CRCFLAG = 1;
        }
    }
}

