// Structures to represent a user profile and an edge in the graph
struct UserProfile {
  char *name; // name of the user
  int age; // age of the user
};

struct Edge {
  struct UserProfile *user1; // first user in the edge
  struct UserProfile *user2; // second user in the edge
};

// Data structure to represent the graph
struct Graph {
  struct UserProfile **users; // array of user profiles
  struct Edge **edges; // array of edges in the graph
  int num_users; // number of users in the graph
  int num_edges; // number of edges in the graph
};

// Function to add a new user to the graph
void addUser(struct Graph *graph, struct UserProfile *user) {
  if (graph->num_users >= MAX_USERS) {
    fprintf(stderr, "Error: maximum number of users reached\n");
    return;
  }
  // allocate memory for the new user profile
  graph->users[graph->num_users] = malloc(sizeof(struct UserProfile));
  memcpy(graph->users[graph->num_users], user, sizeof(struct UserProfile));
  graph->num_users++;
}

// Function to remove an existing user from the graph
void removeUser(struct Graph *graph, int user_id) {
  if (user_id >= graph->num_users || user_id < 0) {
    fprintf(stderr, "Error: invalid user ID\n");
    return;
  }
  // free the memory allocated for the user profile
  free(graph->users[user_id]);
  // update the number of users in the graph
  graph->num_users--;
}

// Function to update an existing user profile in the graph
void updateUserProfile(struct Graph *graph, struct UserProfile *user) {
  if (user->id >= graph->num_users || user->id < 0) {
    fprintf(stderr, "Error: invalid user ID\n");
    return;
  }
  // update the user profile in the graph
  memcpy(graph->users[user->id], user, sizeof(struct UserProfile));
}

// Function to traverse the graph using a depth-first search (DFS) algorithm
void dfsTraversal(struct Graph *graph, int start_node, int *visited) {
  // initialize the visited array
  for (int i = 0; i < graph->num_users; i++) {
    visited[i] = 0;
  }
  // mark the starting node as visited
  visited[start_node] = 1;
  // recursively traverse the graph
  dfsRecursive(graph, start_node, visited);
}

// Recursive function to traverse the graph using a depth-first search (DFS) algorithm
void dfsRecursive(struct Graph *graph, int node, int *visited) {
  // mark all adjacent nodes as visited
  for (int i = 0; i < graph->num_edges; i++) {
    if (graph->edges[i]->user1 == &graph->users[node] ||
        graph->edges[i]->user2 == &graph->users[node]) {
      visited[graph->edges[i]->user1 - graph->users] = 1;
      visited[graph->edges[i]->user2 - graph->users] = 1;
    }
  }
  // recursively traverse the graph for all unvisited nodes
  for (int i = 0; i < graph->num_users; i++) {
    if (!visited[i]) {
      dfsRecursive(graph, i, visited);
    }
  }
}

// Function to cache frequently accessed data in memory
void cacheData(struct Graph *graph) {
  // create a cache for the graph's edges and nodes
  struct Edge **edges_cache = malloc(sizeof(struct Edge *) * graph->num_edges);
  memcpy(edges_cache, graph->edges, sizeof(struct Edge *) * graph->num_edges);
  struct UserProfile **nodes_cache = malloc(sizeof(struct UserProfile *) * graph->num_users);
  memcpy(nodes_cache, graph->users, sizeof(struct UserProfile *) * graph->num_users);
}

// Function to serialize the graph schema to disk for persistence across application restarts
void serializeGraph(struct Graph *graph) {
  // create a file for serialization
  FILE *file = fopen("graph.bin", "wb");
  if (file == NULL) {
    fprintf(stderr, "Error: failed to open graph file for writing\n");
    return;
  }
  // serialize the graph's users and edges
  int num_users = graph->num_users;
  int num_edges = graph->num_edges;
  fwrite(&num_users, sizeof(int), 1, file);
  fwrite(&num_edges, sizeof(int), 1, file);
  for (int i = 0; i < graph->num_users; i++) {
    fwrite(graph->users[i], sizeof(struct UserProfile), 1, file);
  }
  for (int i = 0; i < graph->num_edges; i++) {
    fwrite(graph->edges[i], sizeof(struct Edge), 1, file);
  }
  // close the file
  fclose(file);
}
