    for (uint32_t i = 0; i < list->size; i++) {
        if (list->data[i].rnti == rnti) {
            return i;
        }
    }
    return list->size;
}

// Define the function for garbage collecting unused entries in the list
void nfapi_crc_indication_garbage_collect(nfapi_crc_indication_list_t *list) {
    // Iterate over the list and remove any entries that have not been updated for a certain period of time
    uint32_t i = 0;
    while (i < list->size) {
        if (list->data[i].last_updated + NFAPI_CRC_INDICATION_GARBAGE_COLLECTION_PERIOD < time(NULL)) {
            // Remove the unused entry from the list
            for (uint32_t j = i; j < list->size - 1; j++) {
                list->data[j] = list->data[j + 1];
            }
            list->size--;
        } else {
            i++;
        }
    }
}

// Define the function for handling external data source updates
void nfapi_crc_indication_handle_update(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crc_flag) {
    // Check if the list is empty before updating an existing entry
    if (list->size == 0) {
        return;
    }

    // Find the index of the entry with the provided RNTI in the list
    uint32_t i = nfapi_crc_indication_find(list, rnti);
    if (i < list->size) {
        // Update the CRC flag for the found entry
        list->data[i].crc_flag = crc_flag;
    } else {
        // If the entry is not found, add a new one with the provided RNTI and CRC flag
        nfapi_crc_indication_add(list, rx_ue_information_tag, rnti, crc_flag);
    }
}

// Define the function for handling external data source updates in a thread-safe manner
void nfapi_crc_indication_handle_update_threadsafe(nfapi_crc_indication_list_t *list, uint16_t rx_ue_information_tag, uint32_t rnti, bool crc_flag) {
    // Lock the list to prevent concurrent access from multiple threads
    pthread_mutex_lock(&list->mutex);

    // Handle the update in a thread-safe manner
    nfapi_crc_indication_handle_update(list, rx_ue_information_tag, rnti, crc_flag);

    // Unlock the list to allow other threads to access it again
    pthread_mutex_unlock(&list->mutex);
}
