    record_array[i].int_value = int_array + i;
  }

  // Verify that each pointer is pointing to a valid segment before setting the int value
  for (int i = 0; i < max_frames; i++) {
    assert(record_array[i].long_ptr >= long_array && record_array[i].long_ptr <= long_array + max_frames);
    assert(record_array[i].int_value >= int_array && record_array[i].int_value <= int_array + max_symbols);
  }

  // Set the int values randomly within the given range
