// Union-Find data structure for disjoint pairs in an integer array
class DisjointSet {
public:
    explicit DisjointSet(int num_elements) : parent_(num_elements), rank_(num_elements, 0) {}

    // Return the root of the set containing element i
    int find(int i) {
        if (parent_[i] != i) {
            parent_[i] = find(parent_[i]);
        }
        return parent_[i];
    }

    // Merge sets containing elements p and q
    void union_(int p, int q) {
        int root_p = find(p);
        int root_q = find(q);
        if (root_p == root_q) {
            return;
        }
        if (rank_[root_p] < rank_[root_q]) {
            parent_[root_p] = root_q;
        } else {
            parent_[root_q] = root_p;
            if (rank_[root_p] == rank_[root_q]) {
                rank_[root_p]++;
            }
        }
    }

private:
    vector<int> parent_;
    vector<uint8_t> rank_;
};

