        buffer_.resize(new_size);
    }

    // Resize the list as needed for performance optimization
    void optimize() {
        int target_size = size_ * 1.5;
        if (target_size > buffer_.capacity()) {
            resize(target_size);
        }
    }

    // Validate the CRC flag for each structure after population, correcting invalid flags or aborting the operation if necessary
    void validateCrc() {
