#include <sys/types.h>
#include <sys/mman.h>

// Define the task structure
typedef struct {
    char* description;
    int priority;
    long start_ts, end_ts;
} Task;

// Define the red-black tree for efficient insertion and deletion based on priority
struct rb_root root = RB_ROOT;

// Function to allocate memory for a task structure
Task* alloc_task() {
    Task* task = malloc(sizeof(Task));
    if (task == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    return task;
}

// Function to free memory for a task structure
void free_task(Task* task) {
    free(task->description);
    free(task);
}

// Function to dynamically resize the collection of tasks
void resize_collection(size_t new_size) {
    size_t old_size = root.rb_nodes;
    if (new_size <= old_size) {
        return;
    }
    // Reallocate memory for the red-black tree
    struct rb_node** temp_root = realloc(root.rb_nodes, new_size * sizeof(struct rb_node*));
    if (temp_root == NULL) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    root.rb_nodes = temp_root;
    // Reallocate memory for each task structure
    Task** temp_tasks = realloc(root->tasks, new_size * sizeof(Task*));
    if (temp_tasks == NULL) {
        perror("Memory reallocation failed");
        exit(EXIT_FAILURE);
    }
    root->tasks = temp_tasks;
}

// Function to fill the priority levels with random values, unless provided by an external data source
void fill_priorities() {
    srand(time(NULL));
    for (int i = 0; i < root.rb_nodes; ++i) {
        if (root->tasks[i]->priority == 0) {
            int priority = rand() % 10 + 1;
            root->tasks[i]->priority = priority;
        }
    }
}

// Function to initialize a pointer to a long segment within a dynamically allocated array of at least 10,000 elements
void init_segment(Task* task) {
    size_t total_size = 10000 * sizeof(long);
    void* seg = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (seg == NULL) {
        perror("Memory mapping failed");
        exit(EXIT_FAILURE);
    }
    task->segment = seg;
}

// Function to validate pointers before use and verify the external data source's reliability
void validate_pointers() {
    for (int i = 0; i < root.rb_nodes; ++i) {
        if (root->tasks[i]->description == NULL || root->tasks[i]->priority == 0 || root->tasks[i]->segment == NULL) {
            perror("Invalid pointer");
            exit(EXIT_FAILURE);
        }
    }
}

// Function to minimize memory allocations and deallocations to prevent fragmentation
void minimize_allocations() {
    // Allocate memory for the red-black tree and tasks structures in one go
    root = calloc(root.rb_nodes, sizeof(struct rb_node));
    Task** tasks = calloc(root->tasks, sizeof(Task*));
    if (root == NULL || tasks == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
}

// Function to log the state of the task collection to a file periodically
void log_state() {
    FILE* log = fopen("log.txt", "a+");
    if (log == NULL) {
        perror("File opening failed");
        exit(EXIT_FAILURE);
    }
    for (int i = 0; i < root.rb_nodes; ++i) {
        fprintf(log, "%d %s %d %ld %ld\n", i, root->tasks[i]->description, root->tasks[i]->priority, root->tasks[i]->start_ts, root->tasks[i]->end_ts);
    }
    fclose(log);
}

// Function to print the total number of successfully initialized tasks, their descriptions, priorities, and timestamps
void print_tasks() {
    printf("Tasks: %d\n", root.rb_nodes);
    for (int i = 0; i < root.rb_nodes; ++i) {
        printf("%d - %s - %d - %ld - %ld\n", i, root->tasks[i]->description, root->tasks[i]->priority, root->tasks[i]->start_ts, root->tasks[i]->end_ts);
    }
}

// Function to free all allocated memory upon exit
void cleanup() {
    for (int i = 0; i < root.rb_nodes; ++i) {
        if (root->tasks[i]->description != NULL) {
            free(root->tasks[i]->description);
        }
        if (root->tasks[i]->segment != NULL) {
            munmap(root->tasks[i]->segment, 10000 * sizeof(long));
        }
    }
    free(root.rb_nodes);
    free(root->tasks);
}

int main() {
    // Allocate memory for the red-black tree and tasks structures
    root = calloc(5000, sizeof(struct rb_node));
    Task** tasks = calloc(5000 * sizeof(Task*));
    if (root == NULL || tasks == NULL) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }

    // Fill the priority levels with random values, unless provided by an external data source
    fill_priorities();

    // Initialize a pointer to a long segment within a dynamically allocated array of at least 10,000 elements for each task structure
    for (int i = 0; i < root.rb_nodes; ++i) {
        init_segment(root->tasks[i]);
    }

    // Validate pointers before use and verify the external data source's reliability
    validate_pointers();

    // Minimize memory allocations and deallocations to prevent fragmentation
    minimize_allocations();

    // Log the state of the task collection to a file periodically
    log_state();

    // Print the total number of successfully initialized tasks, their descriptions, priorities, and timestamps
    print_tasks();

    // Free all allocated memory upon exit
    cleanup();

    return 0;
}
