#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>
#include <assert.h>

// Define the struct item
struct item {
    float value;
    char* string;
    double* double_ptr;
};

// Define the hash table for storing the mapping between index and string
typedef struct {
    int capacity;
    int size;
    struct item** items;
} hash_table;

// Function to create a new hash table
hash_table* create_hash_table(int capacity) {
    hash_table* ht = malloc(sizeof(hash_table));
    if (!ht) {
        return NULL;
    }
    ht->capacity = capacity;
    ht->size = 0;
    ht->items = malloc(sizeof(struct item*) * capacity);
    if (!ht->items) {
        free(ht);
        return NULL;
    }
    memset(ht->items, 0, sizeof(struct item*) * capacity);
    return ht;
}

// Function to insert a new item into the hash table
int insert_item(hash_table* ht, int index, struct item* item) {
    if (index < 0 || index >= ht->capacity) {
        return -1;
    }
    if (!item) {
        return -2;
    }
    ht->items[index] = item;
    ht->size++;
    return 0;
}

// Function to retrieve an item from the hash table by its index
struct item* get_item(hash_table* ht, int index) {
    if (index < 0 || index >= ht->capacity) {
        return NULL;
    }
    struct item* item = ht->items[index];
    if (!item) {
        return NULL;
    }
    return item;
}

// Function to delete an item from the hash table by its index
int delete_item(hash_table* ht, int index) {
    if (index < 0 || index >= ht->capacity) {
        return -1;
    }
    struct item* item = ht->items[index];
    if (!item) {
        return -2;
    }
    free(item);
    ht->items[index] = NULL;
    ht->size--;
    return 0;
}

// Function to populate the hash table with random values for each item
int populate_hash_table(hash_table* ht, int num_items, float min, float max) {
    if (!ht || num_items <= 0 || min > max) {
        return -1;
    }
    for (int i = 0; i < num_items; i++) {
        struct item* item = malloc(sizeof(struct item));
        if (!item) {
            return -2;
        }
        item->value = min + (rand() / (float)RAND_MAX) * (max - min);
        char* string = malloc(10 * sizeof(char));
        sprintf(string, "Item %d", i);
        item->string = string;
        item->double_ptr = NULL; // Initialize the double pointer to null
        insert_item(ht, i, item);
    }
    return 0;
}

// Function to retrieve an item from the hash table by its string
struct item* get_item_by_string(hash_table* ht, char* string) {
    if (!ht || !string) {
        return NULL;
    }
    for (int i = 0; i < ht->capacity; i++) {
        struct item* item = ht->items[i];
        if (item && strcmp(item->string, string) == 0) {
            return item;
        }
    }
    return NULL;
}

// Function to delete an item from the hash table by its string
int delete_item_by_string(hash_table* ht, char* string) {
    if (!ht || !string) {
        return -1;
    }
    for (int i = 0; i < ht->capacity; i++) {
        struct item* item = ht->items[i];
        if (item && strcmp(item->string, string) == 0) {
            delete_item(ht, i);
            return 0;
        }
    }
    return -2;
}

// Function to free the memory of the hash table and its items
void free_hash_table(hash_table* ht) {
    if (!ht) {
        return;
    }
    for (int i = 0; i < ht->capacity; i++) {
        struct item* item = ht->items[i];
        if (item) {
            free(item);
        }
    }
    free(ht->items);
    free(ht);
}
