#include <string.h>
#include <pthread.h>
#include <assert.h>

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    size_t payload_size;
} NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T;

typedef struct {
    int min_rnti;
    int max_rnti;
    int *valid_rnti_list;
    size_t valid_rnti_count;
} RNTI_RANGE_T;

typedef struct {
    pthread_mutex_t lock;
    NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T *pdu_list;
    size_t pdu_count;
} NFAPI_CRC_INDICATION_LIST_T;

typedef struct {
    RNTI_RANGE_T *rnti_range_list;
    size_t rnti_range_count;
} NFAPI_CRC_INDICATION_CONFIG_T;

void nfapi_crc_indication_init(NFAPI_CRC_INDICATION_LIST_T *list, const NFAPI_CRC_INDICATION_CONFIG_T *config) {
    list->pdu_count = 0;
    list->pdu_list = NULL;
    list->lock = PTHREAD_MUTEX_INITIALIZER;
    memcpy(&list->rnti_range_list, config->rnti_range_list, sizeof(RNTI_RANGE_T) * config->rnti_range_count);
}

void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T *pdu_with_payload = (NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T));
    pdu_with_payload->pdu = pdu;
    pdu_with_payload->payload_size = 0;
    list->pdu_list = realloc(list->pdu_list, sizeof(NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T) * (list->pdu_count + 1));
    list->pdu_list[list->pdu_count++] = pdu_with_payload;
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_indication_remove(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    pthread_mutex_lock(&list->lock);
    free(list->pdu_list[index]->payload_size);
    list->pdu_count--;
    memmove(&list->pdu_list[index], &list->pdu_list[index + 1], sizeof(NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T) * (list->pdu_count - index));
    pthread_mutex_unlock(&list->lock);
}

void nfapi_crc_indication_validate(NFAPI_CRC_INDICATION_LIST_T *list, int rnti) {
    bool valid = false;
    for (int i = 0; i < list->rnti_range_count; i++) {
        if (rnti >= list->rnti_range_list[i].min_rnti && rnti <= list->rnti_range_list[i].max_rnti) {
            valid = true;
            break;
        }
    }
    if (!valid) {
        printf("Rejected invalid RNTI: %d\n", rnti);
    }
}

void nfapi_crc_indication_process(NFAPI_CRC_INDICATION_LIST_T *list, int index) {
    NFAPI_CRC_INDICATION_PDU_WITH_PAYLOAD_T *pdu_with_payload = list->pdu_list[index];
    NFAPI_CRC_INDICATION_PDU_T *pdu = pdu_with_payload->pdu;
    if (nfapi_crc_indication_validate(list, pdu->RX_UE_INFORMATION.rnti)) {
        // Perform CRC validation and other processing tasks
        // ...
        printf("Processed PDU with RNTI: %d\n", pdu->RX_UE_INFORMATION.rnti);
    } else {
        nfapi_crc_indication_remove(list, index);
    }
}

void *background_worker_thread(void *args) {
    NFAPI_CRC_INDICATION_LIST_T *list = (NFAPI_CRC_INDICATION_LIST_T *)args;
    while (1) {
        for (int i = 0; i < list->pdu_count; i++) {
            nfapi_crc_indication_process(list, i);
        }
        sleep(10); // Periodically check the PDUs and process them
    }
}

int main() {
    NFAPI_CRC_INDICATION_LIST_T list;
    NFAPI_CRC_INDICATION_PDU_T pdu;
    nfapi_crc_indication_init(&list, 10); // Initialize the list with a capacity of 10 PDUs
    pdu.RX_UE_INFORMATION.rnti = 12345;
    nfapi_crc_indication_add(&list, &pdu);
    background_worker_thread(&list); // Start the background worker thread to process the PDUs
    return 0;
}
```

In this example, we have defined a `NFAPI_CRC_INDICATION_LIST_T` structure to store the received PDUs. We have also defined a `background_worker_thread` function that runs in the background and processes the PDUs periodically. The main thread adds new PDUs to the list using the `nfapi_crc_indication_add` function, and the background worker thread removes processed PDUs from the list using the `nfapi_crc_indication_remove` function. The `nfapi_crc_indication_validate` function validates whether the RNTI of a received PDU is within the configured ranges, and performs CRC validation and other processing tasks if the RNTI is valid.

Note that this is just an example code snippet, and you may need to modify it to fit your specific use case. Additionally, you should ensure that the `background_worker_thread` function is properly synchronized with the main thread to avoid race conditions when accessing the list of PDUs.']

