    // Acquire a read or write lock on the given lock ID
    if (id == 0) {
        while (*lock != 0) {
            // If the lock is already taken, wait until it becomes available
        }
        *lock = 1;
    } else {
        while (*lock != 1) {
            // If the lock is not available, wait until it becomes available
        }
    }
}

void unlock(int* lock) {
    // Release a read or write lock on the given lock ID
    *lock = 0;
}

