    offset_arr[i] = rand() % 100;
  }

  // Allocate memory for key array
  key_arr = (int *)malloc(num_records * sizeof(int));
  assert(key_arr != NULL);

  // Initialize key array with random values within specified range
  for (size_t i = 0; i < num_records; i++) {
    key_arr[i] = rand() % 10000;
  }

  // Allocate memory for label array
  label_arr = (char **)malloc(num_records * sizeof(char *));
  assert(label_arr != NULL);

  // Initialize label array with random strings of length [5, 10]
  for (size_t i = 0; i < num_records; i++) {
    size_t len = rand() % 6 + 5;
    char *label = malloc(len);
    assert(label != NULL);
    for (size_t j = 0; j < len; j++) {
      label[j] = 'a' + (rand() % 26);
    }
    label[len - 1] = '\0';
    label_arr[i] = label;
  }
}

