function updateClinicStatus($clinicId, $status, $lastModifiedIp, $lastModifiedDate) {
  // Concurrency handling: use optimistic locking to ensure data consistency
  $lock = $this->getLock($clinicId);
  if ($lock === null) {
    return 'Unable to acquire lock for clinic ID ' . $clinicId;
  }

  // Logging: track updates and changes made to the database
  $this->logUpdate($clinicId, $status, $lastModifiedIp, $lastModifiedDate);

  try {
