    $this->releaseLock($lock);
  }

  return 'Clinic status updated successfully';
}

// Implement concurrency handling using optimistic locking
private function getLock($clinicId) {
  $lock = new Lock();
  if ($lock->acquire('clinic-' . $clinicId, self::LOCK_TIMEOUT)) {
    return $lock;
  } else {
    return null;
  }
}

private function releaseLock(Lock $lock) {
  $lock->release();
