**Coding Task: Scalable and Thread-Safe Linked List Implementation for Managing UE Contexts**
```c
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <errno.h>

// Structure to represent a node in the linked list of UE contexts
typedef struct ue_context {
    int imsi;
    int rnti;
    int pdu_session_id;
    struct ue_context* next;
} ue_context_t;

// Function to generate a random integer between 1 and 9999
int generate_random_imsi() {
    return (rand() % 9999) + 1;
}

// Thread-safe function to add a new node to the linked list of UE contexts
void* add_ue_context(ue_context_t** head, int imsi, int rnti, int pdu_session_id) {
    ue_context_t* new_node = malloc(sizeof(ue_context_t));
    if (!new_node) {
        return NULL;
    }

    // Generate a unique IMSI for the new node
    int unique_imsi = generate_random_imsi();
    while (unique_imsi == 0 || lookup_ue_context(head, unique_imsi)) {
        unique_imsi = generate_random_imsi();
    }

    // Populate the new node with the provided values and add it to the linked list
    new_node->imsi = imsi;
    new_node->rnti = rnti;
    new_node->pdu_session_id = pdu_session_id;
    new_node->next = *head;
    *head = new_node;

    return NULL;
}

// Thread-safe function to lookup a node in the linked list of UE contexts by IMSI
ue_context_t* lookup_ue_context(ue_context_t** head, int imsi) {
    ue_context_t* current = *head;
    while (current != NULL) {
        if (current->imsi == imsi) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

// Thread-safe function to remove a node from the linked list of UE contexts by IMSI
void* remove_ue_context(ue_context_t** head, int imsi) {
    ue_context_t* current = *head;
    ue_context_t* previous = NULL;
    while (current != NULL && current->imsi != imsi) {
        previous = current;
        current = current->next;
    }

    if (current == NULL) {
        return NULL;
    }

    if (previous == NULL) {
        *head = current->next;
    } else {
        previous->next = current->next;
    }

    free(current);
    return NULL;
}

// Thread-safe function to iterate over the linked list of UE contexts and perform an action on each node
void* iterate_ue_contexts(ue_context_t** head, void (*action)(ue_context_t*)) {
    ue_context_t* current = *head;
    while (current != NULL) {
        action(current);
        current = current->next;
    }
    return NULL;
}
