// Define the data structure to store the records
typedef struct {
    uint64_t offset;
    int key;
} record_t;

// Define the hash table implementation (separate chaining or open addressing)
#define HASH_IMPLEMENTATION 0 // separate chaining

// Define the hash function for the records
uint64_t hash(record_t *rec) {
    uint64_t h = rec->key;
    return h % 100;
}

// Define the comparator function for the records
int compare(const void *a, const void *b) {
    record_t *ra = (record_t *)a;
    record_t *rb = (record_t *)b;
    return ra->key - rb->key;
}

// Define the data structure to store the hash table
typedef struct {
    record_t **buckets;
    int size;
    int count;
} hash_table_t;

// Function to initialize the hash table
hash_table_t *init_hash_table(int initial_size) {
    // Allocate memory for the buckets
    hash_table_t *ht = (hash_table_t *)malloc(sizeof(hash_table_t));
    if (!ht) {
        printf("Error: failed to allocate memory for the hash table\n");
        return NULL;
    }

    // Initialize the buckets and size
    ht->buckets = (record_t **)malloc(initial_size * sizeof(record_t *));
    if (!ht->buckets) {
        printf("Error: failed to allocate memory for the buckets\n");
        free(ht);
        return NULL;
    }
    ht->size = initial_size;
    ht->count = 0;

    // Initialize the buckets with NULL pointers
    int i;
    for (i = 0; i < initial_size; i++) {
        ht->buckets[i] = NULL;
    }

    return ht;
}

// Function to insert a record into the hash table
int insert(hash_table_t *ht, int key, uint64_t offset) {
    // Check if the table needs to be resized
    if (ht->count >= ht->size) {
        resize_hash_table(ht);
    }

    // Calculate the hash value for the record
    uint64_t hash_value = hash(&(record_t){key, offset});

    // Find the bucket index
    int bucket_index = hash_value % ht->size;

    // Insert the record into the bucket
    if (!ht->buckets[bucket_index]) {
        // Allocate memory for the record
        ht->buckets[bucket_index] = (record_t *)malloc(sizeof(record_t));
        if (!ht->buckets[bucket_index]) {
            printf("Error: failed to allocate memory for the record\n");
            return -1;
        }
        ht->count++;
    }
    else {
        // Update the existing record
        record_t *rec = ht->buckets[bucket_index];
        rec->key = key;
        rec->offset = offset;
    }

    return 0;
}

// Function to delete a record from the hash table
int delete(hash_table_t *ht, int key) {
    // Calculate the hash value for the record
    uint64_t hash_value = hash(&(record_t){key});

    // Find the bucket index
    int bucket_index = hash_value % ht->size;

    // Check if the bucket exists and contains the record
    if (!ht->buckets[bucket_index]) {
        return -1;
    }
    else if (ht->buckets[bucket_index]->key == key) {
        free(ht->buckets[bucket_index]);
        ht->count--;
        return 0;
    }

    // Check if the record is in a linked list
    record_t *prev = NULL;
    record_t *rec = ht->buckets[bucket_index];
    while (rec) {
        if (rec->key == key) {
            break;
        }
        prev = rec;
        rec = rec->next;
    }

    // Check if the record was found
    if (!rec) {
        return -1;
    }

    // Remove the record from the linked list
    if (prev) {
        prev->next = rec->next;
    }
    else {
        ht->buckets[bucket_index] = rec->next;
    }

    free(rec);
    ht->count--;

    return 0;
}

// Function to lookup a record in the hash table
int lookup(hash_table_t *ht, int key) {
    // Calculate the hash value for the record
    uint64_t hash_value = hash(&(record_t){key});

    // Find the bucket index
    int bucket_index = hash_value % ht->size;

    // Check if the bucket exists and contains the record
    if (!ht->buckets[bucket_index]) {
        return -1;
    }
    else if (ht->buckets[bucket_index]->key == key) {
        return 0;
    }

    // Check if the record is in a linked list
    record_t *rec = ht->buckets[bucket_index];
    while (rec) {
        if (rec->key == key) {
            break;
        }
        rec = rec->next;
    }

    // Check if the record was found
    if (!rec) {
        return -1;
    }

    return 0;
}

// Function to resize the hash table
int resize_hash_table(hash_table_t *ht) {
    // Create a new hash table with twice the size of the current one
    int new_size = ht->size * 2;
    hash_table_t *new_ht = init_hash_table(new_size);
    if (!new_ht) {
        printf("Error: failed to allocate memory for the new hash table\n");
        return -1;
    }

    // Copy all the records from the current hash table to the new one
    int i;
    for (i = 0; i < ht->size; i++) {
        record_t *rec = ht->buckets[i];
        while (rec) {
            insert(new_ht, rec->key, rec->offset);
            rec = rec->next;
        }
    }

    // Replace the current hash table with the new one
    free(ht->buckets);
    ht->size = new_ht->size;
    ht->count = new_ht->count;
    ht->buckets = new_ht->buckets;

    return 0;
}

// Function to print the hash table
void print_hash_table(hash_table_t *ht) {
    int i;
    for (i = 0; i < ht->size; i++) {
        record_t *rec = ht->buckets[i];
        while (rec) {
            printf("%d -> %lu\n", rec->key, rec->offset);
            rec = rec->next;
        }
    }
}
```

This implementation uses a linked list for collision resolution. It has the advantage of being able to handle more than 1 million records in a hash table with a size of 5000, but it also has the disadvantage of having slower insertion and deletion times compared to the array-based implementation.

In this solution, we used an extra variable called `new_size` to store the new size of the hash table when resizing is required. We then created a new hash table with that size using `init_hash_table()` function and copied all records from the current hash table to the new one using `insert()` function. Finally, we replaced the current hash table with the new one using `free()` function.

