#include <iostream>
#include <vector>
#include <map>
#include <string>
#include <algorithm>
#include <cmath>

using namespace std;

// Define a struct for network connections that contains unique identifier, timestamp, and list of packet sizes
struct NetworkConnection {
    string id;
    unsigned long long timestamp;
    vector<unsigned int> packet_sizes;
};

// Define a map to store the network connections with their corresponding unique identifiers as keys
map<string, NetworkConnection> network_connections;

// Define a function to generate random packet sizes based on predefined bandwidth limit
vector<unsigned int> generateRandomPacketSizes(unsigned long long total_payload_size) {
    // Calculate the maximum number of packets that can be generated based on the total payload size and bandwidth limit
    unsigned int max_num_packets = ceil((double)total_payload_size / BANDWIDTH_LIMIT);

    // Initialize a vector to store the packet sizes
    vector<unsigned int> packet_sizes(max_num_packets, 0);

    // Generate random packet sizes that are within the bandwidth limit for each packet
    for (unsigned int i = 0; i < max_num_packets; i++) {
        unsigned int packet_size = rand() % BANDWIDTH_LIMIT + 1;
        packet_sizes[i] = packet_size;
        total_payload_size -= packet_size;
    }

    return packet_sizes;
}

// Define a function to update the network connections with new data from simulated network traffic
void updateNetworkConnections(const vector<unsigned int>& packet_sizes) {
    // Iterate through each connection in the map and add the new packet sizes to their corresponding list of packet sizes
    for (auto& [id, connection]: network_connections) {
        for (auto packet_size: packet_sizes) {
            connection.packet_sizes.push_back(packet_size);
        }
    }
}

// Define a function to handle new connections and add them to the map of network connections
void handleNewConnections(const string& id, const unsigned long long timestamp) {
    // Create a new NetworkConnection object with the unique identifier and timestamp
    NetworkConnection connection;
    connection.id = id;
    connection.timestamp = timestamp;

    // Add the new connection to the map of network connections
    network_connections[id] = connection;
}

// Define a function to handle lost connections and remove them from the map of network connections
void handleLostConnections(const string& id) {
    // Remove the connection with the given unique identifier from the map of network connections
    network_connections.erase(id);
}

int main() {
    // Initialize a vector to store the packet sizes generated based on simulated network traffic
    vector<unsigned int> packet_sizes;

    // Initialize a string variable to store the unique identifier of the new connection
    string id = "";

    // Initialize an unsigned long long variable to store the timestamp of the new connection
    unsigned long long timestamp = 0;

    // Read data from the simulation and update the network connections accordingly
    while (true) {
        // Generate random packet sizes based on predefined bandwidth limit
        packet_sizes = generateRandomPacketSizes(TOTAL_PAYLOAD_SIZE);

        // Update the network connections with new data from simulated network traffic
        updateNetworkConnections(packet_sizes);

        // Handle new connections by adding them to the map of network connections
        cin >> id;
        cin >> timestamp;
        handleNewConnections(id, timestamp);

        // Handle lost connections by removing them from the map of network connections
        cin >> id;
        handleLostConnections(id);
    }

    return 0;
}

// Define constants for the predefined bandwidth limit and total payload size
const unsigned int BANDWIDTH_LIMIT = 1024 * 1024; // 1 MB
const unsigned long long TOTAL_PAYLOAD_SIZE = 1024 * 1024 * 1024; // 1 GB
