// Struct definition for item
typedef struct {
    char* name;
    int quantity;
    float price;
} Item;

// Function to read and decompress archive files
void readArchiveFiles(char** fileNames, int numFiles) {
    // Allocate memory for the items array
    Item* items = malloc(sizeof(Item) * numItems);

    // Initialize the items array with default values
    for (int i = 0; i < numItems; i++) {
        items[i].name = NULL;
        items[i].quantity = 0;
        items[i].price = 0.0f;
    }

    // Loop through each file and decompress it
    for (int i = 0; i < numFiles; i++) {
        FILE* file = fopen(fileNames[i], "rb");
        if (!file) {
            printf("Error: failed to open file %s\n", fileNames[i]);
            continue;
        }

        // Decompress the file using zlib
        int ret = uncompress(items, sizeof(Item), file);
        if (ret != Z_OK) {
            printf("Error: decompression failed with code %d\n", ret);
            continue;
        }

        // Close the file
        fclose(file);
    }
}

// Function to apply a discount to the price based on a threshold
float calculateDiscountedPrice(Item* item, float threshold) {
    if (item->price < threshold) {
        return item->price;
    } else {
        return item->price - (item->price * 0.1f);
    }
}

// Function to filter out items with a low quantity and calculate the total discounted cost
float calculateTotalDiscountedCost(Item* items, int numItems, float threshold) {
    float total = 0.0f;

    // Loop through each item and apply the discount
    for (int i = 0; i < numItems; i++) {
        if (items[i].quantity >= threshold) {
            total += calculateDiscountedPrice(&items[i], threshold);
        }
    }

    return total;
}

// Function to handle errors during memory allocation and file reading
void handleErrors(char* errorMessage, int lineNumber) {
    printf("Error: %s at line %d\n", errorMessage, lineNumber);
    exit(1);
}

int main() {
    // Array of file names to read from
    char* fileNames[] = {"file1.zip", "file2.gz", "file3.xz"};

    // Number of files to read from
    int numFiles = sizeof(fileNames) / sizeof(char*);

    // Threshold for discount calculation
    float threshold = 100.0f;

    // Read and decompress the archive files
    readArchiveFiles(fileNames, numFiles);

    // Allocate memory for the items array
    Item* items = malloc(sizeof(Item) * numItems);

    // Initialize the items array with default values
    for (int i = 0; i < numItems; i++) {
        items[i].name = NULL;
        items[i].quantity = 0;
        items[i].price = 0.0f;
    }

    // Loop through each file and decompress it
    for (int i = 0; i < numFiles; i++) {
        FILE* file = fopen(fileNames[i], "rb");
        if (!file) {
            printf("Error: failed to open file %s\n", fileNames[i]);
            continue;
        }

        // Decompress the file using zlib
        int ret = uncompress(items, sizeof(Item), file);
        if (ret != Z_OK) {
            printf("Error: decompression failed with code %d\n", ret);
            continue;
        }

        // Close the file
        fclose(file);
    }

    // Apply the discount to the price and filter out items with low quantity
    float total = calculateTotalDiscountedCost(items, numItems, threshold);

    // Print the total discounted cost
    printf("Total discounted cost: $%.2f\n", total);

    return 0;
}
