// Define a function to dynamically create and populate the list of structures
NFAPI_CRC_INDICATION_LIST_T* dynamic_create_populate_list(int num_entries) {
    // Check if the number of entries is valid
    if (num_entries < 0 || num_entries > MAX_ENTRIES) {
        return NULL;
    }

    // Initialize the list
    NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (list == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    list->head = NULL;
    list->tail = NULL;

    // Populate the list with random values
    for (int i = 0; i < num_entries; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Memory allocation failed\n");
            return NULL;
        }

        // Set the values for the structure fields
        pdu->rx_ue_information_tag = rand() % 256;
        pdu->rnti = rand() % 10000;
        pdu->crc_indication_rel8_tag = rand() % 100;
        pdu->crcflag = rand() % 2;

        // Add the structure to the list
        if (list->head == NULL) {
            list->head = pdu;
            list->tail = pdu;
        } else {
            NFAPI_CRC_INDICATION_LIST_NODE_T *node = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_NODE_T));
            if (node == NULL) {
                printf("Memory allocation failed\n");
                return NULL;
            }
            node->pdu = pdu;
            node->next = NULL;
            list->tail->next = node;
            list->tail = node;
        }
    }

    // Return the populated list
    return list;
}

// Define a function to free the memory allocated for the list of structures
void dynamic_free_list(NFAPI_CRC_INDICATION_LIST_T *list) {
    if (list == NULL) {
        return;
    }

    // Free the memory for each structure in the list
    NFAPI_CRC_INDICATION_LIST_NODE_T *node = list->head;
    while (node != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = node->pdu;
        free(pdu);
        node = node->next;
    }

    // Free the memory for the list itself
    free(list);
}

int main() {
    // Create and populate the list of structures dynamically
    NFAPI_CRC_INDICATION_LIST_T *list = dynamic_create_populate_list(10);
    if (list == NULL) {
        printf("List creation failed\n");
        return 1;
    }

    // Print the values of each structure field in the list
    NFAPI_CRC_INDICATION_LIST_NODE_T *node = list->head;
    while (node != NULL) {
