        printf("rnti: %d\n", pdu->rnti);
        printf("crc_indication_rel8_tag: %d\n", pdu->crc_indication_rel8_tag);
        printf("crcflag: %d\n", pdu->crcflag);
        node = node->next;
    }

    // Free the memory allocated for the list of structures
    dynamic_free_list(list);

    return 0;
}
