#define MAX_ITEMS 10000
#define MAX_TASKS 256
#define MIN_PRIORITY 1
#define MAX_PRIORITY 3
#define DATA_SIZE 1024

typedef struct {
    int task_id;
    int priority;
    char data[DATA_SIZE];
} QUEUE_ITEM;

struct queue {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    size_t size;
    size_t capacity;
    QUEUE_ITEM *items;
};

void init_queue(struct queue *q, size_t capacity) {
    q->capacity = capacity;
    q->size = 0;
    q->items = (QUEUE_ITEM *)malloc(sizeof(QUEUE_ITEM) * capacity);
    pthread_mutex_init(&q->mutex, NULL);
    pthread_cond_init(&q->cond, NULL);
}

void destroy_queue(struct queue *q) {
    free(q->items);
    q->size = 0;
    pthread_mutex_destroy(&q->mutex);
    pthread_cond_destroy(&q->cond);
}

int enqueue(struct queue *q, QUEUE_ITEM item) {
    int ret = 0;
    pthread_mutex_lock(&q->mutex);
    while (q->size == q->capacity) {
        if (!pthread_cond_wait(&q->cond, &q->mutex)) {
            ret = -1;
            break;
        }
    }
    if (ret != -1) {
        q->items[q->size++] = item;
        pthread_cond_broadcast(&q->cond);
    }
    pthread_mutex_unlock(&q->mutex);
    return ret;
}

QUEUE_ITEM dequeue(struct queue *q) {
    QUEUE_ITEM item;
    pthread_mutex_lock(&q->mutex);
    while (q->size == 0) {
        if (!pthread_cond_wait(&q->cond, &q->mutex)) {
            item = NULL;
            break;
        }
    }
    if (item != NULL) {
        q->items[--q->size] = item;
        pthread_cond_broadcast(&q->cond);
    }
    pthread_mutex_unlock(&q->mutex);
    return item;
}
```
