        return;
    }

    // Define a buffer for reading the input file in chunks
    char buffer[1024];

    // Initialize a counter for the number of valid elements processed
    int valid_elements = 0;

    // Loop until EOF is reached
    while (!feof(fp)) {
        // Read a chunk of data from the input file into the buffer
        size_t bytes_read = fread(buffer, sizeof(char), sizeof(buffer), fp);
        if (bytes_read == 0) {
            // Check for errors in reading from the file
