                fclose(fp);
                return;
            }
        } else {
            // Process each element in the chunk of data
            for (int i = 0; i < bytes_read; i += sizeof(struct Element)) {
                struct Element* element = (struct Element*) (buffer + i);
                if (element->float_data == 0 && element->integer_data == 0 && element->character_data == 0) {
                    // Skip empty records
                    continue;
                } else if (element->nested_data != NULL) {
                    // Handle nested structures
                    // ...
                }
                valid_elements++;
            }
        }
    }

    // Close the input file
    fclose(fp);

    // Print a report of the number of valid elements processed
