// Reader-writer lock for concurrent access and modifications
pthread_rwlock_t rwlock;

// Initialize the dynamic array of LTE_PHY_RX_FRAME structures
struct LTE_PHY_RX_FRAME *array = NULL;
size_t capacity = 0; // Current capacity of the array

// Lock for serializing access to the array
pthread_mutex_t mutex;

void init() {
    // Initialize reader-writer lock and mutex
    pthread_rwlock_init(&rwlock, NULL);
    pthread_mutex_init(&mutex, NULL);
}

// Insert a new frame into the array
void insert(struct LTE_PHY_RX_FRAME *frame) {
    // Acquire write lock on rwlock
    pthread_rwlock_wrlock(&rwlock);

    // Check if the capacity of the array has been exceeded
    if (capacity == 0 || size(array) == capacity) {
        // Double the capacity of the array
        capacity *= 2;
        struct LTE_PHY_RX_FRAME *new_array = realloc(array, sizeof(struct LTE_PHY_RX_FRAME) * capacity);
        if (new_array == NULL) {
            // Reallocation failed, exit with error
            perror("Error: Reallocation of dynamic array failed");
            pthread_rwlock_unlock(&rwlock);
            return;
        } else {
            array = new_array;
        }
    }

    // Insert the frame into the end of the array
    memcpy(array + size(array), frame, sizeof(struct LTE_PHY_RX_FRAME));

    // Release write lock on rwlock
    pthread_rwlock_unlock(&rwlock);
}

// Delete a frame from the array
void delete(size_t index) {
    // Acquire write lock on rwlock
    pthread_rwlock_wrlock(&rwlock);

    // Check if the index is valid
    if (index >= size(array)) {
        // Release write lock on rwlock and exit with error
        perror("Error: Index out of bounds");
        pthread_rwlock_unlock(&rwlock);
        return;
    }

    // Remove the frame from the array
    memmove(array + index, array + index + 1, sizeof(struct LTE_PHY_RX_FRAME) * (size(array) - index));

    // Release write lock on rwlock
    pthread_rwlock_unlock(&rwlock);
}

// Get the number of frames in the array
size_t size() {
    // Acquire read lock on rwlock
    pthread_rwlock_rdlock(&rwlock);

    // Return the number of frames in the array
