    // Acquire read lock on rwlock
    pthread_rwlock_rdlock(&rwlock);

    // Check if the index is valid
    if (index >= size()) {
        // Release read lock on rwlock and exit with error
        perror("Error: Index out of bounds");
        pthread_rwlock_unlock(&rwlock);
        return NULL;
    }

    struct LTE_PHY_RX_FRAME *frame = array + index;

    // Release read lock on rwlock
    pthread_rwlock_unlock(&rwlock);

    return frame;
}

