    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_LIST_NODE {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    struct NFAPI_CRC_INDICATION_LIST_NODE *next;
} NFAPI_CRC_INDICATION_LIST_NODE;

typedef struct NFAPI_CRC_INDICATION_LIST {
    pthread_mutex_t mutex;
    NFAPI_CRC_INDICATION_LIST_NODE *head;
} NFAPI_CRC_INDICATION_LIST;

// Initialize the list with a mutex to ensure thread safety.
void NFAPI_CRC_INDICATION_LIST_init(NFAPI_CRC_INDICATION_LIST *list) {
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    pthread_mutex_init(&list->mutex, &attr);
    list->head = NULL;
}

// Add a new entry to the list. The entry is validated for all fields before being added.
void NFAPI_CRC_INDICATION_LIST_add(NFAPI_CRC_INDICATION_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (pdu->RX_UE_INFORMATION_TAG == 0 || pdu->RNTI == 0 || pdu->CRC_INDICATION_REL8_TAG == 0 || pdu->CRCFLAG == false) {
        // Invalid entry, do not add.
        return;
    }

    NFAPI_CRC_INDICATION_LIST_NODE *node = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_NODE));
    node->pdu = pdu;
    node->next = NULL;

    // Add the new entry to the list.
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = node;
    } else {
        NFAPI_CRC_INDICATION_LIST_NODE *current = list->head;
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = node;
    }
    pthread_mutex_unlock(&list->mutex);
}

// Remove an entry from the list based on its RNTI.
void NFAPI_CRC_INDICATION_LIST_remove(NFAPI_CRC_INDICATION_LIST *list, int RNTI) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        // List is empty.
        return;
    }

    NFAPI_CRC_INDICATION_LIST_NODE *current = list->head;
    while (current != NULL) {
        if (current->pdu->RNTI == RNTI) {
            // Found the entry to remove.
            if (current == list->head) {
                list->head = current->next;
            } else {
                NFAPI_CRC_INDICATION_LIST_NODE *previous = list->head;
                while (previous->next != current) {
                    previous = previous->next;
                }
                previous->next = current->next;
            }
            free(current);
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Update the CRC flag for a specific entry based on its RNTI.
void NFAPI_CRC_INDICATION_LIST_update(NFAPI_CRC_INDICATION_LIST *list, int RNTI, bool CRCFLAG) {
    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        // List is empty.
        return;
    }

    NFAPI_CRC_INDICATION_LIST_NODE *current = list->head;
    while (current != NULL) {
        if (current->pdu->RNTI == RNTI) {
            // Found the entry to update.
            current->pdu->CRCFLAG = CRCFLAG;
            break;
        }
        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Serialize the list to a binary file. The serialized data is organized as follows:
// - First 4 bytes: The length of the entire file (including this header).
// - Next 4 bytes: The number of entries in the list.
// - Followed by NFAPI_CRC_INDICATION_PDU_T structs for each entry, serialized in the same format as above.
void NFAPI_CRC_INDICATION_LIST_serialize(NFAPI_CRC_INDICATION_LIST *list, FILE *file) {
    pthread_mutex_lock(&list->mutex);

    // Write the header with the file length and number of entries.
    int fileLength = 0;
    fwrite(&fileLength, sizeof(int), 1, file);
    int numEntries = 0;
    fwrite(&numEntries, sizeof(int), 1, file);

    // Write each entry in the list.
    NFAPI_CRC_INDICATION_LIST_NODE *current = list->head;
    while (current != NULL) {
        numEntries++;

        // Write the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG.
        fwrite(&(current->pdu->RX_UE_INFORMATION_TAG), sizeof(int), 1, file);
        fwrite(&(current->pdu->RNTI), sizeof(int), 1, file);
        fwrite(&(current->pdu->CRC_INDICATION_REL8_TAG), sizeof(int), 1, file);

        // Write the CRCFLAG.
        fwrite(&(current->pdu->CRCFLAG), sizeof(bool), 1, file);

        current = current->next;
    }

    pthread_mutex_unlock(&list->mutex);
}

// Deserialize the list from a binary file. The serialized data is organized as follows:
// - First 4 bytes: The length of the entire file (including this header).
// - Next 4 bytes: The number of entries in the list.
// - Followed by NFAPI_CRC_INDICATION_PDU_T structs for each entry, serialized in the same format as above.
void NFAPI_CRC_INDICATION_LIST_deserialize(NFAPI_CRC_INDICATION_LIST *list, FILE *file) {
    pthread_mutex_lock(&list->mutex);

    // Read the header with the file length and number of entries.
    int fileLength;
    fread(&fileLength, sizeof(int), 1, file);
    if (fileLength < 0) {
        printf("Invalid file length: %d\n", fileLength);
        return;
    }
    int numEntries = 0;
    fread(&numEntries, sizeof(int), 1, file);
    if (numEntries < 0) {
        printf("Invalid number of entries: %d\n", numEntries);
        return;
    }

    // Read each entry in the list.
