        // Read the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG.
        fread(&(node->pdu->RX_UE_INFORMATION_TAG), sizeof(int), 1, file);
        fread(&(node->pdu->RNTI), sizeof(int), 1, file);
        fread(&(node->pdu->CRC_INDICATION_REL8_TAG), sizeof(int), 1, file);

        // Read the CRCFLAG.
