#include <stdlib.h>
#include <string.h>

// Define the structure for a LTE PHY frame
typedef struct {
    // Header of the LTE PHY frame
    struct {
        unsigned int frame_number;
        unsigned int timestamp;
    } header;

    // Signal strength indicator
    float signal_strength;

    // Variable-length list of symbols in the frame
    struct {
        // Modulation type
        enum { BPSK, QPSK, QAM16, QAM64 } modulation;

        // Phase rotation
        unsigned int phase_rotation;

        // Noise variance estimate
        float noise_variance;
    } symbols[];
} LTE_PHY_RX_FRAME;

// Define the dynamic array of frames
struct {
    LTE_PHY_RX_FRAME **frames;
    size_t num_frames;
    size_t capacity;
} frames;

void init_frames(size_t num_frames, size_t symbols_per_frame) {
    // Validate input parameters
    if (num_frames < 0 || symbols_per_frame < 0) {
        return;
    }

    // Initialize the array of frames with a specified number of frames and symbols per frame
    frames.frames = malloc(sizeof(LTE_PHY_RX_FRAME *) * num_frames);
    if (frames.frames == NULL) {
        return;
    }

    // Initialize each frame with a valid header, signal strength indicator, and a variable-length list of symbols
    for (size_t i = 0; i < num_frames; i++) {
        frames.frames[i] = malloc(sizeof(LTE_PHY_RX_FRAME));
        if (frames.frames[i] == NULL) {
            return;
        }

        // Initialize the header of the frame
        frames.frames[i]->header.frame_number = i + 1;
        frames.frames[i]->header.timestamp = 0;

        // Initialize the signal strength indicator
        frames.frames[i]->signal_strength = -1;

        // Initialize the variable-length list of symbols in the frame
        frames.frames[i]->num_symbols = symbols_per_frame;
        for (size_t j = 0; j < symbols_per_frame; j++) {
            frames.frames[i]->symbols[j].modulation = BPSK;
            frames.frames[i]->symbols[j].phase_rotation = 0;
            frames.frames[i]->symbols[j].noise_variance = -1;
        }
    }

    // Set the number of frames and the capacity of the array
    frames.num_frames = num_frames;
    frames.capacity = 2 * num_frames;
}

void insert_frame(LTE_PHY_RX_FRAME *new_frame) {
    // Check if the frame is valid
    if (new_frame == NULL || new_frame->num_symbols < 0) {
        return;
    }

    // If the array is full, reallocate memory using a doubling strategy
    if (frames.num_frames >= frames.capacity) {
        size_t old_capacity = frames.capacity;
        frames.capacity *= 2;
        LTE_PHY_RX_FRAME **old_frames = frames.frames;
        frames.frames = realloc(frames.frames, sizeof(LTE_PHY_RX_FRAME *) * frames.capacity);
        if (frames.frames == NULL) {
            free(old_frames);
            frames.num_frames = 0;
            return;
        }

        // Copy the old frames to the new memory block
        memcpy(frames.frames, old_frames, sizeof(LTE_PHY_RX_FRAME *) * old_capacity);
        free(old_frames);
    }

    // Add the new frame to the end of the array
    frames.frames[frames.num_frames++] = new_frame;
}

void delete_frame(size_t index) {
    // Check if the index is valid
    if (index >= frames.num_frames) {
        return;
    }

    // Free the symbols in the frame
    for (size_t i = 0; i < frames.frames[index]->num_symbols; i++) {
        free(frames.frames[index]->symbols[i].noise_variance);
    }

    // Free the frame itself
    free(frames.frames[index]);

    // Shift all remaining frames back by one index
    for (size_t i = index; i < frames.num_frames - 1; i++) {
        frames.frames[i] = frames.frames[i + 1];
    }

    // Decrement the number of frames
    frames.num_frames--;
}

void modify_frame(size_t index, float signal_strength) {
    // Check if the index is valid
    if (index >= frames.num_frames) {
        return;
    }

    // Update the signal strength indicator of the frame
    frames.frames[index]->signal_strength = signal_strength;
}

void traverse_frames() {
    // Iterate over all frames and print their headers along with a summary of the symbols in each frame
    for (size_t i = 0; i < frames.num_frames; i++) {
        printf("Frame %zu: ", i);
        printf("%d, ", frames.frames[i]->header.frame_number);
        printf("%d", frames.frames[i]->header.timestamp);
        for (size_t j = 0; j < frames.frames[i]->num_symbols; j++) {
            printf(", ");
            switch (frames.frames[i]->symbols[j].modulation) {
                case BPSK:
                    printf("BPSK");
                    break;
                case QPSK:
                    printf("QPSK");
                    break;
                case 16QAM:
                    printf("16QAM");
                    break;
            }
            printf(", ");
            printf("%d", frames.frames[i]->symbols[j].phase_rotation);
            printf(", ");
            printf("%f", frames.frames[i]->symbols[j].noise_variance);
        }
        printf("\n");
    }
}

int main() {
    init();
    insert_frame(create_frame());
    modify_frame(0, 100.0);
    traverse_frames();
    delete_frame(0);
    return 0;
}']

