// Custom memory pool for better performance under high-memory-pressure conditions
struct MemoryPool {
    size_t size;
    void* ptr;
};

typedef enum Status {
    OK,
    FAIL,
} Status;

typedef struct Record {
    long timestamp;
    int value;
    Status status;
} Record;

Record* initializeRecords(size_t numRecords, size_t offsetArraySize, size_t keyArraySize) {
    // Validate input for the number of records to prevent potential out-of-bounds access during array indexing
    if (numRecords == 0 || offsetArraySize == 0 || keyArraySize == 0) {
        return NULL;
    }

    // Allocate memory for the arrays of offsets, keys, and records
    long* offsets = calloc(offsetArraySize, sizeof(long));
    int* keys = calloc(keyArraySize, sizeof(int));
    Record* records = calloc(numRecords, sizeof(Record));

    // Initialize the arrays with randomly generated values within specified ranges
    srand(time(NULL));
    for (size_t i = 0; i < numRecords; i++) {
        offsets[i] = rand() % offsetArraySize;
        keys[i] = rand() % keyArraySize;
        records[i].timestamp = rand();
        records[i].value = rand();
    }

    // Sort the records based on their timestamps in ascending order
    qsort(records, numRecords, sizeof(Record), compare);

    // Set default status for records that could not be initialized
    for (size_t i = 0; i < offsetArraySize; i++) {
        if (!offsets[i] || !keys[i]) {
            records[i].status = FAIL;
        }
    }

    // Log initialization failures and performance metrics
    for (size_t i = 0; i < offsetArraySize; i++) {
        if (!offsets[i] || !keys[i]) {
            printf("Initialization failed: Offset %lu, Key %d\n", offsets[i], keys[i]);
        }
    }

    // Manage memory deallocation to prevent memory leaks
    free(offsets);
    free(keys);
    return records;
}

int compare(const void* a, const void* b) {
    const Record* recordA = (const Record*)a;
    const Record* recordB = (const Record*)b;
    if (recordA->timestamp < recordB->timestamp) {
        return -1;
    } else if (recordA->timestamp == recordB->timestamp) {
        return 0;
    } else {
        return 1;
    }
}

void deinitializeRecords(Record* records, size_t numRecords) {
    // Free the memory allocated for the arrays of offsets, keys, and records
    free(records);
}']

