  // Check if the specified index is valid
  if (index >= thread_pool->size) return;

  // Destroy the worker thread at the specified index in the pool
  pthread_join(thread_pool->threads[index], NULL);
  memmove(&thread_pool->threads[index], &thread_pool->threads[index + 1], sizeof(pthread_t) * (thread_pool->size - index - 1));
