void *nfapi_crc_indication_thread_pool_perform_job(NFAPI_CRC_INDICATION_THREAD_POOL *thread_pool, void (*job)(void)) {
  // Check if there are any available worker threads in the pool
  for (unsigned int i = 0; i < thread_pool->size; i++) {
    // If a worker thread is available, perform the job on it
    if (pthread_tryjoin_np(thread_pool->threads[i], NULL) == 0) {
      pthread_create(&thread_pool->threads[i], NULL, job, NULL);
      return NULL;
    }
  }
  // If no worker threads are available, create a new one to perform the job
  nfapi_crc_indication_thread_pool_create_thread(thread_pool);
  pthread_create(&thread_pool->threads[thread_pool->size - 1], NULL, job, NULL);
  return NULL;
}

