#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <pthread.h>

// Define data structures
typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    uint16_t PROCESSING_TIME_MS;
    uint16_t RETRANSMISSION_COUNT;
    uint8_t CRC_STATUS;
} CRC_SECONDARY_TAG;

// Define configuration options
#define MAX_MEMORY_ALLOCATION 1024 * 1024 // 1 MB
#define DISABLE_FEATURES false
#define LOGGING_LEVEL 3

// Define logging function
void log(int level, const char* message) {
    if (level <= LOGGING_LEVEL) {
        printf("%s\n", message);
    }
}

// Define error handling functions
void handleError(const char* message) {
    log(3, "ERROR: %s", message);
}

void handleInvalidParameter(const char* parameterName) {
    handleError(parameterName);
}

// Define memory allocation function
void* allocateMemory(size_t size) {
    void* ptr = NULL;
    if (size > 0) {
        ptr = malloc(size);
        if (!ptr) {
            handleError("Failed to allocate memory");
        } else {
            memset(ptr, 0, size);
        }
    }
    return ptr;
}

// Define CRC indication PDU structure creation function
NFAPI_CRC_INDICATION_PDU_T* createCrcIndicationPdu(int N) {
    if (N < 0) {
        handleInvalidParameter("N");
    } else {
        size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
        void* ptr = allocateMemory(size);
        if (ptr) {
            // Initialize CRC indication PDU structures
            for (int i = 0; i < N; ++i) {
                NFAPI_CRC_INDICATION_PDU_T* pdu = &((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i];
                pdu->RX_UE_INFORMATION_TAG = 0xAB;
                pdu->RNTI = i * 100;
                pdu->CRC_INDICATION_REL8_TAG = rand();
            }
        } else {
            handleError("Failed to allocate memory for CRC indication PDUs");
        }
    }
}

// Define secondary data structure creation function
void createSecondaryData(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        size_t size = sizeof(CRC_SECONDARY_TAG);
        void* ptr = allocateMemory(size);
        if (ptr) {
            // Initialize secondary data structure
            CRC_SECONDARY_TAG* secData = (CRC_SECONDARY_TAG*)ptr;
            secData->PROCESSING_TIME_MS = rand() % 1000;
            secData->RETRANSMISSION_COUNT = rand();
            secData->CRC_STATUS = rand() % 2;
        } else {
            handleError("Failed to allocate memory for secondary data");
        }
    }
}

// Define CRC indication PDU structure resizing function
void resizeCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int newSize) {
    if (newSize < 0) {
        handleInvalidParameter("newSize");
    } else {
        size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize;
        void* ptr = allocateMemory(size);
        if (ptr) {
            // Copy old data to new buffer
            memcpy(ptr, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu->length);
        } else {
            handleError("Failed to resize CRC indication PDUs");
        }
    }
}

// Define thread-safe memory allocation function
void* threadSafeAllocateMemory(size_t size) {
    void* ptr = NULL;
    if (size > 0) {
        pthread_mutex_lock(&memoryMutex);
        ptr = allocateMemory(size);
        pthread_mutex_unlock(&memoryMutex);
    }
    return ptr;
}

// Define thread-safe CRC indication PDU structure creation function
NFAPI_CRC_INDICATION_PDU_T* threadSafeCreateCrcIndicationPdu(int N) {
    if (N < 0) {
        handleInvalidParameter("N");
    } else {
        size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
        void* ptr = threadSafeAllocateMemory(size);
        if (ptr) {
            // Initialize CRC indication PDU structures
            for (int i = 0; i < N; ++i) {
                NFAPI_CRC_INDICATION_PDU_T* pdu = &((NFAPI_CRC_INDICATION_PDU_T*)ptr)[i];
                pdu->RX_UE_INFORMATION_TAG = 0xAB;
                pdu->RNTI = i * 100;
                pdu->CRC_INDICATION_REL8_TAG = rand();
            }
        } else {
            handleError("Failed to allocate memory for CRC indication PDUs");
        }
    }
}

// Define thread-safe secondary data structure creation function
void threadSafeCreateSecondaryData(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu) {
        size_t size = sizeof(CRC_SECONDARY_TAG);
        void* ptr = threadSafeAllocateMemory(size);
        if (ptr) {
            // Initialize secondary data structure
            CRC_SECONDARY_TAG* secData = (CRC_SECONDARY_TAG*)ptr;
            secData->PROCESSING_TIME_MS = rand() % 1000;
            secData->RETRANSMISSION_COUNT = rand();
            secData->CRC_STATUS = rand() % 2;
        } else {
            handleError("Failed to allocate memory for secondary data");
        }
    }
}

// Define thread-safe CRC indication PDU structure resizing function
void threadSafeResizeCrcIndicationPdu(NFAPI_CRC_INDICATION_PDU_T* pdu, int newSize) {
    if (newSize < 0) {
        handleInvalidParameter("newSize");
    } else {
        size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * newSize;
        void* ptr = threadSafeAllocateMemory(size);
        if (ptr) {
            // Copy old data to new buffer
            memcpy(ptr, pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * pdu->length);
        } else {
            handleError("Failed to resize CRC indication PDUs");
        }
    }
}

// Define thread-safe memory deallocation function
void threadSafeFreeMemory(void* ptr) {
    if (ptr) {
        pthread_mutex_lock(&memoryMutex);
        free(ptr);
        pthread_mutex_unlock(&memoryMutex);
    }
}

// Define main function
int main() {
    // Initialize memory mutex
    pthread_mutex_init(&memoryMutex, NULL);

    // Create CRC indication PDUs with 100 elements
    int N = 100;
    NFAPI_CRC_INDICATION_PDU_T* pdu = threadSafeCreateCrcIndicationPdu(N);

    // Create secondary data structure for each CRC indication PDU
    for (int i = 0; i < N; ++i) {
        createSecondaryData(&pdu[i]);
    }

    // Resize CRC indication PDUs to half the original size
    resizeCrcIndicationPdu(pdu, N / 2);

    // Free memory allocated for CRC indication PDUs and secondary data structures
    threadSafeFreeMemory(pdu);

    // Terminate memory mutex
    pthread_mutex_destroy(&memoryMutex);

    return 0;
}']

