struct RX_PROC_T {
  LTE_PHY_RX_PROC_T *lte_phy_rx_proc;
  NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu;
};

struct RX_PROC_LIST {
  struct RX_PROC_T *head;
  struct RX_PROC_T **tail;
};

void rx_proc_list_init(struct RX_PROC_LIST *list) {
  list->head = NULL;
  list->tail = &list->head;
}

int rx_proc_list_add(struct RX_PROC_LIST *list, LTE_PHY_RX_PROC_T *lte_phy_rx_proc, NFAPI_CRC_INDICATION_PDU_T *crc_indication_pdu) {
  struct RX_PROC_T *new_element = malloc(sizeof(struct RX_PROC_T));
  new_element->lte_phy_rx_proc = lte_phy_rx_proc;
  new_element->crc_indication_pdu = crc_indication_pdu;

  pthread_mutex_lock(&list->mutex);
  *(list->tail) = new_element;
  list->tail = &new_element->next;
  pthread_mutex_unlock(&list->mutex);

  return 0;
}

int rx_proc_list_remove(struct RX_PROC_LIST *list, LTE_PHY_RX_PROC_T *lte_phy_rx_proc) {
  struct RX_PROC_T **element = &list->head;
  while (*element != NULL) {
    if ((*element)->lte_phy_rx_proc == lte_phy_rx_proc) {
      pthread_mutex_lock(&list->mutex);
      *(element->prev) = element->next;
      free(*element);
      list->tail = element->prev;
      pthread_mutex_unlock(&list->mutex);
      return 0;
    }
    element = &(*element)->next;
  }

  return -1;
}

int rx_proc_list_get(struct RX_PROC_LIST *list, int index, LTE_PHY_RX_PROC_T **lte_phy_rx_proc) {
  struct RX_PROC_T **element = &list->head;
  while (index > 0 && *element != NULL) {
    element = &(*element)->next;
    index--;
  }

  if (*element == NULL) return -1;

  *lte_phy_rx_proc = (*element)->lte_phy_rx_proc;

  return 0;
}
