        return NULL;
    }

    // Compile the Rust program to measure performance
    std::string rustc_command = "rustc -O --release";
    int pid = fork();
    if (pid == 0) {
        execl("/usr/bin/bash", "bash", "-c", rustc_command.c_str(), NULL);
    } else {
        sync_lazy.wait();
        int status;
        wait(&status);
        if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
            printf("Error: Compilation failed with exit code %d\n", status);
            return NULL;
        }
    }

    // Measure the time taken and resident set size before and after compilation
    std::time_t start = std::clock();
    size_t rss_before = get_resident_set_size(getpid());
    int exit_code = rustc_driver::catch_with_exit_code("my_program.rs");
    std::time_t end = std::clock();
    size_t rss_after = get_resident_set_size(getpid());
    if (exit_code != 0) {
        printf("Error: Compilation failed with exit code %d\n", exit_code);
        return NULL;
    }
    double time_taken = ((double)(end - start)) / CLOCKS_PER_SEC;
    size_t memory_usage = rss_after - rss_before;

    // Log the runtime errors and provide detailed logs for debugging purposes
    if (exit_code != 0) {
        printf("Error: Compilation failed with exit code %d\n", exit_code);
    } else {
        printf("Compilation successful. Time taken = %f seconds, memory usage = %lu bytes\n", time_taken, memory_usage);
    }

    // Free the list of CRC indication PDUs and return a pointer to it
    free(list);
    return list;
}

int generate_rnti() {
    // Randomly generate an RNTI value between 0 and 16384
    int rnti = rand() % 16385 + 1;
    while (rnti == -1) {
        rnti = rand() % 16385 + 1;
    }
    return rnti;
}

int generate_crcflag() {
