/* C function to initialize and manage a dynamic array of LTE_PHY_RX_FRAME instances */

#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <time.h>
#include <assert.h>
#include <stdbool.h>

// Structure to represent a LTE PHY frame header
typedef struct {
    int RNTI; // Random Network Transmission Identifier
    int SFN;  // System Frame Number
} LTE_PHY_RX_FRAME;

// Structure to represent a LTE PHY symbol
typedef struct {
    int modulationType;   // Modulation type (e.g. QPSK,16QAM)
    int phaseRotation;    // Phase rotation (in degrees)
    float noiseVarianceEst; // Noise variance estimate
} LTE_PHY_RX_SYMBOL;

// Dynamic array to store the allocated frames
LTE_PHY_RX_FRAME *frames = NULL;

// Size of the dynamic array
int frameCount = 0;

// Index of the next available frame slot in the array
int nextFrameIndex = 0;

/* Function to generate a random CRC flag value for testing */
unsigned int rand_crcf(void) {
    return (unsigned int)(rand() & 0xFFFF);
}

/* Function to initialize and manage a dynamic array of LTE_PHY_RX_FRAME instances */
int initFrames(int frameCount, bool skipFlag) {
    // Allocate memory for the dynamic array
    frames = (LTE_PHY_RX_FRAME *)malloc(frameCount * sizeof(LTE_PHY_RX_FRAME));
    if (!frames) {
        printf("Error: Failed to allocate memory for frames\n");
        return -1;
    }

    // Initialize the dynamic array with empty structures
    memset(frames, 0, frameCount * sizeof(LTE_PHY_RX_FRAME));

    // Generate random CRC flag values unless skipFlag is set to true
    if (!skipFlag) {
        for (int i = 0; i < frameCount; i++) {
            frames[i].CRCflag = rand_crcf();
        }
    } else {
        // Skip generation of CRC flag values for testing purposes
    }

    // Set the size of the dynamic array and the next available index
    this->frameCount = frameCount;
    this->nextFrameIndex = 0;

    return 0;
}

/* Function to allocate a new LTE_PHY_RX_FRAME structure in the dynamic array */
int allocFrame(LTE_PHY_RX_FRAME *frame) {
    // Check if there is still space available in the dynamic array
    if (nextFrameIndex >= frameCount) {
        printf("Error: Out of memory\n");
        return -1;
    }

    // Copy the input parameters to the newly allocated structure
    memcpy(frames + nextFrameIndex, frame, sizeof(LTE_PHY_RX_FRAME));

    // Increment the next available index and return success
    nextFrameIndex++;
    return 0;
}

/* Function to deallocate a LTE_PHY_RX_FRAME structure in the dynamic array */
int deallocFrame(LTE_PHY_RX_FRAME *frame) {
    // Find the index of the input structure in the dynamic array
    int index = -1;
    for (int i = 0; i < frameCount; i++) {
        if (frames[i].RNTI == frame->RNTI && frames[i].SFN == frame->SFN) {
            index = i;
            break;
        }
    }

    // Check if the structure was found in the dynamic array
    if (index < 0) {
        printf("Error: Frame not found\n");
        return -1;
    }

    // Deallocate the memory for the structure
    free(frames + index);

    // Decrement the next available index and return success
    nextFrameIndex--;
    return 0;
}

/* Function to validate that RNTI values within the allocated structures are unique */
int validateRNTIs() {
    // Initialize a hash table for storing RNTI values
    int *rntiValues = (int *)malloc(frameCount * sizeof(int));
    if (!rntiValues) {
        printf("Error: Failed to allocate memory for RNTI values\n");
        return -1;
    }

    // Iterate over all allocated structures and validate the RNTIs
    for (int i = 0; i < frameCount; i++) {
        int rntiValue = frames[i].RNTI;
        if (rntiValues[rntiValue] > 0) {
            printf("Error: Duplicate RNTI value found\n");
            return -1;
        } else {
            rntiValues[rntiValue]++;
        }
    }

    // Free the memory for the hash table
    free(rntiValues);

    return 0;
}

/* Function to log each allocated structure's tag and value to a specified file */
int logFramesToFile(char *filename) {
    FILE *file = fopen(filename, "a");
    if (!file) {
        printf("Error: Failed to open file\n");
        return -1;
    }

    // Iterate over all allocated structures and log their values
    for (int i = 0; i < frameCount; i++) {
        fprintf(file, "RNTI=%d, SFN=%d, CRCflag=0x%X\n", frames[i].RNTI, frames[i].SFN, frames[i].CRCflag);
    }

    // Close the file and return success
    fclose(file);
    return 0;
}
