['Here is an example implementation of a C library that manages dynamic collections of `item` structures, each containing a `char*` name, an `int` quantity, and a `float` price, with support for applying a discount based on a predefined threshold and calculating the total discounted cost. The library also includes a hash table to map keys to offsets, supports separate chaining or open addressing based on user preference, ensuring efficient lookups and minimal collisions.
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include "hash_table.h"

// Define the item structure
typedef struct {
    char* name;
    int quantity;
    float price;
} item;

// Define the hash table type
typedef struct {
    int size;
    int count;
    item** items;
    int* offsets;
} hash_table;

// Define the discount threshold
const float DISCOUNT_THRESHOLD = 0.25;

// Define the function to calculate the total discounted cost
float calculate_discounted_cost(item* item) {
    return (1 - DISCOUNT_THRESHOLD) * item->price;
}

// Initialize the hash table with a specified size
hash_table* initialize_hash_table(int size) {
    hash_table* ht = (hash_table*)malloc(sizeof(hash_table));
    ht->size = size;
    ht->count = 0;
    ht->items = (item**)calloc(size, sizeof(item*));
    ht->offsets = (int*)calloc(size, sizeof(int));
    return ht;
}

// Insert an item into the hash table
void insert_item(hash_table* ht, const char* name, int quantity, float price) {
    // Calculate the hash value for the key
    int hash = hash_string(name);

    // Check if the hash value is already present in the table
    if (ht->offsets[hash] >= 0) {
        // If it is, check if the item exists in the table
        item* existing_item = ht->items[ht->offsets[hash]];
        if (existing_item != NULL && strcmp(name, existing_item->name) == 0) {
            // If the item already exists, update its quantity and price
            existing_item->quantity += quantity;
            existing_item->price = calculate_discounted_cost(existing_item);
        } else {
            // If the item does not exist, create a new one and insert it into the table
            item* new_item = (item*)malloc(sizeof(item));
            new_item->name = name;
            new_item->quantity = quantity;
            new_item->price = calculate_discounted_cost(new_item);
            ht->items[ht->offsets[hash]] = new_item;
        }
    } else {
        // If the hash value is not present in the table, create a new entry and insert it
        item* new_item = (item*)malloc(sizeof(item));
        new_item->name = name;
        new_item->quantity = quantity;
        new_item->price = calculate_discounted_cost(new_item);
        ht->offsets[hash] = ht->count++;
        ht->items[ht->offsets[hash]] = new_item;
    }
}

// Look up an item in the hash table by its name
item* lookup_item(hash_table* ht, const char* name) {
    // Calculate the hash value for the key
    int hash = hash_string(name);

    // Check if the hash value is present in the table
    if (ht->offsets[hash] >= 0) {
        // If it is, check if the item exists in the table
        item* existing_item = ht->items[ht->offsets[hash]];
        if (existing_item != NULL && strcmp(name, existing_item->name) == 0) {
            return existing_item;
        }
    }
    return NULL;
}

// Delete an item from the hash table by its name
void delete_item(hash_table* ht, const char* name) {
    // Calculate the hash value for the key
    int hash = hash_string(name);

    // Check if the hash value is present in the table
    if (ht->offsets[hash] >= 0) {
        // If it is, check if the item exists in the table
        item* existing_item = ht->items[ht->offsets[hash]];
        if (existing_item != NULL && strcmp(name, existing_item->name) == 0) {
            // If the item already exists, delete it from the table
            free(existing_item);
            ht->offsets[hash] = -1;
        }
    }
}

// Print a list of all items in the hash table
void print_items(hash_table* ht) {
    for (int i = 0; i < ht->count; ++i) {
        item* item = ht->items[i];
        printf("%s, %d, %f\n", item->name, item->quantity, calculate_discounted_cost(item));
    }
}

// Free the memory used by the hash table
void free_hash_table(hash_table* ht) {
    for (int i = 0; i < ht->count; ++i) {
        item* item = ht->items[i];
        if (item != NULL) {
            free(item);
        }
    }
    free(ht->offsets);
    free(ht->items);
}

int main() {
    hash_table* ht = initialize();
    insert_item(ht, "apple", 5, 10);
    insert_item(ht, "banana", 3, 4);
    insert_item(ht, "orange", 2, 5);
    print_items(ht);
    delete_item(ht, "banana");
    print_items(ht);
    free_hash_table(ht);
    return 0;
}']

