int manageUEContexts(struct UEContext **contexts, size_t *num_contexts) {
    // Ensure that memory allocation for the contexts was successful
    assert(*contexts != NULL);

    // Create a temporary buffer to store the contexts temporarily
    struct UEContext *temp_buffer = malloc(sizeof(struct UEContext) * (*num_contexts));
    if (temp_buffer == NULL) {
        return -1;
    }

    // Populate the temporary buffer with randomly generated values for testing purposes
    for (int i = 0; i < *num_contexts; i++) {
        sprintf(temp_buffer[i].imsi, "%d", rand() % 10000);
        temp_buffer[i].rnti = rand() % 1000;
        temp_buffer[i].pdu_session_id = rand() % 1000;
    }

    // Ensure that the temporary buffer is unique within the array
    for (int i = 0; i < *num_contexts - 1; i++) {
        for (int j = i + 1; j < *num_contexts; j++) {
            if (strcmp(temp_buffer[i].imsi, temp_buffer[j].imsi) == 0) {
                return -1;
            }
        }
    }

    // Persist the contexts to disk in a specified file format
    FILE *file = fopen("contexts.bin", "wb");
    if (file == NULL) {
        free(temp_buffer);
        return -1;
    }
    for (int i = 0; i < *num_contexts; i++) {
        fwrite(&temp_buffer[i], sizeof(struct UEContext), 1, file);
    }
    fclose(file);

    // Clean up the temporary buffer
    free(temp_buffer);

    return 0;
}

// Function to query the number of active contexts and their statistics
int queryUEContexts(struct UEContext **contexts, size_t *num_contexts) {
    // Ensure that memory allocation for the contexts was successful
    assert(*contexts != NULL);

    // Initialize variables to store statistics
    int total_rnti = 0;
    int average_rnti = 0;
    int most_frequent_pdu_session_id = 0;
    int highest_count = 0;

    // Iterate over the contexts and calculate statistics
    for (int i = 0; i < *num_contexts; i++) {
        total_rnti += (*contexts)[i].rnti;
        if ((*contexts)[i].pdu_session_id > highest_count) {
            most_frequent_pdu_session_id = (*contexts)[i].pdu_session_id;
            highest_count = (*contexts)[i].pdu_session_id;
        }
    }

    // Calculate the average rnti and return it
    if (*num_contexts > 0) {
        average_rnti = total_rnti / *num_contexts;
    }

    return average_rnti;
}

// Function to automatically clean up unused contexts based on a user-defined inactivity threshold
void cleanupUnusedContexts(struct UEContext **contexts, size_t *num_contexts, int inactivity_threshold) {
    // Iterate over the contexts and remove any that have not been used for at least the specified inactivity threshold
    for (int i = 0; i < *num_contexts; i++) {
        if ((*contexts)[i].rnti < inactivity_threshold) {
            (*contexts)[i] = (*contexts)[(*num_contexts) - 1];
            (*num_contexts)--;
            i--;
        }
    }
}
