// Define a lock for synchronizing access to the queue
static pthread_mutex_t queue_lock = PTHREAD_MUTEX_INITIALIZER;

// Define a condition variable for signaling when the queue is full or empty
static pthread_cond_t queue_full = PTHREAD_COND_INITIALIZER;

// Define the function to create and populate the list of NFAPI_CRC_INDICATION_PDU_T structures
void populate_nfapi_crc_indication_pdus(size_t num_pdus, unsigned char *seed) {
    // Initialize the queue with the specified number of PDUs
    pdu_queue_t *queue = malloc(sizeof(pdu_queue_t));
    queue->length = 0;
    queue->pdu = calloc(num_pdus, sizeof(nfapi_crc_indication_pdu_t));

    // Initialize the seed for random number generation
    srand(*seed);

    // Generate the PDUs and add them to the queue
    for (size_t i = 0; i < num_pdus; i++) {
        nfapi_crc_indication_pdu_t *pdu = &queue->pdu[i];

        // Generate a random size between 1 and 500 bytes for the PDU
        pdu->length = rand() % 500 + 1;

        // Allocate memory for the data field in the PDU
        pdu->data = malloc(pdu->length);

        // Fill the data field with random values
        for (size_t j = 0; j < pdu->length; j++) {
            pdu->data[j] = rand();
        }
    }

    // Signal that the queue is full
    pthread_cond_signal(&queue_full);
}

