void handle_temporary_failure(nfapi_crc_indication_pdu_t *pdu) {
    // If the PDU is NULL, it indicates a temporary failure in the data source
    if (pdu == NULL) {
        // Wait for a short period of time before retrying
        usleep(100);

        // Try again to populate the queue
        populate_nfapi_crc_indication_pdus(num_pdus, seed);
    }
}

