    if (external_data_source.has_updates()) {
        // If so, retrieve them and update the configuration parameters
        unsigned char *seed = external_data_source.get_updates();

        // Update the seed for random number generation
        srand(*seed);
    }
}

// Define a function to handle concurrent access from multiple threads
void handle_concurrent_access(nfapi_crc_indication_pdu_t *pdu) {
    // Lock the queue to prevent other threads from modifying it while we're working on it
    pthread_mutex_lock(&queue_lock);

    // Check if there are any updates available from an external data source
    handle_periodic_updates();

    // If there are no more PDUs in the queue, populate it with new ones
    if (queue->length == 0) {
        populate_nfapi_crc_indication_pdus(num_pdus, seed);
    }

    // Handle temporary data source failures gracefully
    handle_temporary_failure(queue->pdu[0]);

    // Signal that the queue is not empty
    pthread_cond_signal(&queue_full);

    // Unlock the queue to allow other threads to access it
    pthread_mutex_unlock(&queue_lock);
}

