typedef struct record {
    char* buffer;
    size_t length;
} record_t;

void manage_memory(size_t n_records, size_t min_buffer_size, size_t max_buffer_size, size_t n_pairs) {
    // Initialize arrays for offsets, keys, and records
    long* offsets = malloc(n_records * sizeof(long));
    int* keys = malloc(n_records * sizeof(int));
    record_t* records = malloc(n_records * sizeof(record_t));

    // Initialize arrays with random data
    for (size_t i = 0; i < n_records; i++) {
        offsets[i] = rand() % (max_buffer_size - min_buffer_size) + min_buffer_size;
        keys[i] = rand();
        records[i].length = rand() % (max_buffer_size - min_buffer_size) + min_buffer_size;
        records[i].buffer = malloc(records[i].length * sizeof(char));
        for (size_t j = 0; j < records[i].length; j++) {
            records[i].buffer[j] = rand() % 256 + 'a';
        }
    }

    // Sort records based on buffer content lexicographically
    for (size_t i = 0; i < n_records - 1; i++) {
        size_t min_idx = i;
        for (size_t j = i + 1; j < n_records; j++) {
            if (strcmp(records[j].buffer, records[min_idx].buffer) < 0) {
                min_idx = j;
            }
        }
        record_t tmp = records[i];
        records[i] = records[min_idx];
        records[min_idx] = tmp;
    }

    // Replace buffer with new random data for each sorted record
    for (size_t i = 0; i < n_records; i++) {
        free(records[i].buffer);
        records[i].length = rand() % (max_buffer_size - min_buffer_size) + min_buffer_size;
        records[i].buffer = malloc(records[i].length * sizeof(char));
        for (size_t j = 0; j < records[i].length; j++) {
            records[i].buffer[j] = rand() % 256 + 'a';
        }
    }

    // Bulk update buffer content asynchronously
    size_t bulk_update_idx = n_records / 2;
    while (bulk_update_idx < n_records) {
        records[bulk_update_idx].buffer[rand() % records[bulk_update_idx].length] = rand() % 256 + 'a';
        bulk_update_idx += n_pairs / 10;
    }

    // Clean up memory and exit
    for (size_t i = 0; i < n_records; i++) {
        free(records[i].buffer);
    }
    free(offsets);
    free(keys);
    free(records);
}
```
