// Number of PDUs to generate
#define NUM_PDUS 1000

// Seed for random number generation
#define SEED 42

// Mutex for protecting access to the list
pthread_mutex_t mutex;

// Semaphore for blocking threads until data is available
sem_t sem;

// List of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *pdu_list = NULL;
size_t pdu_count = 0;

void initialize_data() {
    // Initialize mutex and semaphore for protecting access to the list
    pthread_mutex_init(&mutex, NULL);
    sem_init(&sem, 0, 0);

    // Allocate memory for the list of PDUs
    pdu_list = (NFAPI_CRC_INDICATION_PDU_T *) malloc(NUM_PDUS * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_list) {
        LOG_ERROR("Failed to allocate memory for PDU list");
        exit(1);
    }
}

void read_file(const char *filename) {
    // Open the file for reading
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        LOG_ERROR("Failed to open file %s", filename);
        exit(1);
    }

    // Read data from the file and deserialize it into the custom data structure
    for (size_t i = 0; i < NUM_PDUs; i++) {
        // Allocate memory for the PDU
        NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T *) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            LOG_ERROR("Failed to allocate memory for PDU %zu", i);
            exit(1);
        }

        // Read RX_UE_INFORMATION_TAG and RNTI from the file
        fread(&pdu->rx_ue_information_tag, sizeof(uint8_t), 1, fp);
        fread(&pdu->rnti, sizeof(uint32_t), 1, fp);

        // Generate a randomly set CRCFLAG for the PDU
        pdu->crc_indication_rel8.crcFlag = rand_r(&SEED) % 2;

        // Add the PDU to the list
        pthread_mutex_lock(&mutex);
        pdu_list[pdu_count++] = *pdu;
        pthread_mutex_unlock(&mutex);
    }

    // Close the file
    fclose(fp);
}

void cleanup_data() {
    // Free memory for the list of PDUs
    free(pdu_list);

    // Destroy mutex and semaphore
    pthread_mutex_destroy(&mutex);
    sem_destroy(&sem);
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        printf("Usage: %s <filename>\n", argv[0]);
        exit(1);
    }

    initialize_data();
    read_file(argv[1]);
    cleanup_data();

    return 0;
}
```
