// Structure for storing data
struct item {
    double d;
    char c;
    bool b;
};

// Function to manage dynamic memory allocation for four data structures
void *manage_memory(void *args) {
    // Initialize variables
    float *float_ptr = NULL;
    int *int_ptr = NULL;
    struct item **item_ptr = NULL;
    char **string_ptr = NULL;
    size_t string_size = 0;

    // Allocate memory for the data structures
    float_ptr = (float *)malloc(sizeof(float));
    int_ptr = (int *)malloc(sizeof(int));
    item_ptr = (struct item **)malloc(sizeof(struct item *));
    string_size = 1024; // Set initial size of the string buffer
    string_ptr = (char **)malloc(string_size);

    // Check for memory allocation errors
    if (!float_ptr || !int_ptr || !item_ptr || !string_ptr) {
        fprintf(stderr, "Error: Failed to allocate memory\n");
        return NULL;
    }

    // Initialize the data structures with default values
    *float_ptr = 0.0f;
    *int_ptr = 0;
    (*item_ptr)->d = 0.0;
    (*item_ptr)->c = 'a';
    (*item_ptr)->b = false;
    **string_ptr = '\0';

    // Initialize the thread pool for asynchronous I/O operations
    pthread_t threads[4];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Create four threads to read data from the network stream
    for (int i = 0; i < 4; ++i) {
        if (pthread_create(&threads[i], &attr, read_data, args)) {
            fprintf(stderr, "Error: Failed to create thread\n");
            return NULL;
        }
    }

    // Join the threads and free any memory allocated during data transmission
    for (int i = 0; i < 4; ++i) {
        pthread_join(threads[i], NULL);
        if (!*float_ptr && !*int_ptr && (*item_ptr)->d == 0.0 && (*item_ptr)->c == 'a' && (*item_ptr)->b == false) {
            free(float_ptr);
            float_ptr = NULL;
            free(int_ptr);
            int_ptr = NULL;
            free(*item_ptr);
            *item_ptr = NULL;
        }
        if (**string_ptr == '\0') {
            free(*string_ptr);
            *string_ptr = NULL;
        }
    }

    // Free the memory allocated for the thread pool
    pthread_attr_destroy(&attr);

    // Return the data structures to the caller
    return (void *)float_ptr;
}

// Thread function to read data from the network stream
void *read_data(void *args) {
    // Declare variables
    float *float_ptr = NULL;
    int *int_ptr = NULL;
    struct item **item_ptr = NULL;
    char **string_ptr = NULL;
    size_t string_size = 0;
    bool done = false;
    char buf[1024];
    int nread;

    // Get the arguments passed to the function
    float_ptr = (float *)args;
    int_ptr = (int *)args;
    item_ptr = (struct item **)args;
    string_ptr = (char **)args;

    // Check for NULL pointers
    if (!float_ptr || !int_ptr || !item_ptr || !string_ptr) {
        fprintf(stderr, "Error: Null pointer passed to read_data\n");
        return NULL;
    }

    // Read data from the network stream
    while (!done && (nread = read(STDIN_FILENO, buf, 1024)) > 0) {
        // Check for errors during data transmission
        if (nread < 0) {
            fprintf(stderr, "Error: Failed to read from stream\n");
            done = true;
        } else {
            // Parse the received data and update the structures accordingly
            char *token = strtok(buf, ", ");
            while (token != NULL && !done) {
                if (*float_ptr == 0.0f && *int_ptr == 0) {
                    // Update the floating-point number
                    sscanf(token, "%f", float_ptr);
                } else if (*item_ptr->d == 0.0 && (*item_ptr)->c == 'a' && (*item_ptr)->b == false) {
                    // Update the integer
                    sscanf(token, "%d", int_ptr);
                } else if (**string_ptr == '\0') {
                    // Update the string
                    strcpy(*string_ptr, token);
                } else {
                    // If the data is corrupted or the structures are full, stop reading data
                    done = true;
                }
                token = strtok(NULL, ", ");
            }
        }
    }

    // Free any memory allocated during data transmission
    if (!*float_ptr && !*int_ptr && (*item_ptr)->d == 0.0 && (*item_ptr)->c == 'a' && (*item_ptr)->b == false) {
        free(float_ptr);
        float_ptr = NULL;
        free(int_ptr);
        int_ptr = NULL;
        free(*item_ptr);
        *item_ptr = NULL;
    }
    if (**string_ptr == '\0') {
        free(*string_ptr);
        *string_ptr = NULL;
    }

