    if (!new_symbol) {
        return;
    }

    // Initialize the new symbol with the given values
    new_symbol->modulation_type = modulation_type;
    new_symbol->phase_rotation = phase_rotation;
    new_symbol->noise_variance = noise_variance;

    // Add the new symbol to the end of the frame's symbol list
    struct { int modulation_type; float phase_rotation; float noise_variance; }** current = &(frame->symbols);
    while (*current != NULL) {
        current = &((*current)->next);
    }
    *current = new_symbol;
    new_symbol->next = NULL;
}

// Function to free a LTE_PHY_RX_FRAME structure and its associated symbols
void lte_phy_rx_frame_free(LTE_PHY_RX_FRAME* frame) {
    // Free the symbols in the frame's symbol list
    struct { int modulation_type; float phase_rotation; float noise_variance; }** current = &(frame->symbols);
    while (*current != NULL) {
        struct { int modulation_type; float phase_rotation; float noise_variance; }* symbol = *current;
        free(symbol);
        *current = (*current)->next;
    }

    // Free the frame structure itself
