#define MAX_ENTRIES 10000000 // maximum number of entries in the hash table
#define MIN_TIMESTAMP 0      // minimum timestamp value
#define MAX_TIMESTAMP 1000   // maximum timestamp value
#define MIN_VALUE -1.0       // minimum sensor value
#define MAX_VALUE 100.0      // maximum sensor value

// structure for data items in the array and hash table
typedef struct DataItem {
    char* string;
    int timestamp;
    float value;
} DataItem;

// function to manage memory allocation and initialization for an array of custom `DataItem` structures and a corresponding hash table for efficient lookups based on unique identifiers (IDs)
void initialize_data(int num_entries, char* data[], int timestamp[], float value[], int id[], int hash_table[]) {
    // allocate memory for the array of `DataItem` structures and the hash table
    data = malloc(sizeof(DataItem) * num_entries);
    hash_table = malloc(sizeof(int) * MAX_ENTRIES);

    // initialize the structures and hash table to store a specified number of entries, supporting configurations up to 10 million entries for high-performance applications
    for (int i = 0; i < num_entries; i++) {
        data[i].string = malloc(sizeof(char) * 256);
        timestamp[i] = rand() % (MAX_TIMESTAMP - MIN_TIMESTAMP + 1) + MIN_TIMESTAMP;
        value[i] = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
        id[i] = i + 1;
    }

    // populate the array and hash table with randomly generated data within given ranges for timestamps and values, and with unique IDs for each entry. Consider data integrity during population, especially when dealing with potential collisions.
    for (int i = 0; i < num_entries; i++) {
        int id = id[i];
        char* string = malloc(sizeof(char) * 256);
        sprintf(string, "Data item %d", id);
        data[i].string = string;
        hash_table[id] = i;
    }

    // implement a custom hash function for the hash table to ensure efficient lookups and minimal collisions, while also being scalable to accommodate future growth.
    unsigned long hash(int id) {
        unsigned long seed = 0;
        char* string = data[id].string;
        int len = strlen(string);
        for (int i = 0; i < len; i++) {
            seed += string[i];
            seed *= 131;
        }
        return seed % MAX_ENTRIES;
    }

    // integrate the function with an existing logging framework to capture all allocation and deallocation events, aiding in performance tuning and debugging.
    #ifdef DEBUG
    void log(char* message) {
        printf("[%s] %s\n", __func__, message);
    }
    #endif

    // support concurrent read and write operations in a multi-threaded environment without causing race conditions or data corruption, leveraging thread-safe data structures and synchronization mechanisms.
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // optimize the function for performance, considering the potential for large datasets and frequent updates, but also balance this with ease of maintenance and code readability.
    #ifdef PERFORMANCE
    void update(int id, int timestamp, float value) {
        pthread_mutex_lock(&mutex);
        data[id].timestamp = timestamp;
        data[id].value = value;
        pthread_cond_broadcast(&cond);
        pthread_mutex_unlock(&mutex);
    }
    #endif

    // handle edge cases, such as zero-sized arrays, duplicate IDs, and extremely large datasets, ensuring robustness and reliability.
    if (num_entries <= 0) {
