    PHY_RX_STATUS_TAG status;
    RX_QAM_MIMO_CONFIG qamConfig;
} PHY_RX_FRAME_INFO;

// Linked list node for managing PHY_RX_FRAME_INFO structures
typedef struct {
    PHY_RX_FRAME_INFO *info;
    struct _list_node *next;
} _list_node;

// Function to manage a dynamic list of PHY_RX_FRAME_INFO structures
void manage_rx_frames(PHY_RX_FRAME_INFO **list, size_t numFrames) {
    // Initialize the linked list node
    _list_node *head = NULL;

    // Iterate over each frame in the list
    for (size_t i = 0; i < numFrames; ++i) {
        PHY_RX_FRAME_INFO *info = list[i];

        // Check for duplicate subframe indices and skip if necessary
        _list_node *cur = head;
        while (cur != NULL) {
            if (cur->info->subframeIndex == info->subframeIndex) {
                printf("Duplicate subframe index detected! Skipping frame %lu\n", i);
                break;
            }
            cur = cur->next;
        }

        // Add the frame to the list if it's not a duplicate
        if (cur == NULL) {
            _list_node *newNode = malloc(sizeof(_list_node));
            newNode->info = info;
            newNode->next = head;
            head = newNode;
        }
    }

    // Free the memory used by the list nodes and return the updated list
    _list_node *cur = head;
    while (cur != NULL) {
        _list_node *tmp = cur->next;
        free(cur);
        cur = tmp;
    }

    // Return the updated list
    return list;
}

