        LTE_PHY_RX_FRAME *curr_record = records;

        while (curr_record) {
            prev_record = curr_record;
            curr_record = curr_record->next;
        }

        // Allocate memory for the new record
        alloc_record(record);

        // Add the record to the end of the linked list
        prev_record->next = record;
    }
}

