        LTE_PHY_RX_FRAME *curr_record = records;

        while (curr_record) {
            if (curr_record == record) {
                // Remove the record from the linked list
                prev_record->next = curr_record->next;

                free_record(record);

                break;
            }

            prev_record = curr_record;
            curr_record = curr_record->next;
        }
    }
}

// Function to handle concurrent access to the records linked list
void handle_concurrent_access(LTE_PHY_RX_FRAME *record) {
