// Function to insert an entry into the hash table
void insert_entry(int key, double precision) {
    struct hash_table *new_node = (struct hash_table *)malloc(sizeof(struct hash_table));
    new_node->next = hashtable[key % HASHTABLE_SIZE];
    new_node->key = key;
    new_node->precision = precision;
    hashtable[key % HASHTABLE_SIZE] = new_node;
}

// Function to delete an entry from the hash table
void delete_entry(int key) {
    struct hash_table **current = &hashtable[key % HASHTABLE_SIZE];
    while (*current != NULL && (*current)->key != key) {
        current = &((*current)->next);
    }
    if (*current != NULL) {
        // Remove the node from the linked list
        struct hash_table *tmp = *current;
        *current = tmp->next;
        free(tmp);
    }
}

// Function to look up an entry in the hash table
struct hash_table *lookup_entry(int key) {
    struct hash_table *current = hashtable[key % HASHTABLE_SIZE];
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    return current;
}

// Function to update the data in an entry
