    char buffer[256];
    float* array;
};

struct Item {
    int index;
    struct Data* data;
    struct Item* next;
};

// Define the function that manages memory allocation and lifecycle for the four data structures
void manageMemory(int offsetSize, int keySize, int dataSize, int itemSize) {
    // Initialize the arrays to hold the data structures
    long* offsets = malloc(offsetSize * sizeof(long));
    int* keys = malloc(keySize * sizeof(int));
    struct Data* datas = malloc(dataSize * sizeof(struct Data));
    struct Item* items = malloc(itemSize * sizeof(struct Item));

    // Initialize the 'int' value in each 'data' structure to a random number within a specified range
    for (int i = 0; i < dataSize; ++i) {
        datas[i].value = rand() % 100;
    }

    // Fill the 'char' buffer with a fixed-size string
    char* buffer = "Fixed-size string";
    for (int i = 0; i < dataSize; ++i) {
        memcpy(datas[i].buffer, buffer, sizeof(char) * 256);
    }

    // Allocate memory for the 'float' array based on a predefined size
    int arraySize = 100;
    for (int i = 0; i < dataSize; ++i) {
        datas[i].array = malloc(sizeof(float) * arraySize);
    }

    // Insert new 'item' nodes into the linked list at specific positions, handling cases where the linked list becomes full
    struct Item* head = NULL;
    for (int i = 0; i < itemSize; ++i) {
        struct Item* newItem = malloc(sizeof(struct Item));
        newItem->index = i;
        newItem->data = &datas[i];
        newItem->next = head;
        head = newItem;
    }

    // Reallocation strategy to efficiently update the list when it becomes full
    if (head == NULL) {
        return;
    } else {
        int count = 0;
        struct Item* current = head;
        while (current != NULL) {
            ++count;
            current = current->next;
        }
        if (count >= itemSize - 1) {
            struct Item* newItem = malloc(sizeof(struct Item));
            newItem->index = count + 1;
            newItem->data = &datas[count];
            head->next = newItem;
            head = newItem;
        }
    }

    // Free the memory allocated for the data structures when it is no longer needed
    free(offsets);
    free(keys);
    for (int i = 0; i < dataSize; ++i) {
        free(datas[i].array);
    }
    free(datas);
    free(items);
}
```
