// Define struct for LTE PHY RX frame header, signal strength indicator, and symbol list
typedef struct {
    char header[1024]; // Maximum size of LTE PHY RX frame header is 1024 bytes
    int signal_strength;
    struct symbol_list *symbols;
} LTE_PHY_RX_FRAME;

// Define struct for LTE PHY RX symbol list
typedef struct {
    char modulation[16]; // Maximum size of modulation type is 16 bytes
    int phase_rotation;
    float noise_variance_estimate;
    time_t timestamp;
} LTE_PHY_RX_SYMBOL;

// Define struct for dynamic array of LTE PHY RX frame instances
typedef struct {
    LTE_PHY_RX_FRAME **frames;
    size_t num_frames;
    size_t max_frames;
} LTE_PHY_RX_FRAME_ARRAY;

// Define mutex for thread-safe access to dynamic array
pthread_mutex_t array_lock = PTHREAD_MUTEX_INITIALIZER;

// Initialize and manage a dynamic array of LTE PHY RX frame instances
void init_frame_array(LTE_PHY_RX_FRAME_ARRAY *arr) {
    arr->frames = malloc(sizeof(LTE_PHY_RX_FRAME *) * 10); // Initial capacity of 10 frames
    arr->num_frames = 0;
    arr->max_frames = 10;
}

void add_frame(LTE_PHY_RX_FRAME_ARRAY *arr, LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&array_lock); // Lock mutex for thread-safe access to array
    if (arr->num_frames == arr->max_frames) { // If maximum capacity reached, double size of array
        LTE_PHY_RX_FRAME **new_frames = realloc(arr->frames, sizeof(LTE_PHY_RX_FRAME *) * arr->max_frames * 2);
        if (!new_frames) { // If memory allocation fails, handle error and return
            printf("Error: Memory allocation failed\n");
            pthread_mutex_unlock(&array_lock);
            return;
        }
        arr->frames = new_frames;
        arr->max_frames *= 2;
    }
    // Add frame to array and increase number of frames
    arr->frames[arr->num_frames] = frame;
    arr->num_frames++;
    pthread_mutex_unlock(&array_lock); // Unlock mutex after adding frame
}

void update_frame(LTE_PHY_RX_FRAME_ARRAY *arr, LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&array_lock); // Lock mutex for thread-safe access to array
    int index = find_frame(arr, frame->header);
    if (index < 0) { // If frame not found in array, handle error and return
        printf("Error: Frame not found\n");
        pthread_mutex_unlock(&array_lock);
        return;
    }
    arr->frames[index] = frame;
    pthread_mutex_unlock(&array_lock); // Unlock mutex after updating frame
}

LTE_PHY_RX_FRAME *find_frame(LTE_PHY_RX_FRAME_ARRAY *arr, char *header) {
    for (int i = 0; i < arr->num_frames; i++) {
        if (!strcmp(arr->frames[i]->header, header)) { // If frame found, return its index
            return arr->frames[i];
        }
    }
    return -1; // If frame not found, return -1
}

void free_frame_array(LTE_PHY_RX_FRAME_ARRAY *arr) {
    for (int i = 0; i < arr->num_frames; i++) {
        free(arr->frames[i]); // Free each frame in the array
    }
    free(arr->frames); // Free the array itself
}
