  long* offsets = malloc(num_elements * sizeof(long));
  int* keys = malloc(num_elements * sizeof(int));
  entry* entries = malloc(num_elements * sizeof(entry));

  // Initialize the offsets array with zeroes.
  memset(offsets, 0, num_elements * sizeof(long));

  // Initialize the keys array with random integers.
  for (size_t i = 0; i < num_elements; ++i) {
    keys[i] = rand() % INT_MAX;
  }

  // Initialize the entries array with dynamically allocated strings.
  for (size_t i = 0; i < num_elements; ++i) {
    char* identifier = generate_unique_identifier(IDENTIFIER_LENGTH);
    entries[i].value = keys[i];
    entries[i].identifier = identifier;
  }

  // Ensure all memory allocations are properly managed.
  if (!offsets || !keys || !entries) {
    fprintf(stderr, "Memory allocation error\n");
    return;
  }
}

// Generate a unique alphanumeric identifier with a fixed length of 'IDENTIFIER_LENGTH'.
char* generate_unique_identifier(size_t length) {
  // Initialize the generated identifier string.
  char* identifier = malloc(length * sizeof(char));
  if (!identifier) {
    fprintf(stderr, "Memory allocation error\n");
    return NULL;
  }

  // Generate a random alphanumeric string with the specified length.
  for (size_t i = 0; i < length; ++i) {
    int random_char = rand() % ALPHANUMERIC_CHARS_LENGTH;
    identifier[i] = ALPHANUMERIC_CHARS[random_char];
  }

  return identifier;
}

// Clean up all memory allocations.
void cleanup_memory() {
  // Free the arrays of offsets, keys, and entries.
  free(offsets);
  free(keys);
  for (size_t i = 0; i < num_elements; ++i) {
    free(entries[i].identifier);
  }
  free(entries);
}

// Thread-safe data structure to store the offsets array.
