memset(entries, 0, num_elements * sizeof(entry));

// Mutex to protect concurrent access to the offsets array.
pthread_mutex_t offset_mutex = PTHREAD_MUTEX_INITIALIZER;

// Mutex to protect concurrent access to the keys array.
pthread_mutex_t key_mutex = PTHREAD_MUTEX_INITIALIZER;

// Mutex to protect concurrent access to the entries array.
pthread_mutex_t entry_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to update an offset in the offsets array.
void update_offset(size_t index, long value) {
  // Acquire the mutex for the offsets array.
  pthread_mutex_lock(&offset_mutex);

  // Update the offset at the specified index.
  offsets[index] = value;

  // Release the mutex for the offsets array.
  pthread_mutex_unlock(&offset_mutex);
}

// Function to update a key in the keys array.
void update_key(size_t index, int value) {
  // Acquire the mutex for the keys array.
  pthread_mutex_lock(&key_mutex);

  // Update the key at the specified index.
  keys[index] = value;

  // Release the mutex for the keys array.
  pthread_mutex_unlock(&key_mutex);
}

// Function to update an entry in the entries array.
void update_entry(size_t index, int value) {
  // Acquire the mutex for the entries array.
  pthread_mutex_lock(&entry_mutex);

  // Update the entry at the specified index.
  entries[index].value = value;

  // Release the mutex for the entries array.
  pthread_mutex_unlock(&entry_mutex);
}

// Function to update an entry in the entries array with a dynamically allocated string.
void update_entry_string(size_t index, char* identifier) {
  // Acquire the mutex for the entries array.
  pthread_mutex_lock(&entry_mutex);

  // Update the entry at the specified index with the new string.
  entries[index].identifier = identifier;

  // Release the mutex for the entries array.
  pthread_mutex_unlock(&entry_mutex);
}
