```
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>
#include <sys/sem.h>

struct task {
    char *description;
    int priority;
    struct timeval start_time, end_time;
};

struct task_queue {
    int size;
    int head;
    int tail;
    struct task tasks[];
};

int create_task(struct task_queue *q, char *description, int priority) {
    // Allocate memory for the new task
    struct task *t = malloc(sizeof(struct task));
    if (!t) return -1;

    // Set the description and priority of the task
    t->description = strdup(description);
    t->priority = priority;

    // Get the current time as the start time for the task
    gettimeofday(&t->start_time, NULL);

    // Add the new task to the queue
    q->tasks[q->tail] = t;
    q->tail = (q->tail + 1) % q->size;

    return 0;
}

int delete_task(struct task_queue *q, int index) {
    // Check if the index is valid
    if (index < 0 || index >= q->size) return -1;

    // Get the task at the specified index
    struct task *t = &q->tasks[index];

    // Free the memory allocated for the task's description
    free(t->description);

    // Remove the task from the queue
    q->tail = (q->tail - 1 + q->size) % q->size;

    return 0;
}

int process_task(struct task_queue *q, struct task *t) {
    // Do some processing on the task here...
    printf("Processing task %s\n", t->description);

    return 0;
}

void prune_tasks(struct task_queue *q) {
    int i = q->tail;
    while (i != q->head) {
        struct task *t = &q->tasks[i];
        if (t->end_time.tv_sec == 0) break;
        delete_task(q, i);
    }
}

int main() {
    // Create a shared memory segment for the task queue
    key_t key = ftok("./", 'T');
    int shm_id = shmget(key, sizeof(struct task_queue), IPC_CREAT | 0644);
    if (shm_id < 0) {
        perror("Error creating shared memory segment");
        return 1;
    }

    // Attach the shared memory segment to this process
    struct task_queue *q = shmat(shm_id, NULL, 0);
    if (!q) {
        perror("Error attaching shared memory segment");
        return 1;
    }

    // Initialize the queue with a fixed size
    q->size = 10000;
    q->head = 0;
    q->tail = 0;

    // Create a semaphore for locking access to the queue
    int sem_id = semget(key, 2, IPC_CREAT | 0644);
    if (sem_id < 0) {
        perror("Error creating semaphore");
        return 1;
    }

    // Create a thread for processing tasks in the queue
    pthread_t tid;
    pthread_create(&tid, NULL, process_tasks, q);

    // Create some sample tasks to add to the queue
    struct task t[3];
    t[0].description = "Task 1";
    t[0].priority = 5;
    t[0].start_time.tv_sec = time(NULL);
    t[0].end_time.tv_sec = 0;
    t[1].description = "Task 2";
    t[1].priority = 3;
    t[1].start_time.tv_sec = time(NULL);
    t[1].end_time.tv_sec = 0;
    t[2].description = "Task 3";
    t[2].priority = 7;
    t[2].start_time.tv_sec = time(NULL);
    t[2].end_time.tv_sec = 0;

    // Add the sample tasks to the queue
    for (int i = 0; i < 3; i++) {
        create_task(q, t[i].description, t[i].priority);
    }

    // Wait for the thread to finish processing the tasks
    pthread_join(tid, NULL);

    return 0;
}
```

This code implements a task queue with a fixed size and uses semaphores to ensure thread safety. It also includes a mechanism for pruning completed tasks from the queue to free up resources and improve performance. The `create_task` function allocates memory for a new task, sets its description and priority, and adds it to the end of the queue. The `delete_task` function removes a task from the queue by updating the tail index. The `process_task` function processes a single task in the queue, and the `prune_tasks` function removes completed tasks from the queue. The `main` function creates a shared memory segment for the task queue and attaches it to this process, initializes the queue with a fixed size, creates a thread for processing tasks in the queue, adds some sample tasks to the queue, waits for the thread to finish processing the tasks, and then exits.']

