    for (int i = 0; i < MEMORY_POOL_SIZE / sizeof(memory_pool_entry_t); i++) {
        if (!memory_pool[i].used) {
            memory_pool[i].used = true;
            memory_pool[i].data.rnti = rnti;
            memory_pool[i].data.crc_indication_rel8_tag = RX_UE_INFORMATION_TAG;
            memory_pool[i].data.crcflag = crcfalg;
            return &memory_pool[i].data;
