int processMediaContentAndGenerateReports(int batch_size, const char* media_file_path, const char* output_dir, const configuration_t* config, logging_handle_t* logger) {
    // Check if the input parameters are valid
    if (batch_size <= 0 || !media_file_path || !output_dir || !config || !logger) {
        fprintf(stderr, "Invalid input parameters\n");
        return 1;
    }

    // Open the media file and generate an MD5 hash of its content
    int media_file = open(media_file_path, O_RDONLY);
    if (media_file < 0) {
        fprintf(stderr, "Failed to open media file: %s\n", strerror(errno));
        return 1;
    }

    MD5_CTX md5_ctx;
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_Init(&md5_ctx);
    int read_bytes = 0;
    while ((read_bytes = read(media_file, buffer, sizeof(buffer))) > 0) {
        MD5_Update(&md5_ctx, buffer, read_bytes);
    }
    MD5_Final(digest, &md5_ctx);
    char* md5 = malloc(MD5_DIGEST_LENGTH * 2 + 1);
    if (!md5) {
        fprintf(stderr, "Failed to allocate memory for MD5 hash\n");
        return 1;
    }
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        sprintf(md5 + i * 2, "%02x", digest[i]);
    }

    // Extract key frames from the media file
    int num_frames = extract_key_frames(media_file_path);
    if (num_frames < 0) {
        fprintf(stderr, "Failed to extract key frames\n");
        return 1;
    }

    // Analyze the extracted frames for specific visual patterns
    image_processing_result_t* results = analyze_frames(frames, num_frames);
    if (!results) {
        fprintf(stderr, "Failed to analyze frames\n");
        return 1;
    }

    // Store the analysis results in a structured format within the report
    char* json = generate_report(results, md5, num_frames);
    if (!json) {
        fprintf(stderr, "Failed to generate report\n");
        return 1;
    }

    // Validate the configuration settings and log an appropriate warning if necessary
    int config_valid = validate_configuration(config);
    if (config_valid < 0) {
        fprintf(stderr, "Failed to validate configuration\n");
        return 1;
    } else if (!config_valid) {
        log_warning("Configuration is invalid. Using default settings where possible.");
    }

    // Cache the results of the analysis for improved performance on subsequent runs
    cache_results(json, num_frames);

    // Handle potential race conditions during caching and logging
    pthread_mutex_lock(&cache_mutex);
    write_report(output_dir, json, "report.json");
    pthread_mutex_unlock(&cache_mutex);

    free(md5);
    free(results);
    free(json);

    return 0;
}
