void manage_memory(size_t num_structures, size_t array_size, int random_range, int seed, bool reset) {
    // Check input parameters for validity
    if (num_structures == 0 || array_size == 0 || random_range <= 0) {
        return;
    }

    // Allocate memory for the structures and arrays
    NFAPI_CRC_INDICATION_PDU_T *structures = malloc(num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (structures == NULL) {
        return;
    }

    // Initialize the structures and arrays
    for (size_t i = 0; i < num_structures; i++) {
        structures[i].rx_ue_information_tag = 0;
        structures[i].rnti = 0;

        for (size_t j = 0; j < array_size; j++) {
            structures[i].crc_indication_rel8_tag[j] = (uint32_t)random() % random_range + 1;
        }
    }

    // Reset the arrays to zero after use if requested
    if (reset) {
        for (size_t i = 0; i < num_structures; i++) {
            memset(structures[i].crc_indication_rel8_tag, 0, sizeof(structures[i].crc_indication_rel8_tag));
        }
    }

    // Handle memory reallocation if the number of structures exceeds a predefined threshold
    size_t max_size = num_structures * (sizeof(NFAPI_CRC_INDICATION_PDU_T) + array_size * sizeof(uint32_t));
    if (max_size > MAX_STRUCTURES * (sizeof(NFAPI_CRC_INDICATION_PDU_T) + ARRAY_SIZE * sizeof(uint32_t))) {
        size_t new_num_structures = num_structures / 2;
        NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(structures, new_num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_structures == NULL) {
            free(structures);
            return;
        }
        structures = new_structures;
    }

    // Verify that no memory leaks have occurred
    assert(structures != NULL);

    // Manage resources efficiently to minimize fragmentation and ensure thread safety in a multi-threaded environment
    pthread_mutex_lock(&memory_mutex);
    size_t total_size = num_structures * (sizeof(NFAPI_CRC_INDICATION_PDU_T) + array_size * sizeof(uint32_t));
    if (total_size > MAX_STRUCTURES * (sizeof(NFAPI_CRC_INDICATION_PDU_T) + ARRAY_SIZE * sizeof(uint32_t))) {
        size_t new_num_structures = num_structures / 2;
        NFAPI_CRC_INDICATION_PDU_T *new_structures = realloc(structures, new_num_structures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_structures == NULL) {
            free(structures);
            pthread_mutex_unlock(&memory_mutex);
            return;
        }
        structures = new_structures;
    }
    pthread_mutex_unlock(&memory_mutex);
}
