    if (cachedAnalysisResults != NULL) {
        cachedAnalysisResults = analysisResults;
        pthread_mutex_unlock(&cacheMutex);
    } else {
        pthread_mutex_unlock(&cacheMutex);
        free(analysisResults);
    }

    // Optimize memory usage and processing time, considering the possibility of handling multiple concurrent sessions with varying batch sizes
    if (batchSize > 0 && N > 0) {
        char* optimizedAnalysisResults = optimizeMemoryUsageAndProcessingTime(ipLibHandle, keyFrames, batchSize);
        if (optimizedAnalysisResults == NULL) {
            printf("Error: failed to optimize memory usage and processing time\n");
            return 1;
        }
    }

    // Ensure the function can recover gracefully from unexpected errors, such as failures in third-party library calls or disk I/O issues
