#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define the structure of metadata
typedef struct Metadata {
  char* identifier;
  int status_code;
  long timestamp;
} Metadata;

// Define a hash table data structure for storing metadata
typedef struct HashTableNode {
  Metadata* metadata;
  struct HashTableNode* next;
} HashTableNode;

// Define the external data storage layer
extern void persist_data(Metadata*);

// Define the thread-safe hash table structure
struct ThreadSafeHashTable {
  pthread_mutex_t mutex;
  int capacity;
  float load_factor;
  HashTableNode** nodes;
};

// Initialize a new hash table with specified capacity and load factor
struct ThreadSafeHashTable* init_hash_table(int capacity, float load_factor) {
  struct ThreadSafeHashTable* hash_table = (struct ThreadSafeHashTable*)malloc(sizeof(struct ThreadSafeHashTable));
  hash_table->capacity = capacity;
  hash_table->load_factor = load_factor;
  hash_table->nodes = (HashTableNode**)calloc(hash_table->capacity, sizeof(HashTableNode*));
  pthread_mutex_init(&hash_table->mutex, NULL);
  return hash_table;
}

// Insert a new metadata entry into the hash table
void insert(struct ThreadSafeHashTable* hash_table, Metadata* metadata) {
  // Acquire the mutex lock to ensure thread-safe operations
  pthread_mutex_lock(&hash_table->mutex);

  // Compute the hash code of the metadata identifier
  int hash_code = hash(metadata->identifier);

  // Find the position where the metadata should be inserted
  HashTableNode* new_node = (HashTableNode*)malloc(sizeof(HashTableNode));
  new_node->metadata = metadata;
  new_node->next = NULL;
  int index = hash_code % hash_table->capacity;
  if (hash_table->nodes[index] == NULL) {
    // Insert the new node at the head of the linked list if the position is empty
    hash_table->nodes[index] = new_node;
  } else {
    // Otherwise, insert the new node after the last element in the linked list
    HashTableNode* current = hash_table->nodes[index];
    while (current->next != NULL) {
      current = current->next;
    }
    current->next = new_node;
  }

  // Release the mutex lock and return
  pthread_mutex_unlock(&hash_table->mutex);
}

// Lookup a metadata entry in the hash table
Metadata* lookup(struct ThreadSafeHashTable* hash_table, char* identifier) {
  // Acquire the mutex lock to ensure thread-safe operations
  pthread_mutex_lock(&hash_table->mutex);

  // Compute the hash code of the metadata identifier
  int hash_code = hash(identifier);

  // Find the position where the metadata should be looked up
  HashTableNode* current = hash_table->nodes[hash_code % hash_table->capacity];
  while (current != NULL) {
    if (strcmp(current->metadata->identifier, identifier) == 0) {
      // Release the mutex lock and return the found metadata entry
      pthread_mutex_unlock(&hash_table->mutex);
      return current->metadata;
    }
    current = current->next;
  }

  // If no metadata entry is found, release the mutex lock and return NULL
  pthread_mutex_unlock(&hash_table->mutex);
  return NULL;
}

// Delete a metadata entry from the hash table
void delete(struct ThreadSafeHashTable* hash_table, char* identifier) {
  // Acquire the mutex lock to ensure thread-safe operations
  pthread_mutex_lock(&hash_table->mutex);

  // Compute the hash code of the metadata identifier
  int hash_code = hash(identifier);

  // Find the position where the metadata should be deleted
  HashTableNode* current = hash_table->nodes[hash_code % hash_table->capacity];
  HashTableNode* previous = NULL;
  while (current != NULL) {
    if (strcmp(current->metadata->identifier, identifier) == 0) {
      // Delete the metadata entry from the linked list
      if (previous == NULL) {
        hash_table->nodes[hash_code % hash_table->capacity] = current->next;
      } else {
        previous->next = current->next;
      }
      free(current);
      break;
    }
    previous = current;
    current = current->next;
  }

  // Release the mutex lock and return
  pthread_mutex_unlock(&hash_table->mutex);
}

// Update a metadata entry in the hash table
void update(struct ThreadSafeHashTable* hash_table, Metadata* metadata) {
  // Acquire the mutex lock to ensure thread-safe operations
  pthread_mutex_lock(&hash_table->mutex);

  // Compute the hash code of the metadata identifier
  int hash_code = hash(metadata->identifier);

  // Find the position where the metadata should be updated
  HashTableNode* current = hash_table->nodes[hash_code % hash_table->capacity];
  while (current != NULL) {
    if (strcmp(current->metadata->identifier, metadata->identifier) == 0) {
      // Update the metadata entry in the linked list
      current->metadata = metadata;
      break;
    }
    current = current->next;
  }

  // Release the mutex lock and return
  pthread_mutex_unlock(&hash_table->mutex);
}

// Free memory associated with the hash table and its nodes
void freeHashTable(struct ThreadSafeHashTable* hash_table) {
  // Acquire the mutex lock to ensure thread-safe operations
  pthread_mutex_lock(&hash_table->mutex);

  // Free memory associated with each node in the linked list
  HashTableNode* current = hash_table->nodes[0];
  while (current != NULL) {
    HashTableNode* next = current->next;
    free(current);
    current = next;
  }

  // Release the mutex lock and return
  pthread_mutex_unlock(&hash_table->mutex);
}

// Free memory associated with a specific metadata entry
void freeMetadata(struct Metadata* metadata) {
  free(metadata);
}
```

This code implements a thread-safe hash table that can be used to store and retrieve metadata entries. The `insert` function is used to insert a new metadata entry into the hash table, while the `lookup` function is used to find an existing metadata entry in the hash table by its identifier. The `delete` function is used to delete a specific metadata entry from the hash table, and the `update` function is used to update an existing metadata entry. Finally, the `freeHashTable` function is used to free memory associated with the entire hash table and all of its nodes, while the `freeMetadata` function is used to free memory associated with a specific metadata entry.

