#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

typedef struct NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG rxUeInformationTag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcIndicationRel8Tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct DynamicArray {
    size_t size;
    size_t capacity;
    NFAPI_CRC_INDICATION_PDU_T* elements;
    pthread_mutex_t lock;
} DynamicArray;

DynamicArray* createDynamicArray(size_t initialCapacity) {
    if (initialCapacity == 0) {
        initialCapacity = 1;
    }
    DynamicArray* array = malloc(sizeof(DynamicArray));
    array->size = 0;
    array->capacity = initialCapacity;
    array->elements = malloc(array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

void destroyDynamicArray(DynamicArray* array) {
    free(array->elements);
    pthread_mutex_destroy(&array->lock);
    free(array);
}

bool addElementToDynamicArray(DynamicArray* array, NFAPI_CRC_INDICATION_PDU_T element) {
    pthread_mutex_lock(&array->lock);
    if (array->size == array->capacity) {
        array->capacity *= 2;
        array->elements = realloc(array->elements, array->capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }
    array->elements[array->size++] = element;
    pthread_mutex_unlock(&array->lock);
}

void removeElementFromDynamicArray(DynamicArray* array, size_t index) {
    if (index >= array->size) {
        return;
    }
    pthread_mutex_lock(&array->lock);
    array->elements[index] = array->elements[--array->size];
    pthread_mutex_unlock(&array->lock);
}

void clearDynamicArray(DynamicArray* array) {
    pthread_mutex_lock(&array->lock);
    array->size = 0;
    pthread_mutex_unlock(&array->lock);
}

bool isEmptyDynamicArray(DynamicArray* array) {
    bool result;
    pthread_mutex_lock(&array->lock);
    result = (array->size == 0);
    pthread_mutex_unlock(&array->lock);
    return result;
}

void iterateOverDynamicArray(DynamicArray* array, void (*callback)(NFAPI_CRC_INDICATION_PDU_T)) {
    for (int i = 0; i < array->size; i++) {
        callback(array->elements[i]);
    }
}
