// Structure to represent a TrafficEvent
typedef struct TrafficEvent {
    unsigned long timestamp; // Timestamp of the event in milliseconds since epoch
    char* event_type;        // Type of the event (e.g., "incoming", "outgoing")
    void* metadata;          // Associated metadata (e.g., a JSON object)
} TrafficEvent;

// Dynamic array to store the events
TrafficEvent* events = NULL;
size_t num_events = 0;

// Function to add a new event to the array
void add_event(TrafficEvent* event) {
    // Check if the array is full and needs to be resized
    if (num_events >= MAX_NUM_EVENTS) {
        size_t new_size = num_events * 2;
        events = realloc(events, new_size);
    }
    // Add the event to the array
    memcpy(&events[num_events], event, sizeof(TrafficEvent));
    ++num_events;
}

// Function to remove events based on a specified condition
void remove_events(int (*condition)(const TrafficEvent*)) {
    for (size_t i = 0; i < num_events; ++i) {
        if (condition(&events[i])) {
            // Shift the remaining events to the left by one position
            memmove(&events[i], &events[i + 1], sizeof(TrafficEvent) * (num_events - i - 1));
            --num_events;
        }
    }
}

// Function to retrieve the latest N events
