#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_SESSIONS 1024 // maximum number of concurrent sessions
#define MIN_THREADS 8 // minimum number of threads for aggregation and flush
#define MAX_THREADS 64 // maximum number of threads for aggregation and flush
#define FLUSH_INTERVAL 5 // interval (in seconds) for flushing accumulated metrics

// structure to store statistics for each session
struct SessionStat {
    int session_id;
    unsigned long long bytes_received;
    unsigned long long bytes_sent;
    unsigned long long packets_received;
    unsigned long long packets_sent;
};

// hash table for storing statistics for each session
static struct SessionStat *session_stats[MAX_SESSIONS];

// mutex for protecting concurrent access to the hash table
static pthread_mutex_t stats_mtx = PTHREAD_MUTEX_INITIALIZER;

// condition variable for signaling when flushing is required
static pthread_cond_t flush_cv = PTHREAD_COND_INITIALIZER;

// function to initialize and configure the statistics collection module
void init_statistics(int num_threads) {
    // ensure the number of threads is within the specified range
    if (num_threads < MIN_THREADS || num_threads > MAX_THREADS) {
        printf("Invalid number of threads: %d\n", num_threads);
        exit(1);
    }

    // initialize the hash table for storing statistics for each session
    memset(session_stats, 0, sizeof(struct SessionStat *) * MAX_SESSIONS);

    // create the mutex and condition variable for protecting concurrent access to the hash table
    pthread_mutex_init(&stats_mtx, NULL);
    pthread_cond_init(&flush_cv, NULL);
}

// function to add statistics for a new session
void add_session(int session_id) {
    // acquire the lock on the hash table
    pthread_mutex_lock(&stats_mtx);

    // check if there is space available in the hash table
    if (session_stats[session_id] != NULL) {
        printf("Session %d already exists\n", session_id);
        pthread_mutex_unlock(&stats_mtx);
        return;
    }

    // allocate memory for the statistics structure and initialize it
    struct SessionStat *new_session = (struct SessionStat *) malloc(sizeof(struct SessionStat));
    new_session->session_id = session_id;
    new_session->bytes_received = 0;
    new_session->bytes_sent = 0;
    new_session->packets_received = 0;
    new_session->packets_sent = 0;

    // add the new session to the hash table
    session_stats[session_id] = new_session;

    // release the lock on the hash table
    pthread_mutex_unlock(&stats_mtx);
}

// function to remove statistics for a terminated session
void remove_session(int session_id) {
    // acquire the lock on the hash table
    pthread_mutex_lock(&stats_mtx);

    // check if there is a corresponding entry in the hash table
    if (session_stats[session_id] == NULL) {
        printf("Session %d does not exist\n", session_id);
        pthread_mutex_unlock(&stats_mtx);
        return;
    }

    // free the memory for the statistics structure
    free(session_stats[session_id]);

    // remove the entry from the hash table
    session_stats[session_id] = NULL;

    // release the lock on the hash table
    pthread_mutex_unlock(&stats_mtx);
}

// function to update statistics for a received packet
void receive_packet(int session_id, unsigned long long bytes) {
    // acquire the lock on the hash table
    pthread_mutex_lock(&stats_mtx);

    // check if there is a corresponding entry in the hash table
    if (session_stats[session_id] == NULL) {
        printf("Session %d does not exist\n", session_id);
        pthread_mutex_unlock(&stats_mtx);
        return;
    }

    // update the statistics for the received packet
    struct SessionStat *session = session_stats[session_id];
    session->bytes_received += bytes;
    session->packets_received++;

    // release the lock on the hash table
    pthread_mutex_unlock(&stats_mtx);
}

// function to update statistics for a sent packet
void send_packet(int session_id, unsigned long long bytes) {
    // acquire the lock on the hash table
    pthread_mutex_lock(&stats_mtx);

    // check if there is a corresponding entry in the hash table
    if (session_stats[session_id] == NULL) {
        printf("Session %d does not exist\n", session_id);
        pthread_mutex_unlock(&stats_mtx);
        return;
    }

    // update the statistics for the sent packet
    struct SessionStat *session = session_stats[session_id];
    session->bytes_sent += bytes;
    session->packets_sent++;

    // release the lock on the hash table
    pthread_mutex_unlock(&stats_mtx);
}

// function to flush accumulated statistics for all sessions
void flush_statistics() {
    // acquire the lock on the hash table
    pthread_mutex_lock(&stats_mtx);

    // iterate over all sessions and print their statistics
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_stats[i] != NULL) {
            struct SessionStat *session = session_stats[i];
            printf("Session %d: bytes received = %llu, packets received = %lu, bytes sent = %llu, packets sent = %lu\n",
                   session->session_id, session->bytes_received, session->packets_received,
                   session->bytes_sent, session->packets_sent);
        }
    }

    // reset the statistics for all sessions
    for (int i = 0; i < MAX_SESSIONS; i++) {
        if (session_stats[i] != NULL) {
            struct SessionStat *session = session_stats[i];
            session->bytes_received = 0;
            session->bytes_sent = 0;
            session->packets_received = 0;
            session->packets_sent = 0;
        }
    }

    // release the lock on the hash table
    pthread_mutex_unlock(&stats_mtx);
}
```

In this example, we have a `Stats` struct that contains four fields: `bytesReceived`, `packetsReceived`, `bytesSent`, and `packetsSent`. We use a mutex to ensure that only one thread can access the statistics at a time. Whenever a packet is received or sent, we update the corresponding field in the `Stats` struct.

To flush the statistics, we acquire the lock on the hash table using `pthread_mutex_lock(&statsMutex)`. We then iterate over all sessions and print their statistics. Finally, we reset the statistics for each session by setting their corresponding fields to zero. We release the lock on the hash table using `pthread_mutex_unlock(&statsMutex)` before returning from the function.

Note that in this example, we are using a simple mutex to protect access to the statistics. In a real-world application, you may want to use more advanced synchronization mechanisms such as condition variables or semaphores to handle more complex scenarios.']

