#include <netinet/in.h>
#include <arpa/inet.h>

#define MAX_CONNECTIONS 1024
#define TIMEOUT_SEC 60
#define BUFFER_SIZE 1024

typedef struct {
    int socket_id;
    struct sockaddr_in address;
} connection_t;

void manage_connections(int *num_connections, connection_t **connections) {
    // Initialize the array of connections if necessary
    if (*num_connections == 0) {
        *connections = malloc(MAX_CONNECTIONS * sizeof(connection_t));
    }

    // Handle new incoming connections
    int socket_id = accept(socket_fd, NULL, NULL);
    if (socket_id != -1) {
        connection_t new_connection;
        new_connection.socket_id = socket_id;
        new_connection.address = get_remote_addr(socket_id);
        connections[*num_connections] = new_connection;
        (*num_connections)++;
    }

    // Handle existing connections
    for (int i = 0; i < *num_connections; i++) {
        connection_t current_connection = connections[i];
        if (current_connection.socket_id == -1) continue;

        // Check for timeouts
        int seconds_since_last_message = get_seconds_since(current_connection.address);
        if (seconds_since_last_message > TIMEOUT_SEC) {
            close(current_connection.socket_id);
            current_connection.socket_id = -1;
            continue;
        }

        // Handle messages from clients
        char buffer[BUFFER_SIZE];
        int bytes_received = recv(current_connection.socket_id, buffer, BUFFER_SIZE, 0);
        if (bytes_received == -1) {
            perror("recv");
            continue;
        }

        // Send the received message back to the client
        send(current_connection.socket_id, buffer, bytes_received, 0);
    }
}

struct sockaddr_in get_remote_addr(int socket_id) {
    struct sockaddr_storage remote_addr;
    socklen_t addr_size = sizeof(struct sockaddr_storage);
    int result = getpeername(socket_id, (struct sockaddr *)&remote_addr, &addr_size);
    if (result == -1) {
        perror("getpeername");
        return;
    }
    struct sockaddr_in *addr = (struct sockaddr_in *)&remote_addr;
    return *addr;
}

int get_seconds_since(struct sockaddr_in address) {
    time_t current_time = time(NULL);
    int seconds_since = difftime(current_time, address.sin_ctime);
    return seconds_since;
}
