// Custom hash function for the hash table
unsigned long custom_hash(int key) {
    unsigned long result = 0;
    // Hashing strategy: XOR all bits of the key to generate a random-looking hash value
    for (int i = 0; i < sizeof(key); ++i) {
        result ^= ((unsigned long*) &key)[i];
    }
    return result;
}

// Struct to store record data
typedef struct {
    int key;
    long offset;
} record_t;

// Arrays for offsets, keys, and records
long* offsets = NULL;
int* keys = NULL;
record_t* records = NULL;
size_t num_records = 0;
size_t capacity = 16; // initial size of the arrays

// Hash table for fast lookups
struct hash_table {
    int* buckets[capacity]; // array of pointers to linked lists
    int num_buckets = capacity; // number of buckets in the hash table
    int mask = capacity - 1; // used for fast modulo operation
} hash_table;

// Initialize arrays and hash table with a specified number of records
void init(size_t num_records) {
    offsets = (long*) malloc(num_records * sizeof(long));
    keys = (int*) malloc(num_records * sizeof(int));
    records = (record_t*) malloc(num_records * sizeof(record_t));
    hash_table.buckets = (int**) malloc(hash_table.num_buckets * sizeof(int*));
    for (int i = 0; i < hash_table.num_buckets; ++i) {
        hash_table.buckets[i] = NULL;
    }
}

// Add a record to the arrays and hash table
void add(record_t r) {
    // Check for duplicate entries
    int key = r.key;
    if (hash_table.buckets[key & hash_table.mask] != NULL) {
        return;
    }
    // Add the record to the arrays and hash table
    offsets[num_records] = r.offset;
    keys[num_records] = key;
    records[num_records++] = r;
    int* bucket = &hash_table.buckets[key & hash_table.mask];
    *bucket = (int) malloc(sizeof(**bucket));
    (**bucket).key = key;
    (**bucket).offset = r.offset;
    (**bucket)++;
}

// Remove a record from the arrays and hash table
void remove(int key) {
    int* bucket = &hash_table.buckets[key & hash_table.mask];
    if (bucket == NULL) return;
    // Find the record with the given key in the linked list
    node_t* node = *bucket;
    while (node != NULL && node->next != NULL) {
        if (node->key == key) break;
        node = node->next;
    }
    // Remove the record from the linked list and free its memory
    if (node != NULL && node->next != NULL) {
        node_t* next = node->next;
        free(node);
        *bucket = next;
    }
}

// Look up a record in the hash table
record_t* lookup(int key) {
    int* bucket = &hash_table.buckets[key & hash_table.mask];
    if (bucket == NULL) return NULL;
    // Find the record with the given key in the linked list
    node_t* node = *bucket;
    while (node != NULL && node->next != NULL) {
        if (node->key == key) break;
        node = node->next;
    }
    // Return the record found or NULL
    return node == NULL ? NULL : &records[node->offset];
}

// Main function for testing and demonstration purposes
int main() {
    init(100);
    srand(time(NULL)); // seed random generator with current time
    int keys[] = {1, 2, 3, 4, 5};
    long offsets[] = {0, 1, 2, 3, 4};
    record_t records[] = {{1, 0}, {2, 1}, {3, 2}, {4, 3}, {5, 4}};
    for (int i = 0; i < 5; ++i) {
        add(records[i]);
    }
    for (int i = 0; i < 100; ++i) {
        printf("lookup(%d): %p\n", keys[i], lookup(keys[i]));
    }
}
