// Define a structure to store the CRC indication data
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a list data structure to store the NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size; // Size of the list
    int capacity; // Capacity of the list
    NFAPI_CRC_INDICATION_PDU_T* elements; // Pointer to an array of NFAPI_CRC_INDICATION_PDU_T structures
} List;

// Define a function to create and initialize a list
List* createList(int capacity) {
    if (capacity < 0) {
        return NULL;
    }

    // Allocate memory for the list data structure
    List* list = malloc(sizeof(List));
    if (!list) {
        fprintf(stderr, "Error: Failed to allocate memory for the list\n");
        return NULL;
    }

    // Initialize the list size and capacity
    list->size = 0;
    list->capacity = capacity;

    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * capacity);
    if (!list->elements) {
        fprintf(stderr, "Error: Failed to allocate memory for the list elements\n");
        free(list);
        return NULL;
    }

    // Initialize each element of the array with a random CRC flag
    srand(time(NULL));
    for (int i = 0; i < capacity; i++) {
        list->elements[i].crcflag = rand() % 2;
    }

    return list;
}

// Define a function to add an element to the list
bool addElement(List* list, RX_UE_INFORMATION_TAG tag, uint16_t rnti) {
    if (!list || list->size == list->capacity) {
        return false;
    }

    // Allocate memory for the new element
    NFAPI_CRC_INDICATION_PDU_T* newElement = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!newElement) {
        fprintf(stderr, "Error: Failed to allocate memory for the new element\n");
        return false;
    }

    // Initialize the new element with the specified tag and RNTI values
    newElement->tag = tag;
    newElement->rnti = rnti;
    newElement->crcflag = rand() % 2;

    // Add the new element to the list
    list->elements[list->size++] = *newElement;

    return true;
}

// Define a function to remove an element from the list
bool removeElement(List* list, int index) {
    if (!list || index < 0 || index >= list->size) {
        return false;
    }

    // Remove the specified element from the list
    NFAPI_CRC_INDICATION_PDU_T* removedElement = &list->elements[index];
    for (int i = index; i < list->size - 1; i++) {
        list->elements[i] = list->elements[i + 1];
    }
    list->size--;

    // Free the memory allocated for the removed element
    free(removedElement);

    return true;
}

// Define a function to iterate over the list without modifying it
bool iterateOverList(List* list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T*)) {
    if (!list || !callback) {
        return false;
    }

    // Iterate over each element in the list and pass it to the callback function
    for (int i = 0; i < list->size; i++) {
        callback(&list->elements[i]);
    }

    return true;
}

// Define a function to destroy the list and free its memory
void destroyList(List* list) {
    if (!list) {
        return;
    }

    // Free the memory allocated for the list elements
    for (int i = 0; i < list->size; i++) {
        free(&list->elements[i]);
    }

    // Free the memory allocated for the list data structure
    free(list);
}

// Define a function to log the creation of each NFAPI_CRC_INDICATION_PDU_T structure
void logElementCreation(NFAPI_CRC_INDICATION_PDU_T* element) {
    printf("Log: Created CRC indication PDU with tag %d, RNTI %d, and CRCFLAG %d\n", element->tag, element->rnti, element->crcflag);
}
