        if (offsets[i] >= 0) {
            packets[i].header = *(int*)((char*)buf + offsets[i]);
            packets[i].rnti = *(int*)((char*)buf + offsets[i] + sizeof(int));
            packets[i].crc_indication = *(int*)((char*)buf + offsets[i] + 2 * sizeof(int));
        } else {
            // Error in retrieving header, RNTI, or CRC indication. Return error status.
            return -1;
        }

        // Update arrays of offsets, keys, and custom entries.
        if (keys[i] >= 0) {
            entries[keys[i]].value = packets[i].header;
            entries[keys[i]].pointer = &packets[i].unique_id;
        } else {
            // Error in updating arrays of offsets, keys, and custom entries. Return error status.
            return -1;
        }

        // Perform processing on packet.
        int proc_status = processPacket(packets[i], &entries[keys[i]]);
        if (proc_status != 0) {
            status = -1;
        }
    }

    // Free memory allocated for packet structures and unique IDs.
    for (i = 0; i < n; i++) {
        free(packets[i].unique_id);
        packets[i].unique_id = NULL;
    }
    free(ids);

    // Free memory allocated for arrays of offsets, keys, and custom entries.
    free(offsets);
    free(keys);
    free(entries);

    // Close SSL connection.
    SSL_shutdown(ssl);
    SSL_free(ssl);
    close(sock);

    return status;
}
