// Define a hash table data structure to store the records
struct HashTable {
    int size;
    Record** buckets;
};

// Initialize a new hash table with a specified size
HashTable* create_hash_table(int size) {
    HashTable* table = (HashTable*)malloc(sizeof(HashTable));
    table->size = size;
    table->buckets = (Record**)calloc(size, sizeof(Record*));
    return table;
}

// Generate a random integer within the specified range
int get_random_int(int min, int max) {
    srand(time(NULL));
    return rand() % (max - min + 1) + min;
}

// Dynamically allocate memory for and initialize three arrays:
// one for 'long' offset values, one for 'int' keys, and another for 'record' structures
void init_arrays(Record** records, long* offsets, int* keys, int size) {
