    HashTable* table = create_hash_table(size);

    // Generate random values within the specified range for each key and record
    for (int i = 0; i < size; i++) {
        int key = get_random_int(0, INT_MAX);
        while (contains_key(table, key)) {
            key = get_random_int(0, INT_MAX);
