        record->value = get_random_int(-100, 100);
        records[i] = record;
        keys[i] = key;
        offsets[i] = i;
        insert(table, key, record);
    }
}

// Check if a given key already exists in the hash table
bool contains_key(HashTable* table, int key) {
    for (int i = 0; i < table->size; i++) {
        Record* record = table->buckets[i];
        while (record != NULL) {
            if (record->key == key) {
                return true;
            }
            record = record->next;
        }
    }
    return false;
}

// Insert a new record into the hash table with the given key and value
void insert(HashTable* table, int key, Record* record) {
    int index = key % table->size;
    record->next = table->buckets[index];
    table->buckets[index] = record;
}

// Free memory for the hash table and its contents
void free_hash_table(HashTable* table) {
    for (int i = 0; i < table->size; i++) {
        Record* record = table->buckets[i];
        while (record != NULL) {
            Record* next = record->next;
            free(record);
            record = next;
        }
    }
    free(table->buckets);
    free(table);
}

