struct nfapi_crc_indication_pdu_s {
    NFAPI_CRC_INDICATION_PDU_T pdu;
    struct nfapi_crc_indication_pdu_s *next;
};

struct list_node_s {
    struct nfapi_crc_indication_pdu_s *head;
    struct nfapi_crc_indication_pdu_s *tail;
    int size;
    pthread_mutex_t mutex;
};

void list_init(struct list_node_s *list, list_config_t config) {
    list->max_list_size = config.max_list_size;
    list->initial_buffer_size = config.initial_buffer_size;
    list->growth_increment = config.growth_increment;
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void list_insert(struct list_node_s *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    struct nfapi_crc_indication_pdu_s *new_node = malloc(sizeof(struct nfapi_crc_indication_pdu_s));
    new_node->pdu = *pdu;
    new_node->next = NULL;

    pthread_mutex_lock(&list->mutex);
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

void list_remove(struct list_node_s *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
    struct nfapi_crc_indication_pdu_s *current = list->head;
    struct nfapi_crc_indication_pdu_s *previous = NULL;

    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        if (current->pdu.tag == pdu->tag && current->pdu.rnti == pdu->rnti) {
            if (previous == NULL) {
                list->head = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            list->size--;
            break;
        }
        previous = current;
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}

void list_iterate(struct list_node_s *list, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    struct nfapi_crc_indication_pdu_s *current = list->head;

    pthread_mutex_lock(&list->mutex);
    while (current != NULL) {
        callback(&current->pdu);
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
}
