// Define the function to dynamically generate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T *generate_crc_indication_pdus(int num_pdus) {
  // Allocate memory for the array of PDUs
  NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T *)malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (!pdus) {
    return NULL;
  }

  // Initialize the PDUs
