    pdus[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG_CRC_INDICATION;
    pdus[i].rnti = rand() % UINT16_MAX;
    pdus[i].crc_indication_rel8_tag = rand() % UINT32_MAX;
  }

  // Implement asynchronous DNS resolution using a DNS cache table
  DNS_CACHE_TABLE_T *dns_cache = (DNS_CACHE_TABLE_T *)malloc(sizeof(DNS_CACHE_TABLE_T));
  if (!dns_cache) {
    free(pdus);
    return NULL;
  }

  // Initialize the DNS cache table
  dns_cache->num_entries = 0;
  dns_cache->entries = (DNS_CACHE_ENTRY_T *)malloc(16 * sizeof(DNS_CACHE_ENTRY_T));
  if (!dns_cache->entries) {
    free(pdus);
    free(dns_cache);
    return NULL;
  }

  // Populate the DNS cache table with hostname and IP address pairs
  for (int i = 0; i < num_pdus; i++) {
    char *hostname = "example.com";
    struct in_addr ip_address;
    int hostname_len = strlen(hostname);

    // Check if the hostname is already cached
    DNS_CACHE_ENTRY_T *cached_entry = find_dns_cache_entry(dns_cache, hostname, hostname_len);
    if (cached_entry) {
      ip_address = cached_entry->ip_address;
    } else {
      // Resolve the hostname to its IP address
      struct addrinfo hints, *result;
      memset(&hints, 0, sizeof(hints));
      hints.ai_family = AF_INET;
      hints.ai_socktype = SOCK_STREAM;
      if (getaddrinfo(hostname, NULL, &hints, &result) != 0) {
        continue;
      }

      // Cache the IP address for future use
      ip_address = *((struct in_addr *)result->ai_addr);
      freeaddrinfo(result);
    }

    // Set the DNS cache entry for the hostname
    cached_entry = find_dns_cache_entry(dns_cache, hostname, hostname_len);
    if (!cached_entry) {
      DNS_CACHE_ENTRY_T *new_entry = (DNS_CACHE_ENTRY_T *)malloc(sizeof(DNS_CACHE_ENTRY_T));
      new_entry->hostname = strdup(hostname);
      new_entry->hostname_len = hostname_len;
      new_entry->ip_address = ip_address;
      new_entry->last_resolved_time = time(NULL);
      dns_cache->entries[dns_cache->num_entries++] = *new_entry;
    } else {
      cached_entry->ip_address = ip_address;
      cached_entry->last_resolved_time = time(NULL);
    }
  }

  // Free the DNS cache table when it's no longer needed
  free(dns_cache);

  return pdus;
}

// Define the function to find a DNS cache entry in the table
DNS_CACHE_ENTRY_T *find_dns_cache_entry(DNS_CACHE_TABLE_T *dns_cache, char *hostname, int hostname_len) {
  for (int i = 0; i < dns_cache->num_entries; i++) {
    if (!strncmp(dns_cache->entries[i].hostname, hostname, hostname_len)) {
      return &dns_cache->entries[i];
    }
  }
  return NULL;
}
