    pool->pool = new_pool;
    pool->size = new_size;
  }
  // Allocate a new element in the pool
  uint32_t index = pool->used++;
  NFAPI_UL_RXINDICATION_PDU_T* pdu = &(pool->pool[index]);
  memset(pdu, 0, sizeof(NFAPI_UL_RXINDICATION_PDU_T));
  // Unlock the mutex for protecting access to the pool
