  // Lock the mutex for protecting access to the pool
  pthread_mutex_lock(&pool->mutex);
  // Release the element in the pool
  uint32_t index = pdu - pool->pool;
  pool->used--;
  // If the element is not at the end of the pool, move it to the end
  if (index < pool->used) {
