    memset(pemCert, 0, MAX_CERTIFICATE_SIZE);
    BIO_read(mem, pemCert, MAX_CERTIFICATE_SIZE - 1);

    // Free the memory allocated for the PEM structure and close file handles
    EVP_PKEY_free(pkey);
    RSA_free(rsa);
    X509_free(x509);
    fclose(keyFile);
    fclose(certFile);
    BIO_free(mem);

    // Return the PEM-formatted certificate string
    return pemCert;

error:
