    // Check if the theme is already loaded and load it if not
    if (!themeConfigRef->isLoaded()) {
        // Load the theme configuration
        if (themeConfigRef->load() != 0) {
            return 1;
        }
    }

    // Verify if a default theme directory is set in the configuration and initialize it to a specified default value if not
    if (themeConfigRef->getDefaultThemeDir() == NULL) {
        themeConfigRef->setDefaultThemeDir("default-theme");
    }

    // Create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
    List<NFAPI_CRC_INDICATION_PDU_T> crcIndications = new ArrayList<NFAPI_CRC_INDICATION_PDU_T>(N);
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu = new NFAPI_CRC_INDICATION_PDU_T();
        pdu.rx_ue_information.tag = RX_UE_INFORMATION_TAG;
        pdu.rx_ue_information.rnti = rand() % 10000000;
        pdu.crc_indication.tag = CRC_INDICATION_REL8_TAG;
        pdu.crc_indication.crflag = (rand() % 2 == 0) ? 1 : 0;
        crcIndications.add(pdu);
    }

    // Generate an MD5 hash of the stream metadata using a standard library cryptographic hash function
    unsigned char md5Hash[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    if (MD5_Init(&ctx) != 1) {
        return 1;
    }
    if (MD5_Update(&ctx, filePath, strlen(filePath)) != 1) {
        return 1;
    }
    if (MD5_Final(md5Hash, &ctx) != 1) {
        return 1;
    }

    // Convert the hash to a hexadecimal string and save it in the output directory
    char* md5HashStr = toHexString(md5Hash, MD5_DIGEST_LENGTH);
    FILE* fp = fopen(outputDir + "/" + md5HashStr + ".txt", "w");
    if (fp == NULL) {
        return 1;
    }
    fprintf(fp, "%s\n", md5HashStr);
    fclose(fp);

    // Check for potential integration issues with the third-party library and ensure efficient performance even with large-scale streaming data
    if (settings.useThirdPartyLibrary) {
        // Use a third-party media processing library to convert the stream data into the desired format
        MediaProcessingResult result = processMediaStream(filePath, settings);
        if (result.success == false) {
            return 1;
        }
    }

    return 0;
}
