// Structure to store connection metadata and handshake events
typedef struct {
    int socket;
    char* source_ip;
    char* destination_ip;
    unsigned short source_port;
    unsigned short destination_port;
    time_t timestamp;
    size_t buffer_size;
    void* buffer;
} TCP_SESSION;

// Function to initialize a new session
TCP_SESSION* init_session(int socket, char* source_ip, char* destination_ip, unsigned short source_port, unsigned short destination_port) {
    // Allocate memory for the session structure
    TCP_SESSION* session = malloc(sizeof(TCP_SESSION));
    if (session == NULL) {
        fprintf(stderr, "Failed to allocate memory for session\n");
        return NULL;
    }

    // Initialize the session fields
    session->socket = socket;
    session->source_ip = source_ip;
    session->destination_ip = destination_ip;
    session->source_port = source_port;
    session->destination_port = destination_port;
    session->timestamp = time(NULL);
    session->buffer_size = 0;
    session->buffer = NULL;

    return session;
}

// Function to add a handshake event to a session
void add_handshake(TCP_SESSION* session, char* source_ip, char* destination_ip, unsigned short source_port, unsigned short destination_port) {
    // Allocate memory for the new handshake event
    TCP_HANDSHAKE* handshake = malloc(sizeof(TCP_HANDSHAKE));
    if (handshake == NULL) {
        fprintf(stderr, "Failed to allocate memory for handshake\n");
        return;
    }

    // Initialize the new handshake event fields
    handshake->source_ip = source_ip;
    handshake->destination_ip = destination_ip;
    handshake->source_port = source_port;
    handshake->destination_port = destination_port;
    handshake->timestamp = time(NULL);

    // Add the new handshake event to the session's list of events
    session->handshakes = realloc(session->handshakes, (session->num_handshakes + 1) * sizeof(TCP_HANDSHAKE));
    if (session->handshakes == NULL) {
        fprintf(stderr, "Failed to reallocate memory for session's handshake list\n");
        free(handshake);
        return;
    }
    session->handshakes[session->num_handshakes] = handshake;
    session->num_handshakes++;
}

// Function to receive an incoming packet and update the session's buffer
void recv_packet(TCP_SESSION* session, void* data, size_t length) {
    // Update the session's buffer with the new packet data
    session->buffer = realloc(session->buffer, session->buffer_size + length);
    if (session->buffer == NULL) {
        fprintf(stderr, "Failed to reallocate memory for session's buffer\n");
        return;
    }
    memcpy(session->buffer + session->buffer_size, data, length);
    session->buffer_size += length;
}

// Function to clean up an inactive session and remove it from the session manager
void cleanup_session(TCP_SESSION* session) {
    // Free the memory used by the session's handshake events
    for (int i = 0; i < session->num_handshakes; i++) {
        free(session->handshakes[i]);
    }

    // Free the memory used by the session's buffer
    if (session->buffer != NULL) {
        free(session->buffer);
    }

    // Remove the session from the session manager
    sessions = realloc(sessions, (num_sessions - 1) * sizeof(TCP_SESSION*));
    if (sessions == NULL) {
        fprintf(stderr, "Failed to reallocate memory for session list\n");
        return;
    }
    num_sessions--;
}

// Function to periodically clean up inactive sessions based on their last activity timestamp
void cleanup_inactive_sessions() {
    time_t current_time = time(NULL);

    // Loop through the list of sessions and remove any that have not had any activity in the past N seconds
    for (int i = 0; i < num_sessions; i++) {
        if (sessions[i]->timestamp + SECONDS_INACTIVE < current_time) {
            cleanup_session(sessions[i]);
        }
    }
}
