// Structure definitions for LTE_PHY_RX_FRAME and LTE_PHY_RX_SYMBOL
typedef struct {
    int header;
    float signal_strength;
    int num_symbols;
    struct LTE_PHY_RX_SYMBOL* symbols;
} LTE_PHY_RX_FRAME;

typedef struct {
    int modulation_type;
    float phase_rotation;
    float noise_variance;
} LTE_PHY_RX_SYMBOL;

// Function definitions
void* frame_manager(void* arg) {
    // Cast the argument to a pointer to a list of frames
    LTE_PHY_RX_FRAME** frames = (LTE_PHY_RX_FRAME**)arg;

    // Initialize the mutex and condition variable for thread safety
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    // Loop indefinitely until a signal to exit is received
    while (1) {
        // Acquire the mutex before accessing the frame list
        pthread_mutex_lock(&mutex);

        // Check if there are any frames to process
        if (frames != NULL && frames[0] != NULL) {
            // Process each frame in the list
            for (int i = 0; i < sizeof(frames)/sizeof(frames[0]); i++) {
                LTE_PHY_RX_FRAME* frame = frames[i];

                // Check if the signal strength is above the threshold and not below the minimum value
                if (frame->signal_strength >= 0 && frame->signal_strength < MINIMUM_SIGNAL_STRENGTH) {
                    // Apply a discount to the signal strength based on the predefined threshold
                    frame->signal_strength -= DISCOUNT_FACTOR * (frame->signal_strength - MINIMUM_SIGNAL_STRENGTH);
                } else {
                    // Filter out any frames with a signal strength below the minimum value
                    frame = NULL;
                }
            }
        }

        // Release the mutex after processing the frames
        pthread_mutex_unlock(&mutex);

        // Wait for a signal to exit or process new frames
        pthread_cond_wait(&cond, &mutex);
    }

    return NULL;
}

void add_frame(LTE_PHY_RX_FRAME* frame) {
    // Acquire the mutex before accessing the frame list
    pthread_mutex_lock(&mutex);

    // Check if there is enough memory to allocate a new frame
    if (sizeof(frames)/sizeof(frames[0]) < MAXIMUM_NUM_FRAMES) {
        // Allocate memory for the new frame and copy the header, signal strength, and symbol list
        LTE_PHY_RX_FRAME* new_frame = malloc(sizeof(LTE_PHY_RX_FRAME));
        memcpy(new_frame, frame, sizeof(LTE_PHY_RX_FRAME));

        // Add the new frame to the list of frames
        frames[sizeof(frames)/sizeof(frames[0]) - 1] = new_frame;
    } else {
        printf("ERROR: Maximum number of frames exceeded\n");
    }

    // Release the mutex after adding the new frame
    pthread_mutex_unlock(&mutex);
}

void remove_frame(int index) {
    // Acquire the mutex before accessing the frame list
    pthread_mutex_lock(&mutex);

    // Check if the specified index is within the bounds of the list
    if (index < sizeof(frames)/sizeof(frames[0])) {
        // Free the memory for the removed frame and remove it from the list
        free(frames[index]);
        frames[index] = NULL;
    } else {
        printf("ERROR: Index out of bounds\n");
    }

    // Release the mutex after removing the frame
    pthread_mutex_unlock(&mutex);
}

void update_signal_strength(int index, float signal_strength) {
    // Acquire the mutex before accessing the frame list
    pthread_mutex_lock(&mutex);

    // Check if the specified index is within the bounds of the list
    if (index < sizeof(frames)/sizeof(frames[0])) {
        // Update the signal strength for the specified frame
        frames[index]->signal_strength = signal_strength;
    } else {
        printf("ERROR: Index out of bounds\n");
    }

    // Release the mutex after updating the signal strength
    pthread_mutex_unlock(&mutex);
}
