#define MAX_CRCFLAG_VALUES 2

typedef struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t rx_ue_information_tag;
    uint16_t rnti;
    uint8_t crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct NFAPI_CRC_INDICATION_PDU_ARRAY {
    NFAPI_CRC_INDICATION_PDU_T pdu[MAX_NFAPI_CRC_INDICATION_PDU_T];
    uint32_t count;
} NFAPI_CRC_INDICATION_PDU_ARRAY;

static NFAPI_CRC_INDICATION_PDU_ARRAY *nfapi_crc_indication_pdu_array = NULL;
static pthread_mutex_t nfapi_crc_indication_pdu_array_mutex = PTHREAD_MUTEX_INITIALIZER;

static bool is_rnti_valid(uint16_t rnti) {
    for (int i = 0; i < MAX_RNTI_VALUES; i++) {
        if (rnti == i) {
            return true;
        }
    }
    return false;
}

static bool is_crcflag_valid(uint8_t crcflag) {
    for (int i = 0; i < MAX_CRCFLAG_VALUES; i++) {
        if (crcflag == i) {
            return true;
        }
    }
    return false;
}

static bool is_duplicate_rnti(uint16_t rnti) {
    for (int i = 0; i < nfapi_crc_indication_pdu_array->count; i++) {
        if (nfapi_crc_indication_pdu_array->pdu[i].rnti == rnti) {
            return true;
        }
    }
    return false;
}

static void insert_nfapi_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    bool is_duplicate = false;
    pthread_mutex_lock(&nfapi_crc_indication_pdu_array_mutex);
    if (nfapi_crc_indication_pdu_array->count < MAX_NFAPI_CRC_INDICATION_PDU_T) {
        for (int i = 0; i < nfapi_crc_indication_pdu_array->count; i++) {
            if (nfapi_crc_indication_pdu_array->pdu[i].rnti == pdu->rnti) {
                is_duplicate = true;
                break;
            }
        }
        if (!is_duplicate) {
            nfapi_crc_indication_pdu_array->pdu[nfapi_crc_indication_pdu_array->count++] = *pdu;
        } else {
            printf("Duplicate RNTI detected, discarding CRC indication PDU\n");
        }
    } else {
        printf("CRC indication PDU array overflow, freeing memory to make space\n");
        nfapi_crc_indication_pdu_array = realloc(nfapi_crc_indication_pdu_array, (nfapi_crc_indication_pdu_array->count + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (nfapi_crc_indication_pdu_array != NULL) {
            nfapi_crc_indication_pdu_array->pdu[nfapi_crc_indication_pdu_array->count++] = *pdu;
        } else {
            printf("Failed to allocate memory for CRC indication PDU array\n");
        }
    }
    pthread_mutex_unlock(&nfapi_crc_indication_pdu_array_mutex);
}

static void log_crc_indication_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    printf("Logging CRC indication PDU: rx_ue_information_tag=%d, rnti=%d, crc_indication_rel8_tag=%d\n", pdu->rx_ue_information_tag, pdu->rnti, pdu->crc_indication_rel8_tag);
}

static void log_crc_indication_pdu_array() {
    for (int i = 0; i < nfapi_crc_indication_pdu_array->count; i++) {
        printf("Logging CRC indication PDU: rx_ue_information_tag=%d, rnti=%d, crc_indication_rel8_tag=%d\n", nfapi_crc_indication_pdu_array->pdu[i].rx_ue_information_tag, nfapi_crc_indication_pdu_array->pdu[i].rnti, nfapi_crc_indication_pdu_array->pdu[i].crc_indication_rel8_tag);
    }
}

void handle_nfapi_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (is_rnti_valid(pdu->rnti) && is_crcflag_valid(pdu->crc_indication_rel8_tag)) {
        insert_nfapi_crc_indication_pdu(pdu);
    } else {
        printf("Invalid RNTI or CRC indication REL8 tag detected, discarding CRC indication PDU\n");
    }
}

void log_crc_indication_statistics() {
    printf("Logging CRC indication statistics: total number of CRC indications=%d\n", nfapi_crc_indication_pdu_array->count);
}
