    uint8_t crcFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to create and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* createAndPopulateNfapiCrcIndicationPduArray(uint32_t numElements, uint8_t crcFlag) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* nfapiCrcIndicationPduArray = (NFAPI_CRC_INDICATION_PDU_T*) malloc(numElements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (nfapiCrcIndicationPduArray == NULL) {
        printf("Error: Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T structure array\n");
        return NULL;
    }

    // Populate the array with valid RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG values
    uint32_t i = 0;
    for (i = 0; i < numElements; i++) {
        nfapiCrcIndicationPduArray[i].rnti = i + 1; // Start from 1 to avoid conflicts with RNTI values used in the system
        nfapiCrcIndicationPduArray[i].crcFlag = crcFlag;
    }

    return nfapiCrcIndicationPduArray;
}

// Function to generate CRCFLAG values using a pseudo-random number generator seeded with a unique value for each invocation
uint8_t generateCrcflagValue(uint32_t numElements, uint32_t randomSeed) {
    srand(randomSeed); // Seed the PRNG with the provided value to ensure reproducibility

    uint8_t crcFlag = 0;
    uint32_t i = 0;
    for (i = 0; i < numElements; i++) {
        crcFlag |= ((uint8_t) rand() % 2); // Generate a random bit for the CRCFLAG field
    }

    return crcFlag;
}

// Function to handle potential alignment issues across various hardware architectures
void* alignMemory(void* memPtr, size_t alignment) {
    if (memPtr == NULL) {
        printf("Error: Memory pointer is NULL\n");
        return NULL;
    }

    size_t memSize = sizeof(*memPtr);
    size_t misalignment = (size_t) memPtr % alignment;
    if (misalignment == 0) { // No alignment issues
        return memPtr;
    } else { // Misaligned memory pointer, need to align it
        void* alignedMemPtr = NULL;
        size_t paddingBytes = alignment - misalignment;
        alignedMemPtr = malloc(memSize + paddingBytes);
        if (alignedMemPtr == NULL) {
            printf("Error: Memory allocation failed for aligned memory pointer\n");
            return NULL;
