} NFAPI_CRC_INDICATION_PDU_T;

// Array to hold the CRC indication data
NFAPI_CRC_INDICATION_PDU_T* crc_array = NULL;
size_t crc_array_size = 0; // current size of the array
size_t crc_array_max_size = 1000000; // maximum allowed size of the array

// Thread-safe data structure for concurrent access
pthread_mutex_t crc_mutex = PTHREAD_MUTEX_INITIALIZER;

void manage_crc_array(NFAPI_CRC_INDICATION_PDU_T* pdu, size_t size) {
  // Validate input parameters
  if (pdu == NULL || size == 0) {
    return;
  }

  // Lock the mutex to ensure thread-safe access
  pthread_mutex_lock(&crc_mutex);

  // Check for out-of-bounds access
  if (size > crc_array_max_size) {
    printf("Error: CRC array size exceeds maximum allowed size\n");
    pthread_mutex_unlock(&crc_mutex);
    return;
  }

  // Check for allocation failure
  if (crc_array == NULL) {
    crc_array = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (crc_array == NULL) {
      printf("Error: Failed to allocate CRC array\n");
      pthread_mutex_unlock(&crc_mutex);
      return;
    }
  }

  // Update the current size of the array
  crc_array_size = size;

  // Reset the CRCFLAG in case of duplicate RNTIs
  for (int i = 0; i < crc_array_size; i++) {
    if (pdu->RNTI == crc_array[i].RNTI) {
      crc_array[i].CRCFLAG = 0;
    }
  }

  // Add the new PDU to the array
  memcpy(&crc_array[crc_array_size - size], pdu, size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

  // Unlock the mutex
  pthread_mutex_unlock(&crc_mutex);
}
