// Product structure to store product information
struct Product {
    char* name;
    double price;
    struct Date release_date;
};

// NFAPI_CRC_INDICATION_PDU_T structure to store CRC indication data
struct NFAPI_CRC_INDICATION_PDU_T {
    unsigned int rx_ue_information_tag;
    unsigned int rnti;
    struct CRC_INDICATION_REL8_TAG crc_indication_rel8;
};

// Date structure to store date information
struct Date {
    unsigned int year;
    unsigned int month;
    unsigned int day;
};

// Function to dynamically allocate memory for a collection of Product structures
void* allocProducts(unsigned int num_products) {
    // Allocate memory for the array of Product structures
    void* products = malloc(num_products * sizeof(struct Product));
    if (!products) {
        perror("Error allocating memory for products");
        exit(EXIT_FAILURE);
    }
    return products;
}

// Function to initialize the fields of a Product structure from a CSV file
void initProduct(struct Product* product, char* name, double price, struct Date release_date) {
    // Copy the name and price values into the Product structure
    product->name = strdup(name);
    product->price = price;
    product->release_date.year = release_date.year;
    product->release_date.month = release_date.month;
    product->release_date.day = release_date.day;
}

// Function to dynamically allocate memory for a list of NFAPI_CRC_INDICATION_PDU_T structures
void* allocNFAPICRCIndications(unsigned int num_indications) {
    // Allocate memory for the array of NFAPI_CRC_INDICATION_PDU_T structures
    void* nfapi_crc_indications = malloc(num_indications * sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
    if (!nfapi_crc_indications) {
        perror("Error allocating memory for NFAPI CRC indications");
        exit(EXIT_FAILURE);
    }
    return nfapi_crc_indications;
}

// Function to initialize the fields of an NFAPI_CRC_INDICATION_PDU_T structure from a CSV file
void initNFAPICRCIndication(struct NFAPI_CRC_INDICATION_PDU_T* nfapi_crc_indication, unsigned int rx_ue_information_tag, unsigned int rnti) {
    // Set the RX_UE_INFORMATION_TAG and RNTI values
    nfapi_crc_indication->rx_ue_information_tag = rx_ue_information_tag;
    nfapi_crc_indication->rnti = rnti;

    // Set a randomly set CRCFLAG value
    nfapi_crc_indication->crc_indication_rel8.crcflag = rand() % 2 ? true : false;
}

// Function to calculate the average price of products released within a specified year range
double getAveragePrice(struct Product* products, unsigned int num_products, unsigned int start_year, unsigned int end_year) {
    double total_price = 0.0;
    unsigned int count = 0;

    // Iterate over the products and calculate the average price
    for (unsigned int i = 0; i < num_products; ++i) {
        struct Product* product = &products[i];
        if (product->release_date.year >= start_year && product->release_date.year <= end_year) {
            total_price += product->price;
            count++;
        }
    }

    // Return the average price of products released within the specified year range
    return count == 0 ? -1 : total_price / (double)count;
}

// Function to identify the most frequently occurring product name across all products and return this information along with the average price
struct ProductInfo getMostFrequentProduct(struct Product* products, unsigned int num_products) {
    struct ProductInfo info;
    memset(&info, 0, sizeof(info));

    // Initialize the most frequently occurring product name and count to empty strings and zero
    info.name = "";
    info.count = 0;

    // Iterate over the products and keep track of the most frequently occurring product name
    for (unsigned int i = 0; i < num_products; ++i) {
        struct Product* product = &products[i];
        if (product->name != NULL && strlen(product->name) > 0) {
            unsigned int count = getProductCount(products, num_products, product->name);
            if (count > info.count) {
                info.name = product->name;
                info.count = count;
            }
        }
    }

    // Return the most frequently occurring product name and its count along with the average price
    return info;
}

// Function to get the number of products with a given name
unsigned int getProductCount(struct Product* products, unsigned int num_products, char* name) {
    unsigned int count = 0;

    // Iterate over the products and count those with the given name
    for (unsigned int i = 0; i < num_products; ++i) {
        struct Product* product = &products[i];
