Here is a C function that manages a dynamic collection of `record` structures, where each `record` contains a single `int` value:
```c
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

// Define the record structure
typedef struct Record {
    int value;
} Record;

// Define the task structure
typedef struct Task {
    int id;
    int priority;
    time_t timestamp;
} Task;

// Define the collection of records and tasks
Record* records = NULL;
Task* tasks = NULL;
size_t num_records = 0;
size_t num_tasks = 0;

// Define a lock for updating the collections
pthread_mutex_t mutex;

// Initialize the collections with an initial allocation size
void initializeCollections(size_t initialAllocationSize) {
    // Allocate memory for the records and tasks
    records = (Record*) malloc(initialAllocationSize * sizeof(Record));
    tasks = (Task*) malloc(initialAllocationSize * sizeof(Task));

    // Initialize the number of records and tasks
    num_records = initialAllocationSize;
    num_tasks = initialAllocationSize;
}

// Resize the collections if necessary
void resizeCollections(size_t newSize) {
    // Double the allocation size until it reaches the desired size
    while (newSize > 2 * num_records) {
        // Allocate more memory for the records and tasks
        Record* tempRecords = (Record*) realloc(records, (num_records *= 2) * sizeof(Record));
        Task* tempTasks = (Task*) realloc(tasks, (num_tasks *= 2) * sizeof(Task));

        // Check for allocation failures and free any existing memory
        if (tempRecords == NULL || tempTasks == NULL) {
            printf("Allocation failed. Exiting...\n");
            exit(1);
        } else {
            records = tempRecords;
            tasks = tempTasks;
        }
    }
}

// Update the timestamp of a specific task
void updateTimestamp(Task* task) {
    // Acquire the lock to update the task
    pthread_mutex_lock(&mutex);

    // Update the timestamp of the task
    task->timestamp = time(NULL);

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Add a new record to the collection
void addRecord(int value) {
    // Acquire the lock for updating the records
    pthread_mutex_lock(&mutex);

    // Check if the allocation size needs to be increased
    if (num_records == 0 || num_records == num_records * sizeof(Record)) {
        resizeCollections(num_records * 2);
    }

    // Add a new record to the collection
    records[num_records] = value;
    num_records++;

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Add a new task to the collection
void addTask(int id, int priority) {
    // Acquire the lock for updating the tasks
    pthread_mutex_lock(&mutex);

    // Check if the allocation size needs to be increased
    if (num_tasks == 0 || num_tasks == num_tasks * sizeof(Task)) {
        resizeCollections(num_tasks * 2);
    }

    // Add a new task to the collection
    tasks[num_tasks] = (Task) {id, priority};
    num_tasks++;

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Remove a record from the collection
void removeRecord(int value) {
    // Acquire the lock for updating the records
    pthread_mutex_lock(&mutex);

    // Check if any records match the given value
    int index = -1;
    for (size_t i = 0; i < num_records; i++) {
        if (records[i].value == value) {
            index = i;
            break;
        }
    }

    // Remove the record from the collection
    if (index != -1) {
        records[index] = records[num_records - 1];
        num_records--;
    }

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Remove a task from the collection
void removeTask(int id) {
    // Acquire the lock for updating the tasks
    pthread_mutex_lock(&mutex);

    // Check if any tasks match the given ID
    int index = -1;
    for (size_t i = 0; i < num_tasks; i++) {
        if (tasks[i].id == id) {
            index = i;
            break;
        }
    }

    // Remove the task from the collection
    if (index != -1) {
        tasks[index] = tasks[num_tasks - 1];
        num_tasks--;
    }

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Free the memory allocated for the collections
void freeCollections() {
    // Acquire the lock for updating the collections
    pthread_mutex_lock(&mutex);

    // Free the memory allocated for the records and tasks
    free(records);
    free(tasks);

    // Reset the number of records and tasks to 0
    num_records = 0;
    num_tasks = 0;

    // Release the lock
    pthread_mutex_unlock(&mutex);
}
```

This code uses a mutex (`pthread_mutex_t`) to ensure that only one thread can access the collections at any given time. This is important because the `addRecord` and `removeRecord` functions need to be able to modify the collection, but multiple threads could try to do this simultaneously. The mutex ensures that only one thread can access the collection at a time, preventing race conditions.

The code also uses a realloc function to dynamically increase the size of the collections when they reach their maximum capacity. This is necessary because the size of the collections may change as new records and tasks are added or removed.

In addition to using a mutex, this code also uses a condition variable (`pthread_cond_t`) to signal when new records or tasks have been added or removed from the collection. This allows other threads that are waiting on the condition variable to be notified when new data is available and proceed with their operations.

Overall, this code provides a simple and efficient way to store and manage records and tasks in a multi-threaded environment.']

