struct Customer {
    char* name;
    double balance;
    struct Address details;
};

struct PaymentTransaction {
    long id;
    double amount;
    time_t timestamp;
};

void parseJSON(const json_object* obj, struct Customer* customer) {
    // Parse JSON object to extract name, balance, and address details.
    json_object_object_foreach(obj, key, val) {
        if (strcmp(key, "name") == 0) {
            customer->name = strdup(json_object_get_string(val));
        } else if (strcmp(key, "balance") == 0) {
            customer->balance = json_object_get_double(val);
        } else if (strcmp(key, "details") == 0) {
            parseJSON(json_object_get_object(val), &customer->details);
        }
    }
}

void parseJSONTransactions(const json_array* transactions, struct PaymentTransaction* paymentTransactions) {
    // Parse JSON array to extract transaction IDs, amounts, and timestamps.
    for (int i = 0; i < json_object_array_length(transactions); i++) {
        const json_object* obj = json_object_array_get_idx(transactions, i);
        struct PaymentTransaction transaction = {
            .id = json_object_get_int64(json_object_object_get(obj, "transactionId")),
            .amount = json_object_get_double(json_object_object_get(obj, "amount")),
            .timestamp = json_object_get_int64(json_object_object_get(obj, "timestamp"))
        };
        paymentTransactions[i] = transaction;
    }
}

void calculateAverageBalance(struct Customer* customers, int numCustomers) {
    // Calculate the average balance of customers who made transactions in the last 30 days.
    long totalTransactions = 0;
    double totalBalance = 0.0;
    for (int i = 0; i < numCustomers; i++) {
        struct Customer* customer = &customers[i];
        time_t now = time(NULL);
        if (now - customer->details.timestamp <= LAST_30_DAYS) {
            totalTransactions++;
            totalBalance += customer->balance;
        }
    }
    double averageBalance = 0.0;
    if (totalTransactions > 0) {
        averageBalance = totalBalance / totalTransactions;
    }
    printf("Average balance of customers who made transactions in the last 30 days: %.2f\n", averageBalance);
}

void identifyHighestTransactionVolumeCustomer(struct Customer* customers, int numCustomers) {
    // Identify the customer with the highest total transaction volume.
    struct Customer* highestVolumeCustomer = NULL;
    long highestTotalTransactions = 0;
    for (int i = 0; i < numCustomers; i++) {
        struct Customer* customer = &customers[i];
        if (customer->numTransactions > highestTotalTransactions) {
            highestVolumeCustomer = customer;
            highestTotalTransactions = customer->numTransactions;
        }
    }
    printf("Highest transaction volume customer: %s\n", highestVolumeCustomer->name);
}

int main() {
    // Read JSON data from external payment processor.
    json_object* root = json_object_from_file("data/transactions.json");
    if (!root) {
        fprintf(stderr, "Failed to read JSON data from file\n");
        return 1;
    }

    // Parse JSON data and extract necessary information.
    struct Customer* customers = calloc(MAX_CUSTOMERS, sizeof(struct Customer));
    if (!customers) {
        fprintf(stderr, "Failed to allocate memory for customer data\n");
        return 1;
    }
    int numCustomers = json_object_array_length(json_object_object_get(root, "customers"));
    json_object* transactions = json_object_object_get(root, "transactions");
    struct PaymentTransaction* paymentTransactions = calloc(MAX_TRANSACTIONS, sizeof(struct PaymentTransaction));
    if (!paymentTransactions) {
        fprintf(stderr, "Failed to allocate memory for transaction data\n");
        return 1;
    }
    int numTransactions = json_object_array_length(transactions);

    parseJSON(json_object_get_object(root, "customers"), customers);
    parseJSONTransactions(transactions, paymentTransactions);

    // Populate transaction data for each customer.
    for (int i = 0; i < numCustomers; i++) {
        struct Customer* customer = &customers[i];
        customer->numTransactions = 0;
        for (int j = 0; j < numTransactions; j++) {
            if (strcmp(customer->name, paymentTransactions[j].customerName) == 0) {
                customer->transactions[customer->numTransactions] = paymentTransactions[j];
                customer->numTransactions++;
            }
        }
    }

    // Calculate average balance and identify highest transaction volume customer.
    calculateAverageBalance(customers, numCustomers);
    identifyHighestTransactionVolumeCustomer(customers, numCustomers);

    free(root);
    free(customers);
    free(paymentTransactions);

    return 0;
}
