        }

        // Populate the UserSession structure with parsed information
        user_sessions[i].username = username;
        user_sessions[i].session_id = session_id;
        user_sessions[i].login_time = login_time;
        user_sessions[i].logout_time = logout_time;

        i++;
    }

    return user_sessions;
}

// Function to calculate the average duration of active sessions within a specified time window
double get_average_session_duration(UserSession *user_sessions, int num_sessions, struct Timestamp time_window) {
    // Calculate the total number of sessions within the time window
    int total_sessions = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (time_window.year > user_sessions[i].login_time.year || time_window.month > user_sessions[i].login_time.month || time_window.day > user_sessions[i].login_time.day) {
            continue;
        }
        total_sessions++;
    }

    // Calculate the total duration of active sessions within the time window
    double total_duration = 0;
    for (int i = 0; i < num_sessions; i++) {
        if (time_window.year > user_sessions[i].login_time.year || time_window.month > user_sessions[i].login_time.month || time_window.day > user_sessions[i].login_time.day) {
            continue;
        }
        total_duration += (user_sessions[i].logout_time.second - user_sessions[i].login_time.second) + ((user_sessions[i].logout_time.minute - user_sessions[i].login_time.minute) * 60) + ((user_sessions[i].logout_time.hour - user_sessions[i].login_time.hour) * 3600);
    }

    // Return the average duration of active sessions within the time window
    return total_duration / total_sessions;
}

