};

struct RollingStats {
    int successfulAllocations;
    int failedAllocations;
};

void initList(List *list) {
    list->head = NULL;
    list->tail = NULL;
}

bool isFull(List *list) {
    return (list->head == NULL && list->tail == NULL);
}

CrcIndicationNode *allocateNode() {
    CrcIndicationNode *node = malloc(sizeof(CrcIndicationNode));
    if (!node) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    node->ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!node->ptr) {
        perror("malloc failed");
        free(node);
        exit(EXIT_FAILURE);
    }

    // Set RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG with a randomly set CRCFLAG
    node->ptr->rx_ue_information_tag = rand() % 100;
    node->ptr->rnti = rand() % 10000;
    node->ptr->crc_indication_rel8_tag.crcflag = rand() % 2;

    return node;
}

void freeNode(CrcIndicationNode *node) {
    if (!node) {
        perror("freeNode failed");
        exit(EXIT_FAILURE);
    }

    free(node->ptr);
    free(node);
}

void addToTail(List *list, CrcIndicationNode *node) {
    if (!list || !node) {
        perror("addToTail failed");
        exit(EXIT_FAILURE);
    }

    if (list->tail == NULL) {
        list->head = node;
    } else {
        list->tail->next = node;
    }

    list->tail = node;
}

void removeFromHead(List *list, CrcIndicationNode **node) {
    if (!list || !node) {
        perror("removeFromHead failed");
        exit(EXIT_FAILURE);
    }

    if (list->head == NULL) {
        return;
    }

    *node = list->head;
    list->head = (*node)->next;
    if (list->tail == *node) {
        list->tail = NULL;
    }
}

void threadSafeAddToTail(List *list, CrcIndicationNode *node) {
    pthread_mutex_lock(&list->mutex);
    addToTail(list, node);
    pthread_mutex_unlock(&list->mutex);
}

void threadSafeRemoveFromHead(List *list, CrcIndicationNode **node) {
    pthread_mutex_lock(&list->mutex);
    removeFromHead(list, node);
    pthread_mutex_unlock(&list->mutex);
}

void updateRollingStats(struct RollingStats *stats, bool success) {
    if (success) {
        stats->successfulAllocations++;
    } else {
        stats->failedAllocations++;
    }
}

void main() {
    List list;
    initList(&list);

    struct RollingStats stats = {0};

    while (true) {
        CrcIndicationNode *node = allocateNode();
        if (!node) {
            updateRollingStats(&stats, false);
            continue;
        }

        threadSafeAddToTail(&list, node);

        updateRollingStats(&stats, true);
    }
}
