// Define the structure for scheduling requests
typedef struct {
    int TX_STREAM_ID;
    int SUBFRAME_NUMBER;
    int SCH_INFO_TAG;
} PHY_TASK_SCHEDULING_REQUEST_T;

// Define the pool of scheduling requests
PHY_TASK_SCHEDULING_REQUEST_T scheduling_requests[50000];

// Function to initialize and manage the pool of scheduling requests
void init_scheduling_pool(int num_entries) {
    // Initialize all entries in the pool as invalid
    for (int i = 0; i < num_entries; i++) {
        scheduling_requests[i].TX_STREAM_ID = -1;
        scheduling_requests[i].SUBFRAME_NUMBER = -1;
        scheduling_requests[i].SCH_INFO_TAG = -1;
    }
}

// Function to add a new scheduling request to the pool
void add_scheduling_request(int TX_STREAM_ID, int SUBFRAME_NUMBER, int SCH_INFO_TAG) {
    // Check if there is space in the pool for the new request
    if (num_entries < 50000) {
        // Find a free entry in the pool and initialize it
        int i;
        for (i = 0; i < num_entries; i++) {
            if (scheduling_requests[i].TX_STREAM_ID == -1 && scheduling_requests[i].SUBFRAME_NUMBER == -1) {
                break;
            }
        }
        // If a free entry was found, initialize it and increment the number of entries
        if (i < num_entries) {
            scheduling_requests[i].TX_STREAM_ID = TX_STREAM_ID;
            scheduling_requests[i].SUBFRAME_NUMBER = SUBFRAME_NUMBER;
            scheduling_requests[i].SCH_INFO_TAG = SCH_INFO_TAG;
            num_entries++;
        } else {
            // If no free entry was found, log an appropriate message and return
            printf("Pool is full\n");
        }
    } else {
        // If the pool is already at maximum capacity, log an appropriate message and return
        printf("Pool is already full\n");
    }
}

// Function to check for duplicates in the scheduling pool
void check_duplicates(int TX_STREAM_ID, int SUBFRAME_NUMBER) {
    // Iterate over all entries in the pool and compare the given TX stream ID and subframe number with each entry
    for (int i = 0; i < num_entries; i++) {
        if (scheduling_requests[i].TX_STREAM_ID == TX_STREAM_ID && scheduling_requests[i].SUBFRAME_NUMBER == SUBFRAME_NUMBER) {
            // If a duplicate is found, log an appropriate message and return
            printf("Duplicate pair detected: TX stream ID %d, subframe number %d\n", TX_STREAM_ID, SUBFRAME_NUMBER);
        }
    }
}

// Function to remove a scheduling request from the pool
void remove_scheduling_request(int index) {
    // Check if the index is within the bounds of the pool
    if (index >= 0 && index < num_entries) {
        // If the index is valid, move all subsequent entries in the pool to fill the gap
        for (int i = index; i < num_entries - 1; i++) {
            scheduling_requests[i] = scheduling_requests[i + 1];
        }
        // Decrement the number of entries in the pool
        num_entries--;
    } else {
        // If the index is invalid, log an appropriate message and return
        printf("Index out of bounds\n");
    }
}
```
