Product* read_products(int num_products, FILE *stream) {
    // Calculate the total size required for all product structures
    size_t struct_size = sizeof(Product) * num_products;

    // Allocate memory for the array of products
    Product* products = (Product*)malloc(struct_size);
    if (!products) {
        fprintf(stderr, "Error: Failed to allocate memory for %d products\n", num_products);
        return NULL;
    }

    // Initialize the cache of recently accessed products
    Product* cache = (Product*)malloc(struct_size);
    if (!cache) {
        fprintf(stderr, "Error: Failed to allocate memory for product cache\n");
        free(products);
        return NULL;
    }

    // Read the data from the stream and populate the products array
    int i = 0;
    while (fscanf(stream, "%s %lf %d", &products[i].name, &products[i].price, &products[i].stock_quantity) == 3 && i < num_products) {
        // Apply a tiered pricing strategy based on the stock quantity
        if (products[i].stock_quantity >= 10) {
            products[i].price = products[i].price * 0.8;
        } else if (products[i].stock_quantity >= 5) {
            products[i].price = products[i].price * 0.95;
        }

        // Add the product to the cache
        cache[i] = products[i];
        i++;
    }

    // Free the memory used by the cache if it is not needed anymore
    if (i < num_products) {
        free(cache);
    }

    return products;
}

// Function to calculate the total revenue expected from selling all products at their adjusted prices
double get_total_revenue(Product* products, int num_products) {
    double total_revenue = 0.0;
    for (int i = 0; i < num_products; i++) {
        total_revenue += products[i].price * products[i].stock_quantity;
    }
    return total_revenue;
}

// Function to handle network errors or partial data received during read_products()
int handle_network_errors(Product* products, int num_products) {
    // Check for network errors by reading the error code from errno
    if (errno != 0) {
        fprintf(stderr, "Error: Network error occurred while reading data\n");
        return -1;
    }

    // Check for partial data received during read_products()
    if (num_products < 0) {
        fprintf(stderr, "Error: Partial data received from network stream\n");
        return -2;
    }

    return num_products;
}
