            pdu_list[i].RNTI = rand() % 65535 + 1;
            pdu_list[i].CRCFLAG = (pdu_list[i - 1].CRCFLAG == 0) ? 1 : 0;
        }
    }

    // Release lock on list to allow other threads to modify it concurrently
    pthread_mutex_unlock(&mutex);
}

// Define function to integrate with external logging system for record keeping
void log_pdu_list(NFAPI_CRC_INDICATION_PDU_T* pdu_list, uint32_t num_unique_rnti) {
    // Acquire lock on list to prevent concurrent modifications
    pthread_mutex_lock(&mutex);

    // Iterate through list and record each PDU's RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values in external logging system
    for (uint32_t i = 0; i < num_unique_rnti; i++) {
        // Record current PDU's RX_UE_INFORMATION_TAG, RNTI, and CRCFLAG values in external logging system
        printf("RX_UE_INFORMATION_TAG: %d\n", pdu_list[i].RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", pdu_list[i].RNTI);
        printf("CRCFLAG: %d\n", pdu_list[i].CRCFLAG);
    }

    // Release lock on list to allow other threads to modify it concurrently
    pthread_mutex_unlock(&mutex);
}
