// Define the probability distribution for setting CRCFLAG
static const double crcflag_prob = 0.01; // Probability of setting CRCFLAG to true

int create_records(size_t n, size_t* offset_arr, int* key_arr, record_t** record_arr) {
    // Validate input
    if (n < 1 || n > 100000) {
        printf("Invalid value for N: %lu\n", n);
        return -1;
    }

    // Dynamically allocate memory for the arrays
    offset_arr = malloc(sizeof(size_t) * n);
    key_arr = malloc(sizeof(int) * n);
    record_arr = malloc(sizeof(record_t*) * n);

    if (offset_arr == NULL || key_arr == NULL || record_arr == NULL) {
        printf("Memory allocation failed\n");
        return -1;
    }

    // Initialize the arrays with random values within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < n; ++i) {
        offset_arr[i] = rand() % 100000 + 1;
        key_arr[i] = rand() % 100000 + 1;
        record_arr[i] = malloc(sizeof(record_t));
        if (record_arr[i] == NULL) {
            printf("Memory allocation failed\n");
            return -1;
        }
        record_arr[i]->value = rand() % 100000 + 1;
        record_arr[i]->key = key_arr[i];
        record_arr[i]->offset = offset_arr[i];
    }

    // Set CRCFLAG to true with a probability of crcflag_prob
    if (rand() % 100 < crcflag_prob * 100) {
        for (size_t i = 0; i < n; ++i) {
            record_arr[i]->CRCFLAG = true;
        }
    }

    return 0;
}

void free_records(size_t n, size_t* offset_arr, int* key_arr, record_t** record_arr) {
    // Free the memory allocated for the arrays
    for (size_t i = 0; i < n; ++i) {
        free(record_arr[i]);
    }
    free(offset_arr);
    free(key_arr);
    free(record_arr);
}
