    // Add a new session info to the map
    void addSessionInfo(const UE_SESSION_INFO& sessionInfo) {
        std::unique_lock<std::mutex> lock(mMutex);
        mSessionMap[sessionInfo.UE_ID] = sessionInfo;
    }

    // Look up a session info by its UE ID
