        std::unique_lock<std::mutex> lock(mMutex);
        auto it = mSessionMap.find(UE_ID);
        if (it != mSessionMap.end()) {
            return &(it->second);
        } else {
            return nullptr;
        }
    }

    // Remove a session info by its UE ID
    void removeSessionInfo(int UE_ID) {
        std::unique_lock<std::mutex> lock(mMutex);
        auto it = mSessionMap.find(UE_ID);
        if (it != mSessionMap.end()) {
            mSessionMap.erase(it);
        }
    }

