        std::unique_lock<std::mutex> lock(mMutex);
        mSessionCache.push_back(sessionInfo);
    }

    // Look up a session info by its UE ID in the cache
    const UE_SESSION_INFO* lookupSessionInfo(int UE_ID) {
        std::unique_lock<std::mutex> lock(mMutex);
        for (auto& session : mSessionCache) {
            if (session.UE_ID == UE_ID) {
                return &session;
            }
        }
        return nullptr;
    }

    // Remove a session info by its UE ID from the cache
