        crc_indications[i].CRCFLAG = (rand() & 1) ? 1 : 0; // Generate a random CRCFLAG for each PDU
    }

    // Check for duplicates in the array of CRC indication PDUs
    for (int i = 0; i < N - 1; ++i) {
        for (int j = i + 1; j < N; ++j) {
            if (crc_indications[i].RX_UE_INFORMATION_TAG == crc_indications[j].RX_UE_INFORMATION_TAG ||
                crc_indications[i].RNTI == crc_indications[j].RNTI) {
