// Function to add a new structure to the collection
NFAPIDataStruct *nfapi_add_structure(uint16_t id, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the structure already exists in the cache
    NFAPIDataStruct *existing = nfapi_find_structure(id);
    if (existing != NULL) {
        existing->pdu = pdu;
    } else {
        // Allocate memory for the new structure
        NFAPIDataStruct *new_struct = malloc(sizeof(NFAPIDataStruct));
        if (new_struct == NULL) {
            perror("Failed to allocate memory");
            return NULL;
        }

        // Initialize the structure with the provided data
        new_struct->id = id;
        new_struct->pdu = pdu;

        // Add the new structure to the cache
        nfapi_add_to_cache(new_struct);
    }

    // Release lock and return the structure
    pthread_mutex_unlock(&mutex);
    return existing != NULL ? existing : new_struct;
}

// Function to update an existing structure in the collection
NFAPIDataStruct *nfapi_update_structure(uint16_t id, NFAPI_CRC_INDICATION_PDU_T pdu) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the structure in the cache and update its data
    NFAPIDataStruct *struct = nfapi_find_structure(id);
    if (struct != NULL) {
        struct->pdu = pdu;
    } else {
        perror("Failed to find structure");
    }

    // Release lock and return the updated structure
    pthread_mutex_unlock(&mutex);
    return struct;
}

// Function to remove a structure from the collection
void nfapi_remove_structure(uint16_t id) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the structure in the cache and remove it
    NFAPIDataStruct *struct = nfapi_find_structure(id);
    if (struct != NULL) {
        free(struct->data);
        struct->count--;

        // If the cache is half full, compact it to prevent memory fragmentation
        if (cache.capacity / 2 == cache.count) {
            nfapi_compact_cache();
        }
    } else {
        perror("Failed to find structure");
    }

    // Release lock
    pthread_mutex_unlock(&mutex);
}

// Function to find a structure in the collection by its ID
NFAPIDataStruct *nfapi_find_structure(uint16_t id) {
    // Acquire lock to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Iterate over the cache and find the structure with the matching ID
    NFAPIDataStruct *struct = NULL;
    for (size_t i = 0; i < cache.count; i++) {
        if (cache.data[i].id == id) {
            struct = &cache.data[i];
            break;
        }
    }

    // Release lock and return the structure
    pthread_mutex_unlock(&mutex);
    return struct;
}

// Function to add a new structure to the cache
void nfapi_add_to_cache(NFAPIDataStruct *struct) {
    // Check if the cache has reached its maximum capacity
    if (cache.count == cache.capacity) {
        // If so, evict the least recently used entry from the cache
        NFAPIDataStruct *lru = nfapi_find_lru_entry();
        free(lru->data);
        lru->count--;

        // Compact the cache to prevent memory fragmentation
        nfapi_compact_cache();
    }

    // Add the new structure to the cache
    cache.data[cache.count++] = *struct;
}

// Function to find the least recently used entry in the cache
NFAPIDataStruct *nfapi_find_lru_entry() {
    // Initialize a variable to keep track of the LRU entry
    NFAPIDataStruct *lru = NULL;

    // Iterate over the cache and find the least recently used entry
    for (size_t i = 0; i < cache.count; i++) {
        if (lru == NULL || cache.data[i].usage_map < lru->usage_map) {
            lru = &cache.data[i];
        }
    }

    // Return the LRU entry
    return lru;
}

// Function to compact the cache by relocating entries to a smaller memory space
void nfapi_compact_cache() {
    // Allocate a new buffer for the compacted cache
    NFAPIDataStruct *new_data = malloc(sizeof(NFAPIDataStruct) * cache.count);
    if (new_data == NULL) {
        perror("Failed to allocate memory");
        return;
    }

    // Copy the structures from the old buffer to the new one, updating their usage maps
    for (size_t i = 0; i < cache.count; i++) {
        new_data[i] = cache.data[i];
        new_data[i].usage_map = 0;
    }

    // Free the old buffer and update the cache's data and capacity
    free(cache.data);
    cache.data = new_data;
    cache.capacity = cache.count;
}
