// Define the structure to represent a spatial entry
typedef struct {
    double value;
    char flag;
    struct point {
        float x, y;
    } *coordinates;
} entry;

void load_data(entry **entries, size_t num_entries) {
    // Load data from a CSV file and allocate memory for each entry
    FILE *file = fopen("input.csv", "r");
    assert(file != NULL);

    // Initialize the number of entries to 0
    size_t i = 0;

    // Read each line in the file and parse it into a spatial entry
    char buffer[1024];
    while (fgets(buffer, sizeof(buffer), file) != NULL) {
        // Skip empty lines or lines that start with a comment symbol
        if (strlen(buffer) == 0 || buffer[0] == '#') {
            continue;
        }

        // Allocate memory for the current entry
        entry *new_entry = malloc(sizeof(entry));
        assert(new_entry != NULL);

        // Parse the line into the entry structure
        char *token = strtok(buffer, ",");
        new_entry->value = atof(token);

        token = strtok(NULL, ",");
        new_entry->flag = (char) atoi(token);

        token = strtok(NULL, ",");
        new_entry->coordinates = malloc(sizeof(struct point));
        assert(new_entry->coordinates != NULL);

        token = strtok(NULL, ",\n");
        new_entry->coordinates->x = atof(token);

        token = strtok(NULL, "\n");
        new_entry->coordinates->y = atof(token);

        // Add the entry to the list of entries
        entries[i] = new_entry;

        i++;
    }

    fclose(file);
}

void free_data(entry **entries, size_t num_entries) {
    for (size_t i = 0; i < num_entries; i++) {
        entry *entry = entries[i];
        if (entry != NULL) {
            free(entry->coordinates);
            free(entry);
        }
    }
}

int main() {
    // Load the data from the CSV file and initialize the spatial entries
    size_t num_entries = 0;
    entry **entries = malloc(sizeof(entry *) * num_entries);
    load_data(entries, num_entries);

    // Print out each spatial entry
    for (size_t i = 0; i < num_entries; i++) {
        printf("%f %c (%f, %f)\n", entries[i]->value, entries[i]->flag,
               entries[i]->coordinates->x, entries[i]->coordinates->y);
    }

    // Free the memory allocated for the spatial entries
    free_data(entries, num_entries);

    return 0;
}
