#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <errno.h>

// Structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
  uint16_t RX_UE_INFORMATION_TAG;
  uint16_t RNTI;
  uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to dynamically allocate and populate an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateAndPopulateArray(int n) {
  // Check if the input value is valid
  if (n < 0 || n > 65535) {
    return NULL;
  }

  // Allocate memory for the array of structures
  NFAPI_CRC_INDICATION_PDU_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
  if (array == NULL) {
    fprintf(stderr, "Error: Memory allocation failed\n");
    return NULL;
  }

  // Initialize the array of structures with default values
  for (int i = 0; i < n; i++) {
    array[i].RX_UE_INFORMATION_TAG = 0;
    array[i].RNTI = 0;
    array[i].CRCFLAG = false;
  }

  // Populate the array with random values for RNTI and CRCFLAG, while ensuring unique values for RNTI and TAC/PCI
  srand(time(NULL)); // Initialize the random number generator
  int numUniqueRNTIs = 0;
  int numUniqueTACs = 0;
  int numUniquePCIs = 0;
  for (int i = 0; i < n; i++) {
    // Generate a random RNTI value within the range of 0x0000 to 0xFFFF
    uint16_t rnti = rand() % 0x10000;

    // Check if the generated RNTI value is already present in the array
    bool foundRNTI = false;
    for (int j = 0; j < i; j++) {
      if (array[j].RNTI == rnti) {
        foundRNTI = true;
        break;
      }
    }

    // If the generated RNTI value is not already present, add it to the array and increment the counter
    if (!foundRNTI) {
      array[i].RNTI = rnti;
      numUniqueRNTIs++;
