    struct HashTable* hash_table = (struct HashTable*) malloc(sizeof(struct HashTable));
    hash_table->num_buckets = 10;
    hash_table->load_factor_threshold = 0.75;

    // Initialize the linked lists for each bucket in the hash table
    LinkedList** buckets = (LinkedList**) malloc(sizeof(LinkedList*) * hash_table->num_buckets);
    for (int i = 0; i < hash_table->num_buckets; i++) {
        buckets[i] = NULL;
    }

    // Initialize the mutex for thread safety
    pthread_mutex_init(&hash_table->mutex, NULL);

    // Populate the hash table with unique user IDs for testing
    populateHashTable(hash_table);

    // Insert a new user session into the hash table
