typedef struct {
  NFAPI_CRC_INDICATION_PDU_T *pdu;
  bool is_used;
} PDU_ENTRY;

// Define a list structure to store the PDUs
typedef struct {
  PDU_ENTRY *entries;
  size_t count;
  pthread_mutex_t mutex;
} PDU_LIST;

void add_pdu(PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *pdu) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Check if the RNTI is already in use and if so, log an error message
  for (size_t i = 0; i < list->count; i++) {
    if (list->entries[i].is_used && list->entries[i].pdu->rnti == pdu->rnti) {
      printf("Duplicate RNTI detected in PDU list\n");
      return;
    }
  }

  // Add the new PDU to the list and set its is_used flag to true
  PDU_ENTRY *entry = malloc(sizeof(PDU_ENTRY));
  entry->pdu = pdu;
  entry->is_used = true;
  list->entries[list->count++] = *entry;

  // Release the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}

void remove_pdu(PDU_LIST *list, size_t index) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Set the is_used flag for the specified PDU entry to false and free its memory
  if (index < list->count && index >= 0) {
    list->entries[index].is_used = false;
    free(list->entries[index].pdu);
    list->entries[index] = (PDU_ENTRY){NULL, false};
  }

  // Release the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}

void clear_pdu(PDU_LIST *list) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Free all memory associated with the PDUs in the list and set their is_used flags to false
  for (size_t i = 0; i < list->count; i++) {
    if (list->entries[i].is_used) {
      free(list->entries[i].pdu);
      list->entries[i] = (PDU_ENTRY){NULL, false};
    }
  }

  // Release the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}

void garbage_collect(PDU_LIST *list) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Iterate over the PDUs in the list and free any unused ones
  for (size_t i = 0; i < list->count; i++) {
    if (!list->entries[i].is_used) {
      free(list->entries[i].pdu);
      list->entries[i] = (PDU_ENTRY){NULL, false};
    }
  }

  // Release the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}

void monitor_pdu(PDU_LIST *list) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Check if the number of PDUs in the list exceeds the threshold and trigger garbage collection if so
  if (list->count > GARBAGE_COLLECTION_THRESHOLD) {
    garbage_collect(list);
  }

  // Release the mutex to allow other threads to access the list
  pthread_mutex_unlock(&list->mutex);
}

void create_pdu_list() {
  PDU_LIST *list = malloc(sizeof(PDU_LIST));
  list->entries = malloc(MAX_PDU_COUNT * sizeof(PDU_ENTRY));
  for (size_t i = 0; i < MAX_PDU_COUNT; i++) {
    list->entries[i] = (PDU_ENTRY){NULL, false};
  }
  list->count = 0;
  pthread_mutex_init(&list->mutex, NULL);
}

void destroy_pdu_list(PDU_LIST *list) {
  // Acquire the mutex to prevent concurrent modification of the list
  pthread_mutex_lock(&list->mutex);

  // Clear and free all memory associated with the PDUs in the list
  for (size_t i = 0; i < list->count; i++) {
    if (list->entries[i].is_used) {
      free(list->entries[i].pdu);
      list->entries[i] = (PDU_ENTRY){NULL, false};
    }
  }
  pthread_mutex_unlock(&list->mutex);

  // Release the mutex to allow other threads to access the list
  pthread_mutex_destroy(&list->mutex);
}
