  // Find the PDU in the list and remove it
  if (pdu == list->head) {
    list->head = pdu->next;
  } else {
    NFAPI_CRC_INDICATION_PDU_T *prev = list->head;
    while (prev != NULL && prev->next != pdu) {
      prev = prev->next;
    }
    if (prev == NULL) {
      fprintf(stderr, "Error: PDU not found in the list\n");
      sem_post(&lock);
      return;
    }
    prev->next = pdu->next;
  }
  list->size--;

  // Release the lock and free the memory
  sem_post(&lock);
  free(pdu);
}
