    // Array of event structures
    nicp_event_t* events[MAX_EVENTS];
    // Number of used slots in the array
    int num_used;
    // Mutex for protecting concurrent access to the data structure
    pthread_mutex_t mutex;
} event_manager_t;

// Initialize and manage a scalable collection of NICP events
void init_event_manager(event_manager_t* manager) {
    // Initialize the array of event structures to NULL pointers
    for (int i = 0; i < MAX_EVENTS; i++) {
        manager->events[i] = NULL;
    }
    // Set the number of used slots to zero
    manager->num_used = 0;
    // Initialize the mutex for protecting concurrent access to the data structure
    pthread_mutex_init(&manager->mutex, NULL);
}

// Add a new NICP event to the collection
void add_event(event_manager_t* manager, nicp_event_t event) {
    // Acquire the mutex for protecting concurrent access to the data structure
    pthread_mutex_lock(&manager->mutex);
    // Check if there is space in the array for a new event
    if (manager->num_used < MAX_EVENTS) {
        // Allocate memory for the new event and copy the contents of the given event
        manager->events[manager->num_used] = malloc(sizeof(nicp_event_t));
        memcpy(manager->events[manager->num_used], &event, sizeof(nicp_event_t));
        // Increment the number of used slots
        manager->num_used++;
    } else {
        // If there is no space in the array, log an error and do nothing
        fprintf(stderr, "No space left in event manager\n");
    }
    // Release the mutex for protecting concurrent access to the data structure
    pthread_mutex_unlock(&manager->mutex);
}

