    // Acquire the mutex for protecting concurrent access to the data structure
    pthread_mutex_lock(&manager->mutex);
    // Search for the event with the given MAC address and delete it if found
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (strcmp(manager->events[i]->mac, mac) == 0) {
            free(manager->events[i]);
            manager->events[i] = NULL;
            break;
        }
    }
    // Decrement the number of used slots
    manager->num_used--;
    // Release the mutex for protecting concurrent access to the data structure
    pthread_mutex_unlock(&manager->mutex);
}

// Check if a NICP event exists in the collection
