    // Search for the event with the given MAC address and return true if found
    for (int i = 0; i < MAX_EVENTS; i++) {
        if (strcmp(manager->events[i]->mac, mac) == 0) {
            pthread_mutex_unlock(&manager->mutex);
            return 1;
        }
