    EventLogEntry* entries[QUEUE_SIZE]; // Array of pointers to EventLogEntry structures
    int head; // Index of the first entry in the queue
    int tail; // Index of the last entry in the queue
    int size; // Current size of the queue
} NetworkEventQueue;

// Initialize a new network event queue with a given maximum size
void initializeNetworkEventQueue(NetworkEventQueue* queue, int maxSize) {
    queue->entries = (EventLogEntry**)malloc(maxSize * sizeof(EventLogEntry*));
    queue->head = 0;
    queue->tail = -1;
    queue->size = 0;
}

// Add a new network event log entry to the queue, allocating memory as needed
int addNetworkEvent(NetworkEventQueue* queue, EventLogEntry* entry) {
