        // Grow the queue by a factor of QUEUE_GROWTH_FACTOR
        EventLogEntry** newEntries = (EventLogEntry**)malloc(QUEUE_GROWTH_FACTOR * QUEUE_SIZE * sizeof(EventLogEntry*));
        memcpy(newEntries, queue->entries, QUEUE_SIZE * sizeof(EventLogEntry*));
        free(queue->entries);
        queue->entries = newEntries;
    }

    // Check if the queue is empty and needs to be initialized
    if (queue->tail == -1) {
        initializeNetworkEventQueue(queue, maxSize);
    }

    // Allocate memory for the new entry
    EventLogEntry* newEntry = (EventLogEntry*)malloc(sizeof(EventLogEntry));
    memcpy(newEntry, entry, sizeof(EventLogEntry));

    // Add the new entry to the queue
    if (queue->tail == QUEUE_SIZE - 1) {
        queue->tail = 0;
    } else {
        ++queue->tail;
    }
    queue->entries[queue->tail] = newEntry;

    // Increment the size of the queue
    ++queue->size;

    return ret;
}

// Remove a network event log entry from the queue, reusing memory as needed
int removeNetworkEvent(NetworkEventQueue* queue, EventLogEntry* entry) {
    int ret = 0;

    // Check if the queue is empty
    if (queue->size == 0) {
        return -1;
    }

    // Get the index of the entry to be removed
    int index = queue->head;

    // Remove the entry from the queue
    if (index == QUEUE_SIZE - 1) {
        queue->tail = -1;
    } else {
        ++queue->head;
    }
    --queue->size;

    // Reuse the memory for the removed entry, if possible
    EventLogEntry* freedEntry = (EventLogEntry*)malloc(sizeof(EventLogEntry));
    memcpy(freedEntry, queue->entries[index], sizeof(EventLogEntry));
    free(queue->entries[index]);
    queue->entries[index] = freedEntry;

    return ret;
}

// Check if a given IP address is already in the queue
int checkNetworkEventQueue(NetworkEventQueue* queue, char* ipAddress) {
    int ret = -1;

    // Iterate over the entries in the queue
    for (int i = 0; i < QUEUE_SIZE && ret == -1; ++i) {
        EventLogEntry* entry = queue->entries[i];
        if (strcmp(entry->sourceIP, ipAddress) == 0 || strcmp(entry->destIP, ipAddress) == 0) {
            ret = i;
        }
    }

    return ret;
}

// Print a network event log entry
void printNetworkEventLogEntry(EventLogEntry* entry) {
    printf("[%d] ", entry->timestamp);
    printf("[Source: %s, Destination: %s]", entry->sourceIP, entry->destIP);
}

// Print the contents of a network event queue
void printNetworkEventQueue(NetworkEventQueue* queue) {
    // Iterate over the entries in the queue
    for (int i = 0; i < QUEUE_SIZE && i < queue->size; ++i) {
        EventLogEntry* entry = queue->entries[i];
        printNetworkEventLogEntry(entry);
        printf("\n");
    }
}
