TCP_CONNECTION* init_connection(uint32_t connection_id, int socket_desc) {
    // Allocate memory for the connection structure
    TCP_CONNECTION* connection = (TCP_CONNECTION*)malloc(sizeof(TCP_CONNECTION));
    if (!connection) {
        return NULL;
    }

    // Initialize the connection ID and socket descriptor
    connection->connection_id = connection_id;
    connection->socket_desc = socket_desc;

    // Initialize the packet list with an initial capacity of 10 packets
    connection->packet_count = 0;
    connection->packet_capacity = 10;
    connection->packets = (TCP_PACKET**)malloc(sizeof(TCP_PACKET*) * connection->packet_capacity);
    if (!connection->packets) {
        free(connection);
        return NULL;
    }

    // Initialize the packet list with a single element
    TCP_PACKET* new_packet = (TCP_PACKET*)malloc(sizeof(TCP_PACKET));
    if (!new_packet) {
        free(connection->packets);
        free(connection);
        return NULL;
    }
    connection->packets[0] = new_packet;

    // Return the initialized connection structure
    return connection;
}
