// Define a structure to store information about an NFAPI_CRC_INDICATION_PDU
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a structure to store information about the UE
typedef struct {
    int rnti;
    char* name;
} UE_INFO;

// Define a hash table to map RNTIs to UE information
HASHTABLE* ue_hash = NULL;

// Define a function to initialize the hashtable
void init_hashtable() {
    // Allocate memory for the hashtable
    ue_hash = (HASHTABLE*)malloc(sizeof(HASHTABLE));
    if (!ue_hash) {
        printf("Failed to allocate memory for hashtable\n");
        return;
    }

    // Initialize the hashtable with an initial size of 1000
    hash_init(ue_hash, 1000);
}

// Define a function to add a UE to the hashtable
void add_ue(int rnti, char* name) {
    // Check if the hashtable is initialized
    if (!ue_hash) {
        printf("Hashtable not initialized\n");
        return;
    }

    // Create a new UE information structure
    UE_INFO* ue = (UE_INFO*)malloc(sizeof(UE_INFO));
    if (!ue) {
        printf("Failed to allocate memory for UE information\n");
        return;
    }

    // Initialize the UE information structure
    ue->rnti = rnti;
    ue->name = name;

    // Add the UE information to the hashtable
    hash_insert(ue_hash, (void*)rnti, ue);
}

// Define a function to retrieve a UE from the hashtable
UE_INFO* get_ue(int rnti) {
    // Check if the hashtable is initialized
    if (!ue_hash) {
        printf("Hashtable not initialized\n");
        return NULL;
    }

    // Retrieve the UE information from the hashtable
    void* data = hash_lookup(ue_hash, (void*)rnti);
    if (!data) {
        printf("Failed to retrieve UE information for RNTI %d\n", rnti);
        return NULL;
    }

    // Cast the retrieved data to a UE_INFO structure
    UE_INFO* ue = (UE_INFO*)data;

    // Return the UE information structure
    return ue;
}

// Define a function to allocate memory for an array of NFAPI_CRC_INDICATION_PDUs
void* alloc_pdu_array(int num_pdus) {
    // Allocate memory for the array of PDUS
    void* pdu_array = malloc(num_pdus * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu_array) {
        printf("Failed to allocate memory for PDU array\n");
        return NULL;
    }

    // Initialize the PDUs in the array
    for (int i = 0; i < num_pdus; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &((NFAPI_CRC_INDICATION_PDU_T*)pdu_array)[i];
        // Initialize the RX_UE_INFORMATION_TAG field
        pdu->rx_ue_information_tag = 0;
        // Initialize the RNTI field
        pdu->rnti = -1;
        // Initialize the CRC_INDICATION_REL8_TAG field
        pdu->crc_indication_rel8_tag = 0;
    }

    return pdu_array;
}

// Define a function to free memory for an array of NFAPI_CRC_INDICATION_PDUs
void free_pdu_array(void* pdu_array) {
    // Check if the PDU array is null
    if (!pdu_array) {
        printf("Cannot free a null PDU array\n");
        return;
    }

    // Free the memory allocated for the PDUs in the array
    free(pdu_array);
}

// Define a function to generate a random CRC flag
