void add_frame(phy_rx_frame_t *frame) {
    // Lock the cache and check if there is space in the cache
    pthread_mutex_lock(&caching.lock);
    if (caching.capacity > 0 && caching.cache[caching.size] == NULL) {
        // Add the frame to the cache
        caching.cache[caching.size++] = frame;
        pthread_mutex_unlock(&caching.lock);
    } else {
        // Lock the memory pool and add the frame to the pool
        pthread_mutex_lock(&memory_pool.lock);
        if (memory_pool.capacity > 0 && memory_pool.frames[memory_pool.size] == NULL) {
            memory_pool.frames[memory_pool.size++] = frame;
            pthread_mutex_unlock(&memory_pool.lock);
        } else {
            // Unlock the cache and memory pool and add the frame to the queue
            pthread_mutex_unlock(&caching.lock);
            pthread_mutex_unlock(&memory_pool.lock);
            thread_queue_push(frame);
        }
    }
}

// Remove a PHY RX frame from the collection
void remove_frame(phy_rx_frame_t *frame) {
    // Lock the cache and check if the frame is in the cache
    pthread_mutex_lock(&caching.lock);
    for (int i = 0; i < caching.size; i++) {
        if (caching.cache[i] == frame) {
            // Remove the frame from the cache and return
            caching.cache[i] = NULL;
            pthread_mutex_unlock(&caching.lock);
            return;
        }
    }

    // Lock the memory pool and check if the frame is in the pool
    pthread_mutex_lock(&memory_pool.lock);
    for (int i = 0; i < memory_pool.size; i++) {
