// Function to serialize a list of records to a file
int saveRecords(const char* filename, int numRecords, Record** records) {
    // Validate input parameters
    if (numRecords < 1 || numRecords > 10000) {
        return -1;
    }

    // Open the file for writing and validate it
    FILE* fp = fopen(filename, "wb");
    if (fp == NULL) {
        return -2;
    }

    // Write the number of records to the file
    size_t bytesWritten = fwrite(&numRecords, sizeof(int), 1, fp);
    if (bytesWritten != 1) {
        fclose(fp);
        return -3;
    }

    // Write each record to the file
    for (int i = 0; i < numRecords; i++) {
        bytesWritten = fwrite(*records[i], sizeof(Record), 1, fp);
        if (bytesWritten != 1) {
            fclose(fp);
            return -4;
        }
    }

    // Close the file and return success
    fclose(fp);
    return 0;
}

// Function to deserialize a list of records from a file
int loadRecords(const char* filename, int* numRecords, Record*** records) {
    // Validate input parameters
    if (numRecords == NULL || records == NULL) {
        return -1;
    }

    // Open the file for reading and validate it
    FILE* fp = fopen(filename, "rb");
    if (fp == NULL) {
        return -2;
    }

    // Read the number of records from the file
    size_t bytesRead = fread(numRecords, sizeof(int), 1, fp);
    if (bytesRead != 1) {
        fclose(fp);
        return -3;
    }

    // Allocate memory for the array of pointers to records
    *records = malloc(sizeof(Record*) * (*numRecords));
    if (*records == NULL) {
        fclose(fp);
        return -4;
    }

    // Read each record from the file and initialize it
    for (int i = 0; i < *numRecords; i++) {
        (*records)[i] = malloc(sizeof(Record));
        if ((*records)[i] == NULL) {
            fclose(fp);
            return -5;
        }
        bytesRead = fread(*records[i], sizeof(Record), 1, fp);
        if (bytesRead != 1) {
            fclose(fp);
            return -6;
        }
    }

    // Close the file and return success
    fclose(fp);
    return 0;
}

// Function to compare two timestamps for sorting purposes
int compareTimestamps(const void* a, const void* b) {
    Record* recordA = (Record*)a;
    Record* recordB = (Record*)b;
    if (recordA->timestamp > recordB->timestamp) {
        return 1;
    } else if (recordA->timestamp < recordB->timestamp) {
        return -1;
    } else {
        return 0;
    }
}
