typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    int size;
} CRC_INDICATION_LIST_T;

void init_crc_indication_list(CRC_INDICATION_LIST_T *list) {
    list->data = NULL;
    list->size = 0;
}

void add_crc_indication_pdu(CRC_INDICATION_LIST_T *list, NFAPI_CRC_INDICATION_PDU_T pdu) {
    if (list->data == NULL) {
        list->data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(list->data, &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        NFAPI_CRC_INDICATION_PDU_T *new_data = realloc(list->data, (list->size + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_data == NULL) {
            fprintf(stderr, "Failed to allocate memory for CRC indication list\n");
            return;
        }
        memcpy(&new_data[list->size], &pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        list->data = new_data;
    }
    list->size++;
}

void free_crc_indication_list(CRC_INDICATION_LIST_T *list) {
    if (list->data != NULL) {
        free(list->data);
        list->data = NULL;
        list->size = 0;
    }
}

int main(void) {
    CRC_INDICATION_LIST_T list;
    init_crc_indication_list(&list);

    // Generate random data for the CRC indications
    srand(time(NULL));
    int num_crcs = 10;
    for (int i = 0; i < num_crcs; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        pdu.rx_ue_information_tag = rand();
        pdu.rnti = rand() % 10000;
        pdu.crc_indication_rel8_tag.crcflag = rand() % 2 ? 1 : 0;
        add_crc_indication_pdu(&list, pdu);
    }

    // Validate the uniqueness of the keys
    for (int i = 0; i < list.size; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list.data[i];
        if (pdu->rx_ue_information_tag == pdu->rnti) {
            free_crc_indication_list(&list);
            return -1;
        }
    }

    // Free any allocated memory for the list
    free_crc_indication_list(&list);

    return 0;
}
