    for (int i = 0; i < max_size; i++) {
        records[i].value = rand() % (max_range - min_range) + min_range;
    }

    return records;
}

// Check if the key is already in the array and generate a new key if it is not unique
bool unique_key(int* keys, int index, int key) {
