    int value;
    struct Node* next;
};

// Define a function to dynamically allocate memory for a list of Nodes
struct Node* create_node_list(int num_nodes, int min_key_len, int max_key_len, int value_range) {
    // Check if the input parameters are valid
    if (num_nodes <= 0 || min_key_len < 5 || max_key_len > 10 || value_range < 0) {
        printf("Invalid input parameters. Please enter positive integers for number of nodes, minimum key length, maximum key length, and value range.\n");
        return NULL;
    }

    // Initialize a pointer to the head of the list
    struct Node* head = NULL;

    // Dynamically allocate memory for each node in the list
    struct Node** nodes = malloc(num_nodes * sizeof(struct Node));
    if (nodes == NULL) {
        printf("Error: Unable to allocate memory for node list.\n");
        return NULL;
    }

    // Initialize each node with a random key and value within the specified range
    for (int i = 0; i < num_nodes; i++) {
        int key_len = min_key_len + (rand() % (max_key_len - min_key_len));
        char* key = malloc(key_len * sizeof(char));
        if (key == NULL) {
            printf("Error: Unable to allocate memory for node key.\n");
            return NULL;
        }
        for (int j = 0; j < key_len; j++) {
            key[j] = 'a' + (rand() % 26); // Generate a random character within the alphabet
        }

        int value = rand() % value_range; // Generate a random integer within the range

        nodes[i] = malloc(sizeof(struct Node));
        if (nodes[i] == NULL) {
            printf("Error: Unable to allocate memory for node.\n");
            return NULL;
        }

        nodes[i]->key = key;
        nodes[i]->value = value;
        nodes[i]->next = NULL;

        // Link each node to form a singly linked list
        if (head == NULL) {
            head = nodes[i];
        } else {
            nodes[i - 1]->next = nodes[i];
        }
    }

    // Free dynamically allocated memory for the key and next pointers of each node upon function exit
    struct Node* curr_node = head;
    while (curr_node != NULL) {
        free(curr_node->key);
        if (curr_node->next != NULL) {
            free(curr_node->next);
        }
        curr_node = curr_node->next;
    }
    free(nodes);

    return head;
}
```
This function takes in four parameters: `num_nodes`, which specifies the total number of nodes to be created, `min_key_len` and `max_key_len`, which specify the minimum and maximum length of keys, respectively, and `value_range`, which specifies the range of random values for the `value` field.

The function first checks if the input parameters are valid by ensuring that `num_nodes > 0`, `min_key_len >= 5`, `max_key_len <= 10`, and `value_range >= 0`. If any of these conditions is not met, the function prints an error message and returns NULL.

