    // Check for duplicates and regenerate strings if necessary
    for (int i = 0; i < NUM_ITEMS - 1; i++) {
        for (int j = i + 1; j < NUM_ITEMS; j++) {
            if (strcmp((*record_array)[i]->string, (*record_array)[j]->string) == 0) {
