void init_record_array(Record** arr, size_t max_size) {
    *arr = malloc(max_size * sizeof(Record));
    if (*arr == NULL) {
        fprintf(stderr, "Failed to allocate memory for record array: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    memset(*arr, 0, max_size * sizeof(Record));
}

