    record->string = malloc(strlen("Example String") * sizeof(char));
    if (record->string == NULL) {
        fprintf(stderr, "Failed to allocate memory for string: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }
    // Initialize the string with a random value
    sprintf(record->string, "%d", record->value);
}

// Function to deallocate memory for an array of 'long' offset values
void free_offset_array(long** arr) {
    if (*arr != NULL) {
        free(*arr);
        *arr = NULL;
    }
}

// Function to deallocate memory for an array of 'int' keys
void free_key_array(int** arr) {
    if (*arr != NULL) {
        free(*arr);
        *arr = NULL;
    }
}

