    if (*arr != NULL) {
        for (size_t i = 0; i < max_size; i++) {
            if ((*arr)[i].string != NULL) {
                free((*arr)[i].string);
                (*arr)[i].string = NULL;
            }
        }
        free(*arr);
        *arr = NULL;
    }
}

