// External logging framework
#include "logging.h"

// Define the maximum number of structures to allocate
#define MAX_N 1024

// Define the size of each structure
struct NFAPI_CRC_INDICATION_PDU_T {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[4];
};

// Define the array of structures
struct NFAPI_CRC_INDICATION_PDU_T* arr = NULL;

// Define the size of the array
size_t size = 0;

// Define the number of elements in the array
size_t num_elements = 0;

// Define a custom thread-safe cache to reduce memory allocations and deallocations
struct Cache {
    struct NFAPI_CRC_INDICATION_PDU_T* buffer;
    size_t size;
};

// Initialize the cache with a default size of 1024 elements
static struct Cache cache = {NULL, 1024};

// Function to allocate memory for the array and initialize it to NULL
bool init(size_t new_size) {
    // Check if the requested size is within the maximum limit
    if (new_size > MAX_N) {
        LOG_ERROR("Requested size of %zu exceeds maximum allowed size of %d", new_size, MAX_N);
        return false;
    }

    // Initialize the array to NULL
    arr = NULL;

    // Allocate memory for the array and initialize it to NULL
    arr = malloc(new_size * sizeof(*arr));
    if (arr == NULL) {
        LOG_ERROR("Failed to allocate memory for the array");
        return false;
    }

    // Initialize the size of the array
    size = new_size;

    // Initialize the number of elements in the array
    num_elements = 0;

    // Initialize the custom cache with a default size of 1024 elements
    cache.buffer = malloc(cache.size * sizeof(*cache.buffer));
    if (cache.buffer == NULL) {
        LOG_ERROR("Failed to allocate memory for the cache");
        return false;
    }

    // Return success
    return true;
}

// Function to free all memory allocated by the array and clear it
void destroy() {
    // Check if the array is NULL
    if (arr == NULL) {
        return;
    }

    // Free the memory allocated for the array
    free(arr);
    arr = NULL;

    // Clear the size of the array
    size = 0;

    // Clear the number of elements in the array
    num_elements = 0;

    // Clear the custom cache
    if (cache.buffer != NULL) {
        free(cache.buffer);
        cache.buffer = NULL;
    }
}

// Function to add a new element to the end of the array
bool add(struct NFAPI_CRC_INDICATION_PDU_T element) {
    // Check if the array is full
    if (num_elements == size) {
        LOG_WARNING("Array is full");
        return false;
    }

    // Increment the number of elements in the array
    num_elements++;

    // Add the new element to the end of the array
    arr[num_elements - 1] = element;

    // Return success
    return true;
}

// Function to remove an element from the end of the array
bool remove() {
    // Check if the array is empty
    if (num_elements == 0) {
        LOG_WARNING("Array is empty");
        return false;
    }

    // Decrement the number of elements in the array
    num_elements--;

    // Remove the last element from the array
    arr[num_elements] = NULL;

    // Return success
    return true;
}

// Function to dynamically resize the array based on a user-specified size
bool resize(size_t new_size) {
    // Check if the requested size is within the maximum limit
    if (new_size > MAX_N) {
        LOG_ERROR("Requested size of %zu exceeds maximum allowed size of %d", new_size, MAX_N);
        return false;
    }

    // Reallocate memory for the array to the new size
    struct NFAPI_CRC_INDICATION_PDU_T* new_arr = realloc(arr, new_size * sizeof(*new_arr));
    if (new_arr == NULL) {
        LOG_ERROR("Failed to reallocate memory for the array");
        return false;
    }

    // Update the size of the array
    size = new_size;

    // Update the number of elements in the array
    num_elements = (num_elements > new_size) ? new_size : num_elements;

    // Copy the old elements to the new array
    memcpy(new_arr, arr, num_elements * sizeof(*new_arr));

    // Free the old memory allocated for the array
    free(arr);

    // Update the pointer to the new array
    arr = new_arr;

    // Return success
    return true;
}

// Function to update a specific element in the array based on an RX_UE_INFORMATION_TAG and RNTI
bool update(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Check if the array is empty
    if (num_elements == 0) {
        LOG_WARNING("Array is empty");
        return false;
    }

    // Loop through the elements in the array until a match is found
    for (size_t i = 0; i < num_elements; i++) {
        if (arr[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && arr[i].RNTI == RNTI) {
            // Update the element with a randomly set CRC_INDICATION_REL8_TAG
            memset(arr[i].CRC_INDICATION_REL8_TAG, rand(), 4);
            return true;
        }
    }

    // Return failure if no match is found
    LOG_WARNING("No element found with RX_UE_INFORMATION_TAG %u and RNTI %u", RX_UE_INFORMATION_TAG, RNTI);
    return false;
}

// Function to retrieve an element from the array based on an RX_UE_INFORMATION_TAG and RNTI
struct NFAPI_CRC_INDICATION_RESPONSE* get(uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Check if the array is empty
    if (num_elements == 0) {
        LOG_WARNING("Array is empty");
        return NULL;
    }

    // Loop through the elements in the array until a match is found
    for (size_t i = 0; i < num_elements; i++) {
        if (arr[i].RX_UE_INFORMATION_TAG == RX_UE_INFORMATION_TAG && arr[i].RNTI == RNTI) {
            // Return the element that was found
            return &(arr[i]);
        }
    }

    // Return NULL if no match is found
    LOG_WARNING("No element found with RX_UE_INFORMATION_TAG %u and RNTI %u", RX_UE_INFORMATION_TAG, RNTI);
    return NULL;
}

// Function to clear the custom cache
void clearCache() {
    // Check if the custom cache is empty
    if (cache.buffer == NULL) {
