// Define a function to initialize a linked list of LTE_PHY_RX_FRAME structures
void init_LTE_PHY_RX_FRAME_list(int num_subcarriers, int max_frames) {
    // Allocate memory for the linked list head node
    LTE_PHY_RX_FRAME_Node *head = malloc(sizeof(LTE_PHY_RX_FRAME_Node));
    if (head == NULL) {
        fprintf(stderr, "Failed to allocate memory for linked list head\n");
        exit(EXIT_FAILURE);
    }

    // Initialize the linked list head node with default values
    head->frame = malloc(sizeof(LTE_PHY_RX_FRAME));
    if (head->frame == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_FRAME structure\n");
        exit(EXIT_FAILURE);
    }
    head->frame->header.subcarrier_num = num_subcarriers;
    head->frame->symbols = malloc(sizeof(LTE_PHY_RX_SYMBOL) * head->frame->header.subcarrier_num);
    if (head->frame->symbols == NULL) {
        fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_SYMBOL array\n");
        exit(EXIT_FAILURE);
    }
    head->frame->is_corrupted = false;

    // Initialize the linked list head node with default values
    head->next = NULL;

    // Iterate over the linked list until we reach the maximum number of frames allowed
    LTE_PHY_RX_FRAME_Node *curr = head;
    for (int i = 0; i < max_frames - 1; i++) {
        // Allocate memory for a new node in the linked list
        LTE_PHY_RX_FRAME_Node *new_node = malloc(sizeof(LTE_PHY_RX_FRAME_Node));
        if (new_node == NULL) {
            fprintf(stderr, "Failed to allocate memory for new linked list node\n");
            exit(EXIT_FAILURE);
        }

        // Initialize the new node with default values
        new_node->frame = malloc(sizeof(LTE_PHY_RX_FRAME));
        if (new_node->frame == NULL) {
            fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_FRAME structure\n");
            exit(EXIT_FAILURE);
        }
        new_node->frame->header.subcarrier_num = num_subcarriers;
        new_node->frame->symbols = malloc(sizeof(LTE_PHY_RX_SYMBOL) * new_node->frame->header.subcarrier_num);
        if (new_node->frame->symbols == NULL) {
            fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_SYMBOL array\n");
            exit(EXIT_FAILURE);
        }
        new_node->frame->is_corrupted = false;

        // Insert the new node into the linked list after the current node
        curr->next = new_node;
        curr = new_node;
    }
}

// Define a function to populate the LTE_PHY_RX_SYMBOL structures with random test data
void populate_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME *frame) {
    // Allocate memory for the symbols within the frame
    for (int i = 0; i < frame->header.subcarrier_num; i++) {
        LTE_PHY_RX_SYMBOL *symbol = malloc(sizeof(LTE_PHY_RX_SYMBOL));
        if (symbol == NULL) {
            fprintf(stderr, "Failed to allocate memory for LTE_PHY_RX_SYMBOL structure\n");
            exit(EXIT_FAILURE);
        }
        symbol->value = rand() % 2;
        frame->symbols[i] = symbol;
    }
}

// Define a function to free the memory allocated for the linked list of LTE_PHY_RX_FRAME structures
void free_LTE_PHY_RX_FRAME_list(LTE_PHY_RX_FRAME_Node *head) {
    // Iterate over the linked list until we reach the end
    LTE_PHY_RX_FRAME_Node *curr = head;
    while (curr != NULL) {
        free(curr->frame);
        curr = curr->next;
    }
    free(head);
}
