// Define the function to manage the dynamically allocated array of NFAPI_CRC_INDICATION_PDU_T structures
int manageNfapiCrcIndications(struct LinkedList* list) {
    // Acquire a lock on the linked list to prevent concurrent access
    pthread_mutex_lock(&list->lock);

    // Add a new element to the linked list if necessary
    if (list->size < CACHE_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            // Handle memory allocation failure gracefully
