            return -1;
        }
        list->size++;
        list->pdu = pdu;
    }

    // Update the cache with the new element
    for (int i = 0; i < CACHE_SIZE; i++) {
        if (cache[i].ue_id == -1) {
            memcpy(&cache[i], list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            break;
