#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <stdio.h>
#include <unistd.h>
#include <pthread.h>
#include "LTE_PHY_RX_FRAME.h"

// Linked list of LTE_PHY_RX_FRAME structures
typedef struct LTE_PHY_RX_FRAME_LL {
    LTE_PHY_RX_FRAME *frame;
    struct LTE_PHY_RX_FRAME_LL *next;
} LTE_PHY_RX_FRAME_LL;

// Pre-allocated pool for memory allocation
#define PREALLOCATED_POOL_SIZE 1024
static char preallocated_pool[PREALLOCATED_POOL_SIZE];
static int preallocated_pool_size = 0;

// Function to allocate memory from the pre-allocated pool
void *preallocate(int size) {
    if (preallocated_pool_size + size > PREALLOCATED_POOL_SIZE) {
        return NULL;
    }
    void *mem = &preallocated_pool[preallocated_pool_size];
    preallocated_pool_size += size;
    return mem;
}

// Function to release all allocated resources in the linked list
void free_LTE_PHY_RX_FRAME_LL(LTE_PHY_RX_FRAME_LL *ll) {
    while (ll != NULL) {
        LTE_PHY_RX_FRAME_LL *next = ll->next;
        free(ll->frame);
        ll = next;
    }
}

// Function to initialize a linked list of LTE_PHY_RX_FRAME structures
LTE_PHY_RX_FRAME_LL *init_LTE_PHY_RX_FRAME_LL(int num_frames, int subcarriers) {
    // Allocate memory for the linked list
    LTE_PHY_RX_FRAME_LL *ll = malloc(sizeof(LTE_PHY_RX_FRAME_LL) * num_frames);
    if (ll == NULL) {
        return NULL;
    }

    // Initialize each frame in the linked list
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME *frame = malloc(sizeof(LTE_PHY_RX_FRAME));
        if (frame == NULL) {
            free_LTE_PHY_RX_FRAME_LL(ll);
            return NULL;
        }
        ll[i].frame = frame;
        ll[i].next = i < num_frames - 1 ? &ll[i + 1] : NULL;

        // Initialize the header of each frame
        LTE_PHY_RX_FRAME_HEADER *header = &frame->header;
        header->num_subcarriers = subcarriers;

        // Allocate memory for the symbols in each frame
        int symbol_size = sizeof(LTE_PHY_RX_SYMBOL) * subcarriers;
        LTE_PHY_RX_SYMBOL *symbols = preallocate(symbol_size);
        if (symbols == NULL) {
            free_LTE_PHY_RX_FRAME_LL(ll);
            return NULL;
        }
        frame->symbols = symbols;

        // Populate the symbols with random data for testing purposes
        srand(time(NULL));
        for (int j = 0; j < subcarriers; j++) {
            symbols[j].I = rand() % 256 - 128;
            symbols[j].Q = rand() % 256 - 128;
        }
    }

    return ll;
}

// Function to add a new frame to the linked list
void add_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_LL *ll, LTE_PHY_RX_FRAME *frame) {
    // Allocate memory for the new frame
    if (preallocated_pool_size + sizeof(LTE_PHY_RX_FRAME) > PREALLOCATED_POOL_SIZE) {
        free(frame);
        return;
    }
    void *mem = &preallocated_pool[preallocated_pool_size];
    preallocated_pool_size += sizeof(LTE_PHY_RX_FRAME);
    memcpy(mem, frame, sizeof(LTE_PHY_RX_FRAME));

    // Add the new frame to the linked list
    ll->frame = mem;
    ll->next = malloc(sizeof(LTE_PHY_RX_FRAME_LL));
    if (ll->next == NULL) {
        free(mem);
        return;
    }
}

// Function to remove a frame from the linked list
void remove_LTE_PHY_RX_FRAME(LTE_PHY_RX_FRAME_LL *ll, LTE_PHY_RX_FRAME *frame) {
    // Find the frame in the linked list and remove it
    while (ll != NULL && ll->frame != frame) {
        ll = ll->next;
    }
    if (ll == NULL) {
        return;
    }
    LTE_PHY_RX_FRAME_LL *next = ll->next;
    free(ll->frame);
    ll->next = next;
}

// Function to check and repair corrupted frames
void repair_corrupted_frames(LTE_PHY_RX_FRAME_LL *ll) {
    // Check each frame for corruption
    for (int i = 0; i < ll->frame->header.num_subcarriers; i++) {
        if (!check_frame_corruption(ll, i)) {
            continue;
        }

        // Reinitialize the symbol array and data for the corrupted frame
        LTE_PHY_RX_FRAME *frame = ll->frame;
        int subcarriers = frame->header.num_subcarriers;
        int symbol_size = sizeof(LTE_PHY_RX_SYMBOL) * subcarriers;
        LTE_PHY_RX_SYMBOL *symbols = preallocate(symbol_size);
        if (symbols == NULL) {
            continue;
        }
        frame->symbols = symbols;

        // Populate the symbols with random data for testing purposes
        srand(time(NULL));
        for (int j = 0; j < subcarriers; j++) {
            symbols[j].I = rand() % 256 - 128;
            symbols[j].Q = rand() % 256 - 128;
