void init_network_queue(struct network_queue* queue) {
    assert(queue != NULL);

    // Load default values from configuration file
    FILE* config = fopen("network_config.txt", "r");
    if (config == NULL) {
        printf("Error: unable to open network configuration file\n");
        return;
    }

