    while (fgets(buffer, sizeof(buffer), config)) {
        char* key = strtok(buffer, "=");
        if (key == NULL) {
            continue;
        }
        char* value = strtok(NULL, "\n");
        if (value == NULL) {
            continue;
        }
        if (strcmp(key, "max_packet_size") == 0) {
            queue->max_size = atoi(value);
        } else if (strcmp(key, "max_buffers") == 0) {
            queue->num_buffers = atoi(value);
        } else if (strcmp(key, "initial_capacity") == 0) {
            queue->initial_capacity = atoi(value);
        }
    }
    fclose(config);

    // Initialize head and tail pointers
    queue->head = NULL;
    queue->tail = NULL;

    // Allocate memory for the initial buffers
