    for (i = 0; i < queue->initial_capacity; i++) {
        struct packet_buffer* buffer = malloc(sizeof(struct packet_buffer));
        if (buffer == NULL) {
            printf("Error: unable to allocate memory for initial buffers\n");
            return;
        }
        memset(buffer, 0, sizeof(struct packet_buffer));
        buffer->payload = malloc(queue->max_size);
        if (buffer->payload == NULL) {
            printf("Error: unable to allocate memory for payload\n");
            return;
        }
        memset(buffer->payload, 0, queue->max_size);
        buffer->next = NULL;

        // Insert the new buffer into the queue
        if (queue->head == NULL) {
            queue->head = buffer;
            queue->tail = buffer;
        } else {
            queue->tail->next = buffer;
            queue->tail = buffer;
        }
    }
}

void add_packet(struct network_queue* queue, struct packet_buffer* packet) {
    assert(queue != NULL && packet != NULL);

    // Check if the queue is full
    if (queue->num_buffers >= queue->max_size) {
        return;
    }

    // Generate random test data for the payload
    size_t i;
    for (i = 0; i < queue->max_size; i++) {
        packet->payload[i] = rand() % 256;
    }

    // Insert the new buffer into the queue
    if (queue->head == NULL) {
        queue->head = packet;
        queue->tail = packet;
    } else {
        queue->tail->next = packet;
        queue->tail = packet;
    }

    // Increment the number of buffers in the queue
    queue->num_buffers++;
}

struct packet_buffer* remove_packet(struct network_queue* queue) {
    assert(queue != NULL);

    // Check if the queue is empty
    if (queue->head == NULL) {
        return NULL;
    }

    // Remove the head of the queue
    struct packet_buffer* packet = queue->head;
    queue->head = packet->next;
    packet->next = NULL;

    // Decrement the number of buffers in the queue
    queue->num_buffers--;

    return packet;
}
