// Function to initialize the arrays
void init_arrays(long *offsets, int *keys, record *records, double **doubles, char ***strings, struct point_t ***structs, trajectory_t **trajectories) {
    size_t i, j; // Loop counters
    long offset; // Offset for the current thread
    int key; // Key for the current record
    double value; // Value for the current record
    char *string; // String for the current string
    struct point_t *struct_; // Struct for the current struct
    trajectory_t *trajectory; // Trajectory for the current thread

    // Initialize the arrays
    for (i = 0; i < num_threads; ++i) {
        offset = offsets[i];
        key = keys[offset];
        value = records[offset].value;
        string = strings[offset];
        struct_ = structs[offset];
        trajectory = trajectories[i];

        // Initialize the arrays for this thread
        trajectory->points = (point_t *) malloc(sizeof(point_t) * num_points);
        trajectory->num_points = num_points;

        for (j = 0; j < num_points; ++j) {
            // Initialize the points in the array
            trajectory->points[j].x = value + j * j;
            trajectory->points[j].y = key + j;
        }
    }
}

