struct Config {
    int option1;
    char* option2;
};

void parse_config(const char* json, struct Config* config) {
    json_object* root = NULL;
    json_object* options = NULL;
    json_object* option1 = NULL;
    json_object* option2 = NULL;

    root = json_tokener_parse(json);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", strerror(errno));
        goto error;
    }

    options = json_object_object_get(root, "options");
    if (!options) {
        fprintf(stderr, "Invalid JSON format. Could not find 'options' key.\n");
        goto error;
    }

    option1 = json_object_object_get(options, "option1");
    if (!option1) {
        fprintf(stderr, "Invalid JSON format. Could not find 'option1' value.\n");
        goto error;
    }
    config->option1 = (int)json_object_get_int64(option1);

    option2 = json_object_object_get(options, "option2");
    if (!option2) {
        fprintf(stderr, "Invalid JSON format. Could not find 'option2' value.\n");
        goto error;
    }
    config->option2 = (char*)json_object_get_string(option2);

    json_object_put(root);
    return;

error:
    if (root) {
        json_object_put(root);
    }
    fprintf(stderr, "Error parsing JSON. Aborting.\n");
}

struct Config* load_config(const char* filename) {
    FILE* fp = NULL;
    struct Config* config = NULL;
    char* json = NULL;
    size_t len = 0;

    fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening configuration file: %s\n", strerror(errno));
        goto error;
    }

    config = (struct Config*)malloc(sizeof(struct Config));
    memset(config, 0, sizeof(struct Config));

    if (getline(&json, &len, fp) == -1) {
        fprintf(stderr, "Error reading configuration file: %s\n", strerror(errno));
        goto error;
    }

    parse_config(json, config);

    free(json);
    json = NULL;
    fclose(fp);
    return config;

error:
    if (fp) {
        fclose(fp);
    }
    if (json) {
        free(json);
    }
    if (config) {
        free(config);
    }
    return NULL;
}
