```java
public class RetryMechanism {
    private final int maxAttempts;
    private final long retryDelay;
    private final boolean enableJitter;

    public RetryMechanism(int maxAttempts, long retryDelay, boolean enableJitter) {
        this.maxAttempts = maxAttempts;
        this.retryDelay = retryDelay;
        this.enableJitter = enableJitter;
    }

    public ResponseElement getResponse(String url, int attempt) throws IOException {
        ResponseElement response = null;
        for (int i = 0; i < maxAttempts; i++) {
            try {
                response = HttpClient.getResponse(url);
                break;
            } catch (IOException e) {
                if (attempt == maxAttempts - 1) {
                    throw e;
                } else {
                    attempt++;
                    try {
                        Thread.sleep(retryDelay + (enableJitter ? random.nextInt((int) retryDelay) : 0));
                    } catch (InterruptedException ex) {
                        Thread.currentThread().interrupt();
                    }
                }
            }
        }
        return response;
    }
}
```
