public class Cache {
    private final ConcurrentHashMap<String, ResponseElement> cache = new ConcurrentHashMap<>();
    private final int cacheSize;
    private final long ttl;

    public Cache(int cacheSize, long ttl) {
        this.cacheSize = cacheSize;
        this.ttl = ttl;
    }

    public ResponseElement getResponse(String url) throws IOException {
        ResponseElement response = null;
        if (cache.containsKey(url)) {
            response = cache.get(url);
        } else {
            response = HttpClient.getResponse(url);
            cache.put(url, response);
        }
        return response;
    }
}
