public class SystemMonitor {
    private final ConcurrentHashMap<String, Long> requestTimestamps = new ConcurrentHashMap<>();
    private final long timeout;

    public SystemMonitor(long timeout) {
        this.timeout = timeout;
    }

    public void startRequest(String url) {
        requestTimestamps.put(url, System.nanoTime());
    }

    public void endRequest(String url) {
        long duration = System.nanoTime() - requestTimestamps.get(url);
        if (duration > timeout) {
            // log error
        }
    }
}
