    private final RetryMechanism retryMechanism;
    private final Logging logging;
    private final Cache cache;
    private final SystemMonitor systemMonitor;

    public Client(HttpClient httpClient, RetryMechanism retryMechanism, Logging logging, Cache cache, SystemMonitor systemMonitor) {
        this.httpClient = httpClient;
        this.retryMechanism = retryMechanism;
        this.logging = logging;
        this.cache = cache;
        this.systemMonitor = systemMonitor;
    }

    public void sendRequest(String url) {
        try {
            systemMonitor.startRequest(url);
            ResponseElement response = retryMechanism.getResponse(url, 0);
            if (response != null) {
                logging.logResponse("Received response", response);
            } else {
                logging.logError("No response received");
            }
        } catch (IOException e) {
            logging.logError(e.getMessage());
        } finally {
            systemMonitor.endRequest(url);
        }
    }
}
