// Source file: lte_phy_rx_frame.c

#include "lte_phy_rx_frame.h"
#include <pthread.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

struct LTE_PHY_RX_FRAME_LIST {
    struct LTE_PHY_RX_FRAME *frames;
    int count;
    pthread_mutex_t mutex;
};

struct LTE_PHY_RX_SYMBOL_LIST {
    struct LTE_PHY_RX_SYMBOL *symbols;
    int count;
};

void lte_phy_rx_frame_list_init(struct LTE_PHY_RX_FRAME_LIST *list) {
    list->frames = NULL;
    list->count = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

void lte_phy_rx_frame_list_destroy(struct LTE_PHY_RX_FRAME_LIST *list) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        struct LTE_PHY_RX_FRAME *frame = &list->frames[i];
        lte_phy_rx_symbol_list_destroy(frame->symbols);
    }
    free(list->frames);
    list->count = 0;
    pthread_mutex_unlock(&list->mutex);
}

void lte_phy_rx_frame_add(struct LTE_PHY_RX_FRAME_LIST *list, struct LTE_PHY_RX_FRAME *frame) {
    pthread_mutex_lock(&list->mutex);
    list->frames = realloc(list->frames, (list->count + 1) * sizeof(struct LTE_PHY_RX_FRAME));
    if (!list->frames) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    list->frames[list->count++] = *frame;
    pthread_mutex_unlock(&list->mutex);
}

struct LTE_PHY_RX_FRAME *lte_phy_rx_frame_find(struct LTE_PHY_RX_FRAME_LIST *list, int header) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        struct LTE_PHY_RX_FRAME *frame = &list->frames[i];
        if (frame->header == header) {
            pthread_mutex_unlock(&list->mutex);
            return frame;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return NULL;
}

void lte_phy_rx_frame_update(struct LTE_PHY_RX_FRAME_LIST *list, int header, int signal_strength) {
    struct LTE_PHY_RX_FRAME *frame = lte_phy_rx_frame_find(list, header);
    if (frame) {
        pthread_mutex_lock(&list->mutex);
        frame->signal_strength = signal_strength;
        pthread_mutex_unlock(&list->mutex);
    }
}

void lte_phy_rx_symbol_add(struct LTE_PHY_RX_FRAME *frame, struct LTE_PHY_RX_SYMBOL *symbol) {
    pthread_mutex_lock(&frame->mutex);
    frame->symbols = realloc(frame->symbols, (frame->count + 1) * sizeof(struct LTE_PHY_RX_SYMBOL));
    if (!frame->symbols) {
        perror("realloc");
        exit(EXIT_FAILURE);
    }
    frame->symbols[frame->count++] = *symbol;
    pthread_mutex_unlock(&frame->mutex);
}

void lte_phy_rx_symbol_list_init(struct LTE_PHY_RX_SYMBOL_LIST *list) {
    list->symbols = NULL;
    list->count = 0;
}

void lte_phy_rx_symbol_list_destroy(struct LTE_PHY_RX_SYMBOL_LIST *list) {
    free(list->symbols);
    list->count = 0;
}

void lte_phy_rx_frame_remove(struct LTE_PHY_RX_FRAME_LIST *list, int header) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->count; ++i) {
        struct LTE_PHY_RX_FRAME *frame = &list->frames[i];
        if (frame->header == header) {
            lte_phy_rx_symbol_list_destroy(frame->symbols);
            list->count--;
            break;
        }
    }
    pthread_mutex_unlock(&list->mutex);
}

struct LTE_PHY_RX_SYMBOL *lte_phy_rx_symbol_find(struct LTE_PHY_RX_FRAME *frame, int symbol) {
    pthread_mutex_lock(&frame->mutex);
    for (int i = 0; i < frame->count; ++i) {
        struct LTE_PHY_RX_SYMBOL *symbol = &frame->symbols[i];
        if (symbol->symbol == symbol) {
            pthread_mutex_unlock(&frame->mutex);
            return symbol;
        }
    }
    pthread_mutex_unlock(&frame->mutex);
    return NULL;
}

struct LTE_PHY_RX_SYMBOL *lte_phy_rx_symbol_find_by_time(struct LTE_PHY_RX_FRAME *frame, int time) {
    pthread_mutex_lock(&frame->mutex);
    for (int i = 0; i < frame->count; ++i) {
        struct LTE_PHY_RX_SYMBOL *symbol = &frame->symbols[i];
        if (symbol->time == time) {
            pthread_mutex_unlock(&frame->mutex);
            return symbol;
        }
    }
    pthread_mutex_unlock(&frame->mutex);
    return NULL;
}

void lte_phy_rx_symbol_update(struct LTE_PHY_RX_SYMBOL *symbol, int time) {
    symbol->time = time;
}
