// UE represents a User Equipment
type UE struct {
	RNTI int
	PDUs []PDU
}

// PDU represents a Protocol Data Unit
type PDU struct {
	Type string
	Data []byte
}

func main() {
	var ues []UE

	// Open the CSV file and read it into memory
	f, err := os.Open("data.csv")
	if err != nil {
		fmt.Println(err)
		return
	}
	defer f.Close()

	r := csv.NewReader(f)
	for {
		// Read each row of the CSV file
		record, err := r.Read()
		if err == io.EOF {
			break
		} else if err != nil {
			fmt.Println(err)
			return
		}

		// Parse the RNTI and PDU type from the row
		rnti, err := strconv.Atoi(record[0])
		if err != nil {
			fmt.Println(err)
			return
		}
		pduType := record[1]

		// Create a new UE if it doesn't exist yet
		var ue *UE
		for _, u := range ues {
			if u.RNTI == rnti {
				ue = &u
				break
			}
		}
		if ue == nil {
			ue = &UE{RNTI: rnti, PDUs: make([]PDU, 0)}
			ues = append(ues, *ue)
		}

		// Add the PDU to the UE's list of PDUs
		pdu := PDU{Type: pduType}
		data, err := base64.StdEncoding.DecodeString(record[2])
		if err != nil {
			fmt.Println(err)
			return
		}
		pdu.Data = data
		ue.PDUs = append(ue.PDUs, pdu)
	}

	// Print the UE information
	for _, ue := range ues {
		fmt.Println("UE", ue.RNTI, "with", len(ue.PDUs), "PDUs")
		for _, pdu := range ue.PDUs {
			fmt.Println("  PDU type:", pdu.Type)
		}
	}
}']

