// Global variables
struct LTE_ENB_SIB1 **sib1Array;
int numCells;
pthread_mutex_t mutex;

void manageSIB1(int cellId, struct LTE_ENB_SIB1 *sib1) {
  pthread_mutex_lock(&mutex);
  if (cellId >= numCells) {
    // Reallocate memory for the new cell
    sib1Array = realloc(sib1Array, sizeof(struct LTE_ENB_SIB1 *) * (numCells + 1));
    sib1Array[numCells] = malloc(sizeof(struct LTE_ENB_SIB1));
    numCells++;
  }
  // Update SIB1 parameters for the cell
  struct LTE_ENB_SIB1 *oldSib1 = sib1Array[cellId];
  oldSib1->systemInfoValueTag = sib1->systemInfoValueTag;
  oldSib1->siSchedulingInfo = sib1->siSchedulingInfo;
  oldSib1->siWindowLength = sib1->siWindowLength;
  pthread_mutex_unlock(&mutex);
}

void updateSIB1(int cellId, struct LTE_ENB_SIB1 *sib1) {
  manageSIB1(cellId, sib1);
}

void deleteSIB1(int cellId) {
  pthread_mutex_lock(&mutex);
  if (cellId < numCells) {
    free(sib1Array[cellId]);
    memmove(sib1Array + cellId, sib1Array + cellId + 1, sizeof(struct LTE_ENB_SIB1 *) * (numCells - cellId - 1));
    numCells--;
  }
  pthread_mutex_unlock(&mutex);
}

void initialize() {
  // Initialize the mutex and allocate memory for the sib1Array
  pthread_mutex_init(&mutex, NULL);
  sib1Array = malloc(sizeof(struct LTE_ENB_SIB1 *) * numCells);
  for (int i = 0; i < numCells; i++) {
    sib1Array[i] = malloc(sizeof(struct LTE_ENB_SIB1));
  }
}
