            exit(1);
        }

        long_array = new_long_array;
        int_array = new_int_array;
        record_array = new_record_array;
    }

    // Define function to verify no memory overflows occur during allocation
    void check_memory_overflow() {
        size_t long_usage = sizeof(long) * long_array_size;
        size_t int_usage = sizeof(int) * int_array_size;
        size_t record_usage = sizeof(Record *) * record_array_size;
        if (long_usage + int_usage + record_usage > 0.9 * total_memory) {
