void populateCrcIndicationList(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    // Initialize the list
    list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(maxSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Generate random RX UE information and CRC indication tags
    for (int i = 0; i < maxSize; i++) {
        list[i].rxUeInformationTag = rand();
        list[i].rnti = rand();
        list[i].crcIndicationRel8Tag = rand();
        list[i].crcFlag = (rand() % 2) ? CRC_FLAG_TRUE : CRC_FLAG_FALSE;
    }

    // Check for duplicates and log a message if detected
    for (int i = 0; i < maxSize - 1; i++) {
        for (int j = i + 1; j < maxSize; j++) {
            if (list[i].rnti == list[j].rnti) {
                // Duplicate detected, skip this entry and log a message
                printf("Duplicate RNTI detected: %d\n", list[i].rnti);
                break;
            }
        }
    }
}

// Synchronous processing mode for populating the CRC indication list
void processCrcIndications(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    populateCrcIndicationList(list, maxSize);
}

// Asynchronous processing mode for populating the CRC indication list
void processCrcIndicationsAsync(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    populateCrcIndicationList(list, maxSize);
}

// Thread-safe function to add a new CRC indication entry to the list
void addCrcIndicationEntry(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Check for duplicate RNTIs and log a message if detected
    for (int i = 0; i < maxSize - 1; i++) {
        if (list[i].rnti == list[maxSize - 1].rnti) {
            printf("Duplicate RNTI detected: %d\n", list[i].rnti);
            break;
        }
    }

    // Add the new entry to the list and release the lock
    list[maxSize - 1] = (NFAPI_CRC_INDICATION_PDU_T) {
        .rxUeInformationTag = rand(),
        .rnti = rand(),
        .crcIndicationRel8Tag = rand(),
        .crcFlag = (rand() % 2) ? CRC_FLAG_TRUE : CRC_FLAG_FALSE,
    };
    pthread_mutex_unlock(&mutex);
}

// Thread-safe function to remove an entry from the list
void removeCrcIndicationEntry(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    // Lock the list to prevent concurrent access
    pthread_mutex_lock(&mutex);

    // Find the entry to be removed and replace it with the last element in the list
    for (int i = 0; i < maxSize - 1; i++) {
        if (list[i].rnti == rnti) {
            list[i] = list[maxSize - 1];
            break;
        }
    }

    // Decrement the size of the list and release the lock
    maxSize--;
    pthread_mutex_unlock(&mutex);
}

// Synchronous processing mode for removing an entry from the CRC indication list
void removeCrcIndicationEntrySync(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    removeCrcIndicationEntry(list, maxSize);
}

// Asynchronous processing mode for removing an entry from the CRC indication list
void removeCrcIndicationEntryAsync(NFAPI_CRC_INDICATION_PDU_T *list, int maxSize) {
    removeCrcIndicationEntry(list, maxSize);
}

