#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>
#include <time.h>
#include <math.h>

#define MAX_CONTEXTS 10000
#define CONTEXT_SIZE sizeof(UEContext)
#define IMSI_LEN 8 // length of the imsi string

typedef struct UEContext {
    char imsi[IMSI_LEN];
    int rnti;
    int pdu_session_id;
    time_t last_update;
} UEContext;

struct HashTable {
    UEContext* contexts[MAX_CONTEXTS];
    size_t count;
};

// Initialize the hash table with random values for testing purposes
void initHashTable(struct HashTable* ht) {
    srand((unsigned int) time(NULL));
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        UEContext* context = malloc(CONTEXT_SIZE);
        if (!context) {
            perror("Failed to allocate memory for hash table");
            exit(EXIT_FAILURE);
        }
        // Generate a random imsi string and assign it to the context
        char imsi[IMSI_LEN];
        for (int j = 0; j < IMSI_LEN; j++) {
            imsi[j] = '0' + rand() % 10;
        }
        strcpy(context->imsi, imsi);
        context->rnti = rand() % 65536;
        context->pdu_session_id = rand() % 256;
        context->last_update = time(NULL);
        ht->contexts[i] = context;
    }
    ht->count = MAX_CONTEXTS;
}

// Find the index of the hash table where the imsi string is stored
int findIndex(struct HashTable* ht, char* imsi) {
    for (int i = 0; i < ht->count; i++) {
        if (!strcmp(ht->contexts[i]->imsi, imsi)) {
            return i;
        }
    }
    return -1; // not found
}

// Insert a new UEContext into the hash table with the given imsi string
void insertContext(struct HashTable* ht, char* imsi) {
    int index = findIndex(ht, imsi);
    if (index == -1) { // not found
        UEContext* context = malloc(CONTEXT_SIZE);
        if (!context) {
            perror("Failed to allocate memory for new hash table entry");
            exit(EXIT_FAILURE);
        }
        strcpy(context->imsi, imsi);
        context->rnti = rand() % 65536;
        context->pdu_session_id = rand() % 256;
        context->last_update = time(NULL);
        ht->contexts[ht->count++] = context;
    } else { // already exists
        UEContext* existingContext = ht->contexts[index];
        existingContext->rnti = rand() % 65536;
        existingContext->pdu_session_id = rand() % 256;
        existingContext->last_update = time(NULL);
    }
}

// Retrieve the UEContext from the hash table with the given imsi string
UEContext* retrieveContext(struct HashTable* ht, char* imsi) {
    int index = findIndex(ht, imsi);
    if (index == -1) { // not found
        return NULL;
    } else {
        return ht->contexts[index];
    }
}

// Remove the UEContext with the given imsi string from the hash table
void removeContext(struct HashTable* ht, char* imsi) {
    int index = findIndex(ht, imsi);
    if (index != -1) { // found
        free(ht->contexts[index]);
        ht->count--;
        for (int i = index; i < ht->count; i++) {
            ht->contexts[i] = ht->contexts[i + 1];
        }
    }
}

// Check if the hash table is empty
bool isEmpty(struct HashTable* ht) {
    return ht->count == 0;
}

// Retrieve all contexts from the hash table and free their memory
void clearHashTable(struct HashTable* ht) {
    for (int i = 0; i < ht->count; i++) {
        free(ht->contexts[i]);
    }
}
```
This implementation uses a fixed-size array to store the hash table entries, which allows for efficient insertion and retrieval operations. The `UEContext` structure is defined to include an `imsi`, `rnti`, `pdu_session_id`, and timestamp fields for each context. The `initHashTable` function initializes the hash table with random values for testing purposes, ensuring each `imsi` is unique within the hash table.

The `findIndex` function searches for a specific `imsi` in the hash table and returns its index if found, or -1 otherwise. The `insertContext` function inserts a new context into the hash table with the given imsi string. If an existing context is found with the same imsi, it updates its fields instead of creating a new one.

The `retrieveContext` function retrieves the UEContext from the hash table with the given imsi string and returns it if found, or NULL otherwise. The `removeContext` function removes the UEContext with the given imsi string from the hash table by freeing its memory and shifting all subsequent contexts to fill the gap.

The `isEmpty` function checks if the hash table is empty. The `clearHashTable` function frees the memory of all contexts in the hash table.']

