// Define the memory pool granularity (in bytes) for allocating network packets
#define MEMORY_POOL_GRANULARITY 16

// Initialize and manage a dynamic array of WIRELESS_NETWORK_FRAME structures
WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *init_dynamic_array() {
    // Allocate memory for the dynamic array
    WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array = (WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *)malloc(sizeof(WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY));
    if (!array) {
        printf("Error: Failed to allocate memory for the dynamic array\n");
        return NULL;
    }

    // Initialize the dynamic array
    array->num_frames = 0;
    array->frames = (WIRELESS_NETWORK_FRAME **)malloc(MAX_CONCURRENT_THREADS * sizeof(WIRELESS_NETWORK_FRAME *));
    if (!array->frames) {
        printf("Error: Failed to allocate memory for the dynamic array\n");
        free(array);
        return NULL;
    }

    // Initialize the frame memory pool
    array->frame_memory = (unsigned char *)malloc(MEMORY_POOL_SIZE);
    if (!array->frame_memory) {
        printf("Error: Failed to allocate memory for the frame memory pool\n");
        free(array->frames);
        free(array);
        return NULL;
    }

    // Initialize the packet memory pool
    array->packet_memory = (unsigned char *)malloc(MEMORY_POOL_SIZE);
    if (!array->packet_memory) {
        printf("Error: Failed to allocate memory for the packet memory pool\n");
        free(array->frame_memory);
        free(array->frames);
        free(array);
        return NULL;
    }

    return array;
}

// Add a new frame to the dynamic array
int add_frame(WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array, WIRELESS_NETWORK_FRAME *frame) {
    // Check if the dynamic array is full
    if (array->num_frames == MAX_CONCURRENT_THREADS) {
        printf("Error: The dynamic array is full\n");
        return -1;
    }

    // Allocate memory for the frame
    size_t frame_size = sizeof(WIRELESS_NETWORK_FRAME) + (frame->num_packets * sizeof(NETWORK_PACKET));
    unsigned char *frame_memory = malloc(frame_size);
    if (!frame_memory) {
        printf("Error: Failed to allocate memory for the frame\n");
        return -1;
    }

    // Copy the frame data into the allocated memory
    memcpy(frame_memory, frame, sizeof(WIRELESS_NETWORK_FRAME));

    // Allocate memory for the packets in the frame
    size_t packet_size = sizeof(NETWORK_PACKET) * frame->num_packets;
    unsigned char *packet_memory = malloc(packet_size);
    if (!packet_memory) {
        printf("Error: Failed to allocate memory for the packets\n");
        free(frame_memory);
        return -1;
    }

    // Copy the packet data into the allocated memory
    memcpy(packet_memory, frame->packets, packet_size);

    // Add the frame and packets to the dynamic array
    array->frames[array->num_frames] = (WIRELESS_NETWORK_FRAME *)frame_memory;
    array->frames[array->num_frames]->packets = (NETWORK_PACKET **)packet_memory;
    array->num_frames++;

    return 0;
}

// Remove a frame from the dynamic array
int remove_frame(WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array, WIRELESS_NETWORK_FRAME *frame) {
    // Check if the dynamic array is empty
    if (array->num_frames == 0) {
        printf("Error: The dynamic array is empty\n");
        return -1;
    }

    // Find the frame in the dynamic array
    for (size_t i = 0; i < array->num_frames; i++) {
        if (array->frames[i] == frame) {
            break;
        }
    }

    // Check if the frame was found in the dynamic array
    if (i == array->num_frames) {
        printf("Error: The frame was not found in the dynamic array\n");
        return -1;
    }

    // Remove the frame and packets from the dynamic array
    free(array->frames[i]->packets);
    free(array->frames[i]);
    for (size_t j = i + 1; j < array->num_frames; j++) {
        array->frames[j - 1] = array->frames[j];
    }
    array->num_frames--;

    return 0;
}

// Get the next frame from the dynamic array
WIRELESS_NETWORK_FRAME *get_next_frame(WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array) {
    // Check if the dynamic array is empty
    if (array->num_frames == 0) {
        printf("Error: The dynamic array is empty\n");
        return NULL;
    }

    // Get the first frame in the dynamic array
    WIRELESS_NETWORK_FRAME *frame = array->frames[0];

    // Remove the first frame from the dynamic array
    remove_frame(array, frame);

    return frame;
}

// Release the resources allocated by the dynamic array
void release_dynamic_array(WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array) {
    // Free the memory for the frames and packets in the dynamic array
    for (size_t i = 0; i < array->num_frames; i++) {
        free(array->frames[i]->packets);
        free(array->frames[i]);
    }

    // Free the memory for the frames and packets in the dynamic array
    free(array->frame_memory);
    free(array->packet_memory);

    // Free the memory for the dynamic array
    free(array);
}

int main() {
    // Initialize the dynamic array
    WIRELESS_NETWORK_FRAME_DYNAMIC_ARRAY *array = init_dynamic_array();
    if (!array) {
        return 1;
    }

    // Add a new frame to the dynamic array
    WIRELESS_NETWORK_FRAME frame1 = {0};
    add_frame(array, &frame1);

    // Add another frame to the dynamic array
    WIRELESS_NETWORK_FRAME frame2 = {0};
    add_frame(array, &frame2);

