// Initialize and manage a dynamic list of network interface configurations
int initialize_network_config(network_config* config) {
    // Validate the IP address format
    if (!inet_pton(AF_INET, config->ip_addr, &((struct sockaddr_in*)&config->ip_addr)->sin_addr)) {
        return 1;
    }

    // Verify that the subnet mask is between 8 and 30 bits (inclusive)
    if ((config->subnet_mask < 8) || (config->subnet_mask > 30)) {
        return 2;
    }

    // Ensure the gateway address is a valid IP address and not part of a restricted or reserved range
    struct sockaddr_in* gw = (struct sockaddr_in*)&config->gateway_addr;
    if (!inet_pton(AF_INET, config->gateway_addr, &gw->sin_addr)) {
        return 3;
    }
    if (is_reserved_ipv4_address(gw->sin_addr.s_addr)) {
        return 4;
    }

    // Validate that each DNS server address is a valid IP address and unique within the list
    for (int i = 0; i < config->dns_servers; i++) {
        struct sockaddr_in* dns = (struct sockaddr_in*)&config->dns_servers[i];
        if (!inet_pton(AF_INET, config->dns_servers[i], &dns->sin_addr)) {
            return 5;
        }
        for (int j = i + 1; j < config->dns_servers; j++) {
            if (memcmp(config->dns_servers[i], config->dns_servers[j], sizeof(struct in_addr)) == 0) {
                return 6;
            }
        }
    }

    // Allow dynamic reconfiguration
    pthread_mutex_lock(&config->mutex);
    if (config->configs[config->dns_servers] != NULL) {
        free(config->configs[config->dns_servers]);
        config->configs[config->dns_servers] = NULL;
    }
    config->configs[config->dns_servers] = (network_config*)malloc(sizeof(network_config));
    memcpy(config->configs[config->dns_servers], config, sizeof(network_config));
    pthread_mutex_unlock(&config->mutex);

    return 0;
}

// Integrate with an external configuration management service
void manage_external_config(dns_server_list* list) {
    // Check if the external service is available and healthy
    struct sockaddr_in svc_addr = { AF_INET, htons(53), inet_addr("192.168.0.1") };
    int sock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
    if (sock == -1) {
        perror("socket() failed");
        return;
    }
    if (connect(sock, (struct sockaddr*)&svc_addr, sizeof(struct sockaddr_in)) < 0) {
        perror("connect() failed");
        close(sock);
        return;
    }

    // Retrieve the external configuration from the service
    char* data = malloc(1024 * sizeof(char));
    size_t len = recvfrom(sock, data, 1024, 0, NULL, NULL);
    if (len == -1) {
        perror("recvfrom() failed");
        free(data);
        close(sock);
        return;
    }

    // Parse the received configuration and update the list
    network_config config;
    memcpy(&config, data, sizeof(network_config));
    pthread_mutex_lock(&list->mutex);
    if (list->configs[0] != NULL) {
        free(list->configs[0]);
        list->configs[0] = NULL;
    }
    list->configs[0] = (network_config*)malloc(sizeof(network_config));
    memcpy(list->configs[0], &config, sizeof(network_config));
    pthread_mutex_unlock(&list->mutex);

    free(data);
    close(sock);
}
