void generate_crc_indication_pdu(int num_structures, NFAPI_CRC_INDICATION_PDU_T **list) {
    int i;
    *list = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_structures);
    if (*list == NULL) {
        // handle memory allocation failure gracefully
        return;
    }
    for (i = 0; i < num_structures; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            // handle memory allocation failure gracefully
            return;
        }
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        while (find_duplicate(list, i, pdu->RNTI)) {
            pdu->RNTI = rand();
        }
        pdu->CRCFLAG = rand() % 2; // randomly set CRCFLAG
        list[i] = pdu;
    }
    qsort(list, num_structures, sizeof(NFAPI_CRC_INDICATION_PDU_T), compare_pdu);
}

int find_duplicate(NFAPI_CRC_INDICATION_PDU_T **list, int i, uint16_t rnti) {
    for (int j = 0; j < i; j++) {
        if (list[j]->RNTI == rnti) {
            return 1;
        }
    }
    return 0;
}

void compare_pdu(const void *a, const void *b) {
    NFAPI_CRC_INDICATION_PDU_T **pa = (NFAPI_CRC_INDICATION_PDU_T **) a;
    NFAPI_CRC_INDICATION_PDU_T **pb = (NFAPI_CRC_INDICATION_PDU_T **) b;
    if ((*pa)->RNTI > (*pb)->RNTI) {
        return 1;
    } else if ((*pa)->RNTI < (*pb)->RNTI) {
        return -1;
    } else {
        return 0;
    }
}
