// Define a function to validate the integrity of an interface configuration structure
bool validate_interface_config(NFAPI_INTERFACE_CONFIG *config) {
    // Check that the IP address, subnet mask, and gateway addresses are valid
    if (!validate_ip_addr(config->ip_addr)) {
        return false;
    }
    if (!validate_subnet_mask(config->subnet_mask)) {
        return false;
    }
    if (!validate_gateway_addr(config->gateway_addr)) {
        return false;
    }

    // Check that the DNS server list is properly formatted and non-empty
    int dns_servers_len = 0;
    while (config->dns_servers[dns_servers_len] != NULL) {
        dns_servers_len++;
    }
    if (dns_servers_len == 0) {
        return false;
    }

    return true;
}

// Define a function to validate the integrity of an IP address
bool validate_ip_addr(char *ip_addr) {
    // Check that the IP address is valid
    struct sockaddr_in sa;
    if (inet_pton(AF_INET, ip_addr, &sa.sin_addr) <= 0) {
        return false;
    }

    return true;
}

// Define a function to validate the integrity of a subnet mask
bool validate_subnet_mask(char *subnet_mask) {
    // Check that the subnet mask is valid
    struct sockaddr_in sa;
    if (inet_pton(AF_INET, subnet_mask, &sa.sin_addr) <= 0) {
        return false;
    }

    return true;
}

// Define a function to validate the integrity of a gateway address
bool validate_gateway_addr(char *gateway_addr) {
    // Check that the gateway address is valid
    struct sockaddr_in sa;
    if (inet_pton(AF_INET, gateway_addr, &sa.sin_addr) <= 0) {
        return false;
    }

    return true;
}
