// Struct to represent a PDU Session with QoS parameters
struct pdu_session {
    int qos_profile;
    char* apn;
};

// Struct to represent an LTE UE Context
struct lte_ue_context {
    int ue_id;
    int rnti;
    struct pdu_session* sessions[MAX_PDU_SESSIONS]; // Maximum number of PDU Sessions
    size_t num_sessions;
};

// Global variable to store the UE Contexts
struct lte_ue_context* ue_contexts = NULL;
size_t num_ue_contexts = 0;
pthread_mutex_t ue_context_lock = PTHREAD_MUTEX_INITIALIZER;

// Function to initialize and configure a dynamic set of LTE UE Contexts
int init_lte_ue_contexts(struct lte_ue_context** contexts, size_t num_contexts) {
    // Check for null pointer input
    if (contexts == NULL || num_contexts == 0) {
        return -1;
    }

    // Initialize the UE Contexts array and lock
    ue_contexts = contexts;
    pthread_mutex_lock(&ue_context_lock);

    // Configure each UE Context
    for (size_t i = 0; i < num_contexts; i++) {
        struct lte_ue_context* ctx = &ue_contexts[i];

        // Initialize the RNTI and PDU Session list
        ctx->rnti = -1;
        ctx->num_sessions = 0;
        ctx->sessions[MAX_PDU_SESSIONS] = NULL;

        // Set the UE ID and add a new session
        int ue_id = i + 1;
        add_pdu_session(ctx, ue_id, "default");
    }

    // Unlock the UE Contexts array
    pthread_mutex_unlock(&ue_context_lock);

    return 0;
}

// Function to add a new PDU Session to an LTE UE Context
int add_pdu_session(struct lte_ue_context* ctx, int ue_id, char* apn) {
    // Check for null pointer input
    if (ctx == NULL || ue_id < 0 || apn == NULL) {
        return -1;
    }

    // Lock the UE Context
    pthread_mutex_lock(&ue_context_lock);

    // Initialize a new PDU Session struct
    struct pdu_session* session = (struct pdu_session*)malloc(sizeof(struct pdu_session));
    if (session == NULL) {
        fprintf(stderr, "Error: failed to allocate memory for PDU Session\n");
        return -1;
    }

    // Set the QoS profile and APN
    session->qos_profile = 0;
    session->apn = strdup(apn);

    // Add the new session to the UE Context's list
    ctx->num_sessions++;
    ctx->sessions[ctx->num_sessions - 1] = session;

    // Unlock the UE Context
    pthread_mutex_unlock(&ue_context_lock);

    return 0;
}

// Function to remove a PDU Session from an LTE UE Context
int remove_pdu_session(struct lte_ue_context* ctx, int ue_id) {
    // Check for null pointer input
    if (ctx == NULL || ue_id < 0) {
        return -1;
    }

    // Lock the UE Context
    pthread_mutex_lock(&ue_context_lock);

    // Find the PDU Session to remove
    struct pdu_session* session = NULL;
    for (size_t i = 0; i < ctx->num_sessions; i++) {
        if (ctx->sessions[i]->ue_id == ue_id) {
            session = ctx->sessions[i];
            break;
        }
    }

    // Remove the PDU Session from the UE Context's list
    if (session != NULL) {
        for (size_t i = 0; i < ctx->num_sessions - 1; i++) {
            if (ctx->sessions[i] == session) {
                ctx->sessions[i] = ctx->sessions[ctx->num_sessions - 1];
                break;
            }
        }
        ctx->num_sessions--;
    } else {
        fprintf(stderr, "Error: PDU Session with UE ID %d not found\n", ue_id);
        return -1;
    }

    // Free the memory for the removed session
    free(session->apn);
    free(session);

    // Unlock the UE Context
    pthread_mutex_unlock(&ue_context_lock);

    return 0;
}
