                // If not, fill the record with random values within a specified range
                ue_contexts[i]->pdu_sessions[k]->value = rand() % 1000 + 1;
            }
        }
    }

    // Print out the total number of records successfully initialized, along with their int values and starting indices of the long segments they reference
