        if (frames[i] != NULL && frames[i]->id == id) {
            void* frame = malloc(sizeof(LTE_PHY_RX_FRAME));
            memcpy(frame, frames[i], sizeof(LTE_PHY_RX_FRAME));
            pthread_mutex_unlock(&frame_lock);
            return frame;
        }
    }
    // If the frame does not exist, return NULL
    pthread_mutex_unlock(&frame_lock);
    return NULL;
}

// Create a function to delete a frame by ID
