    pthread_mutex_lock(&frame_lock);
    // Check if the frame exists in the hash table
    for (int i = 0; i < 100; i++) {
        if (frames[i] != NULL && frames[i]->id == id) {
            free(frames[i]);
            frames[i] = NULL;
            pthread_mutex_unlock(&frame_lock);
            return;
        }
