    if (capacity < count) {
        // Dynamically resize the list to accommodate more elements
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * count);
        if (new_list == NULL) {
