    for (size_t i = 0; i < count; i++) {
        NFAPI_CRC_INDICATION_PDU_T *pdu = &list[i];
        pdu->rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
        if (pdu->rx_ue_info == NULL) {
