        pdu->rnti = rand() % 10000; // randomize the RNTI value
        pdu->crc_indication.CRCFLAG = rand() % 2; // randomize the CRCFLAG value
    }
}

// Insert a new structure into the list, handling concurrent access safely
void insert(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&list_mutex);
    if (size < capacity) {
        // Copy the structure to the next available index in the list
        memcpy(&list[size], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        size++;
    } else {
        // Dynamically resize the list if it is full
        NFAPI_CRC_INDICATION_PDU_T *new_list = realloc(list, 2 * capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (new_list == NULL) {
            // Memory allocation failed, handle the error gracefully
            printf("Failed to allocate memory for CRC indication list\n");
            pthread_mutex_unlock(&list_mutex);
            return;
        }
        list = new_list;
        capacity *= 2;
    }
    pthread_mutex_unlock(&list_mutex);
}

// Remove a structure from the list, handling concurrent access safely
void remove(size_t index) {
    pthread_mutex_lock(&list_mutex);
    if (index < size) {
        // Free the memory allocated to the removed structure
        free(list[index].rx_ue_info);
        memmove(&list[index], &list[index + 1], (size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        size--;
    } else {
        printf("Index %zu is out of range\n", index);
    }
    pthread_mutex_unlock(&list_mutex);
}

// Free the memory allocated to the list and its elements
void free_crc_indications() {
    for (size_t i = 0; i < size; i++) {
        free(list[i].rx_ue_info);
    }
    free(list);
}
