#include <stdio.h>

#define MAX_FRAMES 1024 // maximum number of frames to store in the list
#define FRAME_SIZE 512 // size of each frame (in bytes)
#define ERROR_THRESHOLD 5 // error threshold for validating received frames

typedef struct {
    RX_FRAME_HEADER header;
    int snr;
    unsigned long rx_timestamp;
    int frame_error_status;
} PHY_RX_FRAME_INFO_T;

// thread-safe list for storing received frames
struct frame_list {
    PHY_RX_FRAME_INFO_T *frames[MAX_FRAMES]; // array of pointers to frames
    int size; // current number of frames in the list
};

static struct frame_list frame_list = {NULL, 0}; // global variable for shared access

// allocate memory for a new frame and add it to the list
void alloc_and_add_frame(PHY_RX_FRAME_INFO_T *frame) {
    if (frame_list.size >= MAX_FRAMES) {
        // handle full list case
        printf("Error: frame list is full\n");
        return;
    }
    PHY_RX_FRAME_INFO_T *new_frame = malloc(sizeof(PHY_RX_FRAME_INFO_T));
    memcpy(new_frame, frame, sizeof(PHY_RX_FRAME_INFO_T));
    frame_list.frames[frame_list.size++] = new_frame;
}

// validate a received frame and add it to the list if valid
void handle_received_frame(PHY_RX_FRAME_INFO_T *frame) {
    // check error threshold for frame validity
    int validity_check = validate_frame(frame);
    if (validity_check == 0) {
        alloc_and_add_frame(frame);
    } else {
        printf("Error: received frame failed validation with error code %d\n", validity_check);
    }
}

// validate a received frame by checking its SNR and timestamp fields
int validate_frame(PHY_RX_FRAME_INFO_T *frame) {
    if (frame->snr <= ERROR_THRESHOLD || frame->rx_timestamp == 0) {
        return -1; // invalid frame
    }
    return 0; // valid frame
}

// process a received frame by calling the hardware library's processing function
void process_frame(PHY_RX_FRAME_INFO_T *frame) {
    // call the hardware library's processing function with the frame data
    int status = hardware_lib_process_frame(&(frame->header), &(frame->snr), &(frame->rx_timestamp));
    if (status != 0) {
        printf("Error: hardware library processing failed with error code %d\n", status);
    }
}

// main function for the NIC driver
int nic_main() {
    while (1) { // infinite loop to continuously receive and process frames
        PHY_RX_FRAME_INFO_T *frame = hardware_lib_receive_frame(); // receive frame from hardware library
        handle_received_frame(frame); // validate and add the received frame to the list
        process_frame(frame); // call the hardware library's processing function with the validated frame data
    }
}
