// Define the resource bundle structure
typedef struct {
    LTE_PHY_RX_FRAME* frames[];
    size_t numFrames;
} RESOURCE_BUNDLE;

int manageLTE_PHY_RX_FRAME_and_processResources(const char* resourceFile) {
    // Load the resource bundle from the file
    RESOURCE_BUNDLE* bundle = loadResourceBundleFromFile(resourceFile);
    if (bundle == NULL) {
        return -1;
    }

    // Validate the contents of the resource bundle
    if (!validateResourceBundleContents(bundle)) {
        freeResourceBundle(bundle);
        return -2;
    }

    // Initialize a dynamic array to store the LTE PHY frames
    LTE_PHY_RX_FRAME** frames = (LTE_PHY_RX_FRAME**)malloc(sizeof(LTE_PHY_RX_FRAME*) * bundle->numFrames);
    if (frames == NULL) {
        freeResourceBundle(bundle);
        return -3;
    }

    // Dynamically allocate memory for each LTE PHY frame and populate the array
    size_t numValidFrames = 0;
    for (size_t i = 0; i < bundle->numFrames; i++) {
        frames[i] = malloc(sizeof(LTE_PHY_RX_FRAME));
        if (frames[i] == NULL) {
            break;
        }
        memcpy(frames[i], &bundle->frames[i], sizeof(LTE_PHY_RX_FRAME));
        numValidFrames++;
    }

    // Clean up memory if any frames were not allocated successfully
    for (size_t i = 0; i < numValidFrames; i++) {
        free(frames[i]);
    }
    free(frames);

    // Free the resource bundle
    freeResourceBundle(bundle);

    return numValidFrames;
}

void loadResourceBundleFromFile(const char* resourceFile) {
    // Open the file and check for errors
    FILE* fp = fopen(resourceFile, "r");
    if (fp == NULL) {
        perror("Error opening file");
        return;
    }

    // Read the number of frames in the bundle from the first line of the file
    size_t numFrames;
    char* endptr = NULL;
    fscanf(fp, "%lu", &numFrames);

    // Dynamically allocate memory for the resource bundle and populate it
    RESOURCE_BUNDLE* bundle = malloc(sizeof(RESOURCE_BUNDLE));
    if (bundle == NULL) {
        perror("Error allocating memory for resource bundle");
        return;
    }
    bundle->frames = (LTE_PHY_RX_FRAME*)malloc(sizeof(LTE_PHY_RX_FRAME) * numFrames);
    if (bundle->frames == NULL) {
        perror("Error allocating memory for LTE PHY frames");
        freeResourceBundle(bundle);
        return;
    }
    bundle->numFrames = numFrames;

    // Read each frame from the file and populate the resource bundle
    size_t i = 0;
    while (fscanf(fp, "%c", &bundle->frames[i].header[i]) != EOF && i < numFrames) {
        // Parse the header and populate the structure
        fscanf(fp, "%d %d %f", &bundle->frames[i].signalStrength, &bundle->frames[i].symbols[i].modulationType, &bundle->frames[i].symbols[i].phaseRotation);
        bundle->frames[i].symbols[i].noiseVarianceEstimate = fscanf(fp, "%f", &bundle->frames[i].symbols[i].noiseVarianceEstimate);
        i++;
    }

    // Close the file and return the resource bundle
    fclose(fp);
    return bundle;
}

bool validateResourceBundleContents(RESOURCE_BUNDLE* bundle) {
    // Check that each frame has a valid header, signal strength indicator, and symbol list
    for (size_t i = 0; i < bundle->numFrames; i++) {
        if (!isValidHeader(bundle->frames[i].header)) {
            return false;
        }
        if (!isValidSignalStrengthIndicator(bundle->frames[i].signalStrength)) {
            return false;
        }
        for (size_t j = 0; j < sizeof(LTE_PHY_RX_SYMBOL); j++) {
            if (!isValidSymbolList(bundle->frames[i].symbols[j])) {
                return false;
            }
        }
    }
    return true;
}

bool isValidHeader(unsigned char* header) {
    // Check that the header is a valid length and contains only ASCII characters
    if (strlen((const char*)header) != 20) {
        return false;
    }
    for (size_t i = 0; i < 20; i++) {
        if (!isalpha(header[i])) {
            return false;
        }
    }
    return true;
}

bool isValidSignalStrengthIndicator(int signalStrength) {
    // Check that the signal strength indicator is within a valid range
    return (signalStrength >= 0 && signalStrength <= 100);
}

bool isValidSymbolList(LTE_PHY_RX_SYMBOL* symbolList) {
    // Check that each symbol in the list has a valid modulation type, phase rotation, and noise variance estimate
    for (size_t i = 0; i < sizeof(LTE_PHY_RX_SYMBOL); i++) {
        if (!isValidModulationType(symbolList->modulationType)) {
            return false;
        }
        if (!isValidPhaseRotation(symbolList->phaseRotation)) {
            return false;
        }
        if (!isValidNoiseVarianceEstimate(symbolList->noiseVarianceEstimate)) {
            return false;
        }
    }
    return true;
}

bool isValidModulationType(int modulationType) {
    // Check that the modulation type is valid
    if (modulationType != 0 && modulationType != 1 && modulationType != 2 && modulationType != 3 && modulationType != 4) {
        return false;
    }
    return true;
}

bool isValidPhaseRotation(float phaseRotation) {
    // Check that the phase rotation is within a valid range
    if (phaseRotation < -180 || phaseRotation > 180) {
        return false;
    }
    return true;
}

bool isValidNoiseVarianceEstimate(float noiseVarianceEstimate) {
    // Check that the noise variance estimate is within a valid range
    if (noiseVarianceEstimate < 0 || noiseVarianceEstimate > 1) {
        return false;
    }
    return true;
}
