static size_t list_size = 0;
static size_t list_capacity = 0;

// Add a new entry to the list
void add_entry(NFAPI_CRC_INDICATION_PDU_T* entry) {
    pthread_mutex_lock(&lock);
    if (list_size == list_capacity) {
        // Resize the list when it reaches capacity
        list_capacity *= 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = realloc(list, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list_capacity);
        if (new_list == NULL) {
            perror("realloc failed");
            exit(EXIT_FAILURE);
        }
        list = new_list;
    }
    // Copy the entry to the next available slot in the list
    memcpy(&list[list_size], entry, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list_size++;
    pthread_mutex_unlock(&lock);
}

// Remove an entry from the list by its RNTI
void remove_entry(RNTI rnti) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < list_size; i++) {
        if (list[i].rnti == rnti) {
            // Shift the subsequent entries in the list to fill the gap
            memmove(&list[i], &list[i + 1], sizeof(NFAPI_CRC_INDICATION_PDU_T) * (list_size - i));
            list_size--;
        }
    }
    pthread_mutex_unlock(&lock);
}

// Validate an entry in the list by its RNTI and CRC flag
bool validate_entry(RNTI rnti, bool crc_flag) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < list_size; i++) {
        if (list[i].rnti == rnti && list[i].crc_indication_rel8.crc_flag == crc_flag) {
            pthread_mutex_unlock(&lock);
            return true;
        }
    }
    pthread_mutex_unlock(&lock);
    return false;
}

// Thread-safe function to retrieve a random entry from the list
NFAPI_CRC_INDICATION_PDU_T* get_random_entry() {
    pthread_mutex_lock(&lock);
    size_t index = rand() % list_size;
    NFAPI_CRC_INDICATION_PDU_T* entry = &list[index];
    pthread_mutex_unlock(&lock);
    return entry;
}

// Thread-safe function to retrieve an entry from the list by its RNTI
NFAPI_CRC_INDICATION_PDU_T* get_entry(RNTI rnti) {
    pthread_mutex_lock(&lock);
    for (size_t i = 0; i < list_size; i++) {
        if (list[i].rnti == rnti) {
            NFAPI_CRC_INDICATION_PDU_T* entry = &list[i];
            pthread_mutex_unlock(&lock);
            return entry;
        }
    }
    pthread_mutex_unlock(&lock);
    return NULL;
}
