// High-performance C function to manage a dynamic list of LTE_PHY_MEASUREMENTS structures
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>

struct LTE_PHY_MEASUREMENTS {
    int CELL_ID;
    float SNR, RSRP, RSRQ;
    time_t timestamp;
};

typedef struct LTE_PHY_MEASUREMENTS LTE_PHY_MEASUREMENTS;

// Data structure to hold the dynamic list of measurements
struct MeasurementList {
    int size;
    LTE_PHY_MEASUREMENTS* data;
};

typedef struct MeasurementList MeasurementList;

// Lock for thread-safe operations on the measurement list
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new measurement to the list
void addMeasurement(LTE_PHY_MEASUREMENTS* measurement) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Check if the cell ID already exists in the list
    for (int i = 0; i < measurementList.size; i++) {
        if (measurement->CELL_ID == measurementList.data[i].CELL_ID) {
            // Update the existing measurement with the new values
            measurementList.data[i] = *measurement;
            break;
        }
    }

    // If the cell ID was not found, add a new entry to the list
    if (i == measurementList.size) {
        measurementList.data = realloc(measurementList.data, sizeof(LTE_PHY_MEASUREMENTS) * (measurementList.size + 1));
        measurementList.data[measurementList.size] = *measurement;
        measurementList.size++;
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock);
}

// Function to update a measurement in the list
void updateMeasurement(LTE_PHY_MEASUREMENTS* measurement) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Check if the cell ID exists in the list
    int i;
    for (i = 0; i < measurementList.size; i++) {
        if (measurement->CELL_ID == measurementList.data[i].CELL_ID) {
            break;
        }
    }

    // If the cell ID was found, update the existing entry with the new values
    if (i < measurementList.size) {
        measurementList.data[i] = *measurement;
    } else {
        // Log an error and return since the cell ID does not exist in the list
        printf("Error: Cell ID %d not found in the measurement list\n", measurement->CELL_ID);
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock);
}

// Function to validate a measurement in the list
void validateMeasurement(LTE_PHY_MEASUREMENTS* measurement) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Check if the cell ID exists in the list
    int i;
    for (i = 0; i < measurementList.size; i++) {
        if (measurement->CELL_ID == measurementList.data[i].CELL_ID) {
            break;
        }
    }

    // If the cell ID was found, validate the existing entry with the new values
    if (i < measurementList.size) {
        if (measurement->SNR != measurementList.data[i].SNR ||
            measurement->RSRP != measurementList.data[i].RSRP ||
            measurement->RSRQ != measurementList.data[i].RSRQ) {
                // Log an error and return since the measurements do not match
                printf("Error: Measurement for cell ID %d does not match\n", measurement->CELL_ID);
        }
    } else {
        // Log an error and return since the cell ID does not exist in the list
        printf("Error: Cell ID %d not found in the measurement list\n", measurement->CELL_ID);
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock);
}

// Function to retrieve a measurement from the list
LTE_PHY_MEASUREMENTS* getMeasurement(int CELL_ID) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Check if the cell ID exists in the list
    int i;
    for (i = 0; i < measurementList.size; i++) {
        if (CELL_ID == measurementList.data[i].CELL_ID) {
            break;
        }
    }

    // If the cell ID was found, return a pointer to the existing entry
    LTE_PHY_MEASUREMENTS* measurement = NULL;
    if (i < measurementList.size) {
        measurement = &measurementList.data[i];
    } else {
        // Log an error and return since the cell ID does not exist in the list
        printf("Error: Cell ID %d not found in the measurement list\n", CELL_ID);
    }

    // Release the lock and return
    pthread_mutex_unlock(&lock);
    return measurement;
}

// Function to clear the measurement list
void clearMeasurements() {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Release any existing memory allocated for the measurement list
    free(measurementList.data);
    measurementList.size = 0;
    measurementList.data = NULL;

    // Release the lock and return
    pthread_mutex_unlock(&lock);
}

// Function to handle unexpected spikes in data throughput
void handleUnexpectedSpike(int newMeasurements) {
    // Acquire the lock for thread-safe operations
    pthread_mutex_lock(&lock);

    // Update the size of the measurement list to accommodate the new measurements
    int oldSize = measurementList.size;
    measurementList.data = realloc(measurementList.data, sizeof(LTE_PHY_MEASUREMENTS) * (oldSize + newMeasurements));
    for (int i = 0; i < newMeasurements; i++) {
        // Initialize the new measurements with default values
        measurementList.data[oldSize + i].CELL_ID = -1;
        measurementList.data[oldSize + i].SNR = -1;
        measurementList.data[oldSize + i].RSRP = -1;
        measurementList.data[oldSize + i].RSRQ = -1;
    }
    measurementList.size += newMeasurements;

    // Release the lock and return
    pthread_mutex_unlock(&lock);
}
