} NFAPI_CRC_INDICATION_PDU_T;

// Array size limit
#define MAX_ARRAY_SIZE 10000

// Thread-safe array structure
typedef struct {
    pthread_mutex_t mutex; // Mutex for synchronization
    NFAPI_CRC_INDICATION_PDU_T *array; // Array of structures
    size_t capacity; // Current array capacity
} NFAPI_CRC_INDICATION_ARRAY;

// Function to initialize the array
void init_array(NFAPI_CRC_INDICATION_ARRAY *array) {
    array->mutex = PTHREAD_MUTEX_INITIALIZER; // Initialize mutex
    array->capacity = 0; // Set initial capacity to 0
    array->array = NULL; // Set initial array pointer to null
}

// Function to add a new structure to the array
void add_structure(NFAPI_CRC_INDICATION_ARRAY *array, NFAPI_CRC_INDICATION_PDU_T structure) {
    pthread_mutex_lock(&array->mutex); // Acquire mutex lock

    // Check if the array is full
    if (array->capacity == MAX_ARRAY_SIZE) {
        printf("Error: Array is full, cannot add new structure\n");
        pthread_mutex_unlock(&array->mutex); // Release mutex lock
        return;
    }

    // Check if the structure is valid
    if (!validate_structure(structure)) {
        printf("Error: Structure is invalid, cannot add to array\n");
        pthread_mutex_unlock(&array->mutex); // Release mutex lock
        return;
    }

    // Reallocate memory for the array if necessary
    if (array->capacity == 0) {
        array->array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    } else {
        array->array = realloc(array->array, sizeof(NFAPI_CRC_INDICATION_PDU_T) * (array->capacity + 1));
    }

    // Copy the new structure to the end of the array
    memcpy(&array->array[array->capacity], &structure, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    array->capacity++;

    pthread_mutex_unlock(&array->mutex); // Release mutex lock
}

// Function to validate a structure
int validate_structure(NFAPI_CRC_INDICATION_PDU_T structure) {
    if (structure.RX_UE_INFORMATION_TAG != 1 || structure.RNTI == 0 || structure.CRC_INDICATION_REL8_TAG == 0) {
        return 0; // Structure is invalid
    } else {
        return 1; // Structure is valid
    }
}

// Function to remove a structure from the array
void remove_structure(NFAPI_CRC_INDICATION_ARRAY *array, int index) {
    pthread_mutex_lock(&array->mutex); // Acquire mutex lock

    // Check if the index is valid
    if (index < 0 || index >= array->capacity) {
        printf("Error: Index is invalid\n");
        pthread_mutex_unlock(&array->mutex); // Release mutex lock
        return;
    }

    // Shift all elements after the specified index to fill the gap
    for (int i = index + 1; i < array->capacity; i++) {
        memcpy(&array->array[i - 1], &array->array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    }

    // Reduce the capacity of the array by one
    array->capacity--;

    pthread_mutex_unlock(&array->mutex); // Release mutex lock
