#define LOG(format, ...) printf("[LOG] " format "\n", __VA_ARGS__)
#define ERROR(format, ...) fprintf(stderr, "[ERROR] " format "\n", __VA_ARGS__)

// Data structure to represent a MAC context
typedef struct {
  int logical_channel_group_id;
  int rb_id;
  int transmission_power_level;
} MAC_CONTEXT_T;

// Function to manage the list of MAC contexts
void mange_mac_context(MAC_CONTEXT_T **context, int num_contexts) {
  // Allocate memory for the list of MAC contexts
  *context = malloc(sizeof(MAC_CONTEXT_T) * num_contexts);
  if (*context == NULL) {
    ERROR("Failed to allocate memory for MAC context list");
    return;
  }

  // Initialize the list of MAC contexts to default values
  for (int i = 0; i < num_contexts; i++) {
    (*context)[i].logical_channel_group_id = -1;
    (*context)[i].rb_id = -1;
    (*context)[i].transmission_power_level = -1;
  }

  // Set the current size of the list to zero
  int current_size = 0;

  // Function to add a new MAC context to the list
  void add_mac_context(MAC_CONTEXT_T *new_context) {
    if (current_size >= num_contexts) {
      ERROR("Maximum capacity of MAC context list reached");
      return;
    }
    (*context)[current_size] = *new_context;
    current_size++;
  }

  // Function to get the number of MAC contexts in the list
  int get_num_mac_contexts() {
    return current_size;
  }

  // Function to serialize the list of MAC contexts into a binary format
  void serialize_mac_contexts(char *buffer, int buffer_len) {
    if (buffer == NULL || buffer_len <= 0) {
      ERROR("Invalid buffer");
      return;
    }
    // Serialize the list of MAC contexts into a binary format compatible with existing systems
    int pos = 0;
    for (int i = 0; i < current_size; i++) {
      MAC_CONTEXT_T *context = &(*context)[i];
      pos += serialize_int(&buffer[pos], buffer_len - pos, context->logical_channel_group_id);
      pos += serialize_int(&buffer[pos], buffer_len - pos, context->rb_id);
      pos += serialize_int(&buffer[pos], buffer_len - pos, context->transmission_power_level);
    }
  }

  // Function to deserialize the list of MAC contexts from a binary format
  void deserialize_mac_contexts(char *buffer, int buffer_len) {
    if (buffer == NULL || buffer_len <= 0) {
      ERROR("Invalid buffer");
      return;
    }
    // Deserialize the list of MAC contexts from a binary format compatible with existing systems
    int pos = 0;
    for (int i = 0; i < current_size; i++) {
      MAC_CONTEXT_T *context = &(*context)[i];
      pos += deserialize_int(&buffer[pos], buffer_len - pos, &context->logical_channel_group_id);
      pos += deserialize_int(&buffer[pos], buffer_len - pos, &context->rb_id);
      pos += deserialize_int(&buffer[pos], buffer_len - pos, &context->transmission_power_level);
    }
  }

  // Function to clear the list of MAC contexts and reset them to a default state
  void clear_mac_contexts() {
    current_size = 0;
  }
}
