    CRC_INDICATION_LIST* current = head;
    while (current->next != NULL && current->next != element) {
        current = current->next;
    }
    if (current->next == NULL) {
        return;
    }
    // Remove the node from the list
    current->next = current->next->next;
    free(current->next);
