            current->crc_indication_rel8_tag == element->crc_indication_rel8_tag) {
            return true;
        }
        current = current->next;
    }
    return false;
}

// Define a function to iterate over the elements in the doubly linked list
void iterate_elements(void (*func)(NFAPI_CRC_INDICATION_PDU_T*)) {
    CRC_INDICATION_LIST* current = head;
    while (current != NULL) {
        func(current->next);
        current = current->next;
    }
}

// Define a function to clean up the doubly linked list
void cleanup() {
    CRC_INDICATION_LIST* current = head;
    while (current != NULL) {
        free(current);
        current = current->next;
    }
