#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// Define the data structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_information;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the doubly linked list for storing the data structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t size;
    struct node *next;
    struct node *prev;
} NFAPI_CRC_INDICATION_LIST_T;

// Define the function to manage the list of data structures
void nfapi_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T *data, size_t size) {
    // Check if the data is valid and initialize the list
    if (data && size > 0) {
        NFAPI_CRC_INDICATION_LIST_T *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
        list->size = size;
        list->next = NULL;
        list->prev = NULL;

        // Loop through the data and add each structure to the list
        for (int i = 0; i < size; i++) {
            NFAPI_CRC_INDICATION_PDU_T *current = &data[i];
            if (!nfapi_crc_indication_is_valid(current)) {
                continue;
            }
            list->data = current;
        }

        // Synchronize access to the list and prevent duplicates
        pthread_mutex_lock(&list->mutex);
        NFAPI_CRC_INDICATION_PDU_T *current = list->next;
        while (current != NULL) {
            if (!nfapi_crc_indication_is_valid(current)) {
                current = current->next;
                continue;
            }
            if (nfapi_crc_indication_contains_rnti(list, current->rnti)) {
                current = current->next;
                continue;
            }
            break;
        }
        list->next = current;
        pthread_mutex_unlock(&list->mutex);
    }
}

// Check if the data structure is valid
bool nfapi_crc_indication_is_valid(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Check if the RX_UE_INFORMATION_TAG is valid and the RNTI value is within the valid range
    if (data->rx_ue_information.rx_indication_rel8.crc_flag == 0 || data->rnti < 0 || data->rnti > 65535) {
        return false;
    }
    return true;
}

// Check if the list contains a specific RNTI value
bool nfapi_crc_indication_contains_rnti(NFAPI_CRC_INDICATION_LIST_T *list, int rnti) {
    // Synchronize access to the list and search for the RNTI value
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->next;
    while (current != NULL) {
        if (current->rnti == rnti) {
            pthread_mutex_unlock(&list->mutex);
            return true;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list->mutex);
    return false;
}

// Add a data structure to the list
void nfapi_crc_indication_add(NFAPI_CRC_INDICATION_PDU_T *data) {
    // Check if the data is valid and initialize the list
    if (!nfapi_crc_indication_is_valid(data)) {
        return;
    }

    // Synchronize access to the list and add the data structure
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->next;
    while (current != NULL) {
        if (!nfapi_crc_indication_is_valid(current)) {
            current = current->next;
