// Remove a data structure from the list
void nfapi_crc_indication_remove(int rnti) {
    // Synchronize access to the list and search for the RNTI value
    pthread_mutex_lock(&list->mutex);
    NFAPI_CRC_INDICATION_PDU_T *current = list->next;
