#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <stdint.h>
#include <stdio.h>
#include <stdbool.h>

// Data structure for records in the data store
typedef struct record {
    int key;
    long offset;
    char buffer[256];
} record_t;

// Data structure for the dynamic array of records
typedef struct {
    record_t* records;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
} data_store_t;

data_store_t* create_data_store(size_t initial_capacity) {
    data_store_t* store = malloc(sizeof(data_store_t));
    if (!store) {
        return NULL;
    }

    // Initialize the data store with the given initial capacity
    store->records = malloc(initial_capacity * sizeof(record_t));
    if (!store->records) {
        free(store);
        return NULL;
    }
    store->capacity = initial_capacity;
    store->size = 0;

    // Initialize the mutex for thread-safe access to the data store
    pthread_mutex_init(&store->mutex, NULL);

    return store;
}

void destroy_data_store(data_store_t* store) {
    if (!store) {
        return;
    }

    // Release the memory for the records and mutex
    free(store->records);
    pthread_mutex_destroy(&store->mutex);
    free(store);
}

// Insert a new record into the data store
int insert_record(data_store_t* store, int key, long offset, const char* buffer) {
    if (!store || !buffer) {
        return -1;
    }

    // Acquire the mutex for thread-safe access to the data store
    pthread_mutex_lock(&store->mutex);

    // Check if the data store needs to be resized
    if (store->size >= store->capacity) {
        size_t new_capacity = store->capacity * 2;
        record_t* new_records = realloc(store->records, new_capacity * sizeof(record_t));
        if (!new_records) {
            pthread_mutex_unlock(&store->mutex);
            return -1;
        }
        store->records = new_records;
        store->capacity = new_capacity;
    }

    // Copy the record into the data store
    memcpy(&(store->records[store->size]), buffer, sizeof(record_t));
    store->records[store->size].key = key;
    store->records[store->size].offset = offset;
    strncpy(store->records[store->size].buffer, buffer, 256);
    store->size++;

    // Release the mutex for thread-safe access to the data store
    pthread_mutex_unlock(&store->mutex);

    return 0;
}

// Lookup a record in the data store by its key
record_t* lookup_record(data_store_t* store, int key) {
    if (!store) {
        return NULL;
    }

    // Acquire the mutex for thread-safe access to the data store
    pthread_mutex_lock(&store->mutex);

    // Iterate over the records in the data store and find the one with the given key
    for (size_t i = 0; i < store->size; i++) {
        if (store->records[i].key == key) {
            record_t* record = malloc(sizeof(record_t));
            memcpy(record, &(store->records[i]), sizeof(record_t));
            pthread_mutex_unlock(&store->mutex);
            return record;
        }
    }

    // Release the mutex for thread-safe access to the data store
    pthread_mutex_unlock(&store->mutex);

    return NULL;
}

// Update a record in the data store by its key
int update_record(data_store_t* store, int key, long offset, const char* buffer) {
    if (!store || !buffer) {
        return -1;
    }

    // Acquire the mutex for thread-safe access to the data store
    pthread_mutex_lock(&store->mutex);

    // Iterate over the records in the data store and find the one with the given key
    for (size_t i = 0; i < store->size; i++) {
        if (store->records[i].key == key) {
            strncpy(store->records[i].buffer, buffer, 256);
            store->records[i].offset = offset;
            pthread_mutex_unlock(&store->mutex);
            return 0;
        }
    }

    // Release the mutex for thread-safe access to the data store
    pthread_mutex_unlock(&store->mutex);

    return -1;
}

// Resize the data store when the number of records exceeds its capacity
int resize_data_store(data_store_t* store, size_t new_capacity) {
    if (!store || new_capacity <= 0) {
        return -1;
    }

    // Acquire the mutex for thread-safe access to the data store
    pthread_mutex_lock(&store->mutex);

    // Reallocate memory for the records and update the capacity
    record_t* new_records = realloc(store->records, new_capacity * sizeof(record_t));
    if (!new_records) {
        pthread_mutex_unlock(&store->mutex);
        return -1;
    }
    store->records = new_records;
    store->capacity = new_capacity;

    // Release the mutex for thread-safe access to the data store
    pthread_mutex_unlock(&store->mutex);

    return 0;
}

// Evaluate the performance of the data store by tracking the number of successful lookups, inserts, and updates
void evaluate_performance(data_store_t* store) {
    if (!store) {
        return;
    }

    // Acquire the mutex for thread-safe access to the data store
    pthread_mutex_lock(&store->mutex);

    printf("Number of successful lookups: %zu\n", store->lookup_count);
    printf("Number of successful inserts: %zu\n", store->insert_count);
    printf("Number of successful updates: %zu\n", store->update_count);
    printf("Number of failed operations: %zu\n", store->failed_operation_count);

    // Release the mutex for thread-safe access to the data store
    pthread_mutex_unlock(&store->mutex);
}']

