};

// Structure to store the hash table itself
struct NFAPI_CRC_INDICATION_HASH_TABLE {
    struct NFAPI_CRC_INDICATION_PDU** entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
};

// Function to create a new hash table with the given capacity
struct NFAPI_CRC_INDICATION_HASH_TABLE* nfapi_crc_indication_hash_table_create(size_t capacity) {
    struct NFAPI_CRC_INDICATION_HASH_TABLE* table = malloc(sizeof(struct NFAPI_CRC_INDICATION_HASH_TABLE));
    table->entries = calloc(capacity, sizeof(struct NFAPI_CRC_INDICATION_PDU*));
    table->capacity = capacity;
    table->count = 0;
    pthread_mutex_init(&table->mutex, NULL);
    return table;
}

// Function to destroy a hash table and free its resources
void nfapi_crc_indication_hash_table_destroy(struct NFAPI_CRC_INDICATION_HASH_TABLE* table) {
    pthread_mutex_destroy(&table->mutex);
    free(table->entries);
    free(table);
}

// Function to insert a new entry into the hash table
bool nfapi_crc_indication_hash_table_insert(struct NFAPI_CRC_INDICATION_HASH_TABLE* table, struct NFAPI_CRC_INDICATION_PDU* pdu) {
    pthread_mutex_lock(&table->mutex);
    size_t index = hash(pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG) % table->capacity;
    while (table->entries[index] != NULL) {
        index++;
        if (index == table->capacity) {
            index = 0;
        }
    }
    table->entries[index] = pdu;
    table->count++;
    pthread_mutex_unlock(&table->mutex);
}

// Function to retrieve an entry from the hash table by its key
struct NFAPI_CRC_INDICATION_PDU* nfapi_crc_indication_hash_table_lookup(struct NFAPI_CRC_INDICATION_HASH_TABLE* table, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, bool CRCFLAG) {
