    size_t index = hash(RX_UE_INFORMATION_TAG, RNTI, CRCFLAG) % table->capacity;
    while (table->entries[index] != NULL && !nfapi_crc_indication_equals(table->entries[index], RX_UE_INFORMATION_TAG, RNTI, CRCFLAG)) {
        index++;
        if (index == table->capacity) {
            index = 0;
