#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

#define LTE_PHY_RX_FRAME_SIZE 1024 // size of a single frame in bytes
#define MAX_NUM_FRAMES 10000 // maximum number of frames to be stored
#define FLUSH_THRESHOLD 500 // threshold for flushing old or unused frames
#define MIN_FRAME_SIZE 256 // minimum size of a frame in bytes
#define MAX_FRAME_SIZE 1024 // maximum size of a frame in bytes
#define MAX_NUM_SYMBOLS 100 // maximum number of symbols per frame
#define SYMBOL_SIZE 32 // size of a single symbol in bytes

typedef struct LTE_PHY_RX_FRAME {
    char header[LTE_PHY_RX_FRAME_SIZE]; // valid LTE PHY frame header
    int signal_strength; // signal strength indicator
    struct LTE_PHY_RX_SYMBOL symbols[MAX_NUM_SYMBOLS]; // variable-length list of symbols
} LTE_PHY_RX_FRAME;

typedef struct LTE_PHY_RX_SYMBOL {
    int modulation_type; // modulation type
    int phase_rotation; // phase rotation
    float noise_variance_estimate; // noise variance estimate
} LTE_PHY_RX_SYMBOL;

// mutex to protect the array of frames
pthread_mutex_t frame_array_mutex = PTHREAD_MUTEX_INITIALIZER;

// condition variable to signal when a new frame is added or removed
pthread_cond_t frame_added_cond = PTHREAD_COND_INITIALIZER;

// array of frames, dynamically allocated and resized as needed
LTE_PHY_RX_FRAME* frame_array = NULL;

// number of frames in the array
int num_frames = 0;

// function to add a new frame to the array
void add_frame(char* header, int signal_strength, struct LTE_PHY_RX_SYMBOL* symbols) {
    pthread_mutex_lock(&frame_array_mutex);

    // check if the array needs to be resized
    if (num_frames == MAX_NUM_FRAMES) {
        resize_frame_array();
    }

    // add the new frame to the end of the array
    LTE_PHY_RX_FRAME* new_frame = &frame_array[num_frames];
    memcpy(new_frame->header, header, LTE_PHY_RX_FRAME_SIZE);
    new_frame->signal_strength = signal_strength;
    memcpy(new_frame->symbols, symbols, MAX_NUM_SYMBOLS * SYMBOL_SIZE);

    // increment the number of frames in the array
    num_frames++;

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to remove a frame from the array
void remove_frame(int index) {
    pthread_mutex_lock(&frame_array_mutex);

    // decrement the number of frames in the array
    num_frames--;

    // swap the removed frame with the last frame in the array
    LTE_PHY_RX_FRAME* removed_frame = &frame_array[index];
    LTE_PHY_RX_FRAME* last_frame = &frame_array[num_frames];
    memcpy(removed_frame->header, last_frame->header, LTE_PHY_RX_FRAME_SIZE);
    removed_frame->signal_strength = last_frame->signal_strength;
    memcpy(removed_frame->symbols, last_frame->symbols, MAX_NUM_SYMBOLS * SYMBOL_SIZE);

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to flush old or unused frames from the array
void flush_frames() {
    pthread_mutex_lock(&frame_array_mutex);

    // check if there are any old or unused frames to be flushed
    int num_flushed = 0;
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = &frame_array[i];
        if (frame->signal_strength <= FLUSH_THRESHOLD) {
            remove_frame(i);
            num_flushed++;
            i--; // decrement the loop index since we removed a frame
        }
    }

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to resize the array of frames
void resize_frame_array() {
    pthread_mutex_lock(&frame_array_mutex);

    // allocate a new array of twice the size as the current one
    LTE_PHY_RX_FRAME* new_frame_array = (LTE_PHY_RX_FRAME*) malloc(2 * MAX_NUM_FRAMES * sizeof(LTE_PHY_RX_FRAME));

    // copy the frames from the old array to the new one
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = &frame_array[i];
        memcpy(&new_frame_array[i], frame, sizeof(LTE_PHY_RX_FRAME));
    }

    // free the old array of frames
    free(frame_array);

    // update the pointers to the new array and number of frames
    frame_array = new_frame_array;
    num_frames *= 2;

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to export the array of frames in a JSON format
void export_frames(FILE* file) {
    pthread_mutex_lock(&frame_array_mutex);

    // export each frame as a JSON object
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = &frame_array[i];
        fprintf(file, "{\n");
        fprintf(file, "\t\"header\": \"%s\",\n", frame->header);
        fprintf(file, "\t\"signal_strength\": %d,\n", frame->signal_strength);
        fprintf(file, "\t\"symbols\": [\n");
        for (int j = 0; j < MAX_NUM_SYMBOLS; j++) {
            LTE_PHY_RX_SYMBOL* symbol = &frame->symbols[j];
            fprintf(file, "\t\t{\n");
            fprintf(file, "\t\t\t\"duration\": %d,\n", symbol->duration);
            fprintf(file, "\t\t\t\"tx_power\": %d,\n", symbol->tx_power);
            fprintf(file, "\t\t\t\"rx_power\": %d\n", symbol->rx_power);
            fprintf(file, "\t\t}\n");
        }
        fprintf(file, "\t]\n");
        fprintf(file, "}\n");
    }

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to import the array of frames from a JSON file
void import_frames(FILE* file) {
    pthread_mutex_lock(&frame_array_mutex);

    // parse each frame in the JSON file and add it to the array
    char line[256];
    while (fgets(line, sizeof(line), file)) {
        int header_size = strlen(line) - 1; // remove newline character
        char* header = malloc(header_size + 1);
        memcpy(header, line, header_size);
        header[header_size] = '\0';
        int signal_strength = atoi(line);
        struct LTE_PHY_RX_SYMBOL symbols[MAX_NUM_SYMBOLS];
        for (int i = 0; i < MAX_NUM_SYMBOLS; i++) {
            fgets(line, sizeof(line), file);
            char* symbol_data = strchr(line, '{');
            int num_symbols = sscanf(symbol_data, "{\"duration\": %d, \"tx_power\": %d, \"rx_power\": %d}", &symbols[i].duration, &symbols[i].tx_power, &symbols[i].rx_power);
        }
        add_frame(header, signal_strength, symbols);
    }

    pthread_mutex_unlock(&frame_array_mutex);
}

// function to print the array of frames in a human-readable format
void print_frames() {
    pthread_mutex_lock(&frame_array_mutex);

    // print each frame as a string
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = &frame_array[i];
        printf("Frame %d: %s\n", i + 1, frame->header);
        for (int j = 0; j < MAX_NUM_SYMBOLS; j++) {
            LTE_PHY_RX_SYMBOL* symbol = &frame->symbols[j];
            printf("\tSymbol %d: duration=%d, tx_power=%d, rx_power=%d\n", j + 1, symbol->duration, symbol->tx_power, symbol->rx_power);
        }
    }

    pthread_mutex_unlock(&frame_array_mutex);
}']

