// Define the structure to hold the list of NFIX_MESSAGE_T structures
typedef struct {
    NFIX_MESSAGE_T* messages; // Pointer to an array of NFIX_MESSAGE_T structures
    int num_messages; // Number of elements in the array
} DynamicList;

// Define the function that manages the dynamic list of NFIX_MESSAGE_T structures
void manageDynamicList(DynamicList* list) {
    // Lock the list to ensure thread safety
    pthread_mutex_lock(&list->mutex);

    // Handle concurrent access to the list by checking for race conditions
    if (list->num_messages > 0 && list->messages[0].MEASUREMENT_FLAG == 1) {
        // Update the MEASUREMENT_FLAG for the first element in the list
        list->messages[0].MEASUREMENT_FLAG = 2;
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list->mutex);
}

// Define the function that serializes the dynamic list of NFIX_MESSAGE_T structures to a binary format
void serializeDynamicList(DynamicList* list, char* buffer) {
    // Lock the list to ensure thread safety
    pthread_mutex_lock(&list->mutex);

    // Write the number of elements in the list to the buffer
    memcpy(buffer, &list->num_messages, sizeof(int));

    // Write each element in the list to the buffer
    for (int i = 0; i < list->num_messages; i++) {
        memcpy(buffer + sizeof(int), &list->messages[i], sizeof(NFIX_MESSAGE_T));
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list->mutex);
}

// Define the function that deserializes the dynamic list of NFIX_MESSAGE_T structures from a binary format
void deserializeDynamicList(char* buffer, DynamicList* list) {
    // Lock the list to ensure thread safety
    pthread_mutex_lock(&list->mutex);

    // Read the number of elements in the list from the buffer
    memcpy(&list->num_messages, buffer, sizeof(int));

    // Allocate memory for the list
    list->messages = (NFIX_MESSAGE_T*) malloc(list->num_messages * sizeof(NFIX_MESSAGE_T));

    // Read each element in the list from the buffer
    for (int i = 0; i < list->num_messages; i++) {
        memcpy(&list->messages[i], buffer + sizeof(int) + i * sizeof(NFIX_MESSAGE_T), sizeof(NFIX_MESSAGE_T));
    }

    // Unlock the list to allow other threads to access it
    pthread_mutex_unlock(&list->mutex);
