// Define a dynamic array to hold the data for each network event
static LTE_UESRVCC_DATA_PDU* uesrvc_data = NULL;

// Define a mutex to protect shared resources
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define a method to initialize and populate the dynamic array
int init_uesrvc_data(void) {
    // Allocate memory for the dynamic array
    uesrvc_data = (LTE_UESRVCC_DATA_PDU*)malloc(sizeof(LTE_UESRVCC_DATA_PDU));
    if (!uesrvc_data) {
        printf("Failed to allocate memory for uesrvc data\n");
        return -1;
    }

    // Initialize the dynamic array with default values
    memset(uesrvc_data, 0, sizeof(LTE_UESRVCC_DATA_PDU));

    return 0;
}

// Define a method to add new data to the dynamic array
int add_uesrvc_data(LTE_UESRVCC_INFO_TAG uesrvc_info, RRC_VERSION rrc_version, SRVCC_EVENT_TAG srvcc_event) {
    // Acquire a lock on the mutex to protect shared resources
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array has been initialized
    if (!uesrvc_data) {
        int result = init_uesrvc_data();
        if (result != 0) {
            printf("Failed to initialize uesrvc data\n");
            return -1;
        }
    }

    // Validate the incoming network event
    if (srvcc_event < SRVCC_EVENT_MIN || srvcc_event > SRVCC_EVENT_MAX) {
        printf("Invalid SRVCC event type: %d\n", srvcc_event);
        return -1;
    }

    // Allocate memory for the new data structure
    LTE_UESRVCC_DATA_PDU* new_data = (LTE_UESRVCC_DATA_PDU*)malloc(sizeof(LTE_UESRVCC_DATA_PDU));
    if (!new_data) {
        printf("Failed to allocate memory for new uesrvc data\n");
        return -1;
    }

    // Copy the incoming network event and RRC version into the new data structure
    memcpy(&(new_data->uesrvc_info), &uesrvc_info, sizeof(LTE_UESRVCC_INFO_TAG));
    memcpy(&(new_data->rrc_version), &rrc_version, sizeof(RRC_VERSION));
    new_data->srvcc_event = srvcc_event;

    // Add the new data structure to the end of the dynamic array
    uesrvc_data = (LTE_UESRVCC_DATA_PDU*)realloc(uesrvc_data, sizeof(LTE_UESRVCC_DATA_PDU) * (1 + uesrvc_size));
    if (!uesrvc_data) {
        printf("Failed to reallocate memory for uesrvc data\n");
        free(new_data);
        return -1;
    }
    uesrvc_data[uesrvc_size++] = new_data;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Define a method to remove data from the dynamic array
int remove_uesrvc_data(LTE_UESRVCC_INFO_TAG uesrvc_info, RRC_VERSION rrc_version, SRVCC_EVENT_TAG srvcc_event) {
    // Acquire a lock on the mutex to protect shared resources
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array has been initialized
    if (!uesrvc_data) {
        printf("Failed to remove uesrvc data: array not initialized\n");
        return -1;
    }

    // Find the index of the data structure corresponding to the incoming network event
    int i = 0;
    while (i < uesrvc_size && !(uesrvc_data[i].uesrvc_info == uesrvc_info && uesrvc_data[i].rrc_version == rrc_version && uesrvc_data[i].srvcc_event == srvcc_event)) {
        i++;
    }

    // If the data structure was found, remove it from the dynamic array and free its memory
    if (i < uesrvc_size) {
        free(uesrvc_data[i]);
        uesrvc_data = (LTE_UESRVCC_DATA_PDU*)realloc(uesrvc_data, sizeof(LTE_UESRVCC_DATA_PDU) * (uesrvc_size - 1));
        if (!uesrvc_data) {
            printf("Failed to reallocate memory for uesrvc data\n");
            return -1;
        }
        uesrvc_size--;
    } else {
        // If the data structure was not found, log an error and return failure
        printf("Failed to remove uesrvc data: data not found\n");
        return -1;
    }

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
}

// Define a method to clean up the dynamic array when it is no longer needed
int cleanup_uesrvc_data(void) {
    // Acquire a lock on the mutex to protect shared resources
    pthread_mutex_lock(&mutex);

    // Check if the dynamic array has been initialized
    if (!uesrvc_data) {
        printf("Failed to clean up uesrvc data: array not initialized\n");
        return -1;
    }

    // Free the memory allocated for the dynamic array
    free(uesrvc_data);
    uesrvc_data = NULL;

    // Release the lock on the mutex
    pthread_mutex_unlock(&mutex);

    return 0;
