#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <stdbool.h>
#include <pthread.h>
#include <limits.h>
#include <time.h>

// Define the record structure
typedef struct {
    int value;
    long offset;
} Record;

// Define the hash table data structure
typedef struct {
    unsigned int capacity;
    unsigned int size;
    Record** buckets;
} HashTable;

// Define the doubly linked list data structure
typedef struct {
    Record* head;
    Record* tail;
} LinkedList;

// Define the memory pool data structure
typedef struct {
    unsigned int size;
    void** mem_blocks;
} MemoryPool;

// Global variables
static const unsigned int MAX_RECORD_STORAGE_CAPACITY = 1000000; // maximum number of records to store
static const unsigned int MIN_HASH_TABLE_CAPACITY = 16; // minimum capacity of the hash table
static const unsigned int MEMORY_POOL_SIZE = 256 * 1024 * 1024; // size of the memory pool in bytes
static const unsigned int MAX_MEMORY_OVERHEAD = 5000; // maximum memory overhead in percent
static const unsigned int HASH_TABLE_RESIZE_FACTOR = 2; // resize factor for the hash table
static const unsigned int LINKED_LIST_RESIZE_FACTOR = 1.5; // resize factor for the linked list

// Function to generate a random integer within a specified range
int get_random_int(int min, int max) {
    return min + (rand() % (max - min + 1));
}

// Function to initialize a record with a random value and offset
void init_record(Record* rec) {
    rec->value = get_random_int(min, max);
    rec->offset = (long)rec->value * rand();
}

// Function to create a new hash table
HashTable* create_hash_table() {
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        return NULL;
    }
    table->capacity = MIN_HASH_TABLE_CAPACITY;
    table->size = 0;
    table->buckets = malloc(table->capacity * sizeof(Record*));
    if (!table->buckets) {
        free(table);
        return NULL;
    }
    for (unsigned int i = 0; i < table->capacity; ++i) {
        table->buckets[i] = NULL;
    }
    return table;
}

// Function to resize a hash table
void resize_hash_table(HashTable* table, unsigned int new_capacity) {
    // Check if the new capacity is within bounds
    if (new_capacity < MIN_HASH_TABLE_CAPACITY || new_capacity > MAX_RECORD_STORAGE_CAPACITY) {
        return;
    }
    // Create a new array of buckets with the new capacity
    Record** new_buckets = malloc(new_capacity * sizeof(Record*));
    if (!new_buckets) {
        return;
    }
    // Copy the old buckets to the new array
    for (unsigned int i = 0; i < table->capacity; ++i) {
        Record* bucket = table->buckets[i];
        while (bucket != NULL) {
            Record* next = bucket->next;
            unsigned int index = hash_function(bucket) % new_capacity;
            bucket->next = new_buckets[index];
            new_buckets[index] = bucket;
            bucket = next;
        }
    }
    // Free the old buckets
    free(table->buckets);
    table->buckets = new_buckets;
    table->capacity = new_capacity;
}

// Function to hash a record
unsigned int hash_function(const Record* rec) {
    return (rec->value * 31 + rec->offset) % table->capacity;
}

// Function to insert a record into the hash table
bool insert_record(HashTable* table, const Record* rec) {
    // Check if the hash table is full
    if (table->size >= MAX_RECORD_STORAGE_CAPACITY) {
        return false;
    }
    // Hash the record and find the bucket index
    unsigned int index = hash_function(rec) % table->capacity;
    // Find the end of the linked list in the bucket
    Record* tail = table->buckets[index];
    while (tail != NULL && tail->next != NULL) {
        tail = tail->next;
    }
    // Create a new record and insert it into the linked list
    Record* new_rec = malloc(sizeof(Record));
    if (!new_rec) {
        return false;
    }
    init_record(new_rec);
    new_rec->next = NULL;
    tail->next = new_rec;
    table->size++;
    // Resize the hash table if necessary
    if (table->size >= HASH_TABLE_RESIZE_FACTOR * table->capacity) {
        resize_hash_table(table, table->capacity * HASH_TABLE_RESIZE_FACTOR);
    }
    return true;
}

// Function to delete a record from the hash table
bool delete_record(HashTable* table, const Record* rec) {
    // Hash the record and find the bucket index
    unsigned int index = hash_function(rec) % table->capacity;
    // Find the corresponding linked list in the bucket
    Record* prev = NULL;
    Record* curr = table->buckets[index];
    while (curr != NULL && curr != rec) {
        prev = curr;
        curr = curr->next;
    }
    // If the record is not found, return false
    if (curr == NULL) {
        return false;
    }
    // Remove the record from the linked list
    if (prev == NULL) {
        table->buckets[index] = curr->next;
    } else {
        prev->next = curr->next;
    }
    free(curr);
    table->size--;
    return true;
}

// Function to search for a record in the hash table
Record* search_record(HashTable* table, const Record* rec) {
    // Hash the record and find the bucket index
    unsigned int index = hash_function(rec) % table->capacity;
    // Find the corresponding linked list in the bucket
    Record* curr = table->buckets[index];
    while (curr != NULL && curr != rec) {
        curr = curr->next;
    }
    return curr;
}

// Function to create a new memory pool
MemoryPool* create_memory_pool(size_t size) {
    // Check if the memory pool size is within bounds
    if (size > MAX_MEMORY_POOL_SIZE || size == 0) {
        return NULL;
    }
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) {
        return NULL;
    }
    pool->size = size;
    pool->used = 0;
    pool->memory = calloc(pool->size, sizeof(char));
    if (!pool->memory) {
        free(pool);
        return NULL;
    }
    return pool;
}

// Function to destroy a memory pool
void destroy_memory_pool(MemoryPool* pool) {
    // Check if the memory pool is valid
    if (pool == NULL) {
        return;
    }
    free(pool->memory);
    free(pool);
}

// Function to allocate memory from a memory pool
void* allocate_memory(MemoryPool* pool, size_t size) {
    // Check if the memory pool is valid and the allocation size is within bounds
    if (pool == NULL || size > pool->size - pool->used) {
        return NULL;
    }
    void* memory = &pool->memory[pool->used];
    pool->used += size;
    return memory;
}

// Function to deallocate memory from a memory pool
void deallocate_memory(MemoryPool* pool, void* memory) {
    // Check if the memory pool is valid and the memory address is within bounds
    if (pool == NULL || memory < &pool->memory[0] || memory > &pool->memory[pool->size]) {
        return;
    }
    size_t offset = (char*)memory - &pool->memory[0];
    pool->used -= offset;
}

// Function to create a new thread
Thread* create_thread(void (*start_routine)(void *), void* arg) {
    // Check if the start routine is valid
    if (start_routine == NULL) {
        return NULL;
    }
    Thread* thread = malloc(sizeof(Thread));
    if (!thread) {
        return NULL;
    }
    thread->start_routine = start_routine;
    thread->arg = arg;
    thread->status = NEW;
    return thread;
}

// Function to destroy a thread
void destroy_thread(Thread* thread) {
    // Check if the thread is valid
    if (thread == NULL) {
        return;
    }
    free(thread);
}

// Function to start a thread
void start_thread(Thread* thread) {
    // Check if the thread is valid
    if (thread == NULL) {
        return;
    }
    // Set the status of the thread to running
    thread->status = RUNNING;
    // Create a new memory pool for the thread
    MemoryPool* pool = create_memory_pool(THREAD_MEMORY_POOL_SIZE);
    if (!pool) {
        return;
    }
    thread->memory_pool = pool;
    // Allocate memory from the memory pool to store the arguments of the start routine
    void* args = allocate_memory(pool, sizeof(void*));
    if (args == NULL) {
        destroy_memory_pool(pool);
        return;
    }
    *((void**)args) = thread->arg;
    // Start the thread by calling the start routine with the arguments from the memory pool
    void (*start)(void*) = thread->start_routine;
    start(args);
}

// Function to wait for a thread to finish execution
bool wait_thread(Thread* thread) {
    // Check if the thread is valid
    if (thread == NULL || thread->status != EXITED) {
        return false;
    }
    // Wait for the thread to finish by joining it
    void (*start)(void*) = thread->start_routine;
    start(thread->arg);
    // Destroy the memory pool of the thread and free the allocated memory
    destroy_memory_pool(thread->memory_pool);
    free(thread);
    return true;
}
