NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int num_elements) {
    // Allocate memory for the array of structures
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
