    assert(n <= 10000);
    assert(rnti >= 0 && rnti <= 65535);

    // Allocate an array of NFAPI_CRC_INDICATION_PDU_T structures
    nfapi_crc_indication_pdu_t* crc_indication_array = (nfapi_crc_indication_pdu_t*)malloc(sizeof(nfapi_crc_indication_pdu_t) * n);
    if (!crc_indication_array) {
        // Handle memory allocation failure
        return NULL;
    }

