["```
#include <stdlib.h>
#include <time.h>

struct UEContext {
    long imsi;
    int rnti;
    int pdu_session_id;
};

void populateUEContextArray(struct UEContext** ueContexts, size_t maxSize) {
    // Generate unique IMSIs for each UE context
    srand(time(NULL));
    for (size_t i = 0; i < maxSize; ++i) {
        struct UEContext* ctx = malloc(sizeof(struct UEContext));
        ctx->imsi = rand() % 1000000 + 10000000; // Generate unique IMSI for each UE context
        ctx->rnti = rand() % 50000 + 1; // Generate random RNTI
        ctx->pdu_session_id = rand() % 50 + 1; // Generate random PDU session ID
        ueContexts[i] = ctx;
    }
}

void handleExternalData(struct UEContext** ueContexts, size_t maxSize) {
    // Handle data from external source in a separate thread to avoid blocking other operations
    while (1) {
        // Wait for data from external source
        struct ExternalData* data = receiveExternalData();
        if (!data) {
            continue; // Retry if no data received
        }

        // Update UE contexts in memory with new data
        updateUEContexts(ueContexts, maxSize, data);
    }
}

void updateUEContexts(struct UEContext** ueContexts, size_t maxSize, struct ExternalData* data) {
    // Update existing UE contexts with new data from external source
    for (size_t i = 0; i < maxSize; ++i) {
        if (ueContexts[i]->imsi == data->imsi) {
            ueContexts[i]->rnti = data->rnti;
            ueContexts[i]->pdu_session_id = data->pdu_session_id;
        }
    }
}

