    pthread_t eviction_thread;
    pthread_create(&eviction_thread, NULL, cache_eviction_thread, NULL);

    // Iterate over the provided hostname and populate the cache with NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < num_entries; i++) {
