        pthread_mutex_lock(&cache_mutex);

        // Add the new structure to the end of the cache if it is not full
        if (cache_tail == NULL) {
            cache_head = entry;
            cache_tail = entry;
        } else {
            cache_tail->next = entry;
            cache_tail = entry;
        }

        // Unlock the mutex and continue the loop
        pthread_mutex_unlock(&cache_mutex);
    }

    // Wait for the cache eviction thread to complete before returning
    pthread_join(eviction_thread, NULL);

