// Add a new log entry to the collection
void add_log_entry(struct LOG_ENTRY *entry) {
    // Acquire mutex lock for thread safety
    pthread_mutex_lock(&log_collection->mutex);

    // Check if the log collection has reached its capacity
    if (log_collection->count == log_collection->capacity) {
        // Resize the log collection to accommodate more entries
        size_t new_capacity = log_collection->capacity * 2;
        struct LOG_ENTRY *new_entries = realloc(log_collection->entries, new_capacity);
        if (new_entries == NULL) {
            // Reallocation failed, handle error
        }
        log_collection->entries = new_entries;
        log_collection->capacity = new_capacity;
    }

    // Add the new log entry to the collection
    memcpy(&log_collection->entries[log_collection->count++], entry, sizeof(struct LOG_ENTRY));

    // Release mutex lock for thread safety
    pthread_mutex_unlock(&log_collection->mutex);
}

// Create and populate a list of custom event records
void create_event_records(size_t count, struct CUSTOM_EVENT_RECORD **events) {
    // Allocate memory for the list of events
    *events = malloc(count * sizeof(struct CUSTOM_EVENT_RECORD));

    // Generate a unique event ID and source identifier for each event record
    int id = 0;
    char source[16];
    for (size_t i = 0; i < count; ++i) {
        sprintf(source, "Source-%d", id++);
        (*events)[i].event_id = id;
        strcpy((*events)[i].source, source);
        // Populate the payload with custom data
        (*events)[i].payload.value1 = i;
        (*events)[i].payload.value2 = i * 10;
        (*events)[i].payload.value3 = id % 10;
    }
}

// Check if two event records share the same event ID, skip duplicates and log an appropriate message
void check_duplicates(struct CUSTOM_EVENT_RECORD *events, size_t count) {
    // Acquire mutex lock for thread safety
    pthread_mutex_lock(&log_collection->mutex);

    // Iterate over the event records and check for duplicates
    for (size_t i = 0; i < count; ++i) {
        struct CUSTOM_EVENT_RECORD *event1 = &events[i];
        for (size_t j = i + 1; j < count; ++j) {
            struct CUSTOM_EVENT_RECORD *event2 = &events[j];
            if (event1->event_id == event2->event_id) {
                // Log an appropriate message for duplicate events
                printf("Duplicate event ID %d found: %s\n", event1->event_id, event1->source);
                break;
            }
        }
    }

    // Release mutex lock for thread safety
    pthread_mutex_unlock(&log_collection->mutex);
}

// Main function to manage the dynamic collection of log entries and custom event records
void main(void) {
    // Initialize the log collection with a specified number of log entries
    init_log_collection(10000);

    // Create and populate a list of custom event records
    size_t count = 1000;
    struct CUSTOM_EVENT_RECORD *events = NULL;
    create_event_records(count, &events);

    // Add the custom event records to the log collection
    for (size_t i = 0; i < count; ++i) {
        add_log_entry(&events[i]);
    }

    // Check if two event records share the same event ID, skip duplicates and log an appropriate message
    check_duplicates(events, count);
}
