    new_structure->crc_indication_rel8_tag = crc_indication_rel8_tag;

    // add the new structure to the array and update its size
    pthread_mutex_lock(&array->lock);
    array->data[array->size++] = new_structure;
    pthread_mutex_unlock(&array->lock);

