    size_t payload_size; // Size of the payload in bytes
    time_t transmission_time; // Time at which the data was transmitted
    unsigned short error_count; // Number of errors encountered during transmission
} TCP_SOCKET_CONNECTION;

// Define the function for initializing and managing a dynamic array of TCP socket connections
void initialize_tcp_socket_connections(TCP_SOCKET_CONNECTION** connections, size_t max_connections) {
    // Allocate memory for the dynamic array of TCP socket connections
    *connections = (TCP_SOCKET_CONNECTION*)malloc(max_connections * sizeof(TCP_SOCKET_CONNECTION));

    // Initialize all elements in the array to NULL
    memset(*connections, 0, max_connections * sizeof(TCP_SOCKET_CONNECTION));
}

// Define the function for updating a TCP socket connection's throughput metrics based on recent transfer data
void update_tcp_socket_connection_throughput(TCP_SOCKET_CONNECTION* connection, size_t payload_size) {
    // Update the payload size of the current connection
    connection->payload_size += payload_size;

    // Calculate the time elapsed since the last update
    double time_elapsed = (double)(clock() - connection->transmission_time) / CLOCKS_PER_SEC;

    // Update the throughput metrics based on the recent transfer data
    connection->throughput = (float)connection->payload_size / time_elapsed;
}

