TCP_SOCKET_CONNECTION* retrieve_tcp_socket_connection(TCP_SOCKET_CONNECTION** connections, size_t max_connections, float threshold) {
    // Initialize the index to search from
    int current_index = 0;

    // Loop through all elements in the array until a connection with a sufficient throughput is found or the end of the array is reached
    while (current_index < max_connections && connections[current_index].throughput < threshold) {
        current_index++;
    }

    // Return the retrieved connection if one was found, otherwise return NULL
    return current_index < max_connections ? &(connections[current_index]) : NULL;
}

// Define the function for establishing a new TCP socket connection and adding it to the dynamic array of connections
bool establish_tcp_socket_connection(TCP_SOCKET_CONNECTION** connections, size_t* max_connections, int socket) {
    // Check if there is room in the array for a new connection
    if (*max_connections >= connections->size) {
        return false;
    }

    // Allocate memory for the new TCP socket connection
    TCP_SOCKET_CONNECTION* new_connection = (TCP_SOCKET_CONNECTION*)malloc(sizeof(TCP_SOCKET_CONNECTION));

    // Initialize the new connection with the given socket file descriptor
    new_connection->socket = socket;
    new_connection->payload_size = 0;
    new_connection->transmission_time = clock();
    new_connection->error_count = 0;
    new_connection->timestamp = 0;

    // Add the new connection to the array of connections
    connections[*max_connections] = new_connection;

    // Increment the maximum number of connections
    *max_connections += 1;

    return true;
}

// Define the function for updating an existing TCP socket connection's metadata
bool update_tcp_socket_connection(TCP_SOCKET_CONNECTION** connections, size_t max_connections, int socket) {
    // Loop through all elements in the array until a matching socket file descriptor is found or the end of the array is reached
    for (size_t i = 0; i < max_connections; i++) {
        if (connections[i].socket == socket) {
            // Update the connection's metadata with the given data
            connections[i].payload_size += payload_size;
            connections[i].transmission_time = clock();
            connections[i].error_count += error_count;
            connections[i].timestamp = timestamp;

            return true;
        }
    }

    // Return false if no matching socket file descriptor was found
    return false;
}

// Define the function for retrieving a TCP socket connection based on its socket file descriptor
TCP_SOCKET_CONNECTION* retrieve_tcp_socket_connection(TCP_SOCKET_CONNECTION** connections, size_t max_connections, int socket) {
    // Loop through all elements in the array until a matching socket file descriptor is found or the end of the array is reached
    for (size_t i = 0; i < max_connections; i++) {
        if (connections[i].socket == socket) {
            return &(connections[i]);
        }
    }

    // Return NULL if no matching socket file descriptor was found
    return NULL;
}

// Define the function for removing a TCP socket connection from the dynamic array of connections
void remove_tcp_socket_connection(TCP_SOCKET_CONNECTION** connections, size_t* max_connections, int socket) {
    // Loop through all elements in the array until a matching socket file descriptor is found or the end of the array is reached
    for (size_t i = 0; i < *max_connections; i++) {
        if (connections[i].socket == socket) {
            // Free the memory allocated to the connection
            free(connections[i]);

            // Shift all elements after the removed connection to fill the gap
            for (size_t j = i + 1; j < *max_connections; j++) {
                connections[j - 1] = connections[j];
            }

            // Decrement the maximum number of connections
            (*max_connections) -= 1;

            return;
        }
    }
}
