#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>
#include <errno.h>
#include <time.h>

// Define a structure to represent an item
typedef struct {
    char *name;
    int quantity;
    float price;
} item_t;

// Define a linked list node to store items
typedef struct item_node {
    item_t *item;
    struct item_node *next;
} item_node_t;

// Define a hash table to store items and their indices
typedef struct {
    item_node_t **buckets;
    int num_buckets;
    int num_items;
} item_table_t;

// Initialize the item table with an initial size of 1024 buckets
void init_item_table(item_table_t *table) {
    table->num_buckets = 1024;
    table->buckets = (item_node_t **)malloc(sizeof(item_node_t *) * table->num_buckets);
    for (int i = 0; i < table->num_buckets; i++) {
        table->buckets[i] = NULL;
    }
}

// Insert an item into the item table
void insert_item(item_table_t *table, const char *name, int quantity, float price) {
    // Check if the item already exists in the table
    item_node_t **node = &table->buckets[hash(name)];
    while (*node != NULL && strcmp((*node)->item->name, name) != 0) {
        node = &(*node)->next;
    }

    // If the item does not exist, create a new node and insert it into the table
    if (*node == NULL) {
        *node = (item_node_t *)malloc(sizeof(item_node_t));
        (*node)->item = (item_t *)malloc(sizeof(item_t));
        strcpy((*node)->item->name, name);
        (*node)->item->quantity = quantity;
        (*node)->item->price = price;
        (*node)->next = NULL;
        table->num_items++;
    }
}

// Find an item in the item table by its name
item_t *find_item(item_table_t *table, const char *name) {
    // Hash the name to find the corresponding bucket
    int index = hash(name);
    item_node_t **node = &table->buckets[index];

    // Traverse the linked list in the bucket to find the item
    while (*node != NULL && strcmp((*node)->item->name, name) != 0) {
        node = &(*node)->next;
    }

    // Return the item if found, otherwise return NULL
    return *node ? (*node)->item : NULL;
}

// Update an item in the item table by its name
void update_item(item_table_t *table, const char *name, int quantity, float price) {
    // Find the item in the table
    item_t *item = find_item(table, name);

    // If the item is found, update its fields and return
    if (item != NULL) {
        item->quantity = quantity;
        item->price = price;
        return;
    }

    // Otherwise, insert a new item into the table
    insert_item(table, name, quantity, price);
}

// Delete an item from the item table by its name
void delete_item(item_table_t *table, const char *name) {
    // Find the item in the table
    item_node_t **node = &table->buckets[hash(name)];
    while (*node != NULL && strcmp((*node)->item->name, name) != 0) {
        node = &(*node)->next;
    }

    // If the item is found, delete it from the table and return
    if (*node != NULL) {
        item_t *item = (*node)->item;
        free(item);
        free(*node);
        table->num_items--;
        return;
    }
}

// Serialize the item table to a binary file
void serialize_items(item_table_t *table, const char *filename) {
    // Open the file for writing
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", filename);
        return;
    }

    // Write the number of items in the table to the file
    int num_items = table->num_items;
    fwrite(&num_items, sizeof(int), 1, file);

    // Iterate over each bucket and write its contents to the file
    for (int i = 0; i < table->num_buckets; i++) {
        item_node_t *node = table->buckets[i];
        while (node != NULL) {
            fwrite(node->item, sizeof(item_t), 1, file);
            node = node->next;
        }
    }

    // Close the file
    fclose(file);
}

// Deserialize the item table from a binary file
void deserialize_items(item_table_t *table, const char *filename) {
    // Open the file for reading
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: failed to open file %s\n", filename);
        return;
    }

    // Read the number of items in the table from the file
    int num_items;
    fread(&num_items, sizeof(int), 1, file);

    // Initialize the item table with the read number of items
    init_item_table(table);
    for (int i = 0; i < num_items; i++) {
        item_t *item = (item_t *)malloc(sizeof(item_t));
        fread(item, sizeof(item_t), 1, file);
        insert_item(table, item->name, item->quantity, item->price);
    }

    // Close the file
    fclose(file);
}

// Apply a discount to the price of all items in the table and compute the total cost
float calculate_total(item_table_t *table) {
    float total = 0;
    for (int i = 0; i < table->num_buckets; i++) {
        item_node_t *node = table->buckets[i];
        while (node != NULL) {
            total += node->item->quantity * node->item->price;
            node = node->next;
        }
    }
    return total;
}

int main() {
    // Initialize the item table
    item_table_t table;
    init_item_table(&table);

    // Insert some items into the table
    insert_item(&table, "Apple", 5, 10.99);
    insert_item(&table, "Orange", 3, 2.99);
    insert_item(&table, "Banana", 4, 0.99);

    // Find an item in the table by its name
    printf("Find item: %s\n", find_item(&table, "Apple")->name);

    // Update an item in the table by its name
    update_item(&table, "Banana", 2, 0.50);

    // Delete an item from the table by its name
    delete_item(&table, "Orange");

    // Serialize the item table to a binary file
    serialize_items(&table, "items.bin");

    // Deserialize the item table from a binary file
    deserialize_items(&table, "items.bin");

    // Calculate the total cost of all items in the table
    printf("Total: %.2f\n", calculate_total(&table));

    return 0;
}
