    json_object* cells = json_object_get_array(root);

    // Deserialize each cell in the array
    for (int i = 0; i < json_object_array_length(cells); i++) {
        json_object* cell = json_object_array_get_idx(cells, i);
        int CELL_ID = json_object_get_int(json_object_object_get(cell, "CELL_ID"));
        int PCI = json_object_get_int(json_object_object_get(cell, "PCI"));
        unsigned long TIME_INSTANCE = json_object_get_ulong(json_object_object_get(cell, "TIME_INSTANCE"));
