char* renderFooterScripts(LTE_PHY_RX_FRAME **frames, int num_frames) {
    // declare variables
    int i, j;
    char *html = NULL;
    SCRIPT_TAG *script_tags = NULL;
    sem_t *semaphore = NULL;

    // allocate memory for the HTML string and script tag array
    html = (char*)malloc(sizeof(char) * 1024);
    script_tags = (SCRIPT_TAG*)malloc(sizeof(SCRIPT_TAG) * num_frames);

    // initialize the semaphore to control access to the HTML string and script tag array
    semaphore = sem_open("semaphore", O_CREAT, 0644, num_frames);

    // create threads for each frame
    pthread_t *threads = (pthread_t*)malloc(sizeof(pthread_t) * num_frames);
    for (i = 0; i < num_frames; ++i) {
        pthread_create(&threads[i], NULL, processFrame, &frames[i]);
    }

    // wait for all threads to finish
    for (i = 0; i < num_frames; ++i) {
        pthread_join(threads[i], NULL);
    }

    // free the memory allocated for the threads and semaphore
    free(threads);
    sem_close(semaphore);

    // generate the HTML string by concatenating all script tags
    html = (char*)malloc(sizeof(char) * 1024);
    for (i = 0; i < num_frames; ++i) {
        strcat(html, script_tags[i].tag);
    }

    // free the memory allocated for the script tag array
    free(script_tags);

    return html;
}

// define the function to process each frame concurrently
void* processFrame(void *frame) {
    // declare variables
    int i, j;
    char *html = NULL;
    SCRIPT_TAG *script_tag = NULL;

    // allocate memory for the HTML string and script tag
    html = (char*)malloc(sizeof(char) * 1024);
    script_tag = (SCRIPT_TAG*)malloc(sizeof(SCRIPT_TAG));

    // initialize the semaphore to control access to the HTML string and script tag
    sem_t *semaphore = sem_open("semaphore", O_CREAT, 0644, 1);

    // filter frames based on minimum signal strength threshold
    if (((LTE_PHY_RX_FRAME*)frame)->signal_strength >= MIN_SIGNAL_STRENGTH) {
        // generate the script tag for the filtered frame
        script_tag->tag = "<script src='path/to/script.js'></script>";
        script_tag->src = "path/to/script.js";
        sem_wait(semaphore);
        strcat(html, script_tag->tag);
        sem_post(semaphore);
    }

    // free the memory allocated for the HTML string and script tag
    free(html);
    free(script_tag);

    return NULL;
}
