#include <stdlib.h>
#include <string.h>

// Macro for defining a maximum number of downlink grants per context
#define MAX_DOWNLINK_GRANTS 10

// Struct for storing information about each MAC entity context
typedef struct {
    int num_grants; // Number of downlink grants in the context
    int *grants; // Pointer to an array of integers representing the downlink grant requests
} mac_context_t;

// Function for allocating memory for a specified number of MAC entity contexts
mac_context_t *allocate_contexts(int num_contexts) {
    // Allocate memory for the array of MAC entity contexts
    mac_context_t *contexts = malloc(sizeof(mac_context_t) * num_contexts);
    if (!contexts) {
        return NULL; // Memory allocation failed, return NULL
    }

    // Populate each context with a predefined number of downlink grants
    for (int i = 0; i < num_contexts; i++) {
        // Allocate memory for the array of downlink grant requests
        int *grants = malloc(sizeof(int) * MAX_DOWNLINK_GRANTS);
        if (!grants) {
            free(contexts); // Memory allocation failed, release all allocated resources
            return NULL;
        }

        // Populate the array of downlink grant requests with predefined values
        for (int j = 0; j < MAX_DOWNLINK_GRANTS; j++) {
            grants[j] = 1 + (i * MAX_DOWNLINK_GRANTS) + j; // Generate a unique value for each grant request
        }

        contexts[i].num_grants = MAX_DOWNLINK_GRANTS; // Set the number of downlink grants in the context
        contexts[i].grants = grants; // Set the pointer to the array of downlink grant requests
    }

    return contexts; // Return the allocated and populated array of MAC entity contexts
}

// Function for releasing all allocated resources when no longer needed
void release_contexts(mac_context_t *contexts, int num_contexts) {
    if (!contexts) {
        return; // No resources to release, return immediately
    }

    for (int i = 0; i < num_contexts; i++) {
        free(contexts[i].grants); // Release the memory allocated for the array of downlink grant requests
    }
    free(contexts); // Release the memory allocated for the array of MAC entity contexts
}
