// Define a function to release the memory allocated by initializeNfaliteApi()
void releaseNfaliteApi(NFAPI_L1_API_STRUCT* instances, int numInstances) {
  // Check for null pointers and memory allocation failure
  if (instances == NULL || numInstances < 0) {
    return;
  }

  // Free the L1_API_STATS structures for each instance
  for (int i = 0; i < numInstances; i++) {
