typedef struct record {
    int id;
    int value;
    long* data;
} Record;

Record** initialize_records(int max_keys, int min_value, int max_value) {
    // Allocate memory for the unique identifier array
    int* ids = malloc(max_keys * sizeof(int));
    if (ids == NULL) {
        return NULL;
    }

    // Allocate memory for the random integer array
    int* values = malloc(max_keys * sizeof(int));
    if (values == NULL) {
        free(ids);
        return NULL;
    }

    // Allocate memory for the record structures
    Record** records = malloc(max_keys * sizeof(Record*));
    if (records == NULL) {
        free(ids);
        free(values);
        return NULL;
    }

    // Populate the unique identifier array with consecutive integers starting from 0 up to max_keys - 1
    for (int i = 0; i < max_keys; i++) {
        ids[i] = i;
    }

    // Initialize the random integer array with values randomly generated within the specified min_value and max_value range
    srand(time(NULL));
    for (int i = 0; i < max_keys; i++) {
        int value = rand() % (max_value - min_value + 1) + min_value;
        values[i] = value;
    }

    // For each record, allocate memory for a 'long' value and initialize it to zero
    for (int i = 0; i < max_keys; i++) {
        records[i] = malloc(sizeof(Record));
        if (records[i] == NULL) {
            free(ids);
            free(values);
            free(records);
            return NULL;
        }
        records[i]->id = ids[i];
        records[i]->value = values[i];
        records[i]->data = malloc(sizeof(long));
        if (records[i]->data == NULL) {
            free(ids);
            free(values);
            free(records);
            return NULL;
        }
        *(records[i]->data) = 0;
    }

    // Populate the index map to efficiently associate each unique identifier with its corresponding record index
    int* index_map = malloc(max_keys * sizeof(int));
    if (index_map == NULL) {
        free(ids);
        free(values);
        free(records);
        return NULL;
    }
    for (int i = 0; i < max_keys; i++) {
        index_map[i] = -1;
    }
    for (int i = 0; i < max_keys; i++) {
        int id = ids[i];
        if (index_map[id] == -1) {
            index_map[id] = i;
        } else {
            printf("Error: duplicate unique identifier %d\n", id);
            free(ids);
            free(values);
            free(records);
            return NULL;
        }
    }

    // Optimize for both memory usage and access speed, considering potential growth beyond max_keys
    int* new_index_map = realloc(index_map, max_keys * 2 * sizeof(int));
    if (new_index_map == NULL) {
        free(ids);
        free(values);
        free(records);
        return NULL;
    }
    index_map = new_index_map;
    for (int i = max_keys; i < max_keys * 2; i++) {
        index_map[i] = -1;
    }

    // Return a pointer to the first element of the unique identifier array, or NULL if any memory allocation fails
    return records;
}
