NFAPI_CRC_INDICATION_PDU_T* initArray(int size) {
    // Linked list approach:
    NFAPI_CRC_INDICATION_PDU_T** head = NULL;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (int i = 0; i < size; i++) {
        NFAPI_CRC_INDICATION_PDU_T* node = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!node) {
            // Handle memory allocation failure
        }
        node->RX_UE_INFORMATION_TAG = i;
        node->RNTI = 0x1234 + i;
        node->CRCFLAG = (i % 3 == 0 ? 0 : 0x00);
        head = node;
    }

    // Contiguous memory allocation approach:
    NFAPI_CRC_INDICATION_PDU_T* array = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array) {
        // Handle memory allocation failure
    }
    for (int i = 0; i < size; i++) {
        array[i].RX_UE_INFORMATION_TAG = i;
        array[i].RNTI = 0x1234 + i;
        array[i].CRCFLAG = (i % 3 == 0 ? 0 : 0x00);
    }

    return head; // Linked list approach
    return array; // Contiguous memory allocation approach
