// Function to allocate a new structure from the pool
NFAPI_CRC_INDICATION_PDU_T* allocate_structure(uint16_t RX_UE_INFORMATION_TAG, uint16_t RNTI) {
    // Lock the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_lock);

    // Iterate over the pool and find a free structure
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        if (pool[i] == NULL) {
            // Allocate a new structure from the heap
            NFAPI_CRC_INDICATION_PDU_T* new_struct = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (new_struct != NULL) {
                pool[i] = new_struct;
                break;
            } else {
                // Log the failure to allocate memory
                printf("Failed to allocate memory for a new CRC indication structure\n");
            }
        }
    }

    // Unlock the mutex and return the allocated structure
    pthread_mutex_unlock(&pool_lock);
    if (pool[i] != NULL) {
        pool[i]->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
        pool[i]->RNTI = RNTI;
        pool[i]->CRCFLAG = rand() % 256; // Set a random value for the CRCFLAG
    }
    return pool[i];
}

// Function to free a structure from the pool
void free_structure(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    // Lock the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_lock);

    // Iterate over the pool and find the structure to be freed
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        if (pool[i] == struct_ptr) {
            free(struct_ptr);
            pool[i] = NULL;
            break;
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&pool_lock);
}

