bool is_structure_valid(NFAPI_CRC_INDICATION_PDU_T* struct_ptr) {
    // Lock the mutex to prevent concurrent access to the pool
    pthread_mutex_lock(&pool_lock);

    // Iterate over the pool and find the structure to be checked
    for (int i = 0; i < MAX_POOL_SIZE; i++) {
        if (pool[i] == struct_ptr) {
            break;
        }
    }

    // Unlock the mutex and return true if the structure is still valid
    pthread_mutex_unlock(&pool_lock);
    return pool[i] != NULL;
}

// Function to handle external data sources with varying latencies and network conditions
