    // Initialize the mutex and set the number of entries to 0
    pthread_mutex_init(&lock, NULL);
    num_entries = 0;
}

int add_crc_indication(NFAPI_CRC_INDICATION_PDU_T *pdu, void *payload) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lock);

    // Allocate memory for a new entry and copy the PDU and payload
    crc_indication_entry_t *new_entry = malloc(sizeof(crc_indication_entry_t));
    new_entry->pdu = pdu;
    new_entry->payload = payload;

    // Add the new entry to the list and increase the number of entries
    if (entries == NULL) {
        entries = malloc(sizeof(crc_indication_entry_t));
    } else {
        crc_indication_entry_t *tmp = realloc(entries, (num_entries + 1) * sizeof(crc_indication_entry_t));
        if (tmp == NULL) {
            pthread_mutex_unlock(&lock);
            return -1; // Memory allocation failed
        } else {
            entries = tmp;
        }
