    for (i = 0; i < num_entries; i++) {
        if (entries[i]->pdu == pdu) {
            break;
        }
    }
    if (i == num_entries) {
        // No entry found with the matching PDU
        pthread_mutex_unlock(&lock);
        return -1;
    }
    crc_indication_entry_t *tmp = realloc(entries, (num_entries - 1) * sizeof(crc_indication_entry_t));
    if (tmp == NULL) {
        pthread_mutex_unlock(&lock);
        return -1; // Memory allocation failed
    } else {
        entries = tmp;
    }
    num_entries--;

    // Free the memory for the removed entry and unlock the mutex
    free(entries[i]);
    pthread_mutex_unlock(&lock);
    return 0;
}

