// Initialize an empty LTE PHY frame list
LTE_PHY_FRAME_LIST* init_lte_phy_frame_list() {
    LTE_PHY_FRAME_LIST *list = malloc(sizeof(LTE_PHY_FRAME_LIST));
    if (list == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->frames = NULL;
    return list;
}

