    NFIX_MESSAGE_LIST *list = malloc(sizeof(NFIX_MESSAGE_LIST));
    if (list == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    list->count = 0;
    list->messages = NULL;
    return list;
}

// Add a new LTE PHY frame to the list
void add_lte_phy_frame(LTE_PHY_FRAME_LIST *list, LTE_PHY_RX_FRAME *frame) {
    // Acquire the mutex for synchronizing access to the list
    pthread_mutex_lock(&list_mutex);

    // Check if there is enough memory to add a new frame
    if (list->count == 0) {
        list->frames = malloc(sizeof(LTE_PHY_RX_FRAME));
        if (list->frames == NULL) {
            perror("malloc");
            exit(EXIT_FAILURE);
