        if (list->frames == NULL) {
            perror("realloc");
            exit(EXIT_FAILURE);
        }
    }

    // Add the new frame to the list
    list->frames[list->count] = *frame;
    list->count++;

    // Release the mutex for synchronizing access to the list
    pthread_mutex_unlock(&list_mutex);
}

