// Structure to store information about an NFAPI_RRC_MESSAGE_T
typedef struct nfapi_rrc_message {
    int pdu_tag;
    int ue_id;
    struct measurement *measurements;
} nfapi_rrc_message_t;

// Structure to store information about a measurement
typedef struct measurement {
    int measurement_type;
    double value;
} measurement_t;

// Mutex for protecting concurrent access to the measurement list
pthread_mutex_t measurement_list_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function to add a new measurement to the measurement list
void add_measurement(int pdu_tag, int ue_id, double value) {
    // Lock the mutex before accessing the measurement list
    pthread_mutex_lock(&measurement_list_mutex);

    // Allocate a new structure to store the measurement information
    struct measurement *new_measurement = malloc(sizeof(struct measurement));

    // Initialize the structure with the provided values
    new_measurement->pdu_tag = pdu_tag;
    new_measurement->ue_id = ue_id;
    new_measurement->value = value;

    // Add the new measurement to the end of the list
    if (measurements == NULL) {
        measurements = new_measurement;
    } else {
        struct measurement *current_measurement = measurements;
        while (current_measurement->next != NULL) {
            current_measurement = current_measurement->next;
        }
        current_measurement->next = new_measurement;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&measurement_list_mutex);
}

// Function to retrieve a measurement from the measurement list
void get_measurement(int pdu_tag, int ue_id) {
    // Lock the mutex before accessing the measurement list
    pthread_mutex_lock(&measurement_list_mutex);

    // Search for the requested measurement in the list
    struct measurement *current_measurement = measurements;
    while (current_measurement != NULL) {
        if (current_measurement->pdu_tag == pdu_tag && current_measurement->ue_id == ue_id) {
            // Return the measurement value
            printf("Measurement value: %f\n", current_measurement->value);
            break;
        }
        current_measurement = current_measurement->next;
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&measurement_list_mutex);
}

// Function to delete a measurement from the measurement list
void delete_measurement(int pdu_tag, int ue_id) {
    // Lock the mutex before accessing the measurement list
    pthread_mutex_lock(&measurement_list_mutex);

    // Search for the requested measurement in the list
    struct measurement *current_measurement = measurements;
    while (current_measurement != NULL) {
        if (current_measurement->pdu_tag == pdu_tag && current_measurement->ue_id == ue_id) {
            // Remove the measurement from the list
            struct measurement *previous_measurement = current_measurement;
            while (previous_measurement->next != NULL && previous_measurement->next->pdu_tag == pdu_tag && previous_measurement->next->ue_id == ue_id) {
                previous_measurement = previous_measurement->next;
            }
            if (previous_measurement->next != NULL) {
                current_measurement = previous_measurement->next;
                previous_measurement->next = NULL;
            } else {
                break;
            }
        }
    }

    // Unlock the mutex and return
    pthread_mutex_unlock(&measurement_list_mutex);
}

// Function to initialize the measurement list
void init_measurements() {
    // Allocate memory for the initial measurement structure
    measurements = malloc(sizeof(struct measurement));
    if (measurements == NULL) {
        printf("Failed to allocate memory for the measurement list\n");
    }
}

// Function to deinitialize the measurement list
void deinit_measurements() {
    // Free all structures in the list
    struct measurement *current_measurement = measurements;
    while (current_measurement != NULL) {
        struct measurement *next_measurement = current_measurement->next;
        free(current_measurement);
        current_measurement = next_measurement;
    }
}

// Function to handle dynamic memory allocation failures
void malloc_failure() {
    printf("Failed to allocate memory for a new measurement\n");
}

int main() {
    // Initialize the measurement list
    init_measurements();

    // Add measurements to the list
    add_measurement(1, 1001, 3.14);
    add_measurement(2, 1002, 6.28);
    add_measurement(3, 1003, 9.42);

    // Retrieve a measurement from the list
    get_measurement(2, 1002);

    // Delete a measurement from the list
    delete_measurement(3, 1003);

    // Deinitialize the measurement list
    deinit_measurements();

    return 0;
}
