#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <assert.h>

// Structure definition for NFAPI_RRC_MESSAGE_T
struct NFAPI_RRC_MESSAGE_T {
    int valid;
    char *pdu_tag;
    int ue_id;
    struct MeasurementList *measurements;
};

// Structure definition for MeasurementList
struct MeasurementList {
    int length;
    struct Measurement *data[];
};

// Structure definition for Measurement
struct Measurement {
    int type;
    double value;
};

int init_NFAPI_RRC_MESSAGE_T(char *pdu_tag, int ue_id, struct MeasurementList *measurements) {
    // Check if the PDU tag is valid
    if (strlen(pdu_tag) == 0 || strlen(pdu_tag) > 256) {
        return -1;
    }

    // Initialize a new NFAPI_RRC_MESSAGE_T structure
    struct NFAPI_RRC_MESSAGE_T *message = (struct NFAPI_RRC_MESSAGE_T *)malloc(sizeof(struct NFAPI_RRC_MESSAGE_T));
    if (!message) {
        return -2;
    }

    // Set the PDU tag, UE identifier, and measurements
    message->valid = 1;
    message->pdu_tag = (char *)malloc(strlen(pdu_tag) + 1);
    strcpy(message->pdu_tag, pdu_tag);
    message->ue_id = ue_id;
    message->measurements = measurements;

    return 0;
}

void free_NFAPI_RRC_MESSAGE_T(struct NFAPI_RRC_MESSAGE_T *message) {
    // Check if the structure is valid
    if (!message || !message->valid) {
        return;
    }

    // Free the PDU tag and measurements
    free(message->pdu_tag);
    free(message->measurements);

    // Mark the structure as invalid
    message->valid = 0;
}

int get_NFAPI_RRC_MESSAGE_T_length(struct NFAPI_RRC_MESSAGE_T *message) {
    // Check if the structure is valid
    if (!message || !message->valid) {
        return -1;
    }

    return message->measurements->length;
}

void get_NFAPI_RRC_MESSAGE_T_measurement(struct NFAPI_RRC_MESSAGE_T *message, int index, struct Measurement *measurement) {
    // Check if the structure is valid
    if (!message || !message->valid || index < 0 || index >= message->measurements->length) {
        return;
    }

    measurement->type = message->measurements->data[index]->type;
    measurement->value = message->measurements->data[index]->value;
}

struct MeasurementList *get_NFAPI_RRC_MESSAGE_T_measurements(struct NFAPI_RRC_MESSAGE_T *message) {
    // Check if the structure is valid
    if (!message || !message->valid) {
        return NULL;
    }

    return message->measurements;
}

int add_NFAPI_RRC_MESSAGE_T_measurement(struct NFAPI_RRC_MESSAGE_T *message, int measurement_type, double value) {
    // Check if the structure is valid
    if (!message || !message->valid) {
        return -1;
    }

    // Add a new measurement to the list
    struct Measurement *new_measurement = (struct Measurement *)malloc(sizeof(struct Measurement));
    if (!new_measurement) {
        return -2;
    }

    new_measurement->type = measurement_type;
    new_measurement->value = value;

    message->measurements->data[message->measurements->length++] = new_measurement;

    return 0;
}

int remove_NFAPI_RRC_MESSAGE_T_measurement(struct NFAPI_RRC_MESSAGE_T *message, int index) {
    // Check if the structure is valid
    if (!message || !message->valid || index < 0 || index >= message->measurements->length) {
        return -1;
    }

    free(message->measurements->data[index]);
    message->measurements->data[index] = NULL;

    return 0;
}

struct NFAPI_RRC_MESSAGE_T *NFAPI_RRC_MESSAGE_T_new() {
    // Initialize a new NFAPI_RRC_MESSAGE_T structure
    struct NFAPI_RRC_MESSAGE_T *message = (struct NFAPI_RRC_MESSAGE_T *)malloc(sizeof(struct NFAPI_RRC_MESSAGE_T));
    if (!message) {
        return NULL;
    }

    message->valid = 0;
    message->pdu_tag = NULL;
    message->ue_id = -1;
    message->measurements = NULL;

    return message;
}

void NFAPI_RRC_MESSAGE_T_free(struct NFAPI_RRC_MESSAGE_T *message) {
    // Check if the structure is valid
    if (!message || !message->valid) {
        return;
    }

    free_NFAPI_RRC_MESSAGE_T(message);
}']

