#include <stdio.h>

// Define the structure for the TrafficEvent data type
typedef struct {
    unsigned long timestamp; // Timestamp for the event (in milliseconds)
    int event_type; // Type of traffic event (e.g., congestion, accident, etc.)
    int id; // Unique identifier for the event
    char location[20]; // Location identifier for the event
} TrafficEvent;

// Define a dynamic array to store the TrafficEvents
typedef struct {
    TrafficEvent** events; // Array of pointers to TrafficEvent structures
    int capacity; // Current capacity of the array
    int size; // Current number of elements in the array
} DynamicArray;

// Initialize a new dynamic array with the specified capacity
void initialize_array(DynamicArray* array, int capacity) {
    array->events = (TrafficEvent**)malloc(capacity * sizeof(TrafficEvent*));
    if (!array->events) {
        fprintf(stderr, "Failed to allocate memory for dynamic array\n");
        return;
    }
    array->capacity = capacity;
    array->size = 0;
}

// Add a new TrafficEvent to the array
void add_event(DynamicArray* array, const TrafficEvent* event) {
    if (array->size == array->capacity) {
        // Resize the array if it's full
        int new_capacity = array->capacity * 2;
        TrafficEvent** new_events = (TrafficEvent**)realloc(array->events, new_capacity * sizeof(TrafficEvent*));
        if (!new_events) {
            fprintf(stderr, "Failed to resize dynamic array\n");
            return;
        }
        array->events = new_events;
        array->capacity = new_capacity;
    }
    // Copy the event structure into the next available slot in the array
    array->events[array->size++] = (TrafficEvent*)malloc(sizeof(TrafficEvent));
    memcpy(array->events[array->size - 1], event, sizeof(TrafficEvent));
}

// Update an existing TrafficEvent in the array by ID
void update_event(DynamicArray* array, int id, const TrafficEvent* event) {
    // Search for the event with the specified ID
    int i;
    for (i = 0; i < array->size; i++) {
        if (array->events[i]->id == id) {
            break;
        }
    }
    if (i >= array->size) {
        fprintf(stderr, "Could not find event with ID %d\n", id);
        return;
    }
    // Copy the new event structure into the found slot in the array
    memcpy(array->events[i], event, sizeof(TrafficEvent));
}

// Retrieve all TrafficEvents within a specified time range and geographic area
void retrieve_events(DynamicArray* array, unsigned long start_time, unsigned long end_time, const char* location) {
    // Search for events in the specified time range and geographic area
    int i;
    for (i = 0; i < array->size; i++) {
        TrafficEvent* event = array->events[i];
        if (event->timestamp >= start_time && event->timestamp <= end_time && strcmp(event->location, location) == 0) {
            // Print the found event
            printf("Event ID: %d\n", event->id);
            printf("Timestamp: %lu\n", event->timestamp);
            printf("Type: %d\n", event->event_type);
            printf("Location: %s\n", event->location);
        }
    }
}

// Cleanup function to free the memory allocated for the dynamic array
void cleanup_array(DynamicArray* array) {
    if (array->events) {
        int i;
        for (i = 0; i < array->size; i++) {
            free(array->events[i]);
        }
        free(array->events);
    }
}
