void init_nfapi_task(struct nfapi_task *task) {
    task->priority = 0;
    task->description = "Default Task";
}

// Function to create a new sub-task node
struct sub_task_node* create_sub_task_node() {
    struct sub_task_node *new_node = malloc(sizeof(struct sub_task_node));
    if (new_node == NULL) {
        // Handle memory allocation failure gracefully
        printf("Memory allocation failed. Returning null.\n");
        return NULL;
    }
    new_node->next = NULL;
    init_nfapi_task(&(new_node->task));
    return new_node;
}

// Function to add a sub-task to the linked list
void add_sub_task(struct sub_task_node *head, struct nfapi_task task) {
    if (head == NULL) {
        head = create_sub_task_node();
        head->task = task;
    } else {
        struct sub_task_node *curr = head;
        while (curr->next != NULL) {
            curr = curr->next;
        }
        curr->next = create_sub_task_node();
        curr->next->task = task;
    }
}

// Function to remove a sub-task from the linked list
void remove_sub_task(struct sub_task_node *head, struct nfapi_task task) {
    if (head == NULL) return;
    else if (head->task.rx_ue_information_tag == task.rx_ue_information_tag && head->task.rnti == task.rnti) {
        struct sub_task_node *curr = head;
        struct sub_task_node *prev = NULL;
        while (curr != NULL && curr->next != NULL) {
            if (curr->next->task.rx_ue_information_tag == task.rx_ue_information_tag && curr->next->task.rnti == task.rnti) {
                if (prev != NULL) {
                    prev->next = curr->next;
                } else {
                    head = curr->next;
                }
            }
        }
    } else {
        struct sub_task_node *curr = head;
        while (curr != NULL && curr->next != NULL) {
            if (curr->next->task.rx_ue_information_tag == task.rx_ue_information_tag && curr->next->task.rnti == task.rnti) {
                struct sub_task_node *prev = curr;
                curr = curr->next;
                prev->next = curr->next;
            } else {
                curr = curr->next;
            }
        }
    }
}

// Function to update the priority of a task in the linked list
void update_priority(struct sub_task_node *head, struct nfapi_task task) {
    if (head == NULL) return;
    else if (head->task.rx_ue_information_tag == task.rx_ue_information_tag && head->task.rnti == task.rnti) {
        head->priority = task.priority;
    } else {
        struct sub_task_node *curr = head;
        while (curr != NULL && curr->next != NULL) {
            if (curr->next->task.rx_ue_information_tag == task.rx_ue_information_tag && curr->next->task.rnti == task.rnti) {
                curr->next->priority = task.priority;
                break;
            } else {
                curr = curr->next;
            }
        }
    }
}

// Function to handle asynchronous task creation and deletion events
void handle_task_event(struct sub_task_node *head, struct nfapi_task task) {
