        memcpy(new_structure, &structures[i], sizeof(NFAPI_CRC_INDICATION_PDU_T));
        new_structure->next = structure_list;
        structure_list = new_structure;
    }
    pthread_mutex_unlock(&memory_pool_mutex);
}

// Frees all allocated structures and clears the linked list
void free_all_structures() {
    struct NFAPI_CRC_INDICATION_PDU_T *structure = structure_list;
    while (structure != NULL) {
        struct NFAPI_CRC_INDICATION_PDU_T *next_structure = structure->next;
        free(structure);
        structure = next_structure;
    }
    structure_list = NULL;
}

