// Structure to store script information
typedef struct ScriptObject {
    char* scriptId;
    char* scriptCode;
} ScriptObject;

// Function to render footer scripts as an HTML string
char* renderFooterScripts(ScriptObject* scriptObjects, int numScripts) {
    // Initialize the HTML template
    char* html = "<script type=\"text/javascript\">";

    // Iterate over each script object and append it to the HTML template
    for (int i = 0; i < numScripts; i++) {
        ScriptObject* script = &scriptObjects[i];
        char* scriptId = script->scriptId;
        char* scriptCode = script->scriptCode;

        // Append the script ID and code to the HTML template
        html = (char*)realloc(html, strlen(html) + strlen(scriptId) + strlen(scriptCode) + 1);
        strcat(html, scriptId);
        strcat(html, "=");
        strcat(html, scriptCode);
    }

    // Add the closing </script> tag to the HTML template
    html = (char*)realloc(html, strlen(html) + 13);
    strcat(html, "</script>");

    return html;
}

// Function to generate a random number within a given range
int generateRandomNumber(int min, int max) {
    // Calculate the range of numbers to generate
    int range = (max - min) + 1;

    // Generate a random number between 0 and the range
    return rand() % range + min;
}

// Function to handle script execution with randomization
void executeScriptsWithRandomization(ScriptObject* scriptObjects, int numScripts) {
    // Set the random seed for generating random numbers
    srand(time(NULL));

    // Iterate over each script object and execute it with a random delay
    for (int i = 0; i < numScripts; i++) {
        ScriptObject* script = &scriptObjects[i];
        char* scriptId = script->scriptId;
        char* scriptCode = script->scriptCode;

        // Generate a random number of milliseconds to wait before executing the script
        int delay = generateRandomNumber(0, 100) * 100;

        // Execute the script with the generated delay
        printf("Executing script %s with delay of %d ms\n", scriptId, delay);
        fflush(stdout);
        usleep(delay);
    }
}

// Function to handle script execution without randomization
void executeScriptsWithoutRandomization(ScriptObject* scriptObjects, int numScripts) {
    // Iterate over each script object and execute it with the default delay
    for (int i = 0; i < numScripts; i++) {
        ScriptObject* script = &scriptObjects[i];
        char* scriptId = script->scriptId;
        char* scriptCode = script->scriptCode;

        // Execute the script with the default delay
        printf("Executing script %s with default delay\n", scriptId);
        fflush(stdout);
    }
}

// Function to handle script execution based on configuration and environment variables
void executeScriptsWithConfiguration(ScriptObject* scriptObjects, int numScripts) {
    // Check if the RANDOM_SEED environment variable is set
    char* randomSeed = getenv("RANDOM_SEED");
    if (randomSeed != NULL) {
        // Execute scripts with randomization using the random seed
        executeScriptsWithRandomization(scriptObjects, numScripts);
    } else {
        // Execute scripts without randomization
        executeScriptsWithoutRandomization(scriptObjects, numScripts);
    }
}
