#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <pthread.h>

struct NetworkStat {
    time_t timestamp;
    char interface[16];
    unsigned long packet_loss, latency, throughput;
};

struct RecordListNode {
    struct NetworkStat record;
    struct RecordListNode* next;
};

struct RecordList {
    struct RecordListNode* head;
    struct RecordListNode* tail;
    pthread_mutex_t mutex;
    int size;
};

void init_list(struct RecordList* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&(list->mutex), NULL);
}

void insert_record(struct RecordList* list, struct NetworkStat record) {
    pthread_mutex_lock(&(list->mutex));
    struct RecordListNode* new_node = malloc(sizeof(struct RecordListNode));
    new_node->record = record;
    if (list->head == NULL) {
        list->head = new_node;
        list->tail = new_node;
    } else {
        list->tail->next = new_node;
        list->tail = new_node;
    }
    list->size++;
    pthread_mutex_unlock(&(list->mutex));
}

void delete_record(struct RecordList* list, struct NetworkStat record) {
    pthread_mutex_lock(&(list->mutex));
    struct RecordListNode* current = list->head;
    while (current != NULL && current->next != NULL) {
        if (memcmp(&(current->record), &record, sizeof(struct NetworkStat)) == 0) {
            struct RecordListNode* next = current->next;
            free(current);
            list->size--;
            current = next;
            break;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&(list->mutex));
}

void clear_old_records(struct RecordList* list, int age) {
    time_t current_time = time(NULL);
    struct RecordListNode* current = list->head;
    while (current != NULL && current->next != NULL) {
        if (difftime(current_time, current->record.timestamp) > age) {
            struct RecordListNode* next = current->next;
            free(current);
            list->size--;
            current = next;
        } else {
            break;
        }
    }
}

void save_records(struct RecordList* list, char* filepath) {
    int fd = open(filepath, O_WRONLY | O_CREAT, 0644);
    if (fd == -1) {
        printf("Error opening file %s\n", strerror(errno));
        return;
    }
    struct RecordListNode* current = list->head;
    while (current != NULL) {
        write(fd, &(current->record), sizeof(struct NetworkStat));
        current = current->next;
    }
    close(fd);
}

void load_records(struct RecordList* list, char* filepath) {
    int fd = open(filepath, O_RDONLY, 0644);
    if (fd == -1) {
        printf("Error opening file %s\n", strerror(errno));
        return;
    }
    struct RecordListNode* current = list->head;
    while (current != NULL) {
        read(fd, &(current->record), sizeof(struct NetworkStat));
        current = current->next;
    }
    close(fd);
}

void network_statistics_manager(char* filepath) {
    struct RecordList list;
    init_list(&list);
    int age = 100000; // seconds
    while (true) {
        clear_old_records(&list, age);
        save_records(&list, filepath);
        sleep(3600);
    }
}']

