    log_entry->timestamp = get_current_time();

    // Add the new log entry to the logging service
    logging_service->logs[logging_service->num_logs] = log_entry;
    logging_service->num_logs++;
}

// Function to clean up all allocated memory for the index data structure and external logging service
void free_index(IndexData* index) {
    // Free memory for the offset and key arrays
    free(index->offsets);
    free(index->keys);

    // Free memory for each record in the record array
    for (int i = 0; i < index->num_records; i++) {
        free(index->records[i]);
    }

    // Free memory for the record array
    free(index->records);
}

// Function to clean up all allocated memory for the external logging service
void free_logging(LoggingService* logging_service) {
    // Free memory for each log entry in the logs array
    for (int i = 0; i < logging_service->num_logs; i++) {
        free(logging_service->logs[i]);
    }

    // Free memory for the logs array
    free(logging_service->logs);
}

// Function to get the current time in seconds since the epoch
long get_current_time() {
    return time(NULL);
}
