    int flow_id;
    char* source_ip;
    char* destination_ip;
    int packet_count;
    long byte_count;
};

// Define the function that initializes and manages the dynamic array of LTE PHY frames
int init_lte_phy_frames(int num_frames) {
    // Allocate memory for the array of LTE PHY frames
    LTE_PHY_RX_FRAME* frames = (LTE_PHY_RX_FRAME*)malloc(sizeof(LTE_PHY_RX_FRAME) * num_frames);
    if (!frames) {
        return 1; // Return an error code if memory allocation fails
    }

    // Initialize each frame with a valid header, signal strength indicator, and empty symbol list
    for (int i = 0; i < num_frames; i++) {
        frames[i].num_symbols = 0;
    }

    return 0; // Return success if memory allocation succeeds
}

// Define the function that adds a new LTE PHY symbol to a frame and updates the signal strength indicator
void add_lte_phy_symbol(LTE_PHY_RX_FRAME* frame, ModulationType modulation, float phase_rotation, float noise_variance) {
    // Check if the frame is null or has no space for new symbols
    if (!frame || frame->num_symbols >= MAX_NUM_SYMBOLS) {
        return;
    }

    // Allocate memory for a new symbol and add it to the end of the list
    struct LTE_PHY_SYMBOL* symbol = (struct LTE_PHY_SYMBOL*)malloc(sizeof(struct LTE_PHY_SYMBOL));
    if (!symbol) {
        return; // Return if memory allocation fails
    }
    symbol->modulation = modulation;
    symbol->phase_rotation = phase_rotation;
    symbol->noise_variance = noise_variance;
    frame->symbols[frame->num_symbols++] = symbol;
}

// Define the function that updates the signal strength indicator for a given LTE PHY symbol
void update_lte_phy_signal_strength(LTE_PHY_RX_FRAME* frame, int symbol_index) {
    // Check if the frame or symbol index are invalid
    if (!frame || symbol_index < 0 || symbol_index >= frame->num_symbols) {
        return;
    }

    // Update the signal strength indicator for the specified symbol
    float new_strength = calculate_signal_strength(frame->symbols[symbol_index]);
    frame->symbols[symbol_index]->strength = new_strength;
}

// Define the function that updates the network monitoring system with a new log entry
void update_network_monitoring(LogEntry* entry) {
    // Check if the log entry is null or has an invalid timestamp
    if (!entry || entry->timestamp < 0) {
        return;
    }

    // Allocate memory for a new log entry and add it to the end of the array
    LogEntry* new_entry = (LogEntry*)malloc(sizeof(LogEntry));
    if (!new_entry) {
        return; // Return if memory allocation fails
    }
    *new_entry = *entry;
    log_entries[num_log_entries++] = new_entry;
}

// Define the function that handles network flow records and updates the monitoring system accordingly
void handle_network_flow(NetworkFlowRecord* flow) {
    // Check if the flow record is null or has an invalid flow ID
    if (!flow || flow->flow_id < 0) {
        return;
    }

    // Update the network flow record in the monitoring system
    NetworkFlowRecord* updated_record = (NetworkFlowRecord*)malloc(sizeof(NetworkFlowRecord));
    *updated_record = *flow;
    updated_record->packet_count++;
    updated_record->byte_count += flow->byte_count;
}

// Define the function that periodically flushes logs to disk to ensure data persistence
void flush_logs() {
    // Check if there are any log entries to be flushed
    if (num_log_entries <= 0) {
        return;
    }

    // Allocate memory for a new log file and write the current log entries to it
    FILE* log_file = fopen("logs.txt", "w");
    if (!log_file) {
        return; // Return if the log file cannot be opened
    }
    for (int i = 0; i < num_log_entries; i++) {
        LogEntry* entry = log_entries[i];
        fprintf(log_file, "%s\n", entry->message);
    }
    fclose(log_file);
}

// Define the function that handles race conditions and deadlocks in the monitoring system
void synchronize() {
    // Check if there are any log entries to be flushed
    if (num_log_entries <= 0) {
        return;
    }

    // Acquire a lock on the log entry array
    while (!trylock(log_mutex)) {
        continue;
    }

    // Flush the logs and release the lock
    flush_logs();
    unlock(log_mutex);
}

// Define the function that updates the signal strength indicator for all symbols in a given frame
void update_signal_strength() {
    // Check if there are any frames to be processed
    if (num_frames <= 0) {
        return;
    }

    // Iterate over each frame and update its signal strength indicator
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = frames[i];
        for (int j = 0; j < frame->num_symbols; j++) {
            update_lte_phy_signal_strength(frame, j);
        }
    }
}

// Define the function that adds a new LTE PHY symbol to all frames and updates the signal strength indicator
void add_new_symbol() {
    // Check if there are any frames to be processed
    if (num_frames <= 0) {
        return;
    }

    // Iterate over each frame and add a new symbol to it
    for (int i = 0; i < num_frames; i++) {
        LTE_PHY_RX_FRAME* frame = frames[i];
        add_lte_phy_symbol(frame, MODULATION_TYPE, PHASE_ROTATION, NOISE_VARIANCE);
    }
}

// Define the function that updates the network flow records and updates the monitoring system accordingly
void update_network_flow() {
    // Check if there are any network flow records to be processed
    if (num_flows <= 0) {
        return;
    }

    // Iterate over each network flow record and update the monitoring system
    for (int i = 0; i < num_flows; i++) {
        NetworkFlowRecord* flow = flows[i];
        handle_network_flow(flow);
    }
}
