// Define the structure for storing user sessions
typedef struct UserSession {
    uint64_t session_id;
    char* user_ip;
    float data_transfer_rate;
} UserSession;

// Define a linked list node for storing user sessions
typedef struct Node {
    UserSession* session;
    struct Node* next;
} Node;

// Define the linked list structure for storing all user sessions
typedef struct LinkedList {
    Node* head;
    Node* tail;
} LinkedList;

// Function to add a new user session to the linked list
void addSession(LinkedList* list, UserSession* session) {
    // Check if the session ID is already in use
    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->session->session_id == session->session_id) {
            printf("Error: session ID %llu is already in use\n", session->session_id);
            return;
        }
    }

    // Add the new session to the linked list
    Node* newNode = malloc(sizeof(Node));
    if (newNode == NULL) {
        printf("Error: unable to allocate memory for new node\n");
        return;
    }
    newNode->session = session;
    newNode->next = NULL;
    list->tail->next = newNode;
    list->tail = newNode;
}

// Function to retrieve a user session from the linked list
UserSession* getSession(LinkedList* list, uint64_t sessionId) {
    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->session->session_id == sessionId) {
            return node->session;
        }
    }
    printf("Error: session ID %llu not found\n", sessionId);
    return NULL;
}

// Function to update a user session in the linked list
void updateSession(LinkedList* list, uint64_t sessionId, UserSession* session) {
    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->session->session_id == sessionId) {
            node->session = session;
            return;
        }
    }
    printf("Error: session ID %llu not found\n", sessionId);
}

// Function to remove a user session from the linked list
void removeSession(LinkedList* list, uint64_t sessionId) {
    for (Node* node = list->head; node != NULL; node = node->next) {
        if (node->session->session_id == sessionId) {
            Node* prevNode = node->prev;
            Node* nextNode = node->next;
            free(node);
            prevNode->next = nextNode;
            return;
        }
    }
    printf("Error: session ID %llu not found\n", sessionId);
}

// Function to clear expired sessions from the linked list
void cleanupSessions(LinkedList* list) {
    // Iterate through the list and remove any nodes with an expired session
    for (Node* node = list->head; node != NULL; ) {
        if (node->session->data_transfer_rate <= 0.0f) {
            Node* nextNode = node->next;
            free(node);
            node = nextNode;
        } else {
            node = node->next;
        }
    }
}

// Function to handle a full linked list by resizing it when necessary
void resizeList(LinkedList* list) {
    // Check if the list needs to be resized
    int size = list->tail - list->head + 1;
    if (size >= 100000) {
        // Resize the list by doubling its capacity
        LinkedList* newList = malloc(sizeof(LinkedList));
        if (newList == NULL) {
            printf("Error: unable to allocate memory for new list\n");
