// Define a struct to store interface configuration settings
typedef struct {
    char *interface_id;
    uint32_t ip_address;
    uint32_t subnet_mask;
} InterfaceConfig;

// Define a list data structure to store the sorted interface identifiers
typedef struct ListNode {
    InterfaceConfig config;
    struct ListNode *next;
} ListNode;

// Global variable to store the head of the linked list
static ListNode *head = NULL;

// Function to add a new interface configuration to the list
int addInterface(char *interface_id, uint32_t ip_address, uint32_t subnet_mask) {
    // Create a new node for the interface configuration
    ListNode *new_node = malloc(sizeof(ListNode));
    if (new_node == NULL) {
        return -ENOMEM;
    }

    // Set the values of the new node
    new_node->config.interface_id = interface_id;
    new_node->config.ip_address = ip_address;
    new_node->config.subnet_mask = subnet_mask;

    // Insert the new node in the correct position in the list
    ListNode **prev = &head;
    while (*prev != NULL && strcmp(interface_id, (*prev)->config.interface_id) > 0) {
        prev = &(*prev)->next;
    }
    new_node->next = *prev;
    *prev = new_node;

    return 0;
}

// Function to remove an interface configuration from the list
int removeInterface(char *interface_id) {
    // Find the node with the matching interface ID
    ListNode **prev = &head;
    while (*prev != NULL && strcmp(interface_id, (*prev)->config.interface_id) > 0) {
        prev = &(*prev)->next;
    }

    // Check if the node was found
    if (*prev == NULL || strcmp(interface_id, (*prev)->config.interface_id) != 0) {
        return -ENOENT;
    }

    // Remove the node from the list
    ListNode *node = *prev;
    *prev = node->next;

    // Free the memory allocated to the node
    free(node);

    return 0;
}

// Function to update an interface configuration in the list
int updateInterface(char *interface_id, uint32_t ip_address, uint32_t subnet_mask) {
    // Find the node with the matching interface ID
    ListNode **prev = &head;
    while (*prev != NULL && strcmp(interface_id, (*prev)->config.interface_id) > 0) {
        prev = &(*prev)->next;
    }

    // Check if the node was found
    if (*prev == NULL || strcmp(interface_id, (*prev)->config.interface_id) != 0) {
        return -ENOENT;
    }

    // Update the values of the node
    (*prev)->config.ip_address = ip_address;
    (*prev)->config.subnet_mask = subnet_mask;

    return 0;
}

// Function to sort the list of interface identifiers in ascending order
void sortInterfaces() {
    // If there are no interfaces, do nothing
    if (head == NULL) {
        return;
    }

    // Declare a temporary array to store the sorted interface IDs
    char *interface_ids[1024];

    // Populate the temporary array with the interface IDs in ascending order
    ListNode *node = head;
    int index = 0;
    while (node != NULL) {
        interface_ids[index++] = node->config.interface_id;
        node = node->next;
    }

    // Sort the temporary array using a quicksort algorithm
    qsort(interface_ids, index, sizeof(char *), compareInterfaceIds);

    // Update the list with the sorted interface IDs
    ListNode **prev = &head;
    for (int i = 0; i < index; i++) {
        ListNode *node = malloc(sizeof(ListNode));
        node->config.interface_id = interface_ids[i];
        node->next = NULL;
        prev->next = node;
        prev = &node->next;
    }
}

// Comparison function for sorting the list of interface IDs in ascending order
int compareInterfaceIds(const void *a, const void *b) {
    return strcmp(*(char **)a, *(char **)b);
}
