#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Structure to represent a network interface configuration setting
struct ifconfig {
    char *id; // Unique identifier for the interface
    char *ipaddr; // IP address of the interface
    char *subnet_mask; // Subnet mask for the interface
};

// List data structure to store the list of network interface configurations
typedef struct ifconfig_list {
    int count; // Number of elements in the list
    struct ifconfig *data; // Array of ifconfig structures
} ifconfig_list_t;

// Function to add a new network interface configuration setting to the list
int ifconfig_add(ifconfig_list_t *list, char *id, char *ipaddr, char *subnet_mask) {
    // Check if the list is full
    if (list->count == MAX_IFCONFIG_COUNT) {
        return -1; // Return error code if the list is full
    }

    // Allocate memory for a new ifconfig structure
    struct ifconfig *new_ifconfig = malloc(sizeof(struct ifconfig));
    if (new_ifconfig == NULL) {
        return -2; // Return error code if memory allocation fails
    }

    // Set the fields of the new ifconfig structure
    strcpy(new_ifconfig->id, id);
    strcpy(new_ifconfig->ipaddr, ipaddr);
    strcpy(new_ifconfig->subnet_mask, subnet_mask);

    // Add the new ifconfig structure to the list
    list->data[list->count++] = new_ifconfig;

    return 0; // Return success code if everything is added successfully
}

// Function to remove a network interface configuration setting from the list
int ifconfig_remove(ifconfig_list_t *list, char *id) {
    // Check if the id exists in the list
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->data[i]->id, id) == 0) {
            // If found, remove the element from the list
            free(list->data[i]);
            list->data[i] = NULL;
            break;
        }
    }

    return 0; // Return success code if everything is removed successfully
}

// Function to update a network interface configuration setting in the list
int ifconfig_update(ifconfig_list_t *list, char *id, char *ipaddr, char *subnet_mask) {
    // Check if the id exists in the list
    for (int i = 0; i < list->count; i++) {
        if (strcmp(list->data[i]->id, id) == 0) {
            // If found, update the fields of the element
            strcpy(list->data[i]->ipaddr, ipaddr);
            strcpy(list->data[i]->subnet_mask, subnet_mask);
            return 0; // Return success code if everything is updated successfully
        }
    }

    return -1; // Return error code if the id is not found in the list
}

// Function to process network resource paths
char *process_path(const char *path, size_t max_length) {
    // Check for null pointers or empty strings
    if (path == NULL || strlen(path) == 0) {
        return NULL;
    }

    // Add a forward slash at the end of the path if it does not exceed the specified length
    size_t len = strlen(path);
    if (len < max_length) {
        char *new_path = malloc((max_length + 1) * sizeof(char));
        if (new_path == NULL) {
            return NULL;
        }

        // Copy the path and add a forward slash at the end
        strcpy(new_path, path);
        new_path[len] = '/';
        new_path[len + 1] = '\0';

        return new_path;
    }

    // Return NULL if the path exceeds the limit
    return NULL;
}
