}

// Function to validate an incoming SRVCC event tag against the predefined list of allowed values
bool isSrvccEventTagValid(const char* srvccEventTag) {
    for (int i = 0; i < NUM_SRVCC_EVENT_TAGS; i++) {
        if (!strcmp(srvccEventTag, SRVCC_EVENT_TAGS[i])) {
            return true;
        }
    }
    return false;
}

// Function to update the LTE_UESRVCC_DATA_PDU structure with a new SRVCC event tag and version number
void updateLteUesrvcDataPdu(LTE_UESRVCC_DATA_PDU* lteUesrvcDataPdu, const char* srvccEventTag, RRC_VERSION rrcVersion) {
