/* Function to initialize and manage a dynamic array of LTE_PHY_RX_FRAME structure instances */
void init_LTE_PHY_RX_FRAME(struct LTE_PHY_RX_SESSION* session) {
    /* Allocate memory for the list of frames in this session */
    session->frames.data = malloc(sizeof(struct LTE_PHY_RX_FRAME*) * 100);
    if (!session->frames.data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    session->frames.size = 0;

    /* Initialize the mutex for synchronizing concurrent access to this session */
    pthread_mutex_init(&session->lock, NULL);
}

/* Function to add a new LTE PHY RX frame to the dynamic array */
void add_LTE_PHY_RX_FRAME(struct LTE_PHY_RX_SESSION* session, struct LTE_PHY_RX_FRAME* frame) {
    /* Lock the mutex for synchronizing concurrent access to this session */
    pthread_mutex_lock(&session->lock);

    /* Allocate memory for the new frame in this session */
    struct LTE_PHY_RX_FRAME* new_frame = malloc(sizeof(struct LTE_PHY_RX_FRAME));
    if (!new_frame) {
        perror("malloc");
        pthread_mutex_unlock(&session->lock);
        exit(EXIT_FAILURE);
    }

    /* Copy the contents of the new frame from the input argument */
    memcpy(new_frame, frame, sizeof(struct LTE_PHY_RX_FRAME));

    /* Add the new frame to the list of frames in this session */
    session->frames.data[session->frames.size] = new_frame;
    session->frames.size++;

    /* Unlock the mutex for synchronizing concurrent access to this session */
    pthread_mutex_unlock(&session->lock);
}

/* Function to remove a LTE PHY RX frame from the dynamic array */
void remove_LTE_PHY_RX_FRAME(struct LTE_PHY_RX_SESSION* session, int index) {
    /* Lock the mutex for synchronizing concurrent access to this session */
    pthread_mutex_lock(&session->lock);

    /* Remove the frame from the list of frames in this session */
    free(session->frames.data[index]);
    session->frames.data[index] = NULL;
    session->frames.size--;

    /* Shift all frames after the removed one to fill the gap */
    for (int i = index; i < session->frames.size; i++) {
        session->frames.data[i] = session->frames.data[i + 1];
    }

    /* Unlock the mutex for synchronizing concurrent access to this session */
    pthread_mutex_unlock(&session->lock);
}

/* Function to retrieve a LTE PHY RX frame from the dynamic array by index */
struct LTE_PHY_RX_FRAME* get_LTE_PHY_RX_FRAME(struct LTE_PHY_RX_SESSION* session, int index) {
    /* Lock the mutex for synchronizing concurrent access to this session */
    pthread_mutex_lock(&session->lock);

