    list->capacity = 10; // initial capacity of 10 elements
    list->elements = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
}

void crc_indication_list_add(struct crc_indication_list *list, uint32_t rnti, uint8_t crcflag) {
