    if (list->size == list->capacity) {
        // double the capacity of the list
        list->capacity *= 2;
        list->elements = realloc(list->elements, sizeof(NFAPI_CRC_INDICATION_PDU_T) * list->capacity);
    }
    // add a new element to the end of the list
    NFAPI_CRC_INDICATION_PDU_T *new_element = &list->elements[list->size++];
    new_element->RX_UE_INFORMATION_TAG = 0;
    new_element->RNTI = rnti;
    new_element->CRC_INDICATION_REL8_TAG = crcflag;
}

void crc_indication_list_update(struct crc_indication_list *list, uint32_t rnti, uint8_t crcflag) {
