using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using Newtonsoft.Json;

public class TrafficEventManager
{
    private readonly Dictionary<int, TrafficEvent> events = new Dictionary<int, TrafficEvent>();
    private readonly Random random = new Random();
    private readonly object syncLock = new object();

    // Constructor
    public TrafficEventManager() { }

    // Methods
    public void Initialize(DateTime minTime, DateTime maxTime)
    {
        lock (syncLock)
        {
            events.Clear();
            this.minTime = minTime;
            this.maxTime = maxTime;
        }
    }

    public void AddEvent(TrafficEvent event)
    {
        if (event == null)
        {
            throw new ArgumentNullException("event");
        }

        lock (syncLock)
        {
            // Check if the event is within the allowed time range
            if (event.Timestamp < minTime || event.Timestamp > maxTime)
            {
                throw new InvalidOperationException("The event timestamp is outside of the allowed range.");
            }

            // Generate a unique event ID
            int eventId = GenerateRandomEventId();
            event.Id = eventId;

            events[eventId] = event;
        }
    }

    public void UpdateEvent(int eventId, TrafficEvent updatedEvent)
    {
        if (updatedEvent == null)
        {
            throw new ArgumentNullException("updatedEvent");
        }

        lock (syncLock)
        {
            // Check if the event exists
            if (!events.ContainsKey(eventId))
            {
                throw new InvalidOperationException("The event does not exist.");
            }

            events[eventId] = updatedEvent;
        }
    }

    public TrafficEvent GetEvent(int eventId)
    {
        if (eventId == 0)
        {
            throw new ArgumentOutOfRangeException("eventId");
        }

        lock (syncLock)
        {
            return events.GetValueOrDefault(eventId);
        }
    }

    public List<TrafficEvent> GetEvents(DateTime minTime, DateTime maxTime)
    {
        if (minTime > maxTime)
        {
            throw new ArgumentException("The minimum time is greater than the maximum time.");
        }

        lock (syncLock)
        {
            return events.Values.Where(e => e.Timestamp >= minTime && e.Timestamp <= maxTime).ToList();
        }
    }

    public string ToString()
    {
        var builder = new StringBuilder();
        foreach (var event in events.Values)
        {
            builder.AppendLine(event.ToString());
        }
        return builder.ToString();
    }

    public void SerializeToJson(string filename)
    {
        if (filename == null)
        {
            throw new ArgumentNullException("filename");
        }

        lock (syncLock)
        {
            var json = JsonConvert.SerializeObject(events);
            File.WriteAllText(filename, json);
        }
    }

    // Private methods
    private int GenerateRandomEventId()
    {
        int eventId;
        do
        {
            eventId = random.Next(int.MaxValue);
        } while (events.ContainsKey(eventId));
        return eventId;
    }
}
