// Define structure for linked list of sub-tasks
struct SubTask {
  int priority;
  char* description;
  bool crc_flag;
  struct SubTask* next;
};

// Define function to initialize a task
void initTask(struct SubTask* task) {
  // Initialize task priority to random value between 1 and 10
  task->priority = rand() % 10 + 1;
  // Set task description to default message "Default Task"
  task->description = "Default Task";
  // Initialize CRC flag to randomly set CRCFLAG
  task->crc_flag = (rand() % 2 == 0);
}

// Define function to allocate memory for linked list of sub-tasks
struct SubTask* allocateSubTasks(int numTasks) {
  // Allocate memory for each sub-task structure
  struct SubTask* tasks = malloc(numTasks * sizeof(struct SubTask));
  if (tasks == NULL) {
    // Reallocate from pre-allocated pool or use fallback strategy if allocation fails
    return NULL;
  }

  // Initialize each sub-task structure with default values
  for (int i = 0; i < numTasks; i++) {
    initTask(&tasks[i]);
  }

  // Return pointer to first sub-task in linked list
  return tasks;
}

// Define function to handle memory allocation failures
void freeSubTasks(struct SubTask* tasks) {
  // Free each sub-task structure in linked list
  while (tasks != NULL) {
    struct SubTask* temp = tasks;
    tasks = tasks->next;
    free(temp);
  }
}

// Define function to add a new task to the linked list
void addTask(struct SubTask** head, struct SubTask* task) {
  // Insert new task at beginning of linked list
  task->next = *head;
  *head = task;
}

// Define function to remove a task from the linked list
void removeTask(struct SubTask** head, struct SubTask* task) {
  // Find previous node in linked list that points to task
  struct SubTask* prev = NULL;
  for (struct SubTask* curr = *head; curr != NULL; curr = curr->next) {
    if (curr == task) {
      prev->next = curr->next;
      free(task);
      break;
    } else {
      prev = curr;
    }
  }
}

// Define function to fetch and validate frame metadata
void fetchFrameMetadata(struct SubTask** head, int* numTasks) {
  // Fetch frame metadata from external data processing module
  struct FrameMetadata metadata = fetch_metadata();

  // Validate frame metadata against corruption threshold
  if (metadata.corrupted) {
    // Reinitialize symbol arrays and data if necessary
    for (struct SubTask* task = *head; task != NULL; task = task->next) {
      initTask(task);
    }
  } else {
    // Add new tasks to linked list for each valid frame
    for (int i = 0; i < metadata.num_frames; i++) {
      struct SubTask* task = malloc(sizeof(struct SubTask));
      initTask(task);
      addTask(head, task);
    }
  }
}

// Define function to handle memory allocation failures during asynchronous task creation and deletion events
void asyncMemoryAllocationFailureHandler(struct SubTask** head, int* numTasks) {
  // Reallocate from pre-allocated pool or use fallback strategy if allocation fails
  struct SubTask* tasks = reallocate_tasks(*head);
  if (tasks == NULL) {
    // Use fallback strategy to maintain system stability under high load conditions
    for (struct SubTask* task = *head; task != NULL; task = task->next) {
      initTask(task);
    }
  } else {
    // Update linked list with new set of tasks
    *head = tasks;
    *numTasks = count_tasks(*head);
  }
}

// Define function to track total memory usage and release allocated resources when linked list is no longer needed
void trackMemoryUsage(struct SubTask** head, int* numTasks) {
  // Track total memory usage for linked list of sub-tasks
  long mem_usage = 0;
  for (struct SubTask* task = *head; task != NULL; task = task->next) {
    mem_usage += sizeof(struct SubTask);
  }

  // Release allocated resources when linked list is no longer needed
  freeSubTasks(*head);
}

// Define function to scale horizontally and maintain low-latency operation
void horizontalScaling(struct SubTask** head, int* numTasks) {
  // Add new nodes to linked list for each valid frame
  for (int i = 0; i < *numTasks; i++) {
