class MacFrameBuffer:
    def __init__(self, max_buffer_size, growth_factor):
        self.max_buffer_size = max_buffer_size
        self.growth_factor = growth_factor
        self.mac_addresses = []
        self.data = []

    def allocate(self, mac_address):
        if len(self.mac_addresses) < self.max_buffer_size:
            self.mac_addresses.append(mac_address)
            self.data.append([])
        else:
            print("Buffer is full")

    def free(self, index):
        if index < len(self.mac_addresses):
            del self.mac_addresses[index]
            del self.data[index]
        else:
            print("Invalid index")

    def grow(self):
        new_max_buffer_size = int(self.max_buffer_size * self.growth_factor)
        if new_max_buffer_size > 0:
            self.max_buffer_size = new_max_buffer_size
            self.mac_addresses.extend([None] * (new_max_buffer_size - len(self.mac_addresses)))
            self.data.extend([[]] * (new_max_buffer_size - len(self.data)))
        else:
            print("Growth factor is too high")

    def serialize(self, mac_address, data):
        if mac_address in self.mac_addresses:
            index = self.mac_addresses.index(mac_address)
            self.data[index] = data
        else:
            print("MAC address not found")

    def deserialize(self, data):
        mac_address = data[0:6]
        if mac_address in self.mac_addresses:
            index = self.mac_addresses.index(mac_address)
            self.data[index] = data[7:]
        else:
            print("MAC address not found")

    def is_full(self):
        return len(self.mac_addresses) == self.max_buffer_size

    def is_empty(self):
        return len(self.mac_addresses) == 0

    def is_valid(self):
        return self.max_buffer_size > 0 and self.growth_factor > 1.0
