// Define a custom memory management strategy
#define MEM_MANAGEMENT_STRATEGY(T)                  \
    struct T {                                     \
        void *ptr;                                 \
        size_t size;                               \
    };                                             \
                                                   \
    typedef struct T T;                            \
                                                   \
    T malloc(size_t size) {                        \
        T t = {malloc(size), size};                 \
        return t;                                  \
    }                                              \
                                                   \
    void free(T *t) {                              \
        free(t->ptr);                              \
    }                                              \
                                                   \
    T realloc(T *t, size_t new_size) {              \
        t = (T *)realloc(t->ptr, new_size);         \
        t->size = new_size;                         \
        return t;                                  \
    }

// Define the record structure with an int field named value
typedef struct {
    int value;
} record;

// Define the function that manages dynamic memory allocation for multiple arrays and structures under strict operational constraints
void *manage_memory(int n, int m, long min_offset, long max_offset, int min_value, int max_value) {
    // Allocate memory for the offsets array
    T offsets = malloc(n * sizeof(long));
    if (!offsets.ptr) {
        printf("Error: Failed to allocate memory for offsets array\n");
        return NULL;
    }

    // Initialize the keys array with unique sequential integers starting from 0 up to n-1
    int *keys = malloc(n * sizeof(int));
    if (!keys) {
        printf("Error: Failed to allocate memory for keys array\n");
        free(offsets.ptr);
        return NULL;
    }

    // Populate the offsets array with random values within the specified [min_offset, max_offset] range
    srand(time(NULL));
    for (int i = 0; i < n; ++i) {
        offsets.ptr[i] = min_offset + rand() % (max_offset - min_offset + 1);
    }

    // Allocate memory for the records array and initialize each record structure with a random integer within the specified [min_value, max_value] range
    T records = malloc(m * sizeof(record));
    if (!records.ptr) {
        printf("Error: Failed to allocate memory for records array\n");
        free(offsets.ptr);
        free(keys);
        return NULL;
    }
    for (int i = 0; i < m; ++i) {
        record *r = &records.ptr[i];
        r->value = min_value + rand() % (max_value - min_value + 1);
    }

    // Combine the allocated memory into a combined structure for further processing
    void *data = malloc(offsets.size + records.size);
    if (!data) {
        printf("Error: Failed to allocate memory for combined data\n");
        free(offsets.ptr);
        free(keys);
        free(records.ptr);
        return NULL;
    }
    memcpy(data, offsets.ptr, offsets.size);
    memcpy((char *)data + offsets.size, records.ptr, records.size);

    // Release the allocated memory resources
    free(offsets.ptr);
    free(keys);
    free(records.ptr);

    return data;
