// LTE_PHY_RX_FRAME structure
typedef struct {
    int frameNumber;
    float ssi;
    int numSymbols;
    LTE_PHY_RX_SYMBOL symbols[MAX_NUM_SYMBOLS];
} LTE_PHY_RX_FRAME;

// LTE_PHY_RX_SYMBOL structure
typedef struct {
    int modulationType;
    float phaseRotation;
    float noiseVarianceEstimate;
    long timestamp;
} LTE_PHY_RX_SYMBOL;

// NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFlag;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to manage a dynamic array of LTE_PHY_RX_FRAME structures
void manageLTEPhyFrames(LTE_PHY_RX_FRAME* frames, int numFrames) {
    // Update SSI based on recent symbol data
    for (int i = 0; i < numFrames; i++) {
        float ssiSum = 0;
        for (int j = 0; j < frames[i].numSymbols; j++) {
            ssiSum += frames[i].symbols[j].modulationType;
        }
        frames[i].ssi = ssiSum / (float)frames[i].numSymbols;
    }

    // Handle concurrent access from multiple threads
    pthread_mutex_lock(&frameMutex);

    // Add new frames and update existing frames
    for (int i = 0; i < numFrames; i++) {
        int frameIndex = findFrameIndex(frames[i].frameNumber);
        if (frameIndex == -1) {
            // New frame, add it to the array
            int newFrameIndex = numFrames++;
            frames[newFrameIndex] = frames[i];
        } else {
            // Existing frame, update its SSI and symbols
            frames[frameIndex].ssi = frames[i].ssi;
            for (int j = 0; j < frames[i].numSymbols; j++) {
                frames[frameIndex].symbols[j] = frames[i].symbols[j];
            }
        }
    }

    // Handle an array of NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < numFrames; i++) {
        int crcFlag = frames[i].numSymbols % 2 ? 1 : 0;
        for (int j = 0; j < numFrames; j++) {
            if (frames[j].frameNumber == frames[i].frameNumber) {
                frames[j].CRC_INDICATION_REL8_TAG.CRCFlag = crcFlag;
            }
        }
    }

    // Handle concurrent access from multiple threads
    pthread_mutex_unlock(&frameMutex);
}

// Function to add a new frame to the array
void addFrame(LTE_PHY_RX_FRAME* frames, int numFrames, LTE_PHY_RX_FRAME* newFrame) {
    // Handle concurrent access from multiple threads
    pthread_mutex_lock(&frameMutex);

    // Add the new frame to the array
    frames[numFrames++] = *newFrame;

    // Update SSI based on recent symbol data
    float ssiSum = 0;
    for (int i = 0; i < numFrames - 1; i++) {
        ssiSum += frames[i].symbols[frames[i].numSymbols - 1].modulationType;
    }
    frames[numFrames - 1].ssi = ssiSum / (float)frames[numFrames - 1].numSymbols;

    // Handle concurrent access from multiple threads
    pthread_mutex_unlock(&frameMutex);
}

// Function to update an existing frame in the array
void updateFrame(LTE_PHY_RX_FRAME* frames, int numFrames, LTE_PHY_RX_FRAME* updatedFrame) {
    // Handle concurrent access from multiple threads
    pthread_mutex_lock(&frameMutex);

    // Find the frame to update
    int frameIndex = findFrameIndex(updatedFrame->frameNumber);
    if (frameIndex == -1) {
        // Frame not found, do nothing
    } else {
        // Update the SSI and symbols
        frames[frameIndex].ssi = updatedFrame->ssi;
        for (int i = 0; i < numFrames; i++) {
            frames[frameIndex].symbols[i] = updatedFrame->symbols[i];
        }
    }

    // Handle concurrent access from multiple threads
    pthread_mutex_unlock(&frameMutex);
}

// Function to retrieve a frame based on criteria such as SSI or time of reception
LTE_PHY_RX_FRAME* getFrame(LTE_PHY_RX_FRAME* frames, int numFrames, float ssiCriteria) {
    // Handle concurrent access from multiple threads
    pthread_mutex_lock(&frameMutex);

    // Find the frame with the highest SSI above the criteria
    int bestFrameIndex = -1;
    float bestSsi = 0;
    for (int i = 0; i < numFrames; i++) {
        if (frames[i].ssi > ssiCriteria && frames[i].ssi > bestSsi) {
            bestFrameIndex = i;
            bestSsi = frames[i].ssi;
        }
    }

    // Handle concurrent access from multiple threads
    pthread_mutex_unlock(&frameMutex);

    return &frames[bestFrameIndex];
}

// Function to find the index of a frame in the array based on its number
int findFrameIndex(int frameNumber) {
    // Handle concurrent access from multiple threads
    pthread_mutex_lock(&frameMutex);

    for (int i = 0; i < numFrames; i++) {
        if (frames[i].frameNumber == frameNumber) {
            // Frame found, return its index
            int index = i;
            pthread_mutex_unlock(&frameMutex);
            return index;
        }
    }

    // Frame not found, return -1
    pthread_mutex_unlock(&frameMutex);
    return -1;
}

