#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <assert.h>
#include <stdbool.h>
#include <pthread.h>

#define MAX_CRC_INDICATIONS 1000000
#define DEFAULT_CRCFLAG 0
#define MEMORY_POOL_SIZE 524288 // 512KB

typedef struct {
    unsigned int RX_UE_INFORMATION_TAG;
    unsigned short RNTI;
    unsigned char CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash table for efficient lookups of unique RX_UE_INFORMATION_TAG values
typedef struct {
    int key;
    int value;
} hashTable;

// Memory pool for reusing memory blocks
typedef struct {
    void* data;
    size_t size;
} memPool;

// Thread-safe lock for protecting critical sections of code
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void initializeHashTable(hashTable** table, int capacity) {
    // Allocate memory for the hash table and set its size
    *table = (hashTable*) malloc(capacity * sizeof(hashTable));
    memset(*table, 0, capacity * sizeof(hashTable));
}

void initializeMemoryPool(memPool** pool) {
    // Allocate memory for the memory pool and set its size
    *pool = (memPool*) malloc(MEMORY_POOL_SIZE);
    memset(*pool, 0, MEMORY_POOL_SIZE);
}

void allocateCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T** pdu) {
    // Allocate memory for the CRC indication PDU using a memory pool
    *pdu = (NFAPI_CRC_INDICATION_PDU_T*) malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memset(*pdu, 0, sizeof(NFAPI_CRC_INDICATION_PDU_T));
}

void freeCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T* pdu) {
