void insertHashTable(hashTable** table, int key, int value) {
    // Insert a new entry into the hash table
    (*table)[key].key = key;
    (*table)[key].value = value;
}

int findHashTable(hashTable* table, int key) {
    // Find an existing entry in the hash table or return -1 if not found
    for (int i = 0; i < MAX_CRC_INDICATIONS; i++) {
        if (table[i].key == key) {
            return i;
        }
    }
    return -1;
}

void* allocateMemoryPool(memPool* pool, size_t size) {
    // Allocate memory from the memory pool for a given size
    void* data = (void*) malloc(size);
    memset(data, 0, size);
    return data;
}

void freeMemoryPool(memPool* pool, void* data, size_t size) {
    // Free the memory allocated from the memory pool for a given size
    free(data);
}

int addCRCIndicationPDU(NFAPI_CRC_INDICATION_PDU_T** list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Add a new CRC indication PDU to the list, return 0 on success and -1 on failure
    if (*list == NULL) {
        initializeMemoryPool(list);
    }
    if ((*list)->size >= MAX_CRC_INDICATIONS) {
        // Return error if the memory pool is full
        return -1;
    }
    int index = findHashTable(*list, pdu->RX_UE_INFORMATION_TAG);
    if (index == -1) {
        // If the RX_UE_INFORMATION_TAG is not in the hash table, add it and set its value to 0
        insertHashTable(*list, pdu->RX_UE_INFORMATION_TAG, 0);
    } else {
        // Increment the value of the existing RX_UE_INFORMATION_TAG in the hash table
        (*list)[index].value++;
    }
    allocateMemoryPool(*list, size);
    memcpy((*list)->data + (*list)->size * sizeof(NFAPI_CRC_INDICATION_PDU_T), pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*list)->size++;
    return 0;
}

