    // Remove a CRC indication PDU from the list by index, return 0 on success and -1 on failure
    if (index < 0 || index >= (*list)->size) {
        // Return error if the index is out of bounds
        return -1;
    }
    freeMemoryPool(*list, (*list)->data + index * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    memcpy((*list)->data + index * sizeof(NFAPI_CRC_INDICATION_PDU_T), (*list)->data + ((*list)->size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T), sizeof(NFAPI_CRC_INDICATION_PDU_T));
    (*list)->size--;
    return 0;
}

int clearCRCIndicationList(NFAPI_CRC_INDICATION_PDU_T** list) {
