#include <pthread.h>

// Custom message structure
struct Message {
    int payload_type;
    time_t timestamp;
    long sequence_number;
};

// Dynamic array of messages
struct MessageArray {
    struct Message* messages;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock; // Mutex for thread safety
};

// Initializes the message array with a given capacity
void init_message_array(struct MessageArray* msg_arr, size_t capacity) {
    msg_arr->messages = malloc(capacity * sizeof(struct Message));
    if (msg_arr->messages == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    msg_arr->capacity = capacity;
    msg_arr->size = 0;
    pthread_mutex_init(&msg_arr->lock, NULL);
}

// Adds a new message with the given payload type and timestamp to the array
void add_message(struct MessageArray* msg_arr, int payload_type, time_t timestamp) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&msg_arr->lock);

    // Increment the sequence number and store it in the new message
    long seq_num = msg_arr->size + 1;

    // Allocate memory for the new message
    struct Message* new_msg = malloc(sizeof(struct Message));
    if (new_msg == NULL) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }

    // Initialize the new message with the given payload type and timestamp
    new_msg->payload_type = payload_type;
    new_msg->timestamp = timestamp;
    new_msg->sequence_number = seq_num;

    // Add the new message to the array
    msg_arr->messages[msg_arr->size++] = *new_msg;

    // Unlock the mutex
    pthread_mutex_unlock(&msg_arr->lock);
}

// Searches for a message with the given timestamp in the array and returns its index, or -1 if not found
int search_message(struct MessageArray* msg_arr, time_t timestamp) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&msg_arr->lock);

    // Iterate through the messages and compare their timestamps with the given one
    for (size_t i = 0; i < msg_arr->size; i++) {
        if (msg_arr->messages[i].timestamp == timestamp) {
            pthread_mutex_unlock(&msg_arr->lock);
            return i;
        }
    }

    // If the message is not found, unlock the mutex and return -1
    pthread_mutex_unlock(&msg_arr->lock);
    return -1;
}

// Main function for testing the message array
int main() {
    struct MessageArray msg_arr = {0};
    init_message_array(&msg_arr, 10); // Initialize with capacity of 10 messages

    add_message(&msg_arr, 12345, time(NULL)); // Add a message with payload type 12345 and current timestamp
    add_message(&msg_arr, 67890, time(NULL) + 1); // Add another message with payload type 67890 and one second later timestamp
    add_message(&msg_arr, 12345, time(NULL) - 1); // Add a third message with the same payload type and one second earlier timestamp

    int index = search_message(&msg_arr, time(NULL)); // Search for the first message with current timestamp
    printf("Index of first message with current timestamp: %d\n", index);

    return 0;
}
```
