    size_t size;                      // Current number of elements in the hash table
    double loadFactor;               // Load factor threshold for resizing
    mac_context_t* entries[];        // Array of hash table entries
} mac_hash_table_t;

// Define the custom hash function for SCTP stream IDs
static uint32_t sctpStreamHash(uint32_t stream) {
    return stream % (UINT32_MAX + 1);
}

// Define the hash table initialization function
void mac_hash_table_init(mac_hash_table_t* table, size_t capacity) {
    // Initialize the hash table with the specified capacity
    table->capacity = capacity;
    table->size = 0;
    table->loadFactor = 0.5; // Load factor threshold for resizing
    table->entries = (mac_context_t**)malloc(sizeof(mac_context_t*) * capacity);
}

// Define the hash table lookup function
mac_context_t* mac_hash_table_lookup(mac_hash_table_t* table, uint32_t stream) {
    // Calculate the index of the entry in the hash table using the custom hash function
    size_t index = sctpStreamHash(stream) % table->capacity;

    // Loop through the chain of entries at the calculated index until a matching stream ID is found
    while (table->entries[index] != NULL && table->entries[index]->stream != stream) {
        index = (index + 1) % table->capacity;
    }

    // If a matching entry is found, return the context associated with it
    if (table->entries[index] != NULL) {
        return table->entries[index];
    } else {
        return NULL;
    }
}

