    // Calculate the index of the entry in the hash table using the custom hash function
    size_t index = sctpStreamHash(stream) % table->capacity;

    // If the load factor exceeds the specified threshold, resize the hash table
    if (table->size / (double)table->capacity > table->loadFactor) {
        mac_hash_table_resize(table);
    }

    // Allocate a new entry for the given stream ID and context
    mac_context_t* newEntry = (mac_context_t*)malloc(sizeof(mac_context_t));
    if (newEntry == NULL) {
        return false;
    }
    newEntry->stream = stream;
    newEntry->pdcpEntityId = pdcpEntityId;
    newEntry->llcEntityId = llcEntityId;

    // Insert the entry into the hash table at the calculated index, preserving the chain of entries
    while (table->entries[index] != NULL) {
        index = (index + 1) % table->capacity;
    }
    table->entries[index] = newEntry;
    table->size++;

    return true;
}

// Define the hash table deletion function
bool mac_hash_table_delete(mac_hash_table_t* table, uint32_t stream) {
    // Calculate the index of the entry in the hash table using the custom hash function
    size_t index = sctpStreamHash(stream) % table->capacity;

    // Loop through the chain of entries at the calculated index until a matching stream ID is found
    while (table->entries[index] != NULL && table->entries[index]->stream != stream) {
        index = (index + 1) % table->capacity;
    }

    // If a matching entry is found, delete it from the hash table and free its memory
    if (table->entries[index] != NULL) {
        mac_context_t* deletedEntry = table->entries[index];
        table->entries[index] = NULL;
        table->size--;
        free(deletedEntry);
        return true;
    } else {
        return false;
    }
}

// Define the hash table resizing function
void mac_hash_table_resize(mac_hash_table_t* table) {
    // Calculate the new capacity of the hash table based on the current size and load factor
    size_t newCapacity = (size_t)(table->size / table->loadFactor);

    // Allocate a new array for the entries in the resized hash table
    mac_context_t** newEntries = (mac_context_t**)malloc(sizeof(mac_context_t*) * newCapacity);
    if (newEntries == NULL) {
        return;
    }

    // Copy all entries from the original hash table to the resized one
    for (size_t i = 0; i < table->capacity; i++) {
        while (table->entries[i] != NULL) {
            size_t newIndex = sctpStreamHash(table->entries[i]->stream) % newCapacity;
            while (newEntries[newIndex] != NULL) {
                newIndex = (newIndex + 1) % newCapacity;
            }
            newEntries[newIndex] = table->entries[i];
        }
    }

    // Free the original array of entries and replace it with the new one
    free(table->entries);
    table->entries = newEntries;
    table->capacity = newCapacity;
}
