// Define the dynamic array of records
typedef struct {
    Record* records;
    int count;
    int capacity;
    pthread_mutex_t mutex;
} DynamicArray;

// Define the memory allocation thresholds
#define MEMORY_ALLOCATION_THRESHOLD 1024 * 1024 * 8 // 8 MB
#define MAX_LOGGING_FREQUENCY 1000 // Log every second

// Define the memory allocation function
void* allocateMemory(size_t size) {
    void* ptr = malloc(size);
    assert(ptr != NULL);
    return ptr;
}

// Define the function to initialize the dynamic array
DynamicArray initDynamicArray() {
    DynamicArray arr;
    arr.records = NULL;
    arr.count = 0;
    arr.capacity = 0;
    pthread_mutex_init(&arr.mutex, NULL);
    return arr;
}

// Define the function to resize the dynamic array
void resizeDynamicArray(DynamicArray* arr) {
    // Check if the current capacity is greater than the memory allocation threshold
    if (arr->capacity > MEMORY_ALLOCATION_THRESHOLD) {
        // Double the capacity of the dynamic array
        arr->capacity *= 2;
    }
    // Reallocate memory for the records
    arr->records = realloc(arr->records, arr->capacity * sizeof(Record));
}

// Define the function to add a record to the dynamic array
void addRecord(DynamicArray* arr, int value) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&arr->mutex);
    // Check if the current capacity is greater than the number of allocated records
    if (arr->count >= arr->capacity) {
        // Resize the dynamic array
        resizeDynamicArray(arr);
    }
    // Allocate memory for the record
    Record* record = allocateMemory(sizeof(Record));
    record->value = value;
    record->offset = NULL;
    // Add the record to the dynamic array
    arr->records[arr->count++] = *record;
    pthread_mutex_unlock(&arr->mutex);
}

// Define the function to remove a record from the dynamic array
void removeRecord(DynamicArray* arr, int index) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&arr->mutex);
    // Check if the index is valid
    if (index >= 0 && index < arr->count) {
        // Free the memory of the record
        free(arr->records[index].offset);
        // Shift all records after the specified index to fill the gap
        for (int i = index + 1; i < arr->count; i++) {
            arr->records[i - 1] = arr->records[i];
        }
        // Decrement the number of allocated records
        arr->count--;
    }
    pthread_mutex_unlock(&arr->mutex);
}

// Define the function to get a record from the dynamic array
Record* getRecord(DynamicArray* arr, int index) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&arr->mutex);
    // Check if the index is valid
    if (index >= 0 && index < arr->count) {
        Record* record = &(arr->records[index]);
        pthread_mutex_unlock(&arr->mutex);
        return record;
    }
    pthread_mutex_unlock(&arr->mutex);
    return NULL;
}

// Define the function to log the memory usage, number of allocated records, and average size of each record to a file
void logMemoryUsage(DynamicArray* arr) {
    // Lock the mutex to ensure thread safety
    pthread_mutex_lock(&arr->mutex);
    // Calculate the total memory usage
    long total_memory = (long)(sizeof(Record) * arr->count);
    // Calculate the average size of each record
    float average_record_size = 0;
    if (arr->count > 0) {
        average_record_size = (float)(total_memory / arr->count);
