void resize_dynamic_array(DYNAMIC_ARRAY *array, int new_capacity) {
    NFAPI_CRC_INDICATION_PDU_T *new_records = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * new_capacity);
    memcpy(new_records, array->records, sizeof(NFAPI_CRC_INDICATION_PDU_T) * array->size);
