struct crc_indication_data {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
};

typedef struct {
    int queue_size; // Number of CRC indications in the queue
    int head;       // Index of the first element in the queue
    int tail;       // Index of the next free slot in the queue
    struct crc_indication_data *queue;
} crc_indication_queue_t;

struct nfapi_crc_indication_pdu {
    uint16_t rx_ue_information_tag;
    uint32_t rnti;
    uint8_t crc_indication_rel8_tag;
};

// Function to manage and transmit a list of NFAPI_CRC_INDICATION_PDU_T structures over a network interface, ensuring thread safety and efficient memory usage.
int transmit_crc_indications(struct nfapi_crc_indication_pdu *indications, int num_indications) {
    // Create a queue to store the CRC indications
    crc_indication_queue_t *queue = malloc(sizeof(crc_indication_queue_t));
    queue->queue_size = num_indications;
    queue->head = 0;
    queue->tail = 0;
    queue->queue = malloc(num_indications * sizeof(struct crc_indication_data));

    // Initialize the CRC indications in the queue with the input data
    for (int i = 0; i < num_indications; i++) {
        queue->queue[i].rx_ue_information_tag = indications[i].rx_ue_information_tag;
        queue->queue[i].rnti = indications[i].rnti;
        queue->queue[i].crc_indication_rel8_tag = indications[i].crc_indication_rel8_tag;
    }

    // Create a semaphore to synchronize access to the queue
    sem_t *semaphore = malloc(sizeof(sem_t));
    sem_init(semaphore, 0, 1);

    // Create a thread to transmit the CRC indications
    pthread_t tx_thread;
    int rc = pthread_create(&tx_thread, NULL, (void *(*)(void *))transmit_queue, (void *)queue);
    if (rc) {
        printf("Error creating thread for CRC transmission\n");
        return -1;
    }

    // Wait for the transmit thread to complete before freeing resources
    pthread_join(tx_thread, NULL);
    sem_destroy(semaphore);
    free(queue->queue);
    free(queue);

    return 0;
}

// Function to transmit a queue of CRC indications over a network interface, ensuring thread safety and efficient memory usage.
void *transmit_queue(void *arg) {
    crc_indication_queue_t *queue = (crc_indication_queue_t *)arg;

    // Loop until the queue is empty
    while (1) {
        // Acquire the semaphore to synchronize access to the queue
        sem_wait(semaphore);

        // Check if the queue is empty
        if (queue->head == queue->tail) {
            break;
        }

        // Get the next element in the queue and transmit it over the network interface
        struct crc_indication_data *data = &queue->queue[queue->head];
        int rc = send_crc_indication(data);
        if (rc < 0) {
            printf("Error transmitting CRC indication\n");
        } else {
            // Increment the head index to free the slot in the queue
            queue->head++;
            if (queue->head == queue->tail) {
                break;
            }
        }

        sem_post(semaphore);
    }

    return NULL;
}

// Function to send a single CRC indication over the network interface, ensuring thread safety and efficient memory usage.
int send_crc_indication(struct crc_indication_data *data) {
    // Validate the input data before sending it over the network
    if (!validate_crc_indication(data)) {
        printf("Invalid CRC indication data\n");
        return -1;
    }

    // Create a buffer to hold the CRC indication data
    char *buffer = malloc(sizeof(struct nfapi_crc_indication) + sizeof(data->rnti));

    // Populate the buffer with the CRC indication data
    struct nfapi_crc_indication *indication = (struct nfapi_crc_indication *)buffer;
    indication->rx_ue_information_tag = data->rx_ue_information_tag;
    indication->rnti = data->rnti;
    indication->crc_indication_rel8_tag = data->crc_indication_rel8_tag;

    // Send the CRC indication over the network interface
    int rc = send(socket, buffer, sizeof(struct nfapi_crc_indication) + sizeof(data->rnti), 0);
    if (rc < 0) {
        printf("Error sending CRC indication\n");
        free(buffer);
        return -1;
    }

    // Free the buffer and return successfully
    free(buffer);
    return 0;
}

// Function to validate a single CRC indication data structure, ensuring thread safety and efficient memory usage.
int validate_crc_indication(struct crc_indication_data *data) {
    // Check if the RX UE information tag is valid
    if (data->rx_ue_information_tag < 1 || data->rx_ue_information_tag > MAX_RX_UE_INFORMATION_TAG) {
        return -1;
    }

    // Check if the RNTI is valid
    if (data->rnti < MIN_RNTI || data->rnti > MAX_RNTI) {
        return -1;
    }

    // Check if the CRC indication REL8 tag is valid
    if (data->crc_indication_rel8_tag < 1 || data->crc_indication_rel8_tag > MAX_CRC_INDICATION_REL8_TAG) {
        return -1;
    }

    // Return successfully if all checks passed
    return 0;
}
