#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/ipc.h>
#include <sys/shm.h>

// Define the record structure to store in the dynamic array
typedef struct {
    int value;
    long offset;
} Record;

// Define the NFAPI_CRC_INDICATION_PDU_T structure
typedef struct {
    RX_UE_INFORMATION_TAG RX_UE_INFORMATION_TAG;
    RNTI RNTI;
    CRC_INDICATION_REL8_TAG CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array to store the records
typedef struct {
    int size;
    Record* records[];
} DynamicArray;

// Initialize the dynamic array with a predefined threshold
void initDynamicArray(DynamicArray* array, int threshold) {
    // Allocate memory for the dynamic array
    array->records = malloc(sizeof(Record) * threshold);

    // Set the initial size of the dynamic array
    array->size = 0;
}

// Add a new record to the dynamic array and resize it if necessary
void addRecordToDynamicArray(DynamicArray* array, int value, long offset) {
    // Check if the dynamic array needs to be resized
    if (array->size >= threshold) {
        // Double the size of the dynamic array
        DynamicArray* newArray = realloc(array, sizeof(Record) * 2 * array->size);

        // If the resize was successful, update the pointer and size
        if (newArray != NULL) {
            array = newArray;
            array->size *= 2;
        } else {
            // If the resize failed, print an error message
            printf("Error: Could not resize dynamic array\n");
            return;
        }
    }

    // Add a new record to the end of the dynamic array
    array->records[array->size].value = value;
    array->records[array->size].offset = offset;
    array->size++;
}

// Remove a record from the dynamic array and resize it if necessary
void removeRecordFromDynamicArray(DynamicArray* array, int index) {
    // Check if the dynamic array needs to be resized
    if (array->size < threshold / 2) {
        // Half the size of the dynamic array
        DynamicArray* newArray = realloc(array, sizeof(Record) * threshold / 2);

        // If the resize was successful, update the pointer and size
        if (newArray != NULL) {
            array = newArray;
            array->size /= 2;
        } else {
            // If the resize failed, print an error message
            printf("Error: Could not resize dynamic array\n");
            return;
        }
    }

    // Remove the record at the specified index from the dynamic array
    for (int i = index + 1; i < array->size; i++) {
        array->records[i - 1].value = array->records[i].value;
        array->records[i - 1].offset = array->records[i].offset;
    }

    // Decrement the size of the dynamic array by 1
    array->size--;
}

// Populate the dynamic array with instances of NFAPI_CRC_INDICATION_PDU_T structures
void populateDynamicArray(DynamicArray* array) {
    // Initialize the dynamic array with a predefined threshold
    initDynamicArray(array, 10);

    // Iterate over the external data source and add records to the dynamic array
    for (int i = 0; i < 10; i++) {
        // Create a new record
        Record* record = malloc(sizeof(Record));

        // Set the values of the record
        record->value = i;
        record->offset = rand() % 10;

        // Add the record to the dynamic array
        addRecordToDynamicArray(array, record);
    }
}

// Free the memory allocated for the dynamic array
void freeDynamicArray(DynamicArray* array) {
    // Free the memory allocated for each record in the dynamic array
    for (int i = 0; i < array->size; i++) {
        free(array->records[i]);
    }

    // Free the memory allocated for the dynamic array itself
    free(array);
}

// Function to manage a dynamic array of record structures, with thread safety and efficient data structures
void dynamicArrayManager(DynamicArray* array) {
    // Define a mutex lock to prevent concurrent access from multiple threads
    pthread_mutex_t mutex;

    // Initialize the mutex lock
    pthread_mutex_init(&mutex, NULL);

    // Loop indefinitely while the dynamic array is not empty
    while (array->size > 0) {
        // Acquire a lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if the dynamic array needs to be resized
        if (array->size >= threshold) {
            // Double the size of the dynamic array
            DynamicArray* newArray = realloc(array, sizeof(Record) * 2 * array->size);

            // If the resize was successful, update the pointer and size
            if (newArray != NULL) {
                array = newArray;
                array->size *= 2;
            } else {
                // If the resize failed, print an error message
                printf("Error: Could not resize dynamic array\n");
                return;
            }
        }

        // Add a new record to the end of the dynamic array
        array->records[array->size].value = i;
        array->records[array->size].offset = rand() % 10;
        array->size++;

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }
}

// Function to track and report any memory leaks or invalid pointer dereferences during runtime
void memoryLeakTracker(DynamicArray* array) {
    // Define a mutex lock to prevent concurrent access from multiple threads
    pthread_mutex_t mutex;

    // Initialize the mutex lock
    pthread_mutex_init(&mutex, NULL);

    // Loop indefinitely while the dynamic array is not empty
    while (array->size > 0) {
        // Acquire a lock on the mutex
        pthread_mutex_lock(&mutex);

        // Check if any records have been removed from the dynamic array
        for (int i = 0; i < array->size; i++) {
            if (array->records[i] == NULL) {
                printf("Error: Memory leak detected\n");
                return;
            }
        }

        // Release the lock on the mutex
        pthread_mutex_unlock(&mutex);
    }
}

// Function to populate the dynamic array with instances of NFAPI_CRC_INDICATION_PDU structures
void populateDynamicArray(DynamicArray* array) {
    // Initialize the dynamic array with a predefined threshold
    initDynamicArray(array, 10);

    // Iterate over the external data source and add records to the dynamic array
    for (int i = 0; i < 10; i++) {
        // Create a new record
        Record* record = malloc(sizeof(Record));

        // Set the values of the record
        record->value = i;
        record->offset = rand() % 10;

        // Add the record to the dynamic array
        addRecordToDynamicArray(array, record);
    }
}

// Function to free the memory allocated for the dynamic array
void freeDynamicArray(DynamicArray* array) {
    // Free the memory allocated for each record in the dynamic array
    for (int i = 0; i < array->size; i++) {
        free(array->records[i]);
    }

    // Free the memory allocated for the dynamic array itself
    free(array);
}
