// Define the structure for the records in the array
typedef struct record {
    int value;
    long *offset;
} record_t;

// Define the structure for the dynamic array
typedef struct {
    size_t capacity;
    size_t count;
    record_t **records;
} dynamic_array_t;

// Function to initialize the dynamic array
void init_dynamic_array(dynamic_array_t *array) {
    // Initialize the array with a default capacity of 100 records
    array->capacity = 100;
    array->count = 0;
    array->records = (record_t **)malloc(sizeof(record_t *) * array->capacity);
}

// Function to resize the dynamic array when it exceeds the predefined threshold
void resize_dynamic_array(dynamic_array_t *array, size_t new_size) {
    // Reallocate the records array with a new capacity of new_size
    array->capacity = new_size;
    array->records = (record_t **)realloc(array->records, sizeof(record_t *) * array->capacity);
}

// Function to insert a record into the dynamic array
void insert_record(dynamic_array_t *array, int value, long offset) {
    // Check if the array needs to be resized
    if (array->count == array->capacity) {
        resize_dynamic_array(array, 2 * array->capacity);
    }

    // Create a new record and set its value and offset
    record_t *new_record = (record_t *)malloc(sizeof(record_t));
    new_record->value = value;
    new_record->offset = &offset;

    // Insert the new record into the array
    array->records[array->count++] = new_record;
}

// Function to delete a record from the dynamic array
void delete_record(dynamic_array_t *array, int value) {
    // Find the index of the record with the specified value
    size_t index = 0;
    for (size_t i = 0; i < array->count; i++) {
        if (array->records[i]->value == value) {
            index = i;
            break;
        }
    }

    // Delete the record from the array
    free(array->records[index]);
    array->count--;

    // Shift the records in the array to maintain their order
    for (size_t i = index; i < array->count; i++) {
        array->records[i] = array->records[i + 1];
    }
}

// Function to query the current state of the dynamic array
void query_array(dynamic_array_t *array) {
    // Print the number of active records and the total memory consumption
    printf("Number of active records: %zu\n", array->count);
    printf("Total memory consumption: %zu bytes\n", sizeof(record_t *) * array->capacity);
}

// Function to periodically archive old records beyond a certain age threshold
void archive_old_records(dynamic_array_t *array, int age_threshold) {
    // Iterate over the records in the array and delete those that are older than the threshold
    for (size_t i = 0; i < array->count; i++) {
        if (array->records[i]->value < age_threshold) {
            delete_record(array, array->records[i]->value);
        }
    }
}
