#include <iostream>
#include <vector>
#include <string>
#include <cstdlib>
#include <cassert>
#include <memory>

struct record {
  char* buffer;
  size_t length;
};

class DynamicArray {
 private:
  std::vector<record> data_;
  std::string error_;

 public:
  explicit DynamicArray(size_t initialSize) : data_(initialSize) {}

  ~DynamicArray() { clear(); }

  bool init(size_t size) {
    if (data_.size() < size) {
      try {
        data_.resize(size);
      } catch (const std::bad_alloc& e) {
        error_ = e.what();
        return false;
      }
    }
    for (auto& record : data_) {
      record.buffer = new char[record.length];
      if (record.buffer == nullptr) {
        error_ = "Failed to allocate memory";
        return false;
      }
    }
    return true;
  }

  void clear() {
    for (auto& record : data_) {
      delete[] record.buffer;
    }
    data_.clear();
  }

  size_t size() const { return data_.size(); }

  bool push(const int value) {
    if (data_.size() == 0) {
      error_ = "Array is empty";
      return false;
    }
    try {
      data_.emplace_back(record{new char[sizeof(int)], sizeof(int)});
      memcpy(data_.back().buffer, &value, sizeof(int));
    } catch (const std::bad_alloc& e) {
      error_ = e.what();
      return false;
    }
    return true;
  }

  int pop() {
    if (data_.size() == 0) {
      error_ = "Array is empty";
      return -1;
    }
    int value = *reinterpret_cast<int*>(data_.back().buffer);
    delete[] data_.back().buffer;
    data_.pop_back();
    return value;
  }

  std::string error() const { return error_; }
};

int main() {
  // Initialize the dynamic array with an initial size of 10 records
  DynamicArray arr(10);

  // Check if the initialization was successful
  if (!arr.init(10)) {
    std::cerr << "Error: " << arr.error() << std::endl;
    return -1;
  }

  // Push values to the dynamic array
  for (int i = 0; i < 5; ++i) {
    if (!arr.push(i)) {
      std::cerr << "Error: " << arr.error() << std::endl;
      return -1;
    }
  }

  // Print the values in the dynamic array
  for (auto& record : arr) {
    int value = *reinterpret_cast<int*>(record.buffer);
    std::cout << value << " ";
  }
  std::cout << std::endl;

  // Pop a value from the dynamic array
  int popped = arr.pop();
  if (popped == -1) {
    std::cerr << "Error: " << arr.error() << std::endl;
    return -1;
  }
  std::cout << "Popped value: " << popped << std::endl;

  // Clear the dynamic array
  arr.clear();

  return 0;
}']

