#include <stdio.h>
#include <assert.h>

// Enum representing the type of file system entry (directory or file)
typedef enum {
    DIRECTORY,
    FILE
} EntryType;

// Structure representing a file system entry
typedef struct {
    char *name;     // Name of the entry
    EntryType type; // Type of the entry (directory/file)
    unsigned long size;   // Size of the entry (in bytes)
} FileSystemEntry;

// Structure representing a collection of file system entries
typedef struct {
    int numEntries;           // Number of entries in the collection
    FileSystemEntry *entries; // Array of file system entries
} FileSystemCollection;

// Function to add a new entry to the collection
void addEntry(FileSystemCollection *collection, const char *name, EntryType type, unsigned long size) {
    assert(collection != NULL);
    assert(name != NULL);

    // Reallocate memory for the entries array if necessary
    if (collection->numEntries == collection->entries->size) {
        int newSize = collection->entries->size * 2;
        FileSystemEntry *newEntries = realloc(collection->entries, sizeof(FileSystemEntry) * newSize);
        if (newEntries == NULL) {
            // Handle memory allocation failure gracefully by returning an error code
            return;
        }
        collection->entries = newEntries;
    }

    // Add the new entry to the array
    collection->entries[collection->numEntries].name = strdup(name);
    collection->entries[collection->numEntries].type = type;
    collection->entries[collection->numEntries].size = size;
    collection->numEntries++;
}

// Function to retrieve an entry by name from the collection
FileSystemEntry *getEntry(FileSystemCollection *collection, const char *name) {
    assert(collection != NULL);
    assert(name != NULL);

    for (int i = 0; i < collection->numEntries; i++) {
        if (strcmp(collection->entries[i].name, name) == 0) {
            return &collection->entries[i];
        }
    }

    // If the entry is not found, return NULL
    return NULL;
}

// Function to list all entries in the collection
void listEntries(FileSystemCollection *collection) {
    assert(collection != NULL);

    for (int i = 0; i < collection->numEntries; i++) {
        printf("%s %d\n", collection->entries[i].name, collection->entries[i].size);
    }
}

// Function to traverse the collection in a depth-first manner
void traverseCollection(FileSystemCollection *collection) {
    assert(collection != NULL);

    for (int i = 0; i < collection->numEntries; i++) {
        printf("%s\n", collection->entries[i].name);
        if (collection->entries[i].type == DIRECTORY) {
            traverseCollection(&collection->entries[i]);
        }
    }
}

// Function to free all allocated memory upon request
void freeEntries(FileSystemCollection *collection) {
    assert(collection != NULL);

    for (int i = 0; i < collection->numEntries; i++) {
        free(collection->entries[i].name);
    }
    free(collection->entries);
}
