    if (size > MAX_SIZE || array == NULL) {
        printf("Error: Invalid input parameters\n");
        return;
    }

    /* Initialize the mutex for protecting the array */
    pthread_mutex_lock(&lock);

    /* Allocate memory for the NAS messages */
    LTE_NAS_Message_T **messages = (LTE_NAS_Message_T**)malloc(size * sizeof(LTE_NAS_Message_T*));
    if (messages == NULL) {
