// Structure for UE context data
typedef struct {
    long imsi;
    int rnti;
    int pdu_session_id;
} UEContext;

// Function to populate the UE context array with random values
int populateUEContextArray(UEContext* ueContexts, int numUeContexts) {
    // Initialize random seed for reproducibility
    srand(time(NULL));

    // Loop through each UE context and generate unique IMSI, RNTI, and PDU session ID
    for (int i = 0; i < numUeContexts; i++) {
        ueContexts[i].imsi = rand() % 1000000000;
        ueContexts[i].rnti = rand() % 65535;
        ueContexts[i].pdu_session_id = rand() % 4096;
    }

    return numUeContexts;
}

// Function to load initial context data from CSV file
int loadInitialContextData(char* csvFile, UEContext* ueContexts) {
    // Open CSV file for reading
    FILE* fp = fopen(csvFile, "r");
    if (fp == NULL) {
        printf("Error: Could not open CSV file %s\n", csvFile);
        return -1;
    }

    // Read CSV header line and skip it
    char* line = NULL;
    size_t len = 0;
    ssize_t read = getline(&line, &len, fp);
    if (read == -1) {
        printf("Error: Could not read CSV file %s\n", csvFile);
        fclose(fp);
        return -1;
    }

    // Read each line in the CSV file and populate UE context array with data
    int i = 0;
    while ((read = getline(&line, &len, fp)) != -1) {
        char* token = strtok(line, ",");
        if (token == NULL) {
            printf("Error: Could not parse CSV file %s\n", csvFile);
            fclose(fp);
            return -1;
        }
        ueContexts[i].imsi = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Could not parse CSV file %s\n", csvFile);
            fclose(fp);
            return -1;
        }
        ueContexts[i].rnti = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            printf("Error: Could not parse CSV file %s\n", csvFile);
            fclose(fp);
            return -1;
        }
        ueContexts[i].pdu_session_id = atoi(token);
        i++;
    }

    // Close CSV file and return number of UE contexts loaded
    fclose(fp);
    return i;
}

// Function to handle memory allocation failures during population or loading
void handleMemoryAllocationError() {
    printf("Error: Memory allocation failed\n");
    exit(-1);
}

int main() {
    // Declare UE context array with 10,000 entries
    UEContext ueContexts[10000];

    // Populate the UE context array with random values for testing purposes
    int numUeContexts = populateUEContextArray(ueContexts, 10000);

