    char* csvFile = "initial_context_data.csv";
    int numInitialContextsLoaded = loadInitialContextData(csvFile, ueContexts);

    // Check for memory allocation failures during population or loading
    if (numUeContexts < 0 || numInitialContextsLoaded < 0) {
        handleMemoryAllocationError();
    }

    // Print the populated UE context array to console for debugging purposes
    printf("Populated UE context array: \n");
    for (int i = 0; i < numUeContexts; i++) {
        printf("%ld, %d, %d\n", ueContexts[i].imsi, ueContexts[i].rnti, ueContexts[i].pdu_session_id);
