struct phy_rx_frame {
    FRAME_TYPE type;
    SUBFRAME_INDEX subframe_index;
    CHANNEL_QUALITY_INFO quality_info;
    SINR_VALUE sinr_value;
};

// Define a hash table to store the information about each unique subframe index
struct subframe_table {
    int count;
    struct phy_rx_frame* frames[MAX_STRUCTURES];
};

// Define a linked list to store the allocated structures
struct structure_list {
    int count;
    struct phy_rx_frame* head;
    struct phy_rx_frame* tail;
};

// Define a mutex and condition variable for synchronizing access to the list
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

// Define a flag to indicate whether the list is currently being cleared
volatile int clearing = 0;

// Define a function to initialize the structure list and hash table
void init_list(struct structure_list* list, struct subframe_table* table) {
    // Initialize the list and hash table with default values
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
    table->count = 0;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        table->frames[i] = NULL;
    }
}

// Define a function to add a new structure to the list
void add_structure(struct structure_list* list, struct phy_rx_frame* frame) {
    // Acquire the lock and wait for permission to modify the list
    pthread_mutex_lock(&lock);
    while (clearing) {
        pthread_cond_wait(&cond, &lock);
    }

    // Check if the maximum number of structures has been reached
    if (list->count >= MAX_STRUCTURES) {
        // If so, release the lock and return without modifying the list
        pthread_mutex_unlock(&lock);
        return;
    }

    // Add the new structure to the list and increment the count
    frame->next = NULL;
    if (list->head == NULL) {
        list->head = frame;
        list->tail = frame;
    } else {
        list->tail->next = frame;
        list->tail = frame;
    }
    list->count++;

    // Release the lock and signal any waiting threads to continue
    pthread_mutex_unlock(&lock);
    pthread_cond_broadcast(&cond);
}

// Define a function to remove a structure from the list
void remove_structure(struct structure_list* list, struct phy_rx_frame* frame) {
    // Acquire the lock and wait for permission to modify the list
    pthread_mutex_lock(&lock);
    while (clearing) {
        pthread_cond_wait(&cond, &lock);
    }

    // Check if the structure is already removed from the list
    if (frame->next == NULL) {
        // If so, release the lock and return without modifying the list
        pthread_mutex_unlock(&lock);
        return;
    }

    // Remove the structure from the list and decrement the count
    struct phy_rx_frame* prev = NULL;
    struct phy_rx_frame* curr = list->head;
    while (curr != frame) {
        prev = curr;
        curr = curr->next;
    }
    if (prev == NULL) {
        list->head = curr->next;
    } else {
        prev->next = curr->next;
    }
    list->count--;

    // Release the lock and signal any waiting threads to continue
    pthread_mutex_unlock(&lock);
    pthread_cond_broadcast(&cond);
}

// Define a function to retrieve a structure from the list
struct phy_rx_frame* get_structure(struct structure_list* list, SUBFRAME_INDEX subframe_index) {
    // Acquire the lock and wait for permission to access the list
    pthread_mutex_lock(&lock);
    while (clearing) {
        pthread_cond_wait(&cond, &lock);
    }

    // Check if the subframe index is unique and in the hash table
    int found = 0;
    struct phy_rx_frame* frame = list->head;
    while (frame != NULL) {
        if (frame->subframe_index == subframe_index) {
            found = 1;
            break;
        }
        frame = frame->next;
    }
    if (!found) {
        // If not, release the lock and return NULL
        pthread_mutex_unlock(&lock);
        return NULL;
    }

    // Retrieve the structure from the list and increment its count
    frame->count++;

    // Release the lock and signal any waiting threads to continue
    pthread_mutex_unlock(&lock);
    pthread_cond_broadcast(&cond);

    return frame;
}

// Define a function to clear the list and hash table
void clear_list(struct structure_list* list, struct subframe_table* table) {
    // Acquire the lock and wait for permission to modify the list
    pthread_mutex_lock(&lock);
    while (clearing) {
        pthread_cond_wait(&cond, &lock);
    }

    // Set the clearing flag to indicate that the list is being cleared
    clearing = 1;

    // Release the lock and signal any waiting threads to continue
    pthread_mutex_unlock(&lock);
    pthread_cond_broadcast(&cond);

    // Clear the list and hash table
    struct phy_rx_frame* frame = list->head;
    while (frame != NULL) {
        struct phy_rx_frame* next = frame->next;
        free(frame);
        frame = next;
    }
    list->count = 0;
    list->head = NULL;
    list->tail = NULL;
    for (int i = 0; i < MAX_STRUCTURES; i++) {
        table->frames[i] = NULL;
    }
    table->count = 0;

    // Set the clearing flag to indicate that the list has been cleared
    pthread_mutex_lock(&lock);
    clearing = 0;
    pthread_cond_broadcast(&cond);
    pthread_mutex_unlock(&lock);
}

// Define a function to print the contents of the list and hash table
void print_list(struct structure_list* list, struct subframe_table* table) {
    // Acquire the lock and wait for permission to access the list
    pthread_mutex_lock(&lock);
    while (clearing) {
        pthread_cond_wait(&cond, &lock);
    }

    // Print the contents of the list
    struct phy_rx_frame* frame = list->head;
    while (frame != NULL) {
