#include <stdlib.h>
#include <stdio.h>
#include <time.h>

// Define a structure to hold the RX_UE_INFORMATION_TAG, RNTI, and CRC_INDICATION_REL8_TAG
typedef struct {
    RX_UE_INFORMATION_TAG tag;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_tag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a hash map to store the allocated RNTI values
static HashMap<uint16_t, bool> rnti_map;

// Initialize the hash map with a default capacity
void init_rnti_map() {
    rnti_map.reserve(100);
}

// Function to allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_array(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (arr == NULL) {
        perror("Failed to allocate memory for array");
        exit(1);
    }
    return arr;
}

// Function to generate unique RNTI values and validate their uniqueness
void generate_rnti_values(size_t size, NFAPI_CRC_INDICATION_PDU_T* arr) {
    uint16_t rnti = 0;
    while (rnti < size) {
        // Generate a random RNTI value between 0 and 499
        rnti = rand() % 500;
        // Check if the RNTI value is already present in the hash map
        if (!rnti_map.contains(rnti)) {
            break;
        }
    }
    // If all RNTI values are used up, generate a new one and try again
    if (rnti == size) {
        generate_rnti_values(size, arr);
    } else {
        rnti_map.put(rnti, true);
        for (int i = 0; i < size; i++) {
            arr[i].tag = RX_UE_INFORMATION_TAG;
            arr[i].rnti = rnti;
            arr[i].crc_tag = CRC_INDICATION_REL8_TAG;
        }
    }
}

// Function to free the allocated memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
void free_array(NFAPI_CRC_INDICATION_PDU_T* arr, size_t size) {
    if (arr != NULL) {
        free(arr);
        arr = NULL;
    }
}

// Function to log the allocated structures' tags and values to a specified file
void log_allocated_structures(NFAPI_CRC_INDICATION_PDU_T* arr, size_t size) {
    FILE* fp = fopen("logfile.txt", "a");
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char str[10];
    strftime(str, 9, "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "[%s] Allocated structures with tags and values:\n", str);
    for (int i = 0; i < size; i++) {
        fprintf(fp, "\tStructure %d: tag=%d, rnti=%d, crc_tag=%d\n", i, arr[i].tag, arr[i].rnti, arr[i].crc_tag);
    }
    fclose(fp);
}

// Function to handle memory allocation failures by freeing all previously allocated memory and attempting a new allocation with unique RNTI values
void handle_memory_allocation_failure() {
    NFAPI_CRC_INDICATION_PDU_T* arr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * size);
    if (arr == NULL) {
        perror("Failed to allocate memory for array");
        exit(1);
    } else {
        // Free all previously allocated memory and attempt a new allocation with unique RNTI values
        free_array(arr, size);
        generate_rnti_values(size, arr);
        log_allocated_structures(arr, size);
    }
}

// Main function to dynamically allocate memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocate_memory(size_t size) {
    // Initialize the hash map with a default capacity
