        crc_indications[*num_allocated].crc_indication = crc_indications[i].crc_indication;
        *num_allocated += 1;
      }
    }
    retry_count += 1;
  }

  // If any memory allocation failures occurred, log the error and return appropriate error codes
  if (*num_allocated < n) {
    fprintf(stderr, "Error: Memory allocation failed for NFAPI_CRC_INDICATION_PDU_T structures.\n");
    return;
