// Define the structure for LTE uplink data
typedef struct {
    int pdu_session_id;
    int ue_index;
    long up_sequence_number;
    double rx_timestamp;
} LTE_UPLINK_T;

// Define the list of LTE uplink data
typedef struct {
    LTE_UPLINK_T *list;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} LTE_UPLINK_LIST;

// Define the function to add a new entry to the list
void lte_uplink_add(LTE_UPLINK_T *entry) {
    // Lock the mutex to prevent concurrent access
    pthread_mutex_lock(&lte_uplink_list.lock);

    // Check if the list is full and needs to be resized
    if (lte_uplink_list.count >= lte_uplink_list.capacity) {
        size_t new_capacity = lte_uplink_list.capacity * 2;
        LTE_UPLINK_T *new_list = realloc(lte_uplink_list.list, sizeof(LTE_UPLINK_T) * new_capacity);
        if (new_list == NULL) {
            // Handle allocation failure gracefully
        }

        lte_uplink_list.capacity = new_capacity;
        lte_uplink_list.list = new_list;
    }

    // Copy the entry into the list
    memcpy(&lte_uplink_list.list[lte_uplink_list.count], entry, sizeof(LTE_UPLINK_T));
    lte_uplink_list.count++;

    // Unlock the mutex
    pthread_mutex_unlock(&lte_uplink_list.lock);
}

// Define the function to remove an entry from the list
void lte_uplink_remove(int index) {
    // Lock the mutex to prevent concurrent access
