void nfapi_add_crc_indication(NFAPI_CRC_INDICATIONS_ARRAY *array, char rnti[MAX_RNTI_LENGTH], int crcflag) {
    // Check if there is enough space in the array for a new element
    if (array->count >= array->capacity) {
        // Allocate more memory for the array if necessary
        size_t new_capacity = MAX(array->capacity * 2, 10);
        NFAPI_CRC_INDICATION_PDU_T *new_data = malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        memcpy(new_data, array->data, array->count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        free(array->data);
        array->data = new_data;
        array->capacity = new_capacity;
