    fwrite(&num_crc_indications, sizeof(size_t), 1, file);

    // Write each CRC indication structure to the file
    for (size_t i = 0; i < num_crc_indications; i++) {
        fwrite(&array->data[i].rnti, sizeof(char) * MAX_RNTI_LENGTH, 1, file);
        fwrite(&array->data[i].crcflag, sizeof(int), 1, file);
