    // Allocate memory for the array
    NFAPI_CRC_INDICATION_PDU_T *data = malloc(num_crc_indications * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        printf("Error: Failed to allocate memory for CRC indication array\n");
        return;
    }

    // Read each CRC indication structure from the file
    for (size_t i = 0; i < num_crc_indications; i++) {
        fread(data[i].rnti, sizeof(char) * MAX_RNTI_LENGTH, 1, file);
        fread(&data[i].crcflag, sizeof(int), 1, file);
    }

    // Close the input file
    fclose(file);

    // Set the array count and data pointer
    array->count = num_crc_indications;
    array->data = data;
}
