JavaScript Array Reduction Function:
```javascript
function reduce(arr, initialValue, callback) {
    let finalValue = initialValue;
    for (let i = 0; i < arr.length; i++) {
        finalValue = callback(finalValue, arr[i]);
    }
    return finalValue;
}
```
JavaScript Array Reduction Function with Asynchronous Callbacks:
```javascript
function reduceAsync(arr, initialValue, callback) {
    let finalValue = initialValue;
    const promises = [];
    for (let i = 0; i < arr.length; i++) {
        const promise = new Promise((resolve, reject) => {
            callback(finalValue, arr[i], (err, result) => {
                if (err) {
                    reject(err);
                } else {
                    finalValue = result;
                    resolve();
                }
            });
        });
        promises.push(promise);
    }
    return Promise.all(promises).then(() => finalValue);
}
```
Sample Usage:
```javascript
const array = [1, 2, 3, 4, 5];
const initialValue = 0;

// Synchronous reduction
console.log(reduce(array, initialValue, (acc, curr) => acc + curr)); // Output: 15

// Asynchronous reduction with callbacks
reduceAsync(array, initialValue, (acc, curr, done) => {
    setTimeout(() => {
        done(null, acc + curr);
    }, 1000);
}).then((result) => console.log(result)); // Output: 15
```']

