    db->profiles[db->numUsers].name = name;
    db->profiles[db->numUsers].email = email;
    db->numUsers++;
}

// function to remove a user from the graph database schema
void removeUser(GraphDatabase *db, int id) {
    // find the index of the user to be removed
    int i = 0;
    for (; i < db->numUsers && db->profiles[i].id != id; i++) {}
    if (i == db->numUsers) {
        return; // user not found
    }
    // shift remaining users to fill the gap
    for (int j = i; j < db->numUsers - 1; j++) {
        db->profiles[j] = db->profiles[j + 1];
    }
    db->numUsers--;
}

// function to update a user profile in the graph database schema
void updateUser(GraphDatabase *db, int id, char *name, char *email) {
    // find the index of the user to be updated
    int i = 0;
    for (; i < db->numUsers && db->profiles[i].id != id; i++) {}
    if (i == db->numUsers) {
        return; // user not found
    }
    db->profiles[i].name = name;
    db->profiles[i].email = email;
}

