void traverseGraph(GraphDatabase *db, int sourceId) {
    // initialize stack for traversal
    Stack *stack = createStack();
    push(stack, sourceId);
    while (!isEmpty(stack)) {
        int nodeId = pop(stack);
        // process current node
        printf("Node %d: ", nodeId);
        UserProfile *profile = db->profiles[nodeId];
        printf("%s (%s)\n", profile.name, profile.email);
        // explore neighboring nodes
        for (int i = 0; i < db->numRelationships; i++) {
            Relationship *relationship = db->relationships[i];
            if (relationship.sourceId == nodeId) {
                int targetId = relationship.targetId;
                push(stack, targetId);
            }
        }
    }
    destroyStack(stack);
}

// function to identify communities or clusters of interconnected users in the graph database schema
void identifyCommunities(GraphDatabase *db) {
    // initialize array for community identifiers
    int numCommunities = 0;
    Community communities[MAX_USERS];
    for (int i = 0; i < db->numUsers; i++) {
        UserProfile *profile = db->profiles[i];
        bool isInCommunity = false;
        // check if user is already in a community
        for (int j = 0; j < numCommunities && !isInCommunity; j++) {
            Community *community = &communities[j];
            for (int k = 0; k < community->size && !isInCommunity; k++) {
                if (community->profiles[k].id == profile.id) {
                    isInCommunity = true;
                }
            }
        }
        // create new community if user is not in any existing one
        if (!isInCommunity) {
            communities[numCommunities].id = numCommunities + 1;
            communities[numCommunities].profiles[communities[numCommunities].size] = profile;
            communities[numCommunities].size++;
            numCommunities++;
        }
    }
}
