}

int allocate_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list, size_t num_pdus) {
    if (num_pdus > list->max_num_pdus) {
        return -1; // error: requested number of structures exceeds maximum limit
    }

    NFAPI_CRC_INDICATION_PDU_T *new_pdu = realloc(list->pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdus);
    if (new_pdu == NULL) {
        return -1; // error: memory allocation failed
    }

    list->pdu = new_pdu;
    list->num_pdus = num_pdus;

    return 0; // success
}

void add_crc_indication(NFAPI_CRC_INDICATION_LIST *list, uint32_t RX_UE_INFORMATION_TAG, uint32_t RNTI) {
    if (list->num_pdus >= list->max_num_pdus) { // check if the list is full
