    pdu->RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    pdu->RNTI = RNTI;
}

void reset_crc_indication_list(NFAPI_CRC_INDICATION_LIST *list) {
    list->num_pdus = 0;
}
