// Function to insert a new NFAPI_UL_T_PDU structure into the array
void insert_ul_t_pdu(NFAPI_UL_T_PDU* p) {
    // Check if the array is full and needs to be reallocated
    if (ul_t_pdu_array == NULL || ul_t_pdu_array->size == ul_t_pdu_array->capacity) {
        // Reallocate the array with a larger capacity
        int new_capacity = 2 * ul_t_pdu_array->capacity;
