        for (int i = ul_t_pdu_array->size; i < new_capacity; ++i) {
            ul_t_pdu_array[i].UE_ID = i + 1;
            ul_t_pdu_array[i].grant.dl_Bandwidth = 5;
            ul_t_pdu_array[i].user_data = (char*)malloc(1024);
