    // Check if the structure was found and remove it from the array
    if (i < ul_t_pdu_array->size) {
        // Free the user data buffer
        free(ul_t_pdu_array[i].user_data);

        // Shift all elements after the removed element to the left
        for (int j = i; j < ul_t_pdu_array->size - 1; ++j) {
            memcpy(&ul_t_pdu_array[j], &ul_t_pdu_array[j + 1], sizeof(NFAPI_UL_T_PDU));
