    // Check if the array is empty
    if (num_ues == 0) {
        return NULL;
    }

    // Find the matching UE state entry
    for (int i = 0; i < num_ues; ++i) {
        if (ues[i].ue_identifier == ue_identifier) {
            return &ues[i];
        }
    }

    // Return NULL if no matching entry found
    return NULL;
}

// Function to remove an existing UE state entry
int removeUEState(int ue_identifier) {
    // Check if the array is empty
    if (num_ues == 0) {
        return -1;
    }

    // Find the matching UE state entry
    for (int i = 0; i < num_ues; ++i) {
        if (ues[i].ue_identifier == ue_identifier) {
            memmove(ues + i, ues + i + 1, sizeof(UEState) * (num_ues - i - 1));
            --num_ues;
            return 0;
        }
    }

    // Return an error if no matching entry found
    return -1;
}

// Function to perform periodic cleanup of unused UE state entries
void cleanupUEStates() {
    int num_unused = 0;

    for (int i = 0; i < num_ues; ++i) {
        if (!ues[i].radio_link_status.is_active) {
            ++num_unused;
        }
    }

    if (num_unused > 0) {
        // Reallocate the array to remove unused entries
        ues = realloc(ues, sizeof(UEState) * (num_ues - num_unused));

        if (!ues) {
            fprintf(stderr, "Failed to allocate memory for UE state array\n");
            exit(1);
        }

        // Update the number of used entries
        num_ues -= num_unused;
    }
}
