void updateUEStateEntry(struct UEStateNode *ueStateNode) {
    struct UEStateNode *node = SLIST_FIRST(&ueStates);
    while (node != NULL && node->next != ueStateNode) {
        node = node->next;
    }
    if (node == NULL) {
        // Node not found, add a new entry
        struct UEStateNode *newNode = malloc(sizeof(struct UEStateNode));
        SLIST_INSERT_HEAD(&ueStates, newNode, next);
    } else {
