// Define a function for cleaning up outdated frames based on a configurable retention policy
void cleanupOutdatedFrames(int retentionPolicy) {
    struct LTE_PHY_RX_FRAMENode *node = SLIST_FIRST(&frames);
    while (node != NULL && node->next != NULL) {
        if (retentionPolicy == 0) { // Retain all frames
            return;
        } else if (retentionPolicy == 1) { // Retain only last N frames
            struct LTE_PHY_RX_FRAMENode *temp = node->next;
            while (temp != NULL && temp->next != NULL) {
                node = node->next;
                temp = temp->next;
            }
