                SLIST_REMOVE_HEAD(&frames);
            } else {
                struct LTE_PHY_RX_FRAMENode *last = node->next;
                SLIST_REMOVE_AFTER(node);
                free(last);
            }
        }
    }
}

// Define a function for tracking symbol counts and managing resource usage
void trackSymbolCounts() {
    struct LTE_PHY_RX_FRAMENode *node = SLIST_FIRST(&frames);
    while (node != NULL && node->next != NULL) {
        node->frame.symbolCount += 1;
        if (node->frame.symbolCount >= SYMBOL_COUNT_THRESHOLD) {
            // Symbol count threshold reached, clean up outdated frames
            cleanupOutdatedFrames(1);
            break;
        }
        node = node->next;
    }
}

// Define a function for serializing UEState and LTE_PHY_RX_FRAME lists to binary files
void serialize() {
    // Serialize UEState list to file
    FILE *fp = fopen("ueStates.bin", "wb");
    if (fp == NULL) {
        perror("Error opening UEState list file for writing");
        return;
    }
    struct UEStateNode *node = SLIST_FIRST(&ueStates);
    while (node != NULL && node->next != NULL) {
        fwrite(&node->ueState, sizeof(struct UEState), 1, fp);
        node = node->next;
    }
    fclose(fp);

    // Serialize LTE_PHY_RX_FRAME list to file
    fp = fopen("frames.bin", "wb");
    if (fp == NULL) {
        perror("Error opening LTE_PHY_RX_FRAME list file for writing");
        return;
    }
    node = SLIST_FIRST(&frames);
    while (node != NULL && node->next != NULL) {
        fwrite(&node->frame, sizeof(struct LTE_PHY_RX_FRAME), 1, fp);
        node = node->next;
    }
    fclose(fp);
}

// Define a function for deserializing UEState and LTE_PHY_RX_FRAME lists from binary files
void deserialize() {
    // Deserialize UEState list from file
    FILE *fp = fopen("ueStates.bin", "rb");
    if (fp == NULL) {
        perror("Error opening UEState list file for reading");
        return;
    }
    struct UEState ueState;
    while (!feof(fp)) {
        fread(&ueState, sizeof(struct UEState), 1, fp);
        addUEStateEntry(ueState.ueIdentifier, ueState.rnti, ueState.tai, ueState.cellId);
    }
    fclose(fp);

    // Deserialize LTE_PHY_RX_FRAME list from file
    fp = fopen("frames.bin", "rb");
    if (fp == NULL) {
        perror("Error opening LTE_PHY_RX_FRAME list file for reading");
        return;
    }
    struct LTE_PHY_RX_FRAME frame;
    while (!feof(fp)) {
        fread(&frame, sizeof(struct LTE_PHY_RX_FRAME), 1, fp);
        addLTE_PHY_RX_FRAMEEntry(frame.header.frameNumber, frame.payload);
    }
    fclose(fp);
}
