void loadContextData(char* filename, struct UEContext** contexts) {
    // Open the CSV file
    FILE* csvFile = fopen(filename, "r");
    if (csvFile == NULL) {
        printf("Error: Failed to open CSV file\n");
        return;
    }

    // Parse the CSV file
    while (!feof(csvFile)) {
        char line[1024];
        fgets(line, 1024, csvFile);

        // Skip header lines and comments
        if (line[0] == '#' || strlen(line) <= 1) continue;

        // Parse the fields
        char* field = strtok(line, ",");
        int imsi = atoi(field);
        field = strtok(NULL, ",");
        int rnti = atoi(field);
        field = strtok(NULL, ",");
        int pdu_session_id = atoi(field);

        // Create a new UEContext structure and populate it with the parsed data
        struct UEContext* context = malloc(sizeof(struct UEContext));
        if (context == NULL) {
            printf("Error: Failed to allocate memory for UEContext\n");
            return;
        }
        context->imsi = imsi;
        context->rnti = rnti;
        context->pdu_session_id = pdu_session_id;
        context->isValid = true;

        // Add the new UEContext to the list of contexts
        if (*contexts == NULL) {
            *contexts = malloc(sizeof(struct UEContext*));
            if (*contexts == NULL) {
                printf("Error: Failed to allocate memory for list of UEContexts\n");
                return;
            }
        }
        (**contexts).push_back(context);
    }

    // Close the CSV file
    fclose(csvFile);
}

// Generate a list of NFAPI_CRC_INDICATION_PDU_T structures based on the given contexts
void generateNFAPICRCIndicationPDUs(struct UEContext* contexts, int numContexts, struct NFAPI_CRC_INDICATION_PDU_T** pduList) {
