    *pduList = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T*) * numContexts);
    if (*pduList == NULL) {
        printf("Error: Failed to allocate memory for list of NFAPI_CRC_INDICATION_PDU_T\n");
        return;
    }

    // Populate the list of PDUs with data from the contexts
    int i = 0;
    while (i < numContexts) {
        struct UEContext* context = contexts[i];
        struct NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(struct NFAPI_CRC_INDICATION_PDU_T));
        if (pdu == NULL) {
            printf("Error: Failed to allocate memory for NFAPI_CRC_INDICATION_PDU_T\n");
