// Define the structure to hold the CRC indication data
typedef struct NFAPI_CRC_INDICATION_PDU {
    uint8_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the list data structure to hold the NFAPI_CRC_INDICATION_PDU structures
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T** entries;
    size_t count;
    pthread_mutex_t lock;
} LIST_T;

// Function to dynamically manage the list of NFAPI_CRC_INDICATION_PDU structures based on runtime parameters read from an external configuration file.
void manage_list(LIST_T* list, const char* config_file) {
    // Load the configuration file and parse the number of structures to create
    int num_structures = 0;
    FILE* fp = fopen(config_file, "r");
    if (fp == NULL) {
        printf("Error: Could not open config file %s\n", config_file);
        return;
    }
    while (fscanf(fp, "%d", &num_structures) != EOF) {}
    fclose(fp);

    // Allocate memory for the list of structures and initialize the lock
    if (list->entries == NULL) {
        list->entries = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * num_structures);
        assert(list->entries != NULL);
        pthread_mutex_init(&list->lock, NULL);
    }

    // Iterate over the number of structures and create a new structure for each one
    for (int i = 0; i < num_structures; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        assert(pdu != NULL);
        pdu->RX_UE_INFORMATION_TAG = i;
        pdu->RNTI = rand();
        pdu->CRCFLAG = (bool)rand();
        list->entries[i] = pdu;
    }

    // Update the count of structures in the list
    list->count = num_structures;

    // Clean up any previous memory allocations if the number of structures has decreased
    if (list->count > num_structures) {
        for (int i = num_structures; i < list->count; ++i) {
            free(list->entries[i]);
        }
        list->count = num_structures;
    }
}

// Function to validate the integrity of the CRC_INDICATION_REL8_TAG before insertion into the list.
void validate_crc_indication(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Check if the CRCFLAG is set to true and the RNTI is valid
    if (pdu->CRCFLAG && pdu->RNTI != 0) {
        return;
    } else {
        printf("Error: Invalid CRC indication tag or RNTI\n");
    }
}

// Function to reset the structure list when it is no longer needed.
void reset_list(LIST_T* list) {
    pthread_mutex_lock(&list->lock);
    for (int i = 0; i < list->count; ++i) {
        free(list->entries[i]);
    }
    list->count = 0;
    pthread_mutex_unlock(&list->lock);
}

// Main function to demonstrate the use of the manage_list function.
int main() {
    LIST_T* list = malloc(sizeof(LIST_T));
    assert(list != NULL);
    list->entries = NULL;
    list->count = 0;
    pthread_mutex_init(&list->lock, NULL);

    // Create a configuration file with the number of structures to create
    FILE* fp = fopen("config.txt", "w");
    if (fp == NULL) {
        printf("Error: Could not open config file\n");
        return 1;
    }
    for (int i = 0; i < 5; ++i) {
        fprintf(fp, "%d\n", rand() % 10);
    }
    fclose(fp);

    // Call the manage_list function to dynamically create and manage the list of structures based on runtime parameters read from the configuration file.
    manage_list(list, "config.txt");

    // Validate the integrity of each structure in the list before using it for further processing.
    for (int i = 0; i < list->count; ++i) {
        validate_crc_indication(list->entries[i]);
    }

    // Reset the structure list when it is no longer needed.
    reset_list(list);

    free(list);
    return 0;
}
