    NFAPI_CRC_INDICATION_PDU_T *structures; // array of pointers to the structures
    size_t num_structures; // number of structures currently allocated
    size_t max_num_structures; // maximum number of structures that can be allocated
} NFAPI_CRC_INDICATION_PDU_LIST;

// define a mutex for thread safety
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// function to allocate and initialize a new structure
NFAPI_CRC_INDICATION_PDU_T *allocate_structure(void) {
    NFAPI_CRC_INDICATION_PDU_T *structure = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) {
        // handle memory allocation failure
        return NULL;
    }
    structure->valid = 1;
    structure->RX_UE_INFORMATION_TAG = malloc(sizeof(uint8_t));
    structure->RNTI = malloc(sizeof(uint32_t));
    structure->CRC_INDICATION_REL8_TAG = malloc(sizeof(uint8_t));
    *structure->RX_UE_INFORMATION_TAG = 0;
    *structure->RNTI = 0;
    *structure->CRC_INDICATION_REL8_TAG = 0;
    structure->CRCFLAG = rand() % 2; // set CRCFLAG randomly
    return structure;
}

// function to free a structure
void free_structure(NFAPI_CRC_INDICATION_PDU_T *structure) {
    if (!structure) {
        return;
    }
    free(structure->RX_UE_INFORMATION_TAG);
    free(structure->RNTI);
    free(structure->CRC_INDICATION_REL8_TAG);
    free(structure);
}

// function to add a new structure to the list
int add_structure(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    if (list->num_structures == list->max_num_structures) {
        // handle maximum number of structures exceeded
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    list->structures[list->num_structures] = structure;
    list->num_structures++;
    pthread_mutex_unlock(&mutex); // unlock the mutex
    return 0;
}

// function to remove a structure from the list
int remove_structure(NFAPI_CRC_INDICATION_PDU_LIST *list, NFAPI_CRC_INDICATION_PDU_T *structure) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    size_t i;
    for (i = 0; i < list->num_structures; i++) {
        if (list->structures[i] == structure) {
            break;
        }
    }
    if (i >= list->num_structures) {
        // handle structure not found in the list
        pthread_mutex_unlock(&mutex);
        return -1;
    }
    list->num_structures--;
    memmove(list->structures + i, list->structures + i + 1, (list->num_structures - i) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_unlock(&mutex); // unlock the mutex
    return 0;
}

// function to reset the structure list
void reset_structure_list(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    size_t i;
    for (i = 0; i < list->num_structures; i++) {
        free_structure(list->structures[i]);
    }
    list->num_structures = 0;
    pthread_mutex_unlock(&mutex); // unlock the mutex
}

// function to cleanup unused structures in the list
void cleanup_structure_list(NFAPI_CRC_INDICATION_PDU_LIST *list) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    size_t i;
    for (i = 0; i < list->num_structures; i++) {
        if (!list->structures[i]->valid) {
            free_structure(list->structures[i]);
            memmove(list->structures + i, list->structures + i + 1, (list->num_structures - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
            list->num_structures--;
            i--;
        }
    }
    pthread_mutex_unlock(&mutex); // unlock the mutex
}

// function to integrate with an external configuration file to adjust the number of structures based on runtime parameters
void configure_structure_list(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t num_structures) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    if (num_structures > list->max_num_structures) {
        // handle maximum number of structures exceeded
        pthread_mutex_unlock(&mutex);
        return;
    }
    size_t i;
    for (i = 0; i < num_structures; i++) {
        add_structure(list, allocate_structure());
    }
    list->num_structures = num_structures;
    pthread_mutex_unlock(&mutex); // unlock the mutex
}

// function to get a structure from the list by its index
NFAPI_CRC_INDICATION_PDU *get_structure(NFAPI_CRC_INDICATION_PDU_LIST *list, size_t index) {
    pthread_mutex_lock(&mutex); // lock the mutex for thread safety
    if (index >= list->num_structures) {
        // handle structure not found in the list
        pthread_mutex_unlock(&mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU *structure = list->structures[index];
    pthread_mutex_unlock(&mutex); // unlock the mutex
    return structure;
}

// function to log the statistics of the structure list
