// Struct for record
typedef struct {
    int value;
} Record;

// Function to generate a random integer within the specified range
int getRandomInt(int min, int max) {
    return (rand() % (max - min + 1)) + min;
}

// Function to validate if a value is unique in the array
bool isUnique(Record *arr, int size, int value) {
    for (int i = 0; i < size; i++) {
        if (arr[i].value == value) {
            return false;
        }
    }
    return true;
}

// Function to allocate and initialize a new record with a unique value
Record *allocateNewRecord(int min, int max) {
    // Allocate memory for the record
    Record *record = (Record *) malloc(sizeof(Record));
    if (record == NULL) {
        return NULL;
    }

    // Generate a random value within the specified range
    int value = getRandomInt(min, max);

    // Validate if the value is unique in the array
    bool isUnique = true;
    while (!isUnique) {
        isUnique = isUnique(arr, size, value);
        if (!isUnique) {
            free(record);
            record = allocateNewRecord(min, max);
        }
    }

    // Initialize the record with the unique value
    record->value = value;

    return record;
}

// Function to add a new record to the array
void addRecord(Record **arr, int *size, Record *record) {
    // Reallocate memory for the array if necessary
    if (*size == 0) {
        *arr = (Record *) realloc(*arr, sizeof(Record));
    } else {
        *arr = (Record *) realloc(*arr, (*size + 1) * sizeof(Record));
    }
    if (*arr == NULL) {
        free(record);
        return;
    }

    // Add the new record to the array
    arr[*size] = record;
    (*size)++;
}

// Function to remove a record from the array by value
void removeRecordByValue(Record **arr, int *size, int value) {
    // Find the index of the record with the specified value
    int index = -1;
    for (int i = 0; i < *size; i++) {
        if (arr[i]->value == value) {
            index = i;
            break;
        }
    }

    // Remove the record from the array
    if (index != -1) {
        for (int i = index + 1; i < *size; i++) {
            arr[i - 1] = arr[i];
        }
        (*size)--;

        // Reallocate memory for the array if necessary
        if (*size == 0) {
            free(*arr);
            *arr = NULL;
        } else {
            *arr = (Record *) realloc(*arr, (*size) * sizeof(Record));
        }
    }
}

// Function to log the value of a record along with its timestamp
void logRecord(FILE *file, Record *record) {
    // Convert the timestamp to a string
    char *timestamp = (char *) malloc(sizeof(time_t));
    strftime(timestamp, sizeof(time_t), "%Y-%m-%d %H:%M:%S", localtime(&record->value));

    // Write the log entry
    fprintf(file, "%s: %d\n", timestamp, record->value);

    free(timestamp);
}

// Function to handle memory allocation robustly
void *allocateMemory(size_t size) {
    void *memory = malloc(size);
    if (memory == NULL) {
        printf("Error: Out of memory.\n");
        exit(1);
    }
    return memory;
}

// Function to handle memory reallocation robustly
void *reallocateMemory(void **ptr, size_t size) {
    void *memory = realloc(*ptr, size);
    if (memory == NULL) {
        printf("Error: Out of memory.\n");
        exit(1);
    }
    return memory;
}

// Function to handle memory freeing robustly
void freeMemory(void **ptr) {
    free(*ptr);
    *ptr = NULL;
}
