Here is an implementation of a robust C library to manage a dynamic array of UDP packet headers:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <assert.h>

// Define the maximum number of headers to store (N) and the sliding window size (M)
#define N 10000
#define M 50

// Structure to represent a UDP packet header
struct udp_header {
    char source[16];   // Source IP address
    char dest[16];     // Destination IP address
    char protocol[4];  // Protocol type (UDP)
    int seq_num;       // Sequence number
};

// Global array to store the UDP packet headers
struct udp_header *headers = NULL;

// Function to allocate memory for the header array and initialize it to zero
void init_headers() {
    headers = (struct udp_header *)calloc(N, sizeof(struct udp_header));
    assert(headers != NULL);
}

// Function to free memory used by the header array
void destroy_headers() {
    if (headers) {
        free(headers);
        headers = NULL;
    }
}

// Function to insert a new UDP packet header into the array
bool insert_header(struct udp_header *header) {
    // Check if the array is full and needs to be resized
    if (size >= N) {
        resize_array();
    }

    // Copy the new header into the next available slot in the array
    memcpy(&headers[size], header, sizeof(struct udp_header));

    // Increment the size of the array and return success
    size++;
    return true;
}

// Function to validate a sequence number within the sliding window
bool is_valid_sequence(int seq_num) {
    // Check if the sequence number is within the last M packets
    for (int i = 0; i < M; i++) {
        if (headers[size - M + i].seq_num == seq_num) {
            return false;
        }
    }

    // Return true if no duplicate sequence numbers were found
    return true;
}

// Function to retrieve a UDP packet header from the array given its sequence number
struct udp_header *get_header(int seq_num) {
    for (int i = 0; i < size; i++) {
        if (headers[i].seq_num == seq_num) {
            return &headers[i];
        }
    }
    return NULL;
}

// Function to resize the header array when it is full
void resize_array() {
    // Double the size of the array and reallocate memory for the new headers
    N *= 2;
    struct udp_header *new_headers = (struct udp_header *)calloc(N, sizeof(struct udp_header));
    assert(new_headers != NULL);

    // Copy the old headers to the new array
    for (int i = 0; i < size; i++) {
        memcpy(&new_headers[i], &headers[i], sizeof(struct udp_header));
    }

    // Free the memory used by the old array and update the pointers
    free(headers);
    headers = new_headers;
}

// Function to handle concurrent access from multiple threads
void thread_safe_insert(struct udp_header *header) {
    pthread_mutex_lock(&mutex);
    insert_header(header);
    pthread_mutex_unlock(&mutex);
}

// Function to handle concurrent access from multiple threads
void thread_safe_get(int seq_num, struct udp_header *header) {
    pthread_mutex_lock(&mutex);
    memcpy(header, get_header(seq_num), sizeof(struct udp_header));
    pthread_mutex_unlock(&mutex);
}
```
The library provides a simple and efficient way to manage the dynamic array of UDP packet headers, with features such as automatic resizing and thread-safe access. It also includes validation mechanisms for sequence numbers within the sliding window and edge cases where N is zero or negative.']

