```c
#include <stdlib.h>
#include <stdio.h>
#include <time.h>
#include <stdbool.h>

// Struct representing a record with an int field
typedef struct {
  int value;
} record_t;

// Enum for the different list types
typedef enum {
  LIST_TYPE_OFFSET,
  LIST_TYPE_KEY,
} list_type_t;

// Struct representing a dynamically resizable list
typedef struct {
  list_type_t type;
  size_t capacity;
  size_t count;
  void **data;
} list_t;

// Function for allocating and initializing a list
list_t *list_init(size_t capacity, list_type_t type) {
  // Allocate memory for the list structure
  list_t *list = malloc(sizeof(list_t));
  if (list == NULL) {
    fprintf(stderr, "Failed to allocate memory for list\n");
    return NULL;
  }

  // Set the type and capacity of the list
  list->type = type;
  list->capacity = capacity;
  list->count = 0;

  // Allocate memory for the data array
  size_t data_size = sizeof(void *) * capacity;
  void **data = malloc(data_size);
  if (data == NULL) {
    fprintf(stderr, "Failed to allocate memory for list data\n");
    free(list);
    return NULL;
  }

  // Set the data array in the list structure
  list->data = data;

  return list;
}

// Function for adding an element to a list
bool list_add(list_t *list, void *element) {
  // Check if the list is full
  if (list->count == list->capacity) {
    fprintf(stderr, "List is full\n");
    return false;
  }

  // Add the element to the list
  list->data[list->count++] = element;

  return true;
}

// Function for retrieving an element from a list by index
void *list_get(list_t *list, size_t index) {
  if (index >= list->count) {
    fprintf(stderr, "Index out of bounds\n");
    return NULL;
  }

  return list->data[index];
}

// Function for inserting a 'record' structure into the lists
void record_insert(list_t *offset_list, list_t *key_list, record_t *record) {
  // Allocate memory for the offset and key values
  long offset = rand() % 1000;
  int key = rand() % 1000;

  // Set the value in the 'record' structure
  record->value = (int)offset;

  // Add the offset and key values to the appropriate lists
  list_add(offset_list, &offset);
  list_add(key_list, &key);
}

// Function for handling memory allocation failures during list operations
void handle_memory_failure() {
  fprintf(stderr, "Memory allocation failure\n");
}

int main() {
  // Initialize the lists with a capacity of 10,000 elements each
  list_t *offset_list = list_init(10000, LIST_TYPE_OFFSET);
  list_t *key_list = list_init(10000, LIST_TYPE_KEY);

  // Insert 'record' structures into the lists
  for (int i = 0; i < 10000; i++) {
    record_t *record = malloc(sizeof(record_t));
    if (record == NULL) {
      handle_memory_failure();
      return 1;
    }

    record->value = rand() % 1000;
    list_add(offset_list, &record->offset);
    list_add(key_list, &record->key);
  }

  // Retrieve an element from the lists and print its value
  long offset = *((long *)list_get(offset_list, 0));
  int key = *((int *)list_get(key_list, 0));
  printf("Offset: %ld\n", offset);
  printf("Key: %d\n", key);

  // Free the lists and their data arrays
  free(offset_list->data);
  free(offset_list);
  free(key_list->data);
  free(key_list);

  return 0;
}
```
This implementation uses a `record_t` struct to store an int field and allocates memory for the 'record' structures dynamically using `malloc`. The `list_init` function allocates memory for the list structure and initializes its type, capacity, and count fields. The `list_add` function checks if the list is full before adding an element, and the `list_get` function returns NULL if the index is out of bounds.

The `record_insert` function allocates memory for the offset and key values dynamically using `malloc`, sets the value in the 'record' structure to a random value within a specified range, and adds the offset and key values to the appropriate lists using `list_add`. The `handle_memory_failure` function prints an error message if memory allocation fails during list operations.

The `main` function initializes the lists with a capacity of 10,000 elements each, inserts 'record' structures into the lists, and retrieves and prints an element from the lists using `list_get`. Finally, it frees the lists and their data arrays.']

