#include <pthread.h>

#define MAX_CONTEXTS 1000000
#define MIN_RNTI 0
#define MAX_RNTI 65535
#define MIN_PDU_SESSION_ID 0
#define MAX_PDU_SESSION_ID 255

// Context structure to store IMSI, RNTI and PDU Session ID
typedef struct {
    uint64_t imsi;
    uint16_t rnti;
    uint8_t pdu_session_id;
} UEContext;

// Persistence file format for storing contexts
#define CONTEXT_FILE "contexts.bin"

// Locking mechanism to ensure thread safety during concurrent operations
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

// Memory pool for UEContext structures to optimize performance and reduce fragmentation
UEContext* context_pool[MAX_CONTEXTS];

// Function to initialize a randomly generated UEContext structure
void init_context(UEContext* ctx) {
    // Generate random IMSI, RNTI and PDU Session ID within specified range
    ctx->imsi = rand() % (MAX_IMSI - MIN_IMSI + 1) + MIN_IMSI;
    ctx->rnti = rand() % (MAX_RNTI - MIN_RNTI + 1) + MIN_RNTI;
    ctx->pdu_session_id = rand() % (MAX_PDU_SESSION_ID - MIN_PDU_SESSION_ID + 1) + MIN_PDU_SESSION_ID;
}

// Function to add a new UEContext structure to the pool
int add_context(UEContext* ctx) {
    pthread_mutex_lock(&lock);
    // Initialize a new context if the pool is empty or find an unused slot in the pool
    int i;
    for (i = 0; i < MAX_CONTEXTS; i++) {
        if (!context_pool[i] || !context_pool[i]->imsi) {
            context_pool[i] = ctx;
            break;
        }
    }
    // Return error if no slot is found in the pool
    if (i >= MAX_CONTEXTS) {
        return -1;
    }
    pthread_mutex_unlock(&lock);
    return i;
}

// Function to remove a UEContext structure from the pool by index
int remove_context(int idx) {
    pthread_mutex_lock(&lock);
    // Return error if the index is out of bounds
    if (idx < 0 || idx >= MAX_CONTEXTS) {
        return -1;
    }
    context_pool[idx] = NULL;
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to update a UEContext structure in the pool by index
int update_context(int idx, UEContext* ctx) {
    pthread_mutex_lock(&lock);
    // Return error if the index is out of bounds or context is NULL
    if (idx < 0 || idx >= MAX_CONTEXTS || !ctx) {
        return -1;
    }
    memcpy(context_pool[idx], ctx, sizeof(UEContext));
    pthread_mutex_unlock(&lock);
    return 0;
}

// Function to get a UEContext structure from the pool by index
int get_context(int idx) {
    pthread_mutex_lock(&lock);
    // Return error if the index is out of bounds
    if (idx < 0 || idx >= MAX_CONTEXTS) {
        return NULL;
    }
    pthread_mutex_unlock(&lock);
    return context_pool[idx];
}

// Function to get the number of active UEContext structures in the pool
int get_num_contexts() {
    int i, num = 0;
    pthread_mutex_lock(&lock);
    for (i = 0; i < MAX_CONTEXTS; i++) {
        if (context_pool[i] && context_pool[i]->imsi) {
            num++;
        }
    }
    pthread_mutex_unlock(&lock);
    return num;
}

// Function to get the average RNTI usage across all active UEContext structures in the pool
int get_avg_rnti() {
    int i, sum = 0, num = 0;
    pthread_mutex_lock(&lock);
    for (i = 0; i < MAX_CONTEXTS; i++) {
        if (context_pool[i] && context_pool[i]->imsi) {
            sum += context_pool[i]->rnti;
            num++;
        }
    }
    pthread_mutex_unlock(&lock);
    return sum / num;
}

// Function to get the most frequent PDU Session ID across all active UEContext structures in the pool
int get_most_frequent_pdu_session_id() {
    int i, max = 0, pdu_session_id = 0;
    pthread_mutex_lock(&lock);
    for (i = 0; i < MAX_CONTEXTS; i++) {
        if (context_pool[i] && context_pool[i]->imsi) {
            if (max < context_pool[i]->pdu_session_id) {
                max = context_pool[i]->pdu_session_id;
                pdu_session_id = i;
            }
        }
    }
    pthread_mutex_unlock(&lock);
    return pdu_session_id;
}

// Function to persist the pool of UEContext structures to disk
int save_contexts() {
    // Use a temporary file and rename it to the actual filename to avoid data corruption in case of failure
    int fd = open("/tmp/ue_contexts.bin", O_CREAT | O_WRONLY | O_TRUNC, 0644);
    if (fd < 0) {
        return -1;
    }
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (context_pool[i] && context_pool[i]->imsi) {
            int rc = write(fd, context_pool[i], sizeof(UEContext));
            if (rc < 0) {
                close(fd);
                return -1;
            }
        }
    }
    pthread_mutex_unlock(&lock);
    close(fd);
    // Atomically rename the temporary file to the actual filename
    return rename("/tmp/ue_contexts.bin", "/var/run/ue_contexts.bin");
}

// Function to load the pool of UEContext structures from disk
int load_contexts() {
    int fd = open("/var/run/ue_contexts.bin", O_RDONLY);
    if (fd < 0) {
        return -1;
    }
    pthread_mutex_lock(&lock);
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        UEContext ctx;
        int rc = read(fd, &ctx, sizeof(UEContext));
        if (rc < 0) {
            close(fd);
            return -1;
        } else if (rc == 0) {
            break; // Reached end of file
        } else {
            context_pool[i] = ctx;
        }
    }
    pthread_mutex_unlock(&lock);
    close(fd);
    return 0;
}

// Function to initialize the pool of UEContext structures with a set of pre-defined values
int init_contexts() {
    int i, j;
    for (i = 0; i < MAX_CONTEXTS; i++) {
        if (!context_pool[i]) {
            context_pool[i] = malloc(sizeof(UEContext));
            if (!context_pool[i]) {
                return -1;
            }
        }
        memset(context_pool[i], 0, sizeof(UEContext));
        // Fill the pool with pre-defined values for testing purposes
        context_pool[i]->imsi = i + 1000;
        context_pool[i]->rnti = i + 2000;
        context_pool[i]->pdu_session_id = i + 3000;
    }
    return 0;
}

// Function to clean up the pool of UEContext structures
int cleanup_contexts() {
    for (int i = 0; i < MAX_CONTEXTS; i++) {
        if (context_pool[i]) {
            free(context_pool[i]);
            context_pool[i] = NULL;
        }
    }
    return 0;
}
