// Define a structure to represent an element in the linked list
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG rx_ue_information;
    uint16_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8;
} NFAPI_CRC_INDICATION_PDU_T;

// Define a linked list data structure to store the elements
typedef struct {
    NFAPI_CRC_INDICATION_PDU_T *head;
    NFAPI_CRC_INDICATION_PDU_T *tail;
    size_t size;
    pthread_mutex_t lock; // mutex for thread-safe operations
} linked_list_t;

// Initialize the linked list with an initial capacity of 10 elements
static void init_linked_list(linked_list_t *list, size_t max_size) {
    assert(list != NULL);
    assert(max_size > 0);

    // Allocate memory for the linked list structure and initialize its fields
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL); // initialize mutex
}

// Add a new element to the end of the linked list
static void add_element(linked_list_t *list, RX_UE_INFORMATION_TAG rx_ue_information, uint16_t rnti) {
    assert(list != NULL);
    assert(rx_ue_information.valid == 1);

    // Allocate memory for the new element and populate its fields
    NFAPI_CRC_INDICATION_PDU_T *element = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    element->rx_ue_information = rx_ue_information;
    element->rnti = rnti;
    element->crc_indication_rel8.CRCFlag = rand() & 1; // set CRCFlag randomly

    // Lock the mutex to ensure thread-safe operations
    pthread_mutex_lock(&list->lock);

    // Add the new element to the end of the linked list
    if (list->head == NULL) {
        list->head = element;
    } else {
        list->tail->next = element;
    }
    list->tail = element;
    list->size++;

    // Unlock the mutex
    pthread_mutex_unlock(&list->lock);
}

// Remove an element from the linked list by its index
static void remove_element(linked_list_t *list, size_t index) {
    assert(list != NULL);
    assert(index < list->size);

    // Lock the mutex to ensure thread-safe operations
    pthread_mutex_lock(&list->lock);

    // Find the element at the given index and remove it from the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    size_t i = 0;
    while (i < index) {
        current = current->next;
        i++;
    }
    if (i == index) { // found the element at the given index
        if (list->head == list->tail) { // only one element in the linked list
            list->head = NULL;
            list->tail = NULL;
        } else if (current == list->head) { // remove the first element
            list->head = current->next;
        } else if (current == list->tail) { // remove the last element
            list->tail = current->prev;
        } else { // remove an intermediate element
            current->prev->next = current->next;
            current->next->prev = current->prev;
        }
        list->size--;
    }

    // Unlock the mutex
    pthread_mutex_unlock(&list->lock);
}

// Free all allocated memory for the linked list
static void free_linked_list(linked_list_t *list) {
    assert(list != NULL);

    // Lock the mutex to ensure thread-safe operations
    pthread_mutex_lock(&list->lock);

    // Free all elements in the linked list
    NFAPI_CRC_INDICATION_PDU_T *current = list->head;
    while (current != NULL) {
        NFAPI_CRC_INDICATION_PDU_T *next = current->next;
        free(current);
        current = next;
    }

    // Free the memory for the linked list structure and uninitialize its fields
    pthread_mutex_unlock(&list->lock);
}

int main() {
    // Initialize the linked list with an initial capacity of 10 elements
    linked_list_t list;
    init_linked_list(&list, 10);

    // Add a few elements to the linked list
