#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <syslog.h>

// Structure to store user interaction records
typedef struct {
    int interaction_type;
    time_t timestamp;
    int user_id;
    char source_system[16]; // Maximum length of source system name is 15 characters + NULL terminator
} USER_INTERACTION_RECORD;

// Global variables
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER; // Mutex for protecting the list of records
static USER_INTERACTION_RECORD *records; // List of user interaction records
static int record_count = 0; // Number of records in the list

// Function to add a new user interaction record to the list
void add_user_interaction_record(int interaction_type, time_t timestamp, int user_id, const char *source_system) {
    USER_INTERACTION_RECORD new_record;
    new_record.interaction_type = interaction_type;
    new_record.timestamp = timestamp;
    new_record.user_id = user_id;
    strcpy(new_record.source_system, source_system);

    // Check for duplicate records
    pthread_mutex_lock(&mutex);
    int i;
    for (i = 0; i < record_count; ++i) {
        if ((records[i].interaction_type == new_record.interaction_type) &&
            (records[i].timestamp == new_record.timestamp) &&
            (strcmp(records[i].source_system, new_record.source_system) == 0)) {
            // Duplicate record found, log message and skip adding the record
            syslog(LOG_INFO, "Duplicate user interaction record detected. Skipping...");
            pthread_mutex_unlock(&mutex);
            return;
        }
    }

    // No duplicates found, add the new record to the list
    if (record_count >= 5000000) {
        // List is full, remove the oldest record before adding a new one
        USER_INTERACTION_RECORD *oldest_record = records;
        for (i = 1; i < record_count; ++i) {
            if (records[i].timestamp < oldest_record->timestamp) {
                oldest_record = &records[i];
            }
        }
        free(oldest_record);
        --record_count;
    }
    records = realloc(records, sizeof(USER_INTERACTION_RECORD) * (record_count + 1));
    records[record_count] = new_record;
    ++record_count;
    pthread_mutex_unlock(&mutex);
}

// Function to handle unexpected failures gracefully
void handle_failure(const char *message) {
    syslog(LOG_ERR, message);
    exit(EXIT_FAILURE);
}

int main() {
    // Initialize the list of records
    records = calloc(5000000, sizeof(USER_INTERACTION_RECORD));
    if (records == NULL) {
        handle_failure("Failed to allocate memory for user interaction record list.");
    }

    // Initialize the mutex
    if (pthread_mutex_init(&mutex, NULL) != 0) {
        handle_failure("Failed to initialize mutex for user interaction record list.");
    }

    // Start the main processing loop
    while (1) {
        USER_INTERACTION_RECORD new_record;
        int ret = read(STDIN, &new_record, sizeof(USER_INTERACTION_RECORD));
        if (ret == -1) {
            handle_failure("Failed to read from standard input.");
        } else if (ret != sizeof(USER_INTERACTION_RECORD)) {
            syslog(LOG_ERR, "Incomplete user interaction record received. Skipping...");
        } else {
            add_user_interaction_record(new_record.interaction_type, new_record.timestamp, new_record.user_id, new_record.source_system);
        }
    }

    // Clean up resources before exiting
    free(records);
    pthread_mutex_destroy(&mutex);
    return 0;
}']

