// Macro for determining the number of transactions to be managed
#define M 1000

// Structure to represent a transaction record
typedef struct {
    unsigned int tx_id;
    unsigned int seq_num;
    char ack_state;
    time_t start_time;
    time_t end_time;
} MAC_TRANSACTION_RECORD;

// Function to allocate memory for the transaction records
MAC_TRANSACTION_RECORD* alloc_transaction_records(unsigned int num_transactions) {
    // Ensure that the number of transactions is positive and less than or equal to M
    if (num_transactions <= 0 || num_transactions > M) {
        fprintf(stderr, "Invalid number of transactions: %d\n", num_transactions);
        return NULL;
    }

    // Allocate memory for the transaction records
    MAC_TRANSACTION_RECORD* tx_records = (MAC_TRANSACTION_RECORD*)malloc(num_transactions * sizeof(MAC_TRANSACTION_RECORD));

    if (!tx_records) {
        fprintf(stderr, "Failed to allocate memory for transaction records\n");
        return NULL;
    }

    // Initialize the transaction records with default values
    for (unsigned int i = 0; i < num_transactions; i++) {
        tx_records[i].tx_id = i + 1;
        tx_records[i].seq_num = 0;
        tx_records[i].ack_state = 'N';
    }

    return tx_records;
}

// Function to deallocate memory for the transaction records
void free_transaction_records(MAC_TRANSACTION_RECORD* tx_records) {
    // Ensure that the transaction records pointer is not NULL
    if (!tx_records) {
        fprintf(stderr, "Invalid transaction records pointer\n");
        return;
    }

    // Deallocate memory for the transaction records
    free(tx_records);
}

// Function to add a new transaction record to the list
void add_transaction_record(MAC_TRANSACTION_RECORD* tx_records, unsigned int num_transactions) {
    // Ensure that the number of transactions is less than or equal to M
    if (num_transactions > M) {
        fprintf(stderr, "Number of transactions exceeds maximum: %d\n", M);
        return;
    }

    // Allocate memory for a new transaction record
    MAC_TRANSACTION_RECORD* new_record = (MAC_TRANSACTION_RECORD*)malloc(sizeof(MAC_TRANSACTION_RECORD));

    if (!new_record) {
        fprintf(stderr, "Failed to allocate memory for new transaction record\n");
        return;
    }

    // Initialize the new transaction record with default values
    new_record->tx_id = num_transactions + 1;
    new_record->seq_num = 0;
    new_record->ack_state = 'N';

    // Add the new transaction record to the list of transactions
    tx_records[num_transactions] = *new_record;
}

// Function to retrieve a transaction record from the list by its ID
MAC_TRANSACTION_RECORD* get_transaction_record(MAC_TRANSACTION_RECORD* tx_records, unsigned int id) {
    // Ensure that the transaction ID is valid and less than or equal to M
    if (id <= 0 || id > M) {
        fprintf(stderr, "Invalid transaction ID: %d\n", id);
        return NULL;
    }

    // Return the corresponding transaction record from the list
    return &tx_records[id - 1];
}
```
This code defines a function `alloc_transaction_records` to allocate memory for an array of `M` transaction records, each containing an `TX_ID`, `SEQ_NUM`, and associated timestamps. The function also initializes the transaction records with default values.

The function `free_transaction_records` deallocates memory for the transaction records when they are no longer needed.

The function `add_transaction_record` adds a new transaction record to the list of transactions, ensuring that the number of transactions does not exceed the maximum value of `M`.

The function `get_transaction_record` retrieves a transaction record from the list by its ID, returning a pointer to the corresponding transaction structure.

Note that this code does not include any concurrency mechanisms for handling multiple threads accessing the same transaction records simultaneously. If you need to ensure thread-safe operations, you may consider using a lock-based approach or implementing atomic operations on the transaction records.']

