// Define the memory pool structure
typedef struct {
  int size; // Size of the memory pool
  int numAllocated; // Number of structures allocated in the pool
  void* mem; // Pointer to the start of the memory pool
} MEMORY_POOL_T;

// Define the thread-safe data structure for managing the memory pool
typedef struct {
  pthread_mutex_t mutex; // Mutex for locking the memory pool
  MEMORY_POOL_T* pool; // Pointer to the memory pool
} THREAD_SAFE_MEMORY_POOL_T;

// Define the function that allocates an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* allocateArray(int numStructures) {
  if (numStructures <= 0) {
    printf("Error: Invalid input parameter 'numStructures' = %d\n", numStructures);
    return NULL;
  }

  // Initialize the memory pool for the structures
  THREAD_SAFE_MEMORY_POOL_T* memPool = initMemoryPool(sizeof(NFAPI_CRC_INDICATION_PDU_T), numStructures);
  if (memPool == NULL) {
    printf("Error: Failed to initialize memory pool\n");
    return NULL;
  }

  // Allocate the array of structures from the memory pool
  NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
  if (array == NULL) {
    printf("Error: Failed to allocate memory for the array\n");
    return NULL;
  }

  // Initialize each structure in the array with a randomly set CRCFLAG and log the allocation
  int i;
  for (i = 0; i < numStructures; ++i) {
    array[i].crcIndTag.CRCFLAG = rand();
    printf("Allocated structure %d with CRCFLAG = %u\n", i, array[i].crcIndTag.CRCFLAG);
  }

  // Return the array of structures to the caller
  return array;
}

// Define the function that deallocates an array of NFAPI_CRC_INDICATION_PDU_T structures
void deallocateArray(NFAPI_CRC_INDICATION_PDU_T* array, int numStructures) {
  if (array == NULL || numStructures <= 0) {
    printf("Error: Invalid input parameter 'numStructures' = %d\n", numStructures);
    return;
  }

  // Deallocate each structure in the array from the memory pool and log the deallocation
  int i;
  for (i = 0; i < numStructures; ++i) {
    printf("Deallocated structure %d with CRCFLAG = %u\n", i, array[i].crcIndTag.CRCFLAG);
    deallocateMemory(array + i);
  }

  // Deallocate the memory pool and log the cleanup
  printf("Cleaned up memory pool for %d structures\n", numStructures);
  destroyMemoryPool();
}

// Define the function that initializes a thread-safe memory pool for managing the structures
THREAD_SAFE_MEMORY_POOL_T* initMemoryPool(int structureSize, int maxNumStructures) {
  if (structureSize <= 0 || maxNumStructures <= 0) {
    printf("Error: Invalid input parameter 'structureSize' = %d or 'maxNumStructures' = %d\n", structureSize, maxNumStructures);
    return NULL;
  }

  // Create a new memory pool object and initialize its fields
  THREAD_SAFE_MEMORY_POOL_T* memPool = (THREAD_SAFE_MEMORY_POOL_T*)malloc(sizeof(THREAD_SAFE_MEMORY_POOL_T));
  if (memPool == NULL) {
    printf("Error: Failed to allocate memory for the thread-safe memory pool\n");
    return NULL;
  }

  // Initialize the mutex and set its attributes
  memPool->mutex = PTHREAD_MUTEX_INITIALIZER;
  pthread_mutexattr_t attr;
  pthread_mutexattr_init(&attr);
  pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);

  // Initialize the memory pool fields and allocate memory for its structures
  memPool->pool = (MEMORY_POOL_T*)malloc(sizeof(MEMORY_POOL_T));
  if (memPool->pool == NULL) {
    printf("Error: Failed to allocate memory for the memory pool\n");
    free(memPool);
    return NULL;
  }

  memPool->pool->size = structureSize * maxNumStructures;
  memPool->pool->numAllocated = 0;
  memPool->pool->data = malloc(memPool->pool->size);
  if (memPool->pool->data == NULL) {
    printf("Error: Failed to allocate memory for the structures in the memory pool\n");
    free(memPool->pool);
    free(memPool);
    return NULL;
  }

  // Return the initialized thread-safe memory pool
  return memPool;
}

// Define the function that deallocates a thread-safe memory pool for managing the structures
void destroyMemoryPool() {
  if (memPool == NULL) {
    printf("Error: Invalid input parameter 'memPool' = NULL\n");
    return;
  }

  // Deallocate the memory pool and its structures
  free(memPool->pool->data);
  free(memPool->pool);
  pthread_mutexattr_destroy(&memPool->attr);
  memPool = NULL;
}

// Define the function that allocates memory for a structure in the thread-safe memory pool
void* allocateMemory(int structureSize) {
  if (structureSize <= 0 || memPool == NULL) {
    printf("Error: Invalid input parameter 'structureSize' = %d or 'memPool' = NULL\n", structureSize, memPool);
    return NULL;
  }

  // Lock the mutex for exclusive access to the memory pool
  pthread_mutex_lock(&memPool->mutex);

  // Allocate a new structure in the memory pool if there is room
  void* ptr = malloc(structureSize);
  if (ptr == NULL) {
    printf("Error: Failed to allocate memory for the structure\n");
    pthread_mutex_unlock(&memPool->mutex);
    return NULL;
  }

  // Update the number of allocated structures in the memory pool and unlock the mutex
  memPool->pool->numAllocated++;
  pthread_mutex_unlock(&memPool->mutex);

  // Return the pointer to the allocated structure
  return ptr;
}

// Define the function that deallocates memory for a structure in the thread-safe memory pool
void deallocateMemory(void* structurePtr) {
  if (structurePtr == NULL || memPool == NULL) {
    printf("Error: Invalid input parameter 'structurePtr' = NULL or 'memPool' = NULL\n");
    return;
  }

  // Lock the mutex for exclusive access to the memory pool
  pthread_mutex_lock(&memPool->mutex);

  // Deallocate the structure in the memory pool and update the number of allocated structures
  free(structurePtr);
  memPool->pool->numAllocated--;

  // Unlock the mutex
  pthread_mutex_unlock(&memPool->mutex);
}

// Define the function that logs a message to the console
void logMessage(const char* msg) {
  if (msg == NULL) {
    printf("Error: Invalid input parameter 'msg' = NULL\n");
    return;
  }

  // Print the message to the console
  printf("%s\n", msg);
}
