[PYTHON]
def initMemoryPool(max_num_structures, structure_size):
    if max_num_structures <= 0 or structure_size <= 0:
        return None

    memory_pool = {
        'max_num_structures': max_num_structures,
        'structure_size': structure_size,
        'next_free_index': 0,
        'structures': {}
    }

    for i in range(max_num_structures):
        memory_pool['structures'][i] = [0] * structure_size

    return memory_pool

def allocateMemory(memory_pool, num_structures):
    if not memory_pool or num_structures <= 0:
        return None

    free_indexes = []
    for i in range(memory_pool['max_num_structures']):
        if i not in memory_pool['structures']:
            free_indexes.append(i)

    if len(free_indexes) < num_structures:
        return None

    for i in range(num_structures):
        index = free_indexes[i]
        memory_pool['next_free_index'] += 1
        memory_pool['structures'][index] = [0] * memory_pool['structure_size']

    return list(range(memory_pool['next_free_index'] - num_structures, memory_pool['next_free_index']))

def deallocateMemory(memory_pool, indexes):
    if not memory_pool or not indexes:
        return

    for index in indexes:
        del memory_pool['structures'][index]

def destroyMemoryPool(memory_pool):
    if not memory_pool:
        return

    for i in range(memory_pool['max_num_structures']):
        if i in memory_pool['structures']:
