```
public class MemoryPool {
    private int maxNumStructures;
    private int structureSize;
    private Map<Integer, Object> structures = new HashMap<>();
    private int nextFreeIndex;

    public MemoryPool(int maxNumStructures, int structureSize) {
        this.maxNumStructures = maxNumStructures;
        this.structureSize = structureSize;
    }

    public void allocateMemory(int numStructures) {
        for (int i = 0; i < numStructures; i++) {
            int index = nextFreeIndex++;
            structures.put(index, new Object[structureSize]);
        }
    }

    public void deallocateMemory(List<Integer> indexes) {
        for (int index : indexes) {
            structures.remove(index);
        }
    }

    public void destroy() {
        structures.clear();
    }
}
