  // Check if there are any messages in the queue
  if (queue->frame_count > 0) {
    // Get the next message from the front of the queue
    LTE_PHY_RX_FRAME* frame = queue->frames[0];
    memmove(&queue->frames, &queue->frames + 1, sizeof(LTE_PHY_RX_FRAME*) * (queue->frame_count - 1));
    --queue->frame_count;

    // Process the message
    process_message(frame);
