struct network_interface {
    char name[IFNAMSIZ];
    int bandwidth;
    enum nfapi_modulation modulation;
    int power_level;
};

struct network_interface_config {
    struct network_interface *interfaces;
    size_t num_interfaces;
};

void init_network_interfaces(struct network_interface_config *config) {
    // Check for null pointer
    if (config == NULL) {
        printf("Error: Null pointer passed to init_network_interfaces\n");
        return;
    }

    // Initialize the interface array
    config->interfaces = calloc(config->num_interfaces, sizeof(struct network_interface));
    if (config->interfaces == NULL) {
        printf("Error: Failed to allocate memory for network interfaces\n");
        return;
    }

    // Initialize the bandwidth and modulation schemes of each interface
    for (size_t i = 0; i < config->num_interfaces; i++) {
        struct network_interface *interface = &config->interfaces[i];
        if (interface == NULL) {
            printf("Error: Interface at index %zu is null\n", i);
            return;
        }

        // Set default values for bandwidth and modulation schemes
        interface->bandwidth = 1000;
        interface->modulation = NFAPI_MODULATION_QPSK;
        interface->power_level = 20;
    }
}

void configure_network_interfaces(struct network_interface_config *config) {
    // Check for null pointer
    if (config == NULL) {
        printf("Error: Null pointer passed to configure_network_interfaces\n");
        return;
    }

    // Configure the bandwidth and modulation schemes of each interface
    for (size_t i = 0; i < config->num_interfaces; i++) {
        struct network_interface *interface = &config->interfaces[i];
        if (interface == NULL) {
            printf("Error: Interface at index %zu is null\n", i);
            return;
        }

        // Set the bandwidth and modulation schemes of each interface based on the config values
        switch (interface->bandwidth) {
            case 1000:
                interface->modulation = NFAPI_MODULATION_QPSK;
                break;
            case 2000:
                interface->modulation = NFAPI_MODULATION_16QAM;
                break;
            case 5000:
                interface->modulation = NFAPI_MODULATION_64QAM;
                break;
            default:
                printf("Error: Invalid bandwidth value for interface %zu\n", i);
                return;
        }
    }
}

void free_network_interfaces(struct network_interface_config *config) {
    // Check for null pointer
    if (config == NULL) {
        printf("Error: Null pointer passed to free_network_interfaces\n");
        return;
    }

    // Free the memory allocated for the interface array
    if (config->interfaces != NULL) {
        free(config->interfaces);
    }
}
