// Thread-safe list operations
void add_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu, int rnti, int crcflag) {
    pthread_mutex_lock(&pdu_list_mtx);
    if (num_pdu >= MAX_NUM_PDU) {
        // List is full, drop the new entry
        pthread_mutex_unlock(&pdu_list_mtx);
        return;
    }
    pdu_list[num_pdu].pdu = pdu;
    pdu_list[num_pdu].rnti = rnti;
    pdu_list[num_pdu].crcflag = crcflag;
    num_pdu++;
    pthread_mutex_unlock(&pdu_list_mtx);
}

void remove_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    pthread_mutex_lock(&pdu_list_mtx);
    int i;
    for (i = 0; i < num_pdu; i++) {
        if (pdu_list[i].pdu == pdu) {
            // Found the entry to remove, swap it with the last element and decrement the count
            PDU_ENTRY_T tmp = pdu_list[i];
            pdu_list[i] = pdu_list[num_pdu - 1];
            num_pdu--;
            // Unlock the mutex before returning to avoid deadlocks
            pthread_mutex_unlock(&pdu_list_mtx);
            return;
        }
    }
    // The entry was not found, unlock the mutex and return
    pthread_mutex_unlock(&pdu_list_mtx);
}

// Serialization mechanism to store PDUs in a binary format compatible with existing systems
void serialize_pdu_list(char *buffer) {
    int i;
    // Serialize the number of PDUs and RNTIs first
    memcpy(buffer, &num_pdu, sizeof(int));
    buffer += sizeof(int);
    memcpy(buffer, &num_rnti, sizeof(int));
    buffer += sizeof(int);
    // Serialize each PDU entry
    for (i = 0; i < num_pdu; i++) {
        memcpy(buffer, &pdu_list[i].pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
        buffer += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        memcpy(buffer, &pdu_list[i].rnti, sizeof(int));
        buffer += sizeof(int);
        memcpy(buffer, &pdu_list[i].crcflag, sizeof(int));
        buffer += sizeof(int);
    }
}

// Deserialization mechanism to read PDUs from a binary format compatible with existing systems
void deserialize_pdu_list(char *buffer) {
    int i;
    // Read the number of PDUs and RNTIs first
    memcpy(&num_pdu, buffer, sizeof(int));
    buffer += sizeof(int);
    memcpy(&num_rnti, buffer, sizeof(int));
    buffer += sizeof(int);
    // Initialize the list with the deserialized entries
    for (i = 0; i < num_pdu; i++) {
        pdu_list[i].pdu = *((NFAPI_CRC_INDICATION_PDU_T *)buffer);
        buffer += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        pdu_list[i].rnti = *((int *)buffer);
        buffer += sizeof(int);
        pdu_list[i].crcflag = *((int *)buffer);
        buffer += sizeof(int);
    }
}

// Feature to periodically clear the list and reset all allocated structures to a default state
void reset_pdu_list() {
    pthread_mutex_lock(&pdu_list_mtx);
    num_pdu = 0;
    num_rnti = 0;
    // Reset the list to its initial state
    pthread_mutex_unlock(&pdu_list_mtx);
}

// Feature to dynamically adjust the size of the list based on real-time network conditions
void resize_pdu_list(int new_size) {
    pthread_mutex_lock(&pdu_list_mtx);
    // Check if the new size is smaller than the current size and free unused memory
    if (new_size < num_pdu) {
        int i;
        for (i = 0; i < num_pdu - new_size; i++) {
            free(pdu_list[num_pdu - 1].pdu);
            num_pdu--;
        }
    } else if (new_size > num_pdu) { // Check if the new size is larger than the current size and allocate more memory
        int i;
        for (i = 0; i < new_size - num_pdu; i++) {
            pdu_list[num_pdu].pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pdu_list[num_pdu].rnti = 0;
            pdu_list[num_pdu].crcflag = 0;
            num_pdu++;
        }
    }
    // Resize the list to the new size
    num_pdu = new_size;
    pthread_mutex_unlock(&pdu_list_mtx);
}
