#include <semaphore.h>

// Define the structure for LTE PHY RX frame
typedef struct {
    // Frame header
    uint16_t frame_header;

    // Signal strength indicator
    int signal_strength;

    // Variable-length list of symbols
    struct {
        // Modulation type
        uint8_t modulation_type;

        // Phase rotation
        int phase_rotation;

        // Noise variance estimate
        float noise_variance;
    } *symbols;
} LTE_PHY_RX_FRAME;

// Define the structure for symbol data
typedef struct {
    // Modulation type
    uint8_t modulation_type;

    // Phase rotation
    int phase_rotation;

    // Noise variance estimate
    float noise_variance;
} LTE_PHY_RX_SYMBOL;

// Define the dynamic array for RX frames
typedef struct {
    // Array of RX frames
    LTE_PHY_RX_FRAME *frames;

    // Size of the array
    int size;

    // Maximum capacity of the array
    int capacity;
} LTE_PHY_RX_FRAME_ARRAY;

// Define the mutex for protecting concurrent access to the dynamic array
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Define the semaphore for waiting until a new frame can be added to the array
semaphore_t semaphore = SEMAPHORE_INITIALIZER(0);

// Function to initialize and manage the dynamic array of RX frames
LTE_PHY_RX_FRAME_ARRAY *lte_phy_rx_frame_array_init(int capacity) {
    LTE_PHY_RX_FRAME_ARRAY *array = (LTE_PHY_RX_FRAME_ARRAY *)malloc(sizeof(LTE_PHY_RX_FRAME_ARRAY));
    if (array == NULL) {
        return NULL;
    }

    array->frames = (LTE_PHY_RX_FRAME *)malloc(capacity * sizeof(LTE_PHY_RX_FRAME));
    if (array->frames == NULL) {
        free(array);
        return NULL;
    }

    array->size = 0;
    array->capacity = capacity;

    return array;
}

// Function to add a new RX frame to the dynamic array
int lte_phy_rx_frame_add(LTE_PHY_RX_FRAME_ARRAY *array, LTE_PHY_RX_FRAME frame) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&mutex);

    // Wait until there is space in the array to add a new frame
    semaphore_wait(&semaphore);

    // Check if the array needs to be resized
    if (array->size == array->capacity) {
        int new_capacity = array->capacity * 2;
        LTE_PHY_RX_FRAME *new_frames = (LTE_PHY_RX_FRAME *)realloc(array->frames, new_capacity * sizeof(LTE_PHY_RX_FRAME));
        if (new_frames == NULL) {
            pthread_mutex_unlock(&mutex);
            semaphore_post(&semaphore);
            return -1;
        }

        array->frames = new_frames;
        array->capacity = new_capacity;
    }

    // Add the new frame to the end of the array
    memcpy(&array->frames[array->size], &frame, sizeof(LTE_PHY_RX_FRAME));
    array->size++;

    // Release the mutex and post the semaphore to signal that a new frame can be added
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);

    return 0;
}

// Function to remove an RX frame from the dynamic array
int lte_phy_rx_frame_remove(LTE_PHY_RX_FRAME_ARRAY *array, int index) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < 0 || index >= array->size) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    // Remove the frame from the array
    memmove(&array->frames[index], &array->frames[index + 1], (array->size - index - 1) * sizeof(LTE_PHY_RX_FRAME));
    array->size--;

    // Release the mutex and post the semaphore to signal that a new frame can be added
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);

    return 0;
}

// Function to access an RX frame from the dynamic array
LTE_PHY_RX_FRAME *lte_phy_rx_frame_get(LTE_PHY_RX_FRAME_ARRAY *array, int index) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the index is valid
    if (index < 0 || index >= array->size) {
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    LTE_PHY_RX_FRAME *frame = &array->frames[index];

    // Release the mutex and post the semaphore to signal that a new frame can be added
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);

    return frame;
}

// Function to resize the dynamic array of RX frames
int lte_phy_rx_frame_array_resize(LTE_PHY_RX_FRAME_ARRAY *array, int capacity) {
    // Acquire the mutex for protecting concurrent access
    pthread_mutex_lock(&mutex);

    // Check if the new capacity is valid
    if (capacity <= 0 || capacity < array->size) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

