    if (new_frames == NULL) {
        pthread_mutex_unlock(&mutex);
        return -1;
    }

    array->frames = new_frames;
    array->capacity = capacity;

    // Release the mutex and post the semaphore to signal that a new frame can be added
    pthread_mutex_unlock(&mutex);
    semaphore_post(&semaphore);

    return 0;
}

