    // Sort the records based on their timestamps in ascending order
    qsort(records, num_records, sizeof(struct record), compare_records);
}

// Define the comparison function for sorting records
int compare_records(const void *a, const void *b) {
    struct record *record_a = (struct record *)a;
    struct record *record_b = (struct record *)b;

    // Sort based on timestamp in ascending order
    return record_a->timestamp - record_b->timestamp;
}

// Define the parallel sorting function
void parallel_sort_records(struct record *records, size_t num_records) {
    // Use a thread pool to sort the records in parallel
    pthread_t threads[num_records];
    for (size_t i = 0; i < num_records; i++) {
        struct record *record = &records[i];
        pthread_create(&threads[i], NULL, sort_record, record);
    }
    for (size_t i = 0; i < num_records; i++) {
