    time_t last_activity; // Timestamp of the last activity
} tcp_connection_info_t;

// Define a queue data structure to manage incoming and outgoing connection requests
typedef struct queue {
    size_t size; // Number of elements in the queue
    tcp_connection_info_t* array; // Array of elements (of type tcp_connection_info_t)
} queue_t;

// Define a mutex to protect access to the connection list and the queue
pthread_mutex_t conn_list_mtx = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t queue_mtx = PTHREAD_MUTEX_INITIALIZER;

// Define a condition variable to signal when the connection list or the queue changes
pthread_cond_t conn_list_cv = PTHREAD_COND_INITIALIZER;
pthread_cond_t queue_cv = PTHREAD_COND_INITIALIZER;

// Define a function to add a new connection to the list and signal any waiting threads
void add_connection(const char* client_ip, int port) {
    // Acquire the mutex for the connection list
    pthread_mutex_lock(&conn_list_mtx);

    // Create a new element in the array of connections
    tcp_connection_info_t* new_connection = malloc(sizeof(tcp_connection_info_t));
    memset(new_connection, 0, sizeof(tcp_connection_info_t));
    strncpy(new_connection->client_ip, client_ip, 16);
    new_connection->port = port;
    new_connection->state = ESTABLISHED;
    new_connection->last_activity = time(NULL);

    // Add the new connection to the array of connections
    if (conn_list.size == 0) {
        conn_list.array = calloc(1, sizeof(tcp_connection_info_t));
    } else {
        size_t old_size = conn_list.size;
        conn_list.array = realloc(conn_list.array, (old_size + 1) * sizeof(tcp_connection_info_t));
    }
    conn_list.array[conn_list.size++] = new_connection;

    // Release the mutex for the connection list
    pthread_mutex_unlock(&conn_list_mtx);

    // Signal any waiting threads that the connection list has changed
    pthread_cond_broadcast(&conn_list_cv);
}

// Define a function to remove a connection from the list and signal any waiting threads
void remove_connection(const char* client_ip, int port) {
    // Acquire the mutex for the connection list
    pthread_mutex_lock(&conn_list_mtx);

    // Find the element in the array of connections with the matching IP address and port number
    size_t index = 0;
    while (index < conn_list.size && strcmp(conn_list.array[index]->client_ip, client_ip) != 0 || conn_list.array[index]->port != port) {
        index++;
    }

    // If the element is found, remove it from the array and free its memory
    if (index < conn_list.size) {
        size_t old_size = conn_list.size;
        tcp_connection_info_t* removed_connection = conn_list.array[index];
        memmove(conn_list.array + index, conn_list.array + index + 1, (old_size - index - 1) * sizeof(tcp_connection_info_t));
        free(removed_connection);
        conn_list.size--;
    }

    // Release the mutex for the connection list
    pthread_mutex_unlock(&conn_list_mtx);

    // Signal any waiting threads that the connection list has changed
    pthread_cond_broadcast(&conn_list_cv);
}

// Define a function to modify the state of a connection in the list and signal any waiting threads
void update_connection(const char* client_ip, int port, int new_state) {
    // Acquire the mutex for the connection list
    pthread_mutex_lock(&conn_list_mtx);

    // Find the element in the array of connections with the matching IP address and port number
    size_t index = 0;
    while (index < conn_list.size && strcmp(conn_list.array[index]->client_ip, client_ip) != 0 || conn_list.array[index]->port != port) {
        index++;
    }

    // If the element is found, update its state and signal any waiting threads that the connection list has changed
    if (index < conn_list.size) {
        conn_list.array[index]->state = new_state;
        pthread_cond_broadcast(&conn_list_cv);
    }

    // Release the mutex for the connection list
    pthread_mutex_unlock(&conn_list_mtx);
}

// Define a function to query the state of a connection in the list and return its state
int get_connection_state(const char* client_ip, int port) {
    // Acquire the mutex for the connection list
    pthread_mutex_lock(&conn_list_mtx);

    // Find the element in the array of connections with the matching IP address and port number
    size_t index = 0;
    while (index < conn_list.size && strcmp(conn_list.array[index]->client_ip, client_ip) != 0 || conn_list.array[index]->port != port) {
        index++;
    }

    // If the element is found, return its state
    int state = -1;
    if (index < conn_list.size) {
        state = conn_list.array[index]->state;
    }

    // Release the mutex for the connection list
    pthread_mutex_unlock(&conn_list_mtx);

    return state;
}

// Define a function to check if a connection is in the list and return its index
int find_connection(const char* client_ip, int port) {
    // Acquire the mutex for the connection list
    pthread_mutex_lock(&conn_list_mtx);

    // Find the element in the array of connections with the matching IP address and port number
    size_t index = 0;
    while (index < conn_list.size && strcmp(conn_list.array[index]->client_ip, client_ip) != 0 || conn_list.array[index]->port != port) {
        index++;
    }

    // If the element is found, return its index
    int ret = -1;
    if (index < conn_list.size) {
        ret = index;
    }

    // Release the mutex for the connection list
    pthread_mutex_unlock(&conn_list_mtx);

    return ret;
}

// Define a function to add an element to the end of the queue
void enqueue(int value) {
    // Acquire the mutex for the queue
    pthread_mutex_lock(&queue_mutex);

    // Add the element to the end of the queue
    queue.array[queue.size++] = value;

    // Release the mutex for the queue
    pthread_mutex_unlock(&queue_mutex);
}

// Define a function to remove an element from the front of the queue
int dequeue() {
    // Acquire the mutex for the queue
    pthread_mutex_lock(&queue_mutex);

    // If the queue is empty, return -1
    if (queue.size == 0) {
        int ret = -1;
        pthread_mutex_unlock(&queue_mutex);
        return ret;
    }

    // Remove the element from the front of the queue
    int value = queue.array[0];
    memmove(queue.array, queue.array + 1, (queue.size - 1) * sizeof(int));
    queue.size--;

    // Release the mutex for the queue
    pthread_mutex_unlock(&queue_mutex);

    return value;
}
