            fclose(f);
            free(buffer);
            return -4;
        }
        config->PHY_LAYER_MODE = json_int_value(phyMode);

        json_object* rfChainSelection = json_lookup(root, "rf-chain-selection");
        if (rfChainSelection == NULL) {
