    FILE* csv_file = fopen(filename, "r");
    if (csv_file == NULL) {
        fprintf(stderr, "Error: Failed to open CSV file for reading\n");
        return -1;
    }

    // Read the header row of the CSV file
    char* line = NULL;
    size_t len = 0;
    ssize_t read = getline(&line, &len, csv_file);
    if (read < 0) {
        fprintf(stderr, "Error: Failed to read header row of CSV file\n");
        return -1;
    }

    // Skip the first row and read each subsequent row as a new connection statistic
    for (int i = 0; i < num_conns; i++) {
        char* token = strtok(line, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Failed to read token from CSV file\n");
            return -1;
        }
        conn_stats[i].conn_id = atoi(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Failed to read token from CSV file\n");
            return -1;
        }
        conn_stats[i].timestamp = atol(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Failed to read token from CSV file\n");
            return -1;
        }
        conn_stats[i].byte_count_in = atol(token);
        token = strtok(NULL, ",");
        if (token == NULL) {
            fprintf(stderr, "Error: Failed to read token from CSV file\n");
            return -1;
        }
        conn_stats[i].byte_count_out = atol(token);
    }

    // Close the CSV file
    fclose(csv_file);

    return 0;
}

// Function to calculate the cumulative byte count for each unique CONN_ID and store it in a hash map
void calculate_cumulative_byte_counts(tcp_connection_stats_t* conn_stats, int num_conns) {
    // Initialize a hash map to store the cumulative byte counts
    struct hmap* byte_counts = hmap_create();
    if (byte_counts == NULL) {
        fprintf(stderr, "Error: Failed to create hash map for storing cumulative byte counts\n");
        return;
    }

    // Loop through each connection statistic and calculate the cumulative byte count
    for (int i = 0; i < num_conns; i++) {
        long cumulative_byte_count = 0;
        if (hmap_get(byte_counts, conn_stats[i].conn_id) != NULL) {
            cumulative_byte_count = hmap_get(byte_counts, conn_stats[i].conn_id);
        }
        cumulative_byte_count += conn_stats[i].byte_count_in + conn_stats[i].byte_count_out;
        hmap_set(byte_counts, conn_stats[i].conn_id, cumulative_byte_count);
    }

    // Free the hash map and return
    hmap_free(byte_counts);
}
```
This implementation includes a `calculate_cumulative_byte_counts` function that calculates the cumulative byte count for each unique CONN_ID and stores it in a hash map. This function is called after the statistics are loaded from the CSV file using the `load_conn_stats` function.

The `allocate_conn_stats` function dynamically allocates memory for an array of TCP connection statistics structures based on the number of connections specified by the user. The function initializes each structure with default values and returns a pointer to the allocated memory.

The `load_conn_stats` function opens the CSV file for reading and reads each subsequent row as a new connection statistic. It uses the `strtok` function to tokenize each row into individual fields, such as CONN_ID, TIMESTAMP, and BYTE COUNT IN/OUT. The function then populates the array of TCP connection statistics structures with these values.

The implementation also includes a check for errors in reading the CSV file or parsing the data into the array of TCP connection statistics structures.']

