int nicb_set_buffer_size(nicb_t *nicb, size_t buffer_size) {
    if (buffer_size > nicb->buffer_size) {
        // If the new buffer size is larger than the current one, reallocate a new buffer with the new size
        void *new_buffer = realloc(nicb->buffer, buffer_size);
        if (new_buffer == NULL) {
            return -1; // Return error if memory reallocation fails
        }

        // Set the new buffer and update its size
        nicb->buffer = new_buffer;
        nicb->buffer_size = buffer_size;
    } else if (buffer_size < nicb->buffer_size) {
        // If the new buffer size is smaller than the current one, reallocate a new buffer with the new size
        void *new_buffer = realloc(nicb->buffer, buffer_size);
        if (new_buffer == NULL) {
            return -1; // Return error if memory reallocation fails
        }

        // Set the new buffer and update its size
        nicb->buffer = new_buffer;
        nicb->buffer_size = buffer_size;
    }

    return 0; // Return success
}

// Define a function to handle dynamic resizing of buffers based on network activity
int nicb_handle_resize(nicb_t *nicb, size_t new_buffer_size) {
    if (new_buffer_size > nicb->buffer_size) {
        // If the new buffer size is larger than the current one, reallocate a new buffer with the new size
        void *new_buffer = realloc(nicb->buffer, new_buffer_size);
