// Function definitions
void initialize_nicbs() {
    for (int i = 0; i < MAX_NICB_INSTANCES; i++) {
        nicb_count[i] = 0;
        protocol_count[i] = 0;
        nicb_instances[i] = NULL;
    }
}

void configure_nicbs() {
    for (int i = 0; i < MAX_NICB_INSTANCES; i++) {
        nicb_instances[i] = calloc(1, sizeof(struct nicb_instance));
        nicb_instances[i]->nicb_id = i;
    }
}

void start_nicb(int nicb_id) {
    if (nicb_count[nicb_id] == 0) {
        // Initialize NICB instance
        nicb_instances[nicb_id]->nicb_id = nicb_id;
        nicb_instances[nicb_id]->protocol_count = 0;
    }
}

void stop_nicb(int nicb_id) {
    if (nicb_count[nicb_id] > 0) {
        // Release NICB instance resources
        free(nicb_instances[nicb_id]);
        nicb_instances[nicb_id] = NULL;
    }
}

void handle_network_event(struct sockaddr *address, int protocol_index) {
    // Find NICB instance that matches the address and protocol index
    int nicb_id = -1;
    for (int i = 0; i < MAX_NICB_INSTANCES; i++) {
        if (nicb_instances[i] != NULL && nicb_instances[i]->protocol_count > protocol_index) {
            nicb_id = i;
            break;
        }
    }

    // Handle network event
    if (nicb_id >= 0) {
        // Update NICB instance statistics
        nicb_instances[nicb_id]->protocol_count++;

        // Adjust buffer size for protocol instance
        adjust_buffer_size(nicb_instances[nicb_id]);
    }
}

void handle_protocol_event(struct nicb_instance *nicb_instance, int protocol_index) {
    if (nicb_instance->protocol_count > protocol_index) {
        // Update protocol instance statistics
        protocol_instances[protocol_index]->protocol_index++;

        // Handle protocol event
        handle_protocol_event(nicb_instance, protocol_index);
    }
}

void adjust_buffer_size(struct nicb_instance *nicb_instance) {
    if (nicb_instance->protocol_count > 0) {
        // Calculate required buffer size
        int required_buffer_size = 0;
        for (int i = 0; i < nicb_instance->protocol_count; i++) {
            required_buffer_size += protocol_instances[i]->required_buffer_size;
        }

        // Adjust buffer size if necessary
        if (nicb_instance->buffer_size < required_buffer_size) {
            nicb_instance->buffer_size = required_buffer_size;
        }
    }
}

