#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>
#include <pthread.h>

struct TrafficFlow {
    unsigned int FlowID;
    char SourceIP[16];
    char DestinationIP[16];
    long PacketCount;
    struct timeval Timestamp;
};

void initialize_traffic_flows(struct TrafficFlow *flows, size_t num_flows) {
    // Initialize the flows array with unique FlowIDs, SourceIPs, DestinationIPs, and PacketCounts
    for (size_t i = 0; i < num_flows; i++) {
        flows[i].FlowID = i + 1;
        sprintf(flows[i].SourceIP, "192.168.1.%d", (int)(i % 254) + 1);
        sprintf(flows[i].DestinationIP, "192.168.1.%d", (int)(i % 254) + 10);
        flows[i].PacketCount = 0;
    }

    // Initialize the Timestamp for each flow to the current time
    struct timeval now;
    gettimeofday(&now, NULL);
    for (size_t i = 0; i < num_flows; i++) {
        flows[i].Timestamp = now;
    }
}

void populate_traffic_flows(struct TrafficFlow *flows, size_t num_flows) {
    // Populate the flows array with random packet counts and timestamps
    for (size_t i = 0; i < num_flows; i++) {
        flows[i].PacketCount = rand() % 1000;
        struct timeval now;
        gettimeofday(&now, NULL);
        flows[i].Timestamp = now;
    }
}

void validate_traffic_flows(struct TrafficFlow *flows, size_t num_flows) {
    // Validate each flow's IP addresses and packet count
    for (size_t i = 0; i < num_flows; i++) {
        if (!validate_ipv4_address(flows[i].SourceIP)) {
            log_error("Invalid source IP address: %s", flows[i].SourceIP);
            return;
        }
        if (!validate_ipv4_address(flows[i].DestinationIP)) {
            log_error("Invalid destination IP address: %s", flows[i].DestinationIP);
            return;
        }
        if (flows[i].PacketCount < 0) {
            log_error("Negative packet count: %ld", flows[i].PacketCount);
            return;
        }
    }
}

int validate_ipv4_address(const char *ip_addr) {
    // Check if the given IP address is a valid IPv4 address
    int octets[4];
    int i = 0;
    while (*ip_addr != '\0') {
        if (i >= 4) {
            return 0;
        }
        char *endptr;
        long val = strtol(ip_addr, &endptr, 10);
        if (val < 0 || val > 255) {
            return 0;
        }
        ip_addr = endptr;
        octets[i++] = val;
    }
    if (i != 4) {
        return 0;
    }
    for (int i = 0; i < 3; i++) {
        if (octets[i] == 0) {
            return 0;
        }
    }
    return 1;
}

void log_error(const char *format, ...) {
    // Log an error message to the console
    va_list args;
    va_start(args, format);
    vprintf(format, args);
    va_end(args);
}
```
